SCHEMA = "bayes_basket_target_production_worker_v2"
# Live as of the 2026-08-30 go-live migration: the operator armed
# live_intent_v1, the migration widened the intents CHECK, minted the live
# activation and runtime, and raised the capital policy's three boundaries.
# What still stops an order from reaching the exchange is data/live_paused.flag,
# which is the operator's and no code's -- but it is no longer a second thing
# the operator has to remember.  Since 2026-09-02 the dashboard LIVE switch
# owns it in both directions (scripts/live_control_server.set_live): arming
# lifts the flag after writing the intent, disarming places it before, so
# every intermediate state is a stopped one and the switch means what it
# says.  A hand `touch` is still an immediate e-stop for every lane.
PRODUCTION_EXECUTION_MODE = "production_live"
NO_LIVE_EXECUTION_MODE = "production_no_live"
MAX_PREPARED_CYCLES_PER_SCOPE = 1
# What the ledger accepting a scope looks like.  Four of these write no
# rows at all -- the decision they would write is already on file -- and
# they are accepted for the same reason the committing one is: the cycle
# asked the ledger and the ledger answered with a standing decision.
# ``retained_existing_prepared_candidate`` was missing, so a cycle whose
# every scope was that legitimate zero-write retain reported itself as a
# total outage.
COMMITTED_SCOPE_STATES = frozenset({
    "committed",
    "already_committed",
    "already_committed_decision",
    "already_committed_decision_scope",
    "retained_existing_authority_decision",
    "retained_existing_prepared_candidate",
})


#: Refusals that mean the system did not manage, not that it declined.
#:
#: A scope refused because its book expired, because a replay had not been
#: compiled, or because the database was locked, is a scope the objective
#: never got to judge -- rerun it with nothing about the market changed and
#: it should go through.  A scope refused on ``delta_v2_support_empty`` or
#: ``p1_entry_window_not_open`` is the objective answering; rerunning it
#: changes nothing.
#:
#: They shared one counter, and that is how 2026-09-07 read as "90
#: candidates, 88 blocked" -- a sentence that sounds like a fleet with
#: nothing to trade, when in fact 83 of the 88 were books that went stale
#: while the cycle was busy.  One of those numbers belongs in an SLO and
#: the other belongs in a business report, so they are counted apart.
#:
#: Matched as substrings, because reason codes carry scope suffixes.
INCAPACITY_REASON_MARKERS: tuple[str, ...] = (
    "quote_expired",
    "replay_required",
    "database is locked",
    "_locked",
    "stale_fail_closed",
    "manifest_stale",
    "timeout",
    "not_materialized",
    "envelope_missing",
    "scope_missing",
    "unavailable",
    "budget_spent",
)


def classify_scope_refusal(reason_code: str) -> str:
    """``incapacity`` when the system did not manage, else ``verdict``."""

    text = str(reason_code or "").strip().lower()
    if not text:
        return "verdict"
    return (
        "incapacity"
        if any(marker in text for marker in INCAPACITY_REASON_MARKERS)
        else "verdict"
    )


def split_refusals_by_capability(
    reasons: Mapping[str, int],
) -> dict[str, Any]:
    """Split a refusal tally into what was declined and what was missed."""

    incapacity: dict[str, int] = {}
    verdict: dict[str, int] = {}
    for code, count in (reasons or {}).items():
        bucket = (
            incapacity if classify_scope_refusal(code) == "incapacity"
            else verdict
        )
        bucket[str(code)] = int(count)
    incapacity_total = sum(incapacity.values())
    verdict_total = sum(verdict.values())
    total = incapacity_total + verdict_total
    return {
        "schema": "bayes_basket_target_refusal_split_v1",
        "incapacity_count": incapacity_total,
        "incapacity_reasons": dict(sorted(incapacity.items())),
        "verdict_count": verdict_total,
        "verdict_reasons": dict(sorted(verdict.items())),
        # The SLO number.  "Of the scopes we refused, how many did we
        # never actually judge?"
        "incapacity_share": (
            round(incapacity_total / total, 4) if total else 0.0
        ),
    }


#: Exception classes that mean a RULE refused this scope.  A contract, a
#: ledger invariant, a designed resource guard: the system working.
SCOPE_RULE_REFUSAL_CLASSES = frozenset({
    "ContractError",
    "AtomicLedgerError",
    "ResourceBoundError",
    "ExecutionVersionVectorError",
})
#: Classes that mean the machine underneath was busy or full, which is
#: neither a rule nor a defect and wants its own line.
SCOPE_INFRASTRUCTURE_REFUSAL_CLASSES = frozenset({
    "OperationalError",
    "DatabaseError",
    "InterfaceError",
    "TimeoutError",
    "OSError",
})


def _scope_defect_tally(
    results: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Separate the scopes a rule refused from the ones a bug refused.

    ``_scope_verdict_tally`` below deliberately drops the exception class
    from its key -- reasons are colon chains and tallying on the tail split
    one family into eight keys of one -- so a Python-level failure and a
    charter refusal reach the board looking alike, and the fleet-wide ones
    look like a busy afternoon.

    They are not alike.  Measured 2026-09-09 over every blocked-scope row
    since 09-01: 1,529 ContractError, 45 ResourceBoundError and 13
    AtomicLedgerError -- rules and guards speaking -- against 161
    OperationalError (all "database is locked") and 73 TypeError.  Every
    one of the 73 was the same shape, a caller passing a keyword the callee
    did not yet accept, and it happened twice in one week: 28 scopes on
    2026-09-03 (``last_acted_probability_identity``) and 45 on 2026-09-09
    09:03-10:40Z (``off_centre_claim_bands``).  The second took every one
    of the 45 stations on the live event day for an hour and thirty-eight
    minutes -- 65 decision rows in that window, every one blocked, not one
    prepared -- and nothing anywhere said so.

    An unknown class counts as a defect on purpose.  A class nobody has
    classified is far likelier to be a new bug than a new rule, and the
    cost of being wrong is one loud line against another silent outage.
    """

    defect: dict[str, int] = {}
    infrastructure: dict[str, int] = {}
    blocked = 0
    for item in results:
        commit = item.get("atomic_commit")
        commit_map = commit if isinstance(commit, Mapping) else {}
        state_word = str(commit_map.get("state") or "").upper()
        commit_failed = (
            "BLOCK" in state_word
            or "FAIL" in state_word
            or commit_map.get("ok") is False
        )
        if item.get("ok") is not False and not commit_failed:
            continue
        blocked += 1
        reason = str(
            item.get("reason") or commit_map.get("reason") or ""
        ).strip()
        # The decision loop writes ``f"{type(exc).__name__}:{exc}"``, so the
        # class is the leading segment when there is one at all.
        head, _, tail = reason.partition(":")
        if not tail or not head.endswith("Error"):
            # No class in front: these are the worker's own named refusals
            # (a blocker string chosen by this file), which are rules.
            continue
        if head in SCOPE_RULE_REFUSAL_CLASSES:
            continue
        bucket = (
            infrastructure
            if head in SCOPE_INFRASTRUCTURE_REFUSAL_CLASSES
            else defect
        )
        key = f"{head}:{tail.strip()[:70]}"
        bucket[key] = bucket.get(key, 0) + 1
    defect_count = sum(defect.values())
    return {
        "defect_scope_count": defect_count,
        "defect_reasons": defect,
        "infrastructure_scope_count": sum(infrastructure.values()),
        "infrastructure_reasons": infrastructure,
        # One shape took most of the scopes that refused.  Not *every*
        # one: replaying both real episodes through this function showed
        # ordinary rules still refusing beside the defect -- 45 of 65
        # blocked on 2026-09-09, 28 of 29 on 09-03 -- so a rule that
        # demanded unanimity would have called neither of them, which is
        # the whole failure it exists to catch.  Three of one shape is the
        # floor, because one or two is a station's own data.
        "fleet_wide_defect": bool(
            defect
            and max(defect.values()) >= 3
            and max(defect.values()) * 2 >= blocked
        ),
    }


def _scope_verdict_tally(
    results: Sequence[Mapping[str, Any]],
) -> tuple[int, dict[str, int]]:
    """How many scopes the ledger accepted, and what refused the others.

    A refusal is named whether it was raised by the compile (the scope's own
    ``ok`` is False) or by the commit (its ``atomic_commit`` fail-closed).
    Only the first was tallied, and the guard's refusals arrive in the
    second shape -- so fifteen station-days refused on
    ``target_prepared_cycle_retention_violation`` counted as neither
    committed nor blocked, and the board could say the cycle had failed
    without being able to say what failed.
    """

    committed = 0
    reasons: dict[str, int] = {}
    for item in results:
        commit = item.get("atomic_commit")
        commit_map = commit if isinstance(commit, Mapping) else {}
        state = str(commit_map.get("state") or "")
        if state in COMMITTED_SCOPE_STATES:
            committed += 1
        state_word = state.upper()
        commit_failed = (
            "BLOCK" in state_word
            or "FAIL" in state_word
            or commit_map.get("ok") is False
        )
        if item.get("ok") is not False and not commit_failed:
            continue
        raw_reason = str(item.get("reason") or "")
        if not raw_reason:
            raw_reason = str(commit_map.get("reason") or "")
        raw_reason = raw_reason or "unnamed"
        # The family name, not the tail: reasons are colon chains whose
        # first segments are exception classes and whose later segments may
        # carry per-station detail (the named market mismatch puts
        # station@date there), and tallying on the tail split one family
        # into eight keys of one.
        segments = [
            seg for seg in raw_reason.split(":")
            if seg and not seg.endswith("Error")
        ]
        key = (segments[0] if segments else raw_reason)[:60]
        reasons[key] = reasons.get(key, 0) + 1
    return committed, reasons
# Measured on 1022 observed station-days: the daily high landed inside these
# local hours 80% of the time.  It peaks at 15:00 but only 17.6% there, so
# the useful signal is the window rather than a distance from any one hour.
# The measured distribution of when the daily high is actually set, as the
# share of 1022 observed station-days whose high landed in each local hour.
# It is not flat and it is not symmetric: 15:00 carries seven times 10:00's
# share, and the afternoon tail is fatter than the morning approach.  Using
# it directly is what keeps stations inside the window ordered against each
# other, instead of tying at a plateau and falling through to the alphabet.
_WARM_HOUR_SHARE: tuple[tuple[float, float], ...] = (
    (0.0, 0.034), (1.0, 0.006), (7.0, 0.004), (8.0, 0.008),
    (9.0, 0.023), (10.0, 0.026), (11.0, 0.043), (12.0, 0.093),
    (13.0, 0.127), (14.0, 0.158), (15.0, 0.176), (16.0, 0.106),
    (17.0, 0.118), (18.0, 0.044), (19.0, 0.017), (20.0, 0.004),
    (21.0, 0.001), (22.0, 0.003), (23.0, 0.010),
)
_WARM_HOUR_PEAK_SHARE = max(share for _hour, share in _WARM_HOUR_SHARE)


def _warm_hour_share(hour: float) -> float:
    """Interpolate the measured share of daily highs at a local hour."""

    clamped = min(max(float(hour), 0.0), 24.0)
    previous_hour, previous_share = _WARM_HOUR_SHARE[0]
    for current_hour, current_share in _WARM_HOUR_SHARE:
        if clamped <= current_hour:
            if current_hour == previous_hour:
                return current_share
            span = current_hour - previous_hour
            weight = (clamped - previous_hour) / span
            return previous_share + weight * (current_share - previous_share)
        previous_hour, previous_share = current_hour, current_share
    return previous_share
# How far a scope's score may be lifted by waiting.  Twelve hours is enough
# for the quietest station to outrank a busy one, and bounded so that a scope
# left behind by an outage cannot accumulate unbounded priority and then
# monopolise the rotation when service resumes.
ROTATION_AGEING_CAP_HOURS = 12.0
# No open event day may go longer than this without a capture.  The paper
# ledger refuses a book more than thirty minutes older than the decision it
# prices, so a day starved past that window produces decisions nothing can
# be filled against; half of it leaves room for the cycle to land.
EVENT_DAY_CAPTURE_BOUND_SEC = 900.0

# The fleet, derived.  It was the literal 45 and survived the 2026-10-04
# move to 48: the forward P0 compile takes the stations with a live cross
# activation ``ORDER BY station_id LIMIT`` this, so once the three new
# stations held activations the last three alphabetically (ZSQD, ZUCK, ZUUU)
# fell off the end and their D+1/D+2 P0 stopped at the 12Z run.
MAX_FORWARD_P0_STATIONS = expected_station_count()
# Packets kept in the republisher forward inbox.  This has to stay under what
# ``MAX_JSON_OUTPUT_BYTES`` permits, not merely be "a large number": each
# packet carries every registered ensemble system, ~65KiB of JSON and up to
# 95KiB, so the previous cap of 256 allowed roughly 16.6MiB against a 16MiB
# write limit.  The two bounds disagreed and the byte bound won by throwing --
# the inbox filled to 99.7% of the limit and then every capture failed with
# ``target_json_output_bytes_exceeded``.
#
# 45 stations x three open event days is what the horizon prune below leaves
# behind, and at the observed packet size that is ~13MiB with headroom.
MAX_REPUBLISHER_INBOX_PACKETS = expected_station_count() * 3
# Capture states that mean an official packet is on its way for this scope.
#
# The republisher is a fallback for scopes the official archives cannot serve,
# not a hedge against one being slow.  Official capture is asynchronous: the
# cycle that starts it returns SUBMITTED and the packet lands minutes later, at
# which point it takes precedence and the republisher packet it raced is
# discarded.  Paying for that packet anyway is what exhausted the aggregator's
# daily quota -- the ensemble endpoint bills per member, so one republisher
# capture costs ~409 units against a 10,000/day allowance, and the catalogue is
# 270 scopes.
#
# THROTTLED counts as pending: that state exists because an attempt was made
# within the retry window, so the answer for this scope is already being
# decided.  The cost is that a scope whose official capture keeps failing gets
# no aggregator fallback until its throttle expires, which is the intended
# trade -- official first, and the fallback reserved for scopes officially
# unavailable rather than officially late.
OFFICIAL_NATIVE_CAPTURE_PENDING_STATES = frozenset({
    "SUBMITTED",
    "IN_FLIGHT",
    "DEFERRED_CAPTURE_SLOTS_BUSY",
    "THROTTLED",
})
# Open scopes are station-*days*, not stations.  Several event days are open at
# once -- discovery admits a day from 72h before its local start until it
# closes -- so a station appears once per open day.  Bounding them at the
# station count made "more than one day is open" an error, which is how the
# lane came to depend on something upstream pinning it to a single date.
MAX_FORWARD_P0_STATION_DAYS = MAX_FORWARD_P0_STATIONS * 4
# How many station-days may rebuild their TAF confirmation in one cycle.
#
# A bound on the pathological case, not a rate: every open station-day whose
# root moved rebuilds in the cycle it moved.  It was four, set on 2026-08-31
# when the rebuild cost a full-lineage read per scope and a first live cycle
# with 383 eligible scopes ran 1,523 seconds.  The read has since moved in
# front of this decision (the scope is loaded whether or not it rebuilds), so
# the cap stopped saving the expensive part and kept only the delay: measured
# 2026-09-13 04:02Z, four rebuilt and 56 waited, and 74 of 651 sampled
# higher-stage heads on 2026-09-11..12 served a P0-M on a root whose
# probabilities the newest P0 had already replaced.  The whole scope loop was
# 4.5 of that cycle's 244 seconds.  One per open station-day is the most a
# single root generation can ask for.
MAX_P0M_REPLAYS_PER_CYCLE = MAX_FORWARD_P0_STATION_DAYS
# How little lease may remain on a day's books before its next scope is
# compiled against a re-read instead.
#
# Not a cadence.  A cadence measured from when the evidence was written was
# never due, because the books arrive already old: measured 2026-08-31, the
# publisher's own book age is a median 34 seconds across both days, so a
# 60-second lease has about 26 seconds left the moment it is stored.  What
# matters is what is left, not how long ago we wrote it.
#
# Twelve seconds is under that remaining headroom and above the cost of the
# read that answers it, so a day about to run out refreshes once, and a day
# with room does not pay for a read it does not need.
QUOTE_EVIDENCE_REFRESH_SECONDS = 12.0
# How many times one event day may restate its books inside one cycle.
#
# The bound exists because a day with nothing to restate used to ask on every
# scope: 44 refreshes in one cycle, none renewing anything, and the cycle went
# from eight to fourteen minutes.  The answer to that was "ask once, believe
# the answer", which overcorrected -- one ineffective pass disabled the day's
# refresh for the whole cycle, and the compile loop then ran for another four
# minutes against a sixty-second lease.  Measured 2026-09-01: one attempt,
# judged ineffective, and twenty-one scopes died on production_quote_expired
# behind it.
#
# A count is the right shape for that bound.  Six passes covers a six-minute
# loop at roughly one renewal per lease, and a day whose publisher has gone
# silent still stops after six rather than after forty-four.
MAX_QUOTE_EVIDENCE_REFRESHES_PER_DAY = 6


def quote_refresh_admitted_v1(
    *,
    lease_left_seconds: float,
    refresh_interval_seconds: float = QUOTE_EVIDENCE_REFRESH_SECONDS,
    day_is_ineffective: bool,
    unproductive_attempts: int,
    max_unproductive: int = MAX_QUOTE_EVIDENCE_REFRESHES_PER_DAY,
) -> bool:
    """Whether this scope may renew its day's quote lease.

    Three guards, and each answers a different failure (2026-09-08 ruling
    that they must not be conflated):

    * the lease has to be nearly spent, or there is nothing to renew;
    * ``day_is_ineffective`` -- one pass that wrote nothing disables the
      day.  This is the guard the 44-refreshes-in-one-cycle incident needed,
      and it fires after a single attempt;
    * ``unproductive_attempts`` -- attempts that renewed NOTHING, which is
      what a bounded number of tries is still for: an erroring refresh
      leaves the previous books in place and the latch above never sees it,
      because the latch asks whether a pass wrote and an exception did not.

    What it deliberately does NOT bound is a refresh that renews.  That
    attempt is doing exactly its job, and the day it is done for is healthy.
    The cap used to count every attempt, so a long decision loop on a live
    publisher exhausted it: measured 2026-09-08, six attempts, all
    committed, zero failures, zero ineffective days -- then 43 of the 44
    remaining scopes died on ``production_quote_expired``, on the day that
    settled that afternoon.
    """

    if float(lease_left_seconds) > float(refresh_interval_seconds):
        return False
    if day_is_ineffective:
        return False
    return int(unproductive_attempts) < int(max_unproductive)


# How long a renewed lease is expected to keep a scope compilable after the
# refresh that renewed it: the ~26 s a book has left when the publisher hands
# it over (``QUOTE_EVIDENCE_REFRESH_SECONDS``' own note: a median 34 s old
# against a 60 s lease) less the 12 s threshold at which the next scope asks
# again.
QUOTE_REFRESH_REACH_SECONDS = 14.0
# Seconds a decision-loop position costs before any loop has been measured.
QUOTE_REFRESH_DEFAULT_POSITION_SECONDS = 0.45
# "0": every refresh restates the whole day again, as before 2026-10-03.
QUOTE_REFRESH_WITHIN_REACH = (
    os.environ.get("PM_QUOTE_REFRESH_WITHIN_REACH", "1").strip().lower()
    not in {"0", "off", "false", "no"}
)


def quote_refresh_reach_v1(
    *,
    seconds_per_position: float | None,
    reach_seconds: float = QUOTE_REFRESH_REACH_SECONDS,
) -> int:
    """How many decision-loop positions one renewed lease will cover.

    A mid-loop refresh used to restate every station of the day.  The books
    it writes all come off one catalog read, so each has the same ~26 s left
    whenever it is written, and the loop reaches them one compile at a time:
    at 0.45 s a position a refresh covers ~31 scopes, and the rest of the
    day -- plus every scope already compiled -- was written for nothing.
    Under load that turned into a spiral (2026-10-03 13:22Z): four seconds a
    compile, so three scopes per renewal, while restating all 44 took 17-57 s
    -- longer than the lease it was renewing.  25 refreshes, 1,100 station
    writes, 437 s, for 119 compiles.  Restating only the positions inside the
    reach costs one station write per scope that needs one and never writes
    a book that will lapse before it is read.
    """

    per = (
        float(seconds_per_position)
        if seconds_per_position is not None and float(seconds_per_position) > 0
        else QUOTE_REFRESH_DEFAULT_POSITION_SECONDS
    )
    return max(1, int(float(reach_seconds) // per))


def quote_refresh_stations_v1(
    rows: Sequence[tuple[Any, Any]],
    *,
    position: int,
    reach: int,
    skip: Collection[tuple[str, str]] = (),
) -> list[str]:
    """The stations one mid-loop refresh restates: the scope at ``position``
    and every scope of its day in the ``reach`` positions from there that the
    loop will still compile (not in ``skip``), in loop order, each once."""

    station, day = str(rows[position][0]), str(rows[position][1])
    skipped = {(str(item[0]), str(item[1])) for item in skip}
    stations: list[str] = []
    for ahead_station, ahead_day in rows[position:position + max(1, int(reach))]:
        key = (str(ahead_station), str(ahead_day))
        if key[1] != day or key[0] in stations:
            continue
        if key[0] == station or key not in skipped:
            stations.append(key[0])
    return stations


# How long one cycle's decision loop may wait for the publisher's next book
# generation, once a refresh of a day renewed nothing.
#
# A refresh can only renew a lease with books newer than the ones it holds,
# and those come from the publisher's full resubscription every ~30 s.  When
# that stalls the loop used to keep asking: 2026-10-04 15:51:41-45Z, four
# refreshes in four seconds against one unchanged manifest, the per-day cap
# of six spent, and the 19 scopes behind them died together on
# production_quote_expired (23 that cycle, 15 more at 15:43:47Z the same way;
# 41 of 70 on the board's cycle).  Waiting for the generation instead turns a
# publisher gap into seconds of loop time rather than a cycle of dead
# scopes.  Sixty is one whole lease: a publisher silent longer than that is
# not a hiccup, and the loop then fails the remaining scopes as before.
QUOTE_PUBLISHER_WAIT_BUDGET_SECONDS = 60.0
QUOTE_PUBLISHER_POLL_SECONDS = 1.0
# "0": a refresh that renewed nothing is retried at once, as before
# 2026-10-04.
QUOTE_REFRESH_AWAIT_PUBLISHER = (
    os.environ.get("PM_QUOTE_REFRESH_AWAIT_PUBLISHER", "1").strip().lower()
    not in {"0", "off", "false", "no"}
)


def publisher_book_floor_v1(manifest: Mapping[str, Any]) -> datetime | None:
    """The oldest book in one resident scope manifest, or None.

    A snapshot is stamped with its scope's oldest book, so this is the
    stamp a refresh would write now.  None when the scope carries no
    quotes or any quote carries no clock: nothing to wait for.
    """

    quotes = manifest.get("quotes_by_token")
    if not isinstance(quotes, Mapping) or not quotes:
        return None
    floor: datetime | None = None
    for quote in quotes.values():
        if not isinstance(quote, Mapping):
            return None
        text = str(quote.get("book_observed_at") or quote.get("created_at") or "")
        try:
            stamp = datetime.fromisoformat(text.replace("Z", "+00:00"))
        except ValueError:
            return None
        if stamp.tzinfo is None:
            return None
        floor = stamp if floor is None or stamp < floor else floor
    return floor
# Charter 48: a listed day not served for this long takes the next cycle
# regardless of the alternation -- the guard against a restart storm.
LISTING_SCOPE_TURN_STARVATION_SEC = 900.0
# The stages that are not inputs to the current action.
#
# Each already says so at its own call site -- closed-day truth, an OOS
# evaluation that is "isolated_from_probability_and_execution", settlement
# labels the code calls "maintenance work, not inputs to the current
# action" -- and the answer so far has been to move them later in the
# cycle.  That fixes the order and not the arithmetic: the decision path
# compiles against a book with ``max_quote_age_seconds`` of life, so what
# it is racing is the length of the whole cycle, not its own position in
# it.  Measured 2026-09-07: 1436.6s of stages ran before the books were
# even read, and 86 of 90 scopes then died on ``production_quote_expired``.
#
# So they keep their writer, their heartbeat and their watchdog -- the
# reasons they were brought inside the cycle in the first place -- and give
# up only the right to take unbounded time from a decision.  Naming them
# here rather than judging each call site separately is the point: what a
# cycle pays for maintenance is one number.
MAINTENANCE_STAGES: tuple[str, ...] = (
    "truth_increment",
    "native_ensemble_oos",
    "delta_v2_settlement",
)
# Every stage's deadline tier, declared rather than implied.
#
# The rule the whole cycle turns on is one sentence -- **a tier may never
# make a tighter tier late** -- and until now it was expressed nowhere.  It
# was approximated instead, over and over, by reordering stages inside one
# serial body and by tuning constants: settlement was moved after the
# decision loop, the quote-refresh cap went 44 -> 1 -> 6, the dashboard
# render was moved to its own process.  Each of those fixed the case in
# front of it and left the rule unstated, so the next stage added inherited
# nothing.
#
# The tiers are deadlines, not module boundaries:
#
#   R0  the quote lease.  Books have ``max_quote_age_seconds`` of life and
#       a decision compiled against an expired one is thrown away, so
#       everything between reading the book and committing is R0 -- plus
#       the stages a commit is not allowed to happen without.
#   R1  an arrival.  Model runs, TAF issuances and observations land on
#       someone else's clock and some of their windows are not refetchable;
#       late by a cycle is a cost, late by an hour is a loss.
#   R2  a period.  Closed-day truth, OOS evaluation, settlement labels:
#       nothing downstream of the current action reads them, so they may be
#       deferred, and MAINTENANCE_STAGES is exactly this tier's gated set.
#   R3  a day.  Retraining, retention, rendering -- these already live
#       outside the cycle entirely and are named here so the table is the
#       whole picture rather than the part that happens to be in one file.
#
# A stage absent from this table is treated as R0, which is the safe
# default: it means a new stage delays a decision until someone classifies
# it, rather than being silently deferrable.
STAGE_TIER_R0_DECISION = 0
STAGE_TIER_R1_ARRIVAL = 1
STAGE_TIER_R2_PERIODIC = 2
STAGE_TIER_R3_DAILY = 3
STAGE_TIER: dict[str, int] = {
    # R0 -- between reading the book and committing against it.
    "activation": STAGE_TIER_R0_DECISION,
    # Four lanes under one mark, and one of them -- settling live cycles --
    # is a precondition for committing anything at all.
    "intent_reconcile": STAGE_TIER_R0_DECISION,
    "cash_phase_flush": STAGE_TIER_R0_DECISION,
    "registry_ingress": STAGE_TIER_R0_DECISION,
    # P1 resolves each observation's truth-revision hash at compile time,
    # and the envelope table is append-only: a report identified after that
    # compile is one this cycle can never carry.
    "live_observation_identity": STAGE_TIER_R0_DECISION,
    # Charter 148: reports that landed during the previous cycle are turned
    # into P1 at the head of this one, ahead of the NWP arrival stages.
    "early_p1": STAGE_TIER_R0_DECISION,
    # The fast lane: a new TAF becomes P0-M before anything else in the cycle.
    "early_p0m": STAGE_TIER_R0_DECISION,
    # ... and again right before the decision loop, when something new landed.
    "fast_lane_before_decisions": STAGE_TIER_R0_DECISION,
    # Charter 165: the same checkpoint re-armed at the heavy stage
    # boundaries (and, as a span, inside the decision loop).
    "fast_lane_after_native_p0_replay_compile": STAGE_TIER_R0_DECISION,
    "fast_lane_after_native_ensemble_oos": STAGE_TIER_R0_DECISION,
    "fast_lane_after_regime": STAGE_TIER_R0_DECISION,
    "fast_lane_after_forward_p0_loop": STAGE_TIER_R0_DECISION,
    "fast_lane_after_market_ingress": STAGE_TIER_R0_DECISION,
    # Charter 165's in-loop checkpoint is RETIRED (2026-09-21).  Measured on
    # the 14:43:01Z cycle: five in-loop passes cost 560s of a 1767s cycle,
    # one of them 264s on its own, and the decision loop's own quote
    # refreshes went from 12 (86s) to 31 (573s) in the same step -- a pass
    # that takes minutes INSIDE the loop expires the quote lease the loop is
    # holding, so the next scope re-reads the book, which lengthens the loop,
    # which expires more leases.  The five checkpoints at the stage
    # BOUNDARIES have no such coupling and stay.  The label is kept so an
    # older cycle's receipt still reads.
    "fast_lane_in_decision_loop": STAGE_TIER_R0_DECISION,
    "probability_p0": STAGE_TIER_R0_DECISION,
    "probability_p0m": STAGE_TIER_R0_DECISION,
    "probability_p1": STAGE_TIER_R0_DECISION,
    "regime": STAGE_TIER_R0_DECISION,
    "ws_scope_catalog": STAGE_TIER_R0_DECISION,
    # Bookkeeping, but on the decision path by necessity: it records the
    # verdict that decides whether this cycle serves a scope at all, and a
    # verdict recorded a tier later is a verdict recorded after the cycle
    # that acted on it.
    "ws_scope_serving_state": STAGE_TIER_R0_DECISION,
    "market_ingress": STAGE_TIER_R0_DECISION,
    "post_fill_recompute": STAGE_TIER_R0_DECISION,
    "committed_scope_sweep": STAGE_TIER_R0_DECISION,
    "decision_loop": STAGE_TIER_R0_DECISION,
    # R1 -- arrivals.  The forward loop is here because a forward book
    # missed is not refetchable, and the replay compile because it writes
    # the inbox P0 reads on the same pass.
    "native_inbox_ingest": STAGE_TIER_R1_ARRIVAL,
    "native_p0_replay_compile": STAGE_TIER_R1_ARRIVAL,
    "forward_p0_loop": STAGE_TIER_R1_ARRIVAL,
    # R2 -- periodic, and the only tier the cycle currently defers.
    "oos_candidate_scan": STAGE_TIER_R2_PERIODIC,
    "native_ensemble_oos": STAGE_TIER_R2_PERIODIC,
    "truth_increment": STAGE_TIER_R2_PERIODIC,
    "delta_v2_settlement": STAGE_TIER_R2_PERIODIC,
    "settlement_lane": STAGE_TIER_R2_PERIODIC,
}
# What one cycle may spend on all of them together, when the activation
# cannot be read for the real figure.
#
# The live budget is the R0 deadline itself -- ``max_quote_age_seconds``
# off the activation's quote freshness policy -- because that is the whole
# statement of the rule: a tier may spend, at most, the life of the thing
# the tighter tier is racing.  Writing 60.0 here and 60.0 in the policy
# would be two copies of one number that must agree, and the copy in the
# policy is the one production enforces.  This is only the fallback for a
# cycle whose activation did not parse, where deferring more rather than
# less is the safe direction.
MAINTENANCE_BUDGET_SEC = 60.0
# ...and how long one stage may go unserved before it takes a cycle
# regardless of the budget.  Without this the fixed order starves the tail,
# which is the failure LISTING_SCOPE_TURN_STARVATION_SEC exists for and the
# one the rotation cursor alone does not close.
MAINTENANCE_STARVATION_SEC = 1800.0
MAX_RESIDENT_NWP_SCOPES_PER_CYCLE = 4
MAX_NATIVE_ENSEMBLE_TRUTH_CASES_PER_STATION = 64
MAX_RESIDENT_CANDIDATE_PREFETCH_SCOPES_PER_CYCLE = 1
MAX_POST_FILL_RECOMPUTES_PER_PASS = 128
# A single resident pass can legitimately expose multiple committed envelope
# generations for a station/day (P0/P1 corrections and replay-safe lineage).
# The 45-station scope currently expands to 265 envelopes; keep a bounded
# ceiling above that real shape while retaining a hard upper bound for the
# resource guard.
MAX_REGIME_ARTIFACTS_PER_PASS = 512
MAX_FORWARD_DECISIONS_PER_PASS = MAX_FORWARD_STORE_BATCH_ROWS
MAX_FORWARD_DECISION_JSON_BYTES = 262_144
MAX_FORWARD_SCAN_BYTES = 16 * 1024 * 1024
DELTA_V2_LABEL_SCAN_INTERVAL_SECONDS = 900.0
MAX_DELTA_V2_LABEL_PAGES_PER_PASS = 8
TARGET_SCOPE_KEYS = ("season_bin", "maturity_bin", "liquidity_bin", "strategy_version")
MULTI_SCOPE_WS_MANIFEST_SCHEMA = (
    "bayes_basket_target_resident_multi_scope_ws_manifest_v1"
)
# Three concurrent event days per station is the steady state now that the
# catalog subscribes at listing: the listing day, today and tomorrow all
# carry scopes at once.  The publisher's own cap (MAX_TARGET_SCOPES) moved to
# 45x3 for the same reason; a reader stricter than the writer turns a bigger
# catalog into a global WS-path outage.
MAX_RESIDENT_WS_SCOPES = expected_station_count() * 3


def _blocked_plan_error(
    reason: str, *, candidate: Mapping[str, Any] | None
) -> ContractError:
    """The blocked plan's reason, carrying the funnel the plan already holds.

    ``_support_window_error`` puts the window funnel on the solver's own
    exception; the runtime absorbs that exception into a blocked plan and
    moves the funnel to ``delta_v2_audit``.  Anything that re-raises from
    the plan has to move it back, or the recorder downstream -- which reads
    it off the exception -- records a refusal that cannot say what refused
    it.
    """

    error = ContractError(reason)
    audit = (
        candidate.get("delta_v2_audit")
        if isinstance(candidate, Mapping) else None
    )
    if isinstance(audit, Mapping):
        counts = audit.get("window_gate_counts")
        if isinstance(counts, Mapping):
            error.window_gate_counts = dict(counts)
        failures = audit.get("window_failures")
        if isinstance(failures, Sequence) and not isinstance(
            failures, (str, bytes, bytearray)
        ):
            error.window_failures = [
                dict(row) for row in failures if isinstance(row, Mapping)
            ]
    return error


def _window_funnel_from(
    exc: BaseException, *, candidate: Mapping[str, Any] | None
) -> tuple[Any, Any]:
    """The funnel for one blocked-scope record, exception first, plan second.

    Belt and braces for the hop above: an exception that carries the funnel
    is authoritative, and a plan that carries one is read when the
    exception does not -- so a future re-raise that forgets to move it
    costs a hop's worth of provenance rather than the whole diagnosis.
    """

    counts = getattr(exc, "window_gate_counts", None)
    failures = getattr(exc, "window_failures", None)
    if counts is None or failures is None:
        audit = (
            candidate.get("delta_v2_audit")
            if isinstance(candidate, Mapping) else None
        )
        if isinstance(audit, Mapping):
            if counts is None and isinstance(
                audit.get("window_gate_counts"), Mapping
            ):
                counts = dict(audit["window_gate_counts"])
            if failures is None and isinstance(
                audit.get("window_failures"), Sequence
            ) and not isinstance(
                audit.get("window_failures"), (str, bytes, bytearray)
            ):
                failures = [
                    dict(row)
                    for row in audit["window_failures"]
                    if isinstance(row, Mapping)
                ]
    return counts, failures


def insert_probability_envelope(
    conn: sqlite3.Connection,
    envelope: ProbabilityEnvelope,
    *,
    created_at_utc: str,
) -> dict[str, Any]:
    """Single resident write seam: envelope and X-S-B projection atomically.

    ``created_at`` is when the row was actually committed -- the wall clock
    at this write -- never earlier than the logical instant the caller hands
    in.  The callers hand in their decision clocks, which are logical: a P1
    new-high step is dated at its report's commit, a confirmation at its
    TAF's arrival, and a replay a millisecond past a root minted at the cycle
    clock.  Stored as ``created_at`` those claimed the row existed from then
    on, and a strict as-of reader could not tell: the 2026-09-13 review found
    fourteen P1 rows that appeared between two reads of the same window with
    ``created_at`` equal to a decision already inside it (EDDM decided
    08:52:42Z, written after 08:56Z), and the paper ledger pairs a checkpoint
    with every book from its decision on.  The logical clock stays on the
    envelope as ``decision_at_utc``; this one says when anyone could read it
    (``probability_knowable_at``).  Equal replays return before either clock
    is written, so a row keeps the commit time of its first write.
    """

    wall_clock = datetime.now(timezone.utc).isoformat(
        timespec="milliseconds"
    ).replace("+00:00", "Z")
    return materialize_probability_bridge(
        conn,
        envelope,
        created_at_utc=(
            wall_clock
            if timestamp_lt(str(created_at_utc), wall_clock)
            else str(created_at_utc)
        ),
    )


def _stored_probability_envelope(
    conn: sqlite3.Connection,
    *,
    checkpoint_id: str,
) -> ProbabilityEnvelope:
    row = conn.execute(
        "SELECT stage,checkpoint_id,station_id,event_date,"
        "settlement_timezone,decision_at_utc,fresh_until_utc,"
        "bucket_ordinals_json,probabilities_json,posterior_version,"
        "posterior_sha256,bridge_sha256,lineage_json "
        "FROM basket_probability_envelope WHERE checkpoint_id=?",
        (checkpoint_id,),
    ).fetchone()
    if row is None:
        raise ContractError("resident_p0_existing_checkpoint_missing")
    return ProbabilityEnvelope.from_mapping({
        "stage": row[0],
        "checkpoint_id": row[1],
        "station_id": row[2],
        "event_date": row[3],
        "settlement_timezone": row[4],
        "decision_at_utc": row[5],
        "fresh_until_utc": row[6],
        "bucket_ordinals": json.loads(str(row[7])),
        "probabilities": json.loads(str(row[8])),
        "posterior_version": row[9],
        "posterior_sha256": row[10],
        "bridge_sha256": row[11],
        "lineage": json.loads(str(row[12])),
    })


def _p0_bridge_only_semantic_equivalent(
    existing: ProbabilityEnvelope,
    candidate: ProbabilityEnvelope,
) -> bool:
    """Recognize the one-time catalog-root to scope-bridge correction."""

    return (
        existing.stage == candidate.stage == "P0"
        and existing.station_id == candidate.station_id
        and existing.event_date == candidate.event_date
        and existing.settlement_timezone == candidate.settlement_timezone
        and existing.decision_at_utc == candidate.decision_at_utc
        and existing.fresh_until_utc == candidate.fresh_until_utc
        and existing.bucket_ordinals == candidate.bucket_ordinals
        and set(existing.probabilities) == set(candidate.probabilities)
        and all(
            abs(
                float(existing.probabilities[bucket])
                - float(candidate.probabilities[bucket])
            )
            <= 1e-12
            for bucket in existing.probabilities
        )
        and existing.posterior_version == candidate.posterior_version
        and existing.lineage == candidate.lineage
        and existing.bridge_sha256 != candidate.bridge_sha256
    )


# ``database is locked`` is the same message for two unrelated faults, and
# telling them apart decides whether waiting longer can ever help.  The
# distinction itself lives in ``sqlite_busy`` -- the capture lanes need the
# same answer and a second copy of it would drift -- and what stays here is
# the vocabulary production reports it under: a blocked scope names the
# writer it could not take, so ``target_writer_`` prefixes the shared kind.
#
# Measured: with a pinned cursor and a competing committer, BEGIN IMMEDIATE
# fails in 0.000s with 517 while busy_timeout is 60000.  Production blocked
# ten to fifteen stations at a time roughly six times a day under the shared
# message, with nothing in the record to say which fault it was.
WRITER_LOCK_RETRY_ATTEMPTS = 3
SQLITE_BUSY_PRIMARY = sqlite_busy.SQLITE_BUSY_PRIMARY
SQLITE_BUSY_SNAPSHOT = sqlite_busy.SQLITE_BUSY_SNAPSHOT
#: The one kind retrying cannot fix; spelled from the shared name so the
#: branch below cannot drift away from the classifier that produces it.
WRITER_STALE_READ_SNAPSHOT = f"target_writer_{sqlite_busy.STALE_READ_SNAPSHOT}"


def _sqlite_busy_kind(exc: BaseException) -> tuple[str, int] | None:
    """Name a lock failure by its extended result code, or None if unrelated."""

    kind = sqlite_busy.busy_kind(exc)
    if kind is None:
        return None
    name, code = kind
    return (f"target_writer_{name}", code)


def _begin_writer_lock(
    conn: sqlite3.Connection,
    *,
    savepoint: str,
) -> None:
    """Take the file's write lock, retrying only the fault retrying can fix."""

    # Retrying must not extend the wait, only split it.  The connection's
    # busy_timeout is the budget the caller already chose; three attempts at
    # the full budget would turn one lock event into three times the stall,
    # and a cycle is under three minutes.  So the budget is divided by the
    # attempts and each attempt gets its share.  Total wait is unchanged and
    # the lock is contested three times instead of once, which is strictly
    # better: a holder that commits mid-wait is caught at the next attempt
    # instead of only at the one deadline.
    try:
        inherited_timeout_ms = int(
            conn.execute("PRAGMA busy_timeout").fetchone()[0] or 0
        )
    except sqlite3.Error:
        inherited_timeout_ms = 0
    attempt_timeout_ms = max(
        1, inherited_timeout_ms // WRITER_LOCK_RETRY_ATTEMPTS
    ) if inherited_timeout_ms > 0 else 0
    if attempt_timeout_ms:
        try:
            conn.execute(f"PRAGMA busy_timeout={attempt_timeout_ms}")
        except sqlite3.Error:
            attempt_timeout_ms = 0

    def _restore_timeout() -> None:
        if not attempt_timeout_ms:
            return
        try:
            conn.execute(f"PRAGMA busy_timeout={inherited_timeout_ms}")
        except sqlite3.Error:
            pass

    last: sqlite3.OperationalError | None = None
    for attempt in range(1, WRITER_LOCK_RETRY_ATTEMPTS + 1):
        try:
            conn.execute("BEGIN IMMEDIATE")
            # A retry that wins needs no counter of its own: the caller times
            # the lock from before the first attempt, so ``wait_ms`` in the
            # writer-lock profile already reports the full busy_timeout the
            # earlier attempts burned.
            _restore_timeout()
            return
        except sqlite3.OperationalError as exc:
            kind = _sqlite_busy_kind(exc)
            if kind is None:
                _restore_timeout()
                raise
            name, code = kind
            if name == WRITER_STALE_READ_SNAPSHOT:
                # Deterministic until the caller's read ends; retrying would
                # only burn the cycle.  Name it and let the scope block.
                _restore_timeout()
                raise ContractError(
                    f"{name}:{savepoint}:sqlite_errorcode={code}"
                ) from exc
            last = exc
            if attempt < WRITER_LOCK_RETRY_ATTEMPTS:
                continue
            _restore_timeout()
            raise ContractError(
                f"{name}:{savepoint}:sqlite_errorcode={code}"
                f":attempts={attempt}"
            ) from exc
    if last is not None:  # pragma: no cover - loop always returns or raises
        raise last


@contextmanager
def _writer_transaction(
    conn: sqlite3.Connection,
    *,
    savepoint: str,
) -> Iterator[None]:
    """Use one fail-closed transaction without disturbing an outer writer."""

    own_transaction = not conn.in_transaction
    # Only an outermost transaction acquires the file's single write lock; a
    # savepoint nests inside one already held, so timing it would count the
    # same lock twice.  Reported under the savepoint name because that is
    # what identifies the call site.
    lock_started_ns = time.perf_counter_ns()
    if own_transaction:
        _begin_writer_lock(conn, savepoint=savepoint)
    else:
        conn.execute(f"SAVEPOINT {savepoint}")
    acquired_ns = time.perf_counter_ns()
    try:
        yield
        if own_transaction:
            # Split the hold: statements the transaction ran, versus the
            # commit that flushes them.  On a starved page cache and a near
            # full disk these are different problems with different fixes,
            # and a single "held for 19s" cannot tell them apart.
            body_ns = time.perf_counter_ns()
            note_ledger_span(
                f"txn_body:{savepoint}",
                (body_ns - acquired_ns) / 1_000_000.0,
            )
            with ledger_span(f"txn_commit:{savepoint}"):
                conn.commit()
            note_writer_lock_sample(
                savepoint,
                wait_ms=(acquired_ns - lock_started_ns) / 1_000_000.0,
                hold_ms=(time.perf_counter_ns() - acquired_ns) / 1_000_000.0,
            )
        else:
            conn.execute(f"RELEASE {savepoint}")
    except Exception:
        if own_transaction:
            conn.rollback()
        else:
            conn.execute(f"ROLLBACK TO {savepoint}")
            conn.execute(f"RELEASE {savepoint}")
        raise

