def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")


# When a cycle overruns, the stack says only that SQLite is reading btree
# pages -- true of every slow query and useful for none of them.  Twice now
# production has stalled for tens of minutes with nothing in the record to
# name the statement, and the second time the diagnosis was three rounds of
# ``sample`` plus timing candidate queries by hand.
#
# The heartbeat thread keeps writing status.json while the cycle thread is
# parked inside ``sqlite3_step``, so the probe only has to record what each
# thread started and when, and clear it on return.
#
# It does that in Python, around ``execute``, and NOT with sqlite3's own
# trace or progress callbacks.  Those were tried first and deadlocked the
# resident within 34 seconds: a native callback has to take the GIL while
# SQLite holds the connection mutex, every connection here is opened
# ``check_same_thread=False`` and shared across the cycle, forecast and
# heartbeat threads, and a second thread holding the GIL and entering the
# same connection needs that mutex.  Six threads were parked in ``take_gil``
# with two more in ``__psynch_mutexwait`` and nothing running.  A Python
# wrapper takes no lock SQLite knows about and cannot invert that order.
#
# The cost is one dict store before the call and one after, on a path that
# is about to enter SQLite anyway.
_STATEMENT_PROBE: dict[int, dict[str, Any]] = {}
_STATEMENT_PROBE_SQL_CHARS = 400
# Charter 177: per-thread statement ledger.  The probe already sees every
# statement a thread runs; it now also keeps, per statement text, how many
# times it ran and how long its execute and its fetches took, so a cycle can
# say which SQL it spent its time in instead of leaving that to sampled
# stacks -- on 2026-09-21 three stack samples in a row landed on queries that
# turned out to cost 1-2ms, while the two that cost 75ms and 72ms per call
# were found only by profiling one stage offline.  Bounded: past this many
# distinct texts the rest are pooled under one key.
_STATEMENT_LEDGER_MAX_KEYS = 2000
_STATEMENT_LEDGER_KEY_CHARS = 240
_STATEMENT_LEDGER_OTHER = "<other statements>"


def _ledger_key(sql: str) -> str:
    return " ".join(str(sql).split())[:_STATEMENT_LEDGER_KEY_CHARS]


def _ledger_charge(slot: dict[str, Any], key: str, *, execute_ns: int = 0,
                   fetch_ns: int = 0, count: int = 0) -> None:
    ledger = slot.get("ledger")
    if ledger is None:
        return
    entry = ledger.get(key)
    if entry is None:
        if len(ledger) >= _STATEMENT_LEDGER_MAX_KEYS:
            key = _STATEMENT_LEDGER_OTHER
            entry = ledger.get(key)
        if entry is None:
            entry = [0, 0, 0]
            ledger[key] = entry
    entry[0] += count
    entry[1] += execute_ns
    entry[2] += fetch_ns


def begin_statement_ledger() -> None:
    """Start (or restart) this thread's statement ledger."""
    _probe_slot()["ledger"] = {}


def statement_ledger_top(limit: int = 15) -> list[dict[str, Any]]:
    """This thread's ledger, costliest statement texts first."""
    ledger = _probe_slot().get("ledger") or {}
    rows = sorted(
        ledger.items(), key=lambda item: -(item[1][1] + item[1][2])
    )[: max(0, int(limit))]
    return [
        {
            "sql": key,
            "count": int(entry[0]),
            "total_ms": round((entry[1] + entry[2]) / 1_000_000.0, 1),
            "execute_ms": round(entry[1] / 1_000_000.0, 1),
            "fetch_ms": round(entry[2] / 1_000_000.0, 1),
        }
        for key, entry in rows
    ]


def _probe_slot() -> dict[str, Any]:
    ident = threading.get_ident()
    slot = _STATEMENT_PROBE.get(ident)
    if slot is None:
        slot = {
            "statement_count": 0, "sql": None, "started_ns": None,
            "drain_sql": None, "drain_started_ns": None, "drain_rows": 0,
        }
        _STATEMENT_PROBE[ident] = slot
    return slot


def _clear_drain() -> None:
    """A cursor that ran out of rows is no longer being drained."""

    slot = _probe_slot()
    slot["drain_sql"] = None
    slot["drain_started_ns"] = None
    slot["drain_rows"] = 0


RESTING_REPRICE_RECEIPT_PATH = Path(
    os.environ.get("PM_RESTING_REPRICE_RECEIPT_PATH", "")
    or (Path(__file__).resolve().parents[1] / "data" / "resting_reprice_latest.json")
)


def _publish_resting_reprice_receipt(
    receipt: Mapping[str, Any], *, as_of_utc: str
) -> None:
    """Put the resting-ladder verdict somewhere a reader can find it now.

    The cycle's own receipt carries this lane already, but it only reaches
    ``state["production"]`` when the WHOLE cycle returns -- and on 2026-09-07
    a cycle ran 3,912 seconds against a 720-second overdue threshold, so
    every stage result inside it was invisible for over an hour while the
    daemon's status file showed only ``production_inflight``.  A lane that
    cancels real orders at an exchange must not be observable only on the
    other side of that.  Errors here are swallowed on purpose: an
    observability write may never be the reason a trading cycle fails.
    """

    try:
        payload = dict(receipt)
        payload["published_at_utc"] = as_of_utc
        path = RESTING_REPRICE_RECEIPT_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_name(f".{path.name}.tmp.{os.getpid()}")
        tmp.write_text(
            json.dumps(payload, ensure_ascii=False, sort_keys=True, default=str)
            + "\n",
            encoding="utf-8",
        )
        os.replace(tmp, path)
    except Exception:  # noqa: BLE001 -- observability never blocks the cycle
        pass


class _ProbedCursor(sqlite3.Cursor):
    """A cursor that says which statement it is inside while it is inside."""

    def execute(self, sql, parameters=(), /):  # type: ignore[override]
        slot = _probe_slot()
        slot["sql"] = sql[:_STATEMENT_PROBE_SQL_CHARS]
        started_ns = time.perf_counter_ns()
        slot["started_ns"] = started_ns
        slot["statement_count"] += 1
        if slot.get("ledger") is not None:
            self._ledger_key = _ledger_key(sql)
        try:
            return super().execute(sql, parameters)
        except sqlite3.Error as exc:
            # The cycle's outermost handler turns every SQLite fault into one
            # sentence -- "OperationalError:database is locked" -- with no way
            # back to the statement.  Keep the statement here so the handler
            # can name it.
            slot["failed_sql"] = sql[:_STATEMENT_PROBE_SQL_CHARS]
            slot["failed_error"] = f"{type(exc).__name__}:{exc}"
            raise
        finally:
            # Cleared on return, so an idle thread never reads as a stalled
            # one.  The statement moves to the drain slot instead of
            # vanishing: rows pulled from the returned cursor were the honest
            # boundary of v2, and on 2026-09-09 the cycle spent an hour on
            # the far side of it -- 196,202 statements all returned,
            # ``in_flight`` empty, the process in uninterruptible IO, and the
            # last statement already blanked here.  A query that returns
            # instantly and is then dragged row by row is exactly the shape
            # this codebase keeps finding, so it has to be nameable too.
            if slot.get("ledger") is not None:
                _ledger_charge(
                    slot, getattr(self, "_ledger_key", _ledger_key(sql)),
                    count=1, execute_ns=time.perf_counter_ns() - started_ns,
                )
            slot["sql"] = None
            slot["started_ns"] = None
            slot["drain_sql"] = sql[:_STATEMENT_PROBE_SQL_CHARS]
            slot["drain_started_ns"] = time.perf_counter_ns()
            slot["drain_rows"] = 0

    def _drained(self, rows: int) -> None:
        slot = _probe_slot()
        if slot.get("drain_started_ns") is not None:
            slot["drain_rows"] = int(slot.get("drain_rows") or 0) + rows

    def _charge_fetch(self, started_ns: int) -> None:
        key = getattr(self, "_ledger_key", None)
        if key is None:
            return
        slot = _probe_slot()
        if slot.get("ledger") is not None:
            _ledger_charge(slot, key, fetch_ns=time.perf_counter_ns() - started_ns)

    def __next__(self):  # type: ignore[override]
        started_ns = time.perf_counter_ns()
        try:
            row = super().__next__()
        except StopIteration:
            self._charge_fetch(started_ns)
            _clear_drain()
            raise
        self._charge_fetch(started_ns)
        self._drained(1)
        return row

    def fetchone(self):  # type: ignore[override]
        started_ns = time.perf_counter_ns()
        row = super().fetchone()
        self._charge_fetch(started_ns)
        if row is None:
            _clear_drain()
        else:
            self._drained(1)
        return row

    def fetchmany(self, size=None):  # type: ignore[override]
        started_ns = time.perf_counter_ns()
        rows = super().fetchmany() if size is None else super().fetchmany(size)
        self._charge_fetch(started_ns)
        self._drained(len(rows))
        if not rows:
            _clear_drain()
        return rows

    def fetchall(self):  # type: ignore[override]
        started_ns = time.perf_counter_ns()
        rows = super().fetchall()
        self._charge_fetch(started_ns)
        self._drained(len(rows))
        _clear_drain()
        return rows


class _ProbedConnection(sqlite3.Connection):
    """Route ``Connection.execute`` through the probing cursor."""

    def cursor(self, factory=_ProbedCursor):  # type: ignore[override]
        return super().cursor(factory)

    def execute(self, sql, parameters=(), /):  # type: ignore[override]
        return self.cursor().execute(sql, parameters)


def last_failed_statement() -> dict[str, Any] | None:
    """The last statement that raised on this thread, if one has."""

    slot = _STATEMENT_PROBE.get(threading.get_ident())
    if not slot or not slot.get("failed_sql"):
        return None
    return {
        "sql": slot.get("failed_sql"),
        "error": slot.get("failed_error"),
    }


def statement_probe_snapshot(*, min_elapsed_ms: float = 1000.0) -> dict[str, Any]:
    """Name the longest statement now executing, or say none is."""

    now_ns = time.perf_counter_ns()
    running: list[dict[str, Any]] = []
    draining: list[dict[str, Any]] = []
    total = 0
    for thread_ident, slot in list(_STATEMENT_PROBE.items()):
        total += int(slot.get("statement_count") or 0)
        started = slot.get("started_ns")
        if started is not None:
            elapsed_ms = (now_ns - int(started)) / 1_000_000.0
            if elapsed_ms >= min_elapsed_ms:
                running.append({
                    "thread_ident": thread_ident,
                    "elapsed_ms": round(elapsed_ms, 1),
                    "sql": slot.get("sql"),
                })
        # A statement that returned and is still handing back rows.  Reported
        # separately because it is a different fault with the same symptom:
        # ``in_flight`` empty while the cycle does not return.
        drain_started = slot.get("drain_started_ns")
        if drain_started is None:
            continue
        drain_ms = (now_ns - int(drain_started)) / 1_000_000.0
        if drain_ms < min_elapsed_ms:
            continue
        draining.append({
            "thread_ident": thread_ident,
            "elapsed_ms": round(drain_ms, 1),
            "rows": int(slot.get("drain_rows") or 0),
            "sql": slot.get("drain_sql"),
        })
    running.sort(key=lambda item: -float(item["elapsed_ms"]))
    draining.sort(key=lambda item: -float(item["elapsed_ms"]))
    return {
        "schema": "basket_target_statement_probe_v3",
        "statement_count": total,
        "threads_traced": len(_STATEMENT_PROBE),
        "min_elapsed_ms": min_elapsed_ms,
        "in_flight": running[:4],
        "draining": draining[:4],
    }


def open_target_read_only(path: Path) -> sqlite3.Connection:
    """Open target SSOT in SQLite read-only mode; never create a database."""

    resolved = resolve_target_database(path)
    conn = sqlite3.connect(
        f"file:{resolved}?mode=ro",
        uri=True,
        timeout=60.0,
        isolation_level=None,
        check_same_thread=False,
        factory=_ProbedConnection,
    )
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA busy_timeout=60000")
    conn.execute("PRAGMA query_only=ON")
    conn.execute("PRAGMA synchronous=FULL")
    return conn


def open_target_writer_if_enabled(path: Path, *, activation_path: Path) -> sqlite3.Connection | None:
    """Open the isolated M5 writer only for the explicit no-live deployment.

    The environment variable is a service-domain wiring flag, not a live
    authorization. It is accepted only when the resident execution mode is
    exactly ``production_no_live`` and the file activation contract proves
    every live boundary false.
    """

    enabled = str(os.environ.get("PM_TARGET_PRODUCTION_WRITER", "") or "").strip().lower()
    if enabled not in {"1", "true", "yes", "on"}:
        return None
    mode = str(os.environ.get("PM_TARGET_EXECUTION_MODE", "") or "").strip()
    if mode and mode != PRODUCTION_EXECUTION_MODE:
        raise RuntimeError("target_writer_execution_mode_mismatch")
    # load_activation, not load_target_activation: the schema-dispatching
    # loader.  The go-live flip pointed DEFAULT_TARGET_ACTIVATION at the live
    # contract while this line still called the no-live-only loader, which
    # refused the live schema on sight -- target_activation_schema_invalid,
    # writer gate shut, production blocked_fail_closed for seven hours
    # (2026-08-30T18:33 to 2026-08-31T01:57) before anybody looked at the
    # production block of the status file.  The monitor that was watching for
    # the first live intent could not see it: an intent needs a writer.
    activation = load_activation(activation_path)
    if activation.get("execution_mode") != PRODUCTION_EXECUTION_MODE:
        raise RuntimeError("target_writer_activation_mode_mismatch")
    # Each mode asserts its own boundaries rather than one mode asserting all
    # of them false.  Two stay false in both -- the target lane does not write
    # the shared production database and does not mutate production in either
    # mode -- and a live contract that let those through would be claiming a
    # reach this lane has never had.
    if PRODUCTION_EXECUTION_MODE == "production_live":
        must_be_true = (
            "live_decision_write_authorized",
            "live_order_authorized",
            "live_submit_authorized",
            "places_orders",
            "calls_order_gateway",
            "network_access",
        )
        must_be_false = ("writes_production_db", "production_mutation")
        if any(activation.get(key) is not True for key in must_be_true):
            raise RuntimeError("target_writer_activation_live_boundary_invalid")
    else:
        must_be_false = (
            "live_decision_write_authorized",
            "live_order_authorized",
            "live_submit_authorized",
            "places_orders",
            "writes_production_db",
            "calls_order_gateway",
            "network_access",
        )
    if any(activation.get(key) is not False for key in must_be_false):
        raise RuntimeError("target_writer_activation_live_boundary_invalid")
    resolved = resolve_target_database(path)
    conn = sqlite3.connect(
        resolved,
        timeout=60.0,
        isolation_level=None,
        check_same_thread=False,
        factory=_ProbedConnection,
    )
    try:
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA busy_timeout=60000")
        conn.execute("PRAGMA synchronous=FULL")
        if resolved == DEFAULT_TARGET_DB.resolve():
            journal_mode = str(
                conn.execute("PRAGMA journal_mode").fetchone()[0] or ""
            ).strip().lower()
            if journal_mode != "wal":
                raise RuntimeError(
                    "target_writer_journal_mode_not_wal:"
                    f"{journal_mode or 'unknown'}"
                )
        assert_connection_target_capacity(
            conn,
            recover_oversized_wal=True,
        )
        status = production_ssot_schema_status(conn)
        if status.get("ok") is not True or status.get("ledger_schema_ok") is not True:
            raise RuntimeError(
                "target_writer_schema_not_ready:"
                + json.dumps(status, ensure_ascii=False, sort_keys=True)
            )
        assert_target_database_owner(conn)
        return conn
    except Exception:
        conn.close()
        raise


def _blocked(reason: str, *, station_id: str | None = None, event_date: str | None = None) -> dict[str, Any]:
    result: dict[str, Any] = {
        "schema": SCHEMA,
        "ok": False,
        "state": "blocked_fail_closed",
        "reason": reason,
        "execution_mode": PRODUCTION_EXECUTION_MODE,
        "places_orders": False,
        "calls_order_gateway": False,
        "live_submit_authorized": False,
        "orders_submitted": 0,
    }
    if station_id:
        result["station_id"] = station_id
    if event_date:
        result["event_date"] = event_date
    return result


_ENSEMBLE_CANDIDATE_MEMBER_TABLES = (
    "calibration_republisher_ensemble_member_run",
    # Retained pre-migration Open-Meteo rows stay explicitly republisher
    # lineage.  They are read here to finish closed-day historical OOS
    # evidence and may serve the separate no-live P0 fallback contract; native
    # arrival/P1 authority remains independently fail-closed.
    "calibration_native_ensemble_member_run",
)

_ENSEMBLE_CANDIDATE_BUCKET_TABLES = (
    "calibration_republisher_ensemble_member_bucket",
    "calibration_native_ensemble_member_bucket",
)


def _existing_ensemble_candidate_tables(
    conn: sqlite3.Connection,
    *,
    tables: Sequence[str],
) -> tuple[str, ...]:
    """Return only installed candidate tables from the fixed SSOT allowlist."""

    present = {
        str(row[0])
        for row in conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table'"
        )
    }
    return tuple(table for table in tables if table in present)


def _candidate_ensemble_station_ids(
    conn: sqlite3.Connection,
    *,
    limit: int,
) -> list[str]:
    """List bounded OOS candidates from both republisher and legacy lanes."""

    tables = _existing_ensemble_candidate_tables(
        conn,
        tables=_ENSEMBLE_CANDIDATE_MEMBER_TABLES,
    )
    if not tables:
        return []
    source = " UNION ".join(
        "SELECT station_id FROM " + table
        + " WHERE authority_scope='PRODUCTION_NO_LIVE_CANDIDATE'"
        for table in tables
    )
    return [
        str(row[0])
        for row in conn.execute(
            "SELECT DISTINCT station_id FROM ("
            + source
            + ") ORDER BY station_id LIMIT ?",
            (limit,),
        )
    ]


def _native_ensemble_artifact_vintage_by_station(
    conn: sqlite3.Connection,
) -> dict[str, str]:
    """Latest system-calibration vintage per station, for staleness-first picks.

    A station with no artifact at all maps to "" and therefore sorts ahead
    of every dated vintage: never-fitted is the hungriest state there is.
    """

    # Charter 183: the table is append-only by trigger, so the answer moves
    # only when a row is added -- which moves its newest rowid.  The group-by
    # walked all ~82k artifact rows every cycle (1.4s warm, 2-7s in cycle).
    try:
        top = conn.execute(
            "SELECT MAX(rowid) FROM calibration_native_ensemble_system_artifact"
        ).fetchone()[0]
        database = _connection_database_name(conn)
        cached = _ARTIFACT_VINTAGE_MEMO.get(database) if database else None
        if cached is not None and cached[0] == top:
            return dict(cached[1])
        vintage = {
            str(row[0]): str(row[1] or "")
            for row in conn.execute(
                "SELECT station_id, MAX(valid_from_utc)"
                " FROM calibration_native_ensemble_system_artifact"
                " GROUP BY station_id"
            )
        }
    except sqlite3.OperationalError:
        return {}
    if database:
        _ARTIFACT_VINTAGE_MEMO[database] = (top, dict(vintage))
    return vintage


# database -> (newest system-artifact rowid, vintage by station), charter 183.
_ARTIFACT_VINTAGE_MEMO: dict[str, tuple[Any, dict[str, str]]] = {}


def _connection_database_name(conn: sqlite3.Connection) -> str:
    """The file behind the connection's main database ('' if none)."""

    known = getattr(conn, "_worker_database_name", None)
    if isinstance(known, str):
        return known
    database = str(conn.execute("PRAGMA database_list").fetchone()[2] or "")
    try:
        conn._worker_database_name = database  # type: ignore[attr-defined]
    except (AttributeError, TypeError):
        pass
    return database


def _candidate_ensemble_scopes_without_truth(
    conn: sqlite3.Connection,
    *,
    limit: int,
) -> list[tuple[str, str, str]]:
    """Return bounded candidate station-days still lacking accepted AWC truth."""

    tables = _existing_ensemble_candidate_tables(
        conn,
        tables=_ENSEMBLE_CANDIDATE_MEMBER_TABLES,
    )
    if not tables:
        return []
    source = " UNION ".join(
        "SELECT station_id,target_local_date FROM " + table
        + " WHERE authority_scope='PRODUCTION_NO_LIVE_CANDIDATE'"
        for table in tables
    )
    rows = conn.execute(
        "WITH candidate_scopes AS ("
        + source
        + ") SELECT DISTINCT m.station_id,m.target_local_date,"
        "r.settlement_timezone FROM candidate_scopes m "
        "JOIN basket_target_market_registry r "
        "ON r.station_id=m.station_id "
        "AND r.event_date=m.target_local_date "
        "AND r.source_eligible=1 "
        "WHERE NOT EXISTS ("
        "SELECT 1 FROM calibration_station_daily_high_truth t "
        "WHERE t.station_id=m.station_id "
        "AND t.local_date=m.target_local_date "
        "AND t.source_lane IN " + FORMAL_TRUTH_LANES_SQL + " "
        "AND t.qc_status='ACCEPTED'"
        ") ORDER BY m.target_local_date,m.station_id LIMIT ?",
        (limit,),
    ).fetchall()
    return [
        (str(station), str(event_date), str(settlement_timezone))
        for station, event_date, settlement_timezone in rows
    ]


def _open_meteo_packet_bucket_exists(
    conn: sqlite3.Connection,
    *,
    ensemble_system_id: str,
    station_id: str,
    event_date: str,
    member_set_sha256: str,
    bucket_contract_sha256: str,
) -> bool:
    """Check new republisher storage first, then immutable legacy rows."""

    for table in _existing_ensemble_candidate_tables(
        conn,
        tables=_ENSEMBLE_CANDIDATE_BUCKET_TABLES,
    ):
        exists = conn.execute(
            "SELECT 1 FROM " + table + " "
            "WHERE ensemble_system_id=? AND station_id=? "
            "AND target_local_date=? AND member_set_sha256=? "
            "AND bucket_contract_sha256=? "
            "AND source_role='aggregator_republisher' "
            "AND authority_scope='PRODUCTION_NO_LIVE_CANDIDATE' LIMIT 1",
            (
                ensemble_system_id,
                station_id,
                event_date,
                member_set_sha256,
                bucket_contract_sha256,
            ),
        ).fetchone()
        if exists is not None:
            return True
    return False


def _preferred_forward_packets_for_p0(
    packets: Sequence[Mapping[str, Any]],
) -> tuple[
    dict[tuple[str, str], Mapping[str, Any]],
    dict[tuple[str, str], Mapping[str, Any]],
    dict[tuple[str, str], Mapping[str, Any]],
]:
    """Choose official packets per scope, retaining governed fallback scope.

    This function only resolves input precedence.  It does not grant the
    Open-Meteo packet P0 authority: ``compile_native_ensemble_p0`` later
    requires its own closed-AWC historical strict-OOS proof and activation.
    """

    official_by_scope: dict[tuple[str, str], Mapping[str, Any]] = {}
    republisher_by_scope: dict[tuple[str, str], Mapping[str, Any]] = {}
    for packet in packets:
        schema = str(packet.get("schema") or "")
        if schema not in {
            OPEN_METEO_FORWARD_PACKET_SCHEMA,
            OFFICIAL_NATIVE_FORWARD_PACKET_SCHEMA,
        }:
            continue
        scope = (
            str(packet.get("station_id") or "").strip().upper(),
            str(packet.get("event_date") or ""),
        )
        if not all(scope):
            raise ContractError("native_forward_scope_invalid")
        target = (
            official_by_scope
            if schema == OFFICIAL_NATIVE_FORWARD_PACKET_SCHEMA
            else republisher_by_scope
        )
        current = target.get(scope)
        if current is not None and current != packet:
            raise ContractError(
                "native_forward_scope_content_conflict:"
                + ("official" if target is official_by_scope else "republisher")
            )
        target[scope] = packet
    # An official packet always wins its station-day.  A republisher packet is
    # retained only for scopes with no native packet at this evidence instant.
    selected = dict(republisher_by_scope)
    selected.update(official_by_scope)
    return selected, official_by_scope, republisher_by_scope


def _forward_packet_in_cycle_scope(
    packet: Mapping[str, Any],
    *,
    station_allowlist: Sequence[str] = (),
    event_date_allowlist: Sequence[str] = (),
) -> bool:
    """Keep only packets owned by the current resident cycle scope."""

    station = str(packet.get("station_id") or "").strip().upper()
    event_date = str(packet.get("event_date") or "").strip()
    allowed_stations = {
        str(value or "").strip().upper()
        for value in station_allowlist
        if str(value or "").strip()
    }
    allowed_event_dates = {
        str(value or "").strip()
        for value in event_date_allowlist
        if str(value or "").strip()
    }
    return (
        bool(station)
        and bool(event_date)
        and (
            not allowed_stations
            or station in allowed_stations
        )
        and (
            not allowed_event_dates
            or event_date in allowed_event_dates
        )
    )


def _compile_native_ensemble_p0_runtime(
    conn: sqlite3.Connection,
    *,
    forward_packet: Mapping[str, Any],
    decision_at_utc: str,
    native_oos_snapshot: NativeOosSnapshot | Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Compile P0 with the immutable native pointer when production enables it.

    The optional keyword is omitted for isolated unit/research callers so
    existing compiler fixtures remain independent of the production cutoff
    file.  The resident production writer always supplies a validated
    snapshot (or an invalid sentinel, which the compiler rejects fail closed).
    """

    kwargs: dict[str, Any] = {
        "forward_packet": forward_packet,
        "decision_at_utc": decision_at_utc,
    }
    if native_oos_snapshot is not None:
        kwargs["native_oos_snapshot"] = native_oos_snapshot
    return compile_native_ensemble_p0(conn, **kwargs)


def _compile_native_p0_with_republisher_fallback(
    conn: sqlite3.Connection,
    *,
    scope: tuple[str, str],
    preferred_packet: Mapping[str, Any],
    official_packet: Mapping[str, Any] | None,
    republisher_packet: Mapping[str, Any] | None,
    decision_at_utc: str,
    native_oos_snapshot: NativeOosSnapshot | Mapping[str, Any] | None = None,
    republisher_fallback_activation: Mapping[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, list[dict[str, Any]], str]:
    """Compile only the official-native P0 candidate for one scope.

    Republisher cross-selection is historical no-live evidence, not a native
    forward packet or P0 authority.  The retired fallback argument remains a
    typed no-op only until all historical callers are deleted; it can never
    route Open-Meteo data into the native compiler.
    """

    # Prefer the separately indexed official packet rather than trusting the
    # caller's convenience ``preferred_packet``.  This matters when a caller
    # has already tentatively selected an Open-Meteo packet: a fresh official
    # packet for the same station-day must still compile first.  Conversely,
    # a stale official packet is intentionally attempted and recorded before
    # the governed republisher retry; it must not be treated as fresh merely
    # because this function is running now.
    preferred_schema = str(preferred_packet.get("schema") or "")
    official_candidate = official_packet
    if (
        official_candidate is None
        and preferred_schema == OFFICIAL_NATIVE_FORWARD_PACKET_SCHEMA
    ):
        official_candidate = preferred_packet
    del republisher_packet, republisher_fallback_activation

    candidates: list[tuple[str, Mapping[str, Any]]] = []

    def append_candidate(
        source_class: str,
        packet: Mapping[str, Any] | None,
    ) -> None:
        if packet is None or any(
            existing_packet == packet
            for _existing_source, existing_packet in candidates
        ):
            return
        candidates.append((source_class, packet))

    append_candidate("official_native", official_candidate)
    if not candidates:
        return None, [{
            "station_id": scope[0],
            "event_date": scope[1],
            "source_class": (
                "aggregator_republisher"
                if preferred_schema == OPEN_METEO_FORWARD_PACKET_SCHEMA
                else "official_native"
            ),
            "schema": preferred_schema,
            "reason": "republisher_no_live_selection_not_forward_p0_authority",
        }], ""

    failures: list[dict[str, Any]] = []
    for source_class, packet in candidates:
        try:
            compiled = _compile_native_ensemble_p0_runtime(
                conn,
                forward_packet=packet,
                decision_at_utc=decision_at_utc,
                native_oos_snapshot=native_oos_snapshot,
            )
            if (
                not isinstance(compiled, Mapping)
                or compiled.get("schema")
                != "calibrated_native_cross_ensemble_p0_packet_v1"
            ):
                raise ContractError("native_p0_compiler_result_invalid")
            return dict(compiled), failures, source_class
        except Exception as exc:
            failures.append({
                "station_id": scope[0],
                "event_date": scope[1],
                "source_class": source_class,
                "schema": str(packet.get("schema") or ""),
                "reason": f"{type(exc).__name__}:{exc}",
            })
    return None, failures, ""


def _native_ensemble_truth_signatures(
    conn: sqlite3.Connection,
    *,
    max_stations: int = MAX_FORWARD_P0_STATIONS,
    max_cases_per_station: int = (
        MAX_NATIVE_ENSEMBLE_TRUTH_CASES_PER_STATION
    ),
) -> dict[str, str]:
    """Hash accepted truth identity for every native or republisher scope."""

    tables = _existing_ensemble_candidate_tables(
        conn,
        tables=_ENSEMBLE_CANDIDATE_MEMBER_TABLES,
    )
    if not tables:
        return {}
    source = " UNION ".join(
        "SELECT station_id,target_local_date FROM " + table
        + " WHERE authority_scope='PRODUCTION_NO_LIVE_CANDIDATE'"
        for table in tables
    )

    rows = conn.execute(
        "WITH candidate_scopes AS ("
        + source
        + "), matched AS ("
        "SELECT DISTINCT m.station_id,t.local_date,t.content_sha256 "
        "FROM candidate_scopes m "
        "JOIN calibration_station_daily_high_truth t "
        "ON t.station_id=m.station_id "
        "AND t.local_date=m.target_local_date "
        "AND t.source_lane IN " + FORMAL_TRUTH_LANES_SQL + " "
        "AND t.qc_status='ACCEPTED'"
        "), selected_stations AS ("
        "SELECT DISTINCT station_id FROM matched "
        "ORDER BY station_id LIMIT ?"
        "), ranked AS ("
        "SELECT matched.station_id,matched.local_date,"
        "matched.content_sha256,"
        "ROW_NUMBER() OVER ("
        "PARTITION BY matched.station_id "
        "ORDER BY matched.local_date DESC,matched.content_sha256"
        ") AS truth_rank "
        "FROM matched JOIN selected_stations "
        "ON selected_stations.station_id=matched.station_id"
        ") "
        "SELECT station_id,local_date,content_sha256 "
        "FROM ranked WHERE truth_rank<=? "
        "ORDER BY station_id,local_date,content_sha256",
        (max_stations, max_cases_per_station),
    ).fetchall()
    identities_by_station: dict[str, list[dict[str, str]]] = {}
    for station_id, local_date, truth_sha in rows:
        station = str(station_id)
        identities_by_station.setdefault(station, []).append({
            "local_date": str(local_date),
            "truth_content_sha256": str(truth_sha),
        })
    return {
        station: content_sha256({
            "station_id": station,
            "accepted_truths": identities,
        })
        for station, identities in sorted(
            identities_by_station.items()
        )
    }


# The P0 inbox is read, merged and rewritten by two threads of this process:
# the production cycle's replay compile and the forecast lane's arrival
# drain.  The writer turn used to keep those from overlapping; now that the
# forecast lane runs beside production, the merge is serialised here instead,
# so neither thread rewrites the file over packets the other just added.
_P0_INBOX_MERGE_LOCK = threading.Lock()


def _upsert_native_p0_inbox(
    path: Path,
    *,
    compiled_packets: Sequence[Mapping[str, Any]],
    generated_at_utc: str,
) -> dict[str, Any]:
    """Merge bounded compiled native P0 packets by station-day identity."""

    with _P0_INBOX_MERGE_LOCK:
        return _upsert_native_p0_inbox_unlocked(
            path,
            compiled_packets=compiled_packets,
            generated_at_utc=generated_at_utc,
        )


def _upsert_native_p0_inbox_unlocked(
    path: Path,
    *,
    compiled_packets: Sequence[Mapping[str, Any]],
    generated_at_utc: str,
) -> dict[str, Any]:
    # This is a transient handoff inbox, not a historical evidence store.
    # Retaining an expired packet makes a later, otherwise admissible
    # station-day P0 fail as a whole.  Official native packets and the
    # separately-labelled, strict-OOS republisher fallback are retained.
    # Legacy/unknown minimal packets without an envelope remain usable in
    # no-op replay tests; ``materialize_resident_p0`` is the strict validator
    # before SSOT writes.  The fallback never inherits native authority.
    generated_at = datetime.fromisoformat(
        generated_at_utc.replace("Z", "+00:00")
    ).astimezone(timezone.utc)

    def retain_existing(row: Mapping[str, Any]) -> bool:
        packet = row.get("packet")
        if not isinstance(packet, Mapping):
            return False
        envelope = packet.get("native_probability_envelope")
        if not isinstance(envelope, Mapping):
            return True
        lineage = envelope.get("lineage")
        if not isinstance(lineage, Mapping):
            return False
        provider = str(lineage.get("native_transport_provider") or "")
        if provider in {
            "OFFICIAL_NATIVE_SAME_CYCLE_SNAPSHOT",
            "OFFICIAL_NATIVE_MIXED_CYCLE_SNAPSHOT",
        }:
            pass
        elif (
            provider == "OPEN_METEO"
            and str(
                lineage.get("aggregator_fallback_p0_eligible") or ""
            ).lower() == "true"
            and str(
                lineage.get("republisher_fallback_p0_eligible") or ""
            ).lower() == "true"
            and str(lineage.get("transport_lineage_class") or "")
            == "aggregator_republisher"
            and str(
                lineage.get("native_arrival_index_eligible") or ""
            ).lower() == "false"
            and str(lineage.get("native_formal_p0_eligible") or "")
            .lower() == "false"
        ):
            pass
        else:
            return False
        fresh_until_raw = str(envelope.get("fresh_until_utc") or "")
        if not fresh_until_raw:
            # Test/replay fixtures without a real envelope timestamp remain
            # subject to the downstream validator.  Real compiled packets
            # always carry this field and are pruned above on expiry.
            return True
        try:
            fresh_until = datetime.fromisoformat(
                fresh_until_raw.replace("Z", "+00:00")
            ).astimezone(timezone.utc)
        except (TypeError, ValueError):
            return False
        return fresh_until > generated_at

    existing_rows: list[dict[str, Any]] = []
    if path.is_file():
        existing = load_bounded_json(path)
        identity = {
            key: value
            for key, value in existing.items()
            if key != "content_sha256"
        }
        if (
            existing.get("schema")
            != "bayes_basket_target_p0_inbox_v1"
            or not isinstance(existing.get("packets"), list)
            or str(existing.get("content_sha256") or "")
            != content_sha256(identity)
        ):
            raise ContractError("native_p0_inbox_invalid")
        existing_rows = [
            dict(item)
            for item in existing["packets"]
            if isinstance(item, Mapping)
            and item.get("source_class")
            == "calibrated_native_cross_ensemble"
            and retain_existing(item)
        ]
    merged_by_scope = {
        (
            str((row.get("packet") or {}).get("station_id") or "")
            .strip()
            .upper(),
            str((row.get("packet") or {}).get("event_date") or ""),
        ): row
        for row in existing_rows
    }
    def source_priority(row: Mapping[str, Any]) -> int:
        packet = row.get("packet")
        if not isinstance(packet, Mapping):
            return 0
        envelope = packet.get("native_probability_envelope")
        if not isinstance(envelope, Mapping):
            # Keep the deliberately minimal legacy handoff fixture usable;
            # real packets always carry an envelope and are validated below
            # before any SSOT write.
            return 2 if "native_probability_envelope" not in packet else 0
        lineage = envelope.get("lineage")
        if not isinstance(lineage, Mapping):
            return 0
        provider = lineage.get("native_transport_provider")
        if provider in {
            "OFFICIAL_NATIVE_SAME_CYCLE_SNAPSHOT",
            "OFFICIAL_NATIVE_MIXED_CYCLE_SNAPSHOT",
        }:
            return 2
        if (
            provider == "OPEN_METEO"
            and str(
                lineage.get("aggregator_fallback_p0_eligible") or ""
            ).lower() == "true"
            and str(
                lineage.get("republisher_fallback_p0_eligible") or ""
            ).lower() == "true"
            and str(lineage.get("transport_lineage_class") or "")
            == "aggregator_republisher"
            and str(
                lineage.get("native_arrival_index_eligible") or "")
            .lower() == "false"
            and str(lineage.get("native_formal_p0_eligible") or "")
            .lower() == "false"
        ):
            return 1
        return 0

    accepted_count = 0
    for compiled in compiled_packets:
        if compiled.get("schema") != (
            "calibrated_native_cross_ensemble_p0_packet_v1"
        ):
            continue
        packet = compiled.get("packet")
        if not isinstance(packet, Mapping):
            raise ContractError("native_p0_compiled_packet_invalid")
        scope = (
            str(packet.get("station_id") or "").strip().upper(),
            str(packet.get("event_date") or ""),
        )
        if not all(scope):
            raise ContractError("native_p0_compiled_scope_missing")
        candidate_row = {
            "source_class": compiled["source_class"],
            "packet_content_sha256": compiled[
                "packet_content_sha256"
            ],
            "packet": dict(packet),
        }
        if source_priority(candidate_row) == 0:
            # Aggregator/re-publisher data remains excluded unless the
            # compiler attached an activated strict-OOS fallback proof.  Such
            # a packet is still lower authority than official native data and
            # is never admitted to hard-NO/P1 or native-arrival indexes.
            continue
        current = merged_by_scope.get(scope)

        def _decided_at(row: Mapping[str, Any]) -> str:
            envelope = (row.get("packet") or {}).get(
                "native_probability_envelope"
            )
            if not isinstance(envelope, Mapping):
                return ""
            return str(envelope.get("decision_at_utc") or "")

        if (
            current is None
            or source_priority(candidate_row) > source_priority(current)
            or (
                # SAME and MIXED are one official authority tier.  Within the
                # tier the newer decision wins: a replayed older packet
                # carries an older decision instant and stays out, which is
                # all the previous keep-the-incumbent tie rule was protecting
                # -- but that rule also discarded genuinely newer compiles,
                # so a P0-M confirm could never supersede the P0 it confirms.
                source_priority(candidate_row)
                == source_priority(current)
                and _decided_at(candidate_row) > _decided_at(current)
            )
        ):
            merged_by_scope[scope] = candidate_row
        accepted_count += 1
    rows = [
        merged_by_scope[key]
        for key in sorted(
            merged_by_scope,
            key=lambda item: (item[1], item[0]),
        )
    ][-256:]
    inbox_identity = {
        "schema": "bayes_basket_target_p0_inbox_v1",
        "generated_at_utc": generated_at_utc,
        "packets": rows,
    }
    wrote = write_bounded_json_if_changed(path, {
        **inbox_identity,
        "content_sha256": content_sha256(inbox_identity),
    })
    return {
        "state": "COMMITTED" if accepted_count else "NO_COMPILED_P0",
        "accepted_count": accepted_count,
        "packet_count": len(rows),
        "wrote": wrote,
        "calls_order_gateway": False,
        "orders_submitted": 0,
        "live_submit_authorized": False,
    }


def _load_native_forward_inbox(
    path: Path,
    *,
    error_code: str,
) -> list[Mapping[str, Any]]:
    # One verification per file, not per read: the NWP rotation reads this
    # inbox two or three times a call, sixty-odd calls a poll (see
    # ``load_verified_file_cached``).  The error code is the caller's name for
    # a failure, and failures are never stored, so it stays out of the key.
    def _verified(resolved: Path) -> list[Mapping[str, Any]]:
        inbox = load_bounded_json(resolved)
        identity = {
            key: value
            for key, value in inbox.items()
            if key != "content_sha256"
        }
        if (
            inbox.get("schema") != "native_ensemble_forward_inbox_v1"
            or not isinstance(inbox.get("packets"), list)
            or len(inbox["packets"]) > 256
            or str(inbox.get("content_sha256") or "")
            != content_sha256(identity)
        ):
            raise ContractError(error_code)
        return [
            packet
            for packet in inbox["packets"]
            if isinstance(packet, Mapping)
        ]

    return load_verified_file_cached(
        path, _verified, namespace="native_forward_inbox_v1"
    )


def _p0_preselection_scope_version(market_snapshot: Mapping[str, Any]) -> str:
    """The inventory/order-state version for one preselection quote.

    Keyed to the quote, because the evidence it describes is keyed to the
    quote: a later quote observes a later instant and is a different row.
    A version shared across quotes made the reader's lookup ambiguous by
    construction.
    """

    base = str(market_snapshot.get("inventory_version") or "").strip()
    quote_version = str(market_snapshot.get("quote_version") or "").strip()
    if not quote_version:
        return base
    return f"{base}:{quote_version}" if base else quote_version


def _forward_quote_sequence(
    conn: sqlite3.Connection,
    quote_raw: dict[str, Any],
) -> int:
    """Give the forward quote its place in the scope's snapshot sequence.

    ``compile_p0_market_evidence`` stamps every forward quote ``sequence=0``.
    That held while the forward lane was the only writer of a not-started
    day: the evidence bundle refuses a quote whose sequence is below the
    latest row for the scope, and every forward row was 0, so 0 never fell
    behind 0.  Since 2026-09-02 18:27Z the resident ingress persists listed
    days too (05ab1abc..c2615579), numbering them 1, 2, 3 ..., and from the
    first such row every forward insert for the scope was refused as
    ``official_ws_sequence_rewind``.  Measured 2026-09-05: the forward lane
    wrote 2,000-2,900 snapshot rows per event day through 2026-09-03 and
    31, 31 and 60 for the three days after; SAEZ's 2026-09-06 plan compiled
    ``ready_no_live`` on every cycle from 20:19Z on 09-04 and was never
    opened, because the evidence the stage open binds to could not be
    written.  With the live flag armed that is the whole order flow: no
    stage open, no chain, no ticket for P1 (charter 74), no intent, no
    order.

    Same rule the resident ingress applies to its own rows
    (``market_ingress._next_sequence`` / ``_reuse_sequence_for_replay``): a
    quote already persisted under this snapshot id keeps the sequence it was
    given -- the bundle deduplicates by snapshot id and rejects a second row
    whose bytes disagree, and the sequence is in the bytes -- and a new one
    takes the next number for the scope.  Assigned on the writer connection
    at insert time, so it cannot go stale between compile and write.
    """

    snapshot_id = str(quote_raw.get("snapshot_id") or "")
    row = conn.execute(
        "SELECT sequence FROM basket_official_ws_snapshot WHERE snapshot_id=?",
        (snapshot_id,),
    ).fetchone()
    if row is not None:
        sequence = int(row[0])
    else:
        row = conn.execute(
            "SELECT COALESCE(MAX(sequence),-1)+1 "
            "FROM basket_official_ws_snapshot "
            "WHERE station_id=? AND event_date=?",
            (
                str(quote_raw.get("station_id") or ""),
                str(quote_raw.get("event_date") or ""),
            ),
        ).fetchone()
        sequence = max(0, int(row[0] or 0))
    quote_raw["sequence"] = sequence
    return sequence


def _forward_market_evidence_rows(
    market_snapshot: Mapping[str, Any],
    *,
    quote_freshness_policy_sha256: str,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    """Build the quote/inventory/order-state trio for one forward scope.

    A forward day has no resident ingress writing this trio, so the
    preselection path writes it itself.  One builder, because the bundle is
    deduplicated by snapshot id and refuses a second row whose content hash
    disagrees: a scope that recorded its book on a refused compile and then
    compiled cleanly against the same quote must produce the same bytes, or
    the successful pass would fail on its own earlier evidence.
    """

    quote_raw = dict(market_snapshot)
    quote_raw["quote_freshness_policy_sha256"] = quote_freshness_policy_sha256
    buckets = tuple(market_snapshot.get("buckets") or ())
    zero_by_bucket = {
        str(entry.get("bucket") or ""): 0.0
        for entry in buckets
    }
    # The inventory the snapshot was priced on (charter 83: the ledger's
    # settled live fills, read by the preselection builder).  Until
    # 2026-09-05 this row was written held-zero whatever the ledger said,
    # so a forward day that had filled two legs of three compiled its next
    # decision against nothing.  The empty case keeps its exact bytes: the
    # bundle deduplicates by snapshot id and refuses a second row whose
    # content disagrees, and a book unchanged across this change must still
    # match the row it already wrote.
    filled_by_bucket = {
        str(entry.get("bucket") or ""): float(entry.get("filled_shares") or 0.0)
        for entry in buckets
    }
    filled_cost_by_bucket = {
        str(entry.get("bucket") or ""): float(
            entry.get("filled_cost_usdc") or 0.0
        )
        for entry in buckets
    }
    holds_anything = any(value > 1e-9 for value in filled_by_bucket.values())
    inventory_json = (
        {
            "filled_by_bucket": filled_by_bucket,
            "filled_cost_by_bucket": filled_cost_by_bucket,
            "source": "target_reconciliation_ledger_fills",
            "ledger_holdings_sha256": str(
                market_snapshot.get("ledger_holdings_sha256") or ""
            ),
        }
        if holds_anything
        else {"filled_by_bucket": zero_by_bucket}
    )
    evidence_scope = {
        "station_id": str(market_snapshot.get("station_id") or ""),
        "event_date": str(market_snapshot.get("event_date") or ""),
        "settlement_timezone": str(
            market_snapshot.get("settlement_timezone") or ""
        ),
        "observed_at": str(market_snapshot.get("quote_observed_at") or ""),
    }
    inventory_raw = {
        **evidence_scope,
        "inventory_snapshot_id": (
            "p0presel-inv-"
            + str(market_snapshot.get("quote_version") or "")
        ),
        # The snapshot id already varies per quote -- a new quote is a new
        # observation, with its own observed_at -- but the version did not,
        # so every quote added a row that the reader, which resolves by
        # (station, day, version), then found two of.  That is the ambiguity
        # that blocked eleven of thirteen forward scopes; the version has to
        # move with the observation it names.
        "inventory_version": _p0_preselection_scope_version(market_snapshot),
        "complete": 1,
        "inventory_json": inventory_json,
    }
    order_state_raw = {
        **evidence_scope,
        "order_state_snapshot_id": (
            "p0presel-ord-"
            + str(market_snapshot.get("quote_version") or "")
        ),
        # Same reasoning as the inventory version above: keyed to the quote
        # it observes.
        "order_state_version": _p0_preselection_scope_version(
            market_snapshot
        ),
        "known": 1,
        "order_state_json": {
            "pending_by_bucket": zero_by_bucket,
        },
    }
    # The quote row names the version the reader will look the inventory up
    # by, so it has to carry the same quote-keyed value the rows were written
    # under, not the shared one it was copied with.
    quote_raw["inventory_version"] = _p0_preselection_scope_version(
        market_snapshot
    )
    quote_raw["order_state_version"] = _p0_preselection_scope_version(
        market_snapshot
    )
    return quote_raw, inventory_raw, order_state_raw


def _resolve_target_remaining_budget() -> float:
    """Resolve only the target-owned no-live budget.

    An explicit target environment override is allowed for a controlled
    rehearsal.  With no override, only the target-owned runtime config is
    authoritative.  The resident daemon config and activation ``basket``
    fields are intentionally not fallback sources: doing so could borrow a
    live-line bankroll into the target lane.
    """

    # One resolver for the dial (``runtime_config``), shared with the account
    # read in ``production_io``: the override, then the config the mode
    # selects.  After the go-live migration this still read the no-live
    # file; the two happened to carry the same number, which is the only
    # reason it went unnoticed -- a live system taking its budget from a
    # contract that says live_submit_authorized: false is wrong even on the
    # day the numbers agree.
    from .runtime_config import resolve_target_remaining_budget  # noqa: PLC0415

    return resolve_target_remaining_budget(execution_mode=PRODUCTION_EXECUTION_MODE)


def _group_scope_manifests_by_day_state(
    manifests: Sequence[Mapping[str, Any]],
) -> "list[tuple[str, list[dict[str, Any]]]]":
    """Split one event day's manifests by the day state each scope is in.

    ``event_day_state`` reads like a property of the event day and is not:
    it is a property of the day AT A STATION, and the fleet spans every
    timezone.  So for the hours around midnight one event date is genuinely
    ``open`` at some stations and ``not_started`` at others -- measured
    2026-08-31T23:45Z, 2026-09-01 was open at 32 stations and not started at
    16 -- and a merge that demanded one state for the whole day fail-closed
    the entire cycle every night.

    Merging across those two is not an option: the merged document carries a
    single ``event_day_state`` and downstream reads it, so one group's
    stations would be described by the other's state.  They are separate
    ingress passes over the same day, in a stable order so a cycle's work is
    reproducible.
    """

    grouped: dict[str, list[dict[str, Any]]] = {}
    for item in manifests:
        if not isinstance(item, Mapping):
            continue
        grouped.setdefault(
            str(item.get("event_day_state") or ""), []
        ).append(dict(item))
    # Open first: it is the day that can still trade, and a cycle that runs
    # out of lease should have spent it there rather than on a day that has
    # not begun.
    return sorted(
        grouped.items(),
        key=lambda entry: (entry[0] != "open", entry[0]),
    )


def _merge_scope_manifests(
    manifests: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Fuse one event day's scope manifests into a single ingress document.

    The ingress has always taken a station list; what forced one station per
    cycle was this bridge handing it one scope at a time.  Merging is a
    union of the per-token books and registries with the station allowlist
    widened -- no quote is fetched, recomputed or reinterpreted, so a station
    reads exactly as it would have on its own turn.

    Refuses to merge across event days.  Downstream reads a single
    ``event_date`` off the merged document and would silently attribute one
    day's books to another; a mixed set is a programming error here, not
    something to paper over.
    """

    usable = [dict(item) for item in manifests if isinstance(item, Mapping)]
    if not usable:
        raise ContractError("resident_target_ws_sweep_manifest_empty")
    if len(usable) == 1:
        return usable[0]
    event_dates = {str(item.get("event_date") or "") for item in usable}
    day_states = {str(item.get("event_day_state") or "") for item in usable}
    if len(event_dates) != 1 or len(day_states) != 1:
        raise ContractError("resident_target_ws_sweep_scope_not_one_day")

    base = dict(usable[0])
    stations: list[str] = []
    quotes: dict[str, Any] = {}
    side_state: dict[str, Any] = {}
    markets: dict[str, Any] = {}
    scope_keys: list[str] = []
    for item in usable:
        for station in _manifest_station_allowlist(item):
            if station not in stations:
                stations.append(station)
        scope_keys.append(str(item.get("scope_key") or ""))
        for key, value in (item.get("quotes_by_token") or {}).items():
            quotes[str(key)] = value
        for key, value in (
            item.get("quote_side_state_by_token") or {}
        ).items():
            side_state[str(key)] = value
        registry = item.get("market_registry_scope")
        if isinstance(registry, Mapping):
            for key, value in (
                registry.get("markets_by_token") or {}
            ).items():
                markets[str(key)] = value

    base["station_scope"] = {
        **(base.get("station_scope") or {}),
        "mode": "allowlist",
        "station_ids": sorted(stations),
    }
    base["quotes_by_token"] = quotes
    base["quote_side_state_by_token"] = side_state
    base["market_registry_scope"] = {
        **(base.get("market_registry_scope") or {}),
        "markets_by_token": markets,
    }
    base["subscribed_token_count"] = len(quotes)
    base["materialized_token_count"] = len(quotes)
    base["received_book_token_count"] = len(quotes)
    # The merged document is a different thing from any scope it came from,
    # so it says so rather than wearing one member's identity.
    base["scope_key"] = "SWEEP|" + str(base.get("event_date") or "")
    base["swept_scope_keys"] = sorted(key for key in scope_keys if key)
    base.pop("target_timezone", None)
    base.pop("snapshot_sha256", None)
    base["snapshot_sha256"] = content_sha256({
        key: value
        for key, value in base.items()
        if key != "snapshot_sha256"
    })
    return base


#: Scope discovery's probability read.  Bounded below by event date; see
#: ``_decision_scopes`` and ``_decision_scope_event_date_floor``.
DECISION_SCOPE_PROBABILITY_SQL = (
    "SELECT DISTINCT station_id,event_date,settlement_timezone,{stage_projection}"
    " FROM basket_probability_envelope"
    " WHERE station_id<>'' AND event_date<>''"
    " AND state='COMMITTED' AND event_date>=?"
)
#: Days before the decision clock's UTC date that scope discovery still reads.
DECISION_SCOPE_EVENT_DATE_MARGIN_DAYS = 2


def _decision_scope_event_date_floor(as_of_utc: str) -> str:
    """The earliest event date that can still be open or not started."""

    try:
        clock = datetime.fromisoformat(str(as_of_utc).replace("Z", "+00:00"))
    except ValueError:
        # An unreadable clock must not narrow what is read.
        return "0000-00-00"
    if clock.tzinfo is None:
        return "0000-00-00"
    return (
        clock.astimezone(timezone.utc).date()
        - timedelta(days=DECISION_SCOPE_EVENT_DATE_MARGIN_DAYS)
    ).isoformat()


def _settlement_day_open_in_every_zone(
    event_date: str, zones: Collection[str], as_of: datetime
) -> bool:
    """Whether every named timezone still has ``event_date`` open at ``as_of``.

    The truth materializer skips a scope while ``as_of`` is before the end of
    its settlement day in the registry's timezone.  This answers the same
    comparison for every timezone the registry has ever named for the scope,
    and only says "open" when all of them agree -- a scope with no usable zone,
    or one zone saying closed, is left for the materializer to decide.
    """

    usable = [zone for zone in zones if zone]
    if not usable:
        return False
    for zone in usable:
        try:
            end = datetime.fromisoformat(
                str(settlement_day_window(event_date, zone)["target_day_end_utc"])
                .replace("Z", "+00:00")
            )
        except Exception:  # noqa: BLE001 - undecidable here; the materializer decides
            return False
        if as_of >= end:
            return False
    return True


def _scope_manifest_station_day(item: Mapping[str, Any]) -> tuple[str, str]:
    """The ``(STATION, event_date)`` one scope manifest describes.

    Read off the manifest's own scope key and station allowlist.  The
    publisher's scope manifests carry no ``station_id`` field, so a reader
    that asked for one got "" on every live manifest: the listing pass's
    station set was empty on every cycle it ran.
    """

    day = str(item.get("event_date") or "").strip()
    key = str(item.get("scope_key") or "")
    station = key.split("|", 1)[0].strip().upper() if "|" in key else ""
    if not station or station == "SWEEP":
        try:
            stations = _manifest_station_allowlist(item)
        except RuntimeError:
            stations = ()
        station = stations[0] if len(stations) == 1 else ""
    return station, day


def _admitted_evidence_groups(
    manifests: Sequence[Mapping[str, Any]],
    *,
    listing_scope_keys: Collection[str],
) -> "tuple[list[tuple[str, bool, list[dict[str, Any]]]], list[str]]":
    """One event day's manifests as ingress passes, each under its own view.

    The one date-admission rule for the main pass, the listing pass and the
    mid-loop refresh.  Each ``(day_state, group)`` of
    ``_group_scope_manifests_by_day_state`` becomes one pass, and the
    registry view it reads is decided by the state the group is actually in:

    - a group whose day has begun (``open``, ``closed``) reads the
      started-day registry, as every started-day read always has;
    - a ``not_started`` group reads the listed-day registry
      (``listing_day_pass``) -- but only for the station-days charter 48
      admits as listing scopes; a not-started scope without that
      authorization has no registry view to read and is not passed at all.

    The view used to be chosen by call site, not by group.  The main pass
    never passed ``listing_day_pass``, so when the rotation selected a listed
    scope as the cycle's lead -- which charter 85 does for any scope holding
    a position -- its group read the started-day registry, found nothing for
    a day that had not begun, and fail-closed the cycle with
    ``no_registry_scope``: measured 2026-09-13, 44 listed scopes of
    2026-09-14 whose registry held 11 tradable buckets each.  The refresh
    chose it by date, which lent the listed view to every station of a date
    including ones already open, and the listed view is not harmless there:
    it admits an empty book as a bucket nobody has quoted yet, which on a
    started day is the ``official_ws_book_empty`` defect.

    Returns the admitted passes in the grouping's order and the
    ``STATION|DATE`` keys refused for want of listing authorization.
    """

    admitted_keys = {
        str(key or "").strip().upper()
        for key in listing_scope_keys
        if str(key or "").strip()
    }
    passes: list[tuple[str, bool, list[dict[str, Any]]]] = []
    refused: list[str] = []
    for day_state, group in _group_scope_manifests_by_day_state(manifests):
        if day_state != "not_started":
            passes.append((day_state, False, group))
            continue
        listed: list[dict[str, Any]] = []
        for item in group:
            station, day = _scope_manifest_station_day(item)
            key = f"{station}|{day}".upper()
            if station and day and key in admitted_keys:
                listed.append(item)
            else:
                refused.append(f"{station}|{day}")
        if listed:
            passes.append((day_state, True, listed))
    return passes, refused


def _confine_blocked_scopes(
    scopes: Sequence[tuple[str, str]],
    exc: BaseException,
) -> list[tuple[str, str]]:
    """The open scopes a cycle-level exception may be recorded against.

    An exception raised by the evidence passes carries the station-days of
    the groups that failed (``EVIDENCE_GROUP_SCOPES_ATTR``); the blocker is
    theirs and nobody else's.  Recording it against every open scope is how
    one listed day's refusal was written into the ledger of forty-four
    stations that were never in the pass.  Any other exception keeps the
    fleet-wide record it has always had.
    """

    confined = getattr(exc, EVIDENCE_GROUP_SCOPES_ATTR, None)
    if confined is None:
        return list(scopes)
    allowed = {
        (str(station).upper(), str(day))
        for station, day in confined
    }
    return [
        scope
        for scope in scopes
        if (str(scope[0]).upper(), str(scope[1])) in allowed
    ]


def _compiled_listing_rows(
    listing_rows: Sequence[tuple[str, str]],
    *,
    serve_listing: bool,
    lead_listing_scopes: Collection[tuple[str, str]],
) -> list[tuple[str, str]]:
    """The listed scopes this cycle compiles.

    All of them on the listed days' turn; otherwise only the listed scopes
    this cycle's own lead pass materialized.  A listed scope's evidence is
    written on its day's turn, and compiling one against last cycle's books
    manufactures ``production_quote_expired`` rather than observing it --
    but when the rotation leads with a listed scope (charter 85 does, for
    one holding a position) the lead pass IS this cycle's evidence, and
    leaving its scopes to the other turn compiled nothing at all: the open
    rows are the listed date's open stations, which the lead group does not
    contain.
    """

    if serve_listing:
        return list(listing_rows)
    lead = {
        (str(station).upper(), str(day)) for station, day in lead_listing_scopes
    }
    return [
        scope for scope in listing_rows
        if (str(scope[0]).upper(), str(scope[1])) in lead
    ]


#: Set on an evidence-pass exception to the ``(STATION, DATE)`` pairs of the
#: groups that raised it; read by ``_confine_blocked_scopes``.
EVIDENCE_GROUP_SCOPES_ATTR = "evidence_group_scopes"


def _manifest_station_allowlist(root: Mapping[str, Any]) -> tuple[str, ...]:
    """Preserve an explicit one-shot WS station scope during materialization."""

    raw = root.get("station_scope")
    if not isinstance(raw, Mapping) or str(raw.get("mode") or "") != "allowlist":
        return ()
    values = raw.get("station_ids")
    if not isinstance(values, list):
        raise RuntimeError("target_market_manifest_station_allowlist_invalid")
    stations = tuple(sorted({
        str(value or "").strip().upper()
        for value in values
        if str(value or "").strip()
    }))
    if not stations:
        raise RuntimeError("target_market_manifest_station_allowlist_empty")
    return stations


def _manifest_content_sha_matches(value: Mapping[str, Any]) -> bool:
    supplied = str(value.get("snapshot_sha256") or "").strip()
    return bool(supplied) and supplied == content_sha256({
        key: item
        for key, item in value.items()
        if key != "snapshot_sha256"
    })


def _active_forward_scopes(path: Path, *, horizon: date) -> set[tuple[str, str]]:
    """Return the still-open (station, event_date) scopes held in one inbox."""

    if not path.is_file():
        return set()
    try:
        root = load_bounded_json(path)
    except Exception:
        return set()
    if not isinstance(root, Mapping) or not isinstance(root.get("packets"), list):
        return set()
    scopes: set[tuple[str, str]] = set()
    for packet in root["packets"]:
        if not isinstance(packet, Mapping):
            continue
        event_date = str(packet.get("event_date") or "").strip()
        parsed = _event_date_or_none(event_date)
        if parsed is not None and parsed < horizon:
            continue
        station_id = str(packet.get("station_id") or "").strip().upper()
        if station_id and event_date:
            scopes.add((station_id, event_date))
    return scopes


def _active_registry_scopes(path: Path, *, horizon: date) -> set[tuple[str, str]]:
    """Return the still-open (station, event_date) scopes the market lists.

    The forward market registry is the authority on which scopes exist at all,
    so it is the correct bound on the official inbox.  Deriving that bound from
    another inbox instead makes coverage self-limiting: a scope missing from
    that inbox can never accept the very packet meant to cover it.
    """

    if not path.is_file():
        return set()
    try:
        root = load_bounded_json(path)
    except Exception:
        return set()
    if not isinstance(root, Mapping) or not isinstance(root.get("rows"), list):
        return set()
    scopes: set[tuple[str, str]] = set()
    for row in root["rows"]:
        if not isinstance(row, Mapping):
            continue
        event_date = str(row.get("event_date") or "").strip()
        parsed = _event_date_or_none(event_date)
        if parsed is not None and parsed < horizon:
            continue
        station_id = str(row.get("station_id") or "").strip().upper()
        if station_id and event_date:
            scopes.add((station_id, event_date))
    return scopes


def _fitted_lead_buckets(
    conn: sqlite3.Connection | None, *, as_of_utc: str
) -> set[tuple[str, str]] | None:
    """``(station, lead_bucket)`` pairs that currently have fitted weights.

    None when unavailable, which the caller reads as "do not filter".
    """

    if conn is None:
        return None
    # A skip scan over (station, kind, season, lead): one index seek per
    # distinct combination, then one seek for a valid CROSS row.  The bare
    # DISTINCT went through the artifact_kind index and read every CROSS
    # activation row -- 337 s in the first cycle after the 11:03Z restart
    # on 2026-10-02 with the machine swapping, 9 s on a quiet one.  The same
    # pairs: every key column is NOT NULL, so no row escapes the row-value
    # comparison.
    cross = "CROSS_NATIVE_ENSEMBLE"
    past_every_kind = "\U0010ffff"
    pairs: set[tuple[str, str]] = set()
    key: tuple[str, str, str, str] = ("", "", "", "")
    try:
        while True:
            row = conn.execute(
                "SELECT station_id,artifact_kind,season_bin,lead_bucket "
                "FROM calibration_native_ensemble_activation "
                "WHERE (station_id,artifact_kind,season_bin,lead_bucket)"
                ">(?,?,?,?) "
                "ORDER BY station_id,artifact_kind,season_bin,lead_bucket "
                "LIMIT 1",
                key,
            ).fetchone()
            if row is None:
                return pairs
            station, kind, season, lead = (str(value) for value in row)
            if kind < cross:
                key = (station, cross, "", "")
                continue
            if kind > cross:
                key = (station, past_every_kind, "", "")
                continue
            if conn.execute(
                "SELECT 1 FROM calibration_native_ensemble_activation "
                "WHERE station_id=? AND artifact_kind=? AND season_bin=? "
                "AND lead_bucket=? AND valid_until_utc>? "
                "AND authority_scope='PRODUCTION_NO_LIVE_ONLY' "
                "AND valid_from_utc<=? LIMIT 1",
                (station, kind, season, lead, as_of_utc, as_of_utc),
            ).fetchone() is not None:
                pairs.add((station, lead))
            key = (station, kind, season, lead)
    except Exception:
        return None


def _merge_official_native_inbox(
    inbox_path: Path,
    *,
    staging_path: Path,
    as_of_utc: str,
    allowed_scopes: set[tuple[str, str]] | None = None,
    fitted_lead_buckets: set[tuple[str, str]] | None = None,
) -> dict[str, Any]:
    """Merge a freshly captured packet into the shared official-native inbox.

    The capture command emits an inbox holding only the scope it fetched.  This
    replaces the matching ``(station_id, event_date)`` entry and keeps every
    other packet, so rotating through stations accumulates coverage instead of
    overwriting it.  Packets whose event day is certainly over everywhere are
    dropped, which bounds the file without needing a separate retention job.
    """

    staged = load_bounded_json(staging_path)
    if not isinstance(staged, Mapping):
        raise ContractError("official_native_staging_inbox_invalid")
    staged_packets = staged.get("packets")
    if not isinstance(staged_packets, list) or not staged_packets:
        raise ContractError("official_native_staging_packets_missing")

    existing_packets: list[Any] = []
    if inbox_path.is_file():
        existing = load_bounded_json(inbox_path)
        if isinstance(existing, Mapping) and isinstance(existing.get("packets"), list):
            existing_packets = list(existing["packets"])

    horizon = _utc_date(as_of_utc) - timedelta(days=1)

    def _scope_of(packet: Any) -> tuple[str, str] | None:
        if not isinstance(packet, Mapping):
            return None
        return (
            str(packet.get("station_id") or "").strip().upper(),
            str(packet.get("event_date") or "").strip(),
        )

    def _freshness_of(packet: Any) -> tuple[int, float]:
        """How fresh this packet's evidence is; unreadable counts as oldest.

        Captures run concurrently, so a slow older-run fetch can finish after
        a fresher one for the same day.  The inbox holds one packet per
        station-day, so without this the later-finishing capture would win on
        arrival order and quietly replace fresher evidence with an older run.

        Freshness is the newest run the packet carries, not its lead label.
        The label used to be a calendar day count and now is an hour bucket,
        and a comparator parsing the old spelling read every new packet as
        "oldest" -- a freshly captured 06Z packet lost the merge to the 00Z
        packet it had just superseded.  The run identity is spelling-proof and
        is the same fact the supersedence probe already compares.  Packets
        stating no run fall back to the calendar label, so republisher-era
        entries keep their old ordering among themselves.
        """

        if not isinstance(packet, Mapping):
            return (0, float("-inf"))
        run_init = _native_packet_run_init(packet)
        if run_init is not None:
            # Tier 1: a stated run always outranks a mere label.
            return (1, run_init.timestamp())
        bucket = str(packet.get("lead_bucket") or "").strip().lower()
        if bucket.startswith("d") and bucket[1:].isdigit():
            # Smaller lead = fresher; negate so bigger-is-fresher throughout.
            return (0, -float(int(bucket[1:])))
        return (0, float("-inf"))

    def _servable(packet: Any) -> bool:
        """Whether P0 has fitted weights for this packet's own training group."""

        if fitted_lead_buckets is None:
            return True
        if not isinstance(packet, Mapping):
            return False
        return (
            str(packet.get("station_id") or "").strip().upper(),
            str(packet.get("lead_bucket") or "").strip(),
        ) in fitted_lead_buckets

    staged_rank_by_scope: dict[
        tuple[str, str], tuple[bool, tuple[int, float]]
    ] = {}
    staged_best_by_scope: dict[tuple[str, str], Any] = {}
    for packet in staged_packets:
        scope = _scope_of(packet)
        if scope is None:
            continue
        rank = (_servable(packet), _freshness_of(packet))
        held = staged_rank_by_scope.get(scope)
        if held is None or rank > held:
            staged_rank_by_scope[scope] = rank
            staged_best_by_scope[scope] = packet
    merged: list[Any] = []
    pruned = 0
    superseded: set[tuple[str, str]] = set()
    # Charter 193 (三), per system: the freshness key above is the slower
    # required family, so a packet that kept ECMWF/GEFS level while one other
    # family went back (or advanced one required family while the other went
    # back to an older run than the one in service) could still win.  A
    # staged packet in which any system shared with the in-service packet
    # carries an older run is not merged; the in-service packet stays.
    refused_older_systems: dict[str, list[str]] = {}
    for packet in existing_packets:
        scope = _scope_of(packet)
        if scope is None:
            continue
        event_day = _event_date_or_none(scope[1])
        if event_day is not None and event_day < horizon:
            pruned += 1
            continue
        staged_rank = staged_rank_by_scope.get(scope)
        if staged_rank is not None:
            # Servable first, then freshest.  The lead bucket is per station
            # and derived from the run, so following a new publication cycle
            # can land a station in a training group its own history never
            # populated -- reading 06Z for the first time moved thirteen
            # American station-days into ``h12_24``, where nothing had ever
            # been fitted because 06Z had never been read.  A fresher run
            # there serves no P0 at all, so freshness cannot be the outer key.
            # The archive still ingests every run, so the empty group fills
            # and this preference dissolves on its own once weights exist.
            #
            # Ties go to the staged packet: a fresh capture of the same run is
            # a re-read whose members may have been incomplete before.
            if staged_rank >= (_servable(packet), _freshness_of(packet)):
                older = _systems_on_older_run(
                    staged_best_by_scope.get(scope), packet
                )
                # A servable packet still replaces one no P0 can be fitted
                # for, as the outer key above already rules.
                if not older or (staged_rank[0] and not _servable(packet)):
                    continue
                refused_older_systems[f"{scope[0]}|{scope[1]}"] = older
            superseded.add(scope)
        merged.append(packet)
    merged.extend(
        packet
        for packet in staged_packets
        if _scope_of(packet) not in superseded
    )
    if allowed_scopes is not None:
        # An official packet upgrades an already-active scope from republisher
        # to native evidence; it must not widen the scope set.  P0 compilation
        # caps the union of both inboxes at MAX_FORWARD_P0_STATIONS
        # (station-day pairs, not stations), so accumulating official scopes
        # the republisher never had silently pushes that union over the bound
        # and fail-closes the whole mainline.
        merged = [
            packet
            for packet in merged
            if not isinstance(packet, Mapping)
            or _scope_of(packet) is None
            or _scope_of(packet) in allowed_scopes
        ]
    merged.sort(
        key=lambda packet: (
            str((packet or {}).get("event_date") or ""),
            str((packet or {}).get("station_id") or ""),
        )
        if isinstance(packet, Mapping)
        else ("", "")
    )

    identity = {"schema": OFFICIAL_NATIVE_FORWARD_INBOX_SCHEMA, "packets": merged}
    write_bounded_json(
        inbox_path,
        {**identity, "content_sha256": content_sha256(identity)},
    )
    return {
        "packet_count": len(merged),
        "pruned": pruned,
        **(
            {"refused_older_systems": dict(sorted(refused_older_systems.items()))}
            if refused_older_systems
            else {}
        ),
    }


def _packet_runs_by_system(packet: Any) -> dict[str, datetime]:
    """Each system's run in a packet; systems with no readable run are left out."""

    if not isinstance(packet, Mapping):
        return {}
    raw = packet.get("run_init_utc_by_system")
    if not isinstance(raw, Mapping):
        return {}
    runs: dict[str, datetime] = {}
    for system_id, value in raw.items():
        try:
            parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        except (TypeError, ValueError):
            continue
        if parsed.tzinfo is None:
            continue
        runs[str(system_id)] = parsed.astimezone(timezone.utc)
    return runs


def _systems_on_older_run(staged: Any, in_service: Any) -> list[str]:
    """Systems the staged packet carries on an older run than the one in service."""

    staged_runs = _packet_runs_by_system(staged)
    service_runs = _packet_runs_by_system(in_service)
    return sorted(
        system_id
        for system_id in staged_runs.keys() & service_runs.keys()
        if staged_runs[system_id] < service_runs[system_id]
    )


def _utc_date(value: str) -> date:
    return datetime.fromisoformat(str(value).replace("Z", "+00:00")).astimezone(
        timezone.utc
    ).date()


# The two families the capture fails closed without; see
# ``_served_run_init_utc``.
REQUIRED_CAPTURE_FAMILIES = ("NOAA_GEFS_PDS_S3", "ECMWF_OPEN_DATA_S3")


def _held_run_from_capture_archives(
    capture_root: Path, event_date: str
) -> str | None:
    """The run a date holds, read from its per-lead GEFS/ECMWF archives.

    Each family's newest run across the ladder's leads, then the slower of the
    two -- the same reading ``_served_run_init_utc`` takes of a pass receipt.
    ``None`` when either family has no readable archive for the date.
    """

    newest: dict[str, datetime] = {}
    leads = sorted({int(lead) for lead, _cycle in OFFICIAL_NATIVE_LADDER_RUNGS})
    for family, prefix in (
        ("NOAA_GEFS_PDS_S3", "gefs"),
        ("ECMWF_OPEN_DATA_S3", "ecmwf"),
    ):
        for lead in leads:
            path = Path(capture_root) / f"{prefix}_{event_date}_d{lead}.json"
            if path.is_symlink() or not path.is_file():
                continue
            try:
                payload = load_bounded_json(path)
                if str(payload.get("event_date") or "") != str(event_date):
                    continue
                run = datetime.fromisoformat(
                    str(payload.get("run_init_utc") or "").replace("Z", "+00:00")
                ).astimezone(timezone.utc)
            except Exception:  # noqa: BLE001 - unreadable is absent
                continue
            if family not in newest or run > newest[family]:
                newest[family] = run
    if len(newest) != len(REQUIRED_CAPTURE_FAMILIES):
        return None
    return min(newest.values()).isoformat().replace("+00:00", "Z")


def _capture_stdout_reason(stdout: Any) -> str:
    """The reason a capture printed on its stdout receipt, if it printed one."""

    text = str(stdout or "").strip()
    if not text:
        return ""
    for line in reversed(text.splitlines()):
        line = line.strip()
        if not line.startswith("{"):
            continue
        try:
            payload = json.loads(line)
        except ValueError:
            continue
        if isinstance(payload, Mapping):
            return str(payload.get("reason") or payload.get("state") or "")[:300]
    return text[-200:]


def _served_run_init_utc(receipt: Mapping[str, Any]) -> str | None:
    """The run a capture pass actually advanced the date to.

    A pass succeeds as long as every required family produced an archive,
    and a family that cannot serve the requested cycle keeps the run it
    already holds (``_advance_or_hold``).  So "the pass exited zero" and
    "the date now holds the rung that was asked for" are different claims,
    and the worker was recording the second.  On 2026-09-03 that cost the
    whole 2026-09-04 fleet: the 12Z rung was attempted at 15:4xZ, no family
    could serve it, all four held 2026-09-03T00Z, and the date was recorded
    as holding 12Z -- which retired every rung at or below it, so the 06Z
    run that was published and working (the 2026-09-03 scopes were already
    reading it) could never be asked for.  Thirty-two station-days blocked
    on a P0 that expired at 15:29Z.

    The rung means something only to the two families the capture requires.
    ECCC and ICON resolve their own run from their per-lead contracts and
    ignore the cycle asked for, so a rung their publishers do not serve
    costs them nothing -- and reading them here would let one of them speak
    for a rung nobody fetched.  Among the two that do answer it, the date
    has advanced only as far as the slower one: at 2026-09-03T15:5xZ GEFS
    could serve 12Z and ECMWF could not (its 12Z was 404 while its 06Z was
    200), so calling the date 12Z would strand ECMWF -- 51 of the
    ensemble's members -- on 00Z until 18Z published.
    """

    by_family = receipt.get("run_init_utc_by_family")
    if not isinstance(by_family, Mapping):
        return None
    served = [
        str(by_family[family])
        for family in REQUIRED_CAPTURE_FAMILIES
        if str(by_family.get(family) or "").strip()
    ]
    return min(served) if served else None


# The ladder's rungs as (lead days, cycle hour or None for the lead's
# default), one table (charter 195): a hold rung beyond D-2 -- the charter
# 193 amendment's ECMWF D-3 18Z, should it ever ride the ladder rather than
# the follow lane -- is one more entry here, not a rewrite of the walk.
OFFICIAL_NATIVE_LADDER_RUNGS: tuple[tuple[int, int | None], ...] = (
    (0, 18),
    (0, 12),
    (0, 6),
    (0, None),
    (1, 18),
    (1, 12),
    (1, 6),
    (1, None),
    (2, None),
    (2, 12),
    (2, 6),
    (2, 0),
)
# Bounded, but wide enough to always reach a servable rung (see below).
OFFICIAL_NATIVE_LADDER_MAX_RUNGS = 4
# Charter 195 (二): a probe state older than this is not read at all.
ARRIVAL_PROBE_FRESH_SEC = 600.0
_LADDER_REQUIRED_PROBE_FAMILIES = (
    nwp_arrival_probe.ECMWF_FAMILY,
    nwp_arrival_probe.GEFS_FAMILY,
)


def _capture_text_is_network(text: Any) -> bool:
    """Charter 195 (四): whether a failure names the network, not the run."""

    value = str(text or "")
    return any(marker in value for marker in _NETWORK_FAILURE_MARKERS)


def _probe_run_publishing(
    probe_state: Mapping[str, Any] | None,
    *,
    family: str,
    run_init: datetime,
    event_date: str,
    now: datetime,
) -> bool:
    """Charter 195 (四): the probe watches this run land and it has not yet.

    True only on a positive reading -- a fresh state listing the day, the run
    inside the probe's window for the family, and no sighting yet -- so a
    probe that cannot speak never stops a ladder walk.
    """

    if family not in nwp_arrival_probe.SPECS:
        return False
    if not _arrival_probe_state_fresh(probe_state, now=now, event_date=event_date):
        return False
    spec = nwp_arrival_probe.SPECS[family]
    if int(run_init.hour) not in spec.cycles:
        return False
    age_h = (now - run_init).total_seconds() / 3600.0
    if not (
        spec.earliest_after_init_hours[int(run_init.hour)]
        <= age_h
        <= spec.give_up_after_init_hours
    ):
        return False
    key = nwp_arrival_probe.ready_key(
        family, nwp_arrival_probe.DOWNLOAD_SOURCE[family], run_init, event_date
    )
    return key not in ((probe_state or {}).get("ready") or {})


def _arrival_probe_state_fresh(
    probe_state: Mapping[str, Any] | None, *, now: datetime, event_date: str
) -> bool:
    """Whether this probe state may speak for this date at all."""

    if not isinstance(probe_state, Mapping):
        return False
    try:
        updated = datetime.fromisoformat(
            str(probe_state.get("updated_at_utc") or "").replace("Z", "+00:00")
        ).astimezone(timezone.utc)
    except ValueError:
        return False
    if abs((now - updated).total_seconds()) > ARRIVAL_PROBE_FRESH_SEC:
        return False
    listed = (probe_state.get("last_round") or {}).get("listed_dates") or ()
    return str(event_date) in {str(day) for day in listed}


def _probe_keeps_rung(
    probe_state: Mapping[str, Any],
    *,
    event_date: str,
    run_init: datetime,
    now: datetime,
) -> bool:
    """Charter 195 (二): whether a rung is worth a capture pass.

    Kept when either required family has landed this run for this date,
    or when the run is past the probe's window for a family (published long
    ago; the probe no longer asks).  Dropped when it is inside the window
    and landed for neither -- the blind try that used to fail and cost the
    date its 30-minute floor.  A state that cannot speak keeps every rung.
    """

    if not _arrival_probe_state_fresh(probe_state, now=now, event_date=event_date):
        return True
    ready = probe_state.get("ready") or {}
    for family in _LADDER_REQUIRED_PROBE_FAMILIES:
        key = nwp_arrival_probe.ready_key(
            family,
            nwp_arrival_probe.DOWNLOAD_SOURCE[family],
            run_init,
            event_date,
        )
        if key in ready:
            return True
        spec = nwp_arrival_probe.SPECS[family]
        age_h = (now - run_init).total_seconds() / 3600.0
        if age_h > spec.give_up_after_init_hours:
            return True
    return False


def _official_native_run_ladder(
    *,
    event_date: str,
    as_of_utc: str,
    probe_state: Mapping[str, Any] | None = None,
) -> list[tuple[int, int | None, datetime]]:
    """Published runs that could serve this event date, newest first.

    The scope names an event; which run serves it is decided at capture time,
    by freshness.  The lead label on the scope used to decide the run outright
    -- d1 meant "the run day's 00Z" no matter what had been published since --
    so a rotation could serve a P0 from a 30-hour-old field while a 6-hour-old
    one sat unread.  This walks the runs the lanes publish, newest first,
    skipping any not yet due by the clock; the capture's own grid-coverage
    check still rejects a run that cannot cover a station's local day, so
    falling through the ladder is exactly the "newest covering run" the
    training side already speaks (its hour buckets never cared about d-labels).
    A failure on the freshest rung is ordinary -- the newest run is the last to
    finish uploading -- and the next rung answers instead.

    Resolved before any download, so the caller can ask the cheaper question
    first: whether the newest published run is one this date already holds.

    Charter 195 (二): with a fresh arrival-probe state (``probe_state``),
    "due by the clock" becomes "on the server": a rung neither required
    family has landed for this date is dropped instead of being tried
    blind (``_probe_keeps_rung``).  Without one -- probe off, stale, or not
    listing this date -- the ladder is the clock ladder it always was.
    The rungs themselves are ``OFFICIAL_NATIVE_LADDER_RUNGS``, one table, so
    a further hold rung (a lead-3 cycle, say) is one entry there.
    """

    event_day = date.fromisoformat(event_date)
    now_dt = datetime.fromisoformat(
        as_of_utc.replace("Z", "+00:00")
    ).astimezone(timezone.utc)
    ladder: list[tuple[int, int | None, datetime]] = []
    # Six-hourly, matching what ECMWF and GEFS actually publish.  The old
    # 00Z/18Z-only rungs followed half their cycles: 06Z and 12Z published
    # daily and were never read, which capped every station-day's training
    # archive at roughly two runs when the publishers were issuing four.
    # ECCC and ICON ignore the rung's cycle -- the capture resolves their run
    # from their own per-lead contracts -- so rungs their publishers do not
    # serve cost them nothing.
    #
    # Same-day rungs past 00Z serve whoever they can still cover.  The batch
    # is all-or-nothing across its stations, and a same-day 06Z rung once
    # died whole on ``native_family_temperature_curve_point_count_invalid``
    # because the easternmost stations had two 3-hourly points left; the
    # capture now excludes structurally uncoverable stations up front
    # (deterministic from run time and settlement timezone, before any
    # download), so a 06Z/12Z/18Z rung captures the western remainder of the
    # network instead of failing on its eastern edge.  Excluded stations
    # keep their previous packet -- the freshest run that can actually cover
    # them -- and the training archive accumulates every (run, station-day)
    # pair a cycle can legitimately describe.
    # The three deep d2 rungs exist for the easternmost stations.  The lead
    # bucket is measured to the station's local day start, so the same d2 18Z
    # run that lands at 28-40h (h24_48) for Europe and the Americas is only
    # 22h (h12_24) at UTC+8 -- east of roughly UTC+3, no rung above reaches
    # the 24-48h band at all, which left ZUUU's h24_48 training bucket with
    # no ECMWF/GEFS material ever.  Publication order gives each rung its own
    # capture window: a d2 06Z run is the newest published run for a few
    # hours, is captured then, and the fresher-run filter retires it once
    # 12Z lands.  Western stations read the same captures as extra samples in
    # buckets they already serve; coverage is never at risk on a deep rung
    # (the farthest case, a UTC-8 day end from a d2 00Z init, is 56h, inside
    # every family's horizon).
    for rung_lead, rung_cycle in OFFICIAL_NATIVE_LADDER_RUNGS:
        cycle_hour = (
            {2: 18, 1: 0, 0: 0}[rung_lead]
            if rung_cycle is None else rung_cycle
        )
        run_init = datetime.combine(
            event_day - timedelta(days=rung_lead),
            dt_time(hour=cycle_hour),
            tzinfo=timezone.utc,
        )
        if run_init < now_dt:
            ladder.append((rung_lead, rung_cycle, run_init))
    ladder.sort(key=lambda rung: rung[2], reverse=True)
    if probe_state is not None:
        ladder = [
            rung for rung in ladder
            if _probe_keeps_rung(
                probe_state,
                event_date=event_date,
                run_init=rung[2],
                now=now_dt,
            )
        ]
    # Bounded, but wide enough to always reach a servable rung.  At six-hourly
    # cycles with a ~7.5h publication delay, up to two of the newest rungs are
    # initialised but not yet published, and a same-day 06Z rung can still fail
    # coverage for the easternmost stations -- three misses ahead of the rung
    # that works.  A bound of three could spend itself entirely on those misses
    # and lock a scope out of the run it can actually have.
    return ladder[:OFFICIAL_NATIVE_LADDER_MAX_RUNGS]


def _icon_run_published_for(event_date: str, *, as_of_utc: str) -> bool:
    """Whether ICON's own run for this event date should be on DWD by now.

    The lead is the calendar distance from today, which is the lead ICON's
    contract resolves a run for; a date already behind today, or beyond the
    contract, has no run to ask for.
    """

    try:
        now_dt = datetime.fromisoformat(
            as_of_utc.replace("Z", "+00:00")
        ).astimezone(timezone.utc)
        event_day = date.fromisoformat(event_date)
    except (TypeError, ValueError):
        return False
    lead = (event_day - now_dt.date()).days
    cycle_hour = ICON_RUN_CYCLE_HOUR_BY_LEAD.get(lead)
    if cycle_hour is None:
        return False
    run_init = datetime.combine(
        event_day - timedelta(days=lead),
        dt_time(hour=int(cycle_hour)),
        tzinfo=timezone.utc,
    )
    return now_dt >= run_init + timedelta(seconds=ICON_RUN_PUBLICATION_LAG_SEC)


def _live_observation_watermark(
    conn: sqlite3.Connection | None,
) -> tuple[int, int, str] | None:
    """What the observation-identity pass reads, reduced to what can move.

    ``(newest AWC report rowid, newest ASOS substitute fill rowid, UTC date)``:
    the pass exports the AWC lane and stages substitute fills (observation
    ids ``asos_p1_*``), and nothing else in the archive table.  The madis
    high-frequency lane lands a row every few minutes and is read by neither
    -- counted in, it moved the watermark on every cycle and the skip never
    fired (2026-09-15, first hour after deploy).  None when the archive
    cannot be asked, and then the pass runs, as before.
    """

    if conn is None:
        return None
    try:
        awc = conn.execute(
            "SELECT MAX(rowid) FROM reported_trajectory_observations"
            " WHERE source_lane='awc'"
        ).fetchone()[0]
        substitute = conn.execute(
            "SELECT MAX(rowid) FROM reported_trajectory_observations"
            " WHERE observation_id >= 'asos_p1_'"
            " AND observation_id < 'asos_p1`'"
        ).fetchone()[0]
    except (sqlite3.Error, AttributeError, TypeError):
        return None
    if awc is None and substitute is None:
        return None
    return (
        int(awc or 0),
        int(substitute or 0),
        datetime.now(timezone.utc).date().isoformat(),
    )


def _identity_table_rowids(
    conn: sqlite3.Connection | None,
) -> dict[str, int] | None:
    """Charter 181: the newest rowid of each table the identity export reads.

    A table the archive does not carry is recorded as 0 and contributes no
    stations; an archive that cannot be asked is None, and the pass is full.
    """

    if conn is None:
        return None
    rowids: dict[str, int] = {}
    try:
        for table, _lane in _IDENTITY_STATION_TABLES:
            present = conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
                (table,),
            ).fetchone()
            rowids[table] = (
                int(conn.execute(f"SELECT COALESCE(MAX(rowid),0) FROM {table}").fetchone()[0])
                if present is not None
                else 0
            )
    except (sqlite3.Error, AttributeError, TypeError, ValueError):
        return None
    return rowids


def _identity_changed_stations(
    conn: sqlite3.Connection | None,
    *,
    since: Mapping[str, int],
    until: Mapping[str, int],
) -> set[str] | None:
    """Stations with a row past ``since`` and at or before ``until``, in any
    table the identity export reads.  None when any table cannot be asked."""

    if conn is None:
        return None
    stations: set[str] = set()
    try:
        for table, lane in _IDENTITY_STATION_TABLES:
            low = int(since.get(table, 0))
            high = int(until.get(table, 0))
            if high <= low:
                continue
            for (station,) in conn.execute(
                f"SELECT DISTINCT station_id FROM {table}"
                f" WHERE rowid>? AND rowid<=?{lane}",
                (low, high),
            ):
                text = str(station or "").strip().upper()
                if text:
                    stations.add(text)
    except (sqlite3.Error, AttributeError, TypeError, ValueError):
        return None
    return stations


# Charter 148 (2026-09-18, operator ruling "改"): a report's P1 is written at
# the head of the cycle after it lands instead of behind the NWP arrival
# stages.  Measured before the change over 1,370 reports (09-17 12Z..09-18):
# report committed -> first P1 carrying it, median 7.7 min, p90 19.6, of
# which 2.1 min at the median (5.7 at p90) was the next cycle's own stages
# ahead of P1 -- inbox ingest, the P0 replay compile, the OOS scan and the
# OOS evaluation.  P1 reads observations strictly as of the cycle clock and
# roots on the newest committed P0-M, so it needs neither of those to run
# first; only a root that this cycle itself rebuilds does, and those scopes
# get their P1 again right after P0-M, as before.  ``PM_EARLY_P1=0``
# restores the single P1 pass inside the chain.
EARLY_P1_ENABLED = (
    os.environ.get("PM_EARLY_P1", "1").strip().lower()
    not in {"0", "off", "false", "no", ""}
)
# The fast lane (user, 2026-09-19: 「把taf和metar的抓取入库和bayes更新优先级提高
# 最高」).  A TAF the capture round landed is turned into P0-M at the very head
# of the next cycle -- before the intent reconcile and the NWP stages, which
# measured 49s and ~100s of the ~150s a new TAF used to wait inside the cycle
# -- and a P0-M that changed forces the head P1 so P1 re-roots on it at once.
# The chain's own P0-M pass still runs for roots the cycle rebuilds.
# ``PM_EARLY_P0M=0`` restores the single P0-M pass inside the chain.
EARLY_P0M_ENABLED = (
    os.environ.get("PM_EARLY_P0M", "1").strip().lower()
    not in {"0", "off", "false", "no", ""}
)


# Checkpoints between the cycle's long stages (user, 2026-09-19: 「极限压低信息
# 到来到bayes概率更新的延迟」).  The head pass waits for the next cycle, and a
# cycle is ~200s; a report or TAF that lands during one waited up to that long.
# Right before the decision loop the two passes run again for what landed
# since, and only for it -- so decisions price the freshest update:
# P1 for the stations with new reports and the scopes a new P0-M re-rooted,
# P0-M only once the chain has settled the roots (before it, a P0-M pass is
# the chain's own re-root work done twice: measured on the first deploy, a
# checkpoint right after the P0 replay compile took 340s of a 1250s cycle).
# One checkpoint, not more: each pass that has a new report pays the report
# identity pass (~20s, a subprocess) before its P1, and two checkpoints
# stretched the cycle from ~200s to 230-265s, slowing every other stage.
# Nothing new costs one file hash and one indexed read.  ``PM_FAST_LANE_
# CHECKPOINTS=0`` keeps only the head pass.
FAST_LANE_CHECKPOINTS_ENABLED = (
    os.environ.get("PM_FAST_LANE_CHECKPOINTS", "1").strip().lower()
    not in {"0", "off", "false", "no", ""}
)
# Charter 165 (2026-09-20): between the head and the pre-decision checkpoint
# a report waits through stages of 60-150s -- measured 2026-09-18..20 on 1,736
# reports, commit-to-P1 ran a 3.1 minute median with two P1 opportunities per
# ~6 minute cycle.  ``_fast_lane_checkpoint_if_due`` re-arms the checkpoint at
# the heavy stage boundaries and inside the decision loop, at most once per
# this many seconds.  Each check is a watermark read; the pass itself runs
# only for the stations with reports past the covered mark.
FAST_LANE_CHECKPOINT_MIN_INTERVAL_SEC = float(
    os.environ.get("PM_FAST_LANE_CHECKPOINT_INTERVAL_SEC", "").strip() or 45.0
)
#: Charter 257 补记三 (user ruling 2026-10-09 「提高跟单线的权重！加一个快速读取通道」):
#: the copy-follow lane at the cycle's checkpoints too -- at most every
#: COPY_FOLLOW_CHECK_INTERVAL_SEC when the fast feed brought a fill not seen
#: before, and at least every COPY_FOLLOW_IDLE_RECHECK_SEC otherwise (a take
#: whose ask was over the cap may come under it inside its window).
COPY_FOLLOW_CHECK_INTERVAL_SEC = 20.0
COPY_FOLLOW_IDLE_RECHECK_SEC = 120.0
#: ... and never more often than the last pass took.  Measured on the first
#: cycle that ran the re-armed checkpoints (2026-09-20T12:09:53Z): six of
#: them cost 403s of a 1366s cycle, one of them 242s on its own, against a
#: charter-165 acceptance of "no more than one extra batch of P1 (30-50s)".
#: A pass that costs 30 to 240 seconds cannot be re-armed every 45: the
#: interval has to scale with what the work actually costs, or the cycle
#: becomes mostly checkpoints and every OTHER stage -- including the
#: decision loop the freshness was for -- arrives later than before.
#:
#: So the wait is ``max(interval, how long the last pass took)``, measured
#: from when that pass ENDED.  At worst the lane spends half the wall clock
#: on checkpoints; when a pass is cheap, the interval governs and the P1
#: still lands within a minute of its report.
FAST_LANE_CHECKPOINT_DUTY_CYCLE = True
# How much of one cycle the mid-cycle checkpoints may take between them.
#
# The duty cycle above spaces the passes; it does not bound their sum.  On
# the first two cycles after the 2026-09-21 05:44Z restart the passes took
# 116s and 123s of 863s and 606s -- 70s for one pass after the regime stage
# -- because each one that found a new report ran the identity script and P1
# on a machine deep in swap.  In an ordinary cycle the sum is 11s (median,
# 2026-09-19).  So the checkpoints that are optional (``_if_due``) stop once
# the cycle has spent this much on them; the head of the cycle and the pass
# right before decisions are not optional and are not counted against it.  A
# report that lands after the budget is spent waits for that last pass or
# the next head, which is the behaviour before charter 165.
FAST_LANE_CHECKPOINT_CYCLE_BUDGET_SEC = float(
    os.environ.get("PM_FAST_LANE_CHECKPOINT_CYCLE_BUDGET_SEC", "").strip()
    or 90.0
)
# Charter 195 (一): a model run captured mid-cycle is compiled into P0 at the
# next fast-lane checkpoint instead of waiting for the next cycle's replay
# compile.  Measured 2026-09-14..21: capture finished -> P0 committed ran a
# 5-10 minute median, almost all of it the wait for the next cycle to reach
# ``native_p0_replay_compile``.  The checkpoint compiles only the official
# packets whose snapshot changed since the replay compile covered the inbox,
# then P0 -> P0-M -> P1 for the scopes they re-rooted, in the chain's order.
# "0" restores the pre-charter behaviour exactly (the replay compile is
# untouched either way).
FAST_LANE_NWP_P0_ENABLED = (
    os.environ.get("PM_FAST_LANE_NWP_P0", "1").strip().lower()
    not in {"0", "off", "false", "no", ""}
)
# The regime stage reads only the fresh scopes it still owes a read
# (``_regime_scopes_owed``).  "0": every fresh scope, every cycle.
REGIME_STAGE_INCREMENTAL = (
    os.environ.get("PM_REGIME_STAGE_INCREMENTAL", "1").strip().lower()
    not in {"0", "off", "false", "no"}
)


def _official_inbox_watermark(path: Any) -> tuple[int, str] | None:
    """``(size, sha256)`` of the official-native inbox bytes.

    Content, not mtime, for ``_taf_inbox_watermark``'s reason: the capture
    merge rewrites the file on passes that brought nothing new.
    """

    return _taf_inbox_watermark(path)


def _later_report_watermark(
    current: tuple[int, int, str] | None,
    candidate: tuple[int, int, str] | None,
) -> tuple[int, int, str] | None:
    """The later of two report watermarks, by their archive rowids.

    A covered mark only ever moves forward: a pass that covered more than a
    later bookkeeping step knows about must not be undone by it (a mark set
    too early re-runs P1 once, harmlessly; a mark set too late skips reports).
    """

    if current is None:
        return candidate
    if candidate is None:
        return current
    return candidate if (candidate[0], candidate[1]) >= (current[0], current[1]) else current


def _stations_with_reports_after(
    conn: sqlite3.Connection | None, covered: tuple[int, int, str] | None,
) -> set[str] | None:
    """Stations with an AWC report or a substitute fill past ``covered``.

    The same two row families ``_live_observation_watermark`` counts.  None
    when it cannot be answered, and the caller then runs the full pass.
    """

    if conn is None or covered is None:
        return None
    try:
        rows = conn.execute(
            "SELECT DISTINCT station_id FROM reported_trajectory_observations"
            " WHERE (source_lane='awc' AND rowid>?)"
            " OR (observation_id >= 'asos_p1_' AND observation_id < 'asos_p1`'"
            " AND rowid>?)",
            (int(covered[0] or 0), int(covered[1] or 0)),
        ).fetchall()
    except (sqlite3.Error, AttributeError, TypeError, ValueError):
        return None
    return {str(row[0]).strip().upper() for row in rows if row[0]}


def _scopes_for_stations(stations: set[str], *, as_of_utc: str) -> set[tuple[str, str]]:
    """Every event date a P1 could be open for, around this clock, per station.

    The P1 pass keeps only the open ones, so a superset is safe."""

    try:
        today = datetime.fromisoformat(str(as_of_utc).replace("Z", "+00:00")).date()
    except ValueError:
        today = datetime.now(timezone.utc).date()
    days = [(today + timedelta(days=offset)).isoformat() for offset in (-1, 0, 1)]
    return {(station, day) for station in stations for day in days}


def _covered_report_watermark(
    *,
    early_p1_ran: bool,
    early_watermark: tuple[int, int, str] | None,
    cycle_watermark: tuple[int, int, str] | None,
) -> tuple[int, int, str] | None:
    """The report watermark this cycle's P1 covered.

    The head P1 runs before the intent reconcile and reads its own
    watermark; a report landed after that read was seen by no P1 this cycle
    when the head pass ran (the chain then re-roots only rebuilt scopes), so
    only the head's read is covered.  Without a head pass the chain's full P1
    covers the cycle's read.
    """

    return early_watermark if early_p1_ran else cycle_watermark


def _taf_inbox_watermark(path: Any) -> tuple[int, str] | None:
    """``(size, sha256)`` of the TAF inbox's bytes: what moves when a round
    lands a bulletin.

    Content, not modification time: every capture round rewrites the file
    (``refresh_forward_taf_inbox`` ends in an unconditional write), so an
    mtime watermark would move on rounds that landed nothing and run the
    head P0-M -- ~7s -- for no new TAF.  A few MB hash in milliseconds.
    """

    try:
        data = Path(path).read_bytes()
    except (OSError, TypeError):
        return None
    return (len(data), hashlib.sha256(data).hexdigest())


def _merge_resident_p1_receipts(
    early: Mapping[str, Any],
    late: Mapping[str, Any] | None,
    *,
    late_scopes: Sequence[tuple[str, str]],
) -> dict[str, Any]:
    """One P1 receipt for a cycle that ran P1 twice.

    The downstream reads -- the fail-closed check, the correction-review
    wakeup, the status card -- see one pass's shape, so the two passes are
    folded into it: receipts and blockers concatenate, and the state is the
    same three-way rule the materializer applies to one pass.
    """

    receipts = list(early.get("receipts") or [])
    blockers = list(early.get("blockers") or [])
    if isinstance(late, Mapping):
        receipts.extend(late.get("receipts") or [])
        blockers.extend(late.get("blockers") or [])
    merged = dict(early)
    merged.update({
        "state": (
            "PARTIAL_FAIL_CLOSED"
            if blockers and receipts
            else "BLOCKED_FAIL_CLOSED"
            if blockers
            else "COMMITTED"
        ),
        "updated_scope_count": sum(
            1 for item in receipts if item.get("state") == "COMMITTED"
        ),
        "p1_update_count": sum(
            int(item.get("p1_update_count") or 0) for item in receipts
        ),
        "receipts": receipts,
        "blockers": blockers,
        "writes_target_ssot": any(
            int(item.get("p1_update_count") or 0) > 0 for item in receipts
        ),
        "early_pass": True,
        "late_pass_scopes": [f"{station}|{day}" for station, day in late_scopes],
    })
    return merged


def _native_forward_packet_is_stale(
    packet: Mapping[str, Any],
    *,
    as_of_utc: str,
    seated_system_ids: Sequence[str] | None = None,
) -> bool:
    """Whether the compiler would reject this packet for age.

    Mirrors the compiler's own window against the same evidence clock, so the
    probe and the compile agree on what is usable.  An unreadable or missing
    timestamp is not called stale here: the compiler owns that judgement and
    rejects it with a precise reason, which is more useful than this quietly
    deciding to re-download.

    ``seated_system_ids`` are the systems the station-day's latest P0 actually
    weighted.  The compiler's window runs from the newest receipt among those
    (``seated_evidence_received_at``), not from the packet's own clock, which
    is the newest receipt of any archive in it; a probe still reading the
    packet clock would call a packet fresh that the compiler refuses, and the
    scope would take the reuse path and never ask for the re-read that could
    renew it.  Measured 2026-09-06..12: 94% of the forward-day time the
    seated clock would have lost was time in which those systems' archives
    were re-read later the same day.  Without the seat set -- no committed P0
    yet, or a seated system missing from this packet -- the packet clock is
    all there is, and it is what the compiler's first guard reads too.

    The threshold is the compiler's: stale once less than a usable window is
    left, not only once the whole window has elapsed.
    """

    evidence = None
    if seated_system_ids:
        evidence = seated_evidence_received_at(
            packet.get("archive_query_at_utc_by_system"),
            seated_system_ids=list(seated_system_ids),
        )
    try:
        decision = datetime.fromisoformat(as_of_utc.replace("Z", "+00:00"))
        if evidence is None:
            captured_at = str(packet.get("received_at_utc") or "").strip()
            if not captured_at:
                return False
            evidence = datetime.fromisoformat(
                captured_at.replace("Z", "+00:00")
            )
    except (TypeError, ValueError):
        return False
    if evidence.tzinfo is None or decision.tzinfo is None:
        return False
    age_seconds = (
        decision.astimezone(timezone.utc) - evidence.astimezone(timezone.utc)
    ).total_seconds()
    return (
        NATIVE_P0_COMPILE_FRESH_SECONDS - age_seconds
        < MIN_USABLE_FRESHNESS_SECONDS
    )


def _official_inbox_packets_all_stale(
    inbox_path: Path,
    *,
    event_date: str,
    as_of_utc: str,
    station_id: str | None = None,
    seated_system_ids: Sequence[str] | None = None,
) -> bool:
    """Whether the day's official packets need re-reading before they serve.

    True only on a positive reading: the inbox has packets for the day and
    the compiler would refuse each of them for age.  No inbox, or no packet
    for the day, is not "stale" -- it is the held-run guard's ordinary case,
    and re-downloading on it would undo what that guard exists for.

    Also true when the station asking has a packet the compiler would refuse
    on its own seated clock.  Packets of one day share their archives, so
    under the packet clock they aged out together and "every one" and "the
    one asking" were the same question.  Under the seated clock they are not:
    ICON and GEM are re-read on their own lead contracts, and a station whose
    blend is those two can be unusable while its neighbours on ECMWF and GEFS
    are not.  Waiting for every packet left it dark until the others aged out
    too -- ICON+GEM was the blend in 15,815 of the 21,191 five-minute samples
    the seated clock would have lost, 2026-09-06..12.  The capture reuses archives still inside their own window,
    so asking for it re-reads only what has actually aged.
    """

    if not inbox_path.is_file():
        return False
    try:
        root = load_verified_file_cached(
            inbox_path, load_bounded_json, namespace="bounded_json"
        )
    except Exception:  # noqa: BLE001 -- the compiler names an unreadable inbox
        return False
    packets = root.get("packets") if isinstance(root, Mapping) else root
    if not isinstance(packets, list):
        return False
    same_day = [
        packet for packet in packets
        if isinstance(packet, Mapping)
        and str(packet.get("event_date") or "") == str(event_date)
    ]
    if not same_day:
        return False
    if all(
        _native_forward_packet_is_stale(packet, as_of_utc=as_of_utc)
        for packet in same_day
    ):
        return True
    station = str(station_id or "").strip().upper()
    if not station or not seated_system_ids:
        return False
    return any(
        str(packet.get("station_id") or "").strip().upper() == station
        and _native_forward_packet_is_stale(
            packet,
            as_of_utc=as_of_utc,
            seated_system_ids=seated_system_ids,
        )
        for packet in same_day
    )


def _is_republisher_daily_quota_exhausted(exc: BaseException) -> bool:
    """Whether this failure means the republisher is spent for the UTC day.

    A per-request 429 is transient and worth retrying on the next scope; a
    daily cap is not, and re-asking once per scope for the rest of the day is
    both pointless and rude to the provider.  Matched on the provider's own
    wording because the transport surfaces it verbatim and the two cases share
    a status code.
    """

    text = f"{exc}"
    return (
        "open_meteo_ensemble_rate_limited" in text
        and "daily api request limit exceeded" in text.lower()
    )


def _event_date_or_none(value: str) -> date | None:
    try:
        return date.fromisoformat(str(value).strip())
    except ValueError:
        return None


# The same two families as ``REQUIRED_CAPTURE_FAMILIES``, in the packet's
# own vocabulary.
REQUIRED_PACKET_SYSTEMS = ("NOAA_GEFS_05", "ECMWF_IFS_ENS_OPEN_PF50")


def _native_packet_run_init(packet: Mapping[str, Any]) -> datetime | None:
    """The run this packet's members came from, or None if it does not say.

    A packet that names no run is treated as unjudgeable, not as superseded
    -- that keeps an unreadable field from forcing a download.  A mixed
    packet is judged by the slower of its two required systems, for the
    reason given below; a packet naming neither falls back to its newest.
    """

    raw = packet.get("run_init_utc_by_system")
    if not isinstance(raw, Mapping) or not raw:
        return None
    parsed: dict[str, datetime] = {}
    for system_id, value in raw.items():
        try:
            parsed[str(system_id)] = datetime.fromisoformat(
                str(value).replace("Z", "+00:00")
            ).astimezone(timezone.utc)
        except (TypeError, ValueError):
            return None
    if not parsed:
        return None
    # The two required families answer the rung; the packet has advanced
    # only as far as the slower of them.  Judged by the freshest system, a
    # packet of GEFS 12Z over ECMWF 00Z read as "already on 12Z": the probe
    # reused it while ECMWF -- 51 of the members -- sat on a run six hours
    # older than the one published, and the merge would have preferred it
    # over a fresh capture that carried ECMWF 06Z.  2026-09-03T16:09Z,
    # twenty-nine 2026-09-04 scopes.  Same rule as the capture side's
    # ``_served_run_init_utc``; the two vocabularies name the same families.
    required = [
        parsed[system_id]
        for system_id in REQUIRED_PACKET_SYSTEMS
        if system_id in parsed
    ]
    return min(required) if required else max(parsed.values())


def _resident_open_event_dates(
    path: Path,
    *,
    as_of_utc: str | None = None,
) -> tuple[str, ...]:
    """Return the current open station-day dates from the resident WS handoff.

    The forward NWP inbox is intentionally append-only and may retain several
    observational dates.  A production cycle must therefore get its event-day
    scope from the resident market handoff, not from whichever dates happen to
    be present in that inbox.  This helper is deliberately conservative: a
    missing or malformed handoff yields no dates and lets the normal
    downstream fail-closed gates report the actual blocker.  Every open date a
    well-formed handoff names is returned; the result is reported, never used
    to narrow scope (see the note at the end).

    ``event_day_state`` inside the handoff is frozen at write time, so a stale
    manifest keeps advertising a day that closed long ago.  That is not a
    harmless staleness: the inferred date becomes the NWP capture event-date
    allowlist, every registry scope is filtered out, capture fail-closes, and
    without new model data there is no new P0, no new envelope, and no new
    manifest -- the handoff can never refresh itself.  Dates that are already
    closed in every timezone on earth are therefore dropped here regardless of
    what the snapshot claims, which lets the scope fall back to live registry
    discovery instead of deadlocking on a frozen date.
    """

    if not path.is_file():
        return ()
    try:
        root = load_bounded_json(path)
    except Exception:
        return ()
    if not isinstance(root, Mapping):
        return ()
    schema = str(root.get("schema") or "").strip()
    dates: set[str] = set()
    if schema == MULTI_SCOPE_WS_MANIFEST_SCHEMA:
        summaries = root.get("scopes")
        if not isinstance(summaries, list):
            return ()
        for summary in summaries:
            if not isinstance(summary, Mapping):
                continue
            if str(summary.get("event_day_state") or "").strip() != "open":
                continue
            event_date = str(summary.get("event_date") or "").strip()
            if event_date:
                dates.add(event_date)
    else:
        # Legacy resident handoffs carry one explicit target date.
        event_date = str(root.get("target_local_date") or "").strip()
        if event_date and str(root.get("event_day_state") or "open").strip() == "open":
            dates.add(event_date)
    # UTC offsets span UTC-12..UTC+14, so an event day is certainly over once
    # the clock is more than one day past it.  This needs no per-station
    # timezone -- which the handoff summaries do not carry anyway -- and only
    # ever discards dates, never invents one.
    reference = _utc_date(as_of_utc) if as_of_utc else datetime.now(timezone.utc).date()
    horizon = reference - timedelta(days=1)
    dates = {
        event_date
        for event_date in dates
        if _event_date_or_none(event_date) is None
        or _event_date_or_none(event_date) >= horizon
    }
    # Reported, never used to narrow scope.  The manifest lists scopes that
    # already have a probability, so it can only ever name dates the pipeline
    # has already processed.  Every version of "drop the manifest's date when
    # it looks stale" has been a special case that the next stale date walked
    # around: first "closed everywhere on earth", which is a day too late, then
    # "earlier than today", which does nothing when the frozen date *is* today
    # -- observed on 2026-08-08, where a manifest naming only that day held
    # capture to 16 stations while the registry already carried 45 for
    # 2026-08-09.
    #
    # The loop closes because a day with no P0 never appears in the manifest,
    # never enters the capture allowlist, never gets model data, and so never
    # gets a P0.  No filter on the manifest can open it, because the manifest
    # is downstream of the thing it would be gating.  Live registry discovery
    # is upstream and already bounded, so it owns the scope.
    return tuple(sorted(dates))


def _p0m_window_until(
    decision_at_utc: str,
    *,
    root: ProbabilityEnvelope,
    revision: ForecastRevision | None,
) -> str | None:
    """Where a TAF confirmation stops being servable, or None if it cannot start.

    No later than either thing it stands on: the P0 root's own freshness and
    the forecaster's validity period.  The window used to be the root's span
    re-measured from P0-M's decision (``_shift_window``), which was right
    while P0-M rooted on "the P0 current when the forecast arrived" -- a root
    that had, by construction, often expired.  Since the 2026-08-31 ruling
    the root is the newest P0, and the shifted window became a way for a
    confirmation to outlive its root.  Measured 2026-09-11..12 over 45
    stations: 1,320 of 1,507 P0-M checkpoints outlived their root (median
    0.52h, max 13.5h), 50 were decided after the root had already expired
    -- KAUS 09-12 minted a P0-M at 22:25Z on a P0 from 08:54Z and served it
    until 03:59Z -- and 3 outlived the TAF itself.  An identity-likelihood
    confirmation carries no model information of its own; it cannot be
    fresher than the model it confirms.

    None when the window would not clear the mint floor: the scope waits for
    the next root (or the next TAF) rather than seating a checkpoint that is
    dead on arrival.
    """

    until = str(root.fresh_until_utc)
    if revision is not None and timestamp_lt(
        str(revision.valid_until_utc), until
    ):
        until = str(revision.valid_until_utc)
    try:
        assert_mintable_freshness_window(
            decision_at_utc, until, name="resident_taf_confirmation"
        )
    except ContractError:
        return None
    return until


def _p0m_replay_decision_at(
    as_of_utc: str, *, after_decision_utc: str
) -> str:
    """The instant a confirmation rebuilt on a moved root is seated.

    Now: the forecaster spoke hours ago, and what happened now is that the
    base moved.  Except that every P0 this cycle compiled carries the cycle
    clock itself as its decision, and a stage may not share its
    predecessor's instant (``probability_decision_time_rewind``) -- so a
    confirmation of a root minted this very cycle is seated one millisecond
    after it.  Declining instead (the old ``decision_at <= predecessor``
    skip) left the rebuild to the next cycle, and in between P1 rooted on
    the bare P0 and then had to replay the whole day a second time.

    Millisecond precision, the cycle clock's own, so the stamp's byte order
    and instant order agree with the root's.
    """

    here = datetime.fromisoformat(str(as_of_utc).replace("Z", "+00:00"))
    after = datetime.fromisoformat(
        str(after_decision_utc).replace("Z", "+00:00")
    )
    if here > after:
        return str(as_of_utc)
    lifted = after.replace(
        microsecond=(after.microsecond // 1000) * 1000
    ) + timedelta(milliseconds=1)
    return lifted.astimezone(timezone.utc).isoformat(
        timespec="milliseconds"
    ).replace("+00:00", "Z")


def _p0m_scope_day_order(event_date: Any) -> str:
    """Sort token putting the furthest event day first.

    Dates are ISO, so descending lexical order is descending chronological
    order.  Inverting each character keeps the comparison a plain string sort
    while reversing its direction, which is cheaper and less error-prone than
    parsing a date per scope in a 389-scope loop.
    """

    text = str(event_date or "")
    return "".join(chr(0x10FFFD - ord(char)) for char in text)


def _live_order_number(value: Any) -> float | None:
    """The venue sends sizes and prices as strings; unreadable is None."""

    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _recovered_post_ack_for_intent(
    conn: sqlite3.Connection,
    *,
    open_orders: list[Any],
    rival: int,
    intent_id: str,
    token_id: str,
    requested_size: float,
    limit_price: float,
    order_action: str,
    idempotency_key: str,
    as_of_utc: str,
) -> dict[str, Any]:
    """The handle an UNKNOWN_POST never got, when one order is the only one.

    An intent whose POST timed out carries no exchange order id, and
    the id is the handle both the lookup and the cancel need.  Without
    it the order is live on the exchange and invisible to every lane
    here -- it is not the resting lane's business (that lane selects on
    a non-empty id), and it was not this one's either.

    This is not a guess and must not become one.  The id is adopted
    only when nothing else on the books could account for the order:

    * the enumeration for this token, already known COMPLETE, holds
      exactly ONE live order.  Two live orders and a matching price no
      longer names which;
    * this intent is the only unresolved claimant on the token
      (``rival`` is zero), the same test the position branch applies;
    * this intent has no exchange order id yet, so nothing is being
      overwritten -- an intent that has one is already the resting
      lane's and is left alone;
    * no reconciliation row anywhere already carries that id, so the
      order is not another intent's, resolved or not; and
    * side, limit price and ORIGINAL size all match the intent.
      Original size, not remaining: a partly filled order still asked
      for what the intent asked for.

    Any one of those failing returns no event and says which, because
    an intent left unresolved with a reason is a smaller failure than
    an order credited to the wrong intent.

    The event written is POST_ACK and nothing more.  It claims only that
    the order was posted and is the exchange's, which is what the
    enumeration says; it claims no fill, and the ledger does not let it
    pretend otherwise -- ``record_order_event`` deliberately leaves a
    reconciliation that was ``unknown`` still ``unknown``, because an ack
    says nothing about what the order did.  What lands is the handle.

    That is enough: ``load_resting_maker_intents`` selects on the handle
    and admits ``unknown`` alongside ``pending``, so the order becomes the
    resting lane's business in the sense that lane can act on -- ask the
    exchange about it, record the fill, or cancel it.  The ambiguity is
    cleared by the answer, which is the only thing that can clear it.
    """

    out: dict[str, Any] = {"event": None}
    if len(open_orders) != 1:
        return {**out, "reason": f"live_orders_on_token:{len(open_orders)}"}
    if rival:
        return {**out, "reason": f"rival_unresolved_intents:{rival}"}
    row = open_orders[0]
    if not isinstance(row, Mapping):
        return {**out, "reason": "live_order_unreadable"}
    order_id = str(row.get("id") or row.get("orderID") or "").strip()
    if not order_id:
        return {**out, "reason": "live_order_without_id"}
    try:
        mine = conn.execute(
            "SELECT COALESCE(exchange_order_id,'')"
            " FROM basket_target_order_reconciliations"
            " WHERE order_intent_id=?",
            (intent_id,),
        ).fetchone()
        claimed = int(conn.execute(
            "SELECT COUNT(*) FROM basket_target_order_reconciliations"
            " WHERE exchange_order_id=?",
            (order_id,),
        ).fetchone()[0] or 0)
    except sqlite3.Error as exc:
        return {"failure": f"{type(exc).__name__}:{exc}"}
    if mine is not None and str(mine[0] or "").strip():
        return {**out, "reason": "intent_already_has_an_id"}
    if claimed:
        return {**out, "reason": "order_id_already_claimed"}
    if str(row.get("side") or "").strip().upper() != str(
        order_action or ""
    ).strip().upper():
        return {**out, "reason": f"side_mismatch:{row.get('side')!r}"}
    price = _live_order_number(row.get("price"))
    size = _live_order_number(row.get("original_size"))
    if price is None or size is None:
        return {**out, "reason": "live_order_price_or_size_unreadable"}
    if abs(price - float(limit_price or 0.0)) > 1e-6:
        return {**out, "reason": f"price_mismatch:{price}"}
    if abs(size - float(requested_size or 0.0)) > VENUE_SHARE_QUANTUM:
        return {**out, "reason": f"size_mismatch:{size}"}
    # Stamped with the VENUE's creation time, not this pass's clock.  The
    # next reader of a POST_ACK is the reprice rule, which measures how
    # long the rung has been sitting from exactly this field; stamping it
    # "now" would tell that rule an order resting since yesterday had just
    # been posted, and the rule would give it a full dwell all over again.
    # The exchange is the authority on when it created the order.
    created = _live_order_number(row.get("created_at"))
    posted_at = as_of_utc
    if created and created > 0:
        # A stamp after this pass is not a creation time -- it is a unit
        # error (milliseconds read as seconds lands tens of millennia out,
        # far enough that ``fromtimestamp`` itself refuses) or a skewed
        # clock.  Taking it would make dwell negative, which clamps to
        # zero, which reads as "just posted" on every pass forever.  Fall
        # back to this pass's clock and say in the payload which was used.
        try:
            stamp = datetime.fromtimestamp(created, timezone.utc)
            asked = datetime.fromisoformat(
                str(as_of_utc).replace("Z", "+00:00")
            )
        except (OSError, OverflowError, ValueError):
            stamp = asked = None
        if stamp is not None and asked is not None and stamp <= asked:
            posted_at = stamp.isoformat(
                timespec="seconds",
            ).replace("+00:00", "Z")
    return {"event": {
        "event_type": "POST_ACK",
        "exchange_order_id": order_id,
        "observed_at": posted_at,
        "matched_size": 0.0,
        "matched_notional_usdc": 0.0,
        "event_payload": {
            "idempotency_key": idempotency_key,
            "exchange_status": str(row.get("status") or ""),
            "recovered_by": "intent_reconcile_sole_live_order",
            "token_id": token_id,
            "live_orders_on_token": 1,
            "rival_unresolved_intents": 0,
            "open_order_enumeration_complete": True,
            "matched_side": str(row.get("side") or ""),
            "matched_price": price,
            "matched_original_size": size,
            # What the venue says is already filled.  Not recorded as a
            # fill here -- POST_ACK carries none -- but written down so
            # the resting lane's first sync can be checked against what
            # was true when the handle was adopted.
            "venue_size_matched": row.get("size_matched"),
            "venue_created_at": row.get("created_at"),
            "observed_at_source": (
                "venue_created_at" if posted_at != as_of_utc else "as_of_utc"
            ),
            "recovered_at": as_of_utc,
        },
    }}



def resting_dead_buckets(
    registry_conn: sqlite3.Connection,
    *,
    station_id: str,
    event_date: str,
    running_high: float | None,
) -> tuple[tuple[str, ...], float | None]:
    """Charter 135 (二): the buckets a resting buy may no longer stand on.

    Charter 125's predicate on the same running high the selection floor
    reads, over the bucket edges the scope's latest registry snapshot
    states -- the one source of bucket widths (charter 53).  ``((), None)``
    when the floor is switched off, the day has no formal observation yet,
    or the ladder cannot be read: no cancel on a fact nobody could state.

    One reader for the worker's resting pass and the paper ledger (user
    ruling 2026-09-24: 「账本对齐」); each hands in the running high it read
    (``observed_running_high_c``).
    """

    if not observed_high_floor_enabled() or running_high is None:
        return (), None
    latest = registry_conn.execute(
        "SELECT snapshot_sha256 FROM basket_target_market_registry"
        " WHERE station_id=? AND event_date=?"
        " ORDER BY refreshed_at DESC LIMIT 1",
        (station_id, event_date),
    ).fetchone()
    if latest is None:
        return (), running_high
    rows = [
        {
            "station_id": str(row[0]),
            "event_date": str(row[1]),
            "settlement_unit": str(row[2] or ""),
            "outcome": str(row[3]),
            "registry_json": row[4],
        }
        for row in registry_conn.execute(
            "SELECT station_id,event_date,settlement_unit,outcome,"
            " registry_json FROM basket_target_market_registry"
            " WHERE snapshot_sha256=? AND station_id=? AND event_date=?",
            (latest[0], station_id, event_date),
        ).fetchall()
    ]
    from .p0_producer import (  # noqa: PLC0415
        bucket_intervals_from_registry_rows,
    )

    try:
        intervals = bucket_intervals_from_registry_rows(rows)
    except ContractError:
        return (), running_high
    ordered = sorted(
        intervals,
        key=lambda bucket: (
            float("-inf") if intervals[bucket][0] is None
            else float(intervals[bucket][0])
        ),
    )
    dead = dead_buckets_for_upper_bounds(
        ordered_buckets=ordered,
        upper_bounds={
            bucket: (
                float("inf") if intervals[bucket][1] is None
                else float(intervals[bucket][1])
            )
            for bucket in ordered
        },
        running_high_c=running_high,
    )
    return tuple(dead), running_high


def run_script_group_bounded(
    command: Sequence[str],
    *,
    cwd: str,
    timeout: float,
    env: Mapping[str, str] | None = None,
) -> subprocess.CompletedProcess:
    """Run a shell script whose deadline binds every process it starts.

    ``subprocess.run(timeout=)`` kills only the child.  A bash script's own
    children -- the Python steps of ``pr12_awc_observation_sweep.sh`` -- are
    left running, orphaned, holding the captured stdout and stderr pipes, and
    the ``communicate()`` that follows the kill waits for those pipes to
    close: the deadline returns only when the orphan finishes.  Measured
    2026-09-24: the observation-identity pass's 240 s deadline held the
    production cycle 19 minutes and more while an orphaned
    ``build_pr12_awc_observation_contract.py`` scanned archive.db on a
    contended disk, and no basket decision was written from 14:11Z.

    So the script runs as the leader of its own session and the whole group
    is killed at the deadline; ``TimeoutExpired`` is raised as before.
    """

    proc = subprocess.Popen(
        list(command),
        cwd=cwd,
        env=None if env is None else dict(env),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        start_new_session=True,
    )
    try:
        stdout, stderr = proc.communicate(timeout=timeout)
    except subprocess.TimeoutExpired:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        proc.communicate()
        raise
    return subprocess.CompletedProcess(
        proc.args, proc.returncode, stdout, stderr,
    )


def station_edge_from_plan(
    compiled: Mapping[str, Any],
    *,
    station_id: str,
    minimum_clip_usdc: float,
) -> dict[str, Any] | None:
    """What a dollar bought one station, from one compiled forward plan.

    The allocator's edge row, pure: the worker reads the station's last
    committed preselection, the paper ledger its own (user ruling
    2026-09-24: 「账本对齐」).  None when the plan bought nothing to judge.
    """

    plan = compiled.get("plan") or {}
    solution = plan.get("target_solution") or {}
    # Charter 130 (amending 84 (七)): the dollar is judged on the
    # belief the seat was judged on -- the seated window's deflated
    # partition -- not the raw envelope.  The gates read lambda(a)*p;
    # an allocator reading p would fund a station the gate refuses.
    probabilities = (
        (plan.get("basket_support_selection") or {}).get("seated") or {}
    ).get("window_probabilities") or {}
    support = plan.get("final_support") or []
    # What a dollar bought is the *increment* the plan decided --
    # its gap rows and their cost -- not the whole inventory
    # re-judged at today's prices with its sunk cost.  Read whole,
    # a completion (charter 84) looks like a losing basket: ZGSZ
    # 2026-09-06 held 30°C and 31°C bought at 0.25 and 0.43, its
    # 12:51Z plan completed 32°C for 0.95, and the whole-basket
    # reading (payout 5 a rung against 4.35 sunk-plus-new, in-window
    # mass 0.77) came out at -0.51 -- so the allocator gave the
    # station a zero quota, the next compile had zero capital, and
    # the completion it had just seated could not be offered again.
    # For a fresh basket the increment is the whole basket, and the
    # reading is unchanged.
    gap = {
        str(bucket) for bucket in (plan.get("execution_gap_support") or [])
    }
    shares = {}
    for row in plan.get("targets") or ():
        if not isinstance(row, Mapping):
            continue
        bucket = str(row.get("bucket") or "")
        quantity = float(row.get("delta_shares") or 0.0)
        if bucket and quantity > 0.0 and (not gap or bucket in gap):
            shares[bucket] = quantity
    cost = float(plan.get("total_delta_notional_usdc") or 0.0)
    if cost <= 0.0:
        cost = sum(
            float(row.get("delta_shares") or 0.0)
            * float(row.get("candidate_price") or 0.0)
            for row in (plan.get("targets") or ())
            if isinstance(row, Mapping)
            and str(row.get("bucket") or "") in shares
        )
    if not shares or not probabilities or not support or cost <= 0.0:
        return None
    scenario = {
        bucket: float(shares.get(bucket) or 0.0) - cost
        for bucket in probabilities
    }
    mean = sum(
        float(probabilities[bucket]) * value
        for bucket, value in scenario.items()
    )
    variance = sum(
        float(probabilities[bucket]) * (value - mean) ** 2
        for bucket, value in scenario.items()
    )
    return {
        "station_id": station_id,
        "edge_per_usdc": mean / cost,
        "sigma_per_usdc": (variance ** 0.5) / cost,
        "minimum_basket_usdc": minimum_clip_usdc * len(support),
    }


def portfolio_quota_from(
    *,
    stations: Sequence[str],
    inventory: Mapping[str, Any],
    edges_for: Callable[[], list[dict[str, Any]]],
    blocks_by_station: Mapping[str, str],
    policy: Mapping[str, Any],
) -> tuple[dict[str, float], dict[str, Any] | None]:
    """The forward loop's per-station quota from one book, pure.

    A breached Tier-1 bound gives every asked station nothing; no edge
    evidence or no bankroll gives no split (the caller plans those stations
    at the flat budget); otherwise the allocator splits the budget-capped
    bankroll.  ``edges_for`` is asked only when a split is possible.  The
    worker hands in the real account's inventory, the paper ledger its own
    (user ruling 2026-09-24: 「账本对齐」).  The allocation carries the edge
    rows it split on under ``_edges``.
    """

    if not inventory["new_intents_allowed"]:
        return {station: 0.0 for station in stations}, None
    # Charter 141: the bankroll is the account the inventory read
    # (budget-capped), never the pool counter.
    bankroll = float(inventory["bankroll_usdc"])
    edges = edges_for()
    if not edges or bankroll <= 0.0:
        return {}, None
    allocation = allocate_portfolio_quota(
        station_edges=edges,
        blocks_by_station=blocks_by_station,
        bankroll_usdc=bankroll,
        risk_fraction=float(policy["portfolio_risk_fraction"]),
        station_cap_fraction=float(policy["station_cap_fraction"]),
    )
    return dict(allocation["quota_usdc_by_station"]), {**allocation, "_edges": edges}


def observed_running_high_c(
    ssot_conn: sqlite3.Connection,
    canonical_source_conn: sqlite3.Connection | None,
    *,
    station_id: str,
    event_date: str,
    as_of_utc: str,
) -> float | None:
    """The day's observed running high, or None when it has none yet.

    Charter 61's fact, read once for every stage that needs it rather
    than per stage: the read goes through the same strict canonical
    loader P1 uses -- route gates, as-of, corrections -- never a
    hand-written MAX(), and only FORMAL rows count, because the bound
    is a claim about the METAR series settlement follows.

    Charter 125 gives this a second consumer.  It used to exist only
    inside the P0-M bound below, which is reached only when a TAF
    revision arrives; the selection floor needs the same number on
    every cycle, including the ones where no forecast moved.

    One reader for the worker and the paper ledger (user ruling 2026-09-24:
    「账本对齐」): both hand in the SSOT and the canonical observation store.
    """

    # Charter 178: remembered per scope until the registry could have
    # changed it -- one call per decision compile walked the scope's ~880
    # snapshot rows (145 calls, 36.3s in the first ledger-measured cycle).
    registry_rows = [
        {
            "station_id": str(row[0]),
            "event_date": str(row[1]),
            "settlement_timezone": str(row[2]),
            "source_lane": str(row[3] or ""),
        }
        for row in registry_scope_timezone_lanes(
            ssot_conn,
            station_id=station_id,
            event_date=event_date,
        )
    ]
    if not registry_rows:
        return None
    if canonical_source_conn is None:
        return None
    try:
        observations = load_resident_formal_observations(
            canonical_source_conn,
            registry_rows=registry_rows,
            station_id=station_id,
            event_date=event_date,
            as_of_utc=as_of_utc,
        )
    except ContractError:
        return None
    highs = [
        float(item["reported_temperature_c"])
        for item in observations
        if item.get("reported_temperature_c") is not None
        # SOFT_PATH carrier rows feed the path state only; a hard bound
        # is a claim about the METAR series settlement follows.
        and str(item.get("evidence_role") or "").upper() == "FORMAL"
    ]
    if not highs:
        return None
    return max(highs)


class TargetProductionWorker:
    """Resident target compiler and target-local no-live ledger writer."""

    #: Charter 181(七); set by the resident on its production worker only.
    identity_pass_state_path: Path | None = None

    def __init__(
        self,
        db_path: Path,
        *,
        commit_conn: sqlite3.Connection | None = None,
        commit_error: str | None = None,
        activation_path: Path | None = None,
        market_manifest_path: Path | None = None,
        native_oos_snapshot_path: Path | None = None,
        canonical_source_db_path: Path | None = None,
        taf_inbox_path: Path | None = None,
        p0_inbox_path: Path | None = None,
        nwp_runtime_root: Path | None = None,
        cash_phase_forward_store_path: Path | None = None,
        station_allowlist: Sequence[str] | None = None,
        event_date_allowlist: Sequence[str] | None = None,
    ) -> None:
        self.db_path = resolve_target_database(db_path)
        self.activation_path = Path(
            activation_path
            or os.environ.get("PM_TARGET_ACTIVATION", str(DEFAULT_TARGET_ACTIVATION))
        ).expanduser().resolve()
        self.market_manifest_path = resolve_target_ws_manifest(
            market_manifest_path
            or os.environ.get("PM_TARGET_MARKET_MANIFEST", str(DEFAULT_TARGET_MARKET_MANIFEST))
        )
        self.native_oos_snapshot_path = Path(
            native_oos_snapshot_path
            or os.environ.get(
                "PM_TARGET_NATIVE_OOS_SNAPSHOT_MANIFEST",
                str(DEFAULT_TARGET_NATIVE_OOS_SNAPSHOT_MANIFEST),
            )
        ).expanduser()
        self.native_oos_snapshot: NativeOosSnapshot | Mapping[str, Any] | None = None
        self.native_oos_snapshot_error: str | None = None
        writer_requested = str(
            os.environ.get("PM_TARGET_PRODUCTION_WRITER", "") or ""
        ).strip().lower() in {"1", "true", "yes", "on"}
        production_no_live_runtime = (
            writer_requested
            or str(os.environ.get("PM_TARGET_EXECUTION_MODE", "") or "").strip()
            == PRODUCTION_EXECUTION_MODE
        )
        # A pointer snapshot only speaks for the stations it attests.  This
        # one is a hand-generated audit artifact: it froze 5 of 45 stations on
        # 2026-08-03, and every selection sha has moved since, so it rejected
        # the 40 stations it never covered outright and mis-bound the 5 it
        # did.  Fail-closed is right when the snapshot is the authority; it is
        # not an authority once it has stopped tracking the fleet, and the
        # append-only activation rows it was guarding carry their own OOS gate,
        # authority scope and generation order.  Opt in by path, so a replay
        # can still pin a snapshot deliberately and nothing loads a stale one
        # by default.
        snapshot_requested = bool(
            native_oos_snapshot_path
            or os.environ.get("PM_TARGET_NATIVE_OOS_SNAPSHOT_MANIFEST")
        )
        if production_no_live_runtime and snapshot_requested:
            try:
                self.native_oos_snapshot = load_native_oos_snapshot_manifest(
                    self.native_oos_snapshot_path
                )
            except Exception as exc:
                # Preserve a non-None invalid sentinel so every official
                # compiler attempt fails closed instead of silently falling
                # back to the newest append-only DB activation.
                self.native_oos_snapshot_error = (
                    f"{type(exc).__name__}:{exc}"
                )
                self.native_oos_snapshot = {
                    "schema": "invalid_native_oos_snapshot",
                    "load_error": self.native_oos_snapshot_error,
                }
        # Serialises the read-modify-write of the shared native inbox.  Built
        # here rather than beside the capture pool, because it is not a pool:
        # a Lock starts no threads, so there is nothing to be lazy about, and
        # the laziness is what broke it.  The lock used to be created inside
        # ``if self._official_native_capture_pool is None``, and the Open-Meteo
        # D2 lane creates that same pool without it -- so a generation where
        # D2 captured first found the pool already made, skipped the block,
        # and every native merge afterwards raised
        # ``AttributeError: no attribute '_official_native_capture_merge_lock'``
        # for the life of the process.  Measured 2026-09-01: every native
        # capture MERGE_FAILED from 04:03Z, no P0 envelope was written for
        # 5.3 hours, and because P0 and P0-M have no staleness allowance --
        # only P1 does -- every station-day whose newest envelope was one of
        # them fail-closed on ``latest_stage_stale_fail_closed``: 21 scopes in
        # a single cycle.
        self._official_native_capture_merge_lock = threading.Lock()
        self.conn: sqlite3.Connection | None = None
        self.open_error: str | None = None
        # Which of the two opens was in flight when the last reopen
        # failed: "read_only", "writer", or None if neither has failed.
        self.open_failed_stage: str | None = None
        try:
            self.conn = open_target_read_only(self.db_path)
        except Exception as exc:
            self.open_failed_stage = "read_only"
            self.open_error = f"{type(exc).__name__}:{exc}"
        self.taf_inbox_path = Path(
            taf_inbox_path
            or os.environ.get(
                "PM_TARGET_TAF_INBOX",
                str(DEFAULT_TARGET_TAF_INBOX),
            )
        ).expanduser().resolve()
        self.p0_inbox_path = Path(
            p0_inbox_path
            or os.environ.get(
                "PM_TARGET_P0_INBOX",
                str(DEFAULT_TARGET_P0_INBOX),
            )
        ).expanduser().resolve()
        self.nwp_runtime_root = Path(
            nwp_runtime_root
            or os.environ.get(
                "PM_TARGET_NWP_RUNTIME_ROOT",
                str(DEFAULT_TARGET_NWP_RUNTIME_ROOT),
            )
        ).expanduser().resolve()
        raw_station_allowlist: Sequence[str]
        if station_allowlist is None:
            raw_station_allowlist = tuple(
                value
                for value in str(
                    os.environ.get("PM_TARGET_STATION_ALLOWLIST", "")
                    or ""
                ).split(",")
                if value.strip()
            )
            if (
                not raw_station_allowlist
                and self.db_path == DEFAULT_TARGET_DB.resolve()
            ):
                # Production scope is the frozen canonical 45-station
                # registry.  A station-specific vertical slice must be
                # passed explicitly and can never become the resident
                # default through an empty environment variable.
                raw_station_allowlist = CANONICAL_TARGET_STATIONS
        else:
            raw_station_allowlist = station_allowlist
        self.station_allowlist = tuple(
            sorted(
                {
                    str(value or "").strip().upper()
                    for value in raw_station_allowlist
                    if str(value or "").strip()
                }
            )
        )
        if len(self.station_allowlist) > expected_station_count():
            raise RuntimeError("target_station_allowlist_cap_exceeded")
        raw_event_dates: Sequence[str]
        if event_date_allowlist is None:
            raw_event_dates = tuple(
                value
                for value in str(
                    os.environ.get("PM_TARGET_EVENT_DATE_ALLOWLIST", "")
                    or ""
                ).split(",")
                if value.strip()
            )
        else:
            raw_event_dates = event_date_allowlist
        event_date_scope_source = "explicit" if raw_event_dates else "unconfigured"
        # No manifest-derived fallback.  An unset allowlist means "whatever the
        # live registry says is open", which is what a resident worker should
        # follow; deriving it from the handoff instead pinned the lane to the
        # days that already had a probability and starved every new one.
        if not raw_event_dates and production_no_live_runtime:
            event_date_scope_source = "live_registry_discovery"
            self.manifest_open_event_dates = _resident_open_event_dates(
                self.market_manifest_path
            )
        else:
            self.manifest_open_event_dates = ()
        self.event_date_allowlist = tuple(
            sorted(
                {
                    str(value or "").strip()
                    for value in raw_event_dates
                    if str(value or "").strip()
                }
            )
        )
        if len(self.event_date_allowlist) > 7:
            raise RuntimeError("target_event_date_allowlist_cap_exceeded")
        self.event_date_scope_source = event_date_scope_source
        self.nwp_rotation_state_path = (
            self.nwp_runtime_root / "rotation_state.json"
        )
        # Set here as well as per cycle: a caller that drives one stage
        # directly (every test of this lane does) must not meet an
        # AttributeError inside a try that would file it as a scope blocker.
        self._p0m_replay_blocked_scopes: frozenset[tuple[str, str]] = frozenset()
        self._p0m_replay_blocked_next: set[tuple[str, str]] = set()
        self.taf_rotation_state_path = (
            self.nwp_runtime_root / "taf_rotation_state.json"
        )
        self._nwp_rotation_state: dict[str, Any] | None = None
        self._nwp_rotation_state_load_error: str | None = None
        try:
            self._nwp_rotation_state = load_rotation_state(
                self.nwp_rotation_state_path,
                station_ids=self.station_allowlist,
            )
            if self._nwp_rotation_state is not None:
                self._resident_nwp_scope_cursor_by_priority = {
                    int(key): int(value)
                    for key, value in (
                        self._nwp_rotation_state.get(
                            "cursor_by_priority"
                        ) or {}
                    ).items()
                }
        except Exception as exc:
            reason = f"{type(exc).__name__}:{exc}"
            if "nwp_rotation_station_scope_mismatch" in reason:
                # The fleet grew.  The state file pins the station scope it
                # was built for, and on 2026-08-31 a 45-station state met a
                # 48-station fleet and the whole NWP cycle sat down
                # (blocked_fail_closed, every poll) -- for a file whose own
                # writer declares it "scheduler telemetry and a restart hint,
                # not an authorization boundary", and whose write failures
                # deliberately do not block.  Reading it cannot be stricter
                # than writing it: a scope from a smaller fleet is a stale
                # hint, so it is discarded and the first cycle rebuilds it
                # for the fleet that exists, rotation cursor starting over.
                self._nwp_rotation_state = None
                self._nwp_rotation_state_stale_discarded = reason
            else:
                self._nwp_rotation_state_load_error = reason
        self._resident_open_scope_cursor = 0
        self._native_ensemble_scope_cursor = int(
            getattr(
                self,
                "_resident_nwp_scope_cursor_by_priority",
                {},
            ).get(0, 0)
        )
        self.skip_nwp_refresh = str(
            os.environ.get("PM_TARGET_SKIP_NWP_REFRESH", "") or ""
        ).strip().lower() in {"1", "true", "yes", "on"}
        self.cash_phase_forward_store_root = DEFAULT_STORE_ROOT
        self.cash_phase_forward_store_path = resolve_forward_store_path(
            cash_phase_forward_store_path
            or os.environ.get(
                "PM_TARGET_CASH_PHASE_FORWARD_STORE",
                str(DEFAULT_CASH_PHASE_FORWARD_OBSERVATIONS),
            ),
            allowed_root=DEFAULT_STORE_ROOT,
        )
        self.commit_conn = commit_conn
        self.commit_error = commit_error
        self._last_delta_v2_truth_scan_monotonic: float | None = None
        self._last_delta_v2_label_scan_monotonic: float | None = None
        # Where the next forward-day sweep starts.  A pass that does not
        # survive to the end of the catalog must not hand the next pass the
        # same head of the alphabet, or the stations behind the truncation
        # point are the same ones every cycle.
        self._forward_p0_rotation_cursor: str = ""
        # The receipt for the book of the most recent refused forward
        # compile.  The refusal leaves by exception, so this is how the
        # sweep's blocked entry learns whether the observation survived it.
        self._forward_market_evidence_last: dict[str, Any] | None = None
        self._delta_v2_truth_fact_cursor = 0
        self._delta_v2_truth_cursor_initialized = False
        self._delta_v2_label_fact_cursor = 0
        self._delta_v2_label_cursor_initialized = False
        self.canonical_source_conn: sqlite3.Connection | None = None
        self.canonical_source_db_path: Path | None = None
        self.canonical_source_error: str | None = None
        if canonical_source_db_path is not None:
            source_path = Path(
                canonical_source_db_path
            ).expanduser().resolve()
            self.canonical_source_db_path = source_path
            try:
                self.canonical_source_conn = sqlite3.connect(
                    f"file:{source_path}?mode=ro",
                    uri=True,
                    timeout=30.0,
                    isolation_level=None,
                    check_same_thread=False,
                )
                self.canonical_source_conn.row_factory = sqlite3.Row
                self.canonical_source_conn.execute(
                    "PRAGMA busy_timeout=30000"
                )
                self.canonical_source_conn.execute(
                    "PRAGMA query_only=ON"
                )
            except Exception as exc:
                self.canonical_source_error = (
                    f"{type(exc).__name__}:{exc}"
                )

    def _target_open_blocker(self) -> str:
        """Name the connection that actually failed to open.

        Both handles are dropped together, so "self.conn is None" alone
        cannot tell a caller which open failed -- and for a year it always
        said read-only.
        """

        detail = self.open_error or "unknown"
        if self.open_failed_stage == "writer":
            return f"target_ssot_writer_open_failed:{detail}"
        return f"target_ssot_read_only_open_failed:{detail}"

    def reopen_target_connections(self) -> None:
        """Rebuild target SSOT handles after a recoverable SQLite I/O fault.

        SQLite marks a connection unusable after some ``SQLITE_IOERR``
        variants.  Keeping that handle resident turns a transient filesystem
        fault into a permanent fail-closed loop even when a fresh connection
        can read and write the same database.  Reopen both target handles as
        one worker-owned unit; canonical truth remains on its independent
        read-only connection.
        """

        for connection in (self.conn, self.commit_conn):
            if connection is None:
                continue
            try:
                connection.close()
            except sqlite3.Error:
                pass
        self.conn = None
        self.commit_conn = None
        self.open_error = None
        self.commit_error = None
        # Both handles or neither: that pairing is deliberate and stays.  What
        # was wrong is which connection the failure got attributed to.  Both
        # opens shared one try and one error slot, so a writer-open failure
        # landed in open_error, both handles were dropped, and the caller --
        # finding self.conn None -- reported
        # "target_ssot_read_only_open_failed:<the writer's error>".  That is
        # how a WAL checkpoint the writer could not take came back as
        # target_ssot_read_only_open_failed:...wal_checkpoint_busy, naming a
        # connection that had opened without complaint and sending the reader
        # to the wrong layer.  Record which open was in flight instead.
        self.open_failed_stage = None
        try:
            stage = "read_only"
            self.conn = open_target_read_only(self.db_path)
            stage = "writer"
            self.commit_conn = open_target_writer_if_enabled(
                self.db_path,
                activation_path=self.activation_path,
            )
            if self.commit_conn is None:
                raise RuntimeError("target_atomic_writer_not_enabled")
        except Exception as exc:
            self.open_failed_stage = stage
            self.open_error = f"{type(exc).__name__}:{exc}"
            self.commit_error = (
                "target_writer_reopen_failed:"
                f"{type(exc).__name__}:{exc}"
            )
            for connection in (self.conn, self.commit_conn):
                if connection is None:
                    continue
                try:
                    connection.close()
                except sqlite3.Error:
                    pass
            self.conn = None
            self.commit_conn = None
            raise

    def _latest_p0_weighted_systems(
        self,
        read_conn: sqlite3.Connection | None,
        *,
        event_date: str,
        as_of_utc: str,
    ) -> dict[str, tuple[str, ...]]:
        """The systems each station's newest P0 for the day weighted.

        What the capture probe needs to read a packet on the compiler's clock
        (``seated_evidence_received_at``) without compiling it.  The newest
        committed P0 is the prediction: when its seated evidence has aged the
        compile fails, no newer P0 is written, and this keeps answering with
        the seat set that needs re-reading until a packet renews it.

        Two narrow reads a day and a cycle: the latest envelope per station
        off the covering scope index, then one lineage field for each.  An
        unreadable store answers nothing, and the probe falls back to the
        packet clock it always had.
        """

        cache = getattr(self, "_p0_weighted_systems_cache", None)
        key = (str(event_date), str(as_of_utc))
        # One cycle's answers, every day it asks about; a new clock clears it.
        if not isinstance(cache, dict) or any(
            cached_as_of != key[1] for _day, cached_as_of in cache
        ):
            cache = {}
            self._p0_weighted_systems_cache = cache
        if key in cache:
            return cache[key]
        answer: dict[str, tuple[str, ...]] = {}
        if read_conn is not None:
            try:
                latest = read_conn.execute(
                    "SELECT station_id, MAX(decision_at_utc), envelope_id "
                    "FROM basket_probability_envelope "
                    "WHERE state='COMMITTED' AND event_date=? AND stage='P0' "
                    "AND decision_at_utc<=? GROUP BY station_id",
                    (str(event_date), str(as_of_utc)),
                ).fetchall()
                for station, _decision, envelope_id in latest:
                    row = read_conn.execute(
                        "SELECT json_extract(lineage_json,"
                        "'$.system_weights_json') "
                        "FROM basket_probability_envelope WHERE envelope_id=?",
                        (envelope_id,),
                    ).fetchone()
                    try:
                        weights = json.loads(str((row or [None])[0] or "{}"))
                    except (TypeError, ValueError):
                        continue
                    if not isinstance(weights, Mapping):
                        continue
                    seated = tuple(sorted(
                        str(system_id)
                        for system_id, weight in weights.items()
                        if isinstance(weight, (int, float))
                        and float(weight) > 1e-9
                    ))
                    if seated:
                        answer[str(station).strip().upper()] = seated
            except sqlite3.Error:
                answer = {}
        cache[key] = answer
        return answer

    def _retry_icon_held_captures(
        self,
        *,
        as_of_utc: str,
        inbox_path: Path,
    ) -> dict[str, str]:
        """Ask again for dates whose last pass lost ICON, off the cursor.

        A capture starts only when the rotation cursor lands on one of the
        date's scopes, and the cursor laps the catalogue in about two hours
        (2.09h achieved on 2026-09-14).  For the families with an archive that
        is only latency.  For ICON it is loss: DWD keeps one run per cycle, the
        fetch fails transiently often enough to matter, and a miss waited a
        whole lap for its retry -- the 2026-09-14 packets went out ECMWF, GEFS
        and ECCC only from 08:43Z while the run sat on DWD all day.  A date
        whose last pass held ICON after ICON's run was out is asked for again
        on the ordinary per-date throttle; the capture itself decides what
        else that pass refreshes.
        """

        pending = getattr(self, "_official_native_icon_retry_dates", None)
        if not pending:
            return {}
        try:
            today = _utc_date(as_of_utc).isoformat()
        except (TypeError, ValueError):
            return {}
        inflight = getattr(self, "_official_native_capture_inflight", None) or {}
        throttle = getattr(self, "_official_native_capture_attempts", None) or {}
        now_mono = time.monotonic()
        outcomes: dict[str, str] = {}
        for event_date in sorted(pending):
            if event_date < today:
                pending.discard(event_date)
                continue
            if not _icon_run_published_for(event_date, as_of_utc=as_of_utc):
                continue
            last_attempt = throttle.get((event_date,))
            if (event_date,) in inflight or (
                last_attempt is not None
                and now_mono - last_attempt < OFFICIAL_NATIVE_CAPTURE_RETRY_SEC
            ):
                continue
            outcome = self._capture_official_native_packet(
                station_id="",
                event_date=event_date,
                as_of_utc=as_of_utc,
                inbox_path=inbox_path,
            )
            outcomes[event_date] = str(outcome.get("state") or "")
        return outcomes

    def _log_capture_attempt(self, row: Mapping[str, Any]) -> None:
        """Charter 195 (二): one JSON line per capture attempt; never raises."""

        try:
            path = self.nwp_runtime_root / CAPTURE_ATTEMPT_LOG_NAME
            line = json.dumps(dict(row), sort_keys=True, ensure_ascii=False, default=str)
            with _CAPTURE_ATTEMPT_LOG_LOCK:
                try:
                    if path.stat().st_size > CAPTURE_ATTEMPT_LOG_MAX_BYTES:
                        os.replace(path, path.with_name(path.name + ".1"))
                except FileNotFoundError:
                    pass
                with path.open("a", encoding="utf-8") as handle:
                    handle.write(line + "\n")
        except Exception:  # noqa: BLE001 -- a log line is not worth a capture
            pass

    def _arrival_probe_state(self) -> Mapping[str, Any] | None:
        """The arrival probe's state file, re-read only when it changed."""

        if not ARRIVAL_TRIGGER_ENABLED:
            return None
        root = getattr(self, "nwp_runtime_root", None)
        if root is None:
            return None
        path = Path(root) / nwp_arrival_probe.STATE_FILE_NAME
        try:
            stamp = path.stat().st_mtime_ns
        except OSError:
            return None
        cached = getattr(self, "_arrival_probe_cache", None)
        if isinstance(cached, tuple) and cached[0] == stamp:
            return cached[1]
        state = nwp_arrival_probe.load_state(path)
        self._arrival_probe_cache = (stamp, state)
        return state

    def run_arrival_triggered_captures(self, *, as_of_utc: str) -> dict[str, Any]:
        """Charter 195 (二): start the capture a newly landed run is for.

        Called on the forecast thread (the rotation's own), every forecast
        refresh -- not only on the 10-minute NWP poll.  For each run the probe
        has seen complete for a listed day, once: ECMWF/GEFS start the day's
        pass past its retry floor on the probe-filtered ladder; an ICON/ECCC
        run the main pass reads as its lead's own cycle starts the pass on
        that lead's rung (so held ECMWF/GEFS rungs cannot retire it); any
        other ICON/ECCC cycle is queued on the follow lane (charter 192), and
        once that job is done the day's pass re-reads it for seating.  One
        submission per day per call; the rest wait for the next call.
        """

        boundary = {
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }
        if not ARRIVAL_TRIGGER_ENABLED:
            return {"state": "DISABLED", **boundary}
        state = self._arrival_probe_state()
        try:
            now = datetime.fromisoformat(
                as_of_utc.replace("Z", "+00:00")
            ).astimezone(timezone.utc)
            updated = datetime.fromisoformat(
                str((state or {}).get("updated_at_utc") or "").replace("Z", "+00:00")
            ).astimezone(timezone.utc)
        except ValueError:
            return {"state": "NO_PROBE_STATE", **boundary}
        if abs((now - updated).total_seconds()) > ARRIVAL_PROBE_FRESH_SEC:
            return {"state": "PROBE_STALE", **boundary}
        triggered: set[str] = getattr(
            self, "_official_native_arrival_triggered", None
        ) or set()
        self._official_native_arrival_triggered = triggered
        follow_pending: dict[str, str] = getattr(
            self, "_official_native_arrival_follow_pending", None
        ) or {}
        self._official_native_arrival_follow_pending = follow_pending
        inbox_path = (
            self.nwp_runtime_root / "official_native_ensemble_forward_inbox.json"
        )
        oldest_day = (now.date() - timedelta(days=1)).isoformat()
        rows: list[tuple[str, Mapping[str, Any]]] = []
        for key, row in (state.get("ready") or {}).items():
            if not isinstance(row, Mapping) or not row.get("acts_on_capture"):
                continue
            if key in triggered or str(row.get("event_date") or "") < oldest_day:
                continue
            try:
                seen = datetime.fromisoformat(
                    str(row.get("first_seen_at_utc")).replace("Z", "+00:00")
                ).astimezone(timezone.utc)
            except ValueError:
                continue
            if (now - seen).total_seconds() > ARRIVAL_TRIGGER_WINDOW_SEC:
                continue
            rows.append((key, row))
        rows.sort(key=lambda item: str(item[1].get("first_seen_at_utc")))
        busy_days: set[str] = set()
        outcomes: list[dict[str, Any]] = []
        # Follow jobs that have finished: the day's pass re-reads them.
        follow_last = getattr(
            self, "_official_native_follow_inflight", None
        ) or {}
        for key, event_date in list(follow_pending.items()):
            future = follow_last.get(event_date)
            if future is not None and not future.done():
                continue
            if event_date in busy_days:
                continue
            ladder = _official_native_run_ladder(
                event_date=event_date,
                as_of_utc=as_of_utc,
                probe_state=state,
            )
            result = (
                self._capture_official_native_packet(
                    station_id="",
                    event_date=event_date,
                    as_of_utc=as_of_utc,
                    inbox_path=inbox_path,
                    arrival=state["ready"].get(key) or {"family": "follow"},
                    forced_rungs=ladder[:1],
                )
                if ladder else {"state": "SKIPPED"}
            )
            outcome_state = str(result.get("state") or "")
            if outcome_state != "IN_FLIGHT" and outcome_state != (
                "DEFERRED_CAPTURE_SLOTS_BUSY"
            ):
                follow_pending.pop(key, None)
            busy_days.add(event_date)
            outcomes.append({"key": key, "step": "reseat", "state": outcome_state})
        for key, row in rows:
            event_date = str(row.get("event_date"))
            if event_date in busy_days:
                continue
            family = str(row.get("family") or "")
            try:
                run_init = datetime.fromisoformat(
                    str(row.get("run_init_utc")).replace("Z", "+00:00")
                ).astimezone(timezone.utc)
            except ValueError:
                triggered.add(key)
                continue
            lead = (date.fromisoformat(event_date) - run_init.date()).days
            forced = None
            # A lead the ladder does not serve (the charter 193 amendment's
            # ECMWF D-3 18Z for a D+2 day) is a follow-lane run too.
            beyond_ladder = lead not in {
                int(rung_lead) for rung_lead, _cycle in OFFICIAL_NATIVE_LADDER_RUNGS
            }
            # Charter 204: every AIFS ENS run is a follow-lane run -- it has
            # no rung of its own -- so a landed one always queues the job.
            follow_only = family in (
                nwp_arrival_probe.AIFS_FAMILY, nwp_arrival_probe.AIGEFS_FAMILY
            )
            if beyond_ladder or follow_only or family in (
                nwp_arrival_probe.ICON_FAMILY, nwp_arrival_probe.ECCC_FAMILY
            ):
                own = (
                    None
                    if beyond_ladder or follow_only
                    else _ARRIVAL_OWN_CYCLE_BY_LEAD.get(lead)
                )
                if own is None or run_init.hour != own:
                    queued = self._enqueue_arrival_follow(
                        event_date=event_date, lead=lead, run_init=run_init
                    )
                    # A job already running for the day was given its rungs
                    # before this cycle landed: ask again once it is done.
                    if queued != "ALREADY_QUEUED":
                        triggered.add(key)
                    if queued == "QUEUED":
                        follow_pending[key] = event_date
                    busy_days.add(event_date)
                    outcomes.append({"key": key, "step": "follow", "state": queued})
                    continue
                # The newest rung of that lead by the clock: it reads the
                # lead's own ICON/ECCC cycle, and its ECMWF/GEFS run is never
                # older than the one the lead's files hold (those came from a
                # rung of the same lead that was due earlier), so a family that
                # cannot serve it holds what it has -- nothing moves backwards.
                # Charter 193 (三): the newest rung of that lead that ECMWF or
                # GEFS has actually landed (the probe's ladder), not the
                # clock's.  2026-09-23 08:00Z: ECCC 00Z's arrival forced the
                # clock-newest 06Z rung on 09-23/09-24, which neither required
                # family had published; both held 09-22 18Z for seven minutes
                # while ECMWF 00Z sat on the replica.  With no fresh probe
                # state, or no landed rung of the lead, the clock rung as before.
                clock_rungs = [
                    rung
                    for rung in _official_native_run_ladder(
                        event_date=event_date, as_of_utc=as_of_utc
                    )
                    if int(rung[0]) == lead
                ]
                landed_rungs = [
                    rung
                    for rung in _official_native_run_ladder(
                        event_date=event_date,
                        as_of_utc=as_of_utc,
                        probe_state=state,
                    )
                    if int(rung[0]) == lead
                ]
                forced = (landed_rungs or clock_rungs)[:1]
                if not forced:
                    triggered.add(key)
                    outcomes.append({"key": key, "step": "pass", "state": "NO_RUNG"})
                    continue
            result = self._capture_official_native_packet(
                station_id="",
                event_date=event_date,
                as_of_utc=as_of_utc,
                inbox_path=inbox_path,
                arrival=row,
                forced_rungs=forced,
            )
            outcome_state = str(result.get("state") or "")
            if outcome_state not in {"IN_FLIGHT", "DEFERRED_CAPTURE_SLOTS_BUSY"}:
                triggered.add(key)
            busy_days.add(event_date)
            outcomes.append({"key": key, "step": "pass", "state": outcome_state})
        return {
            "state": "RAN",
            "candidate_count": len(rows),
            "outcomes": outcomes[:24],
            **boundary,
        }

    def _official_native_network_backoff_map(self) -> dict[str, dict[str, Any]]:
        """Charter 195 (四): days that last failed on the network, by date."""

        backoff = getattr(self, "_official_native_network_backoff", None)
        if backoff is None:
            backoff = {}
            self._official_native_network_backoff = backoff
        return backoff

    def _egress_answered_since(self, since_utc: str) -> bool:
        """Whether the upstream path has answered after ``since_utc``.

        First the supply watch (charter 197) -- its egress probe says ``ok``
        in a file written after the failure -- then, at most once a minute, a
        HEAD of our own on the two required families' roots.  Never raises.
        """

        try:
            since = datetime.fromisoformat(
                str(since_utc).replace("Z", "+00:00")
            ).astimezone(timezone.utc)
        except ValueError:
            return True
        try:
            from .supply_watch import DEFAULT_OUTPUT  # noqa: PLC0415

            watch = json.loads(Path(DEFAULT_OUTPUT).read_text())
            generated = datetime.fromisoformat(
                str(watch.get("generated_at_utc") or "").replace("Z", "+00:00")
            ).astimezone(timezone.utc)
            if (
                str((watch.get("egress") or {}).get("state") or "") == "ok"
                and generated > since
            ):
                return True
        except Exception:  # noqa: BLE001 -- the direct check below answers
            pass
        seen_ok = getattr(self, "_egress_answered_at", None)
        if isinstance(seen_ok, datetime) and seen_ok > since:
            return True
        last_check = float(getattr(self, "_egress_checked_mono", 0.0) or 0.0)
        if time.monotonic() - last_check < EGRESS_RECHECK_SEC:
            return False
        self._egress_checked_mono = time.monotonic()
        try:
            from official_nwp_https_transport import official_nwp_proxy_url  # noqa: PLC0415

            from .supply_watch import http_head_probe  # noqa: PLC0415

            proxy = official_nwp_proxy_url() or ""
            answered = all(
                str(http_head_probe(url, proxy, 8.0).get("outcome") or "")
                in {"ok", "throttled"}
                for url in EGRESS_PROBE_URLS
            )
        except Exception:  # noqa: BLE001 -- unknown is "not yet"
            answered = False
        if answered:
            self._egress_answered_at = datetime.now(timezone.utc)
            return self._egress_answered_at > since
        return False

    def run_network_recovery_recaptures(self, *, as_of_utc: str) -> dict[str, Any]:
        """Charter 195 (四): once the egress answers, re-queue in order.

        Days that failed on the network go first as a required-only pass
        (ECMWF and GEFS; ICON and ECCC held on what they have, so the day is
        merged and compiled as soon as the two required families land), in
        the supply watch's ``recapture_priority`` order when it gives one and
        D+1, D+0, D+2 otherwise.  Only once no required-only pass is left does
        each day get its full pass (ICON, ECCC, the follow lane).  Runs on the
        forecast thread, off the NWP poll.  Never raises.
        """

        boundary = {
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }
        backoff = self._official_native_network_backoff_map()
        stages: dict[str, str] = getattr(
            self, "_official_native_recovery_stage", None
        ) or {}
        self._official_native_recovery_stage = stages
        try:
            today = datetime.fromisoformat(
                as_of_utc.replace("Z", "+00:00")
            ).astimezone(timezone.utc).date()
        except ValueError:
            return {"state": "CLOCK_INVALID", **boundary}
        oldest = (today - timedelta(days=1)).isoformat()
        for day in [day for day in list(backoff) + list(stages) if day < oldest]:
            backoff.pop(day, None)
            stages.pop(day, None)
        for day in backoff:
            stages.setdefault(day, "required_due")
        if not stages:
            return {"state": "IDLE", **boundary}
        waiting = [day for day, stage in stages.items() if stage == "required_due"]
        if waiting and not any(
            self._egress_answered_since(str((backoff.get(day) or {}).get("since_utc") or ""))
            for day in waiting
        ):
            return {"state": "EGRESS_DOWN", "days": sorted(waiting), **boundary}
        priority: list[str] = []
        try:
            from .supply_watch import DEFAULT_OUTPUT  # noqa: PLC0415

            watch = json.loads(Path(DEFAULT_OUTPUT).read_text())
            priority = [
                str(row.get("event_date"))
                for row in watch.get("recapture_priority") or ()
                if isinstance(row, Mapping)
            ]
        except Exception:  # noqa: BLE001 -- the default order answers
            priority = []

        def order_key(day: str) -> tuple[int, int, str]:
            lead = (date.fromisoformat(day) - today).days
            ranked = priority.index(day) if day in priority else len(priority)
            return (ranked, {1: 0, 0: 1}.get(lead, 2 + abs(lead)), day)

        inflight = getattr(self, "_official_native_capture_inflight", None) or {}
        inbox_path = (
            self.nwp_runtime_root / "official_native_ensemble_forward_inbox.json"
        )
        outcomes: list[dict[str, Any]] = []
        # A finished required-only pass moves its day on -- back to waiting
        # when it met the network again, to its full pass otherwise.
        for day, stage in list(stages.items()):
            if stage != "required_running":
                continue
            future = inflight.get((day,))
            if future is not None and not future.done():
                continue
            try:
                outcome = future.result() if future is not None else {}
            except Exception:  # noqa: BLE001 -- the full pass answers it
                outcome = {}
            again = str(outcome.get("state") or "") == "NETWORK_UNAVAILABLE" or bool(
                outcome.get("network_held_families")
            )
            stages[day] = "required_due" if again else "full_due"
        required_left = [
            day for day, stage in stages.items()
            if stage in {"required_due", "required_running"}
        ]
        for day in sorted(stages, key=order_key):
            stage = stages[day]
            if stage == "required_due":
                result = self._capture_official_native_packet(
                    station_id="",
                    event_date=day,
                    as_of_utc=as_of_utc,
                    inbox_path=inbox_path,
                    arrival={"family": "recovery"},
                    hold_families=RECOVERY_HOLD_FAMILIES,
                )
                state = str(result.get("state") or "")
                if state == "SUBMITTED":
                    stages[day] = "required_running"
                elif state in {"RUN_ALREADY_CAPTURED", "SKIPPED"}:
                    stages[day] = "full_due"
                outcomes.append({"event_date": day, "step": "required", "state": state})
            elif stage == "full_due" and not required_left:
                ladder = _official_native_run_ladder(
                    event_date=day,
                    as_of_utc=as_of_utc,
                    probe_state=self._arrival_probe_state(),
                )
                result = (
                    self._capture_official_native_packet(
                        station_id="",
                        event_date=day,
                        as_of_utc=as_of_utc,
                        inbox_path=inbox_path,
                        arrival={"family": "recovery"},
                        forced_rungs=ladder[:1],
                    )
                    if ladder else {"state": "SKIPPED"}
                )
                state = str(result.get("state") or "")
                if state not in {"IN_FLIGHT", "DEFERRED_CAPTURE_SLOTS_BUSY"}:
                    stages.pop(day, None)
                outcomes.append({"event_date": day, "step": "full", "state": state})
        return {"state": "RAN", "outcomes": outcomes, **boundary}

    def run_listing_triggered_captures(self, *, as_of_utc: str) -> dict[str, Any]:
        """Charter 263: a newly listed station-day starts its capture now.

        Called on the forecast thread every refresh, beside the arrival step.
        Every (station, day) the forward registry lists whose local day has
        not closed and for which the official inbox holds no packet goes
        through the rotation's own entry with ``listing_station`` set, so
        the once-per-(day, station) record, the throttle bypass and the
        attempt log are charter 195 (三)'s, not a second copy.  One
        submission per event date per call, and one per listing batch: a
        pass is a model run, not a station, and covers every station of the
        date the registry held when it started, so every station it was
        asked for is recorded as attempted the moment it is submitted.  A
        station the pass still leaves without a packet -- ECMWF held on a
        banked run that does not seat it (charter 193 amendment C) -- waits
        for the next run arrival (195 (二)) or the rotation, exactly as
        before this trigger; re-running the same pass per station re-held
        the same run (six 70s passes for the 2026-10-11 US batch, 2026-10-09
        07:42Z-07:56Z, none of them seating anyone).
        """

        boundary = {
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }
        if not LISTING_TRIGGER_ENABLED:
            return {"state": "DISABLED", **boundary}
        registry_path = self.nwp_runtime_root / "market_registry_forward.json"
        inbox_path = (
            self.nwp_runtime_root / "official_native_ensemble_forward_inbox.json"
        )
        # Charter 263 (四): a day whose event-run follow files were topped up
        # for stations listed after their first read gets its pass again
        # once that job is done -- the packets come from a pass, and the
        # listing pass ran before the stations were in the files.
        reseat_outcomes = self._reseat_after_listing_follow(
            as_of_utc=as_of_utc, inbox_path=inbox_path
        )
        # A listing whose follow job could not be queued because the day's
        # job was already running (it read the registry before the listing)
        # is asked again every refresh until a job of its own is queued.
        follow_pending: set[str] | None = getattr(
            self, "_official_native_listing_follow_pending", None
        )
        if follow_pending is None:
            follow_pending = set()
            self._official_native_listing_follow_pending = follow_pending
        follow_retries: dict[str, str] = {}
        for day in sorted(follow_pending):
            follow_retries[day] = self._enqueue_listing_follow(event_date=day)
            if follow_retries[day] != "ALREADY_QUEUED":
                follow_pending.discard(day)
        if not registry_path.is_file():
            return {
                "state": "NO_REGISTRY",
                "reseat": reseat_outcomes,
                "follow_retries": follow_retries,
                **boundary,
            }
        try:
            registry = load_market_registry_snapshot(registry_path)
        except Exception as exc:  # noqa: BLE001 -- the rotation is the fallback
            return {
                "state": "REGISTRY_UNREADABLE",
                "reason": f"{type(exc).__name__}:{exc}"[:200],
                **boundary,
            }
        filters = registry.get("filters")
        if not (
            isinstance(filters, Mapping)
            and bool(filters.get("include_not_started_for_p0"))
        ):
            # The capture pass itself refuses a registry without the forward
            # boundary (``p0_forward_registry_scope_not_authorized``).
            return {"state": "REGISTRY_NOT_FORWARD", **boundary}
        held: set[tuple[str, str]] = set()
        if inbox_path.is_file():
            try:
                for packet in _load_native_forward_inbox(
                    inbox_path,
                    error_code="official_native_forward_inbox_invalid",
                ):
                    if (
                        str(packet.get("schema") or "")
                        != OFFICIAL_NATIVE_FORWARD_PACKET_SCHEMA
                    ):
                        continue
                    held.add((
                        str(packet.get("station_id") or "").strip().upper(),
                        str(packet.get("event_date") or "").strip(),
                    ))
            except ContractError as exc:
                return {
                    "state": "INBOX_UNREADABLE",
                    "reason": f"{type(exc).__name__}:{exc}"[:200],
                    **boundary,
                }
        attempted: set[tuple[str, str]] | None = getattr(
            self, "_official_native_listing_attempts", None
        )
        if attempted is None:
            attempted = set()
            self._official_native_listing_attempts = attempted
        allow = {
            str(item).strip().upper()
            for item in (getattr(self, "station_allowlist", None) or ())
        }
        try:
            today = date.fromisoformat(str(as_of_utc)[:10])
        except ValueError:
            return {"state": "CLOCK_INVALID", **boundary}
        scopes: set[tuple[str, str, str]] = set()
        for row in registry.get("rows") or ():
            if not isinstance(row, Mapping):
                continue
            station = str(row.get("station_id") or "").strip().upper()
            day = str(row.get("event_date") or "").strip()
            timezone_name = str(row.get("settlement_timezone") or "").strip()
            if not station or not day or not timezone_name:
                continue
            if allow and station not in allow:
                continue
            if (station, day) in held or (day, station) in attempted:
                continue
            scopes.add((day, station, timezone_name))
        candidates: dict[str, list[str]] = {}
        for day, station, timezone_name in sorted(scopes):
            try:
                day_state = str(event_day_window(
                    day, as_of_utc=as_of_utc, target_timezone=timezone_name
                )["state"])
            except Exception:  # noqa: BLE001 -- a bad row is not a trigger
                continue
            if day_state == "closed":
                continue
            candidates.setdefault(day, []).append(station)
        outcomes: list[dict[str, Any]] = []
        for day in sorted(candidates):
            stations = candidates[day]
            try:
                lead_days = max(0, min(2, (date.fromisoformat(day) - today).days))
            except ValueError:
                continue
            # The event-run files may lack these stations too (ECMWF's D-3
            # 18Z held for the day until its own D-2 00Z lands): their
            # follow job starts now, beside the pass, not after it.
            follow_state = self._enqueue_listing_follow(event_date=day)
            if follow_state == "ALREADY_QUEUED":
                follow_pending.add(day)
            result = self._capture_official_native_packet(
                station_id=stations[0],
                event_date=day,
                as_of_utc=as_of_utc,
                inbox_path=inbox_path,
                listing_station=stations[0],
                lead_days=lead_days,
            )
            state = str(result.get("state") or "")
            if state == "SUBMITTED":
                attempted.update((day, station) for station in stations)
            outcomes.append({
                "event_date": day,
                "station_id": stations[0],
                "stations_without_packet": len(stations),
                "stations_recorded_attempted": (
                    len(stations) if state == "SUBMITTED" else 0
                ),
                "follow": follow_state,
                "state": state,
            })
        return {
            "state": "RAN",
            "outcomes": outcomes,
            "reseat": reseat_outcomes,
            "follow_retries": follow_retries,
            **boundary,
        }

    def _enqueue_listing_follow(self, *, event_date: str) -> str:
        """Charter 263 (四): queue the day's follow job for a listing's gaps."""

        if not follow_run.follow_enabled():
            return "FOLLOW_DISABLED"
        registry_path = self.nwp_runtime_root / "market_registry_forward.json"
        if not registry_path.is_file():
            return "REGISTRY_MISSING"
        capture_root = self.nwp_runtime_root / "official_native_capture"
        capture_root.mkdir(parents=True, exist_ok=True)
        return self._enqueue_follow_run_capture(
            event_date=event_date,
            run_ladder=[],
            registry_path=registry_path,
            capture_root=capture_root,
            env={
                **os.environ,
                "ECMWF_ARCHIVE_TRANSPORT_BASE_URL": ECMWF_GCS_REPLICA_BASE_URL,
            },
        )

    def _reseat_after_listing_follow(
        self, *, as_of_utc: str, inbox_path: Path
    ) -> list[dict[str, Any]]:
        """Run the day's pass once its gap-driven follow job has finished.

        The same step the arrival lane takes after a follow job (charter 195
        (二)): the newest rung, forced past the held-run retirement and the
        retry floor, because the run it reads is one the day already holds --
        what changed is which stations the event-run files carry.
        """

        reseat: dict[str, Any] | None = getattr(
            self, "_official_native_follow_reseat", None
        )
        if not reseat:
            return []
        follow_jobs = getattr(self, "_official_native_follow_inflight", None) or {}
        outcomes: list[dict[str, Any]] = []
        for day in sorted(reseat):
            future = follow_jobs.get(day)
            if future is not None and not future.done():
                continue
            ladder = _official_native_run_ladder(
                event_date=day,
                as_of_utc=as_of_utc,
                probe_state=self._arrival_probe_state(),
            )
            result = (
                self._capture_official_native_packet(
                    station_id="",
                    event_date=day,
                    as_of_utc=as_of_utc,
                    inbox_path=inbox_path,
                    arrival={"family": "listing_follow_reseat"},
                    forced_rungs=ladder[:1],
                )
                if ladder else {"state": "SKIPPED"}
            )
            state = str(result.get("state") or "")
            outcomes.append({
                "event_date": day,
                "follow_files": list(reseat.get(day) or ()),
                "state": state,
            })
            if state not in {"IN_FLIGHT", "DEFERRED_CAPTURE_SLOTS_BUSY"}:
                reseat.pop(day, None)
        return outcomes

    def _enqueue_arrival_follow(
        self, *, event_date: str, lead: int, run_init: datetime
    ) -> str:
        """Queue the follow job for a landed ICON/ECCC cycle (charter 192)."""

        if not follow_run.follow_enabled():
            return "FOLLOW_DISABLED"
        registry_path = self.nwp_runtime_root / "market_registry_forward.json"
        if not registry_path.is_file():
            return "REGISTRY_MISSING"
        capture_root = self.nwp_runtime_root / "official_native_capture"
        capture_root.mkdir(parents=True, exist_ok=True)
        return self._enqueue_follow_run_capture(
            event_date=event_date,
            run_ladder=[(int(lead), int(run_init.hour), run_init)],
            registry_path=registry_path,
            capture_root=capture_root,
            env={
                **os.environ,
                "ECMWF_ARCHIVE_TRANSPORT_BASE_URL": ECMWF_GCS_REPLICA_BASE_URL,
            },
        )

    def _capture_official_native_packet(
        self,
        *,
        station_id: str,
        event_date: str,
        as_of_utc: str,
        inbox_path: Path,
        lead_days: int = 2,
        seated_system_ids: Sequence[str] | None = None,
        arrival: Mapping[str, Any] | None = None,
        forced_rungs: Sequence[tuple[int, int | None, datetime]] | None = None,
        listing_station: str | None = None,
        hold_families: Sequence[str] = (),
    ) -> dict[str, Any]:
        """Start a background capture for one scope; never block the caller.

        Official-native coverage is what actually gates P0: a republisher packet
        is filtered out of the P0 inbox by design, so a scope without an
        official packet yields no envelope at all.  Coverage therefore has to
        grow fast, but one capture takes minutes.

        Running it inline on the forecast worker was the wrong trade in both
        directions: uncapped it stalled the rotation at roughly one scope per
        six hours, and once throttled hard enough to protect the rotation, the
        coverage crawled.  Captures now run on their own small pool, so several
        scopes fetch concurrently while the rotation keeps sweeping at full
        speed.  The work is subprocess-bound, so these threads are almost
        entirely idle wait.

        This returns immediately with the scope's admission state.  The packet
        lands in the shared inbox when its capture finishes, and the rotation
        picks it up on a later pass.
        """


        throttle: dict[tuple[str, ...], float] = getattr(
            self, "_official_native_capture_attempts", None
        ) or {}
        self._official_native_capture_attempts = throttle
        inflight: dict[tuple[str, ...], Any] = getattr(
            self, "_official_native_capture_inflight", None
        )
        if inflight is None:
            inflight = {}
            self._official_native_capture_inflight = inflight
        # Which run each event date has already been captured from.  These
        # families publish on a fixed daily cycle, so a run that has been read
        # once has nothing further to give: re-reading it re-downloads the same
        # immutable objects.  The clock-based retry floor below only governs
        # *failed* attempts; a success is retired by run identity instead, and
        # the next download waits for the next cycle to publish.
        captured_runs: dict[str, str] = getattr(
            self, "_official_native_capture_runs", None
        )
        if captured_runs is None:
            captured_runs = {}
            self._official_native_capture_runs = captured_runs
        # The newest outcome per event date, not one slot for all of them.
        # A single slot was overwritten by whichever capture finished last:
        # on 2026-09-05 the 2026-09-07 pass exited after two minutes with no
        # staging inbox, and by the time any receipt could be read the slot
        # held 2026-06's and then 2026-05's outcome -- the one question worth
        # asking about that date had no answer anywhere.  Keyed by date, a
        # scope's THROTTLED receipt carries the attempt it is actually
        # holding down, and the status publisher can show every open date.
        results_by_date: dict[str, dict[str, Any]] = getattr(
            self, "_official_native_capture_last_result_by_date", None
        )
        if results_by_date is None:
            results_by_date = {}
            self._official_native_capture_last_result_by_date = (
                results_by_date
            )
        icon_retry_dates: set[str] = getattr(
            self, "_official_native_icon_retry_dates", None
        )
        if icon_retry_dates is None:
            icon_retry_dates = set()
            self._official_native_icon_retry_dates = icon_retry_dates
        if getattr(self, "_official_native_capture_pool", None) is None:
            # Small, bounded, and lazily created so a worker that never
            # captures (tests, --once paths) starts no threads at all.  The
            # work is subprocess-bound, so these threads sit in wait.
            self._official_native_capture_pool = ThreadPoolExecutor(
                max_workers=OFFICIAL_NATIVE_CAPTURE_MAX_CONCURRENCY,
                thread_name_prefix="official-native-capture",
            )
        # What gets downloaded is a model run, not a station.  Every family
        # here publishes whole global fields on a fixed cycle; a station is an
        # extraction from those fields, so forty-five stations of one event
        # date cost one download, not forty-five.  Keying this on the station
        # was what made them cost forty-five: retained archives are matched on
        # the exact station set, so one station's archive never served the
        # next, and each scope re-fetched the same objects.
        #
        # The key is therefore the event date alone.  The lead does not belong
        # in it either: the run ladder resolves all three lead-labelled scopes
        # of a day to the same "newest covering run", so keying them apart
        # would download that run three times.
        scope_key = (event_date,)
        now_mono = time.monotonic()

        # Reap finished captures so their scopes free a concurrency slot, and
        # keep the newest outcome visible for the status receipt.
        for key in [key for key, fut in inflight.items() if fut.done()]:
            finished = inflight.pop(key, None)
            try:
                outcome = finished.result()
            except Exception as exc:
                outcome = {
                    "state": "FAILED",
                    "reason": f"{type(exc).__name__}:{str(exc)[:200]}",
                }
            results_by_date[key[0]] = {
                "event_date": key[0],
                "completed_at_utc": as_of_utc,
                **outcome,
            }
            # Charter 195 (四): the network, not the run -- the day keeps
            # neither the floor nor the walk; it backs off and is re-queued
            # when the egress answers.
            network_backoff = self._official_native_network_backoff_map()
            if str(outcome.get("state") or "") == "NETWORK_UNAVAILABLE" or (
                outcome.get("network_held_families")
            ):
                throttle.pop(key, None)
                previous = network_backoff.get(key[0]) or {}
                attempts = int(previous.get("attempts") or 0) + 1
                delay = min(
                    NETWORK_BACKOFF_MAX_SEC,
                    NETWORK_BACKOFF_MIN_SEC * (2 ** (attempts - 1)),
                ) * random.uniform(
                    1.0 - NETWORK_BACKOFF_JITTER, 1.0 + NETWORK_BACKOFF_JITTER
                )
                network_backoff[key[0]] = {
                    "attempts": attempts,
                    "until_mono": time.monotonic() + delay,
                    "since_utc": utc_now(),
                }
            elif str(outcome.get("state") or "") == "CAPTURED":
                network_backoff.pop(key[0], None)
            if str(outcome.get("state") or "") == "CAPTURED":
                captured_runs[key[0]] = str(
                    outcome.get("captured_run_init_utc") or ""
                )
                held = outcome.get("families_held_on_earlier_run")
                if (
                    isinstance(held, Mapping)
                    and ICON_TRANSPORT_PROVIDER_ID in held
                ):
                    icon_retry_dates.add(key[0])
                else:
                    icon_retry_dates.discard(key[0])
        # Bounded by the open window: a date more than three days behind the
        # clock is closed everywhere and its outcome answers nothing.
        try:
            retention_floor = (
                _utc_date(as_of_utc) - timedelta(days=3)
            ).isoformat()
        except (TypeError, ValueError):
            retention_floor = None
        if retention_floor is not None:
            for stale_date in [
                day for day in results_by_date if day < retention_floor
            ]:
                results_by_date.pop(stale_date, None)

        if scope_key in inflight:
            return {
                "state": "IN_FLIGHT",
                "station_id": station_id,
                "event_date": event_date,
                "calls_order_gateway": False,
                "places_orders": False,
            }
        if len(inflight) >= OFFICIAL_NATIVE_CAPTURE_MAX_CONCURRENCY:
            return {
                "state": "DEFERRED_CAPTURE_SLOTS_BUSY",
                "station_id": station_id,
                "event_date": event_date,
                "in_flight": len(inflight),
                "calls_order_gateway": False,
                "places_orders": False,
            }
        # Charter 195 (四): a day that last failed on the network waits out its
        # backoff -- unless the egress has answered since, then it goes now.
        backoff_row = self._official_native_network_backoff_map().get(event_date)
        if backoff_row:
            if self._egress_answered_since(str(backoff_row.get("since_utc") or "")):
                backoff_row["until_mono"] = 0.0
            elif now_mono < float(backoff_row.get("until_mono") or 0.0):
                return {
                    "state": "NETWORK_BACKOFF",
                    "station_id": station_id,
                    "event_date": event_date,
                    "retry_after_sec": round(
                        float(backoff_row["until_mono"]) - now_mono, 1
                    ),
                    "attempts": int(backoff_row.get("attempts") or 0),
                    "calls_order_gateway": False,
                    "places_orders": False,
                }
        # Resolve the run before deciding to spend anything.  These families
        # publish on a fixed cycle, so "is there a newer run than the one this
        # date already holds" is the whole question -- if there is not, the
        # answer is to download nothing at all and wait for the next cycle.
        # Charter 195 (二): an arrival names the run it is for; an ICON/ECCC
        # arrival names the rung whose lead reads that run (``forced_rungs``),
        # because the ECMWF/GEFS rungs the date already holds would retire the
        # pass before ICON/ECCC were ever asked.
        run_ladder = (
            list(forced_rungs)
            if forced_rungs
            else _official_native_run_ladder(
                event_date=event_date,
                as_of_utc=as_of_utc,
                probe_state=self._arrival_probe_state(),
            )
        )
        if not run_ladder:
            return {
                "state": "SKIPPED",
                "reason": "no_published_run_covers_event_date",
                "station_id": station_id,
                "event_date": event_date,
                "calls_order_gateway": False,
                "places_orders": False,
            }
        newest_run_init = (
            run_ladder[0][2].isoformat().replace("+00:00", "Z")
        )
        # A held run is retired for good only while the packets built from
        # it are still usable.  The packet's freshness window runs from the
        # *capture*, not from the run, and the next contracted run lands
        # hours after the window closes -- 2026-09-02: 09-03's packets were
        # received 08:11Z, every one of the 62 in the inbox was refused as
        # native_ensemble_snapshot_stale from mid-afternoon on, the 00Z run
        # was not ready until 08Z, the republisher fallback had spent its
        # daily quota, and no P0 was minted fleet-wide for the whole night.
        # Re-reading the same run is cheap (the archives are retained) and
        # a new capture is a new arrival receipt, which is exactly what the
        # compiler's window was written to require.
        stale_for_day = _official_inbox_packets_all_stale(
            inbox_path,
            event_date=event_date,
            as_of_utc=as_of_utc,
            station_id=station_id,
            seated_system_ids=seated_system_ids,
        )
        # Charter 195 (三): a station listed after the day's pass has no packet
        # at all.  Once per (day, station) its pass runs now, past the held-run
        # retirement and the retry floor: the run it needs is the one the day
        # already holds, the object store has every step of it, and re-reading
        # costs extraction, not a download.
        listing_seen: set[tuple[str, str]] = getattr(
            self, "_official_native_listing_attempts", None
        ) or set()
        self._official_native_listing_attempts = listing_seen
        listing_key = (
            (event_date, str(listing_station).strip().upper())
            if listing_station else None
        )
        listing_new = listing_key is not None and listing_key not in listing_seen
        # Charter 193 (三): what a date holds survives a restart.  The map
        # above lives in process memory; emptied at 2026-09-23 04:00:33Z it
        # let the next pass walk below the 18Z the date's files held and spend
        # 42 minutes capturing 12Z.  Read once per date from the per-lead
        # archives on disk (the slower of GEFS/ECMWF, as a pass records it).
        restored_dates: set[str] = getattr(
            self, "_official_native_capture_runs_restored", None
        ) or set()
        self._official_native_capture_runs_restored = restored_dates
        if event_date not in captured_runs and event_date not in restored_dates:
            restored_dates.add(event_date)
            restored = _held_run_from_capture_archives(
                self.nwp_runtime_root / "official_native_capture", event_date
            )
            if restored:
                captured_runs[event_date] = restored
        if (
            captured_runs.get(event_date) == newest_run_init
            and not stale_for_day
            and not forced_rungs
            and not listing_new
        ):
            return {
                "state": "RUN_ALREADY_CAPTURED",
                "station_id": station_id,
                "event_date": event_date,
                "captured_run_init_utc": newest_run_init,
                "calls_order_gateway": False,
                "places_orders": False,
            }
        # Only rungs newer than what this date already holds are worth trying.
        # The freshest run is the last to finish uploading, so an attempt on it
        # failing is ordinary -- but without this the ladder would then fall
        # back onto the run already captured and download it a second time,
        # which is the opposite of what the fallback is for.  Falling through
        # to nothing is the correct outcome: the date keeps what it has and
        # retries after its floor.
        held_run_init = captured_runs.get(event_date)
        if (
            held_run_init
            and not stale_for_day
            and not forced_rungs
            and not listing_new
        ):
            try:
                held = datetime.fromisoformat(
                    held_run_init.replace("Z", "+00:00")
                ).astimezone(timezone.utc)
            except ValueError:
                held = None
            if held is not None:
                run_ladder = [
                    rung for rung in run_ladder if rung[2] > held
                ]
                if not run_ladder:
                    return {
                        "state": "RUN_ALREADY_CAPTURED",
                        "station_id": station_id,
                        "event_date": event_date,
                        "captured_run_init_utc": held_run_init,
                        "calls_order_gateway": False,
                        "places_orders": False,
                    }
        last_attempt = throttle.get(scope_key)
        # Charter 195 (二): the floor rations blind tries; an arrival is not
        # one -- the probe has seen the run on the server -- so it goes now.
        if (
            arrival is None
            and not listing_new
            and last_attempt is not None
            and now_mono - last_attempt < OFFICIAL_NATIVE_CAPTURE_RETRY_SEC
        ):
            return {
                "state": "THROTTLED",
                "station_id": station_id,
                "event_date": event_date,
                "retry_after_sec": round(
                    OFFICIAL_NATIVE_CAPTURE_RETRY_SEC - (now_mono - last_attempt), 1
                ),
                # Carry what the attempt this throttle is holding down
                # actually returned.  Without it a scope sitting on a
                # twelve-hour-old run reports only that it is waiting, and
                # the reason it is waiting -- the run it did or did not come
                # back with -- is exactly the question being asked.  This
                # date's attempt, not whichever date finished last.
                "last_completed": dict(
                    results_by_date.get(event_date) or {}
                ),
                "calls_order_gateway": False,
                "places_orders": False,
            }
        throttle[scope_key] = now_mono
        if listing_new and listing_key is not None:
            listing_seen.add(listing_key)

        registry_path = self.nwp_runtime_root / "market_registry_forward.json"
        if not registry_path.is_file():
            return {
                "state": "SKIPPED",
                "reason": "forward_market_registry_missing",
                "station_id": station_id,
                "event_date": event_date,
                "calls_order_gateway": False,
                "places_orders": False,
            }
        capture_root = self.nwp_runtime_root / "official_native_capture"
        capture_root.mkdir(parents=True, exist_ok=True)
        staging_inbox = capture_root / f"run_{event_date}_inbox.json"
        # The capture runs as a child process, not in-process.  Its per-request
        # timeouts do not bound total wall time -- several archive reads plus an
        # inbox build ran well past two minutes in production -- and only a
        # child can be killed outright when it overruns; a thread cannot.
        base_command = [
            sys.executable,
            str(ROOT / "scripts" / "capture_official_native_ensemble_forward.py"),
            "--event-date", event_date,
            "--market-registry", str(registry_path),
            # The whole day, not the one station the rotation happens to be
            # pointing at.  Every family below ships global fields on a fixed
            # cycle, and a station is an extraction from them: measured on this
            # lane, forty-five stations cost 517MiB of ECMWF against 259MiB for
            # one, and 70MiB of GEFS against 41MiB.  Twice the bytes for
            # forty-five times the coverage.  Asking per station instead turned
            # that into forty-five separate full downloads, because retained
            # archives are matched on the exact station set and one station's
            # archive never satisfied the next.
            #
            # Stations whose market has not opened for the day are skipped
            # rather than fatal: an event date three days out legitimately
            # lists 29 of 45, and the run still has to be read for those 29.
            "--registry-scope-stations",
            #
            # ECCC is captured on the same rotation rather than left to operator
            # commands.  Its history is what admits a third independent family
            # to the cross-ensemble candidate set; a system whose archive stops
            # growing can never cover the holdout cohort and is silently
            # excluded, which is how per-station model selection ended up with a
            # candidate set of exactly two.
            "--inbox-output", str(staging_inbox),
            "--timeout-seconds", str(OFFICIAL_NATIVE_CAPTURE_TIMEOUT_SEC),
            # Every capture also lands in the historical member table.  The
            # rotation was downloading these systems daily and then discarding
            # the member values once the inbox packet was built, so the
            # training archive only ever advanced when someone ran a manual
            # backfill -- ECMWF, GEFS and ECCC all froze at 2026-08-07, the
            # last day a person did.  ICON never froze because its daily lane
            # commits, and this makes the other three behave like it.
            "--commit",
        ]
        # Charter 192: a station may take ICON's/ECCC's newer retained run
        # once that run's own fit is certified.  With nothing certified the
        # packets are the ones this pass always built.
        #
        # The required-first recovery pass (charter 195 (四)) keeps this step:
        # it reads only retained follow files and the certificate table, no
        # network, and since charters 204 and 212 it is the only way AIFS ENS
        # and AIGEFS enter a packet.  Switched off there, the 2026-09-24
        # 14:05Z recovery pass built four-system packets that the inbox merge
        # took over the six-system ones (its veto compares only the systems
        # both packets carry), and all 45 D+1 P0s served without the two AI
        # ensembles until 16:03Z.  What the recovery pass must not do is
        # queue follow *captures* -- that gate stays below.
        follow_new_runs = follow_run.follow_enabled()
        if follow_new_runs:
            base_command.append("--follow-new-runs")
        # Charter 195 (四): the required-first recovery pass.
        for family_name in hold_families:
            base_command += ["--hold-family", str(family_name)]
        horizon = _utc_date(as_of_utc) - timedelta(days=1)
        republisher_inbox = (
            self.nwp_runtime_root / "native_ensemble_forward_inbox.json"
        )

        # ECMWF's S3 endpoint throttles sustained parallel range requests with
        # `503 Slow Down` and is therefore held to three workers; its GCS
        # replica serves the same official objects without that limit and is
        # allowed sixteen.  Since ECMWF dominates a capture (51 members), the
        # replica is what keeps four archives inside one deadline.
        capture_env = {
            **os.environ,
            "ECMWF_ARCHIVE_TRANSPORT_BASE_URL": ECMWF_GCS_REPLICA_BASE_URL,
        }

        # Charter 195 (二): every attempt, rung by rung, lands in the capture
        # attempt log (``_log_capture_attempt``); before it there was no way
        # to tell a run that was not up yet from a pass that never started.
        rung_trace: list[dict[str, Any]] = []
        family_runs: dict[str, str] = {}
        # Charter 195 (四): read once for the pass; a rung whose held required
        # family the probe sees still landing is waited for, not walked past.
        pass_probe_state = self._arrival_probe_state()
        network_held: list[str] = []
        network_failure: list[str] = []

        def _run_capture() -> dict[str, Any]:
            captured_run_init: str | None = None
            ingress_blocked = ""
            families_held: dict[str, str] = {}
            try:
                completed = None
                last_success = None
                for rung_index, (rung_lead, rung_cycle, rung_run_init) in enumerate(
                    run_ladder
                ):
                    attempt = base_command + [
                        "--lead-days", str(rung_lead),
                        "--gefs-output", str(
                            capture_root / f"gefs_{event_date}_d{rung_lead}.json"
                        ),
                        "--ecmwf-output", str(
                            capture_root / f"ecmwf_{event_date}_d{rung_lead}.json"
                        ),
                        "--eccc-output", str(
                            capture_root / f"eccc_{event_date}_d{rung_lead}.json"
                        ),
                        # ICON belongs with the others now.  It was held out
                        # while this lane asked per station, because its objects
                        # are whole global fields and a per-station rotation
                        # pulled the same ~543MiB once for each of them.  That
                        # was a property of the dispatch, not of the family:
                        # the pass now reads one run for every station the day
                        # lists, which is exactly what the separate daily lane
                        # was doing, so there is no longer a second lane to be
                        # separate from.
                        "--icon-output", str(
                            capture_root / f"icon_{event_date}_d{rung_lead}.json"
                        ),
                    ]
                    if rung_cycle is not None:
                        attempt += ["--run-cycle-hour", str(rung_cycle)]
                    rung_started = time.monotonic()
                    completed = subprocess.run(
                        attempt,
                        cwd=str(ROOT),
                        capture_output=True,
                        text=True,
                        timeout=OFFICIAL_NATIVE_CAPTURE_DEADLINE_SEC,
                        env=capture_env,
                    )
                    rung_trace.append({
                        "lead_days": int(rung_lead),
                        "cycle_hour": rung_cycle,
                        "run_init_utc": rung_run_init.isoformat().replace(
                            "+00:00", "Z"
                        ),
                        "returncode": completed.returncode,
                        "seconds": round(time.monotonic() - rung_started, 1),
                        "stderr_tail": (
                            (completed.stderr or "").strip()[-160:]
                            if completed.returncode != 0 else ""
                        ),
                        # The capture fails closed on its stdout receipt
                        # (``BLOCKED_FAIL_CLOSED`` + reason) with stderr empty,
                        # so without this an rc 2 said nothing about why.
                        "stdout_reason": (
                            _capture_stdout_reason(completed.stdout)
                            if completed.returncode != 0 else ""
                        ),
                    })
                    if completed.returncode != 0 and _capture_text_is_network(
                        completed.stderr
                    ):
                        # The network, not this rung: an older rung would meet
                        # the same dead path.  Stop, and let the day back off.
                        network_failure.append(
                            (completed.stderr or "").strip()[-200:]
                        )
                        break
                    if completed.returncode == 0:
                        rung_run_init_utc = (
                            rung_run_init.isoformat().replace("+00:00", "Z")
                        )
                        # The capture writes the training history itself and
                        # says so on its receipt.  A refusal there leaves the
                        # downloaded runs perfectly servable, so it must not
                        # look like a clean pass either: carry the reason up.
                        try:
                            receipt = json.loads(completed.stdout or "{}")
                        except (TypeError, ValueError):
                            receipt = {}
                        if isinstance(receipt, Mapping):
                            ingress_blocked = str(
                                receipt.get(
                                    "historical_ingress_blocked_reason"
                                ) or ""
                            )
                            held_by_family = receipt.get(
                                "family_held_on_earlier_run"
                            )
                            if isinstance(held_by_family, Mapping):
                                families_held = {
                                    str(name): str(value)
                                    for name, value in held_by_family.items()
                                }
                            served = _served_run_init_utc(receipt)
                            by_family = receipt.get("run_init_utc_by_family")
                            if isinstance(by_family, Mapping):
                                family_runs.update({
                                    str(name): str(value)
                                    for name, value in by_family.items()
                                })
                            # Charter 195 (三): what the object stores saved.
                            if rung_trace and isinstance(
                                receipt.get("nwp_object_store"), Mapping
                            ):
                                rung_trace[-1]["object_store"] = dict(
                                    receipt["nwp_object_store"]
                                )
                        else:
                            served = None
                        # What the families served, not what was asked for.
                        candidate = served or rung_run_init_utc
                        if (
                            captured_run_init is None
                            or candidate > captured_run_init
                        ):
                            captured_run_init = candidate
                        last_success = completed
                        # A required family that had to hold left this rung
                        # short of what was asked.  Walk down while a rung
                        # newer than what was actually served remains -- the
                        # publishers may serve that one -- and stop once the
                        # next rung would only re-read what is already in
                        # hand.  Judged from the receipt alone: process
                        # memory of the held run is empty after a restart,
                        # and the first pass after one is exactly when the
                        # question matters most.
                        next_rung = (
                            run_ladder[rung_index + 1]
                            if rung_index + 1 < len(run_ladder) else None
                        )
                        # Charter 195 (四): a required family held on the
                        # network, or held while the probe sees this rung's run
                        # still landing, is waited for -- the walk would only
                        # fetch an older run the newest will replace minutes
                        # later (09-22 07:50Z: ECMWF 00Z half on the replica,
                        # the pass fell to 09-21 18Z).
                        required_held = [
                            name for name in REQUIRED_CAPTURE_FAMILIES
                            if name in families_held
                        ]
                        network_held[:] = [
                            name for name in required_held
                            if _capture_text_is_network(families_held[name])
                        ]
                        still_landing = [
                            name for name in required_held
                            if _probe_run_publishing(
                                pass_probe_state,
                                family=name,
                                run_init=rung_run_init,
                                event_date=event_date,
                                now=datetime.now(timezone.utc),
                            )
                        ]
                        if network_held or still_landing:
                            break
                        if (
                            candidate < rung_run_init_utc
                            and next_rung is not None
                            and next_rung[2].isoformat().replace("+00:00", "Z")
                            > candidate
                        ):
                            continue
                        break
                if last_success is not None:
                    completed = last_success
                if last_success is None and network_failure:
                    return {
                        "state": "NETWORK_UNAVAILABLE",
                        "reason": network_failure[-1],
                    }
                if completed is None or completed.returncode != 0:
                    # The tail, not the head.  A child that dies on an
                    # exception prints a traceback whose last line is the only
                    # part that names the cause, and taking the first 200
                    # characters kept the banner and the frame while cutting
                    # exactly that -- five hours of "run_ladder_exhausted"
                    # receipts that could not say the database was full.
                    stderr_text = (
                        (completed.stderr if completed is not None else "")
                        or ""
                    ).strip()
                    stdout_reason = (
                        _capture_stdout_reason(completed.stdout)
                        if completed is not None else ""
                    )
                    return {
                        "state": "FAILED",
                        "reason": (
                            "run_ladder_exhausted:"
                            f"capture_exit_{completed.returncode if completed is not None else 'none'}:"
                            f"{stderr_text[-200:] or stdout_reason[-200:]}"
                        ),
                    }
            except subprocess.TimeoutExpired:
                # Overrunning is an ordinary outcome, not an error: the scope is
                # skipped and retried after its own floor.
                return {
                    "state": "DEADLINE_EXCEEDED",
                    "reason": (
                        "capture_exceeded_"
                        f"{OFFICIAL_NATIVE_CAPTURE_DEADLINE_SEC:.0f}s"
                    ),
                }
            except Exception as exc:
                return {
                    "state": "FAILED",
                    "reason": f"{type(exc).__name__}:{str(exc)[:200]}",
                }
            # Captures finish concurrently and all merge into one shared file,
            # so serialise the read-modify-write.
            try:
                with self._official_native_capture_merge_lock:
                    merged = _merge_official_native_inbox(
                        inbox_path,
                        staging_path=staging_inbox,
                        as_of_utc=as_of_utc,
                        # The scope set is bounded by the live market registry,
                        # not by whatever the republisher inbox happens to hold.
                        # Gating on the republisher meant a scope it had not yet
                        # covered could never accept its official packet: ZUUU
                        # 2026-08-07 was captured successfully and then silently
                        # dropped at merge, leaving the station with no P0 at
                        # all.  Official capture exists precisely to cover what
                        # the republisher cannot.
                        allowed_scopes=_active_registry_scopes(
                            registry_path,
                            horizon=horizon,
                        ),
                        # Read here rather than inside the merge so the merge
                        # stays a pure function of what it is handed.
                        fitted_lead_buckets=_fitted_lead_buckets(
                            self.conn, as_of_utc=as_of_utc
                        ),
                    )
            except Exception as exc:
                return {
                    "state": "MERGE_FAILED",
                    "reason": f"{type(exc).__name__}:{str(exc)[:200]}",
                }
            if follow_new_runs and not hold_families:
                # Charter 192: bank the newer ICON/ECCC runs this ladder
                # reaches, after the pass's packets are merged and on a lane
                # of their own, so the download never delays the ECMWF/GEFS
                # run the pass was for.
                self._enqueue_follow_run_capture(
                    event_date=event_date,
                    run_ladder=run_ladder,
                    registry_path=registry_path,
                    capture_root=capture_root,
                    env=capture_env,
                )
            return {
                "state": "CAPTURED",
                "inbox_packet_count": merged["packet_count"],
                "pruned_packet_count": merged["pruned"],
                # Charter 193 (三): staged packets not merged because a system
                # in them was on an older run than the packet in service.
                "merge_refused_older_systems": dict(
                    merged.get("refused_older_systems") or {}
                ),
                # Which run this scope actually got, so a reader can tell a
                # fresh rung from a fallback without re-deriving the ladder.
                "captured_run_init_utc": captured_run_init,
                # Which families could not serve the rung and kept what they
                # had.  A pass where this is full and the run did not move is
                # a pass that refreshed the packet clock and nothing else.
                "families_held_on_earlier_run": families_held,
                # Served, but not archived: the runs above are merged and will
                # be compiled, while the training history stayed where it was.
                "historical_ingress_blocked_reason": ingress_blocked,
                # Charter 195 (四): required families that held on the network.
                "network_held_families": list(network_held),
                "hold_families": list(hold_families),
            }

        trigger = (
            f"recovery:{'required' if hold_families else 'full'}"
            if isinstance(arrival, Mapping) and arrival.get("family") == "recovery"
            else "listing_follow_reseat"
            if isinstance(arrival, Mapping)
            and arrival.get("family") == "listing_follow_reseat"
            else f"arrival:{arrival.get('family')}|{arrival.get('run_init_utc')}"
            if isinstance(arrival, Mapping)
            else f"listing:{listing_key[1]}" if listing_new and listing_key
            else "rotation"
        )
        attempt_started_utc = utc_now()

        def _logged_capture() -> dict[str, Any]:
            started = time.monotonic()
            try:
                outcome = _run_capture()
            except Exception as exc:  # noqa: BLE001 -- recorded, then raised
                outcome = {
                    "state": "FAILED",
                    "reason": f"{type(exc).__name__}:{str(exc)[:200]}",
                }
            outcome = {
                **outcome,
                "run_init_utc_by_family": dict(family_runs),
                "rung_trace": list(rung_trace),
            }
            self._log_capture_attempt({
                "event_date": event_date,
                "trigger": trigger,
                "started_at_utc": attempt_started_utc,
                "finished_at_utc": utc_now(),
                "seconds": round(time.monotonic() - started, 1),
                "state": str(outcome.get("state") or ""),
                "reason": str(outcome.get("reason") or "")[:200],
                "captured_run_init_utc": outcome.get("captured_run_init_utc"),
                "run_init_utc_by_family": dict(family_runs),
                "families_held_on_earlier_run": dict(
                    outcome.get("families_held_on_earlier_run") or {}
                ),
                "network_held_families": list(
                    outcome.get("network_held_families") or ()
                ),
                "hold_families": list(hold_families),
                "merge_refused_older_systems": dict(
                    outcome.get("merge_refused_older_systems") or {}
                ),
                "rungs": list(rung_trace),
            })
            return outcome

        future = self._official_native_capture_pool.submit(_logged_capture)
        inflight[scope_key] = future
        return {
            "state": "SUBMITTED",
            "station_id": station_id,
            "event_date": event_date,
            "trigger": trigger,
            "in_flight": len(inflight),
            "last_completed": dict(results_by_date.get(event_date) or {}),
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }

    def _enqueue_follow_run_capture(
        self,
        *,
        event_date: str,
        run_ladder: Sequence[tuple[int, int | None, datetime]],
        registry_path: Path,
        capture_root: Path,
        env: Mapping[str, str],
    ) -> str:
        """Charter 192: queue the follow-run capture for one event date.

        One worker, one date at a time: a follow capture pulls up to ~0.5GiB
        of ICON through DWD's open-data server, whose connection ceiling sits
        near 24 (16 per pass already), so follow captures never stack and
        each asks with half a pass's connections.  A date already queued is
        not queued twice; its job reads every rung it was given.
        """

        rungs = [
            (int(lead), cycle)
            for lead, cycle, _run_init in run_ladder
            if any(
                follow_run.follow_cycle_for_rung(family, int(lead), cycle)
                is not None
                for family in follow_run.FOLLOW_FAMILIES
            )
        ]
        # Charter 193 amendment: a run followed per event date (ECMWF D-3 18Z)
        # is asked for until its file is on disk, whatever the rungs.
        event_run_missing = any(
            not follow_run.follow_archive_path(
                capture_root, family, event_date, lead, hour
            ).is_file()
            for family in follow_run.EVENT_RUN_FAMILIES
            for lead, hour in follow_run.event_follow_runs(family)
        )
        # Charter 263 (四): ... or its file is on disk without a station
        # listed since, which the job's revisit adds.  Each gap is asked about
        # once: a supplement that fails leaves the same gap, and re-queueing
        # it every pass would re-download for nothing; the arrival and rung
        # triggers keep queueing the job as they always did.
        new_gaps = self._unfollowed_event_run_gaps(
            event_date=event_date,
            registry_path=registry_path,
            capture_root=capture_root,
        )
        if not rungs and not event_run_missing and not new_gaps:
            return "NO_FOLLOW_RUNG"
        with _FOLLOW_LANE_LOCK:
            pool = getattr(self, "_official_native_follow_pool", None)
            if pool is None:
                pool = ThreadPoolExecutor(
                    max_workers=1,
                    thread_name_prefix="official-native-follow",
                )
                self._official_native_follow_pool = pool
            queued: dict[str, Any] = getattr(
                self, "_official_native_follow_inflight", None
            ) or {}
            self._official_native_follow_inflight = queued
            for key in [key for key, fut in queued.items() if fut.done()]:
                queued.pop(key, None)
            if event_date in queued:
                return "ALREADY_QUEUED"
            command = [
                sys.executable,
                str(
                    ROOT / "scripts"
                    / "capture_official_native_ensemble_forward.py"
                ),
                "--follow-capture-only",
                "--event-date", event_date,
                "--market-registry", str(registry_path),
                "--capture-root", str(capture_root),
                "--timeout-seconds", str(OFFICIAL_NATIVE_CAPTURE_TIMEOUT_SEC),
                "--icon-download-workers", str(FOLLOW_ICON_DOWNLOAD_WORKERS),
                "--commit",
            ]
            for lead, cycle in rungs:
                command += [
                    "--follow-rung",
                    f"{lead}:{'default' if cycle is None else cycle}",
                ]
            follow_env = dict(env)

            def _run_follow() -> dict[str, Any]:
                try:
                    completed = subprocess.run(
                        command,
                        cwd=str(ROOT),
                        capture_output=True,
                        text=True,
                        timeout=FOLLOW_RUN_CAPTURE_DEADLINE_SEC,
                        env=follow_env,
                    )
                except subprocess.TimeoutExpired:
                    return {"state": "DEADLINE_EXCEEDED"}
                except Exception as exc:  # noqa: BLE001 - never the pass's
                    return {
                        "state": "FAILED",
                        "reason": f"{type(exc).__name__}:{str(exc)[:200]}",
                    }
                try:
                    receipt = json.loads(completed.stdout or "{}")
                except (TypeError, ValueError):
                    receipt = {}
                outcome = {
                    "state": (
                        str(receipt.get("state") or "")
                        if completed.returncode == 0
                        else "FAILED"
                    ),
                    "returncode": completed.returncode,
                    "receipt": receipt if isinstance(receipt, Mapping) else {},
                    "stderr_tail": (completed.stderr or "").strip()[-200:],
                }
                # The newest outcome per date, for whoever asks what the
                # follow lane last did (the futures are reaped on the next
                # queue).
                with _FOLLOW_LANE_LOCK:
                    last = getattr(
                        self, "_official_native_follow_last_result_by_date", None
                    )
                    if last is None:
                        last = {}
                        self._official_native_follow_last_result_by_date = last
                    last[event_date] = outcome
                return outcome

            queued[event_date] = pool.submit(_run_follow)
            if new_gaps:
                # Recorded only once the job that reads them is queued: one
                # already running started from an older registry and may not
                # hold the new stations, so its gap is asked about again.
                seen = getattr(
                    self, "_official_native_follow_gaps_seen", None
                )
                if seen is None:
                    seen = set()
                    self._official_native_follow_gaps_seen = seen
                seen.update(new_gaps)
                # The packets are built by a pass, not by the follow job: the
                # listing step re-runs the day's pass once this job is done.
                reseat = getattr(
                    self, "_official_native_follow_reseat", None
                )
                if reseat is None:
                    reseat = {}
                    self._official_native_follow_reseat = reseat
                reseat[event_date] = sorted({gap[1] for gap in new_gaps})
        return "QUEUED"

    def _unfollowed_event_run_gaps(
        self,
        *,
        event_date: str,
        registry_path: Path,
        capture_root: Path,
    ) -> set[tuple[str, str, tuple[str, ...]]]:
        """Charter 263 (四): event-run station gaps no follow job has been given.

        ``(event_date, file name, missing stations)`` for every held event-run
        file (``follow_run.event_run_station_gaps``) lacking a station the
        forward registry lists for the day and the run covers -- the same
        listing ``capture_follow_runs`` reads (active, source-eligible rows)
        -- less the gaps already handed to a queued job.  Never raises: a gap
        check that cannot read leaves the follow lane exactly as it was.
        """

        try:
            registry = load_market_registry_snapshot(registry_path)
            station_timezones: dict[str, str] = {}
            for row in registry.get("rows") or ():
                if not isinstance(row, Mapping):
                    continue
                if (
                    str(row.get("event_date") or "") != str(event_date)
                    or int(row.get("market_active") or 0) != 1
                    or int(row.get("source_eligible") or 0) != 1
                ):
                    continue
                station = str(row.get("station_id") or "").strip().upper()
                zone = str(row.get("settlement_timezone") or "").strip()
                if station and zone:
                    station_timezones.setdefault(station, zone)
            if not station_timezones:
                return set()
            gaps = follow_run.event_run_station_gaps(
                capture_root,
                event_date=str(event_date),
                station_timezones=station_timezones,
                as_of=datetime.now(timezone.utc),
            )
        except Exception:  # noqa: BLE001 - the follow lane's other triggers stand
            return set()
        seen = getattr(self, "_official_native_follow_gaps_seen", None) or set()
        return {
            (str(event_date), str(gap["path"]), tuple(gap["missing_station_ids"]))
            for gap in gaps
        } - seen

    def _metar_trajectory_training_due(
        self, *, station_id: str
    ) -> tuple[bool, str, str]:
        """Whether this station's newest settled day lacks artifact coverage.

        Returns ``(due, settlement_timezone, latest_truth_day)``.  Coverage is
        judged against ``trained_through_utc`` of the newest trajectory
        artifact: folds only exist for settled days, so an artifact trained
        through the latest settled day's close cannot gain evidence until the
        next day settles, and rerunning the gate before then is a no-op by
        construction.
        """

        # The read-only handle: this runs on the network-prefetch worker, which
        # deliberately holds no write connection to the target SSOT.  Requiring
        # ``commit_conn`` here silently reported NOT_CONFIGURED on every cycle
        # and the pass never fired.  All queries in this method are reads; the
        # only write in the chain is the fit subprocess's own gated commit.
        read_conn = getattr(self, "conn", None) or self.commit_conn
        if read_conn is None:
            return False, "", ""
        row = read_conn.execute(
            "SELECT settlement_timezone, MAX(local_date) "
            "FROM calibration_station_daily_high_truth "
            "WHERE station_id=? AND qc_status='ACCEPTED'",
            (station_id,),
        ).fetchone()
        if row is None or not row[0] or not row[1]:
            return False, "", ""
        timezone_name, latest_day = str(row[0]), str(row[1])
        day_end = settlement_day_window(latest_day, timezone_name)[
            "target_day_end_utc"
        ]
        covered = read_conn.execute(
            "SELECT MAX(trained_through_utc) "
            "FROM basket_probability_evidence_artifact "
            "WHERE station_id=? AND artifact_kind='METAR_TRAJECTORY_LIKELIHOOD'",
            (station_id,),
        ).fetchone()
        newest = str((covered or [None])[0] or "")
        if not newest:
            return True, timezone_name, latest_day
        # Parsed, not lexicographic: trained_through carries milliseconds and
        # the settlement window does not, and "…00.000Z" sorts before "…00Z"
        # as text -- a covered station would look forever due.
        try:
            covered_at = datetime.fromisoformat(newest.replace("Z", "+00:00"))
            closes_at = datetime.fromisoformat(
                str(day_end).replace("Z", "+00:00")
            )
        except ValueError:
            return True, timezone_name, latest_day
        # Content-window artifacts stamp trained_through one second inside
        # the newest fold day's close (see the training packet builder), so
        # coverage is judged against the same instant; comparing against the
        # exact close would find every fresh artifact forever due.  A stamp
        # strictly past the close can only be the retired wall-clock
        # semantics -- a content window ends inside its own day -- and such
        # an artifact trips the serve-side leakage gate for every event day
        # that began before the sweep ran, so it is due one refit now rather
        # than after the next day settles (12 stations spent 2026-08-20
        # locked out of P1 rebase waiting exactly that long).  A stamp
        # exactly at the close remains covered, as it always was.
        if covered_at < closes_at - timedelta(seconds=1) or (
            covered_at > closes_at
        ):
            return True, timezone_name, latest_day
        # Training coverage is not the only way an artifact stops being
        # servable.  The consumer builds its scope key from the P0 root's
        # own ``season_bin``, so an artifact emitted under a different
        # season label is unreachable however current its folds are -- and
        # the miss is silent, falling back to applied strength 0.  That is
        # what charter 62 did on 2026-08-25: the lineage moved to the
        # station-local vocabulary, every artifact still answered to the
        # calendar trigram, and P1's soft likelihood went from 72% coverage
        # to nil in two days without a single blocker being recorded.  A
        # season the serving side no longer asks for is staleness, and this
        # is where staleness is decided.
        served_season = station_season_bin(station_id, latest_day)
        emitted = read_conn.execute(
            "SELECT scope_key FROM basket_probability_evidence_artifact"
            " WHERE station_id=? AND artifact_kind='METAR_TRAJECTORY_LIKELIHOOD'"
            " ORDER BY trained_through_utc DESC LIMIT 1",
            (station_id,),
        ).fetchone()
        if emitted is not None and str(emitted[0] or ""):
            parts = str(emitted[0]).split("|")
            if len(parts) > 1 and parts[1] != served_season:
                return True, timezone_name, latest_day
        return False, timezone_name, latest_day

    def _run_metar_trajectory_training(
        self, *, as_of_utc: str
    ) -> dict[str, Any]:
        """Run the packet->fit->gated-persist chain for one due station.

        One station per cycle, rotated, on its own single-worker pool -- the
        same shape as the ICON daily pass.  The subprocesses read the target
        SSOT and canonical archive and only the fit's ``--commit`` step writes,
        through the evidence store's validated inserts.
        """

        boundary = {
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }
        if (
            (getattr(self, "conn", None) is None and self.commit_conn is None)
            or self.canonical_source_db_path is None
            or not self.station_allowlist
        ):
            return {"state": "NOT_CONFIGURED", **boundary}
        inflight = getattr(self, "_metar_trajectory_inflight", None)
        if inflight is not None and not inflight.done():
            return {"state": "IN_FLIGHT", **boundary}
        cursor = int(getattr(self, "_metar_trajectory_station_cursor", 0))
        throttle: dict[str, float] = getattr(
            self, "_metar_trajectory_attempts", None
        ) or {}
        self._metar_trajectory_attempts = throttle
        now_mono = time.monotonic()
        chosen: tuple[str, str, str] | None = None
        for offset in range(len(self.station_allowlist)):
            station = self.station_allowlist[
                (cursor + offset) % len(self.station_allowlist)
            ]
            last = throttle.get(station)
            if (
                last is not None
                and now_mono - last < METAR_TRAJECTORY_TRAINING_RETRY_SEC
            ):
                continue
            try:
                due, timezone_name, latest_day = (
                    self._metar_trajectory_training_due(station_id=station)
                )
            except Exception:
                continue
            if due:
                chosen = (station, timezone_name, latest_day)
                self._metar_trajectory_station_cursor = (
                    cursor + offset + 1
                ) % len(self.station_allowlist)
                break
        if chosen is None:
            self._metar_trajectory_station_cursor = (
                cursor + 1
            ) % len(self.station_allowlist)
            return {"state": "NOT_DUE", **boundary}
        station, timezone_name, latest_day = chosen
        throttle[station] = now_mono
        generation = 1 + int(
            (getattr(self, "conn", None) or self.commit_conn).execute(
                "SELECT COUNT(*) FROM basket_probability_evidence_artifact "
                "WHERE station_id=? "
                "AND artifact_kind='METAR_TRAJECTORY_LIKELIHOOD'",
                (station,),
            ).fetchone()[0]
        )
        target_db = str(self.db_path)
        archive_db = str(self.canonical_source_db_path)
        work_root = self.nwp_runtime_root / "metar_trajectory_training"
        work_root.mkdir(parents=True, exist_ok=True)
        valid_until = (
            datetime.fromisoformat(as_of_utc.replace("Z", "+00:00"))
            + timedelta(days=METAR_TRAJECTORY_ARTIFACT_VALID_DAYS)
        ).astimezone(timezone.utc).isoformat(
            timespec="milliseconds"
        ).replace("+00:00", "Z")

        def _train() -> dict[str, Any]:
            outcomes: list[dict[str, Any]] = []
            for bucket in METAR_TRAJECTORY_TRAINING_BUCKETS:
                prefix = work_root / f"{station}_{bucket.lower()}"
                packet_path = Path(f"{prefix}_packet.json")
                build = subprocess.run(
                    [
                        sys.executable,
                        str(
                            ROOT
                            / "scripts"
                            / "build_bayes_basket_target_metar_trajectory_training_packet.py"
                        ),
                        "--target-db", target_db,
                        "--archive-db", archive_db,
                        "--station-id", station,
                        "--settlement-timezone", timezone_name,
                        "--local-time-bucket", bucket,
                        "--decided-at-utc", as_of_utc,
                        "--valid-from-utc", as_of_utc,
                        "--valid-until-utc", valid_until,
                        "--generation", str(generation),
                        # Fold cutoffs anchor to the first report after the
                        # bucket start, matching how runtime P1 is actually
                        # evaluated -- and without it every sparse-archive day
                        # (5 reports/day before 2026-08-01) fails the
                        # bucket-start prefix requirement outright.
                        "--anchor-to-first-report",
                        # Physical conditioning only (user ruling,
                        # 2026-08-21): the layer predicts the day's maximum
                        # from observed METAR state, it does not redistribute
                        # around the model's own curve.  Newly fitted
                        # artifacts carry the physical method; incumbent
                        # hourly-curve activations keep serving their scopes
                        # until a physical fit outranks them by generation,
                        # which is the codebase's standing cutover rule.
                        "--method", "physical",
                        "--output", str(packet_path),
                    ],
                    cwd=str(ROOT),
                    capture_output=True,
                    text=True,
                    timeout=METAR_TRAJECTORY_TRAINING_DEADLINE_SEC,
                )
                if build.returncode != 0:
                    outcomes.append({
                        "local_time_bucket": bucket,
                        "state": "PACKET_FAILED",
                        "reason": (build.stderr or "").strip()[-200:],
                    })
                    continue
                fit = subprocess.run(
                    [
                        sys.executable,
                        str(
                            ROOT
                            / "scripts"
                            / "build_bayes_basket_target_metar_trajectory_oos.py"
                        ),
                        "--input", str(packet_path),
                        "--output", str(Path(f"{prefix}_artifact.json")),
                        "--packet-output", str(Path(f"{prefix}_oos.json")),
                        "--db", target_db,
                        "--commit",
                    ],
                    cwd=str(ROOT),
                    capture_output=True,
                    text=True,
                    timeout=METAR_TRAJECTORY_TRAINING_DEADLINE_SEC,
                )
                if fit.returncode != 0:
                    # A nonzero exit covers two very different situations, and
                    # the packet output tells them apart: BLOCKED_EVIDENCE is
                    # the gate saying "not enough curve-complete folds yet",
                    # which is the expected state for every station whose
                    # recent days have not settled -- an error label there
                    # would make the receipt cry wolf on all 45 stations.
                    blocked_reason = ""
                    try:
                        blocked = json.loads(
                            Path(f"{prefix}_oos.json").read_text(
                                encoding="utf-8"
                            )
                        )
                        if blocked.get("state") == "BLOCKED_EVIDENCE":
                            blocked_reason = str(blocked.get("reason") or "")
                    except Exception:
                        pass
                    outcomes.append({
                        "local_time_bucket": bucket,
                        "state": (
                            "BLOCKED_EVIDENCE"
                            if blocked_reason
                            else "FIT_FAILED"
                        ),
                        "reason": (
                            blocked_reason
                            or (fit.stderr or "").strip()[-200:]
                        ),
                    })
                    continue
                summary: dict[str, Any] = {}
                try:
                    summary = json.loads(
                        (fit.stdout or "").strip().splitlines()[-1]
                    )
                except Exception:
                    pass
                outcomes.append({
                    "local_time_bucket": bucket,
                    "state": (
                        "PROMOTED"
                        if summary.get("oos_gate_passed")
                        else "GATE_REJECTED"
                    ),
                    "artifact_id": summary.get("artifact_id"),
                    "ingress": summary.get("ingress"),
                })
            result = {
                "station_id": station,
                "latest_truth_day": latest_day,
                "generation": generation,
                "outcomes": outcomes,
            }
            self._metar_trajectory_last_result = result
            return result

        pool = getattr(self, "_metar_trajectory_pool", None)
        if pool is None:
            self._metar_trajectory_pool = ThreadPoolExecutor(
                max_workers=1,
                thread_name_prefix="metar-trajectory-training",
            )
            pool = self._metar_trajectory_pool
        self._metar_trajectory_inflight = pool.submit(_train)
        return {
            "state": "SUBMITTED",
            "station_id": station,
            "latest_truth_day": latest_day,
            "last_completed": dict(
                getattr(self, "_metar_trajectory_last_result", {}) or {}
            ),
            **boundary,
        }

    def _preclear_pending_corrections(
        self, *, as_of_utc: str
    ) -> dict[str, Any]:
        """Clear live correction halts before P1 compiles, in this cycle.

        Corrections land on seven to seventeen stations every day, and each
        one fail-closes its station-day's P1 until a review receipt exists.
        Every prior clearing agent was a timer -- a six-hour worker pass, a
        hosted sweep in a contended lane -- so the halt's duration was set
        by scheduler health, measured at forty-three minutes median and
        sixteen hours worst.  The condition is knowable before P1 runs for
        the price of one indexed count, and the policy run itself is around
        a second, so the cycle clears its own path: detect, run the standing
        policy synchronously, then compile P1 against a clean gate.  The
        timers stay as backstops; a genuine conflict still refuses and still
        halts, which is that gate's job.
        """

        boundary = {
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }
        if self.canonical_source_conn is None:
            return {"state": "NOT_CONFIGURED", **boundary}
        try:
            pending = pending_correction_review_count(
                self.canonical_source_conn, as_of_utc=as_of_utc
            )
        except Exception as exc:  # noqa: BLE001
            return {
                "state": "PROBE_FAILED",
                "reason": f"{type(exc).__name__}:{str(exc)[:160]}",
                **boundary,
            }
        if pending <= 0:
            return {"state": "NOTHING_PENDING", "pending": 0, **boundary}
        inflight = getattr(self, "_correction_auto_clear_inflight", None)
        if inflight is not None and not inflight.done():
            # The six-hour pass is already running; wait for it rather than
            # racing a second policy subprocess against the same archive.
            try:
                inflight.result(timeout=CORRECTION_PRECLEAR_DEADLINE_SEC)
            except Exception as exc:  # noqa: BLE001
                return {
                    "state": "INFLIGHT_WAIT_FAILED",
                    "pending": pending,
                    "reason": f"{type(exc).__name__}:{str(exc)[:160]}",
                    **boundary,
                }
            return {"state": "INFLIGHT_COMPLETED", "pending": pending, **boundary}
        since = (
            datetime.fromisoformat(as_of_utc.replace("Z", "+00:00"))
            .astimezone(timezone.utc)
            .date()
            - timedelta(days=CORRECTION_PRECLEAR_WINDOW_DAYS)
        ).isoformat()
        command = [
            sys.executable,
            str(
                ROOT / "scripts" / "auto_clear_pending_correction_reviews.py"
            ),
            "--archive-db", str(self.canonical_source_db_path),
            "--target-db", str(self.db_path),
            "--since", since,
            "--as-of-utc", as_of_utc,
            "--commit",
        ]
        try:
            completed = subprocess.run(
                command,
                cwd=str(ROOT),
                capture_output=True,
                text=True,
                timeout=CORRECTION_PRECLEAR_DEADLINE_SEC,
            )
        except Exception as exc:  # noqa: BLE001
            return {
                "state": "FAILED",
                "pending": pending,
                "reason": f"{type(exc).__name__}:{str(exc)[:160]}",
                **boundary,
            }
        # A completed pre-clear satisfies the six-hour pass's purpose for
        # this window, so stamp its throttle rather than letting both run.
        self._correction_auto_clear_last_mono = time.monotonic()
        summary: dict[str, Any] = {}
        try:
            summary = json.loads(
                (completed.stdout or "").strip().splitlines()[-1]
            )
        except Exception:  # noqa: BLE001
            pass
        return {
            "state": "CLEARED" if completed.returncode == 0 else "PARTIAL",
            "pending": pending,
            "since": since,
            "cleared_scope_count": summary.get("cleared_scope_count"),
            "cleared_observation_count": summary.get(
                "cleared_observation_count"
            ),
            "skipped_count": summary.get("skipped_count"),
            "stderr": (completed.stderr or "").strip()[-200:],
            **boundary,
        }

    def _materialize_truth_increment(
        self, *, as_of_utc: str
    ) -> dict[str, Any]:
        """Materialize settled truth for the live edge, inside the cycle.

        Truth's only retry engine was a timer-driven sweep in a contended
        maintenance lane, so its freshness was set by scheduler health --
        starved by launchd stacking once, by lane oversubscription once,
        and by five deploy restarts in one day resetting its queue place.
        Coverage never actually broke (449 of 450 recent station-days have
        truth), but the engine's staleness alarm fired every deploy day
        because nothing else would have retried.  The cycle is the one loop
        with a heartbeat and a watchdog, so it now materializes newly
        closed station-days itself: the same per-scope materializer, a
        short window, a hard cap per cycle.  The hosted sweep keeps the
        forty-five-day deep window and remains the backstop.
        """

        boundary = {
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }
        if self.commit_conn is None or self.canonical_source_conn is None:
            return {"state": "NOT_CONFIGURED", **boundary}
        window_start = str(
            (
                datetime.fromisoformat(as_of_utc.replace("Z", "+00:00"))
                .astimezone(timezone.utc)
                - timedelta(days=TRUTH_INCREMENT_WINDOW_DAYS)
            ).date()
        )
        # Who is owed a truth row: a registry scope that some snapshot called
        # eligible, inside the window, with no accepted truth yet -- the same
        # question as always, asked without reading the registry table.
        #
        # It was one statement over the whole registry, and no index let it
        # avoid reading every row's table page: 23-25s on 2026-09-14, every
        # cycle this stage ran.  It also handed back the scopes it could never
        # write -- today's and the listed days, whose settlement days have not
        # closed -- and they sort first once the older days all hold truth, so
        # the stage spent 43-204 seconds a turn asking twelve of them and
        # recording ``skipped_open_settlement_day`` twelve times.  Both halves
        # now come from the per-snapshot registry answers, and a scope whose
        # day is still open in every timezone the registry has named for it is
        # set aside before the cap rather than after it: the materializer would
        # skip it on that same comparison, so nothing it could write is lost,
        # and a closed day behind it is no longer kept waiting.
        try:
            truth_scopes = {
                (str(row[0]), str(row[1]))
                for row in self.commit_conn.execute(
                    "SELECT DISTINCT station_id, local_date"
                    " FROM calibration_station_daily_high_truth"
                    " WHERE qc_status='ACCEPTED' AND local_date>=?",
                    (window_start,),
                )
            }
            eligible = registry_eligible_scopes(self.commit_conn)
            zones_by_scope: dict[tuple[str, str], set[str]] = {}
            for zone_station, zone_day, zone in (
                registry_scope_timezone_triples(self.commit_conn)
            ):
                zones_by_scope.setdefault(
                    (str(zone_station), str(zone_day)), set()
                ).add(str(zone or ""))
            as_of_clock = datetime.fromisoformat(
                as_of_utc.replace("Z", "+00:00")
            ).astimezone(timezone.utc)
            pending: list[tuple[str, str]] = []
            not_closed = 0
            for day, station in sorted(
                (str(day), str(station))
                for station, day in eligible
                if station is not None and day is not None
            ):
                if day < window_start or (station, day) in truth_scopes:
                    continue
                if _settlement_day_open_in_every_zone(
                    day, zones_by_scope.get((station, day), set()), as_of_clock
                ):
                    not_closed += 1
                    continue
                # The probe above finds any registry row that ever said
                # eligible.  The sweep asks the same question and has to get
                # the same answer, or the two engines disagree about who is
                # owed a truth row: a scope the registry has since stopped
                # admitting would leave the sweep and come straight back here.
                # See ``registry_scope_still_eligible``.
                if not registry_scope_still_eligible(
                    self.commit_conn, station_id=station, event_date=day
                ):
                    continue
                pending.append((station, day))
                if len(pending) >= TRUTH_INCREMENT_MAX_SCOPES:
                    break
        except sqlite3.OperationalError as exc:
            return {
                "state": "PROBE_FAILED",
                "reason": f"{type(exc).__name__}:{str(exc)[:160]}",
                **boundary,
            }
        outcomes: dict[str, int] = {}
        refusals: dict[str, int] = {}
        committed: list[str] = []
        for station, day in pending:
            try:
                result = materialize_settled_station_truth(
                    self.commit_conn,
                    self.canonical_source_conn,
                    station_id=str(station),
                    event_date=str(day),
                    as_of_utc=as_of_utc,
                )
            except sqlite3.OperationalError as exc:
                if "locked" in str(exc) or "busy" in str(exc):
                    outcomes["deferred_locked"] = (
                        outcomes.get("deferred_locked", 0) + 1
                    )
                    self.commit_conn.rollback()
                    continue
                raise
            except ContractError as exc:
                reason = str(exc).split(":", 1)[0].strip() or "unknown"
                refusals[reason] = refusals.get(reason, 0) + 1
                outcomes["refused"] = outcomes.get("refused", 0) + 1
                self.commit_conn.rollback()
                continue
            state = str(result.get("state") or "unknown")
            outcomes[state] = outcomes.get(state, 0) + 1
            if result.get("wrote"):
                self.commit_conn.commit()
                committed.append(f"{station}|{day}")
            else:
                self.commit_conn.rollback()
        return {
            "state": "COMMITTED" if not pending or committed or all(
                key in {
                    "skipped_open_settlement_day", "refused", "idempotent",
                    "deferred_locked",
                }
                for key in outcomes
            ) else "PARTIAL",
            "checked_at_utc": as_of_utc,
            "window_start": window_start,
            "backlog": len(pending),
            # Owed a row but not yet writable: the settlement day is still open.
            "not_closed_scope_count": not_closed,
            "outcomes": outcomes,
            "refusals": refusals,
            "committed_scopes": committed[:12],
            **boundary,
        }

    def _run_correction_auto_clear(self, *, as_of_utc: str) -> dict[str, Any]:
        """Resolve pending correction halts by standing policy, on a schedule.

        The decision each correction gets follows from the report itself and is
        checked against the stored evidence, so this schedules an existing
        policy rather than deciding anything here.  It runs as a subprocess
        because the receipts belong in the canonical archive, which this worker
        holds read-only by design.
        """

        boundary = {
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }
        if self.canonical_source_db_path is None:
            return {"state": "NOT_CONFIGURED", **boundary}
        inflight = getattr(self, "_correction_auto_clear_inflight", None)
        if inflight is not None and not inflight.done():
            return {"state": "IN_FLIGHT", **boundary}
        now_mono = time.monotonic()
        last_attempt = getattr(self, "_correction_auto_clear_last_mono", None)
        if (
            last_attempt is not None
            and now_mono - last_attempt < CORRECTION_AUTO_CLEAR_RETRY_SEC
        ):
            return {
                "state": "THROTTLED",
                "retry_in_seconds": round(
                    CORRECTION_AUTO_CLEAR_RETRY_SEC - (now_mono - last_attempt),
                    1,
                ),
                **boundary,
            }
        self._correction_auto_clear_last_mono = now_mono
        since = (
            datetime.fromisoformat(as_of_utc.replace("Z", "+00:00"))
            .astimezone(timezone.utc)
            .date()
            - timedelta(days=CORRECTION_AUTO_CLEAR_WINDOW_DAYS)
        ).isoformat()
        command = [
            sys.executable,
            str(
                ROOT / "scripts" / "auto_clear_pending_correction_reviews.py"
            ),
            "--archive-db", str(self.canonical_source_db_path),
            "--target-db", str(self.db_path),
            "--since", since,
            "--as-of-utc", as_of_utc,
            "--commit",
        ]

        def _run() -> dict[str, Any]:
            try:
                completed = subprocess.run(
                    command,
                    cwd=str(ROOT),
                    capture_output=True,
                    text=True,
                    timeout=CORRECTION_AUTO_CLEAR_DEADLINE_SEC,
                )
            except Exception as exc:
                result = {
                    "state": "FAILED",
                    "reason": f"{type(exc).__name__}:{str(exc)[:200]}",
                }
                self._correction_auto_clear_last_result = result
                return result
            summary: dict[str, Any] = {}
            try:
                summary = json.loads(
                    (completed.stdout or "").strip().splitlines()[-1]
                )
            except Exception:
                pass
            result = {
                "state": "CLEARED" if completed.returncode == 0 else "PARTIAL",
                "since": since,
                "candidate_scope_count": summary.get("candidate_scope_count"),
                "cleared_scope_count": summary.get("cleared_scope_count"),
                "cleared_observation_count": summary.get(
                    "cleared_observation_count"
                ),
                "skipped_count": summary.get("skipped_count"),
                "stderr": (completed.stderr or "").strip()[-200:],
            }
            self._correction_auto_clear_last_result = result
            return result

        pool = getattr(self, "_correction_auto_clear_pool", None)
        if pool is None:
            self._correction_auto_clear_pool = ThreadPoolExecutor(
                max_workers=1,
                thread_name_prefix="correction-auto-clear",
            )
            pool = self._correction_auto_clear_pool
        self._correction_auto_clear_inflight = pool.submit(_run)
        return {
            "state": "SUBMITTED",
            "since": since,
            "last_completed": dict(
                getattr(self, "_correction_auto_clear_last_result", {}) or {}
            ),
            **boundary,
        }

    def _historical_taf_capture_stations(self) -> list[str]:
        """The allowlisted stations whose TAF has ever carried a TX group.

        ``TX``/``TN`` are optional in a TAF and a large part of the network --
        every US station among them -- simply never publishes them.  Those
        stations cannot produce a calibration sample no matter how often they
        are captured, and the AWC response budget is shared, so spending it on
        them takes it from the stations that can.

        Derived from what the archive has actually yielded rather than from a
        hardcoded list, so a station that starts publishing TX is picked up.
        Before anything has been captured the question cannot be answered yet,
        and the whole allowlist is tried once.
        """

        allowlist = list(getattr(self, "station_allowlist", ()) or ())
        read_conn = getattr(self, "conn", None) or self.commit_conn
        if read_conn is None or not allowlist:
            return allowlist
        try:
            rows = read_conn.execute(
                "SELECT DISTINCT station_id "
                "FROM calibration_historical_taf_capture "
                "WHERE tx_c IS NOT NULL"
            ).fetchall()
        except Exception:
            return allowlist
        yielded = {str(row[0]).strip().upper() for row in rows}
        if not yielded:
            return allowlist
        return [station for station in allowlist if station in yielded]

    def _identify_live_observations(self) -> dict[str, Any]:
        """Canonically identify the live window's reports, inside the cycle.

        P1's atomic root is the observation contract, and its lineage must
        carry that observation's truth-revision hash before the station-day
        can become an atomic fact.  The lane that mints those hashes ran as a
        hosted sweep on a ten-minute contract -- and the SSOT is an exclusive
        write domain that admits one sweep per turn, so a ten-minute job
        competed with nine other members for a slot that comes once per
        production cycle.  Measured 2026-09-01: it went from 08-31T23:25 to
        07:19 without completing, eight hours and forty-seven missed rounds,
        for a pass that takes 22.8 seconds.

        Every P1 committed in that window was committed blind, and the
        envelope table is append-only, so each one is permanently without its
        sha and its station-day stays refused by the atomic-fact gate until a
        newer P1 carries one.  Fifteen stations were blocked on
        ``target_atomic_lineage_incomplete`` in a single cycle, and thirteen
        of the fifteen had their revision fact in the store by the time it was
        looked for -- it simply had not existed yet when P1 asked.

        So the cycle identifies its own reports, the same way it materializes
        its own truth: this is the one loop with a heartbeat and a watchdog,
        it runs more often than the lane's own contract, and it cannot be
        outbid for a turn because it *is* the turn.  Run before the
        probability chain, because the chain is the consumer.

        The hosted sweep keeps the same script and remains the backstop for
        the rounds where the cycle itself is fail-closed.  Its single-instance
        guard is what keeps the two from overlapping; a refused start exits
        zero, which is why this reads the receipt rather than the exit code
        to decide whether anything was staged.
        """

        boundary = {
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }
        script = ROOT / "scripts" / "pr12_awc_observation_sweep.sh"
        if not script.is_file():
            return {"state": "NOT_CONFIGURED", **boundary}
        # Only when the archive has a report the last pass did not see.  The
        # pass re-derives the whole three-day window whatever arrived, 33s
        # at the median and 16% of a cycle (2026-09-15), and most cycles
        # arrive between one hour's METARs and the next: the archive's
        # observation table is append-only (a correction is a new row), so
        # its newest rowid is the watermark, and the window's own start
        # moves once a day, so the UTC date is the rest of it.  Nothing new
        # means the contract the last pass staged is the contract.
        watermark = _live_observation_watermark(
            getattr(self, "canonical_source_conn", None)
        )
        # Charter 181(七): a fresh process takes up the bookkeeping the last
        # one left, instead of opening with a full pass (70-157 s on
        # 2026-10-04, five restarts by 06:30Z).
        adopted = None
        if getattr(self, "_live_observation_identity_rowids", None) is None:
            adopted = TargetProductionWorker._adopt_identity_pass_state(
                self,
                _identity_table_rowids(
                    getattr(self, "canonical_source_conn", None)
                ),
            )
        previous = getattr(self, "_live_observation_identity_last", None)
        if (
            watermark is not None
            and isinstance(previous, Mapping)
            and previous.get("state") == "STAGED"
            and getattr(self, "_live_observation_identity_watermark", None)
            == watermark
        ):
            return {
                **previous,
                "state": "SKIPPED_NO_NEW_REPORTS",
                "duration_sec": 0.0,
                "watermark": list(watermark),
                **({"adopted_staged_at_utc": adopted} if adopted else {}),
            }
        started = time.monotonic()
        started_utc = utc_now()
        # Charter 181: which stations this pass has to re-derive.  Read
        # before the pass, so a row landing while it runs is past the
        # snapshot and named by the next one.
        source_conn = getattr(self, "canonical_source_conn", None)
        rowids = _identity_table_rowids(source_conn)
        inputs = _identity_inputs_fingerprint(getattr(self, "conn", None))
        try:
            # Called through the class: this pass reports and never raises,
            # and the scope is only an economy -- anything unexpected in it
            # is a full pass, not an exception in front of P1.
            stations, full_reason, skip_substitute = (
                TargetProductionWorker._identity_pass_scope(
                    self, watermark=watermark, rowids=rowids, conn=source_conn,
                    inputs=inputs,
                )
            )
        except Exception as exc:  # noqa: BLE001 -- see above
            stations, full_reason, skip_substitute = (
                None, f"scope_failed:{type(exc).__name__}", False,
            )
        env = None
        if stations is not None:
            env = {
                **os.environ,
                "PR12_STATIONS": ",".join(stations),
                "PR12_SKIP_ASOS_SUBSTITUTE": "1" if skip_substitute else "0",
            }
        try:
            completed = run_script_group_bounded(
                ["/bin/bash", str(script)],
                cwd=str(ROOT),
                timeout=LIVE_OBSERVATION_IDENTITY_DEADLINE_SEC,
                env=env,
            )
            if stations is not None and completed.returncode != 0:
                # A subset the builder or the stage refused (a station
                # outside the projection, a contract with nothing left to
                # stage) is answered by the full pass, now.
                full_reason = "subset_pass_failed"
                stations = None
                completed = run_script_group_bounded(
                    ["/bin/bash", str(script)],
                    cwd=str(ROOT),
                    timeout=LIVE_OBSERVATION_IDENTITY_DEADLINE_SEC,
                )
        except subprocess.TimeoutExpired:
            return {
                "state": "DEADLINE_EXCEEDED",
                "reason": (
                    "live_observation_identity_exceeded_"
                    f"{LIVE_OBSERVATION_IDENTITY_DEADLINE_SEC:.0f}s"
                ),
                "duration_sec": round(time.monotonic() - started, 3),
                **boundary,
            }
        except Exception as exc:  # noqa: BLE001 -- observational
            return {
                "state": "FAILED",
                "reason": f"{type(exc).__name__}:{str(exc)[:200]}",
                "duration_sec": round(time.monotonic() - started, 3),
                **boundary,
            }
        receipt: dict[str, Any] = {
            "state": "STAGED" if completed.returncode == 0 else "FAILED",
            "returncode": completed.returncode,
            "duration_sec": round(time.monotonic() - started, 3),
            "stderr": (completed.stderr or "").strip()[-200:],
            "scope": "full" if stations is None else "stations",
            "stations": list(stations or ()),
            "full_pass_reason": full_reason if stations is None else "",
            "substitute_skipped": bool(stations is not None and skip_substitute),
            **({"adopted_staged_at_utc": adopted} if adopted else {}),
            **boundary,
        }
        # Named on the cycle record: the pass runs at the head and at every
        # fast-lane checkpoint with a new report, and its receipt was kept
        # nowhere -- on 2026-10-04 the cycle spent 20 s a time in it with
        # no record of whether that was the full pass or a few stations.
        # ``getattr``: this pass reports and never raises, and stand-ins for
        # the worker (tests, rotation helpers) carry no span ledger.
        add_span = getattr(self, "_add_span", None)
        if callable(add_span):
            add_span(
                "live_observation_identity_pass",
                (time.monotonic() - started) * 1000.0,
                label=(
                    f"full:{full_reason or 'unscoped'}" if stations is None
                    else f"{len(stations)} stations"
                    + ("" if skip_substitute else " +substitute")
                ),
            )
        # What was actually written, from the stage receipt rather than from
        # the exit code: a start the single-instance guard refused also exits
        # zero, and the two are not the same outcome.
        try:
            staged = load_bounded_json(
                ROOT / "output" / "audits"
                / "pr12_awc_observation_stage_latest.json"
            )
        except Exception:  # noqa: BLE001 -- observational
            staged = None
        if isinstance(staged, Mapping):
            ingress = (
                (staged.get("stage_receipt") or {})
                .get("canonical_ingress_receipt")
                if isinstance(staged.get("stage_receipt"), Mapping)
                else None
            )
            receipt["revision_fact_count"] = staged.get("revision_fact_count")
            receipt["staged_at_utc"] = staged.get("ingested_at_utc")
            if isinstance(ingress, Mapping):
                receipt["inserted_count"] = ingress.get("inserted_count")
                receipt["replayed_count"] = ingress.get("replayed_count")
        if receipt["state"] == "STAGED":
            # The pass saw everything up to this row; a later row, or a
            # later day, is what makes the next one due.
            self._live_observation_identity_watermark = watermark
            self._live_observation_identity_last = dict(receipt)
            # Charter 181: the subset bookkeeping moves only on a stage this
            # pass itself wrote.  A start the single-instance guard refused
            # also exits zero, and the hosted sweep it deferred to may have
            # read the archive before these rows: keeping the old snapshot
            # names them again next time.
            if str(receipt.get("staged_at_utc") or "") >= started_utc:
                self._live_observation_identity_rowids = rowids
                if stations is None:
                    self._live_observation_identity_full_mono = started
                    self._live_observation_identity_full_utc = started_utc
                    self._live_observation_identity_inputs = inputs
                TargetProductionWorker._keep_identity_pass_state(self, receipt)
        return receipt

    def _keep_identity_pass_state(self, receipt: Mapping[str, Any]) -> None:
        """Charter 181(七): write the subset bookkeeping where a restart finds it.

        Written only when a stage this process wrote moved it, and only by a
        worker the resident pointed at the file.  Atomic rename; a write that
        fails leaves the next process its full pass.
        """

        path = getattr(self, "identity_pass_state_path", None)
        full_utc = getattr(self, "_live_observation_identity_full_utc", None)
        rowids = getattr(self, "_live_observation_identity_rowids", None)
        if path is None or not full_utc or not isinstance(rowids, Mapping):
            return
        watermark = getattr(self, "_live_observation_identity_watermark", None)
        state = {
            "schema": IDENTITY_PASS_STATE_SCHEMA,
            "rowids": {str(k): int(v) for k, v in rowids.items()},
            "watermark": list(watermark) if watermark else None,
            "inputs": getattr(self, "_live_observation_identity_inputs", None),
            "full_pass_started_utc": str(full_utc),
            "receipt": dict(receipt),
        }
        target = Path(path)
        scratch = target.with_name(f"{target.name}.{os.getpid()}.tmp")
        try:
            target.parent.mkdir(parents=True, exist_ok=True)
            scratch.write_text(
                json.dumps(state, sort_keys=True, default=str), encoding="utf-8"
            )
            os.replace(scratch, target)
        except OSError:
            try:
                scratch.unlink()
            except OSError:
                pass

    def _adopt_identity_pass_state(
        self, rowids_now: Mapping[str, int] | None
    ) -> str | None:
        """Charter 181(七): take up a previous process's subset bookkeeping.

        Taken only whole: its full pass inside the period (by the wall
        clock), every archive table it counted still at or past its count,
        and a staged receipt.  The rest -- the UTC day, the inputs
        fingerprint, the period itself -- is then asked by the subset rule
        exactly as of a pass this process staged.  The bookkeeping says the
        staged facts cover every station's rows up to its counts; a stage
        by anyone since only adds to them.  Returns the adopted stage's
        stamp, or None and the pass is full as before.
        """

        path = getattr(self, "identity_pass_state_path", None)
        if path is None or not isinstance(rowids_now, Mapping):
            return None
        try:
            target = Path(path)
            if target.stat().st_size > 1024 * 1024:
                return None
            state = json.loads(target.read_text(encoding="utf-8"))
            if (
                not isinstance(state, Mapping)
                or state.get("schema") != IDENTITY_PASS_STATE_SCHEMA
            ):
                return None
            kept = {str(k): int(v) for k, v in dict(state["rowids"]).items()}
            full_utc = str(state["full_pass_started_utc"])
            age = (
                datetime.now(timezone.utc)
                - datetime.fromisoformat(full_utc.replace("Z", "+00:00"))
            ).total_seconds()
            receipt = dict(state["receipt"])
            raw_watermark = state.get("watermark")
            watermark = (
                (int(raw_watermark[0]), int(raw_watermark[1]), str(raw_watermark[2]))
                if raw_watermark
                else None
            )
        except (OSError, ValueError, TypeError, KeyError, IndexError, AttributeError):
            return None
        if (
            not 0.0 <= age < LIVE_OBSERVATION_IDENTITY_FULL_PASS_SEC
            or receipt.get("state") != "STAGED"
            or set(kept) != {str(k) for k in rowids_now}
            or any(kept[table] > int(rowids_now[table]) for table in kept)
        ):
            return None
        self._live_observation_identity_rowids = kept
        self._live_observation_identity_watermark = watermark
        self._live_observation_identity_full_mono = time.monotonic() - age
        self._live_observation_identity_full_utc = full_utc
        self._live_observation_identity_inputs = state.get("inputs")
        self._live_observation_identity_last = receipt
        return str(receipt.get("staged_at_utc") or "") or full_utc

    def _identity_pass_scope(
        self,
        *,
        watermark: tuple[int, int, str] | None,
        rowids: Mapping[str, int] | None,
        conn: sqlite3.Connection | None,
        inputs: str | None = None,
    ) -> tuple[list[str] | None, str, bool]:
        """Charter 181: ``(stations or None for a full pass, why full, skip
        the substitute stage)``.

        A subset needs a snapshot from a pass this process staged, the same
        UTC day as that pass (the window's start moves once a day), a full
        pass within ``LIVE_OBSERVATION_IDENTITY_FULL_PASS_SEC``, and at least
        one station whose AWC rows moved.  Anything else is a full pass --
        including a watermark that moved only on the substitute lane, which
        the AWC export has nothing to say about.
        """

        previous_rowids = getattr(self, "_live_observation_identity_rowids", None)
        previous_watermark = getattr(
            self, "_live_observation_identity_watermark", None
        )
        last_full = getattr(self, "_live_observation_identity_full_mono", None)
        if watermark is None or rowids is None:
            return None, "archive_unreadable", False
        if not isinstance(previous_rowids, Mapping) or last_full is None:
            return None, "no_staged_snapshot", False
        if not previous_watermark or previous_watermark[2] != watermark[2]:
            return None, "utc_day_changed", False
        # The projection, the script naming it and the station registry, as
        # the last full pass read them: any change is a full pass now.  Inputs
        # that cannot be read decide nothing here -- the periodic net below
        # still runs -- rather than turning every pass into a full one.
        kept_inputs = getattr(self, "_live_observation_identity_inputs", None)
        if inputs is not None and inputs != kept_inputs:
            return None, "identity_inputs_changed", False
        if time.monotonic() - float(last_full) >= LIVE_OBSERVATION_IDENTITY_FULL_PASS_SEC:
            return None, "periodic_full_pass", False
        changed = _identity_changed_stations(
            conn, since=previous_rowids, until=rowids,
        )
        if changed is None:
            return None, "changed_stations_unreadable", False
        # The fleet only, read where the builder reads it: its full pass
        # exports the fleet and ignores registry rows staged for onboarding,
        # but asked for one by name it refuses the whole subset
        # (pr12_station_timezone_scope_missing), and the pass fell back to a
        # full one -- 49 s at 03:37Z on 2026-10-04, while LTFM/UUWW/LLBG were
        # still onboarding (they joined the fleet at 5e68ea74 the same
        # morning, and this follows the fleet list with them).
        changed &= {
            str(value).strip().upper()
            for value in coordinate_registry_manifest()["station_ids"]
        }
        if not changed:
            return None, "no_awc_station_moved", False
        skip_substitute = int(watermark[1]) == int(previous_watermark[1])
        return sorted(changed), "", skip_substitute


    def _capture_historical_taf_daily(
        self, *, as_of_utc: str
    ) -> dict[str, Any]:
        """Re-capture the closed days still inside AWC's 30-day window.

        The capture subprocess writes bounded archive files and a receipt;
        the pass then ingests them into the calibration table, batched under
        the ingest CLI's archive cap.  Ingest is a frozen-fact replay, so the
        rolling window's unchanged days verify rather than duplicate.  No
        order gateway is ever touched.
        """

        boundary = {
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }
        stations = self._historical_taf_capture_stations()
        if not stations:
            return {"state": "NOT_CONFIGURED", **boundary}
        inflight = getattr(self, "_historical_taf_capture_inflight", None)
        if inflight is not None and not inflight.done():
            return {"state": "IN_FLIGHT", **boundary}
        capture_root = self.nwp_runtime_root / "historical_taf_multianchor"
        receipt_path = capture_root / "receipt.json"
        now_mono = time.monotonic()
        last_attempt = getattr(self, "_historical_taf_capture_last_mono", None)
        if last_attempt is None:
            # The throttle has to survive a restart, because the work does.
            # Held only in memory it is None on every fresh worker, so the
            # full seven-day, seventeen-station AWC capture and its
            # forty-archive ingest fired on the first cycle after every
            # restart -- six times on 2026-09-01, against a bound that says
            # once a day.  That is the AWC traffic six times over and, until
            # the ingest's lock was split, six chances to stall a cycle.
            #
            # The receipt the capture subprocess writes on completion is the
            # durable record of when it last ran, so read its age and seed
            # the in-memory clock from it.  A capture that failed leaves an
            # older receipt and is retried, which is the behaviour wanted.
            try:
                receipt_age_sec = max(
                    0.0, time.time() - receipt_path.stat().st_mtime
                )
            except OSError:
                receipt_age_sec = None
            if (
                receipt_age_sec is not None
                and receipt_age_sec < HISTORICAL_TAF_CAPTURE_RETRY_SEC
            ):
                last_attempt = now_mono - receipt_age_sec
                self._historical_taf_capture_last_mono = last_attempt
        if (
            last_attempt is not None
            and now_mono - last_attempt < HISTORICAL_TAF_CAPTURE_RETRY_SEC
        ):
            return {
                "state": "THROTTLED",
                "retry_in_seconds": round(
                    HISTORICAL_TAF_CAPTURE_RETRY_SEC
                    - (now_mono - last_attempt),
                    1,
                ),
                **boundary,
            }
        self._historical_taf_capture_last_mono = now_mono
        as_of_day = datetime.fromisoformat(
            as_of_utc.replace("Z", "+00:00")
        ).astimezone(timezone.utc).date()
        end_date = as_of_day - timedelta(days=HISTORICAL_TAF_CAPTURE_LAG_DAYS)
        start_date = end_date - timedelta(
            days=HISTORICAL_TAF_CAPTURE_WINDOW_DAYS - 1
        )
        # Bound above, where the throttle reads the receipt's age.
        capture_root.mkdir(parents=True, exist_ok=True)
        command = [
            sys.executable,
            str(
                ROOT
                / "scripts"
                / "backfill_awc_taf_calibration_multistation.py"
            ),
            "--db", str(self.db_path),
            "--start-date", start_date.isoformat(),
            "--end-date", end_date.isoformat(),
            "--output-dir", str(capture_root),
            # Days already complete are kept and only the transport failures
            # are retried, so the overlapping window costs little after the
            # first pass.
            "--resume",
            "--max-workers", "2",
            "--request-interval-sec", "0.5",
            "--timeout-sec", "30",
            "--receipt", str(receipt_path),
        ]
        for station in stations:
            command.extend(["--station-id", station])
        for anchor in HISTORICAL_TAF_DECISION_ANCHOR_HOURS:
            command.extend(["--decision-anchor-hour", str(anchor)])
        # AWC is reached directly.  The service is public, and the ambient
        # proxy this host exports is for a different lane entirely -- routed
        # through it the capture dies in CONNECT tunnel failures rather than
        # returning bulletins.
        environment = {
            key: value
            for key, value in os.environ.items()
            if key not in {
                "HTTP_PROXY", "HTTPS_PROXY", "http_proxy", "https_proxy",
                "AWC_HTTP_PROXY",
            }
        }

        def _run_capture() -> dict[str, Any]:
            try:
                completed = subprocess.run(
                    command,
                    cwd=str(ROOT),
                    capture_output=True,
                    text=True,
                    timeout=HISTORICAL_TAF_CAPTURE_DEADLINE_SEC,
                    env=environment,
                )
            except subprocess.TimeoutExpired:
                return {
                    "state": "DEADLINE_EXCEEDED",
                    "reason": (
                        "historical_taf_capture_exceeded_"
                        f"{HISTORICAL_TAF_CAPTURE_DEADLINE_SEC:.0f}s"
                    ),
                }
            except Exception as exc:
                return {
                    "state": "FAILED",
                    "reason": f"{type(exc).__name__}:{str(exc)[:200]}",
                }
            summary: dict[str, Any] = {}
            try:
                summary = json.loads(
                    (completed.stdout or "").strip().splitlines()[-1]
                )
            except Exception:
                pass
            # Captured archives are ingested in the same pass.  This lane
            # originally left committing "a separate, explicit step", which is
            # the same shape that froze every other system's training archive
            # at the last day a person ran the manual step; an archive on disk
            # that never reaches the table does not exist as far as the fit is
            # concerned.  Ingest is a frozen-fact replay, so re-ingesting the
            # rolling window's unchanged days verifies rather than duplicates.
            archives = sorted(capture_root.glob("AWC_TAF_*.json"))
            ingested = 0
            ingest_failures: list[str] = []
            for start in range(0, len(archives), 40):
                batch = archives[start:start + 40]
                ingest_command = [
                    sys.executable,
                    str(ROOT / "scripts" / "ingest_awc_taf_calibration.py"),
                    "--db", str(self.db_path),
                    "--commit",
                ]
                for archive_path in batch:
                    ingest_command.extend(["--archive", str(archive_path)])
                try:
                    ingest_run = subprocess.run(
                        ingest_command,
                        cwd=str(ROOT),
                        capture_output=True,
                        text=True,
                        timeout=HISTORICAL_TAF_CAPTURE_DEADLINE_SEC,
                    )
                except Exception as exc:
                    ingest_failures.append(
                        f"{type(exc).__name__}:{str(exc)[:120]}"
                    )
                    continue
                if ingest_run.returncode == 0:
                    ingested += len(batch)
                else:
                    ingest_failures.append(
                        (ingest_run.stderr or "").strip()[-120:]
                    )
            # A nonzero exit here means some station-anchor run failed, which
            # on this lane is ordinary: AWC drops connections and the next
            # day's pass resumes the same window.
            result = {
                "state": "CAPTURED" if completed.returncode == 0 else "PARTIAL",
                "start_date": start_date.isoformat(),
                "end_date": end_date.isoformat(),
                "station_count": len(stations),
                "decision_anchor_offset_hours": list(
                    HISTORICAL_TAF_DECISION_ANCHOR_HOURS
                ),
                "sample_count": summary.get("sample_count"),
                "completed_run_count": summary.get("completed_run_count"),
                "failed_run_count": summary.get("failed_run_count"),
                "ingested_archive_count": ingested,
                "ingest_failures": ingest_failures[:3],
                "stderr": (completed.stderr or "").strip()[-200:],
            }
            self._historical_taf_capture_last_result = result
            return result

        pool = getattr(self, "_historical_taf_capture_pool", None)
        if pool is None:
            self._historical_taf_capture_pool = ThreadPoolExecutor(
                max_workers=1,
                thread_name_prefix="historical-taf-capture",
            )
            pool = self._historical_taf_capture_pool
        self._historical_taf_capture_inflight = pool.submit(_run_capture)
        return {
            "state": "SUBMITTED",
            "start_date": start_date.isoformat(),
            "end_date": end_date.isoformat(),
            "station_count": len(stations),
            "last_completed": dict(
                getattr(self, "_historical_taf_capture_last_result", {}) or {}
            ),
            **boundary,
        }

    def _registry_export_is_stale(
        self, path: Path, *, as_of_utc: str
    ) -> bool:
        """Whether the published registry snapshot is old enough to redo.

        Markets for a future event date are listed progressively, so a snapshot
        taken early carries a station count that is merely how far Polymarket
        had got at that moment.  Holding it indefinitely makes that partial
        count permanent for the date.
        """

        try:
            snapshot = load_market_registry_snapshot(path)
        except Exception:
            return True
        # The export stamps its clock under ``filters`` (and ``exported_at_utc``
        # beside it); there is no top-level ``as_of_utc``.  Reading that key
        # answered "stale" on every call, so every rotation call -- sixty-odd
        # a poll -- re-exported the whole registry from the live database:
        # 152s of a 239s poll on 2026-09-15, 2.45s a call, while production
        # waited behind the turn.
        filters = snapshot.get("filters")
        taken = str(
            (filters.get("as_of_utc") if isinstance(filters, Mapping) else "")
            or snapshot.get("exported_at_utc")
            or ""
        ).strip()
        if not taken:
            return True
        try:
            def _at(value: str) -> datetime:
                return datetime.fromisoformat(
                    str(value).replace("Z", "+00:00")
                ).astimezone(timezone.utc)

            now = _at(as_of_utc)
            age = (now - _at(taken)).total_seconds()
            # An export whose scope had not moved writes nothing, so the file
            # keeps its old clock; the attempt is what says the question was
            # asked.  Without this an unchanged catalog would turn "stale" for
            # good thirty minutes in and re-export on every call again.
            attempted = getattr(self, "_registry_export_attempted_at_utc", None)
            if attempted:
                age = min(age, (now - _at(str(attempted))).total_seconds())
        except Exception:
            return True
        return age >= REGISTRY_EXPORT_MAX_AGE_SEC or age < 0

    def _open_meteo_d2_already_captured(self, *, target_date: str) -> bool:
        """Whether all three republisher families already hold this target day.

        Keyed on the extraction version so a change in how members are read
        does not let a superseded capture satisfy the day.
        """

        if self.conn is None:
            return False
        try:
            row = self.conn.execute(
                "SELECT COUNT(DISTINCT ensemble_system_id) "
                "FROM calibration_republisher_ensemble_historical_member_run "
                "WHERE target_local_date=? AND archive_lead_bucket='d2' "
                "  AND extraction_version=? "
                f"  AND ensemble_system_id IN ({
                    ','.join('?' * len(OPEN_METEO_D2_SYSTEM_IDS))
                })",
                (
                    target_date,
                    OPEN_METEO_D2_EXTRACTION_VERSION,
                    *OPEN_METEO_D2_SYSTEM_IDS,
                ),
            ).fetchone()
        except Exception:
            return False
        return int((row or [0])[0]) >= len(OPEN_METEO_D2_SYSTEM_IDS)

    def _capture_open_meteo_d2_daily(self, *, as_of_utc: str) -> dict[str, Any]:
        """Take today's republisher d2 members for all stations, once."""

        target_date = (
            _utc_date(as_of_utc)
            + timedelta(days=OPEN_METEO_D2_CAPTURE_LEAD_DAYS)
        ).isoformat()
        if self._open_meteo_d2_already_captured(target_date=target_date):
            return {
                "state": "ALREADY_CAPTURED",
                "target_local_date": target_date,
                "orders_submitted": 0,
                "calls_order_gateway": False,
            }
        inflight = getattr(self, "_open_meteo_d2_capture_inflight", None)
        if inflight is not None and not inflight.done():
            return {
                "state": "IN_FLIGHT",
                "target_local_date": target_date,
                "orders_submitted": 0,
                "calls_order_gateway": False,
            }
        now_mono = time.monotonic()
        last_attempt = getattr(self, "_open_meteo_d2_capture_last_mono", None)
        if (
            last_attempt is not None
            and now_mono - last_attempt < OPEN_METEO_D2_CAPTURE_RETRY_SEC
        ):
            return {
                "state": "THROTTLED",
                "target_local_date": target_date,
                "orders_submitted": 0,
                "calls_order_gateway": False,
            }
        self._open_meteo_d2_capture_last_mono = now_mono

        capture_root = self.nwp_runtime_root / "open_meteo_d2_capture"
        capture_root.mkdir(parents=True, exist_ok=True)
        command = [
            sys.executable,
            str(ROOT / "scripts" / "capture_open_meteo_d2_ensemble_daily.py"),
            "--output", str(capture_root / f"om_d2_{target_date}.json"),
            "--commit",
        ]

        def _run() -> dict[str, Any]:
            try:
                completed = subprocess.run(
                    command,
                    cwd=str(ROOT),
                    capture_output=True,
                    text=True,
                    timeout=OPEN_METEO_D2_CAPTURE_DEADLINE_SEC,
                )
            except subprocess.TimeoutExpired:
                return {"state": "DEADLINE_EXCEEDED"}
            except Exception as exc:
                return {
                    "state": "FAILED",
                    "reason": f"{type(exc).__name__}:{str(exc)[:200]}",
                }
            if completed.returncode != 0:
                return {
                    "state": "FAILED",
                    "reason": (
                        f"open_meteo_d2_exit_{completed.returncode}:"
                        f"{(completed.stderr or '').strip()[:200]}"
                    ),
                }
            return {"state": "CAPTURED", "target_local_date": target_date}

        pool = getattr(self, "_official_native_capture_pool", None)
        if pool is None:
            self._official_native_capture_pool = ThreadPoolExecutor(
                max_workers=OFFICIAL_NATIVE_CAPTURE_MAX_CONCURRENCY,
                thread_name_prefix="official-native-capture",
            )
            pool = self._official_native_capture_pool
        self._open_meteo_d2_capture_inflight = pool.submit(_run)
        return {
            "state": "SUBMITTED",
            "target_local_date": target_date,
            "orders_submitted": 0,
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
        }

    def _drain_fresh_official_native_arrivals(
        self,
        read_conn: sqlite3.Connection,
        *,
        as_of_utc: str,
    ) -> dict[str, Any]:
        """Compile every fresh, unconsumed official packet before the cursor.

        The packet TTL and the rotation period are independent quantities, and
        nothing kept them ordered: a packet that lands just after the cursor
        passes its scope waits a full sweep, and when the sweep is longer than
        the TTL the packet dies in the inbox without ever becoming a P0.  This
        drain restores the invariant the architecture already claims -- P0 is
        driven by each model update -- by consuming arrivals on the cycle after
        they land, regardless of where the cursor happens to be.

        Consumption is deduplicated on the packet's ``snapshot_content_sha256``:
        a compile is content-addressed and its persistence idempotent, so the
        in-memory ledger only avoids repeat work, never correctness.  Failures
        are recorded and the sha is *not* marked consumed, so a transient
        rejection is retried on the next cycle while the packet is still
        fresh.
        """

        consumed: dict[tuple[str, str], str] = getattr(
            self, "_official_native_arrival_consumed", None
        ) or {}
        self._official_native_arrival_consumed = consumed
        official_inbox_path = (
            self.nwp_runtime_root
            / "official_native_ensemble_forward_inbox.json"
        )
        receipt: dict[str, Any] = {
            "schema": "official_native_arrival_drain_v1",
            "compiled_count": 0,
            "rejected": [],
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }
        if not official_inbox_path.is_file():
            return receipt
        try:
            packets = _load_native_forward_inbox(
                official_inbox_path,
                error_code="official_native_forward_inbox_invalid",
            )
        except Exception as exc:
            receipt["rejected"].append(
                f"inbox:{type(exc).__name__}:{str(exc)[:120]}"
            )
            return receipt
        compiled_packets: list[dict[str, Any]] = []
        for candidate in packets:
            if (
                str(candidate.get("schema") or "")
                != OFFICIAL_NATIVE_FORWARD_PACKET_SCHEMA
            ):
                continue
            station = str(
                candidate.get("station_id") or ""
            ).strip().upper()
            event_date = str(candidate.get("event_date") or "")
            snapshot_sha = str(
                candidate.get("snapshot_content_sha256") or ""
            )
            if not station or not event_date or not snapshot_sha:
                continue
            if consumed.get((station, event_date)) == snapshot_sha:
                continue
            if _native_forward_packet_is_stale(
                candidate,
                as_of_utc=as_of_utc,
                seated_system_ids=self._latest_p0_weighted_systems(
                    read_conn, event_date=event_date, as_of_utc=as_of_utc
                ).get(station),
            ):
                continue
            try:
                compiled = _compile_native_ensemble_p0_runtime(
                    read_conn,
                    forward_packet=candidate,
                    decision_at_utc=as_of_utc,
                    native_oos_snapshot=self.native_oos_snapshot,
                )
            except Exception as exc:
                receipt["rejected"].append(
                    f"{station}|{event_date}:"
                    f"{type(exc).__name__}:{str(exc)[:120]}"
                )
                continue
            if not (
                isinstance(compiled, Mapping)
                and compiled.get("schema")
                == "calibrated_native_cross_ensemble_p0_packet_v1"
            ):
                receipt["rejected"].append(
                    f"{station}|{event_date}:compile_rejected"
                )
                continue
            compiled = dict(compiled)
            if self.commit_conn is not None:
                compiled[
                    "forward_prediction_persistence"
                ] = persist_native_ensemble_forward_prediction(
                    self.commit_conn,
                    compiled,
                )
            compiled_packets.append(
                (station, event_date, snapshot_sha, compiled)
            )
            receipt["compiled_count"] += 1
        if compiled_packets and self.commit_conn is not None:
            merge = _upsert_native_p0_inbox(
                self.p0_inbox_path,
                compiled_packets=[item[3] for item in compiled_packets],
                generated_at_utc=as_of_utc,
            )
            receipt["p0_inbox_merge"] = merge
            # Consumption follows delivery, not compilation.  A packet the
            # inbox declines -- a P0-M confirm the P0 inbox has no seat for,
            # say -- must stay unconsumed so the next cycle retries or routes
            # it, instead of evaporating behind a dedupe mark.
            if int(merge.get("accepted_count") or 0) == len(
                compiled_packets
            ):
                for station, event_date, snapshot_sha, _packet in (
                    compiled_packets
                ):
                    consumed[(station, event_date)] = snapshot_sha
        elif compiled_packets:
            for station, event_date, snapshot_sha, _packet in (
                compiled_packets
            ):
                consumed[(station, event_date)] = snapshot_sha
        return receipt

    def _persist_nwp_rotation(
        self,
        *,
        station_ids: Sequence[str],
        scopes: Sequence[Mapping[str, Any]],
        selected_scopes: Sequence[Mapping[str, Any]],
        outcomes: Sequence[Mapping[str, Any]],
        as_of_utc: str,
    ) -> dict[str, Any]:
        """Write the rotation cursor and scope catalogue, whatever the outcome.

        Every exit that advanced the cursor has to persist it.  Writing on only
        one of them froze the file the moment the lane stopped taking that
        branch: once packets existed the cycle returned ``official_native_reused``
        instead, so the last write stayed at 2026-08-08T03:04Z while capture
        went on for another fourteen hours.

        Two things go wrong quietly when that happens.  The cursor resumes from
        a stale catalogue after a restart, pointing into a scope list that no
        longer describes the open days; and the in-flight status receipt
        republishes the same stale catalogue, so ``catalog_scope_count`` -- the
        one number worth trusting when station coverage looks short -- reports
        a two-day-old sweep as if it were current.
        """

        rotation_state = build_rotation_state(
            station_ids=tuple(station_ids),
            scopes=list(scopes),
            selected_scopes=list(selected_scopes),
            cursor_by_priority={
                0: self._native_ensemble_scope_cursor,
            },
            outcomes=list(outcomes),
            previous=getattr(self, "_nwp_rotation_state", None),
            updated_at_utc=as_of_utc,
        )
        rotation_state_path = getattr(
            self,
            "nwp_rotation_state_path",
            self.nwp_runtime_root / "rotation_state.json",
        )
        try:
            wrote = persist_rotation_state(rotation_state_path, rotation_state)
        except Exception as exc:
            # Rotation state is scheduler telemetry and a restart hint, not an
            # authorization boundary.  A failed write must not turn a completed
            # capture into a fail-closed cycle.
            self._nwp_rotation_state = rotation_state
            return {
                "rotation_state_path": str(rotation_state_path),
                "rotation_state_wrote": False,
                "rotation_state_error": f"{type(exc).__name__}:{exc}",
                "rotation_generation": rotation_state["generation"],
                "next_scope_cursor": self._native_ensemble_scope_cursor,
            }
        self._nwp_rotation_state = rotation_state
        return {
            "rotation_state_path": str(rotation_state_path),
            "rotation_state_wrote": bool(wrote),
            "rotation_generation": rotation_state["generation"],
            "next_scope_cursor": self._native_ensemble_scope_cursor,
        }

    def _nwp_lap(self, segment: str | None) -> None:
        """Close the running segment of one rotation call as a span.

        The forecast turn holds the resident's single writer and most of it
        is this call, sixty-odd times a poll; on 2026-09-15 a call cost 2.7s
        inside the resident against 0.14s on a read-only replica, and the
        only instrument was the rotation file's write cadence.  Marks, not a
        ``with`` block, so measuring the call does not re-indent it.  ``None``
        starts a call without recording.
        """

        now = time.perf_counter()
        started = getattr(self, "_nwp_lap_at", None)
        self._nwp_lap_at = now
        if segment is not None and started is not None:
            self._add_span(segment, (now - started) * 1000.0)

    def refresh_resident_nwp(self, *, as_of_utc: str) -> dict[str, Any]:
        """Capture official models and refresh the bounded P0 inbox.

        The method belongs to this existing worker so there is still one
        resident owner and no fourth service.  Registry export is read-only
        against the canonical database; only the isolated target registry and
        P0 inbox may change.
        """

        # ICON no longer has a lane of its own.  It was given one because its
        # objects are whole global fields and the native capture asked per
        # station, which would have pulled the same run once for each of them;
        # that capture now reads one run for every station the day lists, so
        # the separate pass was downloading a second copy of what the shared
        # one already had.  Its irreplaceability -- DWD keeps one run, and a
        # skipped day is gone -- now rests on the same capture the other three
        # families depend on.
        self._nwp_lap(None)
        open_meteo_d2 = self._capture_open_meteo_d2_daily(as_of_utc=as_of_utc)
        # Same fire-and-forget shape: the trajectory chain runs for at most one
        # due station per cycle and persists through its own gated commit.
        metar_trajectory_training = self._run_metar_trajectory_training(
            as_of_utc=as_of_utc
        )
        del metar_trajectory_training
        # The TAF revision training lane that used to run here was taken
        # offline 2026-09-13 with the calibrated P0-M branch it fed (charter
        # 133, "仅作研究"); its fit/gate/bind scripts stay for research runs.
        # The historical TAF capture stays in production: AWC serves 30 days,
        # so a closed day not captured while it is still inside that window
        # can never be captured at all, and that research -- and the TAF
        # measurements charter 133 rests on -- read this table.
        historical_taf_capture = self._capture_historical_taf_daily(
            as_of_utc=as_of_utc
        )
        del historical_taf_capture
        # Corrected reports halt settled truth until reviewed, and the review
        # policy only ever ran by hand -- so the halts piled up again and six
        # stations quietly stopped settling.  Scheduling it is the difference
        # between a policy that exists and one that runs.
        correction_auto_clear = self._run_correction_auto_clear(
            as_of_utc=as_of_utc
        )
        del correction_auto_clear

        self._nwp_lap("nwp_daily_tasks")
        read_conn = getattr(self, "commit_conn", None) or getattr(
            self, "conn", None
        )
        rotation_state_load_error = getattr(
            self,
            "_nwp_rotation_state_load_error",
            None,
        )
        if rotation_state_load_error:
            return {
                "schema": "bayes_basket_target_resident_nwp_cycle_v1",
                "state": "blocked_fail_closed",
                "reason": (
                    "resident_nwp_rotation_state_invalid:"
                    + rotation_state_load_error
                ),
                "station_scope_mode": "canonical_allowlist",
                "configured_station_ids": list(
                    getattr(self, "station_allowlist", ())
                ),
                "writes_target_database": False,
                "calls_order_gateway": False,
                "places_orders": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
        if read_conn is None:
            return {
                "state": "not_attempted",
                "reason": "target_read_only_connection_missing",
                "writes_target_database": False,
                "calls_order_gateway": False,
                "places_orders": False,
            }
        if self.canonical_source_db_path is None:
            return {
                "state": "not_configured",
                "reason": "canonical_registry_source_missing",
                "writes_target_database": False,
                "calls_order_gateway": False,
                "places_orders": False,
            }
        assert_process_memory_budget()
        registry_path = self.nwp_runtime_root / "market_registry_forward.json"
        station_allowlist = tuple(
            getattr(self, "station_allowlist", ())
        )
        event_date_allowlist = tuple(
            getattr(self, "event_date_allowlist", ())
        )
        # The resident registry worker owns ongoing publication immediately
        # after each bounded Gamma metadata refresh.  NWP may bootstrap a
        # missing handoff for one-shot/rehearsal use, but it must never
        # overwrite the multi-station catalog with its narrower acquisition
        # allowlist or couple target registry freshness to model cadence.
        try:
            existing_registry = (
                load_market_registry_snapshot(registry_path)
                if registry_path.is_file()
                else None
            )
        except Exception:
            existing_registry = None
        # The comment above assigns ongoing publication to a resident registry
        # worker, but no such writer exists -- this is the only code in the
        # repository that writes the file.  Reusing it whenever it was present
        # therefore froze the catalog at whatever the first bootstrap saw: the
        # snapshot went two days stale, so a new event date was registered with
        # the station count it happened to have at bootstrap time, and every
        # downstream capture scope inherited that stale bound.
        #
        # Refreshing is still refused while a narrowing allowlist is in force,
        # which is what the original guard was protecting: a single-station
        # acquisition run must never overwrite the multi-station catalog.
        stale = self._registry_export_is_stale(
            registry_path, as_of_utc=as_of_utc
        )
        # Narrowing means exactly what the export call below treats as
        # narrowing: a single station or a single event date, which is what
        # makes the export smaller than the catalog.  A full 45-station
        # allowlist is the normal resident configuration, so testing merely for
        # a non-empty allowlist suppressed every refresh.
        narrowed = (
            len(station_allowlist) == 1 or len(event_date_allowlist) == 1
        )
        if existing_registry is None or (stale and not narrowed):
            export = export_shared_live_registry(
                source_db=self.canonical_source_db_path,
                output_path=registry_path,
                station_id=(
                    station_allowlist[0]
                    if len(station_allowlist) == 1
                    else ""
                ),
                event_date=(
                    event_date_allowlist[0]
                    if len(event_date_allowlist) == 1
                    else ""
                ),
                as_of_utc=as_of_utc,
                include_not_started_for_p0=True,
                current_catalog_only=True,
            )
            self._registry_export_attempted_at_utc = as_of_utc
        else:
            export = {
                "schema": str(existing_registry.get("schema") or ""),
                "state": "REUSED_RESIDENT_REGISTRY_EXPORT",
                "snapshot_sha256": str(
                    existing_registry.get("snapshot_sha256") or ""
                ),
                "row_count": int(
                    existing_registry.get("row_count") or 0
                ),
                "output": str(registry_path),
                "source_database": str(
                    existing_registry.get("source_database_path") or ""
                ),
                "boundary": {
                    "reads_shared_live_database": False,
                    "writes_shared_live_database": False,
                    "writes_target_database": False,
                    "calls_order_gateway": False,
                    "places_orders": False,
                },
                "decoupled_from_nwp": True,
            }
        if getattr(self, "commit_conn", None) is None:
            # Network prefetch is deliberately read-only against the target
            # SSOT.  The sole production worker ingests this atomically
            # replaced registry snapshot at the start of its next cycle.
            registry_ingress = {
                "state": "deferred_to_production_writer",
                "wrote_rows": 0,
                "writes_target_database": False,
                "calls_order_gateway": False,
                "places_orders": False,
            }
        else:
            registry_ingress = ingest_target_market_registry(
                self.commit_conn,
                snapshot_path=registry_path,
                commit=True,
                as_of_utc=as_of_utc,
            )
        registry = load_market_registry_snapshot(registry_path)
        self._nwp_lap("nwp_registry")
        scopes = registry_capture_scopes(
            registry,
            as_of_utc=as_of_utc,
            max_scopes=MAX_DISCOVERED_SCOPES,
        )
        if station_allowlist:
            allowed = set(station_allowlist)
            scopes = [
                item
                for item in scopes
                if str(item["station_ids"][0]).strip().upper()
                in allowed
            ]
        if event_date_allowlist:
            allowed_dates = set(event_date_allowlist)
            scopes = [
                item
                for item in scopes
                if str(item["event_date"]).strip() in allowed_dates
            ]
        if not scopes:
            return {
                "schema": "bayes_basket_target_resident_nwp_cycle_v1",
                "state": (
                    "blocked_fail_closed"
                    if station_allowlist or event_date_allowlist
                    else "no_due_registry_scope"
                ),
                "reason": (
                    "resident_nwp_exact_station_scope_missing"
                    if station_allowlist or event_date_allowlist
                    else "no_due_registry_scope"
                ),
                "station_allowlist": list(station_allowlist),
                "event_date_allowlist": list(event_date_allowlist),
                "station_scope_mode": "canonical_allowlist",
                "configured_station_ids": list(self.station_allowlist),
                "discovered_station_ids": [],
                "scope_count": 0,
                "registry_export": export,
                "registry_ingress": registry_ingress,
                "writes_target_database": bool(
                    registry_ingress.get("wrote_rows")
                ),
                "calls_order_gateway": False,
                "places_orders": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
        # P0 authority was replaced by calibrated native-member ensembles.
        # Reuse an already retained official-native packet first.  Only when
        # no usable native packet exists (missing, invalid, stale, or rejected
        # by its own activation/OOS contract) do we capture the same scope from
        # Open-Meteo as an explicit ``aggregator_republisher`` no-live
        # fallback.  This prevents duplicate ECMWF/native downloads while
        # preserving strict lineage and historical-OOS gates.
        #
        # Fresh arrivals are drained before the cursor moves.  A captured
        # packet used to wait in the inbox for the rotation to come back
        # around -- but a sweep is 270 scopes at 20 a poll, and the packet's
        # own compile window is six hours, so tail-of-catalog stations kept
        # losing the race: ZUUU 2026-08-13's 00Z packet landed at 00:54Z and
        # expired unconsumed at 06:54Z while every P1 of the day stayed
        # chained to a two-system root a day and a half old.  A model update
        # drives P0; it must not also have to win a queue position.
        self._nwp_lap("nwp_scope_catalog")
        arrival_drain = self._drain_fresh_official_native_arrivals(
            read_conn,
            as_of_utc=as_of_utc,
        )
        self._official_native_arrival_drain_last = arrival_drain
        native_scope_index = (
            int(getattr(self, "_native_ensemble_scope_cursor", 0))
            % len(scopes)
        )
        native_scope = scopes[native_scope_index]
        self._native_ensemble_scope_cursor = (
            native_scope_index + 1
        ) % len(scopes)
        native_station = str(
            native_scope["station_ids"][0]
        ).strip().upper()
        native_event_date = str(native_scope["event_date"])
        official_inbox_path = (
            self.nwp_runtime_root
            / "official_native_ensemble_forward_inbox.json"
        )
        official_packet: Mapping[str, Any] | None = None
        # What this station's newest P0 weighted, so the probe below and the
        # capture it may ask for read the packet on the compiler's clock.
        self._nwp_lap("nwp_arrival_drain")
        native_seated_system_ids = self._latest_p0_weighted_systems(
            read_conn, event_date=native_event_date, as_of_utc=as_of_utc
        ).get(native_station)
        # A usable packet whose run a newer cycle has superseded.  Kept so the
        # scope can keep compiling from it while the fresher capture is still
        # in flight; see where it is consumed below.
        superseded_packet: Mapping[str, Any] | None = None
        official_probe_reason = "official_native_packet_missing"
        if official_inbox_path.is_file():
            try:
                official_packets = _load_native_forward_inbox(
                    official_inbox_path,
                    error_code="official_native_forward_inbox_invalid",
                )
                for candidate in official_packets:
                    if not (
                        str(candidate.get("schema") or "")
                        == OFFICIAL_NATIVE_FORWARD_PACKET_SCHEMA
                        and str(candidate.get("station_id") or "")
                        .strip()
                        .upper()
                        == native_station
                        and str(candidate.get("event_date") or "")
                        == native_event_date
                    ):
                        continue
                    # Presence is not usability.  A packet the compiler will
                    # reject as stale still satisfied this probe, so the scope
                    # took the reuse path, failed to compile, and never asked
                    # for a fresh capture -- leaving the inbox to age out with
                    # nothing able to replace it.  Treating a too-old packet as
                    # absent is what lets the capture below run.
                    if _native_forward_packet_is_stale(
                        candidate,
                        as_of_utc=as_of_utc,
                        seated_system_ids=native_seated_system_ids,
                    ):
                        official_probe_reason = (
                            "official_native_packet_stale"
                        )
                        continue
                    # A newer cycle has published since this packet was built.
                    # Staleness alone did not catch that: these families issue
                    # on a fixed schedule, and a packet from the 00Z run stays
                    # inside its freshness window for hours after 06Z lands, so
                    # the scope would sit on superseded fields until the clock
                    # -- not the publisher -- decided otherwise.  Treating a
                    # superseded packet as absent is what makes the lane follow
                    # publication instead of expiry.  The capture keys on run
                    # identity, so the first scope of the day pays for the new
                    # run and its siblings ride the same pass.
                    packet_run_init = _native_packet_run_init(candidate)
                    newest_rung = _official_native_run_ladder(
                        event_date=native_event_date,
                        as_of_utc=as_of_utc,
                        probe_state=self._arrival_probe_state(),
                    )
                    if (
                        packet_run_init is not None
                        and newest_rung
                        and newest_rung[0][2] > packet_run_init
                    ):
                        # Held, not discarded.  The capture runs off-thread and
                        # takes minutes, so treating this packet as simply
                        # absent would leave every scope of the date with no
                        # official evidence between the new cycle publishing
                        # and its capture landing -- trading a stale-by-minutes
                        # packet for none at all.  It is superseded, which is a
                        # reason to fetch, not a reason to stop reading.
                        superseded_packet = candidate
                        official_probe_reason = (
                            "official_native_packet_superseded_by_newer_run"
                        )
                        continue
                    official_packet = candidate
                    official_probe_reason = "official_native_packet_found"
                    break
            except Exception as exc:
                official_probe_reason = (
                    "official_native_packet_unavailable:"
                    f"{type(exc).__name__}:{exc}"
                )
        self._nwp_lap("nwp_official_probe")
        official_capture: dict[str, Any] | None = None
        if official_packet is None:
            # The official-native inbox used to be filled only by an operator
            # command, so it went stale and every scope silently degraded to the
            # Open-Meteo republisher -- which can never be forward P0 authority.
            # Capture the one scope this rotation step owns, then re-probe.  The
            # bounded per-scope throttle below keeps a station that genuinely has
            # no published cycle from re-downloading on every cycle.
            official_capture = self._capture_official_native_packet(
                station_id=native_station,
                event_date=native_event_date,
                as_of_utc=as_of_utc,
                inbox_path=official_inbox_path,
                seated_system_ids=native_seated_system_ids,
                # Charter 195 (三): no packet at all for this station-day --
                # typically listed after the day's pass ran.
                listing_station=(
                    native_station
                    if official_probe_reason == "official_native_packet_missing"
                    else None
                ),
                # The lead is advisory now: the capture's run ladder picks the
                # newest published run that covers the local day, so scopes
                # that only differ in lead label share one capture.
                lead_days=(
                    2
                    if native_scope.get("lead_days") is None
                    else int(native_scope["lead_days"])
                ),
            )
            if official_capture.get("state") == "CAPTURED":
                try:
                    for candidate in _load_native_forward_inbox(
                        official_inbox_path,
                        error_code="official_native_forward_inbox_invalid",
                    ):
                        if (
                            str(candidate.get("schema") or "")
                            == OFFICIAL_NATIVE_FORWARD_PACKET_SCHEMA
                            and str(candidate.get("station_id") or "")
                            .strip()
                            .upper()
                            == native_station
                            and str(candidate.get("event_date") or "")
                            == native_event_date
                        ):
                            official_packet = candidate
                            official_probe_reason = (
                                "official_native_packet_captured"
                            )
                            break
                except Exception as exc:
                    official_probe_reason = (
                        "official_native_packet_unavailable:"
                        f"{type(exc).__name__}:{exc}"
                    )
        self._nwp_lap("nwp_capture_admission")
        self._retry_icon_held_captures(
            as_of_utc=as_of_utc,
            inbox_path=official_inbox_path,
        )
        self._nwp_lap("nwp_icon_retry")
        if official_packet is None and superseded_packet is not None:
            # The fresher run was asked for above and is still on its way.  Its
            # arrival is what this scope wants, but not at the cost of having
            # no official evidence until it lands: the packet in hand is the
            # previous cycle's, which is exactly what the scope would have been
            # using had the new cycle not published yet.  The compiler's own
            # staleness gate still governs how old is too old.
            official_packet = superseded_packet
            official_probe_reason = (
                "official_native_packet_superseded_run_capture_pending"
            )
        # A capture performed inside this cycle finishes *after* the cycle's
        # ``as_of_utc`` was taken, and the compiler rejects a packet captured
        # later than the decision instant (`native_ensemble_p0_future_capture_
        # forbidden`).  Re-read the clock so the decision instant genuinely
        # follows the capture; every other consumer keeps the cycle's as-of.
        native_decision_at_utc = (
            utc_now()
            if official_capture is not None
            and official_capture.get("state") == "CAPTURED"
            else as_of_utc
        )
        if official_packet is not None:
            try:
                compiled_official = _compile_native_ensemble_p0_runtime(
                    read_conn,
                    forward_packet=official_packet,
                    decision_at_utc=native_decision_at_utc,
                    native_oos_snapshot=self.native_oos_snapshot,
                )
                if (
                    isinstance(compiled_official, Mapping)
                    and compiled_official.get("schema")
                    == "calibrated_native_cross_ensemble_p0_packet_v1"
                ):
                    compiled_official = dict(compiled_official)
                    if self.commit_conn is not None:
                        compiled_official[
                            "forward_prediction_persistence"
                        ] = persist_native_ensemble_forward_prediction(
                            self.commit_conn,
                            compiled_official,
                        )
                        p0_inbox_merge = _upsert_native_p0_inbox(
                            self.p0_inbox_path,
                            compiled_packets=[compiled_official],
                            generated_at_utc=as_of_utc,
                        )
                    else:
                        p0_inbox_merge = {
                            "wrote": False,
                            "accepted_count": 0,
                            "packet_count": 0,
                        }
                    self._nwp_lap("nwp_official_compile")
                    rotation_receipt = self._persist_nwp_rotation(
                        station_ids=station_allowlist,
                        scopes=scopes,
                        selected_scopes=[native_scope],
                        outcomes=[{
                            "scope_key": nwp_rotation_scope_key(native_scope),
                            "state": "OFFICIAL_NATIVE_REUSED",
                            "candidate_only": False,
                            "reason": "official_native_precedence",
                        }],
                        as_of_utc=as_of_utc,
                    )
                    return {
                        "schema": "bayes_basket_target_resident_nwp_cycle_v1",
                        "state": "official_native_reused",
                        "reason": "official_native_precedence",
                        "arrival_drain": arrival_drain,
                        **rotation_receipt,
                        "station_id": native_station,
                        "event_date": native_event_date,
                        "source_role": "official_native",
                        "official_packet_reused": True,
                        "republisher_fallback_used": False,
                        "official_probe_reason": official_probe_reason,
                        "official_native_capture": official_capture,
                        "native_p0_compile": compiled_official,
                        "p0_inbox_path": str(self.p0_inbox_path),
                        "p0_inbox_wrote": bool(p0_inbox_merge.get("wrote")),
                        "writes_target_database": False,
                        "calls_order_gateway": False,
                        "places_orders": False,
                        "live_submit_authorized": False,
                        "orders_submitted": 0,
                    }
                official_probe_reason = "official_native_compile_rejected"
            except Exception as exc:
                official_probe_reason = (
                    "official_native_compile_rejected:"
                    f"{type(exc).__name__}:{exc}"
                )
        self._nwp_lap("nwp_official_compile")
        official_capture_state = str(
            (official_capture or {}).get("state") or ""
        )
        if (
            official_packet is None
            and official_capture_state
            in OFFICIAL_NATIVE_CAPTURE_PENDING_STATES
        ):
            # Official first: this scope's own packet is already being fetched,
            # so buying an aggregator one now pays full price for evidence that
            # will be superseded before it is used.
            rotation_receipt = self._persist_nwp_rotation(
                station_ids=station_allowlist,
                scopes=scopes,
                selected_scopes=[native_scope],
                outcomes=[{
                    "scope_key": nwp_rotation_scope_key(native_scope),
                    "state": "AWAITING_OFFICIAL_NATIVE",
                    "candidate_only": False,
                    "reason": (
                        "official_native_capture_"
                        f"{official_capture_state.lower()}"
                    ),
                }],
                as_of_utc=as_of_utc,
            )
            return {
                "schema": "bayes_basket_target_resident_nwp_cycle_v1",
                "state": "awaiting_official_native",
                "reason": (
                    "official_native_precedence_no_republisher_spend"
                ),
                "arrival_drain": arrival_drain,
                **rotation_receipt,
                "station_id": native_station,
                "event_date": native_event_date,
                "source_role": "official_native",
                "official_packet_reused": False,
                "republisher_fallback_used": False,
                "official_probe_reason": official_probe_reason,
                "official_native_capture": official_capture,
                "writes_target_database": False,
                "calls_order_gateway": False,
                "places_orders": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
        self._nwp_lap("nwp_after_official_paths")
        native_rows = [
            row
            for row in registry.get("rows") or []
            if isinstance(row, Mapping)
            and str(row.get("station_id") or "").strip().upper()
            == native_station
            and str(row.get("event_date") or "")
            == native_event_date
        ]
        if (
            getattr(self, "_republisher_quota_exhausted_utc_date", None)
            == _utc_date(as_of_utc)
        ):
            # Skip the spend, keep the turn.  The scope still advances and its
            # official native capture was already kicked off above; only the
            # republisher fallback is withheld, and only until the quota day
            # rolls over.  This is not a blocked state: nothing failed here,
            # and reporting it as blocked would hide whether anything else is
            # wrong with the sweep.
            rotation_receipt = self._persist_nwp_rotation(
                station_ids=station_allowlist,
                scopes=scopes,
                selected_scopes=[native_scope],
                outcomes=[{
                    "scope_key": nwp_rotation_scope_key(native_scope),
                    "state": "REPUBLISHER_QUOTA_EXHAUSTED",
                    "candidate_only": False,
                    "reason": "republisher_daily_quota_exhausted",
                }],
                as_of_utc=as_of_utc,
            )
            return {
                "schema": (
                    "bayes_basket_target_resident_native_ensemble_cycle_v1"
                ),
                "state": "republisher_quota_exhausted",
                "reason": "republisher_daily_quota_exhausted",
                "station_id": native_station,
                "event_date": native_event_date,
                "source_role": "official_native",
                "official_packet_reused": False,
                "republisher_fallback_used": False,
                "official_probe_reason": official_probe_reason,
                "official_native_capture": official_capture,
                **rotation_receipt,
                "writes_target_database": False,
                "calls_order_gateway": False,
                "places_orders": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
        try:
            coordinates = station_coordinates(native_station)
            native_packet = capture_open_meteo_ensemble_scope(
                station_id=native_station,
                event_date=native_event_date,
                latitude=float(coordinates["latitude"]),
                longitude=float(coordinates["longitude"]),
                settlement_timezone=str(
                    native_scope["settlement_timezone"]
                ),
                registry_rows=native_rows,
                captured_at_utc=as_of_utc,
            )
            native_inbox_path = (
                self.nwp_runtime_root
                / "native_ensemble_forward_inbox.json"
            )
            existing_packets: list[dict[str, Any]] = []
            if native_inbox_path.is_file():
                existing_inbox = load_bounded_json(
                    native_inbox_path
                )
                if (
                    existing_inbox.get("schema")
                    != "native_ensemble_forward_inbox_v1"
                    or not isinstance(
                        existing_inbox.get("packets"), list
                    )
                ):
                    raise ContractError(
                        "native_ensemble_forward_inbox_invalid"
                    )
                existing_packets = [
                    dict(item)
                    for item in existing_inbox["packets"]
                    if isinstance(item, Mapping)
                ]
            same_snapshot = next(
                (
                    item
                    for item in existing_packets
                    if str(item.get("station_id") or "")
                    == native_station
                    and str(item.get("event_date") or "")
                    == native_event_date
                    and str(
                        item.get("snapshot_content_sha256") or ""
                    )
                    == str(
                        native_packet[
                            "snapshot_content_sha256"
                        ]
                    )
                ),
                None,
            )
            if same_snapshot is None:
                merged_packets = [
                    item
                    for item in existing_packets
                    if not (
                        str(item.get("station_id") or "")
                        == native_station
                        and str(item.get("event_date") or "")
                        == native_event_date
                    )
                ]
                merged_packets.append(native_packet)
                # Drop packets for days that are over in every timezone on
                # earth.  A forward packet describes a forecast for a day that
                # has not settled; once it has, the packet is neither evidence
                # nor a candidate, and keeping it only consumes the budget the
                # open days need.  The official inbox has always pruned this
                # way; this one never did, so it accumulated seven days of
                # closed scopes.
                horizon = _utc_date(as_of_utc) - timedelta(days=1)
                merged_packets = [
                    item
                    for item in merged_packets
                    if (
                        _event_date_or_none(
                            str(item.get("event_date") or "")
                        )
                        is None
                        or _event_date_or_none(
                            str(item.get("event_date") or "")
                        )
                        >= horizon
                    )
                ]
                merged_packets.sort(
                    key=lambda item: (
                        str(item.get("event_date") or ""),
                        str(item.get("station_id") or ""),
                    )
                )
                if len(merged_packets) > MAX_REPUBLISHER_INBOX_PACKETS:
                    merged_packets = merged_packets[
                        -MAX_REPUBLISHER_INBOX_PACKETS:
                    ]
                inbox_identity = {
                    "schema": "native_ensemble_forward_inbox_v1",
                    "packets": merged_packets,
                }
                native_inbox = {
                    **inbox_identity,
                    "content_sha256": content_sha256(
                        inbox_identity
                    ),
                }
                inbox_wrote = write_bounded_json_if_changed(
                    native_inbox_path,
                    native_inbox,
                )
            else:
                native_packet = same_snapshot
                inbox_wrote = False
            native_p0_compile: dict[str, Any]
            try:
                if native_packet.get("schema") != OFFICIAL_NATIVE_FORWARD_PACKET_SCHEMA:
                    raise ContractError(
                        "republisher_no_live_selection_not_forward_p0_authority"
                    )
                native_p0_compile = _compile_native_ensemble_p0_runtime(
                    read_conn,
                    forward_packet=native_packet,
                    decision_at_utc=as_of_utc,
                    native_oos_snapshot=self.native_oos_snapshot,
                )
            except Exception as exc:
                native_p0_compile = {
                    "state": "FAIL_CLOSED_NO_P0",
                    "reason": f"{type(exc).__name__}:{exc}",
                    "station_id": native_station,
                    "event_date": native_event_date,
                    "calls_order_gateway": False,
                    "orders_submitted": 0,
                    "live_submit_authorized": False,
                }
            p0_inbox_merge = _upsert_native_p0_inbox(
                self.p0_inbox_path,
                compiled_packets=(
                    [native_p0_compile]
                    if native_p0_compile.get("schema")
                    == "calibrated_native_cross_ensemble_p0_packet_v1"
                    else []
                ),
                generated_at_utc=as_of_utc,
            )
            p0_inbox_wrote = bool(p0_inbox_merge["wrote"])
            rotation_receipt = self._persist_nwp_rotation(
                station_ids=station_allowlist,
                scopes=scopes,
                selected_scopes=[native_scope],
                outcomes=[{
                    "scope_key": nwp_rotation_scope_key(native_scope),
                    "state": "CAPTURED_CANDIDATE",
                    "candidate_only": True,
                    "reason": (
                        "native_ensemble_calibration_and_cross_family_oos_required"
                    ),
                }],
                as_of_utc=as_of_utc,
            )
            return {
                "schema": "bayes_basket_target_resident_native_ensemble_cycle_v1",
                "state": "candidate_captured_no_p0",
                "reason": (
                    "native_ensemble_calibration_and_cross_family_oos_required"
                ),
                "station_id": native_station,
                "event_date": native_event_date,
                "available_product_count": len(
                    native_packet.get("systems") or []
                ),
                "source_role": "aggregator_republisher",
                "official_packet_reused": False,
                "republisher_fallback_used": True,
                "official_probe_reason": official_probe_reason,
                "official_native_capture": official_capture,
                "unavailable_product_count": len(
                    native_packet.get("unavailable_products") or []
                ),
                "cross_model_gate": native_packet.get(
                    "cross_model_gate"
                ),
                "native_p0_compile": native_p0_compile,
                "p0_inbox_path": str(self.p0_inbox_path),
                "p0_inbox_wrote": p0_inbox_wrote,
                "p0_inbox_packet_count": p0_inbox_merge[
                    "packet_count"
                ],
                "snapshot_content_sha256": native_packet.get(
                    "snapshot_content_sha256"
                ),
                "inbox_path": str(native_inbox_path),
                "inbox_wrote": inbox_wrote,
                **rotation_receipt,
                "writes_target_database": False,
                "calls_order_gateway": False,
                "places_orders": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
        except Exception as exc:
            # A daily quota is a property of the day, not of this scope.  Once
            # the republisher says the day is spent, remember it so the rest of
            # the sweep stops paying a network round trip per scope to be told
            # again -- the scopes still advance, which is what lets their
            # official native captures start.
            if _is_republisher_daily_quota_exhausted(exc):
                self._republisher_quota_exhausted_utc_date = _utc_date(
                    as_of_utc
                )
            # The cursor advanced before this scope failed.  Persisting here is
            # what stops the next sweep from replaying the same failing scope
            # forever after a restart.
            rotation_receipt = self._persist_nwp_rotation(
                station_ids=station_allowlist,
                scopes=scopes,
                selected_scopes=[native_scope],
                outcomes=[{
                    "scope_key": nwp_rotation_scope_key(native_scope),
                    "state": "BLOCKED_FAIL_CLOSED",
                    "candidate_only": False,
                    "reason": f"{type(exc).__name__}:{exc}"[:200],
                }],
                as_of_utc=as_of_utc,
            )
            return {
                "schema": "bayes_basket_target_resident_native_ensemble_cycle_v1",
                "state": "blocked_fail_closed",
                "reason": f"{type(exc).__name__}:{exc}",
                "station_id": native_station,
                "event_date": native_event_date,
                **rotation_receipt,
                "writes_target_database": False,
                "calls_order_gateway": False,
                "places_orders": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }

    def _assert_db_activation(self, activation: Mapping[str, Any]) -> None:
        if self.commit_conn is None:
            return
        assert_target_database_owner(self.commit_conn)
        row = self.commit_conn.execute(
            "SELECT state,activation_sha256,activation_json "
            "FROM basket_strategy_activation_state WHERE singleton=1"
        ).fetchone()
        expected = str(activation.get("activation_contract_sha256") or "")
        if row is None or str(row[0]) != "enabled" or str(row[1] or "") != expected:
            raise RuntimeError("target_activation_state_drift")
        try:
            details = json.loads(str(row[2] or "{}"))
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            raise RuntimeError("target_activation_state_json_invalid") from exc
        if not isinstance(details, Mapping) or details.get("execution_mode") != PRODUCTION_EXECUTION_MODE:
            raise RuntimeError("target_activation_state_mode_drift")
        # Each mode asserts its own boundaries, the same way
        # open_target_writer_if_enabled does.  These four were hard-coded
        # False from the day this file was written and stayed that way
        # through the go-live flip, so the row the DB would have to carry to
        # satisfy the sha check above -- the live contract -- is exactly the
        # row this loop then rejected.  Any DB row and any file that disagree
        # still fail; what no longer fails is a live deployment agreeing with
        # itself.
        expected = (
            PRODUCTION_EXECUTION_MODE == "production_live"
        )
        for key in ("live_decision_write_authorized", "live_submit_authorized", "places_orders", "calls_order_gateway"):
            if details.get(key) is not expected:
                raise RuntimeError(f"target_activation_state_{key}_drift")

    def _capture_account_equity(self, *, as_of_utc: str) -> dict[str, Any]:
        """Charter 141: append one real-account read, at most once a minute."""

        if self.commit_conn is None:
            return {"state": "not_attempted", "reason": "no_writer"}
        # Charter 184: the positions read runs on a background thread in the
        # live resident only -- the one process whose environment says so --
        # and the capture takes its number when it is no older than a
        # capture interval.  Until the first background read lands, and
        # whenever one fails, the capture reads in line as before.
        if (
            str(os.environ.get("PM_TARGET_EXECUTION_MODE", "") or "").strip()
            == "production_live"
            and str(os.environ.get("PM_ACCOUNT_POSITIONS_PREFETCH", "1")).strip()
            not in {"0", "false", "off"}
        ):
            try:
                ensure_positions_prefetch()
            except Exception:  # noqa: BLE001 -- the in-line read is the fallback
                pass
        if not getattr(self, "_account_equity_table_ensured", False):
            # Created before the first read succeeds, so a store whose first
            # read fails reads as stale (production refuses) rather than as
            # a store that never had an account (which sizes off the budget).
            with _writer_transaction(
                self.commit_conn, savepoint="basket_target_account_equity_ddl"
            ):
                ensure_account_equity_table(self.commit_conn)
            self._account_equity_table_ensured = True
        last = getattr(self, "_account_equity_last_capture_monotonic", None)
        now = time.monotonic()
        if last is not None and now - float(last) < ACCOUNT_EQUITY_CAPTURE_INTERVAL_SECONDS:
            return {"state": "throttled"}
        self._account_equity_last_capture_monotonic = now
        conn = self.commit_conn
        receipt = capture_account_equity(
            conn,
            as_of_utc=as_of_utc,
            write=lambda: _writer_transaction(
                conn, savepoint="basket_target_account_equity"
            ),
            budget_usdc=_resolve_target_remaining_budget(),
        )
        self._account_equity_last = receipt
        return receipt

    def _refresh_account_equity(self) -> None:
        """A throttled mid-cycle read; failures stay in the receipt, never raise."""

        try:
            self._capture_account_equity(as_of_utc=utc_now())
        except Exception as exc:  # noqa: BLE001 -- observational lane
            self._account_equity_last = {
                "state": "blocked_fail_closed",
                "reason": f"{type(exc).__name__}:{exc}"[:160],
            }

    def _account_book_equity_usdc(
        self, *, as_of_utc: str,
    ) -> tuple[float | None, str]:
        """The book's equity for sizing: the real account, capped by the budget.

        ``(None, "account_equity_table_absent")`` on a store that has never
        read the account (a fixture), which sizes exactly as before;
        ``(None, "account_equity_stale")`` when the table is there and no
        read is fresh -- the caller must not size anything off that.
        """

        conn = self.conn if self.conn is not None else self.commit_conn
        if conn is None or not account_equity_table_present(conn):
            return None, "account_equity_table_absent"
        row = load_account_equity(conn, as_of_utc=as_of_utc)
        if row is None:
            return None, "account_equity_stale"
        return (
            budget_capped_equity(
                row["equity_usdc"], _resolve_target_remaining_budget()
            ),
            "recorded",
        )

    def _scope_cycle_guard(
        self,
        *,
        station_id: str,
        event_date: str,
        candidate: Mapping[str, Any],
    ) -> dict[str, Any] | None:
        """Return a no-write decision when an unclosed target candidate exists."""

        if self.commit_conn is None:
            return None
        has_training_facts = self.commit_conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' "
            "AND name='basket_policy_training_fact'"
        ).fetchone() is not None
        candidate_scope_key = ""
        if has_training_facts:
            market_snapshot = candidate.get("production_market_snapshot")
            if not isinstance(market_snapshot, Mapping):
                raise ContractError(
                    "target_authority_zero_write_market_snapshot_missing"
                )
            candidate_scope_key = delta_v2_decision_scope_key(
                compiled_plan=candidate,
                market_snapshot=market_snapshot,
            )
        # Ask for this candidate's own scope, not the station-day's most
        # recent one.  ``decision_scope_key`` is UNIQUE, so the question "has
        # this exact decision already been recorded" has a direct answer, and
        # reading the day's latest row answered a different question: the
        # three stages interleave inside one station-day, so a P0 candidate
        # was routinely compared against the P1 fact written between it and
        # the last P0.  The keys differ, the guard falls through, and the
        # ledger is entered with a key it already holds -- where the fact
        # cannot land under this cycle_id, and the version-vector rows are
        # written before the fact writer is even asked.
        scope_fact = (
            self.commit_conn.execute(
                "SELECT fact_id,cycle_id,decision_id,decision_scope_key "
                "FROM basket_policy_training_fact WHERE decision_scope_key=?",
                (candidate_scope_key,),
            ).fetchone()
            if has_training_facts and candidate_scope_key
            else None
        )
        latest_fact = scope_fact
        if latest_fact is not None:
            return {
                "schema": SCHEMA,
                "ok": True,
                "state": "retained_existing_authority_decision",
                "reason": "target_authority_input_zero_write_guard",
                "cycle_id": str(latest_fact[1] or ""),
                "decision_id": str(latest_fact[2] or ""),
                "training_fact_id": str(latest_fact[0] or ""),
                "decision_scope_key": candidate_scope_key,
                "writes_target_ledger": False,
                "execution_mode": PRODUCTION_EXECUTION_MODE,
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
        has_decisions = self.commit_conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='auto_trade_decisions'"
        ).fetchone() is not None
        if has_decisions:
            rows = self.commit_conn.execute(
                # A cycle with no decision row carries no authority, and
                # this table is the blocking authority: the row that says
                # what was decided is the row that makes a cycle standing.
                # The NULL arm admitted the opposite, and on 2026-09-02 the
                # decision-identity migration made that fatal -- it
                # collapsed 67,492 decisions into 27,405 by economic
                # content, leaving exactly 40,087 cycle rows whose decision
                # had been merged into a sibling's.  768 of them name event
                # 2026-09-03, so the moment a late station passed its P1
                # entry window and reached this guard, two orphans answered
                # and the scope was refused
                # target_prepared_cycle_retention_violation on every cycle
                # after -- fifteen station-days at 14:08Z, and a cycle that
                # committed nothing at all published a reason-less
                # blocked_fail_closed.  The orphan rows stay: the ledger is
                # append-only and the reader is what was wrong.
                "SELECT c.cycle_id,c.plan_id,c.state FROM basket_target_execution_cycles c "
                "JOIN auto_trade_decisions d ON d.cycle_id=c.cycle_id "
                "WHERE c.station_id=? AND c.event_date=? AND c.state IN "
                "('prepared','submitting','submitted','reconcile_required') "
                "AND d.decided_state<>'blocked' "
                "ORDER BY c.created_at DESC,c.rowid DESC LIMIT 2",
                (station_id, event_date),
            ).fetchall()
        else:
            # Small in-memory fixtures from the guard tests predate the M5
            # decision table.  Preserve their strict retention semantics.
            rows = self.commit_conn.execute(
                "SELECT cycle_id,plan_id,state FROM basket_target_execution_cycles "
                "WHERE station_id=? AND event_date=? AND state IN "
                "('prepared','submitting','submitted','reconcile_required') "
                "ORDER BY created_at DESC, rowid DESC LIMIT 2",
                (station_id, event_date),
            ).fetchall()
        if not rows:
            return None
        if len(rows) > MAX_PREPARED_CYCLES_PER_SCOPE:
            return _blocked(
                "target_prepared_cycle_retention_violation",
                station_id=station_id,
                event_date=event_date,
            )
        current_plan = ""
        plan = candidate.get("plan")
        if isinstance(plan, Mapping):
            current_plan = str(plan.get("plan_id") or "")
        latest = rows[0]
        state = str(latest[2] or "")
        if state != "prepared":
            return _blocked(
                "target_existing_cycle_not_quiescent",
                station_id=station_id,
                event_date=event_date,
            )
        # Full production facts can atomically retire a purely local no-live
        # prepared candidate when newer P1/WS authority changes the scope.
        # Legacy/minimal fixtures lack the facts required to prove this and
        # therefore retain the conservative zero-write behavior.
        #
        # The fact this arm needs is the retiring cycle's own, not the
        # station-day's most recent.  Blocked decisions write training facts
        # too -- 9,913 of 10,392 as of 2026-08-26 -- so reading the day's
        # latest disarmed the arm permanently the first time any scope was
        # refused after a candidate was prepared: the guard fell through to a
        # zero-write retention and that station-day committed no further
        # decision, while its reservation had nothing left that could ever
        # release it.  Measured on the cycles the settled-day sweep retired,
        # 95 of 113 had been disarmed this way; EPWA 2026-08-16 by a blocked
        # fact written four hours before Warsaw's event day opened, so the
        # whole day wrote nothing.
        retiring_fact = (
            self.commit_conn.execute(
                "SELECT fact_id,cycle_id,decision_id,decision_scope_key "
                "FROM basket_policy_training_fact WHERE cycle_id=? "
                "ORDER BY decision_at_utc DESC,rowid DESC LIMIT 1",
                (str(latest[0]),),
            ).fetchone()
            if has_training_facts
            else None
        )
        if (
            has_training_facts
            and retiring_fact is not None
            and candidate_scope_key
            # Same inputs as the candidate already prepared: there is nothing
            # to supersede, and asking the ledger to would only earn a
            # ``prepared_supersession_scope_unchanged`` refusal that fails the
            # whole commit.  Retain instead.
            and str(retiring_fact[3] or "") != candidate_scope_key
        ):
            return {
                "schema": SCHEMA,
                "ok": True,
                "state": "supersede_existing_prepared_candidate",
                "reason": "target_authority_input_superseded",
                "cycle_id": str(latest[0]),
                "decision_id": str(retiring_fact[2] or ""),
                "training_fact_id": str(retiring_fact[0] or ""),
                "old_decision_scope_key": str(retiring_fact[3] or ""),
                "new_decision_scope_key": candidate_scope_key,
                "writes_target_ledger": True,
                "execution_mode": PRODUCTION_EXECUTION_MODE,
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
        return {
            "schema": SCHEMA,
            "ok": True,
            "state": "retained_existing_prepared_candidate",
            "reason": "target_prepared_cycle_retention_guard",
            "cycle_id": str(latest[0]),
            "existing_plan_id": str(latest[1]),
            "candidate_plan_id": current_plan,
            "max_prepared_cycles_per_scope": MAX_PREPARED_CYCLES_PER_SCOPE,
            "writes_target_ledger": False,
            "execution_mode": PRODUCTION_EXECUTION_MODE,
            "places_orders": False,
            "calls_order_gateway": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }

    @staticmethod
    def _event_day_started(
        event_date: str,
        *,
        settlement_timezone: str,
        as_of_utc: str,
    ) -> bool:
        """Allow only registry settlement days that have started.

        A future market must not enter the decision scope before the event
        day starts in the fixed ET timezone.
        """

        try:
            state = event_day_window(
                event_date,
                as_of_utc=as_of_utc,
                target_timezone=settlement_timezone,
            )["state"]
        except Exception:
            # A malformed target identity is not a reason to manufacture a
            # blocked decision row.  Leave it to the owning ingress audit.
            return False
        return state in {"open", "closed"}

    @staticmethod
    def _event_day_open(
        event_date: str,
        *,
        settlement_timezone: str,
        as_of_utc: str,
    ) -> bool:
        """Allow decisions only during the registry settlement day.

        A closed day remains available to offline truth reconstruction,
        calibration and audit, but it is no longer an executable target
        scope.  Keeping this distinction at the resident worker boundary
        prevents every poll after the ET close from appending another
        historical no-live decision.
        """

        try:
            state = event_day_window(
                event_date,
                as_of_utc=as_of_utc,
                target_timezone=settlement_timezone,
            )["state"]
        except Exception:
            return False
        return state == "open"

    def _listing_scope_turn_path(self) -> Path:
        return self.nwp_runtime_root / "listing_scope_turn.json"

    # ------------------------------------------------------------------
    # The maintenance lane: same writer, same cycle, its own budget.
    # ------------------------------------------------------------------

    def _maintenance_turn_path(self) -> Path:
        return self.nwp_runtime_root / "maintenance_lane_turn.json"

    def _load_maintenance_turn(self) -> dict[str, Any]:
        """When each maintenance stage was last served.

        Persisted beside the listing turn and the NWP cursor, for the same
        reason: held in memory, every restart would reseed the rotation to
        its head, and restarts here are not rare -- nineteen on 2026-09-02.
        A stage at the tail would then be served almost never, which is the
        starvation this budget must not introduce while removing the
        overrun.
        """

        recorded = getattr(self, "_maintenance_turn_cache", None)
        if recorded is not None:
            return recorded
        self._maintenance_cost_cache = {}
        loaded: dict[str, Any] = {}
        try:
            raw = load_bounded_json(self._maintenance_turn_path())
            if isinstance(raw, Mapping):
                served = raw.get("served_at_utc")
                if isinstance(served, Mapping):
                    loaded = {
                        str(key): str(value)
                        for key, value in served.items()
                        if str(value or "").strip()
                    }
                costs = raw.get("last_elapsed_sec")
                if isinstance(costs, Mapping):
                    self._maintenance_cost_cache = {
                        str(key): float(value)
                        for key, value in costs.items()
                        if isinstance(value, (int, float))
                    }
        except Exception:  # noqa: BLE001 -- a turn, not a fact
            loaded = {}
        self._maintenance_turn_cache = loaded
        return loaded

    def _maintenance_unserved_seconds(
        self, stage: str, *, now_utc: str
    ) -> float | None:
        """How long since this stage last ran, or None if it never has."""

        served = self._load_maintenance_turn().get(stage)
        if not served:
            return None
        try:
            return (
                datetime.fromisoformat(now_utc.replace("Z", "+00:00"))
                - datetime.fromisoformat(str(served).replace("Z", "+00:00"))
            ).total_seconds()
        except ValueError:
            return None

    def _maintenance_admits(self, stage: str) -> bool:
        """Whether this cycle can afford to run ``stage``.

        Two ways in.  The budget, while the cycle has not yet spent what a
        decision can afford to wait for; and starvation, which overrides the
        budget outright -- a stage unserved for MAINTENANCE_STARVATION_SEC
        runs even in a cycle that has already spent its allowance, because a
        lane that is never served is a worse failure than one cycle that
        runs long.  A stage that has never run is starved by definition, so
        a fresh worker serves every one of them on its first cycle.
        """

        if stage not in MAINTENANCE_STAGES:
            return True
        admissions = self._maintenance_admissions_map()
        unserved = self._maintenance_unserved_seconds(
            stage, now_utc=utc_now()
        )
        if unserved is None or unserved >= MAINTENANCE_STARVATION_SEC:
            admissions[stage] = "starved"
            return True
        # What it is about to spend, not what has already been spent.
        # Checking only the running total admits a stage that costs three
        # times the whole allowance, because at the moment it is asked the
        # total is still zero -- which is how a budget becomes decorative.
        # The cost is the stage's own last measured one; a stage with no
        # record has never run and is admitted by the starvation arm above.
        expected = self._maintenance_last_cost(stage)
        if self._maintenance_spent() + expected <= self._maintenance_budget():
            admissions[stage] = "budget"
            return True
        admissions[stage] = "deferred"
        return False

    def _maintenance_last_cost(self, stage: str) -> float:
        costs = getattr(self, "_maintenance_cost_cache", None)
        if costs is None:
            # The two caches are filled by the same read, so an unfilled
            # cost cache means the read has not happened -- or was skipped
            # because the turn cache was already warm, which would leave the
            # costs empty and every stage looking free.
            self._maintenance_turn_cache = None
            self._load_maintenance_turn()
            costs = getattr(self, "_maintenance_cost_cache", None) or {}
            self._maintenance_cost_cache = costs
        return float(costs.get(stage, 0.0) or 0.0)

    def _maintenance_admissions_map(self) -> dict[str, str]:
        admissions = getattr(self, "_maintenance_admissions", None)
        if admissions is None:
            admissions = {}
            self._maintenance_admissions = admissions
        return admissions

    def _maintenance_spent(self) -> float:
        return float(getattr(self, "_maintenance_spent_sec", 0.0) or 0.0)

    def _maintenance_budget(self) -> float:
        """The R0 deadline, which is what a lower tier may spend.

        Read from the activation the cycle is running under, not typed
        here: the quote lease is the deadline R0 is racing, so it is also
        the most a deferrable tier may take from it.  Two copies of one
        number would drift, and the copy in the policy is the one
        production enforces.
        """

        budget = getattr(self, "_quote_lease_seconds", None)
        if isinstance(budget, (int, float)) and budget > 0:
            return float(budget)
        return MAINTENANCE_BUDGET_SEC

    def _record_quote_lease_seconds(self, activation: Mapping[str, Any]) -> None:
        """Remember this cycle's R0 deadline for the tiers below it."""

        try:
            policy = activation.get("quote_freshness_policy")
            age = float((policy or {}).get("max_quote_age_seconds"))
            self._quote_lease_seconds = age if age > 0 else None
        except (AttributeError, TypeError, ValueError):
            self._quote_lease_seconds = None

    def _record_maintenance_served(
        self, stage: str, elapsed_sec: float
    ) -> None:
        """Charge a served stage to the budget and persist its turn."""

        self._maintenance_spent_sec = self._maintenance_spent() + max(
            0.0, float(elapsed_sec)
        )
        self._add_span(
            "maintenance_lane", max(0.0, float(elapsed_sec)) * 1000.0,
            label=stage,
        )
        served = dict(self._load_maintenance_turn())
        served[stage] = utc_now()
        self._maintenance_turn_cache = served
        costs = dict(getattr(self, "_maintenance_cost_cache", None) or {})
        costs[stage] = round(max(0.0, float(elapsed_sec)), 1)
        self._maintenance_cost_cache = costs
        try:
            write_bounded_json_if_changed(
                self._maintenance_turn_path(),
                {
                    "schema": "bayes_basket_target_maintenance_lane_turn_v1",
                    "served_at_utc": served,
                    "last_elapsed_sec": costs,
                    "budget_seconds": self._maintenance_budget(),
                    "starvation_seconds": MAINTENANCE_STARVATION_SEC,
                },
            )
        except Exception:  # noqa: BLE001 -- telemetry and a restart hint
            pass

    def _maintenance_deferred(self, stage: str) -> dict[str, Any]:
        """The receipt a deferred stage leaves behind.

        The state word carries neither BLOCK nor FAIL on purpose: the board
        reads lane states by substring, and a deferred maintenance pass is
        the lane working as designed, not an outage.  It still reports how
        long the stage has gone unserved, so a lane that stops being
        scheduled at all stays visible rather than merely quiet.
        """

        unserved = self._maintenance_unserved_seconds(
            stage, now_utc=utc_now()
        )
        return {
            "schema": "bayes_basket_target_maintenance_deferred_v1",
            "state": "DEFERRED_MAINTENANCE_BUDGET",
            "stage": stage,
            "reason": "maintenance_budget_spent",
            "budget_seconds": self._maintenance_budget(),
            "spent_seconds": round(self._maintenance_spent(), 1),
            "unserved_seconds": (
                round(unserved, 1) if unserved is not None else None
            ),
            "starvation_seconds": MAINTENANCE_STARVATION_SEC,
            "written_count": 0,
            "appended_count": 0,
            "calls_order_gateway": False,
            "places_orders": False,
            "orders_submitted": 0,
            "live_submit_authorized": False,
        }

    def _maintenance_lane_report(self) -> dict[str, Any]:
        """What this cycle spent on maintenance, and what it put off."""

        now = utc_now()
        stages: dict[str, Any] = {}
        for stage in MAINTENANCE_STAGES:
            unserved = self._maintenance_unserved_seconds(stage, now_utc=now)
            stages[stage] = {
                "admitted": self._maintenance_admissions_map().get(
                    stage, ""
                ),
                "unserved_seconds": (
                    round(unserved, 1) if unserved is not None else None
                ),
                "last_elapsed_sec": self._maintenance_last_cost(stage),
            }
        return {
            "schema": "bayes_basket_target_maintenance_lane_v1",
            "budget_seconds": self._maintenance_budget(),
            "budget_source": (
                "quote_lease"
                if getattr(self, "_quote_lease_seconds", None)
                else "fallback_constant"
            ),
            "spent_seconds": round(self._maintenance_spent(), 1),
            "starvation_seconds": MAINTENANCE_STARVATION_SEC,
            "stages": stages,
            "tiers": self._tier_spend_report(),
        }

    def _tier_spend_report(self) -> dict[str, Any]:
        """What each deadline tier cost this cycle.

        The rule is that a tier may not make a tighter tier late, and until
        this existed the rule could only be argued from the code.  Now the
        receipt answers it: R0's own total is the number the quote lease is
        racing, and every tier below it is a claim on that total.

        Read from the marks, so a stage that is never classified shows up
        as R0 -- the safe default, and a visible one.
        """

        timings = getattr(self, "_stage_timings_ms", None) or {}
        spend: dict[int, float] = {}
        unclassified: list[str] = []
        for stage, value in timings.items():
            if stage in {"cycle_total", "unattributed"}:
                continue
            if not isinstance(value, (int, float)):
                continue
            tier = STAGE_TIER.get(stage)
            if tier is None:
                tier = STAGE_TIER_R0_DECISION
                unclassified.append(stage)
            spend[tier] = spend.get(tier, 0.0) + float(value)
        return {
            "seconds_by_tier": {
                f"R{tier}": round(value / 1000.0, 1)
                for tier, value in sorted(spend.items())
            },
            # A stage nobody classified is charged to the decision path,
            # because that is what an unclassified stage does to it.
            "unclassified_stages": sorted(unclassified),
        }

    def _take_listing_scope_turn(self, *, now_utc: str | None = None) -> bool:
        """Whether this cycle serves the listed days.

        Alternates with the current day, and the alternation is persisted
        beside the NWP rotation cursor rather than held in memory.  Held in
        memory it was reseeded to "current day first" by every restart, and
        restarts are not rare here: nineteen on 2026-09-02, each from a
        concurrent session redeploying, most of them inside one cycle of
        the last.  A listed day's turn came second every time and therefore
        almost never came at all -- charter 48 says listing is entry, and
        the d2 day is the one only this lane can open (the 2026-09-01
        stage-governs-its-own-day ruling).  Now a restart resumes the
        alternation where it stood, and a listed day that has not been
        served for ``LISTING_SCOPE_TURN_STARVATION_SEC`` takes the next
        cycle regardless of whose turn it was.
        """

        now_text = str(now_utc or utc_now())
        path = self._listing_scope_turn_path()
        recorded: dict[str, Any] = {}
        try:
            loaded = load_bounded_json(path)
            if isinstance(loaded, Mapping):
                recorded = dict(loaded)
        except Exception:  # noqa: BLE001 -- a turn, not a fact
            recorded = {}
        previous_turn = bool(recorded.get("listing_turn", False))
        last_served = str(recorded.get("listing_served_at_utc") or "")
        last_current = str(recorded.get("current_served_at_utc") or "")

        def _starved_since(stamp: str) -> bool:
            if not stamp:
                return True
            try:
                age = (
                    datetime.fromisoformat(now_text.replace("Z", "+00:00"))
                    - datetime.fromisoformat(stamp.replace("Z", "+00:00"))
                ).total_seconds()
            except ValueError:
                return True
            return age >= LISTING_SCOPE_TURN_STARVATION_SEC

        starved = _starved_since(last_served)
        # The override has to be symmetric, or it inverts (measured
        # 2026-09-08).  ``listing_served_at_utc`` only advances on a listing
        # cycle, so once a cycle takes longer than the starvation bound the
        # listed days are starved at EVERY decision and take every cycle
        # forever: the current day's last decision on 2026-09-08 was
        # 10:32:15Z and it had not been served since, while the listed days
        # were served at 11:28.  Its serve interval had been widening all
        # day -- 31, 37, 52, 40 minutes -- as cycles grew past 900s.
        #
        # That is the opposite of what this guard is for.  A listed day is
        # entered on a window measured in days and serving it late "costs it
        # about seven minutes of freshness and nothing else"; the current
        # day carries P1 and the live book, and a completion leg it does not
        # get to judge is a naked position held to settlement.  So the
        # listed days' override yields when the current day is itself
        # starved, and the two fall back to strict alternation -- which is
        # what the alternation was always meant to guarantee.
        current_starved = _starved_since(last_current)
        serve = (not previous_turn) or (starved and not current_starved)
        record = {
            "schema": "bayes_basket_target_listing_scope_turn_v1",
            "listing_turn": bool(serve),
            "listing_served_at_utc": now_text if serve else last_served,
            # Recorded for the same reason the listing stamp is: the
            # override cannot know the current day is starving unless
            # somebody writes down when it last ran.
            "current_served_at_utc": last_current if serve else now_text,
            "decided_at_utc": now_text,
            "starvation_seconds": LISTING_SCOPE_TURN_STARVATION_SEC,
            "starved": bool(starved),
            "current_starved": bool(current_starved),
        }
        try:
            write_bounded_json_if_changed(path, record)
        except Exception:  # noqa: BLE001 -- telemetry and a restart hint
            pass
        self._listing_scope_turn = bool(serve)
        return bool(serve)

    def request_stop(self) -> None:
        """Ask the cycle in flight to stop at its next scope boundary.

        The daemon's SIGTERM handler calls this.  A cycle runs several
        minutes over dozens of scopes; without a boundary to stop at, a
        restart waits on the whole cycle, launchd's exit timeout expires
        first and the process is killed mid-write.  Every scope commits in
        its own transaction, so stopping between two of them loses nothing
        the next cycle will not redo.
        """

        self._stop_requested = True

    @property
    def stop_requested(self) -> bool:
        return bool(getattr(self, "_stop_requested", False))

    def _retire_stranded_prepared_intents(
        self,
        *,
        as_of_utc: str,
        limit: int = 40,
    ) -> dict[str, Any]:
        """Retire prepared intents no cycle will ever submit.

        submit_prepared_intents only ever looks at the intents its own cycle
        just created -- it selects on cycle_id -- so an intent that misses
        that one window is never offered to the exchange again. And a
        prepared intent blocks its own bucket and token: can_submit_next_order
        counts it as pending, so the bucket cannot trade while it sits there.
        Measured 2026-09-01: two intents stranded that way, one on a day still
        open and one on a listing day, both buckets shut.

        Nothing here is deleted. The intent is marked cancelled -- the state
        supersession and settled-day close already use for an intent that
        never became an order -- so the audit trail keeps it and the bucket
        is free.

        Only an intent that cannot still be submitted this cycle: its quote
        has expired, so its limit price describes a market hours gone.  An
        intent whose cycle is current is left alone, and anything that
        reached the exchange -- any state past prepared, or a reconciliation
        row -- is never touched from here.
        """

        receipt: dict[str, Any] = {
            "schema": "bayes_basket_target_intent_retire_v1",
            "state": "no_stranded_intents",
            "examined": 0,
            "retired": 0,
            "retired_scopes": [],
            "places_orders": False,
            "calls_order_gateway": False,
            "orders_submitted": 0,
        }
        if self.commit_conn is None:
            receipt["state"] = "not_attempted"
            return receipt
        try:
            rows = self.commit_conn.execute(
                "SELECT i.order_intent_id, i.bucket, cy.station_id,"
                "       cy.event_date, v.quote_expires_at"
                " FROM basket_target_order_intents i"
                " JOIN basket_target_execution_cycles cy"
                "   ON cy.cycle_id = i.cycle_id"
                " LEFT JOIN basket_target_execution_version_vectors v"
                "   ON v.order_intent_id = i.order_intent_id"
                " LEFT JOIN basket_target_order_reconciliations r"
                "   ON r.order_intent_id = i.order_intent_id"
                " WHERE i.state='prepared' AND r.order_intent_id IS NULL"
                " ORDER BY i.created_at LIMIT ?",
                (int(limit),),
            ).fetchall()
        except sqlite3.Error as exc:
            receipt["state"] = "blocked_fail_closed"
            receipt["reason"] = f"{type(exc).__name__}:{exc}"
            return receipt
        if not rows:
            return receipt
        receipt["examined"] = len(rows)
        stranded: list[tuple[str, str, str, str]] = []
        for intent_id, bucket, station, day, expires_at in rows:
            expiry = str(expires_at or "")
            # No recorded expiry is not a licence to retire: an intent whose
            # freshness cannot be read is left for a reader that can.
            if not expiry or expiry > as_of_utc:
                continue
            stranded.append((str(intent_id), str(bucket), str(station), str(day)))
        if not stranded:
            receipt["state"] = "all_within_quote_lease"
            return receipt
        try:
            with _writer_transaction(
                self.commit_conn,
                savepoint="basket_target_retire_stranded_intents",
            ):
                for intent_id, bucket, station, day in stranded:
                    self.commit_conn.execute(
                        "UPDATE basket_target_order_intents"
                        " SET state='cancelled'"
                        " WHERE order_intent_id=? AND state='prepared'",
                        (intent_id,),
                    )
                    receipt["retired_scopes"].append(
                        f"{station}|{day}|{bucket}"
                    )
            receipt["retired"] = len(stranded)
            receipt["state"] = "committed"
        except Exception as exc:  # noqa: BLE001 -- observational lane
            receipt["state"] = "blocked_fail_closed"
            receipt["reason"] = f"{type(exc).__name__}:{exc}"[:160]
        return receipt

    def _settle_live_cycles(
        self,
        *,
        as_of_utc: str,
        limit: int = 40,
    ) -> dict[str, Any]:
        """Settle live cycles whose orders have all ended and reconciled.

        The counterpart of the no-live runtime's terminal transition for a
        real order: a cycle is a batch of orders, and once every order in
        it has ended (filled, refused, cancelled) with every fill resolved
        by the reconciliation ledger, the batch is over -- its reservation
        is consumed by what was spent and the cycle is ``settled``.  Left
        ``prepared``, such a cycle counts as the station-day's active
        candidate and the atomic commit refuses every later trade decision
        on the day as ``target_active_candidate_supersession_required``,
        which is how the first live half-baskets could not be completed
        (2026-09-05).  Only cycles that filled something: an inert cycle is
        the supersession path's.

        "Filled something" is read off the reconciliation ledger, not the
        intent's end state: a rung that filled in part and was then
        cancelled (charter 94's ordinary ending) is ``cancelled`` over a
        ``resolved_partial`` that holds the shares.  Read as not-filled
        until 2026-09-18, it left KLGA and ZUCK 2026-09-18 standing
        ``prepared`` all day, every decision refused
        ``prepared_supersession_execution_fact_present``.
        """

        receipt: dict[str, Any] = {
            "schema": "bayes_basket_target_live_cycle_settle_v1",
            "state": "no_settleable_cycles",
            "examined": 0,
            "settled": 0,
            "settled_scopes": [],
            "failures": [],
            "places_orders": False,
            "calls_order_gateway": False,
            "orders_submitted": 0,
        }
        if self.commit_conn is None:
            receipt["state"] = "not_attempted"
            return receipt
        try:
            rows = self.commit_conn.execute(
                "SELECT c.cycle_id, c.station_id, c.event_date"
                # Charter 188 (after 187): start from the cycles that have
                # an intent at all -- ~1,660 of them, read off the intents'
                # covering index -- rather than from the ~61,600 prepared
                # cycles, nearly all the identity migration's intent-less
                # orphans (see the last clause's note).  187 put that test
                # first and it still read every prepared cycle's row for
                # its id and created_at: 0.1s warm, 5.5s cold in the cycle.
                # CROSS JOIN fixes the order; every clause below is
                # unchanged, so the rows are the same (cycles sharing one
                # created_at were unordered before and still are).
                " FROM (SELECT DISTINCT cycle_id"
                "       FROM basket_target_order_intents) x"
                " CROSS JOIN basket_target_execution_cycles c"
                "   ON c.cycle_id=x.cycle_id"
                " WHERE c.state='prepared'"
                # Filled something, or every order was refused on the
                # ledger's own account -- both carry reconciliation facts
                # that supersession will not retire.
                "   AND ("
                "     EXISTS ("
                "       SELECT 1 FROM basket_target_order_intents i"
                "       JOIN basket_target_order_reconciliations r"
                "         ON r.order_intent_id=i.order_intent_id"
                "       WHERE i.cycle_id=c.cycle_id"
                "         AND ((i.state='filled'"
                "           AND r.state IN ('resolved_filled','resolved_partial'))"
                "          OR (r.state='resolved_partial' AND r.filled_size>0)))"
                # ...or every order was refused, a leg cancelled before it
                # was ever sent counting with them (no reconciliation, no
                # order event; the ledger re-checks every execution table).
                "     OR (NOT EXISTS ("
                "       SELECT 1 FROM basket_target_order_intents i"
                "       LEFT JOIN basket_target_order_reconciliations r"
                "         ON r.order_intent_id=i.order_intent_id"
                "       WHERE i.cycle_id=c.cycle_id"
                "         AND COALESCE(r.state,'') NOT IN"
                "           ('resolved_not_placed','resolved_cancelled')"
                "         AND NOT (i.state='cancelled'"
                "           AND r.order_intent_id IS NULL"
                "           AND NOT EXISTS ("
                "             SELECT 1 FROM basket_target_order_events e"
                "             WHERE e.order_intent_id=i.order_intent_id)))"
                "       AND EXISTS ("
                "         SELECT 1 FROM basket_target_order_intents i"
                "         JOIN basket_target_order_reconciliations r"
                "           ON r.order_intent_id=i.order_intent_id"
                "         WHERE i.cycle_id=c.cycle_id"
                "           AND r.state IN"
                "             ('resolved_not_placed','resolved_cancelled')))"
                "   )"
                "   AND NOT EXISTS ("
                "     SELECT 1 FROM basket_target_order_intents i"
                "     WHERE i.cycle_id=c.cycle_id"
                "       AND i.state NOT IN ('filled','failed','cancelled'))"
                "   AND NOT EXISTS ("
                "     SELECT 1 FROM basket_target_order_intents i"
                "     JOIN basket_target_order_reconciliations r"
                "       ON r.order_intent_id=i.order_intent_id"
                "     WHERE i.cycle_id=c.cycle_id"
                "       AND r.state IN ('pending','unknown'))"
                # A cycle with no intent at all is not a live cycle: it
                # is one of the ~55,000 prepared rows the identity
                # migration orphaned, and it can never settle.  The
                # all-refused branch above admitted them (NOT EXISTS
                # over zero intents is vacuously true), so from the
                # 2026-09-05 17:34Z restart the forty oldest -- all from
                # 2026-07-26 -- filled the batch every pass and failed
                # ``live_cycle_settle_no_intents``, while eight cycles
                # that had really filled (KAUS/KATL/KORD/ZUUU/ZGGG/ZGSZ/
                # ZSQD/SAEZ 2026-09-07) stayed prepared for seven hours:
                # reservations unconsumed, and every later top-up on
                # those station-days due to be refused as
                # ``target_active_candidate_supersession_required``.
                "   AND EXISTS ("
                "     SELECT 1 FROM basket_target_order_intents i"
                "     WHERE i.cycle_id=c.cycle_id)"
                " ORDER BY c.created_at LIMIT ?",
                (int(limit),),
            ).fetchall()
        except sqlite3.Error as exc:
            receipt["state"] = "blocked_fail_closed"
            receipt["reason"] = f"{type(exc).__name__}:{exc}"
            return receipt
        if not rows:
            return receipt
        receipt["examined"] = len(rows)
        for cycle_id, station, day in rows:
            try:
                with _writer_transaction(
                    self.commit_conn,
                    savepoint="basket_target_live_cycle_settle",
                ):
                    settled = settle_live_cycle_after_terminal_intents(
                        self.commit_conn,
                        cycle_id=str(cycle_id),
                        settled_at_utc=as_of_utc,
                    )
            except Exception as exc:  # noqa: BLE001 -- observational lane
                receipt["failures"].append({
                    "cycle_id": str(cycle_id),
                    "scope": f"{station}|{day}",
                    "reason": f"{type(exc).__name__}:{exc}"[:160],
                })
                continue
            receipt["settled"] += 1
            receipt["settled_scopes"].append({
                "scope": f"{station}|{day}",
                "cycle_id": str(cycle_id),
                "consumed_usdc": settled.get("consumed_usdc"),
            })
        receipt["state"] = (
            "committed" if receipt["settled"] else "blocked_fail_closed"
        )
        return receipt

    def _replay_oos_activation_p0(
        self,
        *,
        oos_station: str,
        valid_native_packets: Sequence[Mapping[str, Any]],
        now: str,
        oos_report: Mapping[str, Any] | None = None,
        passed: bool | None = None,
    ) -> dict[str, Any]:
        """Replay P0 for a station whose cross activation just passed OOS.

        Charter 189: lifted out of the cycle's OOS stage unchanged so the
        same replay serves both the stage's own OOS pass and an activation
        the maintenance worker persisted and handed off.  The replay writes
        forward predictions and the P0 inbox the cycle reads, so it stays in
        the production process either way.
        """

        if passed is None:
            passed = any(
                row.get("state") == "PRODUCTION_NO_LIVE_OOS_PASS"
                for row in (oos_report or {}).get("cross_candidates") or ()
            )
        activation_replay_compiled = []
        activation_replay_failures = []
        if passed:
            replay_packets = sorted(
                (
                    packet
                    for packet in valid_native_packets
                    if str(
                        packet.get("station_id") or ""
                    ).strip().upper()
                    == oos_station
                ),
                key=lambda packet: str(
                    packet.get("event_date") or ""
                ),
                reverse=True,
            )[:MAX_RESIDENT_NWP_SCOPES_PER_CYCLE]
            for replay_packet in replay_packets:
                try:
                    if replay_packet.get("schema") != OFFICIAL_NATIVE_FORWARD_PACKET_SCHEMA:
                        raise ContractError(
                            "republisher_no_live_selection_not_forward_p0_authority"
                        )
                    compiled = (
                        _compile_native_ensemble_p0_runtime(
                            self.commit_conn,
                            forward_packet=replay_packet,
                            decision_at_utc=now,
                            native_oos_snapshot=self.native_oos_snapshot,
                        )
                    )
                except Exception as exc:
                    activation_replay_failures.append({
                        "station_id": oos_station,
                        "event_date": str(
                            replay_packet.get(
                                "event_date"
                            )
                            or ""
                        ),
                        "reason": (
                            f"{type(exc).__name__}:{exc}"
                        ),
                    })
                else:
                    compiled[
                        "forward_prediction_persistence"
                    ] = (
                        persist_native_ensemble_forward_prediction(
                            self.commit_conn,
                            compiled,
                        )
                    )
                    activation_replay_compiled.append(
                        compiled
                    )
        activation_replay = (
            _upsert_native_p0_inbox(
                self.p0_inbox_path,
                compiled_packets=(
                    activation_replay_compiled
                ),
                generated_at_utc=now,
            )
            if activation_replay_compiled
            else {
                "state": "NO_COMPILED_P0",
                "accepted_count": 0,
                "packet_count": 0,
                "wrote": False,
                "calls_order_gateway": False,
                "orders_submitted": 0,
                "live_submit_authorized": False,
            }
        )
        activation_replay["failures"] = (
            activation_replay_failures
        )
        return activation_replay

    def run_maintenance_oos_step(self, *, now_utc: str | None = None) -> dict[str, Any]:
        """Charter 189: one native-ensemble OOS pass, for the maintenance worker.

        The cycle's own pass, lifted whole: the same station choice (a
        station whose truth moved, stalest artifact first, else the
        rotation), the same build and the same persist.  What the cycle
        also chose by -- stations whose native rows arrived in its own
        ingest -- the worker has no ingest to read; it sweeps the fleet
        every few minutes instead of every hour or two, which covers them.
        A station with a passing candidate is handed to the cycle for its
        P0 replay.  Never raises: a failure is the receipt.
        """

        boundary = {
            "isolated_from_probability_and_execution": True,
            "calls_order_gateway": False,
            "orders_submitted": 0,
            "live_submit_authorized": False,
        }
        conn = self.commit_conn
        if conn is None:
            return {"state": "not_attempted", "reason": "no_writer", **boundary}
        now = now_utc or utc_now()
        try:
            stations = _candidate_ensemble_station_ids(
                conn, limit=MAX_FORWARD_P0_STATIONS,
            )
            if not stations:
                return {"state": "no_candidate_stations", **boundary}
            signatures = _native_ensemble_truth_signatures(conn)
            previous = dict(getattr(
                self, "_native_ensemble_oos_truth_signature_by_station", {},
            ))
            changed = [
                station for station, signature in sorted(signatures.items())
                if previous.get(station) != signature
            ]
            if changed:
                vintage = _native_ensemble_artifact_vintage_by_station(conn)
                station = min(changed, key=lambda item: (vintage.get(item, ""), item))
                choice = "truth_moved_stalest_first"
            else:
                cursor = int(getattr(
                    self, "_native_ensemble_oos_station_cursor", 0,
                )) % len(stations)
                station = stations[cursor]
                self._native_ensemble_oos_station_cursor = (cursor + 1) % len(stations)
                choice = "rotation"
            if station in signatures:
                previous[station] = signatures[station]
            self._native_ensemble_oos_truth_signature_by_station = previous
            report = build_native_ensemble_oos(
                conn,
                station_id=station,
                as_of_utc=now,
                min_train_days=FORWARD_ACCUMULATION_MIN_TRAIN_DAYS,
                min_holdout_days=FORWARD_ACCUMULATION_MIN_HOLDOUT_DAYS,
            )
            # The write lock is taken before the persist reads anything:
            # in its own process this pass is a second writer, and a
            # deferred transaction that read first could not upgrade past a
            # cycle commit (SQLITE_BUSY_SNAPSHOT, which no busy handler
            # waits out).  Held for the persist only; the build above ran
            # outside any write.
            with _writer_transaction(
                conn, savepoint="native_ensemble_oos_maintenance",
            ):
                persist = persist_native_ensemble_oos(
                    conn, report, activated_at_utc=now,
                )
        except Exception as exc:  # noqa: BLE001 -- measurement, never fatal
            return {
                "state": "blocked_fail_closed",
                "reason": f"{type(exc).__name__}:{exc}"[:300],
                **boundary,
            }
        passed = any(
            row.get("state") == "PRODUCTION_NO_LIVE_OOS_PASS"
            for row in report["cross_candidates"]
        )
        handoff = None
        if passed:
            handoff = append_oos_handoff({
                "station_id": station,
                "activated_at_utc": now,
                "report_content_sha256": report["content_sha256"],
            })
        return {
            "schema": report["schema"],
            "state": (
                "OOS_READY" if report["cross_candidates"]
                else "ACCUMULATING_STRICT_OOS"
            ),
            "station_id": station,
            "station_choice": choice,
            "changed_truth_station_count": len(changed),
            "registered_system_count": report["registered_system_count"],
            "formal_p0_eligible": report["formal_p0_eligible"],
            "cross_candidate_states": [
                {
                    "season_bin": row["season_bin"],
                    "lead_bucket": row["lead_bucket"],
                    "run_cycle": row["run_cycle"],
                    "state": row["state"],
                }
                for row in report["cross_candidates"]
            ],
            "persist": persist,
            "handed_off": handoff,
            "report_content_sha256": report["content_sha256"],
            **boundary,
        }

    def _delegated_oos_handoff(
        self,
        *,
        valid_native_packets: Sequence[Mapping[str, Any]],
        now: str,
        delegate: Mapping[str, Any],
    ) -> dict[str, Any]:
        """Charter 189: the cycle's half of a delegated OOS pass.

        Replay P0 for every station the maintenance worker has handed over
        since the last cycle -- the replay the cycle's own pass made right
        after a passing persist.  A fresh cycle process looks back
        MAINTENANCE_HANDOFF_RESTART_WINDOW_SEC so a hand-over made while it
        restarted is not lost; replaying one twice writes what it wrote.
        """

        entries = _read_oos_handoff()
        seen = getattr(self, "_oos_handoff_seen_seq", None)
        if seen is None:
            horizon = (
                datetime.now(timezone.utc)
                - timedelta(seconds=MAINTENANCE_HANDOFF_RESTART_WINDOW_SEC)
            ).isoformat().replace("+00:00", "Z")
            seen = max(
                (
                    int(entry.get("seq") or 0) for entry in entries
                    if str(entry.get("activated_at_utc") or "") < horizon
                ),
                default=0,
            )
        fresh = [entry for entry in entries if int(entry.get("seq") or 0) > seen]
        replays: list[dict[str, Any]] = []
        for station in sorted({str(entry.get("station_id") or "") for entry in fresh} - {""}):
            try:
                replay = self._replay_oos_activation_p0(
                    oos_station=station,
                    valid_native_packets=valid_native_packets,
                    now=now,
                    passed=True,
                )
            except Exception as exc:  # noqa: BLE001 -- one station's problem
                replay = {
                    "state": "blocked_fail_closed",
                    "reason": f"{type(exc).__name__}:{exc}"[:200],
                }
            replays.append({"station_id": station, "activation_p0_replay": replay})
        self._oos_handoff_seen_seq = max(
            [seen] + [int(entry.get("seq") or 0) for entry in entries]
        )
        return {
            "state": "delegated_to_maintenance_worker",
            "maintenance_worker": dict(delegate),
            "handoff_count": len(fresh),
            "handoff_replays": replays,
            "isolated_from_probability_and_execution": True,
            "calls_order_gateway": False,
            "orders_submitted": 0,
            "live_submit_authorized": False,
        }

    def _reprice_resting_rungs(
        self,
        *,
        as_of_utc: str,
        limit: int = 200,
    ) -> dict[str, Any]:
        """Charter 94: sync every resting rung with the exchange, then cancel
        the ones that have fallen out of the bid-anchored ladder so the next
        compile re-posts at the ladder that stands.  Reads the exchange
        through the gateway (lookup, cancel), writes only the
        reconciliation ledger; never places an order."""

        receipt: dict[str, Any] = {
            "schema": "bayes_basket_target_resting_reprice_v1",
            "state": "not_applicable",
            "examined": 0,
            "places_orders": False,
            "calls_order_gateway": False,
            "orders_submitted": 0,
        }
        if self.commit_conn is None:
            receipt["state"] = "not_attempted"
            return receipt
        from .delta_v2_runtime import (  # noqa: PLC0415
            EXECUTION_MODE as _order_family,
            MAKER_LADDER_SHAPE as _ladder_shape,
        )
        if (
            PRODUCTION_EXECUTION_MODE != "production_live"
            or _order_family != "maker"
            or _ladder_shape != "bid_anchored"
        ):
            receipt["reason"] = (
                f"mode={PRODUCTION_EXECUTION_MODE};family={_order_family};"
                f"shape={_ladder_shape}"
            )
            return receipt
        try:
            from clob_order_service_client import (  # noqa: PLC0415
                ClobOrderServiceClient,
            )
            from .proper_bet_lane import benchmark_sealed_rung  # noqa: PLC0415
            from .resting_ladder_lifecycle import (  # noqa: PLC0415
                RESTING_LOOKUP_CONCURRENCY,
                reprice_resting_rungs,
            )

            client = ClobOrderServiceClient(timeout_seconds=20.0)
        except Exception as exc:  # noqa: BLE001 -- observational lane
            receipt["state"] = "blocked_fail_closed"
            receipt["reason"] = f"{type(exc).__name__}:{exc}"[:160]
            return receipt
        conn = self.commit_conn
        receipt = reprice_resting_rungs(
            conn,
            as_of_utc=as_of_utc,
            client=client,
            write=lambda: _writer_transaction(
                conn, savepoint="basket_target_resting_reprice"
            ),
            limit=limit,
            # Charter 135 (二): the running high lives behind the canonical
            # connection this worker owns, so the loader is supplied here.
            dead_bucket_loader=self._resting_dead_buckets,
            # Charter 174: a pass the gateway breaker cut short says where
            # the next one starts, so no rung is asked first every time.
            start_index=int(getattr(self, "_resting_reprice_cursor", 0) or 0),
            # Charter 180: the lookups overlap; the pass does not.
            lookup_concurrency=RESTING_LOOKUP_CONCURRENCY,
            # Charter 258: a Proper rung on a bucket the benchmark cluster
            # has traded against is cancelled.
            benchmark_seal_loader=benchmark_sealed_rung,
        )
        self._resting_reprice_cursor = int(receipt.get("next_start_index") or 0)
        # Charter 186: which orders the resting lane has just read, by their
        # own exchange order id, as still resting.  The unresolved-intent
        # lane leaves those to it (see ``_reconcile_unresolved_intents``).
        now_mono = time.monotonic()
        self._resting_lane_live = {
            str(entry.get("order_intent_id") or ""): now_mono
            for entry in receipt.get("rungs") or ()
            if isinstance(entry, Mapping)
            and str((entry.get("sync") or {}).get("state") or "")
            in {"resting", "resting_partial"}
            and entry.get("order_intent_id")
        }
        _publish_resting_reprice_receipt(receipt, as_of_utc=as_of_utc)
        return receipt

    def _book_verdict_for_intent(
        self,
        *,
        client: Any,
        intent_id: str,
        token_id: str,
        requested_size: float,
        limit_price: float,
        order_action: str,
        idempotency_key: str,
        as_of_utc: str,
    ) -> dict[str, Any]:
        """What the exchange's own books say about one unresolved intent.

        Charter 110's two facts, asked only after the point lookup has
        declined to answer.  Neither depends on the gateway remembering the
        submission, and neither expires:

        * the OPEN-ORDER ENUMERATION for the token, which is an answer only
          when the gateway completed it (``complete``).  An order missing
          from a completed enumeration is positively not live; an
          enumeration that ran out of pages is silence and is treated as
          such.
        * the POSITION on that token, which is what a departed order
          actually did.

        Attribution is the delicate part, because a position is per token
        and cumulative over every order this book ever sent to it.  What can
        be attributed here is only the REMAINDER -- the shares held beyond
        what the ledger already records against that token -- and only when
        this intent is the single unresolved claimant on it.  Two unresolved
        intents on one token cannot be told apart by a balance, so both are
        left alone and reported; that is a smaller failure than crediting
        the wrong one.

        A live order on the token used to end this lane outright, on the
        grounds that a live order is the resting lane's business.  It is --
        but only once that lane can see it, and it sees an intent by the
        exchange order id the POST_ACK wrote.  A submission that timed out
        never wrote one, so ``load_resting_maker_intents`` skips it twice
        over (``r.state='pending'`` and a non-empty id) and this lane handed
        it to nobody.  Measured 2026-09-10: ZSQD 27C, event date 09-11,
        BUY 7 @ 0.16 accepted by the exchange at 2026-09-09T13:38:19Z and
        still resting seventeen hours later, unseen by every automatic path
        and holding its bucket shut the whole time -- while this function
        bailed out holding the enumeration that named it.

        So the handle is recovered here when the books can only mean one
        order; see ``_recovered_post_ack_for_intent`` for what "only" means.

        Never records more than the intent asked for.  Reads two GETs and
        writes nothing: the caller owns the transaction.
        """

        if not token_id:
            return {"event": None}
        # ``getattr`` rather than an attribute read: a worker built through
        # __new__ (which several tests and one rotation helper do) has no
        # ``commit_conn`` at all, and an AttributeError here would be an
        # exception escaping an observational lane.
        commit_conn = getattr(self, "commit_conn", None)
        if commit_conn is None:
            return {"event": None}
        try:
            enumeration = client.lookup_open_orders({"token_id": token_id})
        except Exception as exc:  # noqa: BLE001 -- one scope's problem
            return {"failure": f"{type(exc).__name__}:{exc}"}
        if enumeration.get("complete") is not True:
            # An enumeration the gateway could not finish is silence.
            return {"event": None}
        open_orders = enumeration.get("open_orders")
        if not isinstance(open_orders, list):
            return {"event": None}
        # The single-claimant test, which both branches below need: neither
        # a balance nor a live order's price and size can tell two
        # unresolved intents on one token apart.
        try:
            rival = int(commit_conn.execute(
                "SELECT COUNT(*) FROM basket_target_order_intents"
                " WHERE token_id=? AND state='reconcile_required'"
                "   AND order_intent_id<>?",
                (token_id, intent_id),
            ).fetchone()[0] or 0)
        except sqlite3.Error as exc:
            return {"failure": f"{type(exc).__name__}:{exc}"}
        if open_orders:
            return _recovered_post_ack_for_intent(
                commit_conn,
                open_orders=open_orders,
                rival=rival,
                intent_id=intent_id,
                token_id=token_id,
                requested_size=requested_size,
                limit_price=limit_price,
                order_action=order_action,
                idempotency_key=idempotency_key,
                as_of_utc=as_of_utc,
            )
        try:
            position = client.lookup_position({"token_id": token_id})
        except Exception as exc:  # noqa: BLE001
            return {"failure": f"{type(exc).__name__}:{exc}"}
        if position.get("ok") is not True:
            return {"event": None}
        try:
            held = float(position.get("shares") or 0.0)
        except (TypeError, ValueError):
            return {"event": None}
        try:
            recorded = float(commit_conn.execute(
                "SELECT COALESCE(SUM(r.filled_size),0)"
                " FROM basket_target_order_reconciliations r"
                " JOIN basket_target_order_intents i"
                "   ON i.order_intent_id=r.order_intent_id"
                " WHERE i.token_id=?",
                (token_id,),
            ).fetchone()[0] or 0.0)
        except sqlite3.Error as exc:
            return {"failure": f"{type(exc).__name__}:{exc}"}
        unrecorded = held - recorded
        if unrecorded > VENUE_SHARE_QUANTUM:
            if rival:
                # Ambiguous by construction; say so rather than guess.
                return {"event": None}
            matched = min(unrecorded, float(requested_size or 0.0))
            if matched <= VENUE_SHARE_QUANTUM:
                return {"event": None}
            return {"event": {
                "event_type": "FILL",
                "exchange_order_id": "",
                "observed_at": as_of_utc,
                "matched_size": matched,
                "matched_notional_usdc": matched * float(limit_price or 0.0),
                "event_payload": {
                    "idempotency_key": idempotency_key,
                    "exchange_status": "position_confirmed",
                    "recovered_by": "intent_reconcile_book_facts",
                    "token_position_shares": held,
                    "ledger_recorded_shares": recorded,
                    "open_order_enumeration_complete": True,
                },
            }}
        if unrecorded < -VENUE_SHARE_QUANTUM:
            # The ledger claims more than the account holds.  Not this
            # lane's to correct, and certainly not by writing another fill.
            return {"event": None}
        # Nothing live, and the position holds nothing this intent has not
        # already been credited with.  If the ledger never credited it at
        # all, the order never reached the exchange.
        try:
            prior = float(commit_conn.execute(
                "SELECT COALESCE(filled_size,0)"
                " FROM basket_target_order_reconciliations"
                " WHERE order_intent_id=?",
                (intent_id,),
            ).fetchone()[0] or 0.0)
        except sqlite3.Error as exc:
            return {"failure": f"{type(exc).__name__}:{exc}"}
        if prior > VENUE_SHARE_QUANTUM:
            # An order that departed with a fill the ledger already holds.
            # It will never reach its requested size -- the order is gone --
            # so the state that stands is the fill it got.  Nothing retired
            # these: ZSQD 23C matched 24.969975 of 25 and sat unresolved
            # because the shortfall exceeds one venue quantum, which
            # ``fill_is_complete`` reads as "not done yet" for an order that
            # cannot trade again.
            return {"event": None, "resolve_partial": prior}
        return {"event": {
            "event_type": "NEVER_REACHED_EXCHANGE",
            "exchange_order_id": None,
            "observed_at": as_of_utc,
            "matched_size": 0.0,
            "matched_notional_usdc": 0.0,
            "event_payload": {
                "idempotency_key": idempotency_key,
                "exchange_status": "absent_from_completed_enumeration",
                "recovered_by": "intent_reconcile_book_facts",
                "token_position_shares": held,
                "ledger_recorded_shares": recorded,
            },
        }}

    def _reconcile_unresolved_intents(
        self,
        *,
        as_of_utc: str,
        limit: int = 20,
    ) -> dict[str, Any]:
        """Close intents the exchange has already answered about.

        A submission that times out leaves the intent in reconcile_required
        with an UNKNOWN_POST event, and the gateway can settle it: it asks
        the exchange for the deterministic order id the signer computed
        before the POST -- the one thing that makes a lost submission
        findable -- and gets back whether the order exists.  Nothing
        consumed that answer, so the ledger stayed unknown after the gateway
        knew, and the board reported an open reconciliation over a question
        that had been settled.

        Reads the exchange, writes only this ledger. It never places or
        cancels: the gateway path used here is a GET on one order id.

        Nothing here closes an order the exchange still holds.  A resting
        order is the fill lane's fact, not something to settle from here --
        but the fill lane reaches an intent through its exchange order id,
        and a submission that timed out has none.  So the one thing this
        lane does with a live order is give the intent back its handle,
        under the conditions in ``_recovered_post_ack_for_intent``, which
        moves it to the lane that owns it.  It still never places or
        cancels anything.
        """

        receipt: dict[str, Any] = {
            "schema": "bayes_basket_target_intent_reconcile_v1",
            "state": "no_unresolved_intents",
            "examined": 0,
            "closed": 0,
            "still_unresolved": 0,
            "failures": [],
            "places_orders": False,
            "calls_order_gateway": True,
            "orders_submitted": 0,
        }
        if self.commit_conn is None:
            receipt["state"] = "not_attempted"
            return receipt
        try:
            rows = self.commit_conn.execute(
                "SELECT order_intent_id, idempotency_key,"
                " order_action, limit_price, token_id, requested_size"
                " FROM basket_target_order_intents"
                " WHERE state='reconcile_required'"
                " ORDER BY created_at LIMIT ?",
                (int(limit),),
            ).fetchall()
        except sqlite3.Error as exc:
            receipt["state"] = "blocked_fail_closed"
            receipt["reason"] = f"{type(exc).__name__}:{exc}"
            return receipt
        if not rows:
            return receipt
        # Charter 186: a partly filled order still resting on the exchange is
        # ``reconcile_required`` by the ledger's rule (a partial fill), and
        # the resting lane loads exactly those and reads each by its own
        # exchange order id every pass -- the authoritative answer the point
        # lookup here can only approximate.  Asking again here (the point
        # lookup, the open-order enumeration, the position) was 9-15s a
        # cycle for one KHOU GTD rung resting until its expiry (2026-09-21
        # 11:42Z-16:39Z).  So an intent the resting lane read as resting in
        # its last pass, within the handoff bound, is its alone; one it did
        # not reach, could not read, or saw end comes back here next cycle.
        live = getattr(self, "_resting_lane_live", None) or {}
        now_mono = time.monotonic()
        owned = {
            str(intent_id)
            for intent_id, seen in live.items()
            if now_mono - float(seen) <= RESTING_LANE_HANDOFF_MAX_AGE_SEC
        }
        receipt["resting_lane_owned"] = sorted(
            str(row[0]) for row in rows if str(row[0]) in owned
        )
        rows = [row for row in rows if str(row[0]) not in owned]
        if not rows:
            receipt["state"] = "resting_lane_owned"
            return receipt
        try:
            from clob_order_service_client import (  # noqa: PLC0415
                ClobOrderServiceClient,
            )

            client = ClobOrderServiceClient(timeout_seconds=20.0)
        except Exception as exc:  # noqa: BLE001 -- observational lane
            receipt["state"] = "blocked_fail_closed"
            receipt["reason"] = f"{type(exc).__name__}:{exc}"[:160]
            return receipt
        receipt["examined"] = len(rows)
        receipt["filled"] = 0
        receipt["already_recorded"] = 0
        receipt["closed_by_book"] = 0
        # Not closed: handed over.  An intent that just got its exchange
        # order id back is now something the resting lane can act on, and
        # counting it as closed would report a live order as settled.
        receipt["handle_recovered"] = 0
        for (
            intent_id, idempotency_key, order_action, limit_price,
            token_id, requested_size,
        ) in rows:
            try:
                answer = client._post(
                    "/reconcile-order",
                    {"idempotency_key": str(idempotency_key or "")},
                )
            except Exception as exc:  # noqa: BLE001 -- one scope's problem
                receipt["failures"].append({
                    "order_intent_id": str(intent_id),
                    "reason": f"{type(exc).__name__}:{exc}"[:120],
                })
                continue
            # What the ledger already holds for this intent.  The gateway's
            # stored reply is the exchange's *cumulative* account of the one
            # order the key names, so a fill it reports is the whole fill,
            # not an increment on top of one the submit pass already wrote.
            # KAUS 98-99°F, 2026-09-05 19:49Z: the submit pass recorded the
            # matched 4.99 shares, the ledger read 4.99 against a 4.999...
            # request as partial, and this lane added the same 4.99 again --
            # 9.98 shares on the book for one order of five.
            prior = self.commit_conn.execute(
                "SELECT exchange_order_id, filled_size, filled_notional_usdc"
                " FROM basket_target_order_reconciliations"
                " WHERE order_intent_id=?",
                (str(intent_id),),
            ).fetchone()
            prior_order_id = str(prior[0] or "") if prior else ""
            prior_filled = float(prior[1] or 0.0) if prior else 0.0
            prior_notional = float(prior[2] or 0.0) if prior else 0.0
            # Two verdicts are acted on.  "Never reached" reads the same
            # whether this is the first time the gateway asked or a replay of
            # an answer it already has.  "Accepted and matched" is the
            # gateway's stored success reply for the key -- the fill the
            # submit pass did not get to see, because the first five live
            # fills (2026-09-05) came back without the ``accepted`` flag the
            # classifier wanted and were written as UNKNOWN_POST; nothing
            # then ever moved them, and five ``reconcile_required`` rows read
            # as a non-quiescent book that froze every quote refresh.
            # Anything else -- a resting order, a lookup that could not reach
            # the exchange -- leaves the intent alone.
            error = str(answer.get("error") or "")
            event: dict[str, Any] | None = None
            if error == "order_never_reached_exchange":
                event = {
                    "event_type": "NEVER_REACHED_EXCHANGE",
                    "exchange_order_id": None,
                    "observed_at": as_of_utc,
                    "matched_size": 0.0,
                    "matched_notional_usdc": 0.0,
                    "event_payload": {
                        "expected_order_id": str(
                            answer.get("expected_order_id") or ""
                        ),
                        "exchange_status": str(answer.get("status") or ""),
                    },
                }
            elif answer.get("ok") is True and not error:
                fill = fill_from_gateway_response(answer)
                matched_size, matched_notional = fill_quantities(
                    fill,
                    event_type="FILL",
                    order_action=str(order_action or ""),
                    limit_price=float(limit_price or 0.0),
                )
                if (
                    fill["exchange_order_id"]
                    and fill["status"] == "matched"
                    and matched_size > 0.0
                ):
                    if prior_order_id and prior_order_id == fill["exchange_order_id"]:
                        # Same order the ledger already carries: only what
                        # the exchange reports beyond the recorded fill is
                        # new.  Nothing beyond it means the recorded fill
                        # is the order, and the question left is whether
                        # it covers the request.
                        matched_size = max(0.0, matched_size - prior_filled)
                        matched_notional = max(
                            0.0, matched_notional - prior_notional
                        )
                        if matched_size <= 1e-9:
                            requested = float(self.commit_conn.execute(
                                "SELECT requested_size FROM"
                                " basket_target_order_intents"
                                " WHERE order_intent_id=?",
                                (str(intent_id),),
                            ).fetchone()[0])
                            if fill_is_complete(prior_filled, requested):
                                try:
                                    with _writer_transaction(
                                        self.commit_conn,
                                        savepoint="basket_target_intent_reconcile",
                                    ):
                                        resolve_reconciliation(
                                            self.commit_conn,
                                            order_intent_id=str(intent_id),
                                            authoritative_state="filled",
                                            filled_size=prior_filled,
                                            filled_notional_usdc=prior_notional,
                                            resolved_at_utc=as_of_utc,
                                        )
                                    receipt["closed"] += 1
                                    receipt["already_recorded"] += 1
                                except Exception as exc:  # noqa: BLE001
                                    receipt["failures"].append({
                                        "order_intent_id": str(intent_id),
                                        "reason": f"{type(exc).__name__}:{exc}"[:120],
                                    })
                            else:
                                receipt["still_unresolved"] += 1
                            continue
                    event = {
                        "event_type": "FILL",
                        "exchange_order_id": fill["exchange_order_id"],
                        "observed_at": as_of_utc,
                        "matched_size": matched_size,
                        "matched_notional_usdc": matched_notional,
                        "event_payload": {
                            "idempotency_key": str(idempotency_key or ""),
                            "exchange_status": fill["status"],
                            "recovered_by": "intent_reconcile",
                            **(
                                {"cumulative_size_matched": float(
                                    fill.get("shares_matched") or 0.0
                                )}
                                if prior_filled > 0.0 else {}
                            ),
                        },
                    }
            if event is None:
                # Charter 110's two facts, because the point lookup above
                # has just told us nothing and that is not an answer.
                #
                # The gateway can only run its authoritative lookup while it
                # still remembers the key: ``unresolved`` is in-memory, so a
                # gateway restart turns every outstanding intent into
                # ``{ok: false, found: false}`` -- "I do not know this key",
                # which this lane rightly refuses to read as "the exchange
                # does not have it".  The result was a class of intent that
                # could never be resolved by anybody: ZSQD 23C sat in
                # reconcile_required from 2026-09-07T18:59Z across every
                # restart since, and ZGSZ 32C and 33C joined it on 09-08
                # when the gateway restarted five minutes after their POST
                # timed out.
                #
                # These two questions do not depend on gateway memory and do
                # not expire.  The enumeration says whether the order is
                # still live; the position says what a departed one did.
                # Measured on those three intents: 33C was reported "live"
                # by the point lookup (a cached reply from POST time) while
                # the enumeration held zero open orders and the position
                # held 7 shares -- the order had filled and the ledger
                # carried nothing.
                verdict = self._book_verdict_for_intent(
                    client=client,
                    intent_id=str(intent_id),
                    token_id=str(token_id or ""),
                    requested_size=float(requested_size or 0.0),
                    limit_price=float(limit_price or 0.0),
                    order_action=str(order_action or ""),
                    idempotency_key=str(idempotency_key or ""),
                    as_of_utc=as_of_utc,
                )
                if verdict.get("failure"):
                    receipt["failures"].append({
                        "order_intent_id": str(intent_id),
                        "reason": str(verdict["failure"])[:120],
                    })
                    continue
                event = verdict.get("event")
                if event is None:
                    partial = verdict.get("resolve_partial")
                    if partial is None:
                        receipt["still_unresolved"] += 1
                        continue
                    # A departed order whose fill the ledger already holds.
                    # It cannot trade again, so the fill it got is the state
                    # that stands; leaving it "not yet complete" is what kept
                    # ZSQD 23C unresolved for sixteen hours over 0.03 of a
                    # share the venue was never going to send.
                    #
                    # Closed through the ledger's own partial-close, not
                    # through ``resolve_reconciliation(partial)``.  The
                    # latter settles the RECONCILIATION and leaves the
                    # INTENT at reconcile_required, which is one of the four
                    # states ``can_submit_next_order`` blocks on -- so the
                    # first version of this retirement got the books right
                    # and left the bucket shut, with the row reading
                    # ``authoritative_partial_requires_manual_close``.
                    # There is no terminal intent state called "partial";
                    # the order ended without completing, which is what
                    # ``cancelled`` means here, and the fill lives on the
                    # reconciliation row where the inventory readers
                    # already count it.
                    try:
                        with _writer_transaction(
                            self.commit_conn,
                            savepoint="basket_target_intent_reconcile",
                        ):
                            resolve_cancelled_after_partial_fill(
                                self.commit_conn,
                                order_intent_id=str(intent_id),
                                filled_size=float(partial),
                                filled_notional_usdc=float(partial)
                                * float(limit_price or 0.0),
                                resolved_at_utc=as_of_utc,
                            )
                        receipt["closed"] += 1
                        receipt["closed_by_book"] += 1
                    except Exception as exc:  # noqa: BLE001
                        receipt["failures"].append({
                            "order_intent_id": str(intent_id),
                            "reason": f"{type(exc).__name__}:{exc}"[:120],
                        })
                    continue
                if event["event_type"] != "POST_ACK":
                    receipt["closed_by_book"] += 1
            try:
                with _writer_transaction(
                    self.commit_conn,
                    savepoint="basket_target_intent_reconcile",
                ):
                    record_order_event(
                        self.commit_conn,
                        order_intent_id=str(intent_id),
                        event=event,
                    )
                if event["event_type"] == "POST_ACK":
                    receipt["handle_recovered"] += 1
                else:
                    receipt["closed"] += 1
                    if event["event_type"] == "FILL":
                        receipt["filled"] += 1
            except Exception as exc:  # noqa: BLE001 -- one scope's problem
                receipt["failures"].append({
                    "order_intent_id": str(intent_id),
                    "reason": f"{type(exc).__name__}:{exc}"[:120],
                })
        receipt["state"] = (
            "committed"
            if (receipt["closed"] or receipt["handle_recovered"])
            else "no_change"
        )
        return receipt

    def _listing_entry_scopes(
        self,
        *,
        as_of_utc: str,
        station_allowlist: set[str] | frozenset[str] | None = None,
        event_date: str | None = None,
    ) -> list[tuple[str, str]]:
        """Charter 48 scopes: a listed day this book may already open on.

        Clause 48 of the 2026-08-14 ruling is "listing is entry" -- a market
        becomes tradable when it is listed, not when its settlement day
        begins.  The admission rule is not invented here: it is the one
        ``_decision_scopes`` already carries for a not-started day, namely a
        committed P0 or P0-M authority and no P1 (a future P1 cannot exist,
        and a scope claiming one is not a listing scope).

        The rule was live and producing between 2026-08-14 and 08-21 -- about
        twenty entries a day, measured on the local calendar of each
        station's settlement timezone -- then fell to zero.  The cycle scopes
        exactly one ``manifest_event_date`` and requires it to be open, so a
        listed day could not enter, and the preselection lane that does see
        listed days writes plans no consumer reads.  This restores the path;
        every downstream gate the current day passes still applies unchanged.

        ``station_allowlist`` and ``event_date`` confine the reads, not only
        the answer: see ``_decision_scopes``.
        """

        _listing_started = time.perf_counter()
        allow = {str(item).upper() for item in (station_allowlist or ())}
        listing: list[tuple[str, str]] = []
        for station, day in self._decision_scopes(
            as_of_utc=as_of_utc,
            include_not_started=True,
            event_date=event_date,
            station_ids=allow or None,
        ):
            if allow and str(station).upper() not in allow:
                continue
            if self._event_day_open(
                day,
                settlement_timezone=self._scope_settlement_timezone(
                    station, day
                ),
                as_of_utc=as_of_utc,
            ):
                # Already the current day for this station; the ordinary
                # same-day path owns it and must not be duplicated here.
                continue
            listing.append((str(station), str(day)))
        # Called three times inside the market-ingress window and once more
        # in the sweep, each time re-running ``_decision_scopes`` and one
        # timezone read per scope.  The window measured 472.1s on
        # 2026-09-09 with 101s of it inside the evidence passes; this is
        # one of the candidates for the rest, so it says so itself.
        self._add_span(
            "listing_entry_scopes",
            (time.perf_counter() - _listing_started) * 1000.0,
            label=f"{len(listing)} scopes",
        )
        return sorted(set(listing))

    def _scope_settlement_timezone(self, station_id: str, event_date: str) -> str:
        """The settlement timezone this scope is keyed on, or ""."""

        if self.conn is None:
            return ""
        try:
            row = self.conn.execute(
                "SELECT settlement_timezone FROM basket_probability_envelope"
                " WHERE station_id=? AND event_date=? AND settlement_timezone<>''"
                " LIMIT 1",
                (str(station_id), str(event_date)),
            ).fetchone()
        except sqlite3.Error:
            return ""
        return str(row[0]) if row else ""

    def _decision_scopes(
        self,
        *,
        as_of_utc: str | None = None,
        include_not_started: bool = True,
        event_date: str | None = None,
        station_ids: Collection[str] | None = None,
    ) -> list[tuple[str, str]]:
        """Discover open scopes plus pre-event P0/P0-M no-live scopes.

        A not-started market is actionable only for the preliminary
        zero-execution lane and only while its committed probability authority
        is P0/P0-M.  Future P1 remains invalid and WS cache rows alone can
        never manufacture a future decision identity.

        ``event_date`` confines each of the three reads to that day and
        ``station_ids`` the answer to those stations.  A scope is admitted on
        its own registry, probability and WS-cache rows alone, so the answer is
        the unconfined one restricted to them.  2026-10-04 05:15Z: a mid-loop
        refresh of a not-started day asked for the fleet's listing scopes to
        admit the three to thirty stations it restates -- 54 times, 149 s of a
        1,464 s cycle, 5,289 timezone reads.
        """

        if self.conn is None:
            return []
        decision_clock = as_of_utc or utc_now()
        only_day = str(event_date or "").strip()
        only_day_sql = " AND event_date=?" if only_day else ""
        only_day_args: tuple[str, ...] = (only_day,) if only_day else ()
        scopes: set[tuple[str, str]] = set()
        try:
            for item in load_started_registry_rows(
                self.conn, as_of_utc=decision_clock, event_date=only_day,
            ):
                station = str(item.get("station_id") or "").strip()
                day = str(item.get("event_date") or "").strip()
                settlement_timezone = str(
                    item.get("settlement_timezone") or ""
                ).strip()
                if (
                    station
                    and day
                    and settlement_timezone
                    and self._event_day_open(
                        day,
                        settlement_timezone=settlement_timezone,
                        as_of_utc=decision_clock,
                    )
                ):
                    scopes.add((station, day))
        except Exception:
            # The registry is evidence, not a reason to invent an identity. A
            # missing registry leaves the worker globally blocked; when a
            # target-owned cache or probability row does identify a scope we
            # still record that concrete blocker below.
            pass
        try:
            probability_columns = {
                str(row[1])
                for row in self.conn.execute(
                    "PRAGMA table_info(basket_probability_envelope)"
                ).fetchall()
            }
            stage_projection = (
                "stage" if "stage" in probability_columns else "'' AS stage"
            )
            # DISTINCT, like the WS-cache read forty lines below that asks
            # the same question of its own table.  The loop under this fold
            # the rows into ``probability_scopes`` -- a dict keyed on the
            # scope with a set of stages -- so duplicates were only ever
            # built to be discarded, and by 2026-09-09 that was 416,855
            # rows for 3,935 distinct answers, per call, several calls a
            # cycle.  The cost is not the query: a 15-second sample of the
            # resident mid-cycle put ~77% of the worker thread's time in
            # ``tupledealloc``, freeing fetched rows.  Measured warm
            # against the live SSOT: 5.15s to 3.9s for the read, and 413k
            # tuples a call that are never allocated.
            # And only the days that can still be open or not started.  A
            # local day ends by 12:00Z on the UTC day after it (UTC-12 is the
            # westernmost settlement zone), so no event date before the
            # decision clock's UTC date minus one can be either -- everything
            # older is fetched, folded and then discarded by the day-state
            # test below.  Measured 2026-09-14 against the live SSOT: 4,619
            # distinct rows in 4.5-5.0s for 466 that could matter, 0.01s with
            # the bound, which the publisher scope index serves as a range; and
            # identical open/not-started sets at every half hour across 48
            # hours of clocks.  Two days of margin, not one.
            probability_rows = self.conn.execute(
                DECISION_SCOPE_PROBABILITY_SQL.format(
                    stage_projection=stage_projection
                ) + only_day_sql,
                (_decision_scope_event_date_floor(decision_clock), *only_day_args),
            ).fetchall()
        except sqlite3.Error:
            probability_rows = []
        probability_scopes: dict[
            tuple[str, str, str], set[str]
        ] = {}
        for station, day, settlement_timezone, stage in probability_rows:
            identity = (
                str(station or "").strip(),
                str(day or "").strip(),
                str(settlement_timezone or "").strip(),
            )
            if not all(identity):
                continue
            probability_scopes.setdefault(identity, set()).add(
                str(stage or "").strip()
            )
        for (
            station_text,
            day_text,
            settlement_timezone,
        ), stages in probability_scopes.items():
            try:
                day_state = str(event_day_window(
                    day_text,
                    as_of_utc=decision_clock,
                    target_timezone=settlement_timezone,
                )["state"])
            except Exception:
                continue
            if day_state == "open":
                scopes.add((station_text, day_text))
            elif (
                include_not_started
                and
                day_state == "not_started"
                and "P1" not in stages
                and bool(stages.intersection({"P0", "P0-M"}))
            ):
                scopes.add((station_text, day_text))
        try:
            ws_rows = self.conn.execute(
                "SELECT DISTINCT station_id,event_date,settlement_timezone "
                "FROM basket_official_ws_evidence_cache "
                "WHERE station_id<>'' AND event_date<>''" + only_day_sql,
                only_day_args,
            ).fetchall()
        except sqlite3.Error:
            ws_rows = []
        for station, day, settlement_timezone in ws_rows:
            station_text = str(station or "").strip()
            day_text = str(day or "").strip()
            timezone_text = str(settlement_timezone or "").strip()
            if (
                station_text
                and day_text
                and timezone_text
                and self._event_day_open(
                    day_text,
                    settlement_timezone=timezone_text,
                    as_of_utc=decision_clock,
                )
            ):
                scopes.add((station_text, day_text))
        station_allowlist = set(
            getattr(self, "station_allowlist", ())
        )
        event_date_allowlist = set(
            getattr(self, "event_date_allowlist", ())
        )
        if station_allowlist:
            scopes = {
                (station, day)
                for station, day in scopes
                if station.upper() in station_allowlist
            }
        if event_date_allowlist:
            scopes = {
                (station, day)
                for station, day in scopes
                if day in event_date_allowlist
            }
        if station_ids is not None:
            wanted = {str(item).upper() for item in station_ids}
            scopes = {
                (station, day)
                for station, day in scopes
                if station.upper() in wanted
            }
        return sorted(scopes)

    @staticmethod
    def _blocker_reason_codes(*values: Any) -> list[str]:
        """Extract stable reason codes and keep volatile exception text in details."""

        reasons: set[str] = set()
        for value in values:
            text = str(value or "").strip()
            if not text:
                continue
            if ":" in text:
                text = text.split(":", 1)[1].strip() or text.split(":", 1)[0].strip()
            if text:
                reasons.add(text)
        return sorted(reasons) or ["target_candidate_blocked"]

    def _standing_blocker_matches(
        self,
        *,
        station_id: str,
        event_date: str,
        reason_codes: Sequence[str],
    ) -> str | None:
        """When this exact blocker started standing, or None if it is new.

        Compares against the scope's most recent decision only.  Anything
        else -- a blocker that lifted and returned, a different set of codes,
        a decision that was not blocked -- is a transition and has to be
        recorded, so only an unbroken repeat of the standing blocker is
        suppressed.

        Read failures return None, which writes.  Losing a transition costs
        the audit trail; writing one extra row costs a row.
        """

        try:
            row = self.commit_conn.execute(
                "SELECT decided_state,reason_codes_json,created_at "
                "FROM auto_trade_decisions "
                "WHERE station_id=? AND event_date=? "
                "ORDER BY created_at DESC LIMIT 1",
                (station_id, event_date),
            ).fetchone()
        except sqlite3.Error:
            return None
        if row is None or str(row[0]) != "blocked":
            return None
        try:
            standing = json.loads(str(row[1]))
        except (TypeError, ValueError):
            return None
        if not isinstance(standing, list):
            return None
        if [str(value) for value in standing] != [
            str(value) for value in reason_codes
        ]:
            return None
        return str(row[2])

    def _commit_blocked_scope(
        self,
        *,
        station_id: str,
        event_date: str,
        reason_codes: list[str],
        details: Mapping[str, Any] | None,
        created_at_utc: str,
    ) -> dict[str, Any]:
        """Write only the authoritative blocker; never manufacture inputs.

        A blocker that has not changed is not a new fact.  Every swept scope
        used to append a cycle, a decision and a version vector whatever it
        concluded, so 29,566 of 29,910 cycles -- 98.85% -- were empty shells
        recording that nothing had happened again, and the decision table
        alone reached 0.365 GiB of them.  That write amplification, not the
        quote snapshots, is what put the store into its size ceiling and
        stopped the whole chain today.

        So the first occurrence of a blocker is written, every change of
        blocker is written, and a repeat of the one already standing is not.
        What that costs is the ability to say what the book looked like on
        the 47th identical scan; what it keeps is every transition, which is
        what an audit of "when did this start, and why" actually reads --
        today's own three outages were diagnosed from exactly that sequence.
        The sweep receipt below records that the scope was evaluated at all,
        so "scanned and unchanged" stays distinguishable from "never
        scanned", which it was not before.
        """

        if self.commit_conn is None:
            return {
                "state": "not_attempted",
                "reason": "target_atomic_writer_not_injected",
                "writes_target_ledger": False,
                "orders_submitted": 0,
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
            }
        try:
            timezone_rows = self.commit_conn.execute(
                "SELECT DISTINCT settlement_timezone "
                "FROM basket_target_market_registry "
                "WHERE station_id=? AND event_date=? "
                "UNION SELECT DISTINCT settlement_timezone "
                "FROM basket_probability_envelope "
                "WHERE station_id=? AND event_date=?",
                (station_id, event_date, station_id, event_date),
            ).fetchall()
            settlement_timezones = {
                str(row[0] or "").strip()
                for row in timezone_rows
                if str(row[0] or "").strip()
            }
            if len(settlement_timezones) != 1:
                raise RuntimeError(
                    "target_scope_settlement_timezone_not_unique"
                )
            unchanged = self._standing_blocker_matches(
                station_id=station_id,
                event_date=event_date,
                reason_codes=reason_codes,
            )
            if unchanged:
                return {
                    "state": "unchanged_blocker_not_rewritten",
                    "reason": "auto_trade_decisions_blocked_authority",
                    "writes_target_ledger": False,
                    "standing_blocker": list(reason_codes),
                    "standing_since_utc": unchanged,
                    "intent_count": 0,
                    "reserved_amount_usdc": 0.0,
                    "orders_submitted": 0,
                    "places_orders": False,
                    "calls_order_gateway": False,
                    "live_submit_authorized": False,
                }
            receipt = commit_blocked_scope_decision(
                self.commit_conn,
                station_id=station_id,
                event_date=event_date,
                settlement_timezone=next(iter(settlement_timezones)),
                strategy_lane="basket",
                reason_codes=reason_codes,
                details=details or {},
                created_at_utc=created_at_utc,
            )
        except Exception as exc:
            return {
                "state": "blocked_fail_closed",
                "reason": f"target_blocked_decision_write_failed:{type(exc).__name__}:{exc}",
                "writes_target_ledger": False,
                "orders_submitted": 0,
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
            }
        receipt_state = str(receipt.get("state") or "committed")
        return {
            "state": receipt_state,
            "reason": "auto_trade_decisions_blocked_authority",
            "writes_target_ledger": True,
            "intent_count": 0,
            "reserved_amount_usdc": 0.0,
            "receipt": receipt,
            "orders_submitted": 0,
            "places_orders": False,
            "calls_order_gateway": False,
            "live_submit_authorized": False,
        }

    def _commit_blocked_scopes(
        self,
        *,
        scopes: list[tuple[str, str]],
        reason_codes: list[str],
        details: Mapping[str, Any] | None,
        created_at_utc: str,
    ) -> list[dict[str, Any]]:
        receipts: list[dict[str, Any]] = []
        for station_id, event_date in scopes:
            receipts.append({
                "station_id": station_id,
                "event_date": event_date,
                **self._commit_blocked_scope(
                    station_id=station_id,
                    event_date=event_date,
                    reason_codes=reason_codes,
                    details=details,
                    created_at_utc=created_at_utc,
                ),
            })
        return receipts

    @staticmethod
    def _blocked_receipt_summary(receipts: list[Mapping[str, Any]]) -> list[dict[str, Any]]:
        return [
            {
                "station_id": str(item.get("station_id") or ""),
                "event_date": str(item.get("event_date") or ""),
                "state": str(item.get("state") or ""),
                "reason": str(item.get("reason") or ""),
                "cycle_id": str((item.get("receipt") or {}).get("cycle_id") or "")
                if isinstance(item.get("receipt"), Mapping) else "",
                "decision_id": str((item.get("receipt") or {}).get("decision_id") or "")
                if isinstance(item.get("receipt"), Mapping) else "",
                "idempotent": bool((item.get("receipt") or {}).get("idempotent", False))
                if isinstance(item.get("receipt"), Mapping) else False,
            }
            for item in receipts
        ]

    def _commit_candidate(
        self,
        candidate: Mapping[str, Any],
        *,
        station_id: str,
        event_date: str,
        created_at_utc: str,
    ) -> dict[str, Any]:
        if self.commit_conn is None:
            return {
                "state": "not_attempted",
                "reason": "target_atomic_writer_not_injected",
                "writes_target_ledger": False,
                "orders_submitted": 0,
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
            }
        production_inputs = candidate.get("production_inputs")
        if isinstance(production_inputs, Mapping):
            delta_v2_blocker = str(
                production_inputs.get("delta_v2_resolution_blocker") or ""
            ).strip()
            if delta_v2_blocker:
                # Missing/unpromoted/OOS-failed v2 authority is not
                # an optimizer HOLD. It is an incomplete decision contract.
                # Preserve the exact resolver reason and do not let the
                # downstream atomic-fact adapter mask it as a probability error
                # or materialize a false forward training fact.
                raise ContractError(delta_v2_blocker)
        retained = self._scope_cycle_guard(
            station_id=station_id,
            event_date=event_date,
            candidate=candidate,
        )
        supersession = None
        if (
            retained is not None
            and retained.get("state")
            == "supersede_existing_prepared_candidate"
        ):
            supersession = retained
        elif retained is not None:
            return retained
        # P0 opens on the model ensemble and P0-M re-confirms on the TAF
        # revision.  Neither has an observed METAR to root on, so the P1-shaped
        # observation facts simply do not exist for them.  The ledger already
        # picks its chain head from the stage, so hand it nothing here rather
        # than a hollow observation that would let a forecast pose as a
        # settled fact.
        plan = candidate.get("plan")
        plan_lineage = plan.get("lineage") if isinstance(plan, Mapping) else None
        candidate_stage = (
            str(plan_lineage.get("probability_stage") or "").strip().upper()
            if isinstance(plan_lineage, Mapping)
            else ""
        )
        if not candidate_stage:
            # Ask the envelope, which is the authority on its own stage and
            # is what the router twenty lines below already asks.  The plan
            # lineage is a copy of that same value -- runtime.py writes
            # "probability_stage": envelope.stage into it -- so this can never
            # disagree when the lineage exists; it only supplies the answer
            # when it does not.
            #
            # It does not, for any plan blocked before the success path adds
            # a lineage.  An empty stage is not in {"P0", "P0-M"}, so such a
            # plan fell through to the P1-shaped fact path, and a P0 envelope
            # -- which has no observed METAR and by contract must not carry
            # canonical observation keys -- was refused for lacking exactly
            # the six keys it is forbidden to have.  Ten stations on
            # 2026-08-31 read target_atomic_lineage_incomplete for that
            # reason, none of them a lineage problem.
            probability_envelope = candidate.get("probability_envelope")
            candidate_stage = (
                str(probability_envelope.get("stage") or "").strip().upper()
                if isinstance(probability_envelope, Mapping)
                else ""
            )
        facts = (
            {
                "awc_observation_contract": None,
                "truth_observation_revision_content_sha256": "",
                "bound": None,
            }
            if candidate_stage in {"P0", "P0-M"}
            else target_atomic_facts_from_cycle(candidate)
        )
        market_snapshot = candidate.get("production_market_snapshot")
        if not isinstance(market_snapshot, Mapping):
            raise RuntimeError("production_market_snapshot_missing_for_atomic_commit")
        if str(market_snapshot.get("station_id") or "") != station_id or str(market_snapshot.get("event_date") or "") != event_date:
            raise RuntimeError("production_market_snapshot_scope_mismatch_for_atomic_commit")
        with _writer_transaction(
            self.commit_conn,
            savepoint="candidate_persistence_cas",
        ):
            committed = commit_production_candidate_atomic(
                self.commit_conn,
                compiled_plan=candidate,
                market_snapshot=market_snapshot,
                awc_observation_contract=facts["awc_observation_contract"],
                truth_observation_revision_content_sha256=facts[
                    "truth_observation_revision_content_sha256"
                ],
                bound=facts["bound"],
                created_at_utc=created_at_utc,
                supersede_prepared_cycle_id=(
                    str(supersession["cycle_id"])
                    if supersession is not None
                    else None
                ),
                new_decision_scope_key=(
                    str(supersession["new_decision_scope_key"])
                    if supersession is not None
                    else None
                ),
            )
            atomic_receipt = committed.get("receipt")
            if not isinstance(atomic_receipt, Mapping):
                raise ContractError(
                    "candidate_atomic_receipt_mapping_required"
                )
            cycle_id = str(
                atomic_receipt.get("cycle_id") or ""
            ).strip()
            if not cycle_id:
                raise ContractError("candidate_atomic_cycle_id_missing")
            vector_columns = ",".join(
                "v." + field for field in EXECUTION_VERSION_FIELDS
            )
            vector_rows = self.commit_conn.execute(
                "SELECT i.order_intent_id,"
                + vector_columns
                + ",v.vector_sha256 "
                "FROM basket_target_order_intents i "
                "JOIN basket_target_execution_version_vectors v "
                "ON v.order_intent_id=i.order_intent_id "
                "WHERE i.cycle_id=? ORDER BY i.order_intent_id",
                (cycle_id,),
            ).fetchall()
            current_vectors = {
                str(row[0]): {
                    "schema": EXECUTION_VERSION_VECTOR_SCHEMA,
                    **{
                        field: row[index + 1]
                        for index, field in enumerate(
                            EXECUTION_VERSION_FIELDS
                        )
                    },
                    "vector_sha256": row[
                        len(EXECUTION_VERSION_FIELDS) + 1
                    ],
                }
                for row in vector_rows
            }
            consumption_cas = (
                validate_persisted_candidate_consumption_cas(
                    self.commit_conn,
                    cycle_id=cycle_id,
                    current_vectors_by_intent=current_vectors,
                    at_utc=created_at_utc,
                )
            )
            if (
                consumption_cas.get("authorizes_order") is not False
                or consumption_cas.get("evidence_only") is not True
                or consumption_cas.get("live_submit_authorized") is not False
                or int(consumption_cas.get("orders_submitted", -1)) != 0
            ):
                raise ContractError(
                    "candidate_consumption_no_live_boundary_invalid"
                )
            return {
                **committed,
                "candidate_consumption_cas": consumption_cas,
                "authorizes_order": False,
                "evidence_only": True,
                # What the submission actually did, kept rather than dropped.
                # commit_production_candidate_atomic returns it and this
                # receipt is where an operator looks; without it a prepared
                # intent that was never offered to the exchange and one that
                # was offered and refused read identically, and the reason
                # the submitter recorded is lost with the frame.
                "order_submission": committed.get("order_submission"),
            }

    def _commit_stage_zero_execution_candidate(
        self,
        candidate: Mapping[str, Any],
        *,
        station_id: str,
        event_date: str,
        created_at_utc: str,
    ) -> dict[str, Any]:
        """Persist an open-day no-execution evaluation without fact writes."""
        if self.commit_conn is None:
            return {
                "state": "not_attempted",
                "reason": "target_atomic_writer_not_injected",
                "writes_target_ledger": False,
                "intent_count": 0,
                "reserved_amount_usdc": 0.0,
                "orders_submitted": 0,
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
            }
        anchor = target_stage_zero_execution_anchor_from_cycle(candidate)
        return commit_production_stage_zero_execution_atomic(
            self.commit_conn,
            compiled_plan=candidate,
            anchor=anchor,
            created_at_utc=created_at_utc,
        )

    def _commit_current_stage_no_execution_candidate(
        self,
        candidate: Mapping[str, Any],
        *,
        station_id: str,
        event_date: str,
        created_at_utc: str,
    ) -> dict[str, Any]:
        """Route every materialized probability stage to NO_EXECUTION only."""

        probability = candidate.get("probability_envelope")
        stage = (
            str(probability.get("stage") or "").strip().upper()
            if isinstance(probability, Mapping)
            else ""
        )
        if stage not in {"P0", "P0-M", "P1"}:
            raise ContractError(
                "resident_current_scope_probability_stage_invalid"
            )
        # A plan the compile already refused carries no lineage -- that is
        # added on the success path -- so handing it to the stage-zero
        # commit only earns ``stage_zero_execution_plan_lineage_missing``,
        # and the blocked decision then gets written under that name while
        # the compile's own reason is lost.  Fourteen listed-day scopes on
        # 2026-09-03 read as a lineage defect that way; every one was
        # ``delta_v2_support_empty``, a book with nothing priced yet.  Name
        # the refusal after what refused it, and let the caller's blocked
        # path record it exactly as it records a compile that raised.
        if str(candidate.get("status") or "").strip().lower() == "blocked":
            codes = [
                str(code).strip()
                for code in (candidate.get("reason_codes") or ())
                if str(code).strip()
            ]
            # ...and it carries the compile's funnel with it.  The solver
            # attaches ``window_gate_counts`` to its own error, but that
            # error never leaves ``_compile_target_plan``: the runtime
            # absorbs ``delta_v2_support_empty`` into a blocked plan and
            # files the funnel under ``delta_v2_audit``, and this line then
            # minted a *fresh* ContractError from the reason code alone.
            # The blocked-scope recorder reads the funnel off the exception
            # with ``getattr``, so it found nothing: measured 2026-09-09,
            # 0 of 1,808 blocked-scope rows since 09-01 carried a funnel,
            # including all 254 ``delta_v2_support_empty`` ones.  The two
            # tests that guard this checked the source text of the raise
            # and the recorder, which were both correct; the loss was the
            # hop between them.
            raise _blocked_plan_error(
                codes[0] if codes else "compiled_plan_blocked",
                candidate=candidate,
            )
        # Stage-zero is intentionally limited to pre-final P0/P0-M.  Once
        # official METAR/SPECI materializes P1, the final-authority path must
        # atomically persist the canonical observation/bound together with
        # the blocked no-live decision.  The ledger rejects a P1 stage-zero
        # anchor by contract, so routing P1 through that helper would turn a
        # healthy no-live candidate into a false fail-closed blocker.
        if stage == "P1":
            return self._commit_candidate(
                candidate,
                station_id=station_id,
                event_date=event_date,
                created_at_utc=created_at_utc,
            )
        return self._commit_stage_zero_execution_candidate(
            candidate,
            station_id=station_id,
            event_date=event_date,
            created_at_utc=created_at_utc,
        )

    def _flush_cash_phase_forward_observations_probe(self) -> dict[str, Any]:
        """Materialize atomically bound receipts into the bounded OOS store.

        The durable source is ``auto_trade_decisions.details_json``.  Scanning
        it by an append-only rowid cursor makes a store-write failure retryable
        and avoids an outbox or a second decision authority.

        This method is the validation core.  The public wrapper below invokes
        it in a one-row, no-write probe mode so a poison row can be quarantined
        without losing the valid prefix that precedes it.
        """

        if self.commit_conn is None:
            return {
                "state": "not_attempted",
                "reason": "target_atomic_writer_not_injected",
                "observation_count": 0,
                "written": False,
            }
        store_path = getattr(self, "cash_phase_forward_store_path", None)
        if store_path is None:
            raise ContractError("cash_phase_forward_store_path_missing")
        store_root = getattr(
            self,
            "cash_phase_forward_store_root",
            Path(store_path).parent,
        )
        store_state = read_forward_store_state(
            store_path,
            allowed_root=store_root,
        )
        source_cursor = int(
            getattr(
                self,
                "_forward_flush_source_cursor_override",
                store_state["last_source_rowid"],
            )
        )
        probe_rowid = getattr(self, "_forward_flush_probe_rowid", None)
        probe_mode = bool(getattr(self, "_forward_flush_probe", False))
        scan_limit = int(
            getattr(
                self,
                "_forward_flush_scan_limit",
                MAX_FORWARD_DECISIONS_PER_PASS,
            )
        )
        if not 1 <= scan_limit <= MAX_FORWARD_DECISIONS_PER_PASS:
            raise ContractError("cash_phase_forward_scan_limit_invalid")
        if probe_rowid is not None:
            try:
                probe_rowid = int(probe_rowid)
            except (TypeError, ValueError) as exc:
                raise ContractError("cash_phase_forward_probe_rowid_invalid") from exc
            if probe_rowid <= source_cursor:
                raise ContractError("cash_phase_forward_probe_cursor_order_invalid")
            header_sql = (
                "SELECT d.rowid,d.decision_id,d.decision_sha256,"
                "length(CAST(d.reason_codes_json AS BLOB)),"
                "length(CAST(d.details_json AS BLOB)),"
                "(SELECT COUNT(*) FROM basket_policy_training_fact f "
                " WHERE f.cycle_id=d.cycle_id AND f.decision_id=d.decision_id),"
                "(SELECT length(CAST(f.policy_version_vector_json AS BLOB)) "
                " FROM basket_policy_training_fact f "
                " WHERE f.cycle_id=d.cycle_id AND f.decision_id=d.decision_id "
                " LIMIT 1),"
                "(SELECT length(CAST(f.feature_json AS BLOB)) "
                " FROM basket_policy_training_fact f "
                " WHERE f.cycle_id=d.cycle_id AND f.decision_id=d.decision_id "
                " LIMIT 1) "
                "FROM auto_trade_decisions d "
                "WHERE d.rowid=? AND d.details_json LIKE "
                "'%\"forward_observation_status\":\"ELIGIBLE\"%' "
                "LIMIT 1"
            )
            header_params: tuple[Any, ...] = (probe_rowid,)
        else:
            header_sql = (
                "SELECT d.rowid,d.decision_id,d.decision_sha256,"
                "length(CAST(d.reason_codes_json AS BLOB)),"
                "length(CAST(d.details_json AS BLOB)),"
                "(SELECT COUNT(*) FROM basket_policy_training_fact f "
                " WHERE f.cycle_id=d.cycle_id AND f.decision_id=d.decision_id),"
                "(SELECT length(CAST(f.policy_version_vector_json AS BLOB)) "
                " FROM basket_policy_training_fact f "
                " WHERE f.cycle_id=d.cycle_id AND f.decision_id=d.decision_id "
                " LIMIT 1),"
                "(SELECT length(CAST(f.feature_json AS BLOB)) "
                " FROM basket_policy_training_fact f "
                " WHERE f.cycle_id=d.cycle_id AND f.decision_id=d.decision_id "
                " LIMIT 1) "
                "FROM auto_trade_decisions d "
                "WHERE d.rowid>? AND d.details_json LIKE "
                "'%\"forward_observation_status\":\"ELIGIBLE\"%' "
                "ORDER BY d.rowid LIMIT ?"
            )
            header_params = (source_cursor, scan_limit + 1)
        header_rows = self.commit_conn.execute(
            header_sql,
            header_params,
        ).fetchall()
        more_pending = (
            False
            if probe_rowid is not None
            else len(header_rows) > MAX_FORWARD_DECISIONS_PER_PASS
        )
        header_rows = header_rows[:scan_limit]
        if not header_rows:
            return {
                "state": "already_current",
                "reason": "no_new_eligible_atomic_receipts",
                "observation_count": int(
                    store_state.get("observation_count") or 0
                ),
                "written": False,
                "generation": int(store_state.get("generation") or 0),
            }
        decision_ids: list[str] = []
        total_json_bytes = 0
        for header in header_rows:
            decision_id = str(header[1] or "").strip()
            field_sizes = (
                int(header[3] or 0),
                int(header[4] or 0),
                int(header[6] or 0),
                int(header[7] or 0),
            )
            if (
                not decision_id
                or int(header[0] or 0) <= source_cursor
                or int(header[5] or 0) != 1
                or any(
                    size <= 0 or size > MAX_FORWARD_DECISION_JSON_BYTES
                    for size in field_sizes
                )
            ):
                raise ContractError(
                    "cash_phase_forward_record_cardinality_or_size_invalid"
                )
            total_json_bytes += sum(field_sizes)
            if total_json_bytes > MAX_FORWARD_SCAN_BYTES:
                raise ContractError(
                    "cash_phase_forward_decision_scan_bytes_exceeded"
                )
            decision_ids.append(decision_id)
        assert_process_memory_budget(projected_bytes=total_json_bytes * 3)

        full_row_sql = (
            "SELECT d.cycle_id,d.decision_id,d.plan_id,d.station_id,"
            "d.event_date,d.settlement_timezone,d.strategy_lane,"
            "d.decided_state,d.will_order,d.target_execution_hard_deadline_at,"
            "d.reason_codes_json,d.details_json,d.decision_sha256,d.created_at,"
            "c.plan_sha256,c.plan_id,c.station_id,c.event_date,"
            "c.settlement_timezone,c.strategy_lane,"
            "f.decision_at_utc,f.probability_envelope_id,f.posterior_sha256,"
            "f.quote_observed_at,f.quote_expires_at,f.quote_sha256,"
            "f.inventory_sha256,f.order_state_sha256,"
            "f.policy_version_vector_json,f.feature_json,"
            "f.decision_sha256,f.plan_sha256,f.stage,"
            "length(CAST(d.details_json AS BLOB)),"
            "f.ws_snapshot_id,f.quote_version,"
            "f.inventory_snapshot_id,f.inventory_version,"
            "f.order_state_snapshot_id,f.order_state_version,"
            "f.fact_id,f.content_sha256,f.authority_scope,d.rowid,"
            "d.decision_scope_key "
            "FROM auto_trade_decisions d "
            "JOIN basket_target_execution_cycles c ON c.cycle_id=d.cycle_id "
            "LEFT JOIN basket_policy_training_fact f "
            "ON f.cycle_id=d.cycle_id AND f.decision_id=d.decision_id "
            "WHERE d.decision_id=? "
            "AND d.details_json LIKE "
            "'%\"forward_observation_status\":\"ELIGIBLE\"%' LIMIT 2"
        )
        rows: list[tuple[Any, ...]] = []
        for decision_id in decision_ids:
            matches = self.commit_conn.execute(
                full_row_sql,
                (decision_id,),
            ).fetchall()
            if len(matches) != 1:
                raise ContractError(
                    "cash_phase_forward_record_exact_row_missing"
                )
            rows.append(tuple(matches[0]))
        eligible = 0
        store_records: list[dict[str, Any]] = []
        for row in rows:
            try:
                reasons = json.loads(str(row[10] or "[]"))
                details = json.loads(str(row[11] or "{}"))
                policy_vector = json.loads(str(row[28] or "{}"))
                feature = json.loads(str(row[29] or "{}"))
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                raise ContractError(
                    "cash_phase_forward_decision_json_invalid"
                ) from exc
            if (
                not isinstance(reasons, list)
                or not isinstance(details, Mapping)
                or not isinstance(policy_vector, Mapping)
                or not isinstance(feature, Mapping)
            ):
                raise ContractError(
                    "cash_phase_forward_decision_json_shape_invalid"
                )
            binding = details.get("forward_evidence_binding")
            if not isinstance(binding, Mapping):
                raise ContractError(
                    "cash_phase_forward_binding_mapping_required"
                )
            if details.get("forward_observation_status") != "ELIGIBLE":
                raise ContractError(
                    "cash_phase_forward_status_binding_mismatch"
                )
            probability_stage = str(
                binding.get("probability_stage") or ""
            ).strip().upper()
            stage_zero_pre_final = probability_stage in {"P0", "P0-M"}
            # Two writers stamp a forward-eligible decision, and each stamps
            # its own mode: the stage-zero pre-final fact says
            # ``production_no_live`` with submission never authorized
            # (``atomic_ledger.commit_stage_zero_execution_scope_decision``),
            # and the live-lane commit says the lane's mode with the lane's
            # authorization (``production.py``).  Before go-live the two
            # coincided, so the check read one mode and one flag.  Since
            # 2026-08-31 the lane's mode is ``production_live`` and every
            # ELIGIBLE row failed here on one clause or the other -- 838
            # quarantined 2026-09-02..09-10, nothing materialized after
            # 08-30.  The boundary is still "this decision placed no order"
            # (``will_order`` 0, a prepared or blocked state); the mode and
            # flag must only agree with the writer that stamped them.
            decision_mode = details.get("execution_mode")
            submit_authorized = details.get("live_submit_authorized")
            boundary_stamp_consistent = (
                decision_mode == NO_LIVE_EXECUTION_MODE
                and submit_authorized is False
            ) or (
                decision_mode == PRODUCTION_EXECUTION_MODE
                and submit_authorized is (
                    PRODUCTION_EXECUTION_MODE == "production_live"
                )
            )
            if (
                str(row[6]) != "basket"
                or int(row[8]) != 0
                or str(row[7]) not in {"prepared", "blocked"}
                or not boundary_stamp_consistent
                or details.get("delta_v2_authorized") is not True
            ):
                raise ContractError(
                    "cash_phase_forward_no_live_decision_boundary_invalid"
                )
            if stage_zero_pre_final:
                # Pre-final P0/P0-M decisions use the deliberately smaller
                # blocked-scope ledger receipt.  Its decision hash therefore
                # excludes an execution deadline (no intent can exist before
                # P1).  Require its full marker set before applying that
                # exact identity rule; a generic blocked/P1 receipt cannot
                # borrow the alternate schema.
                if (
                    str(row[7]) != "blocked"
                    or row[9] is not None
                    or details.get("stage_zero_execution_version") != 1
                    or details.get("final_authority") != "P1"
                    or details.get("capital_authorized") is not False
                    or type(details.get("intents_written")) is not int
                    or details.get("intents_written") != 0
                    or type(details.get("reservations_written")) is not int
                    or details.get("reservations_written") != 0
                    or type(details.get("training_facts_written")) is not int
                    or details.get("training_facts_written") != 1
                ):
                    raise ContractError(
                        "cash_phase_forward_stage_zero_receipt_invalid"
                    )
            # The decision's content address is the ledger's to define, and
            # this reader asks the ledger rather than keeping a copy of the
            # rule.  The copy it kept was the v1 identity (cycle, plan, the
            # commit clock); charter 69 (2026-09-02) made the decision its
            # economic content under ``DECISION_SCHEMA_V2``, and from that day
            # every row the copy re-derived mismatched.  The scope key is the
            # one the ledger stored beside the row, which is the one it hashed:
            # a training-fact decision carries its fact's key, a stage-zero
            # fact carries none.
            decision_identity = economic_decision_identity(
                station_id=str(row[3]),
                event_date=str(row[4]),
                settlement_timezone=str(row[5]),
                strategy_lane=str(row[6]),
                decided_state=str(row[7]),
                will_order=int(row[8]),
                reason_codes=reasons,
                details=details,
                decision_scope_key=str(row[44] or "") or None,
            )
            expected_decision_sha = ledger_content_hash(
                DECISION_SCHEMA_V2, decision_identity
            )
            expected_decision_id = ledger_derive_id(
                "decision", decision_identity
            )
            if (
                str(row[12]) != expected_decision_sha
                or str(row[1]) != expected_decision_id
            ):
                raise ContractError(
                    "cash_phase_forward_decision_content_address_mismatch"
                )
            cycle_identity = {
                "plan_id": str(row[15]),
                "station_id": str(row[16]),
                "event_date": str(row[17]),
                "settlement_timezone": str(row[18]),
                "strategy_lane": str(row[19]),
            }
            if (
                str(row[0])
                != "cycle_" + content_sha256(cycle_identity)[:40]
                or str(row[2]) != str(row[15])
                or str(row[3]) != str(row[16])
                or str(row[4]) != str(row[17])
                or str(row[5]) != str(row[18])
                or str(row[6]) != str(row[19])
            ):
                raise ContractError(
                    "cash_phase_forward_cycle_content_address_mismatch"
                )
            if (
                row[20] is None
                or str(row[20]) != str(row[13])
                or str(row[30]) != str(row[12])
                or str(row[31]) != str(row[14])
            ):
                raise ContractError(
                    "cash_phase_forward_training_fact_binding_mismatch"
                )
            if (
                str(binding.get("station_id") or "") != str(row[3])
                or str(binding.get("event_date") or "") != str(row[4])
                or str(binding.get("settlement_timezone") or "")
                != str(row[5])
                or not timestamp_eq(
                    str(binding.get("decision_at_utc") or ""),
                    str(row[13]),
                )
                or str(binding.get("probability_stage") or "")
                != str(row[32])
            ):
                raise ContractError(
                    "cash_phase_forward_binding_scope_or_clock_mismatch"
                )
            envelope_rows = self.commit_conn.execute(
                "SELECT decision_at_utc,content_sha256,posterior_sha256,"
                "settlement_timezone,station_id,event_date,stage "
                "FROM basket_probability_envelope "
                "WHERE envelope_id=? AND state='COMMITTED' LIMIT 2",
                (str(row[21]),),
            ).fetchall()
            if len(envelope_rows) != 1:
                raise ContractError(
                    "cash_phase_forward_probability_exact_row_missing"
                )
            envelope = envelope_rows[0]
            if (
                not timestamp_eq(
                    str(
                        binding.get(
                            "probability_decision_at_utc"
                        )
                        or ""
                    ),
                    str(envelope[0]),
                )
                or str(binding.get("probability_artifact_sha256") or "")
                != str(envelope[1])
                or str(binding.get("probability_lineage_sha256") or "")
                != str(envelope[2])
                or str(binding.get("settlement_timezone") or "")
                != str(envelope[3])
                or str(row[22]) != str(envelope[2])
                or str(envelope[4]) != str(row[3])
                or str(envelope[5]) != str(row[4])
                or str(envelope[6]) != str(row[32])
            ):
                raise ContractError(
                    "cash_phase_forward_probability_binding_drift"
                )
            quote_rows = self.commit_conn.execute(
                "SELECT quote_observed_at,quote_expires_at,"
                "settlement_timezone,quote_source,buckets_json,"
                "cash_phase_input_json,station_id,event_date,snapshot_id,"
                "market_id,quote_version FROM basket_official_ws_snapshot "
                # The scope first: content_sha256 has no index and sits
                # behind both JSON columns, so the bare hash was a scan of
                # 1.1M rows through their overflow pages -- 332 s of one
                # cycle's settlement lane on 2026-10-02.  The binding was
                # just checked to name this scope, so a quote from any other
                # is not this receipt's either way.
                "WHERE station_id=? AND event_date=? AND state='COMMITTED' "
                "AND content_sha256=? LIMIT 2",
                (str(row[3]), str(row[4]), str(row[25])),
            ).fetchall()
            if len(quote_rows) != 1:
                raise ContractError(
                    "cash_phase_forward_ws_exact_row_missing"
                )
            quote = quote_rows[0]
            try:
                quote_buckets = json.loads(str(quote[4] or "[]"))
                cash_input = json.loads(str(quote[5] or "{}"))
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                raise ContractError(
                    "cash_phase_forward_ws_payload_invalid"
                ) from exc
            if (
                not isinstance(quote_buckets, list)
                or not isinstance(cash_input, Mapping)
                or not timestamp_eq(
                    str(binding.get("ws_quote_observed_at_utc") or ""),
                    str(quote[0]),
                )
                or not timestamp_eq(
                    str(binding.get("ws_quote_expires_at_utc") or ""),
                    str(quote[1]),
                )
                or str(binding.get("settlement_timezone") or "")
                != str(quote[2])
                or str(quote[3]) != "OFFICIAL_CLOB_WS"
                or int(binding.get("ws_quote_count") or 0)
                != len(quote_buckets)
                or str(binding.get("ws_snapshot_sha256") or "")
                != str(row[25])
                or not timestamp_eq(
                    str(binding.get("cash_observed_at_utc") or ""),
                    str(cash_input.get("observed_at_utc") or ""),
                )
                or str(binding.get("cash_checkpoint_id") or "")
                != str(cash_input.get("checkpoint_id") or "")
                or str(quote[6]) != str(row[3])
                or str(quote[7]) != str(row[4])
                or str(quote[8]) != str(row[34])
                or not str(quote[9] or "").strip()
                or str(quote[10]) != str(row[35])
            ):
                raise ContractError(
                    "cash_phase_forward_ws_or_cash_clock_binding_drift"
                )
            plan_feature = feature.get("plan")
            plan_lineage = (
                plan_feature.get("lineage")
                if isinstance(plan_feature, Mapping)
                else None
            )
            plan_delta_v2_audit = (
                plan_feature.get("delta_v2_audit")
                if isinstance(plan_feature, Mapping)
                else None
            )
            station_policy = policy_vector.get("station_policy")
            if (
                not isinstance(plan_lineage, Mapping)
                or not isinstance(plan_delta_v2_audit, Mapping)
                or not isinstance(station_policy, Mapping)
                or plan_delta_v2_audit.get("authorized") is not True
                or str(binding.get("cash_decision_sha256") or "")
                != str(
                    plan_lineage.get("cash_phase_decision_sha256") or ""
                )
                or str(binding.get("cash_policy_sha256") or "")
                != str(policy_vector.get("cash_phase_policy_sha256") or "")
                or str(binding.get("station_policy_sha256") or "")
                != str(station_policy.get("policy_sha256") or "")
                or str(binding.get("delta_v2_artifact_sha256") or "")
                != str(
                    policy_vector.get("delta_v2_artifact_sha256") or ""
                )
                or str(binding.get("delta_v2_evaluation_sha256") or "")
                != str(plan_delta_v2_audit.get("content_sha256") or "")
                or str(binding.get("inventory_sha256") or "")
                != str(row[26])
                or str(binding.get("order_state_sha256") or "")
                != str(row[27])
            ):
                raise ContractError(
                    "cash_phase_forward_policy_or_state_binding_drift"
                )
            inventory_rows = self.commit_conn.execute(
                "SELECT station_id,event_date,inventory_version,complete,"
                "content_sha256 FROM basket_confirmed_inventory_snapshot "
                "WHERE inventory_snapshot_id=? AND state='COMMITTED' LIMIT 2",
                (str(row[36]),),
            ).fetchall()
            if (
                len(inventory_rows) != 1
                or str(inventory_rows[0][0]) != str(row[3])
                or str(inventory_rows[0][1]) != str(row[4])
                or str(inventory_rows[0][2]) != str(row[37])
                or int(inventory_rows[0][3]) != 1
                or str(inventory_rows[0][4]) != str(row[26])
            ):
                raise ContractError(
                    "cash_phase_forward_inventory_ssot_drift"
                )
            order_state_rows = self.commit_conn.execute(
                "SELECT station_id,event_date,order_state_version,known,"
                "content_sha256 FROM basket_order_state_snapshot "
                "WHERE order_state_snapshot_id=? AND state='COMMITTED' LIMIT 2",
                (str(row[38]),),
            ).fetchall()
            if (
                len(order_state_rows) != 1
                or str(order_state_rows[0][0]) != str(row[3])
                or str(order_state_rows[0][1]) != str(row[4])
                or str(order_state_rows[0][2]) != str(row[39])
                or int(order_state_rows[0][3]) != 1
                or str(order_state_rows[0][4]) != str(row[27])
            ):
                raise ContractError(
                    "cash_phase_forward_order_state_ssot_drift"
                )
            fact_cursor = self.commit_conn.execute(
                "SELECT * FROM basket_policy_training_fact "
                "WHERE fact_id=? LIMIT 2",
                (str(row[40]),),
            )
            fact_rows = fact_cursor.fetchall()
            if len(fact_rows) != 1:
                raise ContractError(
                    "cash_phase_forward_training_fact_exact_row_missing"
                )
            fact_columns = [
                str(column[0]) for column in fact_cursor.description or ()
            ]
            fact = dict(zip(fact_columns, tuple(fact_rows[0])))
            fact_identity = {
                key: value
                for key, value in fact.items()
                if key not in {"fact_id", "content_sha256"}
            }
            expected_fact_sha = content_sha256(
                {"schema": FACT_SCHEMA, **fact_identity}
            )
            if (
                str(fact.get("fact_id") or "")
                != "d2fact_" + expected_fact_sha[:40]
                or str(fact.get("content_sha256") or "")
                != expected_fact_sha
                or str(row[41]) != expected_fact_sha
                or str(fact.get("authority_scope") or "")
                != FACT_AUTHORITY_SCOPE
                or str(row[42]) != FACT_AUTHORITY_SCOPE
                or str(fact.get("station_id") or "") != str(row[3])
                or str(fact.get("event_date") or "") != str(row[4])
                or str(fact.get("settlement_timezone") or "") != str(row[5])
            ):
                raise ContractError(
                    "cash_phase_forward_training_fact_content_address_mismatch"
                )
            receipt = {
                "schema": "bayes_basket_target_atomic_forward_cycle_receipt_v1",
                "cycle_id": str(row[0]),
                "decision_id": str(row[1]),
                "plan_id": str(row[2]),
                "plan_sha256": str(row[14]),
                "decision_sha256": str(row[12]),
                "decision_at_utc": str(row[13]),
                "forward_evidence_binding": dict(binding),
                # The receipt's own mode, not the lane's: this receipt places
                # no order whatever the lane is armed to do (every flag below
                # says so), and the forward store admits only no-live
                # evidence.  Stamping the lane's mode after go-live made every
                # receipt inadmissible (``cycle_execution_mode_must_be_...``).
                "execution_mode": NO_LIVE_EXECUTION_MODE,
                "writes_target_ledger": True,
                "orders_submitted": 0,
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
                "authorizes_order": False,
                "evidence_only": True,
            }
            receipt["receipt_sha256"] = content_sha256(receipt)
            station_id = str(binding.get("station_id") or "").strip()
            event_date = str(binding.get("event_date") or "").strip()
            registry_rows = self.commit_conn.execute(
                "SELECT station_id,event_date,settlement_timezone "
                "FROM basket_target_market_registry "
                "WHERE station_id=? AND event_date=? "
                "ORDER BY outcome,yes_token",
                (station_id, event_date),
            ).fetchall()
            registry = {
                "rows": [
                    {
                        "station_id": str(item[0]),
                        "event_date": str(item[1]),
                        "settlement_timezone": str(item[2]),
                    }
                    for item in registry_rows
                ]
            }
            packet = build_forward_observation_packet(
                cycle_receipt=receipt,
                registry=registry,
            )
            packet_rows = packet.get("observations")
            if (
                not isinstance(packet_rows, list)
                or len(packet_rows) != 1
                or not isinstance(packet_rows[0], Mapping)
            ):
                raise ContractError(
                    "cash_phase_forward_single_observation_expected"
                )
            store_records.append({
                "observation": dict(packet_rows[0]),
                "decision_id": str(row[1]),
                "decision_sha256": str(row[12]),
                "source_rowid": int(row[43]),
            })
            eligible += 1
        if probe_mode:
            if not store_records:
                raise ContractError(
                    "cash_phase_forward_probe_record_missing"
                )
            return {
                "schema": "bayes_basket_target_forward_observation_probe_v1",
                "state": "validated",
                "records": store_records,
                "last_source_rowid": max(
                    int(record["source_rowid"]) for record in store_records
                ),
                "eligible_atomic_receipt_count": eligible,
                "more_pending": more_pending,
                "orders_submitted": 0,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
            }
        materialized = commit_forward_observation_batch(
            store_path,
            records=store_records,
            expected_generation=int(store_state["generation"]),
            last_source_rowid=max(
                int(record["source_rowid"]) for record in store_records
            ),
            materialized_at_utc=utc_now(),
            allowed_root=store_root,
        )
        return {
            **materialized,
            "state": (
                "committed_more_pending"
                if more_pending
                else str(materialized["state"])
            ),
            "eligible_atomic_receipt_count": eligible,
            "written": int(materialized.get("inserted") or 0) > 0,
            "more_pending": more_pending,
            "orders_submitted": 0,
            "calls_order_gateway": False,
            "live_submit_authorized": False,
        }

    def _flush_cash_phase_forward_observations(self) -> dict[str, Any]:
        """Validate a bounded source prefix, then commit or quarantine it.

        A poison source row is not allowed to pin the append-only cursor.  The
        valid prefix is committed first; the first poison row is then handed
        to the storage API as identity-only quarantine metadata.  Rows after
        that poison row intentionally remain for the next pass so a failure
        between the two storage calls cannot lose valid observations.

        Canonical storage API::

            quarantine_forward_observation_batch(
                store_path, *, records, expected_generation,
                quarantined_at_utc, allowed_root
            ) -> Mapping

        The API must atomically append only ``decision_id``, source SHA,
        source rowid and error code, and update the store generation/cursor.
        It must reject identity conflicts and resource-limit violations.
        """

        if self.commit_conn is None:
            return {
                "state": "not_attempted",
                "reason": "target_atomic_writer_not_injected",
                "observation_count": 0,
                "written": False,
                "promotion_allowed": False,
            }
        store_path = getattr(self, "cash_phase_forward_store_path", None)
        if store_path is None:
            raise ContractError("cash_phase_forward_store_path_missing")
        store_root = getattr(
            self,
            "cash_phase_forward_store_root",
            Path(store_path).parent,
        )
        store_state = read_forward_store_state(
            store_path,
            allowed_root=store_root,
        )
        source_cursor = int(store_state.get("last_source_rowid") or 0)
        # Charter 183: start past the rows an earlier empty scan already
        # read.  ``auto_trade_decisions`` is append-only by trigger, so a row
        # that did not match the ELIGIBLE filter never will; the store cursor
        # moves only on a written observation, so without this every pass
        # re-read every decision since the last ELIGIBLE one, details_json
        # and all (2 passes, 16.4s at 11:40Z; 12.1s at 12:12Z).  A cursor
        # that has moved back (a rebuilt store) or another store drops it.
        scanned = getattr(self, "_forward_flush_scanned", None)
        scan_after = source_cursor
        if (
            isinstance(scanned, tuple)
            and scanned[0] == str(store_path)
            and source_cursor >= int(scanned[1])
        ):
            scan_after = max(source_cursor, int(scanned[2]))
        scan_ceiling = int(self.commit_conn.execute(
            "SELECT COALESCE(MAX(rowid),0) FROM auto_trade_decisions"
        ).fetchone()[0])
        header_rows = self.commit_conn.execute(
            "SELECT d.rowid,d.decision_id,d.decision_sha256,"
            "length(CAST(d.reason_codes_json AS BLOB)),"
            "length(CAST(d.details_json AS BLOB)),"
            "(SELECT COUNT(*) FROM basket_policy_training_fact f "
            " WHERE f.cycle_id=d.cycle_id AND f.decision_id=d.decision_id),"
            "(SELECT length(CAST(f.policy_version_vector_json AS BLOB)) "
            " FROM basket_policy_training_fact f "
            " WHERE f.cycle_id=d.cycle_id AND f.decision_id=d.decision_id "
            " LIMIT 1),"
            "(SELECT length(CAST(f.feature_json AS BLOB)) "
            " FROM basket_policy_training_fact f "
            " WHERE f.cycle_id=d.cycle_id AND f.decision_id=d.decision_id "
            " LIMIT 1) "
            "FROM auto_trade_decisions d "
            "WHERE d.rowid>? AND d.details_json LIKE "
            "'%\"forward_observation_status\":\"ELIGIBLE\"%' "
            "ORDER BY d.rowid LIMIT ?",
            (scan_after, MAX_FORWARD_DECISIONS_PER_PASS + 1),
        ).fetchall()
        more_pending = len(header_rows) > MAX_FORWARD_DECISIONS_PER_PASS
        header_rows = header_rows[:MAX_FORWARD_DECISIONS_PER_PASS]
        if not header_rows:
            # Charter 183: nothing up to the ceiling read before the scan is
            # ELIGIBLE, and nothing below it can become so.
            self._forward_flush_scanned = (
                str(store_path), source_cursor, scan_ceiling,
            )
            return {
                "state": "already_current",
                "reason": "no_new_eligible_atomic_receipts",
                "observation_count": int(store_state.get("observation_count") or 0),
                "written": False,
                "generation": int(store_state.get("generation") or 0),
                "promotion_allowed": True,
                "orders_submitted": 0,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
            }

        def _sha256(value: Any) -> bool:
            text = str(value or "").strip()
            return len(text) == 64 and all(
                char in "0123456789abcdefABCDEF" for char in text
            )

        def _identity(header: tuple[Any, ...]) -> dict[str, Any] | None:
            try:
                rowid = int(header[0] or 0)
            except (TypeError, ValueError):
                return None
            decision_id = str(header[1] or "").strip()
            source_sha = str(header[2] or "").strip()
            if rowid <= source_cursor or not decision_id or not _sha256(source_sha):
                return None
            return {
                "decision_id": decision_id,
                "source_decision_sha256": source_sha,
                "source_rowid": rowid,
            }

        def _stable_error_code(exc: Exception) -> str:
            base = str(exc).split(":", 1)[0].strip().lower()
            normalized = re.sub(r"[^a-z0-9_.:-]+", "_", base).strip("_")
            return (normalized or "cash_phase_forward_record_invalid")[:128]

        total_header_bytes = 0
        valid_records: list[dict[str, Any]] = []
        poison: dict[str, Any] | None = None
        for header in header_rows:
            identity = _identity(tuple(header))
            if identity is None:
                return {
                    "state": "blocked_fail_closed",
                    "reason": "cash_phase_forward_identity_unstable",
                    "promotion_allowed": False,
                    "cursor_advanced": False,
                    "quarantined_count": 0,
                    "written": False,
                    "observation_count": int(store_state.get("observation_count") or 0),
                    "orders_submitted": 0,
                    "calls_order_gateway": False,
                    "live_submit_authorized": False,
                }
            sizes = (
                int(header[3] or 0),
                int(header[4] or 0),
                int(header[6] or 0),
                int(header[7] or 0),
            )
            total_header_bytes += sum(sizes)
            if total_header_bytes > MAX_FORWARD_SCAN_BYTES:
                return {
                    "state": "blocked_fail_closed",
                    "reason": "cash_phase_forward_decision_scan_bytes_exceeded",
                    "promotion_allowed": False,
                    "cursor_advanced": False,
                    "quarantined_count": 0,
                    "written": False,
                    "observation_count": int(store_state.get("observation_count") or 0),
                    "orders_submitted": 0,
                    "calls_order_gateway": False,
                    "live_submit_authorized": False,
                }
            if (
                int(header[5] or 0) != 1
                or any(size <= 0 or size > MAX_FORWARD_DECISION_JSON_BYTES for size in sizes)
            ):
                poison = {
                    **identity,
                    "error_code": "cash_phase_forward_record_cardinality_or_size_invalid",
                }
                break

            previous = {
                "_forward_flush_probe": getattr(self, "_forward_flush_probe", None),
                "_forward_flush_probe_rowid": getattr(self, "_forward_flush_probe_rowid", None),
                "_forward_flush_source_cursor_override": getattr(
                    self, "_forward_flush_source_cursor_override", None
                ),
                "_forward_flush_scan_limit": getattr(self, "_forward_flush_scan_limit", None),
            }
            try:
                self._forward_flush_probe = True
                self._forward_flush_probe_rowid = identity["source_rowid"]
                self._forward_flush_source_cursor_override = source_cursor
                self._forward_flush_scan_limit = 1
                probe = self._flush_cash_phase_forward_observations_probe()
            except Exception as exc:
                error_text = str(exc)
                # Resource failures and unexpected implementation/database
                # failures are not poison evidence: quarantine cannot prove a
                # stable identity in those cases, so the cursor stays put.
                if (
                    not isinstance(exc, ContractError)
                    or not error_text.startswith("cash_phase_forward_")
                ):
                    return {
                        "state": "blocked_fail_closed",
                        "reason": f"{type(exc).__name__}:{exc}",
                        "promotion_allowed": False,
                        "cursor_advanced": False,
                        "quarantined_count": 0,
                        "written": False,
                        "observation_count": int(store_state.get("observation_count") or 0),
                        "orders_submitted": 0,
                        "calls_order_gateway": False,
                        "live_submit_authorized": False,
                    }
                poison = {
                    **identity,
                    "error_code": _stable_error_code(exc),
                }
                break
            finally:
                for name, value in previous.items():
                    if value is None:
                        self.__dict__.pop(name, None)
                    else:
                        setattr(self, name, value)
            probe_records = probe.get("records") if isinstance(probe, Mapping) else None
            if (
                not isinstance(probe_records, list)
                or len(probe_records) != 1
                or not isinstance(probe_records[0], Mapping)
            ):
                return {
                    "state": "blocked_fail_closed",
                    "reason": "cash_phase_forward_probe_result_invalid",
                    "promotion_allowed": False,
                    "cursor_advanced": False,
                    "quarantined_count": 0,
                    "written": False,
                    "observation_count": int(store_state.get("observation_count") or 0),
                    "orders_submitted": 0,
                    "calls_order_gateway": False,
                    "live_submit_authorized": False,
                }
            valid_records.append(dict(probe_records[0]))

        def _blocked_result(reason: str, *, cursor_advanced: bool = False, quarantined_count: int = 0, **extra: Any) -> dict[str, Any]:
            return {
                "state": "blocked_fail_closed",
                "reason": reason,
                "promotion_allowed": False,
                "cursor_advanced": cursor_advanced,
                "quarantined_count": quarantined_count,
                "orders_submitted": 0,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
                **extra,
            }

        materialized: dict[str, Any] | None = None
        if valid_records:
            try:
                assert_process_memory_budget(projected_bytes=total_header_bytes * 3)
                materialized = commit_forward_observation_batch(
                    store_path,
                    records=valid_records,
                    expected_generation=int(store_state["generation"]),
                    last_source_rowid=max(
                        int(record["source_rowid"]) for record in valid_records
                    ),
                    materialized_at_utc=utc_now(),
                    allowed_root=store_root,
                )
            except Exception as exc:
                return _blocked_result(
                    f"{type(exc).__name__}:{exc}",
                    cursor_advanced=False,
                    observation_count=int(store_state.get("observation_count") or 0),
                    written=False,
                )

        if poison is not None:
            try:
                after_valid = read_forward_store_state(
                    store_path,
                    allowed_root=store_root,
                )
                quarantined = quarantine_forward_observation_batch(
                    store_path,
                    records=[{
                        "decision_id": poison["decision_id"],
                        "source_decision_sha256": poison["source_decision_sha256"],
                        "source_rowid": int(poison["source_rowid"]),
                        "error_code": str(poison["error_code"])[:128],
                    }],
                    expected_generation=int(after_valid["generation"]),
                    quarantined_at_utc=utc_now(),
                    allowed_root=store_root,
                )
            except Exception as exc:
                return _blocked_result(
                    f"{type(exc).__name__}:{exc}",
                    cursor_advanced=bool(materialized),
                    poison_cursor_advanced=False,
                    observation_count=int((materialized or {}).get("observation_count") or store_state.get("observation_count") or 0),
                    written=bool(materialized and materialized.get("inserted")),
                )
            return _blocked_result(
                "cash_phase_forward_poison_quarantined",
                cursor_advanced=True,
                poison_cursor_advanced=True,
                quarantined_count=int(
                    quarantined.get("quarantined", quarantined.get("inserted", 1))
                    if isinstance(quarantined, Mapping)
                    else 1
                ),
                written=bool(materialized and materialized.get("inserted")),
                observation_count=int(
                    quarantined.get("observation_count", (materialized or {}).get("observation_count", 0))
                    if isinstance(quarantined, Mapping)
                    else (materialized or {}).get("observation_count", 0)
                ),
                more_pending=more_pending,
            )

        if materialized is None:
            return _blocked_result(
                "cash_phase_forward_no_valid_records",
                cursor_advanced=False,
                observation_count=int(store_state.get("observation_count") or 0),
                written=False,
            )
        return {
            **materialized,
            "state": (
                "committed_more_pending"
                if more_pending
                else str(materialized.get("state") or "committed")
            ),
            "promotion_allowed": True,
            "cursor_advanced": bool(valid_records),
            "eligible_atomic_receipt_count": len(valid_records),
            "written": int(materialized.get("inserted") or 0) > 0,
            "more_pending": more_pending,
            "orders_submitted": 0,
            "calls_order_gateway": False,
            "live_submit_authorized": False,
        }

    def _consume_post_fill_recompute_requests(
        self,
        *,
        activation: Mapping[str, Any],
        scope_config: Mapping[str, Any],
        as_of_utc: str,
    ) -> dict[str, Any]:
        """Recompile every authoritative full or terminal partial fill.

        Receipt ingress only records the authoritative transition and a
        content-addressed request.  The resident worker owns the next
        probability -> quote -> inventory -> objective evaluation.  A request
        is acknowledged only in the same writer transaction that commits the
        replacement candidate; compile/commit failures therefore leave it
        pending for a bounded retry.
        """

        if self.commit_conn is None:
            return {
                "schema": "bayes_basket_target_post_fill_recompute_batch_v1",
                "state": "not_attempted",
                "reason": "target_atomic_writer_not_injected",
                "request_count": 0,
                "applied_count": 0,
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
        requests = load_post_fill_recompute_requests(self.commit_conn)
        if len(requests) > MAX_POST_FILL_RECOMPUTES_PER_PASS:
            raise RuntimeError("post_fill_recompute_request_cap_exceeded")
        results: list[dict[str, Any]] = []
        blockers: list[dict[str, str]] = []
        seen_request_ids: set[str] = set()
        for request in requests:
            try:
                if not isinstance(request, Mapping):
                    raise ContractError("post_fill_recompute_request_mapping_required")
                request_id = str(request.get("request_id") or "").strip()
                if not request_id or request_id in seen_request_ids:
                    raise ContractError("post_fill_recompute_request_identity_invalid")
                seen_request_ids.add(request_id)
                request_scope = request.get("scope")
                if not isinstance(request_scope, Mapping):
                    raise ContractError("post_fill_recompute_scope_missing")
                station = str(request_scope.get("station_id") or "").strip().upper()
                day = str(request_scope.get("event_date") or "").strip()
                settlement_timezone = str(
                    request_scope.get("settlement_timezone") or ""
                ).strip()
                if not station or not day or not settlement_timezone:
                    raise ContractError("post_fill_recompute_scope_incomplete")
                from .execution_transition_runtime import (
                    post_fill_recompute_binding_sha256,
                )

                source_binding_sha = post_fill_recompute_binding_sha256(
                    request
                )
                if not self._event_day_open(
                    day,
                    settlement_timezone=settlement_timezone,
                    as_of_utc=as_of_utc,
                ):
                    raise ContractError("post_fill_recompute_event_day_not_open")
                transition = self.commit_conn.execute(
                    "SELECT state,inventory_version,order_state_version,"
                    "evidence_json,content_sha256,filled_size,"
                    "filled_notional_usdc "
                    "FROM basket_target_execution_transition_versions "
                    "WHERE order_intent_id=?",
                    (str(request.get("order_intent_id") or ""),),
                ).fetchone()
                if transition is None:
                    raise ContractError("post_fill_recompute_transition_missing")
                if str(transition[0]) not in {
                    "FULL_FILLED",
                    "PARTIAL_FILLED",
                }:
                    raise ContractError(
                        "post_fill_recompute_transition_state_not_recomputable"
                    )
                if (
                    str(transition[1]) != str(request.get("inventory_version") or "")
                    or str(transition[2]) != str(request.get("order_state_version") or "")
                ):
                    raise ContractError("post_fill_recompute_transition_version_drift")
                try:
                    transition_evidence = json.loads(
                        str(transition[3] or "")
                    )
                except (TypeError, ValueError, json.JSONDecodeError) as exc:
                    raise ContractError(
                        "post_fill_recompute_transition_evidence_invalid"
                    ) from exc
                if not isinstance(transition_evidence, Mapping):
                    raise ContractError(
                        "post_fill_recompute_transition_evidence_invalid"
                    )
                if (
                    transition_evidence.get("version_vector")
                    != request.get("source_execution_version_vector")
                    or int(transition_evidence.get("quote_sequence", -1))
                    != int(request.get("quote_sequence", -2))
                    or str(transition_evidence.get("scope_sha256") or "")
                    != str(request.get("source_scope_sha256") or "")
                    or str(transition[4] or "")
                    != str(request.get("source_transition_sha256") or "")
                ):
                    raise ContractError(
                        "post_fill_recompute_transition_full_vector_drift"
                    )
                candidate = compile_production_cycle_from_ssot(
                    self.conn,
                    station_id=station,
                    event_date=day,
                    evaluation_at_utc=as_of_utc,
                    season_bin=str(scope_config["season_bin"]),
                    maturity_bin=str(scope_config["maturity_bin"]),
                    liquidity_bin=str(scope_config["liquidity_bin"]),
                    strategy_version=str(scope_config["strategy_version"]),
                    policy_authority_scope=str(
                        activation["policy_authority_scope"]
                    ),
                    base_policy=(
                        scope_config.get("base_policy")
                        if isinstance(scope_config.get("base_policy"), Mapping)
                        else None
                    ),
                    # Charter 125: the day's own thermometer, read here
                    # because this process is the one holding the canonical
                    # observation connection.
                    observed_running_high_c=self._observed_running_high_c(
                        station_id=station,
                        event_date=day,
                        as_of_utc=as_of_utc,
                    ),
                )
                self._assert_post_fill_candidate_projection(
                    candidate=candidate,
                    request=request,
                    transition_content_sha256=str(transition[4] or ""),
                    transition_filled_size=float(transition[5] or 0.0),
                    transition_filled_notional_usdc=float(
                        transition[6] or 0.0
                    ),
                )
                post_fill_market = candidate.get(
                    "production_market_snapshot"
                )
                if not isinstance(post_fill_market, Mapping):
                    raise ContractError(
                        "post_fill_recompute_market_snapshot_missing"
                    )
                completion = {
                    "schema": "bayes_basket_target_post_fill_recompute_result_v1",
                    "request_id": request_id,
                    "order_intent_id": str(request.get("order_intent_id") or ""),
                    "source_cycle_id": str(request.get("cycle_id") or ""),
                    "station_id": station,
                    "event_date": day,
                    "settlement_timezone": settlement_timezone,
                    "recomputed_at_utc": as_of_utc,
                    "source_request_binding_sha256": source_binding_sha,
                    "production_cycle_sha256": str(
                        candidate.get("production_cycle_sha256") or ""
                    ),
                    "post_fill_inventory_sha256": str(
                        post_fill_market.get("inventory_sha256") or ""
                    ),
                    "post_fill_order_state_sha256": str(
                        post_fill_market.get("order_state_sha256") or ""
                    ),
                    "post_fill_transition_sha256": str(
                        transition[4] or ""
                    ),
                    "status": str(candidate.get("status") or ""),
                    "execution_mode": PRODUCTION_EXECUTION_MODE,
                    "places_orders": False,
                    "calls_order_gateway": False,
                    "live_submit_authorized": False,
                    "orders_submitted": 0,
                }
                if not completion["production_cycle_sha256"]:
                    raise ContractError("post_fill_recompute_candidate_sha_missing")
                from .execution_transition_runtime import (
                    complete_post_fill_recompute_request,
                )

                with _writer_transaction(
                    self.commit_conn,
                    savepoint="post_fill_recompute_scope",
                ):
                    atomic_commit = self._commit_candidate(
                        candidate,
                        station_id=station,
                        event_date=day,
                        created_at_utc=as_of_utc,
                    )
                    if atomic_commit.get("writes_target_ledger") is not True:
                        raise ContractError(
                            "post_fill_recompute_candidate_not_committed"
                        )
                    completion["atomic_commit"] = atomic_commit
                    completed = complete_post_fill_recompute_request(
                        self.commit_conn,
                        request_id=request_id,
                        scope=request_scope,
                        inventory_version=str(request["inventory_version"]),
                        order_state_version=str(request["order_state_version"]),
                        result=completion,
                        result_content_sha256=content_sha256(completion),
                        completed_at_utc=as_of_utc,
                    )
                results.append({
                    "request_id": request_id,
                    "station_id": station,
                    "event_date": day,
                    "candidate": {
                        **candidate,
                        "atomic_commit": atomic_commit,
                        "post_fill_recompute_request_id": request_id,
                    },
                    "completion": completed,
                })
            except Exception as exc:
                blockers.append({
                    "request_id": str(
                        request.get("request_id") or ""
                    ) if isinstance(request, Mapping) else "",
                    "station_id": str(
                        (request.get("scope") or {}).get("station_id") or ""
                    ) if isinstance(request, Mapping) and isinstance(
                        request.get("scope"), Mapping
                    ) else "",
                    "event_date": str(
                        (request.get("scope") or {}).get("event_date") or ""
                    ) if isinstance(request, Mapping) and isinstance(
                        request.get("scope"), Mapping
                    ) else "",
                    "reason": f"{type(exc).__name__}:{exc}",
                })
            assert_process_memory_budget()
        return {
            "schema": "bayes_basket_target_post_fill_recompute_batch_v1",
            "state": "BLOCKED_FAIL_CLOSED" if blockers else "COMMITTED",
            "request_count": len(requests),
            "applied_count": len(results),
            "results": results,
            "blockers": blockers,
            "places_orders": False,
            "calls_order_gateway": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }

    def _assert_post_fill_candidate_projection(
        self,
        *,
        candidate: Mapping[str, Any],
        request: Mapping[str, Any],
        transition_content_sha256: str,
        transition_filled_size: float,
        transition_filled_notional_usdc: float,
    ) -> None:
        """Prove that a recompute consumed the authoritative post-fill q.

        The receipt transition versions are event-level identities.  Resident
        market ingress folds all current transition rows into aggregate
        inventory and order-state snapshots, whose versions intentionally
        differ from the event-level versions.  A recompute is therefore
        admissible only when both aggregate snapshots retain the exact
        transition hash in lineage and the projected bucket position includes
        at least the authoritative fill.
        """

        if self.commit_conn is None:
            raise ContractError(
                "post_fill_recompute_projection_writer_missing"
            )
        market = candidate.get("production_market_snapshot")
        if not isinstance(market, Mapping):
            raise ContractError(
                "post_fill_recompute_market_snapshot_missing"
            )
        inventory_sha = str(market.get("inventory_sha256") or "")
        order_state_sha = str(market.get("order_state_sha256") or "")
        if not inventory_sha or not order_state_sha:
            raise ContractError(
                "post_fill_recompute_state_content_address_missing"
            )
        inventory_row = self.commit_conn.execute(
            "SELECT inventory_json FROM "
            "basket_confirmed_inventory_snapshot WHERE content_sha256=?",
            (inventory_sha,),
        ).fetchone()
        order_state_row = self.commit_conn.execute(
            "SELECT order_state_json FROM basket_order_state_snapshot "
            "WHERE content_sha256=?",
            (order_state_sha,),
        ).fetchone()
        if inventory_row is None or order_state_row is None:
            raise ContractError(
                "post_fill_recompute_projected_state_missing"
            )
        try:
            inventory = json.loads(str(inventory_row[0] or ""))
            order_state = json.loads(str(order_state_row[0] or ""))
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            raise ContractError(
                "post_fill_recompute_projected_state_invalid"
            ) from exc
        if not isinstance(inventory, Mapping) or not isinstance(
            order_state, Mapping
        ):
            raise ContractError(
                "post_fill_recompute_projected_state_invalid"
            )
        source_transition = str(transition_content_sha256 or "").strip()
        inventory_lineage = inventory.get("transition_content_sha256")
        order_state_lineage = order_state.get(
            "transition_content_sha256"
        )
        if (
            not source_transition
            or not isinstance(inventory_lineage, list)
            or source_transition
            not in {str(value) for value in inventory_lineage}
            or not isinstance(order_state_lineage, list)
            or source_transition
            not in {str(value) for value in order_state_lineage}
        ):
            raise ContractError(
                "post_fill_recompute_transition_not_materialized"
            )
        scope = request.get("scope")
        if not isinstance(scope, Mapping):
            raise ContractError("post_fill_recompute_scope_missing")
        bucket = str(scope.get("bucket") or "")
        filled_by_bucket = inventory.get("filled_by_bucket")
        filled_cost_by_bucket = inventory.get("filled_cost_by_bucket")
        if (
            not bucket
            or not isinstance(filled_by_bucket, Mapping)
            or not isinstance(filled_cost_by_bucket, Mapping)
        ):
            raise ContractError(
                "post_fill_recompute_inventory_projection_invalid"
            )
        try:
            projected_size = float(filled_by_bucket.get(bucket, 0.0))
            projected_notional = float(
                filled_cost_by_bucket.get(bucket, 0.0)
            )
        except (TypeError, ValueError) as exc:
            raise ContractError(
                "post_fill_recompute_inventory_projection_invalid"
            ) from exc
        if projected_size + 1e-9 < float(transition_filled_size):
            raise ContractError(
                "post_fill_recompute_filled_size_not_projected"
            )
        if projected_notional + 1e-9 < float(
            transition_filled_notional_usdc
        ):
            raise ContractError(
                "post_fill_recompute_filled_notional_not_projected"
            )

    def _scope_day_quote_expiry(
        self, event_date: str, station_id: str | None = None
    ) -> datetime | None:
        """When this scope's freshest book stops being usable, or None.

        Read from the snapshot the compile itself validates against, so the
        trigger and the failure answer the same question rather than one
        being a proxy for the other.

        With a station, the answer is that station-day's own newest expiry;
        without one, the day's across the fleet.  Both callers exist and they
        are asking different questions.  The trigger wants the station's,
        because the compile fails on the station's: a fleet maximum says the
        books are fine while the station in hand has been expired for hours,
        which is precisely how a scope reaches production_quote_expired with
        no refresh ever attempted for it.  The effectiveness test wants the
        day's, because it is asking whether the pass wrote anything at all.

        Cached by the caller, never asked once per scope unconditionally.  The
        first version scanned the table and cost 6.8 seconds a call; both
        forms are index reads now -- measured 2026-09-01, 2.3ms for all 44
        stations of a day -- so per-station is affordable at this cadence.
        """

        if self.conn is None:
            return None
        station = str(station_id or "").strip()
        try:
            if station:
                row = self.conn.execute(
                    "SELECT MAX(quote_expires_at) "
                    "FROM basket_official_ws_snapshot"
                    " WHERE station_id=? AND event_date=?",
                    (station, str(event_date)),
                ).fetchone()
            else:
                row = self.conn.execute(
                    "SELECT MAX(quote_expires_at) "
                    "FROM basket_official_ws_snapshot"
                    " WHERE event_date=?",
                    (str(event_date),),
                ).fetchone()
        except sqlite3.Error:
            return None
        if row is None or not row[0]:
            return None
        try:
            return datetime.fromisoformat(str(row[0]).replace("Z", "+00:00"))
        except ValueError:
            return None

    def _await_publisher_books(
        self,
        *,
        station_id: str,
        event_date: str,
        lease_seconds: float,
        budget_seconds: float,
    ) -> tuple[float, bool]:
        """Wait until the publisher holds books that would renew this scope.

        Returns the seconds waited and whether such books arrived.  The
        manifest is re-read only when the file changes; a scope the
        publisher does not carry returns at once, since no generation will
        bring it.  ``QUOTE_PUBLISHER_WAIT_BUDGET_SECONDS`` says why.
        """

        started = time.monotonic()
        last_identity: tuple[int, int] | None = None
        station = str(station_id).strip().upper()
        while True:
            if self.stop_requested:
                return time.monotonic() - started, False
            try:
                stat = os.stat(self.market_manifest_path)
                identity: tuple[int, int] | None = (
                    stat.st_mtime_ns, stat.st_size,
                )
            except OSError:
                identity = None
            if identity is not None and identity != last_identity:
                last_identity = identity
                try:
                    manifest = next(
                        (
                            item["manifest"]
                            for item in self._resident_ws_scope_catalog()
                            if str(item.get("event_date") or "") == str(event_date)
                            and str(item.get("station_id") or "").strip().upper()
                            == station
                            and isinstance(item.get("manifest"), Mapping)
                        ),
                        None,
                    )
                except Exception:  # noqa: BLE001 -- mid-write; read again
                    manifest = {}
                if manifest is None:
                    return time.monotonic() - started, False
                floor = publisher_book_floor_v1(manifest) if manifest else None
                if floor is not None and (
                    floor
                    + timedelta(seconds=float(lease_seconds))
                    - datetime.now(timezone.utc)
                ).total_seconds() > QUOTE_EVIDENCE_REFRESH_SECONDS:
                    return time.monotonic() - started, True
            waited = time.monotonic() - started
            if waited >= float(budget_seconds):
                return waited, False
            time.sleep(
                min(QUOTE_PUBLISHER_POLL_SECONDS, float(budget_seconds) - waited)
            )

    def _refresh_scope_day_evidence(
        self,
        activation: Mapping[str, Any],
        *,
        event_date: str,
        as_of_utc: str,
        stations: Collection[str] | None = None,
    ) -> dict[str, Any]:
        """Re-read one event day's books and restate its evidence.

        The publisher rewrites the scope catalog every couple of seconds, so
        this is a bounded file read and the same validation path the cycle's
        first pass took -- no quote is fetched, recomputed or reinterpreted.
        It exists because the compile loop outlives the quote lease.

        ``stations`` restates only those stations of the day (the decision
        loop's reach, ``quote_refresh_reach_v1``); None restates them all.
        ``day_scope_manifest_count`` says how many the whole day had, so a
        caller can tell a day with nothing to restate from a subset that
        has nothing.
        """

        catalog = self._resident_ws_scope_catalog()
        day_items = [
            item
            for item in catalog
            if str(item.get("event_date") or "") == str(event_date)
            and isinstance(item.get("manifest"), Mapping)
            and item.get("probability_evidence_fresh") is True
            and not item.get("scope_blocker")
        ]
        wanted = (
            None if stations is None
            else {str(station).strip().upper() for station in stations}
        )
        day_scopes = [
            item["manifest"]
            for item in day_items
            if wanted is None
            or str(
                item.get("station_id")
                or _scope_manifest_station_day(item["manifest"])[0]
                or ""
            ).strip().upper() in wanted
        ]
        if not day_scopes:
            return {
                "event_date": str(event_date),
                "state": "no_scope_manifest",
                "day_scope_manifest_count": len(day_items),
            }
        # One pass per day state, each under the registry view its own state
        # and listing authorization admit -- the rule the cycle's first pass
        # uses; see _admitted_evidence_groups.  The refreshed snapshot the
        # caller is waiting for belongs to the scopes that can still trade,
        # so the open group's result is the one returned -- but a
        # not-started group present in the same day still gets its evidence
        # written rather than skipped, and one group's contract failure does
        # not take the other group's refresh with it.
        #
        # Full, never evidence-cache-only: the point of the refresh is the
        # snapshot the compile reads, and a cache-only pass returns before
        # writing it and would leave the loop compiling against the stamp it
        # was already failing on.
        # The listing keys only decide what happens to a ``not_started``
        # group (``_admitted_evidence_groups``), and reading them re-runs
        # ``_decision_scopes`` over the fleet: 2 s a refresh, 46 s of 105 on
        # 2026-10-03 15:35Z, where every refresh was of an open day.  Read
        # only when the manifests restated hold such a group -- and only for
        # the scopes in it: admission asks each manifest's own key and
        # nothing else, and the fleet's took 2.8 s a refresh under load on
        # 2026-10-04 05:15Z, 54 refreshes of the not-started 2026-10-05.
        not_started = [
            _scope_manifest_station_day(item)
            for state, group in _group_scope_manifests_by_day_state(day_scopes)
            if state == "not_started"
            for item in group
        ]
        listing_stations = {station for station, _day in not_started if station}
        listing_days = {day for _station, day in not_started}
        outcomes, refused = self._materialize_evidence_groups(
            activation,
            manifests=day_scopes,
            listing_scope_keys=(
                self._listing_entry_scope_keys(
                    as_of_utc=as_of_utc,
                    event_date=(
                        next(iter(listing_days)) if len(listing_days) == 1 else None
                    ),
                    station_ids=listing_stations or None,
                )
                if not_started
                else frozenset()
            ),
            full_materialization=True,
        )
        succeeded = [item for item in outcomes if "error" not in item]
        if not succeeded:
            if outcomes:
                raise outcomes[0]["error"]
            return {
                "event_date": str(event_date),
                "state": "no_admitted_scope",
                "refused_scope_count": len(refused),
                "refused_scopes": refused[:10],
            }
        result = dict(succeeded[0]["ingress"])
        result["day_scope_manifest_count"] = len(day_items)
        failed = [item for item in outcomes if "error" in item]
        if failed:
            result["evidence_group_failures"] = [
                self._evidence_group_summary(item) for item in failed
            ]
        return result

    def _listing_entry_scope_keys(
        self,
        *,
        as_of_utc: str,
        event_date: str | None = None,
        station_ids: Collection[str] | None = None,
    ) -> frozenset[str]:
        """Charter 48 listing scopes as ``STATION|DATE`` keys."""

        return frozenset(
            f"{str(station).upper()}|{day}"
            for station, day in self._listing_entry_scopes(
                as_of_utc=as_of_utc,
                station_allowlist=(
                    frozenset(str(item).upper() for item in station_ids)
                    if station_ids is not None
                    else None
                ),
                event_date=event_date,
            )
        )

    def _materialize_evidence_groups(
        self,
        activation: Mapping[str, Any],
        *,
        manifests: Sequence[Mapping[str, Any]],
        listing_scope_keys: Collection[str],
        full_materialization: bool,
        skip: Collection[tuple[str, str]] = (),
    ) -> "tuple[list[dict[str, Any]], list[str]]":
        """Materialize one event day group by group, each under its own view.

        A group that fails its evidence contract -- no registry scope, no
        book, nothing materialized -- fails as that group: the error is kept
        on its outcome, unraised, and the next group is still passed.  Which
        groups a cycle depends on, and what to do when those fail, is the
        caller's decision; this function only refuses to let one group's
        refusal stand in for another's.  Anything that is not a contract
        failure (a locked database, a memory ceiling) is not a property of
        the group and still propagates.

        ``skip`` names ``(event_date, day_state)`` groups already passed this
        cycle.
        """

        passes, refused = _admitted_evidence_groups(
            manifests, listing_scope_keys=listing_scope_keys
        )
        skipped = {(str(day), str(state)) for day, state in skip}
        outcomes: list[dict[str, Any]] = []
        for day_state, listing_pass, group in passes:
            scopes = sorted({
                scope
                for scope in (_scope_manifest_station_day(item) for item in group)
                if scope[0] and scope[1]
            })
            event_date = scopes[0][1] if scopes else str(
                group[0].get("event_date") or ""
            )
            if (event_date, day_state) in skipped:
                continue
            outcome: dict[str, Any] = {
                "event_date": event_date,
                "day_state": day_state,
                "listing_day_pass": listing_pass,
                "scopes": scopes,
            }
            try:
                with self._temporary_scope_manifest(
                    _merge_scope_manifests(group)
                ) as group_manifest_path:
                    outcome["ingress"] = (
                        self._materialize_market_evidence_from_manifest(
                            activation,
                            manifest_path=group_manifest_path,
                            full_materialization=full_materialization,
                            listing_day_pass=listing_pass,
                        )
                    )
            except ContractError as exc:
                setattr(exc, EVIDENCE_GROUP_SCOPES_ATTR, frozenset(scopes))
                outcome["error"] = exc
            outcomes.append(outcome)
        return outcomes, refused

    def _materialize_cycle_market_evidence(
        self,
        activation: Mapping[str, Any],
        *,
        sweep_scopes: Sequence[Mapping[str, Any]],
        selected_scope: Mapping[str, Any],
    ) -> dict[str, Any]:
        """The cycle's evidence: the selected scope's date, then listed days.

        The main pass serves every scope of the selected scope's event date,
        not that scope alone -- see the sweep -- and around midnight that
        date is open at some stations and not started at others, so it is
        one pass per day-state group, each under the view
        ``_admitted_evidence_groups`` gives it.  The selected scope may be a
        listed one: charter 85 leads the rotation with any scope holding a
        position, whatever its day.

        The cycle depends on the group holding the selected scope.  If that
        group refuses, the cycle falls back to another group that did not,
        then to a listed day's pass, and writes the lead's blocker against
        the lead's own open scopes.  Only when every group refused is the
        cycle failed, and only after the listed days have been passed --
        with the exception confined to the groups that raised it.

        Returns ``market_ingress`` (the receipt the compile reads),
        ``materialized_at`` per day, ``serve_listing``, ``listing_stations``,
        ``lead_listing_scopes`` and ``error`` (to raise, or None).
        """

        current_day = str(selected_scope.get("event_date") or "")
        selected_key = (
            str(selected_scope.get("station_id") or "").upper(),
            current_day,
        )
        materialized_at: dict[str, float] = {}
        # One admission set for both passes.  Read here rather than before
        # selection: a scope that crossed its midnight since then is open now
        # and must not borrow the listed view.
        listing_scope_keys = self._listing_entry_scope_keys(
            as_of_utc=utc_now()
        )
        current_outcomes, current_refused = self._materialize_evidence_groups(
            activation,
            manifests=[
                item for item in sweep_scopes
                if str(item.get("event_date") or "") == current_day
            ],
            listing_scope_keys=listing_scope_keys,
            full_materialization=bool(
                selected_scope["probability_evidence_fresh"]
            ),
        )
        lead = next(
            (item for item in current_outcomes if selected_key in item["scopes"]),
            None,
        ) or next(
            (
                item for item in current_outcomes
                if item["day_state"]
                == str(selected_scope.get("event_day_state") or "")
            ),
            None,
        )
        current_ok = [item for item in current_outcomes if "error" not in item]
        if current_ok:
            materialized_at[current_day] = time.monotonic()

        # Charter 48, one day at a time.  _merge_scope_manifests refuses to
        # fuse across event days because everything downstream reads a single
        # event_date off the merged document, so a listed day gets its own
        # merged manifests and its own passes, and its evidence lands in the
        # same cache the current day's does.  Never fatal.
        #
        # One cycle serves the current day, the next serves the listed days.
        # Restoring charter 48 roughly doubled the scopes a cycle carries --
        # 45 to between 82 and 90 -- and the cycle went from 462 seconds to
        # over 2,800 without completing, which stopped P0 for three hours.
        # Halving is enough because the two days are not equally urgent: a
        # listed day is entered on a window measured in days.
        #
        # A listed day is a (station, day) whose local day has not started --
        # not a date other than the fleet's current one -- so the current
        # date's own not-started group is a listed day too; the groups the
        # main pass already passed are skipped rather than restated.
        serve_listing = self._take_listing_scope_turn()
        listing_days = sorted({
            key.split("|", 1)[1] for key in listing_scope_keys if "|" in key
        })
        passed = {
            (item["event_date"], item["day_state"]) for item in current_outcomes
        }
        listing_evidence: list[dict[str, Any]] = []
        listing_outcomes: list[dict[str, Any]] = []
        for listing_day in (listing_days if serve_listing else ()):
            day_scopes = [
                item for item in sweep_scopes
                if str(item.get("event_date") or "") == listing_day
            ]
            if not day_scopes:
                listing_evidence.append({
                    "event_date": listing_day,
                    "state": "no_scope_manifest",
                })
                continue
            try:
                outcomes, _refused = self._materialize_evidence_groups(
                    activation,
                    manifests=day_scopes,
                    listing_scope_keys=listing_scope_keys,
                    # Full, not evidence-cache-only.  The compile reads
                    # basket_official_ws_snapshot and a cache-only pass
                    # returns before writing it, so a listed day got fresh
                    # evidence and a snapshot left over from its last full
                    # pass -- measured 47 seconds behind the current day's,
                    # against a 60-second lease.
                    full_materialization=True,
                    skip=passed,
                )
            except Exception as exc:  # noqa: BLE001 -- observational
                listing_evidence.append({
                    "event_date": listing_day,
                    "state": "blocked_fail_closed",
                    "reason": f"{type(exc).__name__}:{exc}"[:200],
                })
                continue
            for item in outcomes:
                if "error" in item:
                    listing_evidence.append({
                        "event_date": listing_day,
                        "day_state": item["day_state"],
                        "state": "blocked_fail_closed",
                        "reason": (
                            f"{type(item['error']).__name__}:{item['error']}"
                        )[:200],
                    })
                else:
                    listing_evidence.append(item["ingress"])
            if any("error" not in item for item in outcomes):
                materialized_at[listing_day] = time.monotonic()
            listing_outcomes.extend(outcomes)

        listing_ok = [item for item in listing_outcomes if "error" not in item]
        source = (
            lead if lead is not None and "error" not in lead
            else (current_ok[0] if current_ok else None)
        ) or (listing_ok[0] if listing_ok else None)
        groups_receipt = [
            self._evidence_group_summary(item) for item in current_outcomes
        ]
        error: BaseException | None = None
        if source is None:
            failed = [item for item in current_outcomes if "error" in item]
            error = (
                lead["error"] if lead is not None and "error" in lead
                else (
                    failed[0]["error"] if failed
                    else ContractError("resident_target_ws_sweep_manifest_empty")
                )
            )
            setattr(error, EVIDENCE_GROUP_SCOPES_ATTR, frozenset(
                scope for item in failed for scope in item["scopes"]
            ))
            market_ingress: dict[str, Any] = {
                "state": "blocked_fail_closed",
                "reason": f"{type(error).__name__}:{error}",
                "event_date": current_day,
                "writes_target_ssot": False,
            }
        else:
            market_ingress = source["ingress"]
            if lead is not None and "error" in lead and lead["day_state"] == "open":
                # The lead's scopes would have been this cycle's compile.
                # They are not compiled now, so the ledger records why --
                # their own blocker, not the fallback's absence of one.
                lead_reason = f"{type(lead['error']).__name__}:{lead['error']}"
                receipts = self._commit_blocked_scopes(
                    scopes=list(lead["scopes"]),
                    reason_codes=self._blocker_reason_codes(lead_reason),
                    details={
                        "blocked_scope_decision_version": 1,
                        "exception_type": type(lead["error"]).__name__,
                        "exception_reason": str(lead["error"]),
                        "evidence_group_day_state": lead["day_state"],
                        "no_market_snapshot_written": True,
                        "no_intents_written": True,
                        "no_capital_reserved": True,
                        "no_orders_submitted": True,
                        "execution_mode": PRODUCTION_EXECUTION_MODE,
                    },
                    created_at_utc=utc_now(),
                )
                if isinstance(market_ingress, dict):
                    market_ingress["evidence_group_blocked_decisions"] = (
                        self._blocked_receipt_summary(receipts)
                    )
        if isinstance(market_ingress, dict):
            market_ingress["evidence_groups"] = groups_receipt
            if current_refused:
                market_ingress["evidence_group_refused_scopes"] = (
                    current_refused[:10]
                )
            if listing_evidence:
                market_ingress["listing_day_evidence"] = listing_evidence
        materialized_listing = [
            item for item in (*current_ok, *listing_ok)
            if item["listing_day_pass"]
        ]
        return {
            "market_ingress": market_ingress,
            "materialized_at": materialized_at,
            "serve_listing": serve_listing,
            "listing_stations": {
                station
                for item in materialized_listing
                for station, _day in item["scopes"]
            },
            "lead_listing_scopes": (
                set(source["scopes"])
                if source is not None and source["listing_day_pass"]
                else set()
            ),
            "error": error,
        }

    @staticmethod
    def _evidence_group_summary(outcome: Mapping[str, Any]) -> dict[str, Any]:
        """One evidence group's receipt line, without its ingress payload."""

        error = outcome.get("error")
        ingress = outcome.get("ingress")
        return {
            "event_date": str(outcome.get("event_date") or ""),
            "day_state": str(outcome.get("day_state") or ""),
            "listing_day_pass": bool(outcome.get("listing_day_pass")),
            "station_count": len(outcome.get("scopes") or ()),
            "state": (
                "blocked_fail_closed"
                if error is not None
                else str((ingress or {}).get("state") or "")
            ),
            "reason": (
                f"{type(error).__name__}:{error}"[:200]
                if error is not None
                else str((ingress or {}).get("reason") or "")[:200]
            ),
        }

    def _materialize_market_evidence(self, activation: Mapping[str, Any]) -> dict[str, Any]:
        return self._materialize_market_evidence_from_manifest(
            activation,
            manifest_path=self.market_manifest_path,
        )

    def _materialize_market_evidence_from_manifest(
        self,
        activation: Mapping[str, Any],
        *,
        manifest_path: Path,
        full_materialization: bool = True,
        listing_day_pass: bool = False,
    ) -> dict[str, Any]:
        if self.commit_conn is None:
            return {
                "state": "not_attempted",
                "reason": "target_atomic_writer_not_injected",
                "writes_target_ssot": False,
            }
        _manifest_read_started = time.perf_counter()
        remaining_budget = _resolve_target_remaining_budget()
        manifest_path = Path(manifest_path).expanduser().resolve()
        manifest_root, _manifest_quotes = load_official_ws_quotes(
            manifest_path
        )
        station_allowlist = _manifest_station_allowlist(manifest_root)
        # The pass's own head, before either sub-pass.  The market-ingress
        # window measured 472.1s on 2026-09-09 while the two spans inside it
        # -- cache and snapshot -- accounted for 100.7s, so the rest was
        # attributed to nothing.  Name the head and the whole pass, and what
        # is left over is the call site's, not this function's.
        self._add_span(
            "market_evidence_manifest_read",
            (time.perf_counter() - _manifest_read_started) * 1000.0,
            label=f"{len(station_allowlist)} stations",
        )
        manifest_event_date = (
            str(manifest_root.get("target_local_date") or "").strip()
            if station_allowlist
            else ""
        )
        if station_allowlist and not manifest_event_date:
            raise RuntimeError("target_market_manifest_event_date_missing")
        # One station's missing quotes are that station's problem.  This was
        # a list comprehension, so the first ``ContractError`` aborted the
        # whole pass: the stations after it never had their evidence
        # materialized at all, and the cycle-level decision written for every
        # one of the 45 carried the failing station's reason.  Measured
        # 2026-08-20..22: 923 of 942 ``official_ws_evidence_complete_scope_missing``
        # blockages were a *different* station's gap, most of them CYYZ's
        # five unsubscribed buckets.  The remedy for a station with no book
        # is to skip that station, which is what the per-scope contract
        # already says; hoisting it to the fleet was the defect.
        evidence_cache_failures: list[dict[str, str]] = []
        if station_allowlist:
            evidence_cache_receipts = []
            # One manifest, one event day -- _merge_scope_manifests refuses
            # to fuse across days on purpose, because everything downstream
            # reads a single event_date off the merged document.  A listed
            # day therefore gets its own merged manifest and its own pass at
            # the call site; this function stays single-day, as its contract
            # has always been.
            evidence_scopes = [
                (station_id, manifest_event_date)
                for station_id in station_allowlist
            ]
            current_day_materialized = 0
            _evidence_cache_started = time.perf_counter()
            for station_id, scope_event_date in evidence_scopes:
                try:
                    evidence_cache_receipts.append(
                        materialize_official_ws_evidence_cache(
                            self.commit_conn,
                            manifest_path=manifest_path,
                            station_id=station_id,
                            event_date=scope_event_date,
                            commit=True,
                            include_listing_days=listing_day_pass,
                        )
                    )
                    if scope_event_date == manifest_event_date:
                        current_day_materialized += 1
                except ContractError as exc:
                    evidence_cache_failures.append({
                        "station_id": station_id,
                        "event_date": scope_event_date,
                        "reason": f"{type(exc).__name__}:{exc}",
                    })
            self._add_span(
                "market_evidence_cache_pass",
                (time.perf_counter() - _evidence_cache_started) * 1000.0,
                label=f"{len(evidence_scopes)} stations",
            )
            # Counted in the loop, not inferred from the receipt: the
            # receipt does not have to carry an event_date, and reading one
            # off it turned every cycle fatal the moment listing scopes were
            # added -- 51 scopes materialized and the filter still saw none.
            if not current_day_materialized:
                # Nothing was materialized for any station, so there is no
                # partial pass to keep -- fail the way the single-scope
                # contract does, naming what was skipped.
                #
                # For every group, including one whose day has not begun.
                # This used to take ``optional_pass`` and return quietly for
                # such a group, on the belief that a day before its first
                # midnight has no registry scope to materialize (2026-09-01).
                # It has one: the group was reading the started-day registry
                # because its caller never passed ``listing_day_pass``.  A
                # listed group admitted under its own view that still
                # materializes nothing is a real gap, and the caller confines
                # it to that group (``_materialize_evidence_groups``).
                raise ContractError(
                    "official_ws_evidence_complete_scope_missing:"
                    + str(len(evidence_cache_failures))
                    + " skipped:"
                    + "; ".join(
                        f"{row['station_id']}:{row['reason']}"
                        for row in evidence_cache_failures[:5]
                    )
                )
        else:
            evidence_cache_receipts = [
                materialize_official_ws_evidence_cache(
                    self.commit_conn,
                    manifest_path=manifest_path,
                    commit=True,
                )
            ]
        evidence_cache = {
            "state": (
                "committed" if not evidence_cache_failures
                else "committed_with_skipped_scopes"
            ),
            "skipped_scope_count": len(evidence_cache_failures),
            "skipped_scopes": evidence_cache_failures[:10],
            "station_allowlist": list(station_allowlist),
            "receipts": evidence_cache_receipts,
        }
        if not full_materialization:
            return {
                "state": "evidence_cache_only",
                "writes_target_ssot": True,
                "full_materialization": False,
                "station_allowlist": list(station_allowlist),
                "event_date": manifest_event_date,
                "evidence_cache": evidence_cache,
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
        # Per station, for the same reason the evidence cache above is per
        # station: one station's missing book is that station's problem, and
        # hoisting it to the fleet is what stops the day being written at all.
        # That fix was made for the cache and not for the snapshot, and the
        # snapshot is the row the compile actually reads -- so a single
        # station raising here left every other station of the day on
        # whatever generation it last had, and the mid-loop refresh, which
        # calls straight back into this function, could never renew anything.
        # Measured 2026-09-01: one refresh attempt, recorded ineffective, the
        # day's refresh disabled behind it, and ten scopes on
        # production_quote_expired with books minutes past their lease.
        snapshot_failures: list[dict[str, str]] = []
        first_snapshot_error: ContractError | None = None
        try:
            if station_allowlist:
                resident_receipts = []
                _snapshot_started = time.perf_counter()
                for station_id in station_allowlist:
                    try:
                        resident_receipts.append(
                            materialize_resident_no_live_market_evidence(
                                self.commit_conn,
                                manifest_path=manifest_path,
                                activation_path=self.activation_path,
                                remaining_budget_usdc=remaining_budget,
                                policy_authority_scope=str(
                                    activation["policy_authority_scope"]
                                ),
                                station_id=station_id,
                                event_date=manifest_event_date,
                                materialize_ws_cache=False,
                                include_listing_days=listing_day_pass,
                            )
                        )
                    except ContractError as exc:
                        if first_snapshot_error is None:
                            first_snapshot_error = exc
                        snapshot_failures.append({
                            "station_id": str(station_id),
                            "event_date": manifest_event_date,
                            "reason": f"{type(exc).__name__}:{exc}"[:200],
                        })
                self._add_span(
                    "market_evidence_snapshot_pass",
                    (time.perf_counter() - _snapshot_started) * 1000.0,
                    label=f"{len(station_allowlist)} stations",
                )
                if not resident_receipts and first_snapshot_error is not None:
                    # Nothing written for any station: there is no partial
                    # pass to keep, so fail exactly as the whole-fleet form
                    # did -- by raising the station's own error, unwrapped.
                    # The blocker recorded against the scope has to stay the
                    # real one; a synthetic "n stations skipped" heading in
                    # front of it is precisely the substitution this function
                    # already refuses to make one level down.  Who else was
                    # skipped is carried in the receipt below, where a count
                    # belongs.
                    raise first_snapshot_error
            else:
                resident_receipts = [
                    materialize_resident_no_live_market_evidence(
                        self.commit_conn,
                        manifest_path=manifest_path,
                        activation_path=self.activation_path,
                        remaining_budget_usdc=remaining_budget,
                        policy_authority_scope=str(activation["policy_authority_scope"]),
                        materialize_ws_cache=False,
                    )
                ]
            result = {
                "state": (
                    "committed" if not snapshot_failures
                    else "committed_with_skipped_scopes"
                ),
                "station_allowlist": list(station_allowlist),
                "skipped_scope_count": len(snapshot_failures),
                "skipped_scopes": snapshot_failures[:10],
                "receipts": resident_receipts,
            }
        except Exception as exc:
            return {
                "state": "blocked_fail_closed",
                "reason": f"{type(exc).__name__}:{exc}",
                "writes_target_ssot": True,
                # Preserve the already registry-verified scope even when a
                # downstream readiness gate (for example cash authority)
                # fails.  Dropping it here caused the outer worker to replace
                # the real blocker with target_market_station_allowlist_scope_required.
                "station_allowlist": list(station_allowlist),
                "event_date": manifest_event_date,
                "evidence_cache": evidence_cache,
                # Who else could not be written, beside the one whose error
                # this is.  The reason above stays the station's own; this
                # says how much of the day went with it.
                "skipped_scope_count": len(snapshot_failures),
                "skipped_scopes": snapshot_failures[:10],
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
        return {
            # The lane's own state stays "committed": callers branch on it and
            # a partial pass is still a pass that wrote.  What was skipped is
            # named here rather than folded into the word, because a count
            # dropped silently reads as full coverage -- and the nested
            # market_evidence receipt says "committed_with_skipped_scopes" for
            # a reader who wants it in one word.
            "state": "committed",
            "writes_target_ssot": True,
            "station_allowlist": list(station_allowlist),
            "event_date": manifest_event_date,
            "snapshot_skipped_scope_count": len(snapshot_failures),
            "snapshot_skipped_scopes": snapshot_failures[:10],
            "market_evidence": result,
            "evidence_cache": evidence_cache,
        }

    #: Charter 126.  How stale an evidence-only scope's last capture may be
    #: before this cycle takes another.  Not the decision cadence: a scope
    #: nobody may act on still has to leave a legible price series, and a
    #: 17KB book every cycle for every blocked scope is the SSOT growth this
    #: floor exists to avoid.  Ten minutes catches a repricing -- ZUUU
    #: 2026-09-09 moved 27C from 0.30 to 0.998 inside a 21.6-hour silence --
    #: at roughly a sixth of the rows an actionable scope writes.
    EVIDENCE_ONLY_CAPTURE_MIN_INTERVAL_SECONDS = float(
        os.environ.get(
            "PM_EVIDENCE_ONLY_CAPTURE_MIN_INTERVAL_SECONDS", ""
        ).strip() or 600.0
    )

    #: And how many of them one cycle takes.  The sweep's own cap is 180
    #: against a catalog of 127, so it cannot bind today -- this bound is
    #: what keeps that true if either number moves, and it spreads the extra
    #: writes over cycles instead of taking them in one burst.  Sixteen a
    #: cycle clears forty-odd stale scopes well inside the interval above.
    MAX_EVIDENCE_ONLY_SCOPES_PER_CYCLE = int(
        os.environ.get("PM_MAX_EVIDENCE_ONLY_SCOPES_PER_CYCLE", "").strip()
        or 16
    )

    def _evidence_only_capture_scopes(
        self,
        day_window_scopes: Sequence[Mapping[str, Any]],
        *,
        decidable: Sequence[Mapping[str, Any]],
    ) -> list[Mapping[str, Any]]:
        """Scopes this cycle may not act on but must still record.

        The interval is held in memory on purpose.  A restart resets it,
        which costs one extra capture per scope and never a missed one --
        the opposite direction from the rotation cursors, where a reset
        starves the tail, and the only direction that is safe for a rule
        whose whole point is that a missed quote cannot be refetched.
        """

        if self.EVIDENCE_ONLY_CAPTURE_MIN_INTERVAL_SECONDS <= 0.0:
            return []
        decidable_keys = {
            str(item.get("scope_key") or "") for item in decidable
        }
        captured = getattr(self, "_evidence_only_last_captured", None)
        if captured is None:
            captured = {}
            self._evidence_only_last_captured = captured
        elapsed_floor = float(
            self.EVIDENCE_ONLY_CAPTURE_MIN_INTERVAL_SECONDS
        )
        clock = time.monotonic()
        due: list[tuple[float, str, Mapping[str, Any]]] = []
        for item in day_window_scopes:
            key = str(item.get("scope_key") or "")
            if not key or key in decidable_keys:
                continue
            last = captured.get(key)
            if last is not None and (clock - float(last)) < elapsed_floor:
                continue
            # Never captured sorts first, then longest since.  A bound that
            # dropped the same tail every cycle would be the starvation this
            # whole change exists to remove.
            due.append((float(last) if last is not None else -1.0, key, item))
        due.sort(key=lambda row: (row[0], row[1]))
        return [
            item for _last, _key, item
            in due[: self.MAX_EVIDENCE_ONLY_SCOPES_PER_CYCLE]
        ]

    def _mark_evidence_only_captured(
        self,
        evidence_only: Sequence[Mapping[str, Any]],
        *,
        swept: Sequence[Mapping[str, Any]],
        as_of_utc: str,
    ) -> None:
        """Stamp only the evidence-only scopes the sweep actually carried.

        The sweep drops scopes of an unrelated event day and stops at its
        own cap, so a scope offered here and not taken must not be marked as
        captured -- that would push its next attempt out by the whole
        interval for a book that was never written.
        """

        del as_of_utc
        captured = getattr(self, "_evidence_only_last_captured", None)
        if captured is None:
            captured = {}
            self._evidence_only_last_captured = captured
        taken = {
            str(manifest.get("scope_key") or "")
            for manifest in swept
            if isinstance(manifest, Mapping)
        }
        clock = time.monotonic()
        for item in evidence_only:
            key = str(item.get("scope_key") or "")
            if key and key in taken:
                captured[key] = clock

    #: How many recent verdict changes one scope row keeps.  A ring, not a
    #: log: the table must answer "since when, and what stopped it" without
    #: growing with the cycle rate.
    WS_SCOPE_SERVING_TRANSITIONS_KEPT = 8

    def _record_ws_scope_serving_state(
        self,
        catalog: Sequence[Mapping[str, Any]],
        *,
        as_of_utc: str,
    ) -> dict[str, Any]:
        """Persist each scope's serving verdict, on change only.

        The actionable filter is silent by construction: a scope it drops
        simply is not swept, so no book is written and no decision row is
        raised, and the station looks identical to one nobody published.
        ``_ws_scope_catalog_summary`` names the drops, but only into
        status.json, which the next cycle overwrites -- so on 2026-09-09,
        when ZUUU|2026-09-09 went 21.6 hours without a book across the first
        13.2 hours of its own event day, the verdict that would have said
        why no longer existed anywhere.

        One row per (station, event_date), rewritten only when the verdict
        changes.  ``state_since_utc`` and ``last_actionable_at_utc`` are the
        answer to an outage; the ring beside them says what the last few
        changes were.  Never fatal: a diagnostic that can stop a decision
        cycle is worse than the blindness it removes.
        """

        if self.commit_conn is None or not catalog:
            return {"state": "not_attempted", "written": 0}
        rows = {}
        for item in catalog:
            station_id = str(item.get("station_id") or "")
            event_date = str(item.get("event_date") or "")
            if not station_id or not event_date:
                continue
            blocker = str(item.get("scope_blocker") or "")
            fresh = item.get("probability_evidence_fresh") is True
            rows[(station_id, event_date)] = {
                "event_day_state": str(item.get("event_day_state") or ""),
                "probability_stage": str(item.get("probability_stage") or ""),
                "probability_evidence_fresh": 1 if fresh else 0,
                "scope_blocker": blocker,
                "actionable": 1 if (fresh and not blocker) else 0,
            }
        if not rows:
            return {"state": "empty_catalog", "written": 0}
        written = 0
        unserved: list[dict[str, Any]] = []
        try:
            existing = {
                (str(row[0]), str(row[1])): row
                for row in self.commit_conn.execute(
                    "SELECT station_id,event_date,event_day_state,"
                    "probability_stage,probability_evidence_fresh,"
                    "scope_blocker,actionable,state_since_utc,"
                    "last_actionable_at_utc,transition_count,"
                    "recent_transitions_json"
                    " FROM basket_target_ws_scope_serving_state"
                )
            }
            changes: list[tuple] = []
            for (station_id, event_date), verdict in sorted(rows.items()):
                previous = existing.get((station_id, event_date))
                unchanged = previous is not None and (
                    str(previous[2]) == verdict["event_day_state"]
                    and str(previous[3]) == verdict["probability_stage"]
                    and int(previous[4]) == verdict[
                        "probability_evidence_fresh"
                    ]
                    and str(previous[5]) == verdict["scope_blocker"]
                    and int(previous[6]) == verdict["actionable"]
                )
                last_actionable = (
                    as_of_utc if verdict["actionable"]
                    else (str(previous[8]) if previous and previous[8] else None)
                )
                if unchanged:
                    if verdict["actionable"]:
                        # Only the "still being served" stamp moves, and it
                        # is the one field an outage is measured against.
                        changes.append((
                            station_id, event_date, verdict, previous,
                            as_of_utc, str(previous[7]), False,
                        ))
                    else:
                        unserved.append({
                            "scope_key": f"{station_id}|{event_date}",
                            "since": str(previous[7]),
                            "blocker": verdict["scope_blocker"]
                            or "resident_target_ws_probability_stale",
                        })
                    continue
                changes.append((
                    station_id, event_date, verdict, previous,
                    last_actionable, as_of_utc, True,
                ))
                if not verdict["actionable"]:
                    unserved.append({
                        "scope_key": f"{station_id}|{event_date}",
                        "since": as_of_utc,
                        "blocker": verdict["scope_blocker"]
                        or "resident_target_ws_probability_stale",
                    })
            if changes:
                with _writer_transaction(
                    self.commit_conn,
                    savepoint="ws_scope_serving_state",
                ):
                    for (
                        station_id, event_date, verdict, previous,
                        last_actionable, state_since, is_change,
                    ) in changes:
                        ring = []
                        if previous is not None and previous[10]:
                            try:
                                loaded = json.loads(str(previous[10]))
                                if isinstance(loaded, list):
                                    ring = [
                                        row for row in loaded
                                        if isinstance(row, Mapping)
                                    ]
                            except (TypeError, ValueError):
                                ring = []
                        if is_change:
                            ring.append({
                                "at": as_of_utc,
                                "actionable": bool(verdict["actionable"]),
                                "blocker": verdict["scope_blocker"],
                                "fresh": bool(
                                    verdict["probability_evidence_fresh"]
                                ),
                                "stage": verdict["probability_stage"],
                                "day_state": verdict["event_day_state"],
                            })
                            ring = ring[
                                -self.WS_SCOPE_SERVING_TRANSITIONS_KEPT:
                            ]
                        transition_count = (
                            (int(previous[9]) + 1)
                            if previous is not None and is_change
                            else (int(previous[9]) if previous is not None else 1)
                        )
                        payload = {
                            "station_id": station_id,
                            "event_date": event_date,
                            **verdict,
                            "state_since_utc": state_since,
                            "last_actionable_at_utc": last_actionable,
                            "transition_count": transition_count,
                            "recent_transitions_json": json.dumps(
                                ring, sort_keys=True, ensure_ascii=False
                            ),
                        }
                        self.commit_conn.execute(
                            "INSERT INTO basket_target_ws_scope_serving_state("
                            "station_id,event_date,event_day_state,"
                            "probability_stage,probability_evidence_fresh,"
                            "scope_blocker,actionable,state_since_utc,"
                            "last_actionable_at_utc,transition_count,"
                            "recent_transitions_json,updated_at,"
                            "content_sha256) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)"
                            " ON CONFLICT(station_id,event_date) DO UPDATE SET"
                            " event_day_state=excluded.event_day_state,"
                            " probability_stage=excluded.probability_stage,"
                            " probability_evidence_fresh="
                            "excluded.probability_evidence_fresh,"
                            " scope_blocker=excluded.scope_blocker,"
                            " actionable=excluded.actionable,"
                            " state_since_utc=excluded.state_since_utc,"
                            " last_actionable_at_utc="
                            "excluded.last_actionable_at_utc,"
                            " transition_count=excluded.transition_count,"
                            " recent_transitions_json="
                            "excluded.recent_transitions_json,"
                            " updated_at=excluded.updated_at,"
                            " content_sha256=excluded.content_sha256",
                            (
                                station_id,
                                event_date,
                                verdict["event_day_state"],
                                verdict["probability_stage"],
                                verdict["probability_evidence_fresh"],
                                verdict["scope_blocker"],
                                verdict["actionable"],
                                state_since,
                                last_actionable,
                                transition_count,
                                payload["recent_transitions_json"],
                                as_of_utc,
                                content_sha256(payload),
                            ),
                        )
                        written += 1
        except Exception as exc:  # noqa: BLE001
            # A cycle must not fail because its own bookkeeping failed.
            return {
                "state": "error",
                "reason": f"{type(exc).__name__}:{exc}"[:200],
                "written": written,
            }
        unserved.sort(key=lambda row: str(row["since"]))
        return {
            "state": "recorded",
            "scope_count": len(rows),
            "written": written,
            "unserved_scope_count": len(unserved),
            # Longest first: the one an operator should look at.
            "longest_unserved": unserved[:5],
        }

    @staticmethod
    def _ws_scope_catalog_summary(
        catalog: Sequence[Mapping[str, Any]],
    ) -> dict[str, Any]:
        """Name every scope the actionable filter drops, and why.

        The filter that selects actionable scopes is a silent one: a scope
        that fails it simply does not appear downstream, so a station whose
        probability expired is indistinguishable from one that was never
        published.  This is the only place those scopes are reported.
        """

        blocked: list[dict[str, str]] = []
        for item in catalog:
            fresh = item.get("probability_evidence_fresh") is True
            blocker = str(item.get("scope_blocker") or "")
            if fresh and not blocker:
                continue
            blocked.append({
                "scope_key": str(item.get("scope_key") or ""),
                "station_id": str(item.get("station_id") or ""),
                "event_date": str(item.get("event_date") or ""),
                "event_day_state": str(item.get("event_day_state") or ""),
                "probability_stage": str(item.get("probability_stage") or ""),
                "reason": (
                    blocker or "resident_target_ws_probability_stale"
                ),
            })
        return {
            "scope_count": len(catalog),
            "actionable_scope_count": len(catalog) - len(blocked),
            "blocked_scope_count": len(blocked),
            "blocked_scopes": sorted(
                blocked, key=lambda row: row["scope_key"]
            ),
        }

    def _resident_ws_scope_catalog(self) -> list[dict[str, Any]]:
        """Verify and expose each bounded resident WS scope in memory."""

        root = load_bounded_json(self.market_manifest_path)
        if not isinstance(root, Mapping):
            raise ContractError("resident_target_ws_manifest_mapping_required")
        if str(root.get("schema") or "") != MULTI_SCOPE_WS_MANIFEST_SCHEMA:
            # Legacy one-scope manifests remain readable during the cutover.
            manifest = dict(root)
            station_allowlist = _manifest_station_allowlist(manifest)
            event_date = str(
                manifest.get("target_local_date") or ""
            ).strip()
            if not station_allowlist or not event_date:
                raise ContractError(
                    "resident_target_ws_legacy_scope_invalid"
                )
            return [{
                "scope_key": f"{station_allowlist[0]}|{event_date}",
                "station_id": station_allowlist[0],
                "event_date": event_date,
                "event_day_state": "open",
                "probability_stage": "",
                "manifest": manifest,
            }]
        if (
            root.get("state") != "connected"
            or root.get("source")
            != "official_polymarket_clob_websocket"
            or root.get("evidence_only") is not True
            or root.get("authorizes_order") is not False
            or root.get("calls_order_gateway") is not False
            or root.get("live_submit_authorized") is not False
            or int(root.get("orders_submitted", -1)) != 0
            or not _manifest_content_sha_matches(root)
        ):
            raise ContractError(
                "resident_target_ws_multi_scope_boundary_invalid"
            )
        summaries = root.get("scopes")
        nested_by_scope = root.get("scope_manifests")
        if (
            not isinstance(summaries, list)
            or not isinstance(nested_by_scope, Mapping)
            or not 1 <= len(summaries) <= MAX_RESIDENT_WS_SCOPES
            or len(nested_by_scope) != len(summaries)
        ):
            raise ContractError(
                "resident_target_ws_multi_scope_cardinality_invalid"
            )
        catalog: list[dict[str, Any]] = []
        seen: set[str] = set()
        for summary in summaries:
            if not isinstance(summary, Mapping):
                raise ContractError(
                    "resident_target_ws_scope_summary_invalid"
                )
            scope_key = str(summary.get("scope_key") or "").strip()
            station_id = str(summary.get("station_id") or "").strip()
            event_date = str(summary.get("event_date") or "").strip()
            day_state = str(
                summary.get("event_day_state") or ""
            ).strip()
            stage = str(
                summary.get("probability_stage") or ""
            ).strip()
            probability_evidence_fresh = summary.get(
                "probability_evidence_fresh"
            )
            nested = nested_by_scope.get(scope_key)
            nested_stations = (
                _manifest_station_allowlist(nested)
                if isinstance(nested, Mapping)
                else ()
            )
            if (
                not scope_key
                or scope_key in seen
                or scope_key != f"{station_id}|{event_date}"
                or day_state not in {"open", "not_started"}
                or not isinstance(nested, Mapping)
                or nested.get("schema")
                != "clob_ws_latest_quote_snapshot_v1"
                or nested.get("state") != "connected"
                or nested.get("source")
                != "official_polymarket_clob_websocket"
                or nested.get("evidence_only") is not True
                or nested.get("authorizes_order") is not False
                or nested.get("calls_order_gateway") is not False
                or nested.get("live_submit_authorized") is not False
                or int(nested.get("orders_submitted", -1)) != 0
                or str(nested.get("scope_key") or "") != scope_key
                or str(nested.get("event_day_state") or "") != day_state
                or str(nested.get("target_local_date") or "")
                != event_date
                or nested_stations != (station_id,)
                or str(
                    (nested.get("probability_authority") or {}).get(
                        "stage"
                    )
                ) != stage
                or probability_evidence_fresh not in {True, False}
                or (
                    nested.get("probability_authority") or {}
                ).get("evidence_fresh") is not probability_evidence_fresh
                or str(summary.get("scope_manifest_sha256") or "")
                != str(nested.get("snapshot_sha256") or "")
                or not _manifest_content_sha_matches(nested)
            ):
                raise ContractError(
                    "resident_target_ws_scope_binding_invalid"
                )
            if day_state == "not_started" and stage not in {"P0", "P0-M", ""}:
                raise ContractError(
                    "resident_target_ws_future_stage_forbidden"
                )
            scope_blocker = ""
            if day_state == "not_started" and not stage:
                # A rootless listing-day scope: subscribed at listing (charter
                # 48) so its book records from the first quote, while no
                # probability claim exists yet to preselect from.  It must be
                # observational, not fatal -- treating it as a forbidden stage
                # killed this whole catalog on the first rootless scope, which
                # silenced every healthy scope's preselection and open-day
                # decision for as long as one unrooted listing existed.
                scope_blocker = "resident_target_ws_future_scope_rootless"
            elif day_state == "not_started" and probability_evidence_fresh is not True:
                # A stale future scope is observational only.  Keep it in the
                # catalog for auditability, but do not let one station-day
                # suppress healthy open scopes or create a future P0 action.
                scope_blocker = "resident_target_ws_future_probability_stale"
            if day_state == "open" and stage not in {"P0", "P0-M", "P1", ""}:
                raise ContractError(
                    "resident_target_ws_open_scope_probability_stage_invalid"
                )
            if day_state == "open" and not stage:
                # A rootless open scope: the market trades but no probability
                # root ever compiled for it (a listing-day subscription whose
                # station never landed a packet).  Same doctrine as the
                # rootless future scope above -- keep recording its book,
                # block decisions on it alone, never let it kill the catalog.
                scope_blocker = "resident_target_ws_open_scope_rootless"
            if (
                day_state == "open"
                and stage in {"P0", "P0-M"}
                and probability_evidence_fresh is not True
            ):
                # Keep the blocker attached to this station-day.  The worker
                # below excludes it from the actionable scope set while
                # allowing other fresh scopes to proceed independently.
                scope_blocker = (
                    "resident_target_ws_open_scope_pre_p1_probability_stale"
                )
            if (
                day_state == "open"
                and stage == "P1"
                and probability_evidence_fresh is not True
            ):
                # A stale open P1 is excluded by the freshness test either
                # way, but without a blocker it left no trace at all: it is
                # not a not-started scope, so it raises no preliminary
                # decision, and the actionable filter drops it silently.  A
                # station whose P1 expired then looks identical to one that
                # was never scanned.
                scope_blocker = (
                    "resident_target_ws_open_scope_p1_probability_stale"
                )
            seen.add(scope_key)
            catalog.append({
                "scope_key": scope_key,
                "station_id": station_id,
                "event_date": event_date,
                "event_day_state": day_state,
                "probability_stage": stage,
                "probability_evidence_fresh": probability_evidence_fresh,
                "scope_blocker": scope_blocker,
                "manifest": dict(nested),
            })
        return sorted(catalog, key=lambda item: item["scope_key"])

    @staticmethod
    def _ws_scope_manifest_age_sec(
        scope: Mapping[str, Any],
        *,
        now: datetime,
    ) -> float:
        """How old this scope's book is, by the clock the compile will use.

        ``compile_p0_preselection`` rejects a manifest whose
        ``connection_observed_at`` is further than the performance budget's
        ``max_ws_snapshot_age_sec`` from the evaluation instant.  Measuring
        the same quantity here is what lets the sweep re-read *before* that
        check can fail rather than discovering it forty scopes in.

        An unreadable or unclocked stamp returns infinity: re-read rather
        than compile against a manifest whose age cannot be established.
        """

        nested = scope.get("manifest")
        observed = ""
        if isinstance(nested, Mapping):
            observed = str(nested.get("connection_observed_at") or "")
        if not observed:
            return float("inf")
        try:
            parsed = datetime.fromisoformat(observed.replace("Z", "+00:00"))
        except ValueError:
            return float("inf")
        if parsed.tzinfo is None:
            return float("inf")
        return (now - parsed).total_seconds()

    @staticmethod
    def _forward_preselection_order(
        scope_keys: Sequence[str],
        *,
        resume_at: str,
        priority: Collection[str] = (),
    ) -> list[str]:
        """The catalog's own order, rotated to where the last pass stopped.

        Every scope still appears exactly once -- this moves where a pass
        begins, not what it covers.  It matters only when a pass does not
        reach the end: without it the survivors are always the same head of
        the alphabet, and the stations behind the truncation point are
        starved every cycle rather than served on the next one.

        ``priority`` (user ruling, 2026-09-05: the rotation serves the
        station-days that hold live positions first) is lifted to the head
        of the pass in its rotated order; the cursor still walks the whole
        list, so nothing behind it is starved for longer than before.
        """

        order = list(scope_keys)
        if resume_at in order:
            start = order.index(resume_at)
            order = order[start:] + order[:start]
        wanted = {str(key) for key in priority}
        if not wanted:
            return order
        return (
            [key for key in order if key in wanted]
            + [key for key in order if key not in wanted]
        )

    def _ledger_held_scope_keys(self) -> frozenset[str]:
        """The station-days the reconciliation ledger says the book holds.

        ``STATION|EVENT_DATE`` keys, the forward catalog's spelling: every
        scope with a settled live BUY not yet sold flat.  These are the
        scopes where money is already at risk, and the rotation serves them
        first (user ruling, 2026-09-05) -- a half-filled basket waiting
        behind forty flat scopes is the one place a truncated pass costs
        real money.  Empty when the ledger tables are absent or the read
        fails: the rotation then falls back to its own order.
        """

        conn = self.commit_conn if self.commit_conn is not None else self.conn
        try:
            rows = conn.execute(
                "SELECT c.station_id, c.event_date,"
                " SUM(CASE WHEN upper(i.order_action)='SELL'"
                "          THEN -r.filled_size ELSE r.filled_size END) AS net"
                " FROM basket_target_order_reconciliations r"
                " JOIN basket_target_order_intents i"
                "   ON i.order_intent_id=r.order_intent_id"
                " JOIN basket_target_execution_cycles c"
                "   ON c.cycle_id=i.cycle_id"
                " WHERE r.state IN ('resolved_filled','resolved_partial')"
                " GROUP BY c.station_id, c.event_date"
            ).fetchall()
        except sqlite3.Error:
            return frozenset()
        return frozenset(
            f"{str(station).strip().upper()}|{str(day).strip()}"
            for station, day, net in rows
            if float(net or 0.0) > 1e-9
        )

    @staticmethod
    def _forward_preselection_scope_skipped(scope: Any) -> bool:
        """Whether this scope has no forward preselection to make right now."""

        return (
            not isinstance(scope, Mapping)
            or scope.get("event_day_state") != "not_started"
            or not scope.get("probability_evidence_fresh")
            or bool(scope.get("scope_blocker"))
        )

    @staticmethod
    def _scope_input_fingerprint(scope: Mapping[str, Any]) -> tuple[str, str]:
        """What this scope's answer depends on: its probability and its book.

        Returned as a pair so the two can be compared separately -- a new
        envelope changes the answer, a moved book only may -- rather than as
        one hash that would make every quote tick look like new evidence.
        """

        nested = scope.get("manifest")
        if not isinstance(nested, Mapping):
            return ("", "")
        envelope_id = str(
            (nested.get("probability_authority") or {}).get("envelope_id")
            or ""
        )
        observed = ""
        quotes = nested.get("quotes_by_token")
        if isinstance(quotes, Mapping):
            observed = max(
                (
                    str(quote.get("book_observed_at") or "")
                    for quote in quotes.values()
                    if isinstance(quote, Mapping)
                ),
                default="",
            )
        return (envelope_id, observed)

    @staticmethod
    def _warm_window_weight(
        scope: Mapping[str, Any],
        *,
        as_of_utc: str,
    ) -> float:
        """How likely this station-day's high is still being set right now.

        Measured, not assumed: across 1022 observed station-days the daily
        high landed between 10:00 and 17:00 local 80% of the time, peaking at
        15:00 but only 17.6% there -- so the signal is the window, not a
        distance from any one hour.  Inside it an arriving observation can
        still change the answer and the weight is 1; outside it decays with
        hours from the nearest edge and reaches almost nothing overnight.

        An unreadable timezone weighs low rather than raising: the rotation
        orders work, and refusing to order one scope would hold up every
        scope behind it.
        """

        nested = scope.get("manifest")
        timezone_name = (
            str(nested.get("target_timezone") or "")
            if isinstance(nested, Mapping)
            else ""
        )
        if not timezone_name:
            return 0.05
        try:
            local = datetime.fromisoformat(
                str(as_of_utc).replace("Z", "+00:00")
            ).astimezone(ZoneInfo(timezone_name))
        except (ValueError, KeyError, ZoneInfoNotFoundError):
            return 0.05
        hour = local.hour + local.minute / 60.0
        # Not a flat window.  A plateau gave every station between 10:00 and
        # 17:00 the identical score, so thirty-one of them tied at 1.0 and
        # the ordering fell through to the tie-break, which is the scope key
        # -- the alphabet, again, with a station at 10:09 ahead of one at
        # 15:09.  The measured distribution is not flat either: of 1022
        # observed station-days the high landed at 15:00 seven times more
        # often than at 10:00, so the hour's own share of highs is the
        # weight, interpolated between the measured points and floored so a
        # quiet station still has a score for ageing to lift.
        share = _warm_hour_share(hour)
        return max(0.05, share / _WARM_HOUR_PEAK_SHARE)

    @classmethod
    def _scope_rotation_key(
        cls,
        scope: Mapping[str, Any],
        *,
        as_of_utc: str,
        last_served: Mapping[str, Any] | None,
        quota_usdc: float | None,
        held: bool = False,
    ) -> tuple[int, int, float, float, str]:
        """Order scopes by what recompiling one now is actually worth.

        ``held`` -- the station-day holds a live position in the
        reconciliation ledger -- leads everything (user ruling, 2026-09-05:
        the rotation serves the scopes with money at risk first).

        The rotation hands out scarce compute, and every serve costs a
        compile plus the SQLite writes behind it -- the store crossed its
        size ceiling once already today -- so the ordering is by expected
        value of the recompute, not by name.  It was the scope key, which is
        the ICAO code: on a live catalog all thirteen stations then inside
        their warm window sorted to positions 13-27 because Asia's codes
        begin with R, W and Z, while the small hours took positions 0-8.

        One ordering above the score, because it is not tradable against
        anything: the event day under way precedes the day not started.  A
        day being decided now cannot wait for one being planned.

        A market never compiled is not a tier -- see below -- it is maximal
        new evidence, which is what it actually is.

        Within a tier, the score multiplies what would be gained:

        - *new evidence*: a fresh probability envelope changes the answer, a
          moved book may, and neither means the recompute reproduces the plan
          it already has.  This is the term that matters most, because it is
          the one that makes the rotation skip stations with nothing to say.
        - *warm window*: whether the high is still being set locally.
        - *actionable capital*: a station the allocator funded can act on
          what it finds; one it could not fund to a whole basket cannot.

        Ties break to the longest unserved, which is also why the caller
        tracks serve times per station rather than advancing a cursor over
        positions -- the ordering is recomputed every cycle, so a positional
        cursor visits positions, not stations.
        """

        day_state = str(scope.get("event_day_state") or "")
        # The day being decided leads the day being planned; that is the only
        # ordering strong enough to override the score.  "Never compiled" is
        # deliberately *not* a tier of its own: at a cold start every scope
        # is unseen, so a tier would flatten them all and hand the ordering
        # straight back to the scope key -- the alphabetical behaviour this
        # replaced.  It enters the score instead, as maximal new evidence,
        # which is exactly what it is.
        tier = 0 if day_state == "open" else 1

        envelope_id, observed_at = cls._scope_input_fingerprint(scope)
        if last_served is None:
            evidence = 1.0
        elif envelope_id and envelope_id != str(
            last_served.get("envelope_id") or ""
        ):
            evidence = 1.0
        elif observed_at and observed_at > str(
            last_served.get("book_observed_at") or ""
        ):
            evidence = 0.5
        else:
            # Nothing moved.  Recompiling reproduces the same plan and pays
            # the full write cost for it; keep it possible, not preferred.
            evidence = 0.1

        actionable = (
            1.0
            if quota_usdc is None or float(quota_usdc) > 0.0
            else 0.2
        )
        # Ageing is multiplicative, and it is what makes "nobody starves" a
        # guarantee rather than a hope.  Breaking ties by serve time does
        # nothing here because the scores are continuous and almost never
        # equal: a station inside its warm window scored 0.1 against 0.027
        # for one at dawn, and simply kept winning.  Growing the score with
        # time waited means a quiet station rises until it is served -- in
        # roughly three hours at that ratio -- so a position there is still
        # revisited even on a day when nothing about it changes.
        waited_hours = 0.0
        served_at = str((last_served or {}).get("served_at_utc") or "")
        if served_at:
            try:
                waited_hours = max(
                    0.0,
                    (
                        datetime.fromisoformat(
                            str(as_of_utc).replace("Z", "+00:00")
                        )
                        - datetime.fromisoformat(
                            served_at.replace("Z", "+00:00")
                        )
                    ).total_seconds()
                    / 3600.0,
                )
            except ValueError:
                waited_hours = 0.0
        ageing = 1.0 + min(waited_hours, ROTATION_AGEING_CAP_HOURS)
        score = (
            evidence
            * cls._warm_window_weight(scope, as_of_utc=as_of_utc)
            * actionable
            * ageing
        )
        # Ascending sort: lower tier first, then higher score.  The scope key
        # only ever settles an exact tie, so the ordering stays deterministic
        # without the alphabet deciding anything that matters.
        return (
            0 if held else 1,
            tier,
            -score,
            0.0,
            str(scope.get("scope_key") or ""),
        )

    @staticmethod
    def _starved_event_dates(
        scopes: Sequence[Mapping[str, Any]],
        *,
        served: Mapping[str, Mapping[str, Any]],
        as_of_utc: str,
    ) -> set[str]:
        """Open event days whose last capture is older than the bound.

        A day never captured at all counts as starved from the moment it has
        a scope, which is the case this exists for: a day opens, its P1 stage
        starts speaking, and the ordering has no reason to prefer it because
        every one of its stations is at local midnight.
        """

        try:
            now = datetime.fromisoformat(str(as_of_utc).replace("Z", "+00:00"))
        except ValueError:
            return set()
        latest: dict[str, str] = {}
        present: set[str] = set()
        for scope in scopes:
            day = str(scope.get("event_date") or "")
            if not day or str(scope.get("event_day_state") or "") != "open":
                continue
            present.add(day)
            stamp = str(
                (served.get(str(scope.get("scope_key") or "")) or {})
                .get("served_at_utc") or ""
            )
            if stamp and stamp > latest.get(day, ""):
                latest[day] = stamp
        starved: set[str] = set()
        for day in present:
            stamp = latest.get(day)
            if not stamp:
                starved.add(day)
                continue
            try:
                served_at = datetime.fromisoformat(stamp.replace("Z", "+00:00"))
            except ValueError:
                starved.add(day)
                continue
            if (now - served_at).total_seconds() > EVENT_DAY_CAPTURE_BOUND_SEC:
                starved.add(day)
        return starved

    def _sweep_scope_manifests(
        self,
        open_scopes: Sequence[Mapping[str, Any]],
        *,
        selected: Mapping[str, Any],
        as_of_utc: str,
    ) -> list[Mapping[str, Any]]:
        """The scope manifests this cycle should ingest, best first.

        All of them, in the priority order, bounded only by the sweep cap.
        The cap is not a throughput choice -- 45 stations of inline books is
        a bounded document either way -- it is the same fail-closed habit as
        every other resource guard here: a catalog that somehow grew past the
        station-day ceiling should stop, not swell the write.

        Priority still decides, but now it decides who is ingested first
        within one cycle rather than who waits minutes for a turn.  The
        selected scope leads regardless, because the code downstream reads
        its stage and freshness to decide how much to materialize.
        """

        _sweep_started = time.perf_counter()
        ordered = [dict(selected)]
        seen = {str(selected.get("scope_key") or "")}
        quotas = (
            getattr(self, "_portfolio_allocation_last", None) or {}
        ).get("quota_usdc_by_station")
        served = getattr(self, "_resident_scope_served", None) or {}
        listing_days = {
            day
            for _station, day in self._listing_entry_scopes(as_of_utc=as_of_utc)
        }
        held_scopes = self._ledger_held_scope_keys()
        for scope in sorted(
            (dict(item) for item in open_scopes),
            key=lambda item: self._scope_rotation_key(
                item,
                as_of_utc=as_of_utc,
                last_served=served.get(str(item.get("scope_key") or "")),
                quota_usdc=(
                    quotas.get(str(item.get("station_id") or ""))
                    if isinstance(quotas, Mapping)
                    else None
                ),
                held=str(item.get("scope_key") or "") in held_scopes,
            ),
        ):
            key = str(scope.get("scope_key") or "")
            if key in seen:
                continue
            scope_day = str(scope.get("event_date") or "")
            if (
                scope_day != str(selected.get("event_date") or "")
                and scope_day not in listing_days
            ):
                # One event day per ingress -- the merged document carries a
                # single event_date and everything downstream reads it -- so
                # a scope from an unrelated day still waits for a cycle whose
                # selection lands on it.  A charter 48 listed day is not
                # unrelated: it is a day this book may already open on, and
                # the caller merges and materializes it in its own pass, so
                # its manifests have to survive the sweep to get there.
                continue
            seen.add(key)
            ordered.append(scope)
            if (
                sum(
                    1
                    for item in ordered
                    if str(item.get("event_date") or "")
                    == str(selected.get("event_date") or "")
                )
                >= MAX_FORWARD_P0_STATION_DAYS
            ):
                # The cap is a fail-closed ceiling on the current day's
                # write, which is what it was written for.  Counting listed
                # scopes against it would let tomorrow starve today.
                break
        # Re-read the books at ingest time, keeping the ordering above.
        # The catalog is captured early in the cycle to decide *which*
        # scopes to serve, and the stages between that capture and this
        # sweep cost minutes (the forward-P0 loop alone ran 90s on
        # 2026-08-20) while a quote's lease is sixty seconds.  Ingesting the
        # catalog's copies therefore wrote books that were already expired:
        # every one of that cycle's 172 evidence rows carried one shared
        # observation stamp 161s behind the compile clock, and 24 of 26
        # candidates died on ``production_quote_expired``.  The publisher
        # rewrites the manifest every couple of seconds, so a fresh read
        # costs one bounded file read and re-validates on the same path.
        # A scope that vanished or failed re-validation keeps the copy the
        # ordering was decided on rather than dropping out of the sweep.
        fresh_manifests: dict[str, Mapping[str, Any]] = {}
        try:
            for scope in self._resident_ws_scope_catalog():
                scope_key = str(scope.get("scope_key") or "")
                manifest = scope.get("manifest")
                if scope_key and isinstance(manifest, Mapping):
                    fresh_manifests[scope_key] = manifest
        except ContractError:
            fresh_manifests = {}
        swept = [
            fresh_manifests.get(
                str(item.get("scope_key") or ""), item["manifest"]
            )
            for item in ordered
            if isinstance(item.get("manifest"), Mapping)
        ]
        self._add_span(
            "sweep_scope_manifests",
            (time.perf_counter() - _sweep_started) * 1000.0,
            label=f"{len(swept)} scopes",
        )
        return swept

    def _select_resident_open_ws_scope(
        self,
        open_scopes: Sequence[Mapping[str, Any]],
        *,
        as_of_utc: str | None = None,
    ) -> dict[str, Any] | None:
        """Serve the station-day closest to deciding, without starving any.

        The rotation used to be the scope key's alphabetical order, which is
        the ICAO code, which has nothing to do with when a station-day is
        settled.  Measured on a live catalog it was actively perverse: every
        one of the thirteen stations then within three hours of its warmest
        hour sorted into positions 13-27, because they are the Asian codes and
        Asia begins with R, W and Z -- while positions 0-8 went to stations at
        one and two in the morning, thirteen hours from anything happening.

        The basket is a bet on the day's high, so information arrives while a
        station is warming and is nearly worthless before that.  Scopes are
        therefore ordered by how close local time is to the warm hours, and
        the cursor still advances through the whole ordering, so a station
        that is far from its peak is served later rather than never.
        """

        if not open_scopes:
            return None
        if len(open_scopes) > MAX_FORWARD_P0_STATION_DAYS:
            raise ContractError(
                "resident_target_ws_open_scope_station_day_cap_exceeded"
            )
        as_of = as_of_utc or utc_now()
        served = getattr(self, "_resident_scope_served", None)
        if served is None:
            served = {}
            self._resident_scope_served = served
        quotas = (
            getattr(self, "_portfolio_allocation_last", None) or {}
        ).get("quota_usdc_by_station")
        # One ingress serves one event day (the sweep filters to the selected
        # day), so a day that never wins the ordering is not merely served
        # late -- it is not captured at all.  That is what happened on
        # 2026-08-15: through the 16:00Z hour every one of the 136 captures
        # went to 08-15 and 08-16 got none, which is precisely the hour
        # 08-16's local day opens across Asia and its P1 stage first speaks.
        # The ordering was right to prefer 08-15 -- 08-16's stations were at
        # their own local midnight, the coldest point of the warm-window
        # curve -- but the P1 decisions landed in that hour regardless, and
        # with no book within thirty minutes of them, twelve stations
        # produced no basket for the whole day.
        #
        # So the guarantee is at the day level, where the starvation is, and
        # it only fires once a day has actually been starved.  Scoring is
        # untouched: on any cycle where no open day is overdue this picks
        # exactly what it picked before.
        candidates = [dict(item) for item in open_scopes]
        overdue = self._starved_event_dates(
            candidates, served=served, as_of_utc=as_of
        )
        # The starved scopes themselves, not every scope sharing their date.
        # A date is starved at the stations where it is open, and it is
        # relieved only by serving one of those: a listed scope of the same
        # date is not itself open, is never stamped against the date, and
        # outranks the open ones whenever it holds a position (charter 85).
        # Admitting it here let it take the guarantee every cycle.  Measured
        # 2026-09-13: NZWN opened 2026-09-14 at 12:00Z, which made the 14th a
        # starved open date; LFPB|2026-09-14, listed and held, then won every
        # selection, and 2026-09-13 -- the day under way at 44 stations --
        # wrote no book from 12:02Z on.
        eligible = [
            item for item in candidates
            if str(item.get("event_date") or "") in overdue
            and str(item.get("event_day_state") or "") == "open"
        ] or candidates
        held_scopes = self._ledger_held_scope_keys()
        selected = min(
            eligible,
            key=lambda item: self._scope_rotation_key(
                item,
                as_of_utc=as_of,
                last_served=served.get(str(item.get("scope_key") or "")),
                quota_usdc=(
                    quotas.get(str(item.get("station_id") or ""))
                    if isinstance(quotas, Mapping)
                    else None
                ),
                held=str(item.get("scope_key") or "") in held_scopes,
            ),
        )
        envelope_id, observed_at = self._scope_input_fingerprint(selected)
        # Recorded per scope, not as a position: the ordering is rebuilt from
        # current time and current evidence every cycle, so a positional
        # cursor would march through positions while the stations under them
        # changed.  Remembering what each scope was last served with is what
        # makes "nothing moved since" answerable at all.
        served[str(selected.get("scope_key") or "")] = {
            "served_at_utc": as_of,
            "envelope_id": envelope_id,
            "book_observed_at": observed_at,
        }
        if len(served) > MAX_FORWARD_P0_STATION_DAYS * 2:
            for key in sorted(
                served, key=lambda k: str(served[k].get("served_at_utc") or "")
            )[: len(served) - MAX_FORWARD_P0_STATION_DAYS]:
                served.pop(key, None)
        return selected

    @contextmanager
    def _temporary_scope_manifest(
        self,
        value: Mapping[str, Any],
    ) -> Iterator[Path]:
        """Bridge one verified in-memory scope to existing path consumers."""

        assert_process_memory_budget()
        with tempfile.TemporaryDirectory(
            prefix="bayes-target-ws-scope-",
        ) as temporary_root:
            path = Path(temporary_root) / "manifest.json"
            _write_started = time.perf_counter()
            write_bounded_json(path, dict(value))
            # A merged day of inline books, copied to disk once per pass and
            # read back once per station by each sub-pass.  Named for the
            # same reason the pass head is: the market-ingress window's
            # 472.1s on 2026-09-09 was 100.7s of measured sub-passes and
            # 371.4s of nothing in particular.
            self._add_span(
                "scope_manifest_write",
                (time.perf_counter() - _write_started) * 1000.0,
                label=str(value.get("target_local_date") or ""),
            )
            try:
                yield path
            finally:
                # TemporaryDirectory removes the only duplicate immediately;
                # no quote history or failed fragment is retained.
                assert_process_memory_budget()

    def _materialize_resident_p1(
        self,
        *,
        as_of_utc: str,
        freshness_seconds: int = 3600,
        stage_clock_utc: str | None = None,
        only_scopes: "set[tuple[str, str]] | None" = None,
    ) -> dict[str, Any]:
        """Append resident official new-high P1 through the unique compiler.

        ``stage_clock_utc`` is the latest decision the stages below this one
        stamped in the same cycle.  Observations stay strictly as of
        ``as_of_utc`` -- their truth revisions were identified against that
        clock -- but the root this compile builds on is read as of the stage
        clock, so a P0-M rebuilt one millisecond after a root minted at the
        cycle clock (``_p0m_replay_decision_at``) is the root P1 takes, not a
        cycle later after a detour through the bare P0.
        """

        envelope_as_of_utc = as_of_utc
        if stage_clock_utc and timestamp_lt(as_of_utc, stage_clock_utc):
            envelope_as_of_utc = str(stage_clock_utc)

        if self.canonical_source_conn is None:
            return {
                "state": "not_configured",
                "reason": self.canonical_source_error
                or "resident_canonical_source_not_configured",
                "writes_target_ssot": False,
            }
        if self.commit_conn is None:
            return {
                "state": "not_attempted",
                "reason": "target_atomic_writer_not_injected",
                "writes_target_ssot": False,
            }
        assert_process_memory_budget()
        # Clear the path before compiling: an unreviewed correction in the
        # live window WILL halt its station-day below, and the standing
        # policy that lifts it costs about a second.  Detect-and-clear here
        # makes the halt last one compile instead of one scheduler cycle.
        with self._span("p1_correction_preclear"):
            correction_preclear = self._preclear_pending_corrections(
                as_of_utc=as_of_utc,
            )
        with self._span("p1_started_registry_rows"):
            rows = load_started_registry_rows(
                self.commit_conn,
                as_of_utc=as_of_utc,
            )
        # Which started scopes hold a committed P0/P0-M/P1 by this clock.
        # Asked pair by pair on the (station, day, state, decision) index:
        # the DISTINCT over the whole table this replaces read ~484k rows,
        # 4.2s, on every P1 pass -- head, chain and fast-lane checkpoint
        # alike (2026-09-19).  Only membership was ever read from it.
        probability_scopes: set[tuple[str, str]] = set()
        for row in rows:
            pair = (
                str(row.get("station_id") or "").strip().upper(),
                str(row.get("event_date") or "").strip(),
            )
            if not pair[0] or not pair[1] or pair in probability_scopes:
                continue
            if self.commit_conn.execute(
                "SELECT 1 FROM basket_probability_envelope "
                "WHERE station_id=? AND event_date=? AND state='COMMITTED' "
                "AND decision_at_utc<=? AND stage IN ('P0','P0-M','P1') LIMIT 1",
                (pair[0], pair[1], as_of_utc),
            ).fetchone():
                probability_scopes.add(pair)
        grouped: dict[tuple[str, str], list[dict[str, Any]]] = {}
        for row in rows:
            station = str(
                row.get("station_id") or ""
            ).strip().upper()
            day = str(row.get("event_date") or "").strip()
            timezone_name = str(
                row.get("settlement_timezone") or ""
            ).strip()
            if (
                station
                and day
                and timezone_name
                and (station, day) in probability_scopes
                and self._event_day_open(
                    day,
                    settlement_timezone=timezone_name,
                    as_of_utc=as_of_utc,
                )
            ):
                grouped.setdefault((station, day), []).append(dict(row))
        # Charter 148: the chain's second pass, in a cycle whose head already
        # ran P1 over every scope, is only for the scopes this cycle rebuilt
        # a root for.
        if only_scopes is not None:
            wanted = {
                (str(station).strip().upper(), str(day).strip())
                for station, day in only_scopes
            }
            grouped = {
                key: value for key, value in grouped.items() if key in wanted
            }
        # Keyed by (station, day), so this counts station-days.  Capping it at
        # the station count made the whole P1 pass fail the moment a second
        # event day was open.
        if len(grouped) > MAX_FORWARD_P0_STATION_DAYS:
            raise RuntimeError("resident_p1_station_day_scope_cap_exceeded")
        receipts: list[dict[str, Any]] = []
        blockers: list[dict[str, str]] = []
        for (station, day), registry_rows in sorted(grouped.items()):
            try:
                scope_label = f"{station}|{day}"
                with self._span("p1_source_lane", label=scope_label):
                    expected_source_lane = target_registry_source_lane(
                        self.commit_conn,
                        station_id=station,
                        event_date=day,
                    )
                # This one reads the 21GB canonical archive, not the SSOT --
                # a different file, a different cache, and the only phase of
                # P1 that leaves the target database.  Timed separately so a
                # slow archive is never diagnosed as a slow SSOT.
                with self._span("p1_load_observations", label=scope_label):
                    observations = load_resident_formal_observations(
                        self.canonical_source_conn,
                        registry_rows=registry_rows,
                        station_id=station,
                        event_date=day,
                        as_of_utc=as_of_utc,
                    )
                # The observations come from the read-only canonical archive,
                # but the revision facts P1's lineage must name live in the
                # target SSOT.  Resolved here, against the same connection the
                # neighbouring registry lookup uses, rather than by handing the
                # loader a second database: the loader's job is the strict
                # as-of read of the archive, and nothing else on that path
                # needs SSOT access.
                with self._span("p1_attach_revisions", label=scope_label):
                    observations = attach_truth_observation_revisions(
                        self.commit_conn,
                        observations,
                        station_id=station,
                        as_of_utc=as_of_utc,
                    )
                if not observations:
                    continue
                with self._span("p1_load_envelopes", label=scope_label):
                    envelopes = load_materialized_probability_envelopes(
                        self.commit_conn,
                        station_id=station,
                        event_date=day,
                        evaluation_at_utc=envelope_as_of_utc,
                        expected_source_lane=expected_source_lane,
                    )
                prediction_root, predecessor, consumed, rebasing = (
                    select_p1_replay_base(
                    envelopes,
                    as_of_utc=envelope_as_of_utc,
                    )
                )
                source_lanes = {
                    str(item.get("source_lane") or "").strip().lower()
                    for item in observations
                    if str(item.get("source_lane") or "").strip()
                }
                # The registry still binds every formal station to exactly
                # one lane.  An AWC station-day may additionally carry
                # OOS-governed ASOS substitutes for its own frozen METAR
                # slots -- same sensor, same slots, admitted by the adapter
                # at write time -- so the observation set is a subset of
                # that trio, never a second registry lane.
                admitted_observation_lanes = set(
                    admissible_p1_source_lanes(expected_source_lane)
                )
                if not source_lanes:
                    raise ContractError(
                        "resident_p1_source_lane_ambiguous"
                    )
                if not source_lanes <= admitted_observation_lanes:
                    raise ContractError(
                        "resident_p1_source_lane_registry_mismatch"
                    )
                local_hour = datetime.fromisoformat(
                    as_of_utc.replace("Z", "+00:00")
                ).astimezone(
                    ZoneInfo(prediction_root.settlement_timezone)
                ).hour
                local_time_bucket = (
                    "NIGHT"
                    if local_hour < 6
                    else "MORNING"
                    if local_hour < 12
                    else "AFTERNOON"
                    if local_hour < 18
                    else "EVENING"
                )
                maturity_bin = "D0"
                p1_trajectory_started = time.perf_counter()

                def _resolve_trajectory_scope(bucket: str) -> Any:
                    """One bucket's active artifact, promoted or candidate.

                    Factored out because the compiler needs one per bucket the
                    prefix spans, not one for the wall clock: an artifact is
                    fitted for a single local-time bucket, so a morning step
                    handed the afternoon's artifact falls to the identity
                    fallback with its own bucket's activation sitting unused.

                    The resolution itself lives in the evidence store now, so
                    a measurement can resolve exactly what production would
                    have served rather than a copy of it that drifts.  The
                    fallback to the candidate is the 2026-08-18 ruling: the
                    promotion gate is a label, not the switch on the layer --
                    refusing to resolve a candidate left 301 of 350 P1
                    station-days with no trajectory evidence, and P1 without
                    it finds the settled bucket 45.7% of the time against
                    75.8% with it.  Strength still rides on the artifact's own
                    sample size.

                    Artifact scopes are fitted per registry lane; a mixed
                    observation set (AWC plus scheduled ASOS substitutes) must
                    not let set iteration order pick a lane no artifact was
                    ever fitted for.
                    """

                    return resolve_metar_trajectory_artifact_row(
                        self.commit_conn,
                        station_id=station,
                        source_lane=expected_source_lane,
                        season_bin=str(
                            prediction_root.lineage.get("season_bin") or ""
                        ),
                        local_time_bucket=bucket,
                        maturity_bin=maturity_bin,
                        settlement_definition=str(
                            prediction_root.lineage.get(
                                "settlement_definition"
                            )
                            or ""
                        ),
                        as_of_utc=as_of_utc,
                    )

                trajectory_row = _resolve_trajectory_scope(local_time_bucket)
                trajectory_artifact = (
                    None
                    if trajectory_row is None
                    else MetarTrajectoryLikelihoodArtifact.from_mapping(
                        trajectory_row["artifact"]
                    )
                )
                # One artifact per bucket the day can contain, so every step of
                # the replayed prefix is governed by the artifact fitted for
                # the hour it happened in.  The wall-clock bucket keeps the
                # resolution semantics it has always had, including its
                # errors; the other three are best-effort, because a scope the
                # compiler may never reach must not be able to fail a
                # station-day that works today.  Whatever they refuse is named
                # in the receipt rather than swallowed.
                trajectory_artifact_by_bucket: dict[
                    str, MetarTrajectoryLikelihoodArtifact
                ] = {}
                trajectory_scope_blockers: dict[str, str] = {}
                for candidate_bucket in (
                    "NIGHT", "MORNING", "AFTERNOON", "EVENING"
                ):
                    if candidate_bucket == local_time_bucket:
                        candidate_row = trajectory_row
                    else:
                        try:
                            candidate_row = _resolve_trajectory_scope(
                                candidate_bucket
                            )
                        except ContractError as exc:
                            trajectory_scope_blockers[candidate_bucket] = str(
                                exc
                            )
                            continue
                    if candidate_row is None:
                        continue
                    trajectory_artifact_by_bucket[candidate_bucket] = (
                        MetarTrajectoryLikelihoodArtifact.from_mapping(
                            candidate_row["artifact"]
                        )
                    )
                self._add_span(
                    "p1_trajectory_artifact",
                    (time.perf_counter() - p1_trajectory_started) * 1000.0,
                    label=scope_label,
                )
                # A missing or pre-curve artifact degrades P1, it does not
                # stop it.  Requiring the hourly-curve successor before any
                # P1 could run inverted the codebase's own cutover rule --
                # the incumbent stays active until the successor passes its
                # gate -- and the arithmetic made the outage open-ended: the
                # gate needs 20 effective folds, curve-bearing roots exist
                # only from 2026-08-03, and folds need settled truth, so no
                # station could promote before late August.  P1 emitted
                # nothing after 2026-08-01.
                #
                # The cost was not just the learned update.  P1 is the only
                # writer of the reported-high hard bound into the atomic
                # chain, so while it was dark the system kept pricing buckets
                # the day's own observations had already excluded.  The
                # compiler's identity-LR fallback prices nothing it cannot
                # defend -- likelihood one everywhere, official running high
                # still hard -- which is exactly the incumbent production ran
                # on through 2026-08-01.  A promoted curve artifact takes
                # over the moment one exists.
                p1_trajectory_mode = p1_trajectory_mode_for_artifact(
                    trajectory_artifact,
                    hourly_curve_method_version=(
                        METAR_TRAJECTORY_CONDITIONAL_HOURLY_CURVE_METHOD_VERSION
                    ),
                )
                p1_compile_started = time.perf_counter()
                refresh_refusals: list[str] = []
                packets = compile_station_p1_packets(
                    state_refresh_refusals_out=refresh_refusals,
                    predecessor=predecessor,
                    prediction_root=prediction_root,
                    observations=observations,
                    registry_rows=registry_rows,
                    compilation_at_utc=as_of_utc,
                    freshness_seconds=freshness_seconds,
                    decision_floor_at_utc=(
                        str(
                            self.commit_conn.execute(
                                "SELECT MAX(decision_at_utc) "
                                "FROM basket_probability_envelope "
                                "WHERE station_id=? AND event_date=? "
                                "AND stage='P1' AND state='COMMITTED' "
                                "AND decision_at_utc<=?",
                                (station, day, as_of_utc),
                            ).fetchone()[0]
                            or ""
                        )
                        or None
                    ),
                    consumed_observation_ids=consumed,
                    trajectory_artifact=trajectory_artifact,
                    trajectory_artifact_by_local_time_bucket=(
                        trajectory_artifact_by_bucket or None
                    ),
                    # The regional lane's runs for this station-day, read
                    # once here; each prefix reads the freshest run its own
                    # clock could have seen, as a covariate of the joint
                    # likelihood (charter 150) and nothing else.
                    regional_runs=load_regional_runs_for_station_day(
                        self.commit_conn if self.commit_conn is not None else self.conn,
                        station_id=str(predecessor.station_id),
                        event_date=str(predecessor.event_date),
                        as_of_utc=as_of_utc,
                    ),
                    regional_debias_artifact=(
                        load_regional_point_debias_artifact()
                    ),
                    # Charter 150: P1 = root x hard bound x g(d | s)**alpha.
                    # Handed in so a replay rebuilds the same envelope; the
                    # loader follows the daily refit by modification time.
                    observation_likelihood_artifact=(
                        load_p1_observation_likelihood_artifact()
                    ),
                    maturity_bin=maturity_bin,
                )
                self._add_span(
                    "p1_compile_packets",
                    (time.perf_counter() - p1_compile_started) * 1000.0,
                    label=scope_label,
                )
                if not packets:
                    # Nothing to write: no new reported high, and the state
                    # refresh either had nothing newer to read or its clock
                    # had not lapsed.  Nothing is renewed by copying.
                    #
                    # This branch used to append a reaffirmation -- the
                    # predecessor's probabilities verbatim on a new decision
                    # clock -- so a hot night's standing high (ZUUU
                    # 2026-08-13: 31C at 00:06 local, ten morning reports
                    # under it) would not age the envelope out of service.
                    # That renewed a belief without updating it: 595 P1
                    # envelopes written 2026-09-11..12 restated their
                    # predecessor's numbers byte for byte, on reports the
                    # walk had examined and not stepped on.  The compiler's
                    # state refresh (60b24dfb) now recomputes on the current
                    # clock over the complete prefix in exactly that case, and
                    # of 2,810 P1 envelopes written after it landed none was a
                    # reaffirmation.  What remains reachable here is a refresh
                    # the compiler refused, and a refusal restated as a fresh
                    # belief is the defect, not the fallback -- it is named in
                    # the receipt and the envelope ages out on its own grace.
                    receipts.append({
                        "station_id": station,
                        "event_date": day,
                        "state": "NO_NEW_REPORTED_HIGH",
                        **(
                            {"state_refresh_refused": refresh_refusals[-1]}
                            if refresh_refusals else {}
                        ),
                        "observation_count": len(observations),
                        "p1_update_count": 0,
                        "trajectory_mode": p1_trajectory_mode,
                        "soft_likelihood_policy": SOFT_LIKELIHOOD_POLICY,
                    })
                    continue
                final_envelope = ProbabilityEnvelope.from_mapping(
                    packets[-1]["expected_envelope"]
                )
                # A delayed official new-high remains part of the immutable
                # P1 replay history even when its decision-time freshness has
                # already elapsed.  Refusing this append leaves the same
                # observation perpetually unconsumed and blocks every later
                # cycle.  Persist the deterministic cursor; the independent
                # stage selector still rejects stale P1 for basket decisions
                # and cannot silently downgrade to P0.
                current_consumable = final_envelope.is_servable(as_of_utc)
                with self._span(
                    "p1_write_scope", label=scope_label
                ), _writer_transaction(
                    self.commit_conn,
                    savepoint="resident_p1_scope",
                ):
                    writes = []
                    for packet in packets:
                        envelope = ProbabilityEnvelope.from_mapping(
                            packet["expected_envelope"]
                        )
                        proof = dict(packet["trajectory_proof"])
                        insert_probability_update_proof(
                            self.commit_conn,
                            {
                                "proof_id": proof["proof_id"],
                                "proof_kind": (
                                    "METAR_TRAJECTORY_UPDATE"
                                ),
                                "station_id": station,
                                "event_date": day,
                                "settlement_timezone": (
                                    envelope.settlement_timezone
                                ),
                                "prediction_root_checkpoint_id": (
                                    prediction_root.checkpoint_id
                                ),
                                "artifact_id_or_none": (
                                    proof["artifact_id"]
                                ),
                                "activation_id_or_none": (
                                    proof["activation_id"]
                                ),
                                "canonical_sequence_sha256_or_none": (
                                    proof[
                                        "canonical_observation_sequence_sha256"
                                    ]
                                ),
                                "decision_at_utc": (
                                    envelope.decision_at_utc
                                ),
                                "proof": proof,
                                "content_sha256": (
                                    proof["content_sha256"]
                                ),
                            },
                        )
                        writes.append(
                            insert_probability_envelope(
                                self.commit_conn,
                                envelope,
                                created_at_utc=str(
                                    packet["created_at_utc"]
                                ),
                            )
                        )
                write_count = sum(
                    1 for write in writes if write.get("wrote") is True
                )
                receipts.append({
                    "station_id": station,
                    "event_date": day,
                    "state": (
                        "COMMITTED"
                        if write_count
                        else "ALREADY_COMMITTED"
                    ),
                    "observation_count": len(observations),
                    "p1_update_count": write_count,
                    "trajectory_mode": p1_trajectory_mode,
                    "soft_likelihood_policy": SOFT_LIKELIHOOD_POLICY,
                    # Which local-time buckets had an artifact to govern their
                    # steps.  ``trajectory_mode`` is the wall-clock bucket's
                    # answer alone and has been misread as the layer's coverage
                    # before; this is the coverage.
                    "trajectory_buckets_resolved": sorted(
                        trajectory_artifact_by_bucket
                    ),
                    "trajectory_scope_blockers": trajectory_scope_blockers,
                    # Whether the walk closed with a state refresh -- the
                    # step that recomputes the belief on the current clock
                    # over the complete prefix.  The compiler swallows a
                    # refusal there rather than failing the station-day, so
                    # this is where a refresh that never lands becomes
                    # visible: on an event day it should be true on most
                    # scopes that wrote anything at all.
                    "state_refresh_written": any(
                        str(packet.get("state_refresh_of_checkpoint_id") or "")
                        for packet in packets
                    ),
                    **(
                        {"state_refresh_refused": refresh_refusals[-1]}
                        if refresh_refusals else {}
                    ),
                    "p0_rebase": rebasing,
                    "current_consumable": current_consumable,
                    "replay_cursor_only": not current_consumable,
                    "p1_checkpoint_ids": [
                        str(
                            packet["expected_envelope"]["checkpoint_id"]
                        )
                        for packet in packets
                    ],
                    "writes": writes,
                })
            except Exception as exc:
                blockers.append({
                    "station_id": station,
                    "event_date": day,
                    "reason": f"{type(exc).__name__}:{exc}",
                })
            assert_process_memory_budget()
        return {
            "schema": "bayes_basket_target_resident_p1_ingress_v1",
            "correction_preclear": correction_preclear,
            # A correction/revision blocker halts only that station-day.  If
            # other scopes committed successfully, preserve their P1 chain
            # and surface the isolated halt as PARTIAL_FAIL_CLOSED; a wholly
            # blocked pass remains globally blocked.
            "state": (
                "PARTIAL_FAIL_CLOSED"
                if blockers and receipts
                else "BLOCKED_FAIL_CLOSED"
                if blockers
                else "COMMITTED"
            ),
            "scope_count": len(grouped),
            "probability_scope_count": len(probability_scopes),
            "updated_scope_count": sum(
                1
                for item in receipts
                if item["state"] == "COMMITTED"
            ),
            "p1_update_count": sum(
                int(item.get("p1_update_count") or 0)
                for item in receipts
            ),
            "receipts": receipts,
            "blockers": blockers,
            "writes_target_ssot": any(
                int(item.get("p1_update_count") or 0) > 0
                for item in receipts
            ),
            "places_orders": False,
            "calls_order_gateway": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }

    @staticmethod
    def _p0m_no_op_receipt(
        *,
        station_id: str,
        event_date: str,
        state: str,
        dropped_pre_root: int | None = None,
    ) -> dict[str, Any]:
        """The receipt for a scope this stage does nothing for.

        One constructor for both no-op exits, and for the cheap path that
        reaches the same conclusion without the read.  Three copies of the
        same dict is how a fast path and a slow path stop agreeing without
        anyone noticing.
        """

        receipt: dict[str, Any] = {
            "station_id": station_id,
            "event_date": event_date,
            "state": state,
            "write_count": 0,
            "writes": [],
        }
        if dropped_pre_root is not None:
            receipt["dropped_pre_root_captures"] = dropped_pre_root
        return receipt

    def _observed_running_high_c(
        self,
        *,
        station_id: str,
        event_date: str,
        as_of_utc: str,
    ) -> float | None:
        """The day's observed running high (see ``observed_running_high_c``)."""

        return observed_running_high_c(
            self.commit_conn,
            self.canonical_source_conn,
            station_id=station_id,
            event_date=event_date,
            as_of_utc=as_of_utc,
        )

    def _resting_dead_buckets(
        self,
        conn: sqlite3.Connection,
        *,
        station_id: str,
        event_date: str,
        as_of_utc: str,
    ) -> tuple[tuple[str, ...], float | None]:
        """Charter 135 (二)'s dead buckets (see ``resting_dead_buckets``)."""

        if not observed_high_floor_enabled():
            return (), None
        return resting_dead_buckets(
            conn,
            station_id=station_id,
            event_date=event_date,
            running_high=self._observed_running_high_c(
                station_id=station_id,
                event_date=event_date,
                as_of_utc=as_of_utc,
            ),
        )

    def _p0m_observed_hard_bound(
        self,
        *,
        station_id: str,
        event_date: str,
        as_of_utc: str,
        root: Any,
    ) -> tuple[tuple[str, ...], float | None]:
        """Charter 61: the observed-high fact for one P0-M decision.

        Promoted from P1: the settlement rule defines truth as the day's
        maximum, so a reported high of X makes every bucket ending at or
        below X arithmetically dead whatever any model claims.  Returns
        ((), None) whenever the day has no formal observations yet (a
        pre-day TAF confirmation), and refuses to exhaust the support from
        here -- the materializer would raise, and a bound that deletes the
        whole distribution is evidence of a vocabulary problem, not a fact
        to apply.
        """

        running_high = self._observed_running_high_c(
            station_id=station_id,
            event_date=event_date,
            as_of_utc=as_of_utc,
        )
        if running_high is None:
            return (), None
        excluded = dead_buckets_for_running_high(
            ordered_buckets=sorted(
                root.probabilities,
                key=lambda bucket: root.bucket_ordinals.get(bucket, 0),
            ),
            bucket_intervals_c_json=root.lineage.get(
                "bucket_intervals_c_json"
            ),
            running_high_c=running_high,
        )
        return excluded, running_high

    @staticmethod
    def _p0_root_latest_run_init_utc(root: ProbabilityEnvelope) -> datetime | None:
        """The newest model run a P0 root is built on, or None if unknown.

        ``run_init_utc_by_system_json`` names one run per family; the root
        knows everything its newest member knows, so that is the instant a
        forecast must postdate to bring information the root lacks.
        """

        raw = root.lineage.get("run_init_utc_by_system_json")
        if not raw:
            return None
        try:
            by_system = json.loads(str(raw))
        except (TypeError, ValueError, json.JSONDecodeError):
            return None
        if not isinstance(by_system, Mapping) or not by_system:
            return None
        latest: datetime | None = None
        for value in by_system.values():
            try:
                parsed = datetime.fromisoformat(
                    str(value).replace("Z", "+00:00")
                )
            except (TypeError, ValueError):
                return None
            if parsed.tzinfo is None:
                return None
            parsed = parsed.astimezone(timezone.utc)
            if latest is None or parsed > latest:
                latest = parsed
        return latest

    @staticmethod
    def _taf_issued_after(
        capture: Mapping[str, Any], instant: datetime
    ) -> bool:
        issued_raw = str(
            (capture.get("forecast_revision") or {}).get("issued_at_utc")
            or ""
        )
        try:
            issued = datetime.fromisoformat(issued_raw.replace("Z", "+00:00"))
        except (TypeError, ValueError):
            return False
        if issued.tzinfo is None:
            return False
        return issued.astimezone(timezone.utc) > instant

    @staticmethod
    def _p0m_scope_shape(
        envelopes: Sequence[ProbabilityEnvelope],
        captures: Sequence[Mapping[str, Any]],
        *,
        as_of_utc: str | None = None,
    ) -> dict[str, Any]:
        """The P0/P0-M-only shape both the real and the cheap path read.

        One implementation, called twice on two lists, is what makes the
        shadow comparison meaningful: a disagreement is then a disagreement
        about the *rows*, which is the thing under test, and never about two
        copies of the arithmetic drifting apart.
        """

        first_root_at = min(
            (
                item.decision_at_utc
                for item in envelopes
                if item.stage == "P0"
            ),
            default="",
        )
        # Seatability is an information question, not a delivery one.  A
        # TAF adjusts a root when the forecaster issued it after the model
        # run the root is built on; when it was carried into our inbox, and
        # when we happened to mint the root, are our clocks and say nothing
        # about which knows more.  Judged by our clocks, the five TX
        # stations of 2026-09-04 lost their only TAF: issued 21:04Z on the
        # 2nd, three hours after the 18Z run the root reads, received 01Z,
        # while the root itself was minted 05:56Z after a night of capture
        # starvation -- and ZBAA answered forecast_revision_chain_empty on
        # every cycle.  The receipt rule remains for roots that carry no
        # run identity (the aggregator fallback), so nothing they admitted
        # before is lost.  (User ruling 2026-09-03.)
        gate_root = max(
            (item for item in envelopes if item.stage == "P0"),
            key=lambda item: item.decision_at_utc,
            default=None,
        )
        gate_run_init = (
            TargetProductionWorker._p0_root_latest_run_init_utc(gate_root)
            if gate_root is not None else None
        )
        if gate_run_init is not None:
            seatable = [
                capture for capture in captures
                if TargetProductionWorker._taf_issued_after(
                    capture, gate_run_init
                )
            ]
        else:
            seatable = [
                capture for capture in captures
                if first_root_at
                and str(
                    (capture.get("forecast_revision") or {}).get(
                        "received_at_utc"
                    ) or ""
                ) >= first_root_at
            ]
        earliest_taf = min(
            (
                str(
                    (capture.get("forecast_revision") or {}).get(
                        "received_at_utc"
                    ) or ""
                )
                for capture in seatable
            ),
            default="",
        )
        # Charter, operator ruling 2026-08-31: a TAF replayed onto a newer
        # model base is still the forecaster's confirmation, and P0-M should
        # be built on P0's latest probabilities the way P1 already is.
        #
        # The base used to be the last P0 predating the earliest un-applied
        # TAF, and stayed there while that TAF stayed earliest.  KATL is the
        # specimen: TAF at 05:39, base frozen on the 05:28 P0, and P0-M was
        # still serving it at 10:43 -- five hours and four model improvements
        # later, stating 0.347 for the 92-93F bucket while the current P0
        # said 0.427.  Stage precedence serves the higher stage, so the book
        # was priced off the older number with the newer one in hand.
        roots = [item for item in envelopes if item.stage == "P0"]
        latest_root = (
            max(roots, key=lambda item: item.decision_at_utc) if roots else None
        )
        # Confirmed on the root being served -- that exact checkpoint.
        #
        # This used to be "seen under a base with the same probabilities",
        # on the argument that a P0 is re-minted every compile and keying on
        # the id would re-apply every scope every cycle.  Two things changed
        # the arithmetic.  A confirmation's window now ends with its root's
        # (``_p0m_window_until``), so a re-minted root with the same numbers
        # but a later freshness leaves the old confirmation expiring on a
        # root nobody serves.  And P1 roots on the P0-M whose root *is* the
        # newest P0 checkpoint (``select_p1_replay_base``), so a confirmation
        # left on an equal-probability predecessor sent P1 onto the bare P0
        # -- dropping the stage -- until the probabilities next moved.  The
        # re-mint rate the old note feared is the rate P1 already replays
        # at: 2,834 P0 transitions over 90 station-days, 2026-09-11..12.
        seen_revisions = {
            str(item.lineage.get("forecast_source_object_sha256") or "")
            for item in envelopes
            if item.stage == "P0-M"
            and latest_root is not None
            and str(item.lineage.get("p0_root_checkpoint_id") or "")
            == latest_root.checkpoint_id
        }
        # Every TAF text that has ever confirmed this station-day, under any
        # root.  A text in here has already been judged seatable once; the
        # forecaster has not spoken again just because the model moved.
        seated_revisions = {
            str(item.lineage.get("forecast_source_object_sha256") or "")
            for item in envelopes
            if item.stage == "P0-M"
        } - {""}
        # What a rebuilt confirmation should carry: the forecaster's newest
        # word that is still valid.  Operator ruling 2026-08-31 -- "a TAF
        # replayed onto a newer model base is still the forecaster's
        # confirmation" -- so a text that already confirmed an older root is
        # carried onto the newer one even when it was issued before the newer
        # run.  The 2026-09-03 information-order rule still governs *new*
        # texts (``seatable``); applied to the replay as well, it stranded
        # the confirmation on its old root whenever a model run landed after
        # the last TAF: 17 of the 86 sampled P0-M heads serving a superseded
        # root on 2026-09-11..12 had no way off it until the next issuance.
        #
        # And the newest, not the first.  The replay walked revisions in
        # receipt order and seated each at "now"; the second one then failed
        # the strictly-after test, so what survived was the *oldest* text,
        # whose TX then chose the charter-57 centre/width cell.
        replay_candidates: dict[str, Mapping[str, Any]] = {}
        for capture in (
            *seatable,
            *(
                capture for capture in captures
                if str(
                    (capture.get("forecast_revision") or {}).get(
                        "source_object_sha256"
                    ) or ""
                ) in seated_revisions
            ),
        ):
            revision_raw = capture.get("forecast_revision") or {}
            if as_of_utc is not None:
                valid_until = str(revision_raw.get("valid_until_utc") or "")
                if not valid_until or not timestamp_lt(as_of_utc, valid_until):
                    continue
            replay_candidates[
                str(revision_raw.get("source_object_sha256") or "")
            ] = capture
        ordered_candidates = sorted(
            replay_candidates.values(),
            key=lambda capture: (
                str((capture.get("forecast_revision") or {}).get(
                    "issued_at_utc"
                ) or ""),
                str((capture.get("forecast_revision") or {}).get(
                    "received_at_utc"
                ) or ""),
                str((capture.get("forecast_revision") or {}).get(
                    "revision_id"
                ) or ""),
            ),
            reverse=True,
        )
        replay_target = ordered_candidates[0] if ordered_candidates else None
        replay_target_sha = (
            str(
                (replay_target.get("forecast_revision") or {}).get(
                    "source_object_sha256"
                ) or ""
            )
            if replay_target is not None
            else ""
        )
        # Texts never seated that may still seat: an expired one never will,
        # and counting it would keep the cheap path from ever skipping the
        # scope again.
        new_revision_count = sum(
            1 for capture in seatable
            if str(
                (capture.get("forecast_revision") or {}).get(
                    "source_object_sha256"
                ) or ""
            ) not in seated_revisions
            and str(
                (capture.get("forecast_revision") or {}).get(
                    "source_object_sha256"
                ) or ""
            ) in replay_candidates
        )
        return {
            "first_root_at": first_root_at,
            "seatable": seatable,
            "dropped_pre_root": len(captures) - len(seatable),
            "earliest_taf": earliest_taf,
            "roots": roots,
            "latest_root": latest_root,
            "seen_revisions": seen_revisions,
            "seated_revisions": seated_revisions,
            "replay_target": replay_target,
            "new_revision_count": new_revision_count,
            # A root with no usable life left can lend a confirmation none
            # (``_p0m_window_until``), so the scope has nothing to do until
            # the next P0 -- and must not need a registry shard to say so.
            "root_exhausted": bool(
                as_of_utc is not None
                and latest_root is not None
                and _p0m_window_until(
                    as_of_utc, root=latest_root, revision=None
                ) is None
            ),
            # Whether the root being served still lacks a confirmation of the
            # text it should carry -- the rebuild this lane owes the scope.
            "reroot_due": bool(
                replay_target_sha
                and replay_target_sha not in seen_revisions
            ),
        }

    def _materialize_resident_p0m(
        self,
        *,
        as_of_utc: str,
    ) -> dict[str, Any]:
        """Consume a bounded forward-only TAF inbox before resident P1."""

        if self.commit_conn is None:
            return {
                "state": "not_attempted",
                "reason": "target_atomic_writer_not_injected",
                "writes_target_ssot": False,
            }
        if not self.taf_inbox_path.is_file():
            return {
                "state": "not_configured",
                "reason": "resident_taf_inbox_missing",
                "writes_target_ssot": False,
            }
        with self._span("p0m_inputs_load"):
            inbox = load_bounded_json(self.taf_inbox_path)
        if not isinstance(inbox, Mapping):
            raise ContractError("resident_taf_input_invalid")
        if inbox.get("schema") != "bayes_basket_target_taf_revision_inbox_v1":
            raise ContractError("resident_taf_inbox_schema_invalid")
        try:
            with self._span("p0m_taf_fact_ingress"):
                taf_fact_ingress = ingest_forward_taf_inbox(
                    self.commit_conn,
                    inbox,
                )
            # The sibling point system rides the same stage.  Its lane is
            # forward-only accumulation -- each pass projects whichever noon
            # anchors have newly passed, and settled days become OOS folds on
            # their own -- so a failure here is one missed pass, never a
            # reason to block the TAF ingest it shares the stage with.
            try:
                if self.canonical_source_conn is None:
                    projection_receipt: dict[str, Any] = {
                        "state": "not_attempted",
                        "reason": "canonical_source_conn_missing",
                    }
                else:
                    # Plan outside the lock; take it only if there is a row
                    # to write.  Nearly every cycle plans nothing (all
                    # station-days already projected), and those cycles now
                    # never open a transaction at all.
                    with self._span("metar_proj_plan"):
                        pending_projection, projection_receipt = (
                            plan_metar_physical_member_runs(
                                self.commit_conn,
                                archive_conn=self.canonical_source_conn,
                                as_of_utc=as_of_utc,
                            )
                        )
                    if pending_projection:
                        with _writer_transaction(
                            self.commit_conn,
                            savepoint="metar_physical_projection",
                        ):
                            with self._span("metar_proj_apply"):
                                projection_receipt = {
                                    **projection_receipt,
                                    "wrote_count": (
                                        apply_metar_physical_member_runs(
                                            self.commit_conn,
                                            pending_projection,
                                        )
                                    ),
                                }
            except Exception as exc:  # noqa: BLE001 - stage isolation
                projection_receipt = {
                    "state": "failed",
                    "reason": f"{type(exc).__name__}:{exc}"[:200],
                }
            taf_fact_ingress = {
                **taf_fact_ingress,
                "metar_physical_projection": projection_receipt,
            }
        except ContractError as exc:
            if str(exc) != "forward_taf_capture_content_conflict":
                raise
            return {
                "schema": "bayes_basket_target_resident_taf_ingress_v1",
                "state": "BLOCKED_FAIL_CLOSED",
                "taf_fact_ingress": {
                    "state": "BLOCKED_FAIL_CLOSED",
                    "reason": f"ContractError:{exc}",
                    "wrote_count": 0,
                },
                "receipts": [],
                "blockers": [{
                    "reason": f"ContractError:{exc}",
                }],
                "writes_target_ssot": False,
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
        raw_captures = inbox.get("captures")
        if not isinstance(raw_captures, list) or len(raw_captures) > 2048:
            raise ContractError("resident_taf_inbox_capture_count_invalid")
        captures_by_scope: dict[tuple[str, str], list[Mapping[str, Any]]] = {}
        # A capture that fails its own checks is set aside on its own, as the
        # fact ingest above now does: its scope has no committed TAF fact and
        # fails closed for P0-M, and no other station's P0-M waits on it.
        refused_captures: list[dict[str, str]] = []
        # One revision twice in the inbox: the newer is the revision
        # (「以最新的为准」, 2026-09-23), the same one the fact ingest keeps.
        newest = newest_forward_taf_captures(raw_captures)
        for index, raw_capture in enumerate(raw_captures):
            if index not in newest:
                refused_captures.append(rejected_forward_taf_capture(
                    raw_capture, "forward_taf_capture_superseded_in_inbox"
                ))
                continue
            try:
                if not isinstance(raw_capture, Mapping):
                    raise ContractError("resident_taf_capture_invalid")
                supplied_sha = str(raw_capture.get("content_sha256") or "")
                identity = {
                    key: value
                    for key, value in raw_capture.items()
                    if key != "content_sha256"
                }
                if supplied_sha != content_sha256(identity):
                    raise ContractError(
                        "resident_taf_capture_content_sha_mismatch"
                    )
                boundary = raw_capture.get("boundary")
                if (
                    raw_capture.get("source_class")
                    != "official_forward_native_receipt"
                    or not isinstance(boundary, Mapping)
                    or boundary.get("native_local_receipt") is not True
                    or boundary.get("retrospective_replay_only") is not False
                ):
                    raise ContractError("resident_taf_forward_receipt_required")
                revision = ForecastRevision.from_mapping(
                    raw_capture.get("forecast_revision")
                )
            except ContractError as exc:
                refused_captures.append(
                    rejected_forward_taf_capture(raw_capture, str(exc))
                )
                continue
            if revision.received_at_utc > as_of_utc:
                continue
            captures_by_scope.setdefault(
                (revision.station_id, revision.event_date),
                [],
            ).append(raw_capture)
        receipts: list[dict[str, Any]] = []
        blockers: list[dict[str, str]] = []
        ignored_inactive_scope_count = 0
        ignored_no_artifact_scope_count = 0
        # What a cheaper path would have concluded, kept beside what the real
        # path concludes so the two can be compared before either is trusted.
        #
        # The real path reads every committed envelope for the station-day to
        # decide, and 80% of that read is per-row work -- JSON-decoding the
        # row, hashing it back to check its stored sha, building the envelope
        # -- while P1 is 78% of the rows and no part of this decision needs
        # it.  Measured 2026-08-22: 168 scopes, 197 seconds, and every one of
        # the 168 concluded NO_NEW_TAF_REVISION, having built 1,353 envelopes
        # per scope to say so.
        #
        # The cheap path loads P0 and P0-M only and answers two questions:
        # are there roots, and is every capture already materialised.  It is
        # run in shadow first because P0-M is the stage that goes silent
        # without saying so, and a verdict that agrees on one cycle is worth
        # more than an argument that it must.
        shadow_verdicts: dict[tuple[str, str], dict[str, Any] | None] = {}
        shadow_errors: list[dict[str, str]] = []
        replays_this_cycle = 0
        replays_deferred: list[str] = []
        p0m_serving_tables: dict[str, Any] | None = None
        # The latest decision this pass stamped, which a rebuild on a root
        # minted at the cycle clock places one millisecond past it.  P1 reads
        # its roots as of this, so it builds on the confirmation just made.
        p0m_stage_clock_utc: str | None = None
        # Furthest event day first, then station.
        #
        # The replay budget is four scopes a cycle and this loop used to walk
        # (station, day) alphabetically, so for any station the *current* day
        # came before the forward one and spent the budget first.  Measured
        # 2026-09-01 16:05: twelve scopes deferred on budget -- nine of them
        # the current day, three the forward one -- and the single write the
        # budget bought went to the current day.
        #
        # That is the wrong day for this stage.  Each event day has one stage
        # that governs it: the furthest day has only P0, because nothing else
        # can open its position; the day after that is shaped by P0-M, the
        # TAF confirmation that sizes it before it opens; and the day already
        # open is P1's, driven by arriving observations.  A P0-M replay spent
        # on the open day refines a book P1 is about to restate anyway, while
        # the forward day -- the one P0-M actually governs -- waits.
        #
        # Descending date puts the forward days first and the settled backlog
        # last, which is also where it belongs: those are skipped above
        # before anything is read.
        _p0m_loop_started = time.perf_counter()
        _replay_blocked = getattr(
            self, "_p0m_replay_blocked_scopes", frozenset()
        )
        for (station, day), captures in sorted(
            captures_by_scope.items(),
            key=lambda item: (
                # A scope whose decision was refused last round for want of
                # this replay comes first, whatever day it is.  The day order
                # below is the stage-governs-its-own-day rule and stays the
                # rule; this is the case that rule cannot see, because a
                # forward day that is being served fine and an open day that
                # is refusing every cycle look identical to a date.
                0 if item[0] in _replay_blocked else 1,
                _p0m_scope_day_order(item[0][1]),
                item[0][0],
            ),
        ):
            try:
                with self._span("p0m_scope_exists", label=station):
                    # The settlement timezone comes off the same row, from the
                    # same index seek: the day-state test below needs it and
                    # nothing else here does, so asking for it costs nothing.
                    scope_exists = self.commit_conn.execute(
                        "SELECT settlement_timezone"
                        " FROM basket_probability_envelope "
                        "WHERE station_id=? AND event_date=? "
                        "AND state='COMMITTED' AND stage='P0' "
                        "AND decision_at_utc<=? LIMIT 1",
                        (station, day, as_of_utc),
                    ).fetchone()
                if scope_exists is None:
                    ignored_inactive_scope_count += 1
                    receipts.append({
                        "station_id": station,
                        "event_date": day,
                        "state": "IGNORED_NO_P0_SCOPE",
                        "write_count": 0,
                        "writes": [],
                    })
                    continue
                # A settled day, decided before anything is read.
                #
                # "Only where trading can still happen": a settled day's base
                # never moves again and nobody prices it.  That ruling already
                # existed, but it sat two reads deep -- past the shadow load
                # and past the full scope load -- so every closed station-day
                # in the backlog paid for both before being told it had
                # nothing to do.  The day state is a pure function of the
                # date, the timezone and the clock, so it can be asked first.
                #
                # Measured 2026-09-01 over one cycle's 389 scopes: 323 were
                # closed and *every one of them wrote nothing* -- 290 already
                # labelled REPLAY_SKIPPED_SETTLED_DAY and 33 reaching the same
                # no-op through the fast path's NO_NEW_TAF_REVISION.  So this
                # changes no write anywhere; it changes when the answer is
                # known.  At the shadow load's measured 133.8ms a scope that
                # is about 43 seconds of a 409-second cycle.
                #
                # The 33 are relabelled deliberately.  A closed day does
                # nothing because it is closed, not because its TAF is
                # unchanged, and the receipt should say the binding reason.
                #
                # Unreadable falls through rather than skipping, and the
                # original guard downstream stays where it is: it is the
                # backstop for exactly that case.
                try:
                    p0m_day_state = event_day_window(
                        day,
                        as_of_utc=as_of_utc,
                        target_timezone=str(scope_exists[0] or ""),
                    )["state"]
                except Exception:  # noqa: BLE001 -- unreadable is not skippable
                    p0m_day_state = ""
                if p0m_day_state and p0m_day_state not in {
                    "open", "not_started"
                }:
                    ignored_no_artifact_scope_count += 1
                    receipts.append(self._p0m_no_op_receipt(
                        station_id=station,
                        event_date=day,
                        state="REPLAY_SKIPPED_SETTLED_DAY",
                    ))
                    continue
                # Read the station-day once.  The lane gate below is a pure
                # function of this list, so the second call reuses it rather
                # than paying for the whole read again -- 24 to 27 MB with
                # lineage_json on the largest days, twice per scope, per
                # cycle.  Reusing it also means both gates judge one snapshot
                # instead of two taken moments apart.
                # The cheap verdict, taken before the expensive read so it is
                # answering the same question from the same instant.  Nothing
                # acts on it yet.
                if P0M_FAST_PATH_MODE != "off":
                    try:
                        with self._span(
                            "p0m_shadow_load", label=f"{station}|{day}"
                        ):
                            narrow = load_materialized_probability_envelopes(
                                self.commit_conn,
                                station_id=station,
                                event_date=day,
                                evaluation_at_utc=as_of_utc,
                                stages=("P0", "P0-M"),
                            )
                        narrow_shape = self._p0m_scope_shape(
                            narrow, captures, as_of_utc=as_of_utc
                        )
                        if not narrow_shape["roots"]:
                            fast_receipt = self._p0m_no_op_receipt(
                                station_id=station,
                                event_date=day,
                                state="IGNORED_NO_P0_BEFORE_FORECAST",
                                dropped_pre_root=narrow_shape[
                                    "dropped_pre_root"
                                ],
                            )
                        elif narrow_shape["root_exhausted"]:
                            fast_receipt = self._p0m_no_op_receipt(
                                station_id=station,
                                event_date=day,
                                state="IGNORED_STALE_P0_SCOPE",
                            )
                        elif (
                            not narrow_shape["new_revision_count"]
                            and not narrow_shape["reroot_due"]
                        ):
                            fast_receipt = self._p0m_no_op_receipt(
                                station_id=station,
                                event_date=day,
                                state="NO_NEW_TAF_REVISION",
                            )
                        else:
                            fast_receipt = None
                        shadow_verdicts[(station, day)] = fast_receipt
                        if (
                            P0M_FAST_PATH_MODE == "on"
                            and fast_receipt is not None
                        ):
                            if fast_receipt["state"] == "NO_NEW_TAF_REVISION":
                                ignored_no_artifact_scope_count += 1
                            else:
                                ignored_inactive_scope_count += 1
                            receipts.append(fast_receipt)
                            continue
                    except Exception as exc:  # noqa: BLE001
                        # A shadow that cannot answer is a shadow finding, not
                        # a cycle fault.
                        shadow_verdicts[(station, day)] = {
                            "state": f"SHADOW_ERROR:{type(exc).__name__}",
                        }
                        shadow_errors.append({
                            "station_id": station,
                            "event_date": day,
                            "reason": f"{type(exc).__name__}:{exc}"[:200],
                        })
                scope_validated: list[ProbabilityEnvelope] = []
                with self._span("p0m_scope_load", label=f"{station}|{day}"):
                    envelopes = load_materialized_probability_envelopes(
                        self.commit_conn,
                        station_id=station,
                        event_date=day,
                        evaluation_at_utc=as_of_utc,
                        validated_out=scope_validated,
                    )
                # As-of the forecast, not as-of now.  The three stages run
                # at wildly different cadences -- P0 recompiles on every
                # model update (78-106 times a station-day), the TAF is
                # issued once or twice, P1 follows each observation -- so
                # "the newest P0" is almost always stamped after the TAF
                # that is being applied, and a stage whose decision must
                # follow its predecessor can then never be seated.  P1
                # already resolves this the right way and says so: its base
                # is "durable history, not necessarily a currently
                # consumable probability", chosen by decision time and
                # explicitly allowed to be stale.  P0-M now follows the same
                # contract, which is also what it is *for*: laying new
                # evidence on the model that was current when the evidence
                # arrived.  Freshness is re-established by P0-M's own
                # decision time, not inherited from the root.
                # Per capture, not batch-min.  The inbox carries every
                # forward capture for the scope on every cycle, so one
                # revision received before the scope's first P0 root dragged
                # the anchor in front of every root forever and the whole
                # batch was discarded each cycle -- including revisions that
                # individually satisfy the contract.  Measured 2026-08-20:
                # ZGGG event 2026-08-21 had a TX-less 15:06Z TAF received
                # 16:23Z, first P0 root 17:31Z, and the TX-carrying 21:04Z
                # revision behind it; seven stations sat in
                # IGNORED_NO_P0_BEFORE_FORECAST with no way out, because the
                # blocking capture never leaves the inbox.  A capture with
                # no root before it cannot seat *itself* under the contract
                # -- "no P0 before forecast" is true of it alone -- so it is
                # dropped alone, counted, and its siblings proceed.
                shape = self._p0m_scope_shape(
                    envelopes, captures, as_of_utc=as_of_utc
                )
                first_root_at = shape["first_root_at"]
                dropped_pre_root = shape["dropped_pre_root"]
                # Kept whole beside the seatable subset: a text issued before
                # the newest run may not seat afresh, but one that already
                # confirmed an older root is carried onto the new one.
                scope_captures = captures
                captures = shape["seatable"]
                earliest_taf = shape["earliest_taf"]
                roots = shape["roots"]
                if not roots:
                    ignored_inactive_scope_count += 1
                    receipts.append(self._p0m_no_op_receipt(
                        station_id=station,
                        event_date=day,
                        state="IGNORED_NO_P0_BEFORE_FORECAST",
                        dropped_pre_root=dropped_pre_root,
                    ))
                    continue
                if shape["root_exhausted"]:
                    ignored_inactive_scope_count += 1
                    receipts.append(self._p0m_no_op_receipt(
                        station_id=station,
                        event_date=day,
                        state="IGNORED_STALE_P0_SCOPE",
                    ))
                    continue
                # A stale historical P0 scope is a no-op and must not need a
                # current market registry shard.  Once a fresh P0 can feed a
                # P0-M write, resolve the authoritative lane and re-read the
                # complete chain through the P1 gate before using it.
                with self._span("p0m_source_lane", label=station):
                    expected_source_lane = target_registry_source_lane(
                        self.commit_conn,
                        station_id=station,
                        event_date=day,
                    )
                with self._span("p0m_lane_gate", label=f"{station}|{day}"):
                    envelopes = load_materialized_probability_envelopes(
                        self.commit_conn,
                        station_id=station,
                        event_date=day,
                        evaluation_at_utc=as_of_utc,
                        expected_source_lane=expected_source_lane,
                        preloaded_validated=scope_validated,
                    )
                # Same rule as the shape gate: the base is the latest P0, so
                # a confirmation rebuilt this cycle is rebuilt on the
                # forecast being served.
                roots = [item for item in envelopes if item.stage == "P0"]
                if not roots:
                    raise ContractError("resident_p0_scope_changed_during_lane_gate")
                root = max(roots, key=lambda item: item.decision_at_utc)
                # P0-M has one operator: the identity likelihood.  The
                # calibrated TAF branch (``compile_taf_revision_proof`` +
                # ``materialize_p0m``) went offline 2026-09-13 by user ruling
                # (charter 133, "TAF 校准分支下线，仅作研究"): it moved the centre
                # toward the TAF, which settled truth scored worse (NLL
                # 1.80->1.91 over its own 171 transport rows), and served no
                # row in the five days before.  What the TAF says about the
                # day is served by the width cells inside this operator.
                ignored_no_artifact_scope_count += 1
                capture_by_id = {
                    str(
                        (item.get("forecast_revision") or {}).get(
                            "revision_id"
                        ) or ""
                    ): item
                    for item in scope_captures
                }

                def _taf_field(
                    capture: Mapping[str, Any], name: str
                ) -> float | None:
                    fields = capture.get("taf_fields")
                    if not isinstance(fields, Mapping):
                        return None
                    try:
                        value = float(fields[name])
                    except (KeyError, TypeError, ValueError):
                        return None
                    return value if math.isfinite(value) else None

                # Deliberately not the chain validator for the observed path.
                # That exists for the correcting path, where each revision's
                # likelihood is applied on top of the last and a gap would
                # silently drop a correction.  Identity-likelihood seats are
                # each their own entry moment, and failing the scope on a gap
                # took the whole stage down on first run (14 stations).
                revisions = sorted(
                    (
                        ForecastRevision.from_mapping(item["forecast_revision"])
                        for item in captures
                    ),
                    key=lambda item: (item.received_at_utc, item.revision_id),
                )
                # Keyed by the source object hash: revision ids are re-keyed
                # when the inbox chain repair renumbers a scope, and matching
                # on them re-seated every committed revision at its exact
                # original received instant (43 stations, 2026-08-20).
                gated_shape = self._p0m_scope_shape(
                    envelopes, scope_captures, as_of_utc=as_of_utc
                )
                seen_revisions = gated_shape["seen_revisions"]
                seated_revisions = gated_shape["seated_revisions"]
                # Texts never seated for this day that may seat now; a
                # bulletin without a TX seats too (the identity operator does
                # not read one).
                new_revisions = [
                    revision
                    for revision in revisions
                    if revision.source_object_sha256 not in seated_revisions
                    and timestamp_lt(as_of_utc, revision.valid_until_utc)
                ]
                if p0m_serving_tables is None:
                    # Read once a pass, not once a revision: the rebuild runs
                    # for every scope whose root moved.  Charter 150: P0-M is
                    # P0 times the TAF likelihood and carries no post-hoc
                    # table of its own.
                    p0m_serving_tables = {
                        "taf_likelihood_artifact": (
                            load_taf_likelihood_artifact()
                        ),
                    }
                observed_pending: list[tuple[ProbabilityEnvelope, str]] = []
                observed_error: str | None = None
                window_refusals: list[str] = []
                replay_skip_state: str | None = None
                # Every seat chains from the root.
                observed_predecessor: ProbabilityEnvelope = root

                def _observe(
                    revision: ForecastRevision,
                    decision_at: str,
                    predecessor: ProbabilityEnvelope,
                ) -> ProbabilityEnvelope | None:
                    window_until = _p0m_window_until(
                        decision_at, root=root, revision=revision
                    )
                    if window_until is None:
                        window_refusals.append(revision.revision_id)
                        return None
                    capture = capture_by_id.get(revision.revision_id) or {}
                    observed_excluded, observed_high = (
                        self._p0m_observed_hard_bound(
                            station_id=station,
                            event_date=day,
                            as_of_utc=decision_at,
                            root=root,
                        )
                    )
                    return materialize_p0m_observed(
                        predecessor,
                        p0_root=root,
                        observed_hard_excluded_buckets=observed_excluded,
                        observed_running_high_c=observed_high,
                        forecast_revision_id=revision.revision_id,
                        forecast_source_object_sha256=(
                            revision.source_object_sha256
                        ),
                        taf_tx_c=_taf_field(capture, "tx_c"),
                        # Charter 158: the same bulletin's weather says
                        # whether its disagreement with P0 has a reason.
                        taf_cloud_cover=_taf_field(
                            capture, "cloud_cover_fraction"
                        ),
                        taf_precip_prob=_taf_field(
                            capture, "precipitation_probability"
                        ),
                        decision_at_utc=decision_at,
                        fresh_until_utc=window_until,
                        bridge_sha256=root.bridge_sha256,
                        **p0m_serving_tables,
                    )

                for revision in new_revisions:
                    # The forecast's own arrival is the moment, and it has to
                    # be strictly later than what it follows.  A revision that
                    # was in hand before its predecessor was minted is seated
                    # at the predecessor's clock plus a second; the chain only
                    # needs its order, and the information order was settled
                    # by the seatability gate.
                    previous_time = datetime.fromisoformat(
                        observed_predecessor.decision_at_utc.replace(
                            "Z", "+00:00"
                        )
                    ).astimezone(timezone.utc)
                    received_time = datetime.fromisoformat(
                        revision.received_at_utc.replace("Z", "+00:00")
                    ).astimezone(timezone.utc)
                    decision_time = max(previous_time, received_time)
                    decision_time = decision_time.replace(microsecond=0)
                    if decision_time <= previous_time:
                        decision_time = previous_time.replace(
                            microsecond=0
                        ) + timedelta(seconds=1)
                    decision_at = decision_time.isoformat().replace(
                        "+00:00", "Z"
                    )
                    if (
                        decision_at <= observed_predecessor.decision_at_utc
                        or decision_at > as_of_utc
                    ):
                        # Not this cycle's to date at its arrival -- the root
                        # was minted after it.  The rebuild below seats it now
                        # if it is the newest word.
                        continue
                    try:
                        observed = _observe(
                            revision, decision_at, observed_predecessor
                        )
                    except Exception as exc:  # noqa: BLE001
                        # The identity path is additive: a scope it cannot
                        # serve falls back to silence rather than failing the
                        # stage for every other scope (it did, twice, on first
                        # run).
                        observed_error = f"ContractError:{exc}"[:200]
                        break
                    if observed is None:
                        continue
                    observed_pending.append((observed, decision_at))
                    observed_predecessor = observed
                # The root being served carries the forecaster's newest valid
                # word, rebuilt now when the model moved under it.
                replay_target = gated_shape["replay_target"]
                replay_revision = (
                    ForecastRevision.from_mapping(
                        replay_target["forecast_revision"]
                    )
                    if replay_target is not None
                    else None
                )
                if (
                    observed_error is None
                    and replay_revision is not None
                    and replay_revision.source_object_sha256
                    not in seen_revisions
                    and replay_revision.source_object_sha256
                    not in {
                        str(
                            envelope.lineage.get(
                                "forecast_source_object_sha256"
                            ) or ""
                        )
                        for envelope, _decision in observed_pending
                    }
                ):
                    # Only where trading can still happen.
                    try:
                        replay_day_state = event_day_window(
                            day,
                            as_of_utc=as_of_utc,
                            target_timezone=root.settlement_timezone,
                        )["state"]
                    except Exception:  # noqa: BLE001 -- unreadable is not replayable
                        replay_day_state = "closed"
                    if replay_day_state not in {"open", "not_started"}:
                        replay_skip_state = "REPLAY_SKIPPED_SETTLED_DAY"
                    elif replays_this_cycle >= MAX_P0M_REPLAYS_PER_CYCLE:
                        replays_deferred.append(f"{station}|{day}")
                        replay_skip_state = "REPLAY_DEFERRED_CYCLE_BUDGET"
                    else:
                        replays_this_cycle += 1
                        # Now: the forecaster spoke once; what happened just
                        # now is that the model moved and this confirmation was
                        # re-made against the forecast being served.  The
                        # text's own issued/received clocks stay on the
                        # revision; only the computation is dated now.
                        decision_at = _p0m_replay_decision_at(
                            as_of_utc,
                            after_decision_utc=(
                                observed_predecessor.decision_at_utc
                            ),
                        )
                        try:
                            observed = _observe(
                                replay_revision,
                                decision_at,
                                observed_predecessor,
                            )
                        except Exception as exc:  # noqa: BLE001
                            observed_error = f"ContractError:{exc}"[:200]
                            observed = None
                        if observed is not None:
                            observed_pending.append((observed, decision_at))
                            observed_predecessor = observed
                observed_writes = []
                if observed_pending and observed_error is None:
                    with _writer_transaction(
                        self.commit_conn,
                        savepoint="resident_taf_observed_scope",
                    ):
                        for envelope, decision_at in observed_pending:
                            observed_writes.append(
                                insert_probability_envelope(
                                    self.commit_conn,
                                    envelope,
                                    created_at_utc=decision_at,
                                )
                            )
                observed_count = sum(
                    1 for write in observed_writes
                    if write.get("wrote") is True
                )
                for _envelope, written_at in (
                    observed_pending if observed_writes else ()
                ):
                    if p0m_stage_clock_utc is None or timestamp_lt(
                        p0m_stage_clock_utc, written_at
                    ):
                        p0m_stage_clock_utc = written_at
                if (
                    not observed_count
                    and observed_error is None
                    and replay_skip_state is not None
                ):
                    receipts.append(self._p0m_no_op_receipt(
                        station_id=station,
                        event_date=day,
                        state=replay_skip_state,
                    ))
                    continue
                receipts.append({
                    "station_id": station,
                    "event_date": day,
                    "state": (
                        "COMMITTED_OBSERVED_NO_ARTIFACT"
                        if observed_count
                        else "OBSERVED_PATH_REFUSED"
                        if observed_error
                        # The root or the TAF has too little life left to lend
                        # a confirmation: the scope waits for the next P0 or
                        # the next issuance.
                        else "CONFIRMATION_WINDOW_EXHAUSTED"
                        if window_refusals
                        else "NO_NEW_TAF_REVISION"
                    ),
                    **(
                        {"observed_reason": observed_error}
                        if observed_error else {}
                    ),
                    **(
                        {"window_refused_revision_ids": window_refusals[:8]}
                        if window_refusals else {}
                    ),
                    "write_count": observed_count,
                    "writes": observed_writes,
                })
            except Exception as exc:
                blockers.append({
                    "station_id": station,
                    "event_date": day,
                    "reason": f"{type(exc).__name__}:{exc}",
                })
            assert_process_memory_budget()
        self._add_span(
            "p0m_scope_loop",
            (time.perf_counter() - _p0m_loop_started) * 1000.0,
            label=f"{len(captures_by_scope)} scopes",
        )
        # Where the cheap verdict and the real receipt disagreed, and on what.
        # Reported rather than acted on: this is the evidence the switch is
        # waiting for.
        shadow_report: dict[str, Any] | None = None
        if P0M_FAST_PATH_MODE != "off":
            actual = {
                (str(item.get("station_id")), str(item.get("event_date"))):
                item
                for item in receipts
            }
            agreed = 0
            disagreed: list[dict[str, Any]] = []
            for scope, verdict in shadow_verdicts.items():
                real = actual.get(scope)
                if real is None:
                    # The scope raised before it produced a receipt; the
                    # blocker already records that and the shadow has nothing
                    # to say about it.
                    continue
                if verdict is None:
                    # The cheap path declined to answer, which is never wrong.
                    agreed += 1
                    continue
                # The whole receipt, not just its state: a fast path that
                # picks the right word and the wrong dropped-capture count is
                # still a fast path that changed the record.
                if verdict == real:
                    agreed += 1
                    continue
                disagreed.append({
                    "station_id": scope[0],
                    "event_date": scope[1],
                    "shadow": verdict,
                    "actual": {
                        key: value for key, value in real.items()
                        if key != "writes"
                    },
                })
            shadow_report = {
                "schema": "bayes_basket_target_p0m_fast_path_shadow_v1",
                "mode": P0M_FAST_PATH_MODE,
                "scopes": len(shadow_verdicts),
                "agreed": agreed,
                "disagreed_count": len(disagreed),
                "shadow_would_skip": sum(
                    1 for verdict in shadow_verdicts.values()
                    if verdict is not None
                    and str(verdict.get("state") or "").startswith(
                        ("NO_NEW_TAF_REVISION", "IGNORED_NO_P0")
                    )
                ),
                "shadow_error_count": len(shadow_errors),
                "disagreed": disagreed[:8],
                "shadow_errors": shadow_errors[:4],
            }
        return {
            "schema": "bayes_basket_target_resident_taf_ingress_v1",
            **(
                {"fast_path_shadow": shadow_report}
                if shadow_report is not None else {}
            ),
            "state": "BLOCKED_FAIL_CLOSED" if blockers else "COMMITTED",
            "taf_fact_ingress": taf_fact_ingress,
            "receipts": receipts,
            "blockers": blockers,
            "ignored_inactive_scope_count": ignored_inactive_scope_count,
            "ignored_no_artifact_scope_count":
                ignored_no_artifact_scope_count,
            # The size and reach of the set this stage walks, because the
            # stage's cost is a function of them and nothing reported either.
            # This lane's cost went 168 scopes (2026-08-22) to 389
            # (2026-09-01) to 498 (2026-09-07) while the inbox filled to its
            # 2048-capture ceiling and came to span thirteen event days --
            # and every profile in between reported only the seconds, so the
            # growth read as a mystery regression instead of as a window
            # that had stopped being forward-only.  Measured the same day:
            # 447 of the 498 are closed days that skip before anything is
            # read, so the count that matters is not the total.
            "scope_count": len(captures_by_scope),
            "inbox_capture_count": len(raw_captures),
            "inbox_event_date_span": sorted({
                str(day) for _station, day in captures_by_scope
            })[:1] + sorted({
                str(day) for _station, day in captures_by_scope
            })[-1:],
            # Counted, not inferred.  A replay budget that silently drops
            # scopes reads exactly like a replay that never fired.
            "replays_this_cycle": replays_this_cycle,
            "replay_budget": MAX_P0M_REPLAYS_PER_CYCLE,
            "replays_deferred": replays_deferred[:20],
            "replays_deferred_count": len(replays_deferred),
            "refused_capture_count": len(refused_captures),
            "refused_captures": refused_captures[:20],
            "stage_clock_utc": p0m_stage_clock_utc,
            "writes_target_ssot": any(
                item["write_count"] > 0 for item in receipts
            ),
            "places_orders": False,
            "calls_order_gateway": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }

    def materialize_resident_p0(
        self,
        *,
        as_of_utc: str,
    ) -> dict[str, Any]:
        """Append fresh forward NWP bundles from the bounded P0 inbox."""

        if self.commit_conn is None:
            return {
                "state": "not_attempted",
                "reason": "target_atomic_writer_not_injected",
                "writes_target_ssot": False,
            }
        if not self.p0_inbox_path.is_file():
            return {
                "state": "not_configured",
                "reason": "resident_p0_inbox_missing",
                "writes_target_ssot": False,
            }
        inbox = load_bounded_json(self.p0_inbox_path)
        if (
            not isinstance(inbox, Mapping)
            or inbox.get("schema")
            != "bayes_basket_target_p0_inbox_v1"
        ):
            raise ContractError("resident_p0_inbox_schema_invalid")
        rows = inbox.get("packets")
        if not isinstance(rows, list) or len(rows) > 256:
            raise ContractError("resident_p0_inbox_packet_count_invalid")
        if not rows:
            return {
                "schema": "bayes_basket_target_resident_p0_ingress_v1",
                "state": "BLOCKED_FAIL_CLOSED",
                "reason": "FAIL_CLOSED_NO_P0:"
                "native_cross_ensemble_activation_missing",
                "receipts": [],
                "blockers": [{
                    "reason": "FAIL_CLOSED_NO_P0:"
                    "native_cross_ensemble_activation_missing",
                }],
                "writes_target_ssot": False,
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
        receipts: list[dict[str, Any]] = []
        blockers: list[dict[str, str]] = []
        pending_envelopes: list[ProbabilityEnvelope] = []
        pending_proofs: dict[str, dict[str, Any]] = {}
        pending_by_scope_clock: dict[
            tuple[str, str, str], ProbabilityEnvelope
        ] = {}
        for raw in rows:
            try:
                if not isinstance(raw, Mapping):
                    raise ContractError("resident_p0_inbox_row_invalid")
                packet = raw.get("packet")
                if (
                    raw.get("source_class")
                    != "calibrated_native_cross_ensemble"
                    or not isinstance(packet, Mapping)
                ):
                    raise ContractError(
                        "resident_p0_calibrated_native_cross_ensemble_required"
                    )
                if str(packet.get("stage") or "") != "P0":
                    # A confirm-stage (P0-M) compile shares the inbox but
                    # belongs to the P0-M lane, which supplies its own
                    # predecessor and TAF revision chain.  This lane refusing
                    # to skip it turned one confirm packet into a network-wide
                    # P0 materialization outage: the whole ingress fail-closed
                    # on ``materialization_predecessor_missing`` and healthy
                    # P0 packets behind it never materialized.
                    receipts.append({
                        "station_id": str(packet.get("station_id") or ""),
                        "event_date": str(packet.get("event_date") or ""),
                        "state": "SKIPPED_NON_P0_STAGE",
                        "stage": str(packet.get("stage") or ""),
                    })
                    continue
                if (
                    packet.get("probability_pathway")
                    != P0_PROBABILITY_PATHWAY
                ):
                    raise ContractError(
                        "resident_p0_probability_pathway_invalid"
                    )
                if str(raw.get("packet_content_sha256") or "") != content_sha256(packet):
                    raise ContractError(
                        "resident_p0_packet_content_sha_mismatch"
                    )
                envelope = build_probability_envelope(packet)
                lineage = envelope.lineage
                provider = str(
                    lineage.get("native_transport_provider") or ""
                )
                if provider in {
                    "OFFICIAL_NATIVE_SAME_CYCLE_SNAPSHOT",
                    "OFFICIAL_NATIVE_MIXED_CYCLE_SNAPSHOT",
                }:
                    pass
                elif (
                    provider == "OPEN_METEO"
                    and str(lineage.get(
                        "aggregator_fallback_p0_eligible"
                    ) or "").lower() == "true"
                    and str(lineage.get(
                        "republisher_fallback_p0_eligible"
                    ) or "").lower() == "true"
                    and str(lineage.get("transport_lineage_class") or "")
                    == "aggregator_republisher"
                    and str(lineage.get(
                        "native_arrival_index_eligible"
                    ) or "").lower() == "false"
                    and str(lineage.get(
                        "native_formal_p0_eligible"
                    ) or "").lower() == "false"
                ):
                    pass
                else:
                    raise ContractError(
                        "resident_p0_native_transport_required"
                    )
                settlement_end = (
                    datetime.fromisoformat(envelope.event_date)
                    .replace(
                        tzinfo=ZoneInfo(
                            envelope.settlement_timezone
                        )
                    )
                    + timedelta(days=1)
                ).astimezone(timezone.utc)
                if settlement_end <= datetime.fromisoformat(
                    as_of_utc.replace("Z", "+00:00")
                ).astimezone(timezone.utc):
                    receipts.append({
                        "station_id": envelope.station_id,
                        "event_date": envelope.event_date,
                        "state": "IGNORED_CLOSED_SETTLEMENT_SCOPE",
                        "wrote": False,
                    })
                    continue
                proof_raw = packet.get("p0_historical_tilt_proof")
                if (
                    not isinstance(proof_raw, Mapping)
                    and envelope.posterior_version
                    == "p0_nwp_historical_meta_anchor_v4"
                ):
                    raise ContractError(
                        "resident_p0_historical_tilt_proof_required"
                    )
                if envelope.stage != "P0":
                    raise ContractError("resident_p0_stage_invalid")
                if envelope.decision_at_utc > as_of_utc:
                    raise ContractError(
                        "resident_p0_future_decision_forbidden"
                    )
                if not envelope.is_fresh(as_of_utc):
                    # Expired in the handoff inbox, not malformed: it cannot
                    # become a servable P0 and must not stop the ones that
                    # can.  Raising here failed the whole bounded inbox --
                    # every station's P0 -- on one packet whose window closed
                    # between its compile and this write, and the seated
                    # evidence clock (``seated_evidence_received_at``) makes
                    # windows that close earlier than the packet clock did.
                    # The upsert prunes such rows when it next runs; this is
                    # for the cycles where nothing else compiled.
                    receipts.append({
                        "station_id": envelope.station_id,
                        "event_date": envelope.event_date,
                        "state": "IGNORED_EXPIRED_IN_INBOX",
                        "wrote": False,
                        "fresh_until_utc": envelope.fresh_until_utc,
                    })
                    continue
                scope_clock = (
                    envelope.station_id,
                    envelope.event_date,
                    envelope.decision_at_utc,
                )
                previous_pending = pending_by_scope_clock.get(scope_clock)
                if previous_pending is not None:
                    if (
                        previous_pending.content_sha256
                        != envelope.content_sha256
                    ):
                        raise ContractError(
                            "resident_p0_scope_content_conflict"
                        )
                    continue
                # Charter 179: ``+stage`` -- see probability_bridge's
                # restatement read; the recency index has no event_date.
                existing = self.commit_conn.execute(
                    "SELECT checkpoint_id,content_sha256 FROM basket_probability_envelope "
                    "WHERE station_id=? AND event_date=? AND +stage='P0' "
                    "AND state='COMMITTED' ORDER BY decision_at_utc DESC "
                    "LIMIT 1",
                    (envelope.station_id, envelope.event_date),
                ).fetchone()
                if existing is not None:
                    existing_checkpoint = str(existing[0] or "")
                    existing_content = str(existing[1] or "")
                    existing_row = self.commit_conn.execute(
                        "SELECT decision_at_utc FROM basket_probability_envelope "
                        "WHERE checkpoint_id=?",
                        (existing_checkpoint,),
                    ).fetchone()
                    existing_decision = str(
                        existing_row[0] or ""
                    ) if existing_row is not None else ""
                    if existing_decision == envelope.decision_at_utc:
                        if existing_content != envelope.content_sha256:
                            existing_envelope = (
                                _stored_probability_envelope(
                                    self.commit_conn,
                                    checkpoint_id=existing_checkpoint,
                                )
                            )
                            if not _p0_bridge_only_semantic_equivalent(
                                existing_envelope,
                                envelope,
                            ):
                                raise ContractError(
                                    "resident_p0_scope_content_conflict"
                                )
                            receipts.append({
                                "station_id": envelope.station_id,
                                "event_date": envelope.event_date,
                                "state": (
                                    "ALREADY_COMMITTED_EQUIVALENT_"
                                    "BRIDGE_UPGRADE"
                                ),
                                "wrote": False,
                                "existing_checkpoint_id": (
                                    existing_checkpoint
                                ),
                            })
                            continue
                        receipts.append({
                            "station_id": envelope.station_id,
                            "event_date": envelope.event_date,
                            "state": "ALREADY_COMMITTED",
                            "wrote": False,
                        })
                        continue
                    if existing_decision > envelope.decision_at_utc:
                        receipts.append({
                            "station_id": envelope.station_id,
                            "event_date": envelope.event_date,
                            "state": "STALE_MODEL_BUNDLE",
                            "wrote": False,
                        })
                        continue
                pending_by_scope_clock[scope_clock] = envelope
                pending_envelopes.append(envelope)
                if isinstance(proof_raw, Mapping):
                    pending_proofs[envelope.checkpoint_id] = dict(
                        proof_raw
                    )
            except Exception as exc:
                blockers.append({
                    "reason": f"{type(exc).__name__}:{exc}",
                })
            assert_process_memory_budget()
        # Validate the complete bounded inbox before its first write.  One
        # malformed packet must not leave unrelated P0 roots committed.
        if not blockers:
            try:
                committed_receipts: list[dict[str, Any]] = []
                with _writer_transaction(
                    self.commit_conn,
                    savepoint="resident_p0_inbox",
                ):
                    for envelope in pending_envelopes:
                        proof = pending_proofs.get(
                            envelope.checkpoint_id
                        )
                        if proof is not None:
                            p0_proof_started = time.perf_counter()
                            insert_probability_update_proof(
                                self.commit_conn,
                                {
                                "proof_id": proof["proof_id"],
                                "proof_kind": "P0_HISTORICAL_TILT",
                                "station_id": envelope.station_id,
                                "event_date": envelope.event_date,
                                "settlement_timezone": (
                                    envelope.settlement_timezone
                                ),
                                "prediction_root_checkpoint_id": (
                                    envelope.checkpoint_id
                                ),
                                "artifact_id_or_none": proof[
                                    "meta_artifact_id"
                                ],
                                "activation_id_or_none": proof[
                                    "meta_activation_id"
                                ],
                                "canonical_sequence_sha256_or_none": (
                                    "NONE"
                                ),
                                "decision_at_utc": (
                                    envelope.decision_at_utc
                                ),
                                "proof": proof,
                                "content_sha256": proof[
                                    "content_sha256"
                                ],
                                },
                            )
                            self._add_span(
                                "p0_insert_proof",
                                (
                                    time.perf_counter() - p0_proof_started
                                ) * 1000.0,
                                label=envelope.station_id,
                            )
                        with self._span(
                            "p0_insert_envelope",
                            label=(
                                f"{envelope.station_id}"
                                f"|{envelope.event_date}"
                            ),
                        ):
                            write = insert_probability_envelope(
                                self.commit_conn,
                                envelope,
                                created_at_utc=envelope.decision_at_utc,
                            )
                        committed_receipts.append({
                            "station_id": envelope.station_id,
                            "event_date": envelope.event_date,
                            "state": "COMMITTED",
                            "wrote": bool(write.get("wrote")),
                            "checkpoint_id": envelope.checkpoint_id,
                        })
                receipts.extend(committed_receipts)
            except Exception as exc:
                blockers.append({
                    "reason": f"{type(exc).__name__}:{exc}",
                })
        return {
            "schema": "bayes_basket_target_resident_p0_ingress_v1",
            "state": "BLOCKED_FAIL_CLOSED" if blockers else "COMMITTED",
            "receipts": receipts,
            "blockers": blockers,
            "writes_target_ssot": any(
                item.get("wrote") is True for item in receipts
            ),
            "places_orders": False,
            "calls_order_gateway": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }

    def _materialize_resident_probability_chain(
        self,
        *,
        as_of_utc: str,
    ) -> dict[str, Any]:
        """Run the only resident probability event chain in stage order.

        The daemon may refresh bounded NWP/TAF inboxes before this method is
        called.  This method alone owns their SSOT handoff order:
        NWP/P0 -> TAF physical confirmation/P0-M -> METAR/SPECI/P1.  Each
        stage remains its own atomic append transaction, while the returned
        receipt makes the order and no-live boundary explicit to the caller.
        """

        # The chain is the cycle's largest pre-loop cost (239s measured
        # 2026-08-16) and reported one number for three stages, so which of
        # them owns it was unknown.  Mark each: the stages run in a fixed
        # order and never overlap, so the three spans sum to what the single
        # ``probability_chain`` mark used to report.
        early = getattr(self, "_early_p1_this_cycle", None)
        early_ran = isinstance(early, Mapping) and early.get("ran") is True
        rowid_mark = self._envelope_rowid_ceiling() if early_ran else None
        p0 = self.materialize_resident_p0(as_of_utc=as_of_utc)
        self._mark("probability_p0")
        taf_mark = _taf_inbox_watermark(getattr(self, "taf_inbox_path", None))
        p0m = self._materialize_resident_p0m(as_of_utc=as_of_utc)
        if (
            taf_mark is not None
            and str((p0m or {}).get("state") or "").upper() != "BLOCKED_FAIL_CLOSED"
        ):
            # The next head pass runs only for a TAF landed after this read.
            self._p0m_covered_taf_watermark = taf_mark
        self._mark("probability_p0m")
        stage_clock = (
            p0m.get("stage_clock_utc") if isinstance(p0m, Mapping) else None
        )
        if not early_ran:
            p1 = self._materialize_resident_p1(
                as_of_utc=as_of_utc,
                stage_clock_utc=stage_clock,
            )
        else:
            # The head of the cycle already ran P1 over every scope on the
            # roots committed before it.  What it could not see is a root
            # this chain has just rebuilt; those scopes re-root here, exactly
            # as the single pass would have, and nothing else is read twice.
            rerooted = self._scopes_rooted_after(rowid_mark)
            late = (
                self._materialize_resident_p1(
                    as_of_utc=as_of_utc,
                    stage_clock_utc=stage_clock,
                    only_scopes=set(rerooted),
                )
                if rerooted else None
            )
            p1 = _merge_resident_p1_receipts(
                early["p1"], late, late_scopes=rerooted
            )
        self._mark("probability_p1")
        blocked_stages = [
            stage
            for stage, receipt in (("P0", p0), ("P0-M", p0m), ("P1", p1))
            if str(receipt.get("state") or "").upper()
            == "BLOCKED_FAIL_CLOSED"
        ]
        return {
            "schema": "bayes_basket_target_resident_probability_chain_v1",
            "stage_order": ["P0", "P0-M", "P1"],
            "state": (
                "BLOCKED_FAIL_CLOSED" if blocked_stages else "COMMITTED"
            ),
            "blocked_stages": blocked_stages,
            "as_of_utc": as_of_utc,
            "p0": p0,
            "p0m": p0m,
            "p1": p1,
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }

    def _envelope_rowid_ceiling(self) -> int:
        """The envelope table's newest rowid; append-only, so a watermark."""

        return int(self.commit_conn.execute(
            "SELECT COALESCE(MAX(rowid),0) FROM basket_probability_envelope"
        ).fetchone()[0])

    def _scopes_rooted_after(self, after_rowid: int | None) -> list[tuple[str, str]]:
        """Station-days that gained a committed P0 or P0-M past ``after_rowid``.

        A rowid range seek; ``stage`` and ``state`` are filtered here rather
        than in SQL for the reason ``_fresh_committed_envelope_scopes`` gives.
        """

        if after_rowid is None:
            return []
        scopes: set[tuple[str, str]] = set()
        for station_id, event_date, stage, state in self.commit_conn.execute(
            "SELECT station_id,event_date,stage,state"
            " FROM basket_probability_envelope WHERE rowid>?",
            (int(after_rowid),),
        ):
            if state == "COMMITTED" and stage in ("P0", "P0-M"):
                scopes.add((
                    str(station_id or "").strip().upper(),
                    str(event_date or "").strip(),
                ))
        return sorted(scope for scope in scopes if all(scope))

    def _identify_live_observations_for_chain(self) -> dict[str, Any]:
        """The identity pass at the chain's position, whenever a report landed.

        Until 2026-10-04 this skipped whenever the head pass had run or found
        nothing uncovered, on the premise that the chain's P1 reads reports
        as of the head's clock.  It does not: the chain reads as of its own
        clock, taken after the intent reconcile and the cash-phase flush, so
        a report that landed in between went into the chain's P1 with no
        identity pass behind it.  Its envelope carried no truth-revision
        hash and the atomic-fact gate refused that station-day until the
        next report (SAEZ 11:16:16Z: cycle head 11:16:15, P1 in the chain
        at 11:16:37, no identity pass that cycle; 68 such P1s on 10-03).

        The pass decides for itself: it reads the archive watermark now --
        after the chain's clock -- and skips at no cost when nothing landed
        since the pass it last staged, and otherwise runs the subset for the
        stations that moved (charter 181), a few seconds.
        """

        head = getattr(self, "_early_p1_this_cycle", None)
        receipt = dict(self._identify_live_observations())
        receipt["head_pass_state"] = str((head or {}).get("state") or "")
        return receipt

    def _materialize_early_p0m(
        self,
        *,
        as_of_utc: str,
        taf_watermark: tuple[int, str] | None,
        force: bool = False,
    ) -> dict[str, Any]:
        """The fast lane: P0-M at the head of the cycle, for TAFs it has not seen.

        Runs only when the TAF inbox moved since the last P0-M pass covered it,
        on the roots already committed.  Never raises: anything short of a
        clean pass leaves the chain's own P0-M to do it, as before.
        ``new_envelopes`` says whether it committed anything, which is what
        forces the head P1 to re-root on it.

        ``force`` (charter 195): a checkpoint has just committed new P0 roots,
        so P0-M re-seats on them even though no TAF moved.
        """

        boundary = {
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }
        if not EARLY_P0M_ENABLED:
            return {"state": "DISABLED", "ran": False, **boundary}
        if taf_watermark is None:
            return {"state": "SKIPPED_INBOX_UNREADABLE", "ran": False, **boundary}
        if (
            not force
            and getattr(self, "_p0m_covered_taf_watermark", None) == taf_watermark
        ):
            return {"state": "SKIPPED_NO_NEW_TAF", "ran": False, **boundary}
        started = time.perf_counter()
        try:
            before = self._envelope_rowid_ceiling()
            p0m = self._materialize_resident_p0m(as_of_utc=as_of_utc)
            after = self._envelope_rowid_ceiling()
        except Exception as exc:  # noqa: BLE001 -- the chain's pass is the fallback
            return {
                "state": "FAILED",
                "ran": False,
                "reason": f"{type(exc).__name__}:{str(exc)[:200]}",
                "duration_sec": round(time.perf_counter() - started, 3),
                **boundary,
            }
        state = str((p0m or {}).get("state") or "")
        if state.upper() != "BLOCKED_FAIL_CLOSED":
            self._p0m_covered_taf_watermark = taf_watermark
        return {
            "state": "RAN",
            "ran": True,
            "p0m_state": state,
            "new_envelopes": after > before,
            "rowid_before": before,
            # The latest decision this pass stamped: a P0-M rebuilt on a root
            # minted at this clock is seated a millisecond after it, and the
            # P1 that follows reads its root as of this, as the chain does.
            "stage_clock_utc": (p0m or {}).get("stage_clock_utc"),
            "duration_sec": round(time.perf_counter() - started, 3),
            **boundary,
        }

    def _copy_follow_if_due(self, label: str) -> dict[str, Any] | None:
        """Charter 257 补记三: the copy-follow lane at a safe writer checkpoint.

        The cluster's fills reach the resident through the fast feed (its own
        read-only executor, every 15 s); this is where the writer acts on
        them mid-cycle instead of at the next head or tail -- the head and the
        tail runs stay, and every write is idempotent on the source key and
        the intent id.  Never raises: the cycle is not the lane's to stop.
        """

        if PRODUCTION_EXECUTION_MODE != "production_live":
            return None
        connection = getattr(self, "commit_conn", None)
        if connection is None or getattr(connection, "in_transaction", False):
            return None
        from .copy_follow_feed import FEED  # noqa: PLC0415
        from .strategy_lanes import LANE_COPY_FOLLOW, lane_enabled  # noqa: PLC0415

        now = time.monotonic()
        last = getattr(self, "_last_copy_follow_check_mono", None)
        seen = getattr(self, "_copy_follow_seen_feed_version", None)
        if last is not None:
            since = now - float(last)
            if since < COPY_FOLLOW_CHECK_INTERVAL_SEC:
                return None
            if FEED.version == seen and since < COPY_FOLLOW_IDLE_RECHECK_SEC:
                return None
        if not lane_enabled(LANE_COPY_FOLLOW):
            return None
        self._last_copy_follow_check_mono = now
        self._copy_follow_seen_feed_version = FEED.version
        started = time.perf_counter()
        try:
            from .copy_follow_lane import execute_copy_follow  # noqa: PLC0415
            from .exit_orders import default_transport  # noqa: PLC0415

            receipt = execute_copy_follow(
                connection,
                getattr(self, "canonical_source_conn", None),
                transport=default_transport,
                now_utc=utc_now(),
                live_submit_authorized=True,
                ws_manifest_path=getattr(self, "market_manifest_path", None),
                feed=FEED,
                # Charter 264: inside the cycle the lane reads the feed only;
                # an uncovered wallet waits for the head or the tail.
                api_fallback=False,
            )
        except Exception as exc:  # noqa: BLE001 -- a lane failure is a receipt
            receipt = {"ok": False, "error": f"{type(exc).__name__}:{str(exc)[:200]}"}
        receipt = {**receipt, "reason": f"checkpoint:{label}"}
        receipts = getattr(self, "_copy_follow_receipts", None)
        if not isinstance(receipts, list):
            receipts = []
            self._copy_follow_receipts = receipts
        receipts.append({k: receipt.get(k) for k in (
            "reason", "state", "planned", "submitted", "filled", "refusals", "error", "ok")})
        del receipts[:-20]
        self._add_span("copy_follow_checkpoint", (time.perf_counter() - started) * 1000.0, label=label)
        return receipt

    def _fast_lane_official_p0(
        self,
        *,
        as_of_utc: str,
        official_watermark: tuple[int, str] | None,
        materialize: bool,
    ) -> dict[str, Any]:
        """Charter 195 (一): compile the runs a capture merged mid-cycle.

        The same compile, persistence and P0-inbox upsert the cycle's replay
        compile runs (``native_p0_replay_compile``), restricted to the official
        packets whose snapshot differs from the one that pass (or an earlier
        checkpoint) compiled for the scope; station, date and activation
        scope are the replay's own.  With ``materialize`` -- the chain has run
        this cycle -- the new packets are committed as P0 now, and the caller
        re-seats P0-M and P1 on them.  Before the chain they only reach the P0
        inbox, which the chain's own P0 stage then reads in order.

        Never raises: the next cycle's replay compile remains the fallback.
        """

        boundary = {
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }
        started = time.perf_counter()
        compiled_shas: dict[tuple[str, str], str] = getattr(
            self, "_p0_replay_compiled_shas", None
        ) or {}
        self._p0_replay_compiled_shas = compiled_shas
        active = getattr(self, "_p0_replay_active_stations", None)
        compiled: list[dict[str, Any]] = []
        failures: list[dict[str, Any]] = []
        candidates = 0
        try:
            packets = _load_native_forward_inbox(
                self.nwp_runtime_root
                / "official_native_ensemble_forward_inbox.json",
                error_code="official_native_forward_inbox_invalid",
            )
            now_dt = datetime.fromisoformat(
                as_of_utc.replace("Z", "+00:00")
            ).astimezone(timezone.utc)
            for packet in packets:
                if (
                    str(packet.get("schema") or "")
                    != OFFICIAL_NATIVE_FORWARD_PACKET_SCHEMA
                    or not _forward_packet_in_cycle_scope(
                        packet,
                        station_allowlist=tuple(
                            getattr(self, "station_allowlist", ())
                        ),
                        event_date_allowlist=tuple(
                            getattr(self, "event_date_allowlist", ())
                        ),
                    )
                ):
                    continue
                station = str(packet.get("station_id") or "").strip().upper()
                event_date = str(packet.get("event_date") or "")
                snapshot = str(packet.get("snapshot_content_sha256") or "")
                if not station or not event_date or not snapshot:
                    continue
                if active is not None and station not in active:
                    continue
                if compiled_shas.get((station, event_date)) == snapshot:
                    continue
                try:
                    closes_at = datetime.fromisoformat(
                        str(
                            settlement_day_window(
                                event_date,
                                str(packet.get("settlement_timezone") or ""),
                            )["target_day_end_utc"]
                        ).replace("Z", "+00:00")
                    ).astimezone(timezone.utc)
                except Exception:
                    continue
                if closes_at <= now_dt:
                    continue
                candidates += 1
                # Attempted, not just succeeded: a packet the compiler refuses
                # is refused again at every checkpoint, and the next cycle's
                # replay compile retries it anyway.
                compiled_shas[(station, event_date)] = snapshot
                result, reasons, _source = (
                    _compile_native_p0_with_republisher_fallback(
                        self.commit_conn,
                        scope=(station, event_date),
                        preferred_packet=packet,
                        official_packet=packet,
                        republisher_packet=None,
                        decision_at_utc=as_of_utc,
                        native_oos_snapshot=self.native_oos_snapshot,
                    )
                )
                if result is None:
                    failures.extend(reasons)
                    continue
                result["forward_prediction_persistence"] = (
                    persist_native_ensemble_forward_prediction(
                        self.commit_conn, result
                    )
                )
                compiled.append(result)
            merge = (
                _upsert_native_p0_inbox(
                    self.p0_inbox_path,
                    compiled_packets=compiled,
                    generated_at_utc=as_of_utc,
                )
                if compiled else None
            )
            before = after = None
            p0_state = None
            if materialize and compiled:
                before = self._envelope_rowid_ceiling()
                p0 = self.materialize_resident_p0(as_of_utc=as_of_utc)
                after = self._envelope_rowid_ceiling()
                p0_state = str((p0 or {}).get("state") or "")
        except Exception as exc:  # noqa: BLE001 -- the replay compile is the fallback
            return {
                "state": "FAILED",
                "reason": f"{type(exc).__name__}:{str(exc)[:200]}",
                "candidate_count": candidates,
                "compiled_count": len(compiled),
                "new_envelopes": False,
                "duration_sec": round(time.perf_counter() - started, 3),
                **boundary,
            }
        self._p0_covered_official_watermark = official_watermark
        return {
            "state": "RAN",
            "candidate_count": candidates,
            "compiled_count": len(compiled),
            "failure_count": len(failures),
            "p0_inbox_accepted": int((merge or {}).get("accepted_count") or 0),
            "p0_state": p0_state,
            "new_envelopes": (
                before is not None and after is not None and after > before
            ),
            "rowid_before": before,
            "duration_sec": round(time.perf_counter() - started, 3),
            **boundary,
        }

    def _fast_lane_checkpoint(
        self, label: str, *, mark: bool = True
    ) -> dict[str, Any] | None:
        """Update, mid-cycle, only what landed since the last pass covered it.

        P0-M when the TAF inbox content moved -- once the chain has settled
        the roots, so the pass has only the new bulletins to seat.  P1 for
        the stations with a report past the covered watermark and for the
        scopes a new P0-M re-rooted.  Returns None, having marked nothing,
        when neither moved.  Never raises: both passes catch their own
        failures, and the chain and the next head remain the fallback.
        """

        if not FAST_LANE_CHECKPOINTS_ENABLED:
            return None
        started = time.perf_counter()
        # Charter 165: the re-armed checkpoints read these two.  A pass that
        # found nothing still counts as a check -- the watermark read is the
        # cost being rationed -- and the clock is stamped again on the way
        # out, so the next wait starts from when this pass ENDED and knows
        # what it cost.
        self._last_fast_lane_checkpoint_mono = time.monotonic()
        self._last_fast_lane_checkpoint_cost_sec = 0.0
        chain_ran = bool(getattr(self, "_probability_chain_ran", False))
        taf_mark = _taf_inbox_watermark(getattr(self, "taf_inbox_path", None))
        archive = getattr(self, "canonical_source_conn", None)
        report_mark = _live_observation_watermark(archive)
        covered = getattr(self, "_p1_covered_watermark", None)
        new_taf = (
            chain_ran
            and taf_mark is not None
            and taf_mark != getattr(self, "_p0m_covered_taf_watermark", None)
        )
        new_reports = (
            report_mark is not None
            and report_mark != covered
            and _later_report_watermark(covered, report_mark) != covered
        )
        # Charter 195 (一): the official-native inbox moved since the replay
        # compile covered it -- a capture merged a run mid-cycle.  Read before
        # the clock (charter 148's order), like the two marks above.
        nwp_covered = getattr(self, "_p0_covered_official_watermark", None)
        nwp_mark = (
            _official_inbox_watermark(
                self.nwp_runtime_root
                / "official_native_ensemble_forward_inbox.json"
            )
            if FAST_LANE_NWP_P0_ENABLED and nwp_covered is not None
            else None
        )
        new_nwp = nwp_mark is not None and nwp_mark != nwp_covered
        if not new_taf and not new_reports and not new_nwp:
            return None
        clock = utc_now()
        nwp = (
            self._fast_lane_official_p0(
                as_of_utc=clock,
                official_watermark=nwp_mark,
                materialize=chain_ran,
            )
            if new_nwp else None
        )
        # A new P0 root moves every P0-M built on the old one, so P0-M runs
        # after it whether or not a TAF landed -- once, covering both.
        p0m = (
            self._materialize_early_p0m(
                as_of_utc=clock,
                taf_watermark=taf_mark,
                force=bool((nwp or {}).get("new_envelopes")),
            )
            if new_taf or (nwp or {}).get("new_envelopes") else None
        )
        scopes: set[tuple[str, str]] | None = set()
        if new_reports:
            stations = _stations_with_reports_after(archive, covered)
            scopes = (
                None if stations is None
                else _scopes_for_stations(stations, as_of_utc=clock)
            )
        if scopes is not None and (nwp or {}).get("new_envelopes"):
            scopes |= set(self._scopes_rooted_after(nwp.get("rowid_before")))
        if scopes is not None and (p0m or {}).get("new_envelopes"):
            scopes |= set(self._scopes_rooted_after(p0m.get("rowid_before")))
        p1 = None
        if scopes is None or scopes:
            # The P0-M this pass rebuilt on a root minted at ``clock`` sits at
            # clock + 1 ms; read as of ``clock`` alone, P1 missed it and
            # rooted on the bare P0 until the next pass (charter 150 (三): at
            # a TAF station the root is P0-M).
            p1 = self._materialize_early_p1(
                as_of_utc=clock, report_watermark=report_mark, force=True,
                only_scopes=scopes,
                stage_clock_utc=(p0m or {}).get("stage_clock_utc"),
            )
            if p1.get("ran") and new_reports:
                p1_state = str(((p1.get("p1") or {}).get("state")) or "").upper()
                if p1_state != "BLOCKED_FAIL_CLOSED":
                    self._p1_covered_watermark = _later_report_watermark(
                        getattr(self, "_p1_covered_watermark", None), report_mark
                    )
                    self._early_p1_watermark = _later_report_watermark(
                        getattr(self, "_early_p1_watermark", None), report_mark
                    )
        # A checkpoint inside the decision loop commits envelopes a later
        # scope in the same loop may price: give them their companions now.
        self._regime_catch_up(label=f"checkpoint_{label}")
        receipt = {
            "label": label,
            "at_utc": clock,
            "scopes": None if scopes is None else len(scopes),
            "nwp_p0": nwp,
            "p0m": {k: v for k, v in (p0m or {}).items() if k != "p0m"} or None,
            "p1": {k: v for k, v in (p1 or {}).items() if k != "p1"} or None,
        }
        receipts = getattr(self, "_fast_lane_receipts", None)
        if not isinstance(receipts, list):
            receipts = []
            self._fast_lane_receipts = receipts
        receipts.append(receipt)
        self._last_fast_lane_checkpoint_cost_sec = time.perf_counter() - started
        self._fast_lane_cycle_spent_sec = (
            float(getattr(self, "_fast_lane_cycle_spent_sec", 0.0) or 0.0)
            + self._last_fast_lane_checkpoint_cost_sec
        )
        self._last_fast_lane_checkpoint_mono = time.monotonic()
        if mark:
            self._mark(f"fast_lane_{label}")
        else:
            # Inside the decision loop: a mark would split that stage's
            # timing, so the pass is recorded as a span and the loop's own
            # time keeps it (it happened inside the loop).
            self._add_span(
                f"fast_lane_{label}", (time.perf_counter() - started) * 1000.0
            )
        return receipt

    def _note_fast_lane_budget_skip(
        self, label: str, *, spent_sec: float
    ) -> None:
        """Record, once per cycle, that the checkpoint budget is spent."""

        if getattr(self, "_fast_lane_budget_skip_noted", False):
            return
        self._fast_lane_budget_skip_noted = True
        receipts = getattr(self, "_fast_lane_receipts", None)
        if not isinstance(receipts, list):
            receipts = []
            self._fast_lane_receipts = receipts
        receipts.append({
            "label": label,
            "skipped": "cycle_budget_spent",
            "spent_sec": round(float(spent_sec), 1),
            "budget_sec": FAST_LANE_CHECKPOINT_CYCLE_BUDGET_SEC,
        })

    def _begin_cycle_scratch(self) -> None:
        """Forget what one cycle may reuse but the next must not.

        Called once at the head of ``run``.  Everything here is a per-cycle
        memo or counter: the checkpoint budget spent, whether its skip was
        already noted, and the portfolio book read for this cycle's forward
        scopes.
        """

        self._fast_lane_cycle_spent_sec = 0.0
        self._fast_lane_budget_skip_noted = False
        self._portfolio_book_cycle_memo = None

    def _fast_lane_checkpoint_if_due(
        self, label: str, *, mark: bool = True
    ) -> dict[str, Any] | None:
        """Charter 165: the checkpoint again, wherever the cycle has time.

        Called at the heavy stage boundaries and before each decision-loop
        scope; runs the checkpoint at most once per
        ``FAST_LANE_CHECKPOINT_MIN_INTERVAL_SEC``, so a report that landed
        during a two-minute stage gets its P1 within the interval instead
        of at the next head.  Everything else is the checkpoint's own rule
        (charter 154): P1 only for the stations with reports past the
        covered mark, P0-M only once the chain has settled the roots, never
        raises.  Before the chain that means P1 alone.
        """

        # Charter 264 (user ruling 2026-10-09 「把其他策略移除快车道」): the
        # copy-follow lane is the only strategy at the cycle's checkpoints;
        # H1 and the P1 tail lane run at the head and the tail alone.
        self._copy_follow_if_due(label)
        if not FAST_LANE_CHECKPOINTS_ENABLED:
            return None
        spent = float(getattr(self, "_fast_lane_cycle_spent_sec", 0.0) or 0.0)
        if spent >= FAST_LANE_CHECKPOINT_CYCLE_BUDGET_SEC:
            self._note_fast_lane_budget_skip(label, spent_sec=spent)
            return None
        last = getattr(self, "_last_fast_lane_checkpoint_mono", None)
        if last is not None:
            wait = FAST_LANE_CHECKPOINT_MIN_INTERVAL_SEC
            if FAST_LANE_CHECKPOINT_DUTY_CYCLE:
                wait = max(
                    wait,
                    float(getattr(self, "_last_fast_lane_checkpoint_cost_sec", 0.0)),
                )
            if time.monotonic() - float(last) < wait:
                return None
        return self._fast_lane_checkpoint(label, mark=mark)

    def _materialize_early_p1(
        self,
        *,
        as_of_utc: str,
        report_watermark: tuple[int, int, str] | None,
        force: bool = False,
        only_scopes: "set[tuple[str, str]] | None" = None,
        stage_clock_utc: str | None = None,
    ) -> dict[str, Any]:
        """Charter 148: P1 at the head of the cycle, for reports it has not seen.

        Runs only when the archive holds a report newer than the last cycle
        whose P1 covered its clock, and only when the report's identity pass
        has staged its contract -- a P1 written ahead of that carries no
        truth-revision hash and is refused by the atomic-fact gate until a
        newer one does.  Anything short of a clean pass falls back to the
        single P1 inside the chain, which is the behaviour before this stage.
        """

        boundary = {
            "calls_order_gateway": False,
            "places_orders": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }
        if not EARLY_P1_ENABLED:
            return {"state": "DISABLED", "ran": False, **boundary}
        if report_watermark is None and not force:
            return {"state": "SKIPPED_WATERMARK_UNREADABLE", "ran": False, **boundary}
        # ``force``: the head P0-M just committed, so P1 re-roots on it now
        # rather than at the end of the chain.
        if not force and getattr(self, "_p1_covered_watermark", None) == report_watermark:
            return {"state": "SKIPPED_NO_UNCOVERED_REPORTS", "ran": False, **boundary}
        started = time.perf_counter()
        try:
            identity = self._identify_live_observations()
            if str(identity.get("state") or "") not in {
                "STAGED", "SKIPPED_NO_NEW_REPORTS",
            }:
                return {
                    "state": "SKIPPED_IDENTITY_NOT_STAGED",
                    "ran": False,
                    "identity_state": identity.get("state"),
                    "duration_sec": round(time.perf_counter() - started, 3),
                    **boundary,
                }
            resident: dict[str, Any] = {"as_of_utc": as_of_utc}
            if only_scopes is not None:
                resident["only_scopes"] = set(only_scopes)
            if stage_clock_utc:
                # The stage below's own clock: its root is read as of it.
                resident["stage_clock_utc"] = str(stage_clock_utc)
            p1 = self._materialize_resident_p1(**resident)
        except Exception as exc:  # noqa: BLE001 -- the chain's pass is the fallback
            return {
                "state": "FAILED",
                "ran": False,
                "reason": f"{type(exc).__name__}:{str(exc)[:200]}",
                "duration_sec": round(time.perf_counter() - started, 3),
                **boundary,
            }
        if str(p1.get("state") or "") not in {
            "COMMITTED", "PARTIAL_FAIL_CLOSED", "BLOCKED_FAIL_CLOSED",
        }:
            return {
                "state": "SKIPPED_P1_NOT_ATTEMPTED",
                "ran": False,
                "p1_state": p1.get("state"),
                "duration_sec": round(time.perf_counter() - started, 3),
                **boundary,
            }
        return {
            "state": "RAN",
            "ran": True,
            "identity_state": identity.get("state"),
            "p1_state": p1.get("state"),
            "p1_update_count": p1.get("p1_update_count"),
            "p1": p1,
            "duration_sec": round(time.perf_counter() - started, 3),
            **boundary,
        }

    def _fresh_committed_envelope_scopes(
        self, *, fresh_after_utc: str
    ) -> list[tuple[Any, Any]]:
        """``SELECT DISTINCT station_id,event_date ... fresh_until_utc>?`` over COMMITTED envelopes.

        Exactly that answer, sorted as that statement sorted it.  The statement
        itself could not seek: ``fresh_until_utc`` is the ninth column of the
        publisher index, so every cycle walked all ~448,000 committed envelopes
        to keep ~100 scopes -- 5.7s on 2026-09-09, 7-8s on 2026-09-14.  And no
        event-date bound can stand in for it: a P0-M envelope was minted for
        CYYZ 2026-08-24 on 2026-09-01, and the freshness window has no
        contracted ceiling (P0 measured 12.7h).

        The envelope table is append-only by trigger -- no UPDATE, no DELETE --
        so a scope's newest freshness only ever grows, and only by rows past
        the last rowid read.  The first call aggregates the newest
        ``fresh_until_utc`` per scope over the covering publisher index (a few
        seconds, once per connection); every later call reads the rows appended
        since, by rowid.  The ceiling is taken before the aggregate, so a row
        landing between the two is counted twice and never missed.
        """

        conn = self.conn
        index = getattr(self, "_committed_envelope_freshness", None)
        if index is None or index.get("conn") is not conn:
            ceiling = int(conn.execute(
                "SELECT COALESCE(MAX(rowid),0) FROM basket_probability_envelope"
            ).fetchone()[0])
            newest: dict[tuple[Any, Any], Any] = {}
            for station_id, event_date, fresh_until in conn.execute(
                "SELECT station_id,event_date,MAX(fresh_until_utc)"
                " FROM basket_probability_envelope"
                " WHERE state='COMMITTED' GROUP BY station_id,event_date"
            ):
                newest[(station_id, event_date)] = fresh_until
            index = {"conn": conn, "after_rowid": ceiling, "newest": newest}
            self._committed_envelope_freshness = index
        else:
            newest = index["newest"]
            # ``state`` stays out of the WHERE clause on purpose: given a
            # term on it the planner walks the state index instead of seeking
            # the rowid range (4.3s for 3,000 rows against 0.4s).
            for rowid, station_id, event_date, fresh_until, state in conn.execute(
                "SELECT rowid,station_id,event_date,fresh_until_utc,state"
                " FROM basket_probability_envelope WHERE rowid>?",
                (int(index["after_rowid"]),),
            ):
                if int(rowid) > int(index["after_rowid"]):
                    index["after_rowid"] = int(rowid)
                if state != "COMMITTED" or fresh_until is None:
                    continue
                key = (station_id, event_date)
                held = newest.get(key)
                if held is None or fresh_until > held:
                    newest[key] = fresh_until
        return sorted(
            key
            for key, fresh_until in index["newest"].items()
            if fresh_until is not None and fresh_until > fresh_after_utc
        )

    def _regime_catch_up(self, *, label: str) -> dict[str, Any] | None:
        """Companions for the envelopes committed since the regime pass.

        The regime stage runs once, mid-cycle; the forward P0 loop and the
        fast-lane checkpoints commit envelopes after it, and a decision that
        prices one of them found no companion -- ``regime_ssot_missing`` --
        until the next cycle's pass (NZWN 2026-10-03: envelopes 12:24-12:26Z,
        decision 12:29:50Z, companions 12:31:58Z).  Runs only once this
        cycle's regime pass has, reads the new envelopes' scopes by rowid,
        and hands them to the same pass; companions are pure functions of
        the committed row, so this is the pass, sooner.
        """

        if not getattr(self, "_regime_ran_this_cycle", False):
            return None
        mark = getattr(self, "_regime_rowid_mark", None)
        if mark is None or self.conn is None:
            return None
        started = time.perf_counter()
        ceiling = int(self.conn.execute(
            "SELECT COALESCE(MAX(rowid),0) FROM basket_probability_envelope"
        ).fetchone()[0])
        if ceiling <= int(mark):
            return None
        scopes = {
            (row[0], row[1])
            for row in self.conn.execute(
                "SELECT station_id,event_date FROM basket_probability_envelope"
                " WHERE rowid>? AND rowid<=?",
                (int(mark), ceiling),
            )
        }
        self._regime_rowid_mark = ceiling
        if not scopes:
            return None
        receipt = self._materialize_regime_ssot(
            as_of_utc=utc_now(), only_scopes=scopes,
        )
        self._add_span(
            f"regime_catch_up_{label}",
            (time.perf_counter() - started) * 1000.0,
            label=f"{len(scopes)} scopes",
        )
        return receipt

    def _regime_scopes_owed(
        self, fresh: Sequence[tuple[Any, Any]], *, ceiling: int,
    ) -> list[tuple[Any, Any]]:
        """The fresh scopes the stage's pass still owes a read.

        The pass read every fresh station-day whole, every cycle, to find
        that almost all of them had nothing new: 1,957 envelopes loaded and
        rebuilt for 1-23 committed since the pass before (2026-10-03, 14 s
        of a 197 s cycle).  Envelopes and companions are append-only, a
        companion is a pure function of its envelope, and both the set of
        fresh scopes and the set of servable envelopes only shrink while
        nothing is committed -- so a scope a completed pass read without a
        blocker is owed nothing until an envelope lands on it.  Owed: the
        scopes of the envelopes committed since the last completed stage
        pass (by rowid, catch-up or not), and the scopes whose last read
        had a blocker.  The first pass of a process owes every fresh scope,
        and so does any pass after one that did not finish.  "0" restores
        every scope every cycle.
        """

        done = getattr(self, "_regime_full_done_mark", None)
        if not REGIME_STAGE_INCREMENTAL or done is None or int(done) > int(ceiling):
            return list(fresh)
        owed = {
            (str(scope[0]), str(scope[1]))
            for scope in getattr(self, "_regime_retry_scopes", None) or ()
        }
        owed.update(
            (str(row[0]), str(row[1]))
            for row in self.conn.execute(
                "SELECT station_id,event_date FROM basket_probability_envelope"
                " WHERE rowid>? AND rowid<=?",
                (int(done), int(ceiling)),
            )
        )
        return [
            scope for scope in fresh
            if (str(scope[0]), str(scope[1])) in owed
        ]

    def _regime_note_pass(
        self,
        passed_scopes: Sequence[tuple[str, str]],
        blockers: Sequence[Mapping[str, Any]],
        *,
        full_pass_ceiling: int | None,
    ) -> None:
        """What a finished pass leaves owed (``_regime_scopes_owed``)."""

        blocked = {
            (str(item.get("station_id") or ""), str(item.get("event_date") or ""))
            for item in blockers
        }
        retry = set(getattr(self, "_regime_retry_scopes", None) or ())
        retry.difference_update(passed_scopes)
        retry.update(scope for scope in passed_scopes if scope in blocked)
        self._regime_retry_scopes = retry
        if full_pass_ceiling is not None:
            self._regime_full_done_mark = int(full_pass_ceiling)

    def _materialize_regime_ssot(
        self,
        *,
        as_of_utc: str,
        only_scopes: Collection[tuple[Any, Any]] | None = None,
    ) -> dict[str, Any]:
        """Append exact probability companions before any basket compile.

        Regime is derived only from a committed probability envelope and its
        model-envelope lineage. Missing disagreement lineage is a blocker; no
        extrema or direction is synthesized at this boundary.
        """

        if self.conn is None or self.commit_conn is None:
            return {
                "schema": "bayes_basket_target_regime_batch_v1",
                "state": "BLOCKED_FAIL_CLOSED",
                "reason": "target_atomic_writer_not_injected",
                "receipts": [],
                "blockers": [],
                "calls_order_gateway": False,
                "orders_submitted": 0,
            }
        # No decision-time filter: companions are pure functions of the
        # committed row, and the chain step this cycle just ran commits
        # envelopes whose decision stamps sit past the cycle-start clock
        # (deterministic +1s/+1us bumps).  Anchoring coverage to that clock
        # left every such envelope companion-less for exactly one cycle,
        # and the basket compile -- evaluating moments later with a fresher
        # clock -- died on ``regime_ssot_not_unique`` for whichever station
        # had just minted one (20 stations in one 2026-08-20 snapshot).
        _regime_probe_started = time.perf_counter()
        full_pass_ceiling: int | None = None
        fresh_scope_count: int | None = None
        if only_scopes is not None:
            # A catch-up pass (``_regime_catch_up``): the scopes of the
            # envelopes committed since the last pass, nothing else.
            scopes = sorted(set(only_scopes))
        else:
            # Everything committed after this mark is the catch-up's.
            self._regime_rowid_mark = int(self.conn.execute(
                "SELECT COALESCE(MAX(rowid),0) FROM basket_probability_envelope"
            ).fetchone()[0])
            full_pass_ceiling = int(self._regime_rowid_mark)
            self._regime_ran_this_cycle = True
            scopes = self._fresh_committed_envelope_scopes(
                # Widened by the serving grace: a P1 an hour past its roll is
                # still the day's current reading (contracts.STAGES_SERVABLE_
                # PAST_CADENCE) and its companion must exist for that long.
                fresh_after_utc=shift_timestamp_utc(
                    as_of_utc, -PROBABILITY_MAX_STALE_SECONDS
                ),
            )
            fresh_scope_count = len(scopes)
            scopes = self._regime_scopes_owed(
                scopes, ceiling=full_pass_ceiling,
            )
        self._add_span(
            "regime_scope_probe",
            (time.perf_counter() - _regime_probe_started) * 1000.0,
            label=f"{len(scopes)} scopes",
        )
        envelopes: list[ProbabilityEnvelope] = []
        blockers: list[dict[str, str]] = []
        passed_scopes = [(str(scope[0]), str(scope[1])) for scope in scopes]
        _regime_load_started = time.perf_counter()
        for station_id, event_date in scopes:
            try:
                expected_source_lane = target_registry_source_lane(
                    self.conn,
                    station_id=str(station_id),
                    event_date=str(event_date),
                )
                envelopes.extend(
                    envelope
                    for envelope in load_materialized_probability_envelopes(
                        self.conn,
                        station_id=str(station_id),
                        event_date=str(event_date),
                        evaluation_at_utc=as_of_utc,
                        expected_source_lane=expected_source_lane,
                        include_future_decisions=True,
                    )
                    # Coverage is "every envelope a later evaluation could
                    # see", and an already-expired envelope is exactly the
                    # one no later evaluation can: ``load_regime_artifact``
                    # matches on ``valid_until_utc > evaluation``, the window
                    # is fixed, and evaluation clocks only move forward.  A
                    # companion built here could therefore never be read
                    # back.  The visibility rule that ``include_future_
                    # decisions`` lifts is about decision stamps landing
                    # ahead of the cycle clock -- it was never a licence to
                    # reach backwards past expiry.
                    #
                    # This is also what makes the sixteen self-contradictory
                    # P0-M rows of 2026-08-27 harmless.  Their 44ms windows
                    # closed within a second of opening, so the SSOT's
                    # CHECK -- a TEXT comparison, where ``'…:11Z'`` sorts
                    # after ``'…:11.044000Z'`` -- rejected every companion
                    # and fail-closed this lane on every cycle.  The table
                    # is append-only by trigger, so those rows cannot be
                    # repaired or retracted; they can only stop being asked
                    # for, and they should never have been asked for.
                    if timestamp_lt(
                        as_of_utc,
                        servable_horizon_utc(
                            envelope.stage, envelope.fresh_until_utc
                        ),
                    )
                )
            except Exception as exc:
                blockers.append({
                    "station_id": str(station_id),
                    "event_date": str(event_date),
                    "reason": f"{type(exc).__name__}:{exc}",
                })
        self._add_span(
            "regime_envelope_load",
            (time.perf_counter() - _regime_load_started) * 1000.0,
            label=f"{len(envelopes)} envelopes",
        )
        receipts: list[dict[str, Any]] = []
        # Envelopes are append-only and immutable, so a companion built for
        # one is final -- yet every cycle rebuilt and re-probed all of them.
        # Measured 2026-08-16: 16,441 envelopes across 88 fresh scopes, each
        # costing two idempotency SELECTs and its own savepoint transaction,
        # for 103s a cycle of which ~79s wrote nothing.  Those 32,882 probes
        # are one read of the same rows, so take it once: 0.5s warm.
        #
        # This is a shortcut around ``insert_regime_artifact``'s no-op branch
        # and nothing else.  It fires only on an exact identity match -- one
        # committed companion for the scope, with the same probability sha,
        # content sha and artifact id -- which is precisely the case that
        # function returns ``wrote=False`` for.  Every other shape (absent,
        # duplicated, drifted) still goes through it, so the uniqueness and
        # content-drift contracts remain where they were written.
        #
        # Read for the station-days in hand, not for the whole table.  "Take
        # it once" was right and the scope was not: the artifact table is
        # append-only beside the envelope table it companions, so by
        # 2026-09-09 one read of it was 416,210 rows to answer 947
        # questions -- 31.8 to 38.1 seconds warm against the live SSOT,
        # every cycle, inside a stage that measured 363.5s.  Every lookup
        # key below is built from an envelope in ``envelopes``, so the
        # station-days of those envelopes are exactly the rows this map can
        # ever be asked for: 0.9s for the same answer, over the unique
        # committed index.  Tenth of this repo's read-the-whole-ledger bug.
        committed_regime: dict[
            tuple[str, str, str, str], list[tuple[str, str, str]]
        ] = {}
        _regime_prior_started = time.perf_counter()
        prior_scopes = sorted({
            (str(envelope.station_id), str(envelope.event_date))
            for envelope in envelopes
        })
        for prior_station, prior_day in prior_scopes:
            for prior_row in self.conn.execute(
                "SELECT station_id,event_date,stage,checkpoint_id,"
                "probability_sha256,content_sha256,artifact_id "
                "FROM basket_regime_artifact WHERE state='COMMITTED'"
                " AND station_id=? AND event_date=?",
                (prior_station, prior_day),
            ):
                committed_regime.setdefault(
                    (
                        str(prior_row[0]),
                        str(prior_row[1]),
                        str(prior_row[2]),
                        str(prior_row[3]),
                    ),
                    [],
                ).append(
                    (str(prior_row[4]), str(prior_row[5]), str(prior_row[6]))
                )
        self._add_span(
            "regime_prior_scan",
            (time.perf_counter() - _regime_prior_started) * 1000.0,
            label=f"{len(prior_scopes)} scopes",
        )
        _regime_build_started = time.perf_counter()
        # Keep the resident pass resource-bounded without turning a healthy
        # multi-stage 45-station SSOT into a global blocker once the number
        # of committed envelopes exceeds the per-batch guard.  Each chunk is
        # idempotent and transaction-fenced; a later cycle can safely replay
        # the same rows if a transient fault interrupts a chunk.
        for chunk_start in range(
            0,
            len(envelopes),
            MAX_REGIME_ARTIFACTS_PER_PASS,
        ):
            chunk = envelopes[
                chunk_start : chunk_start + MAX_REGIME_ARTIFACTS_PER_PASS
            ]
            assert_process_memory_budget()
            for envelope in chunk:
                try:
                    artifact = build_regime_artifact(envelope)
                    prior = committed_regime.get(
                        (
                            artifact.station_id,
                            artifact.event_date,
                            artifact.stage,
                            artifact.checkpoint_id,
                        )
                    ) or []
                    if len(prior) == 1 and prior[0] == (
                        artifact.probability_sha256,
                        artifact.content_sha256,
                        artifact.artifact_id,
                    ):
                        receipt = {
                            "artifact_id": artifact.artifact_id,
                            "wrote": False,
                            "idempotent": True,
                        }
                    else:
                        with _writer_transaction(
                            self.commit_conn,
                            savepoint="basket_target_regime_artifact",
                        ):
                            receipt = insert_regime_artifact(
                                self.commit_conn,
                                artifact,
                                created_at_utc=as_of_utc,
                            )
                    receipts.append({
                        **receipt,
                        "station_id": envelope.station_id,
                        "event_date": envelope.event_date,
                        "stage": envelope.stage,
                        "checkpoint_id": envelope.checkpoint_id,
                        "probability_sha256": envelope.content_sha256,
                    })
                except Exception as exc:
                    blockers.append({
                        "station_id": envelope.station_id,
                        "event_date": envelope.event_date,
                        "stage": envelope.stage,
                        "checkpoint_id": envelope.checkpoint_id,
                        "reason": f"{type(exc).__name__}:{exc}",
                    })
        self._add_span(
            "regime_artifact_build",
            (time.perf_counter() - _regime_build_started) * 1000.0,
            label=f"{len(envelopes)} envelopes",
        )
        self._regime_note_pass(
            passed_scopes, blockers,
            full_pass_ceiling=full_pass_ceiling if only_scopes is None else None,
        )
        return {
            "schema": "bayes_basket_target_regime_batch_v1",
            "state": "BLOCKED_FAIL_CLOSED" if blockers else "COMMITTED",
            # The stage's pass names the fresh scopes it found and the ones
            # it owed a read; a catch-up pass was handed its scopes.
            "fresh_scope_count": (
                fresh_scope_count if only_scopes is None else None
            ),
            "scope_count": len(passed_scopes),
            "receipt_count": len(receipts),
            "envelope_count": len(envelopes),
            "chunk_count": (
                (len(envelopes) + MAX_REGIME_ARTIFACTS_PER_PASS - 1)
                // MAX_REGIME_ARTIFACTS_PER_PASS
            ),
            "written_count": sum(
                1 for item in receipts if item.get("wrote") is True
            ),
            "receipts": receipts,
            "blockers": blockers,
            "calls_order_gateway": False,
            "orders_submitted": 0,
        }

    def _replay_root_mismatch_reason(
        self,
        *,
        station_id: str,
        event_date: str,
        as_of_utc: str,
        validated_out: list[ProbabilityEnvelope] | None = None,
    ) -> str | None:
        """Refuse to trade a higher stage that has not caught up with its root.

        The target is resolved by the compiler's own resolver
        (``select_p1_replay_base``): the newest P0, and on it the newest P0-M
        if one exists.  A P1 is current only when both of its parents -- the
        direct prediction root and the P0 ancestor, each by checkpoint and by
        content -- are that target (``p1_stands_on_replay_base``); a P0-M is
        current only when its root is exactly the newest P0.

        Until 2026-09-13 this read the P0 ancestor alone, so a P1 still on a
        P0-M the lane had just replaced passed as current, and it excused any
        higher stage whose P0 had the same bucket probabilities as the newest
        one.  That excuse predates re-rooting in the same cycle: it existed
        because a confirmation could lag its root for hours.  Now the chain
        re-roots before this runs, and the decision loop's clock is taken
        after the chain has written, so a mismatch here means the rebuild did
        not happen -- and equal probabilities are not equal inputs: 444 of
        2,834 P0 transitions on 2026-09-11..12 kept the numbers and moved the
        future temperature curve that P1's remaining-warming layer reads.

        When no P1 exists, an older P0-M branch still blocks: stage precedence
        would serve it, and it is built on a superseded root.  When a P1 on
        the current target exists, an older P0-M is irrelevant -- P1 is what
        is served.
        """

        if self.conn is None:
            return "resident_probability_read_only_connection_missing"
        expected_source_lane = target_registry_source_lane(
            self.conn,
            station_id=station_id,
            event_date=event_date,
        )
        envelopes = load_materialized_probability_envelopes(
            self.conn,
            station_id=station_id,
            event_date=event_date,
            evaluation_at_utc=as_of_utc,
            expected_source_lane=expected_source_lane,
            validated_out=validated_out,
        )
        p0_rows = [row for row in envelopes if row.stage == "P0"]
        if not p0_rows:
            return "resident_p0_root_missing"
        latest_p0_at = max(row.decision_at_utc for row in p0_rows)
        latest_p0_rows = [
            row for row in p0_rows if row.decision_at_utc == latest_p0_at
        ]
        if len(latest_p0_rows) != 1:
            return "resident_p0_scope_ambiguous"
        latest_p0 = latest_p0_rows[0]
        p1_rows = [row for row in envelopes if row.stage == "P1"]
        if p1_rows:
            latest_p1_at = max(row.decision_at_utc for row in p1_rows)
            latest_p1 = [
                row for row in p1_rows if row.decision_at_utc == latest_p1_at
            ]
            if len(latest_p1) != 1:
                return "resident_p1_scope_ambiguous"
            try:
                base, _predecessor, _consumed, _rebasing = (
                    select_p1_replay_base(envelopes, as_of_utc=as_of_utc)
                )
            except ContractError:
                return "resident_p1_replay_required"
            if base.stage == "P0":
                p0_root_content = base.content_sha256
            else:
                p0_root_content = str(
                    base.lineage.get("p0_root_content_sha256") or ""
                ).lower()
            if p1_stands_on_replay_base(
                latest_p1[0],
                base=base,
                p0_root_checkpoint_id=latest_p0.checkpoint_id,
                p0_root_content_sha256=p0_root_content,
            ):
                return None
            return "resident_p1_replay_required"
        p0m_rows = [row for row in envelopes if row.stage == "P0-M"]
        if not p0m_rows:
            return None
        latest_p0m_at = max(row.decision_at_utc for row in p0m_rows)
        latest_p0m = [
            row for row in p0m_rows if row.decision_at_utc == latest_p0m_at
        ]
        if len(latest_p0m) != 1:
            return "resident_p0m_scope_ambiguous"
        lineage = latest_p0m[0].lineage
        if (
            str(lineage.get("p0_root_checkpoint_id") or "")
            != latest_p0.checkpoint_id
            or str(lineage.get("p0_root_content_sha256") or "").lower()
            != latest_p0.content_sha256
        ):
            return "resident_p0m_replay_required"
        return None

    def _portfolio_quota(
        self,
        *,
        stations: Sequence[str],
        fallback_budget_usdc: float,
        as_of_utc: str,
    ) -> dict[str, float]:
        """Per-station quota from the one bankroll, or the old flat budget.

        Each station's edge and curve spread are measured from its own most
        recent committed plan -- what a dollar bought it last time -- and the
        atomic basket minimum comes from the activated clip grid.  A station
        with no such history is left out of the split and keeps the flat
        budget, so introducing the allocator cannot silently stop a station
        that has never traded from trying.

        The book half of this -- what the account holds, whether a Tier-1
        bound is breached, the bankroll, the clip grid -- does not depend on
        which station is asking, and the forward loop asks once per scope
        with that scope's single station: 61 times a cycle at the 2026-09-19
        median, 10.5s of a 202s cycle (54.7s at the worst), and one persisted
        inventory snapshot per ask (10,929 and 17,171 rows on 09-20 and
        09-19).  So the book is read once per cycle (``_portfolio_book_for_
        cycle``) and the station half -- its edge and the allocation over the
        stations asked about -- is computed per call exactly as before.  The
        book is as of the first ask in the cycle; the forward loop places no
        orders, so nothing it could hold changes between its asks.

        Failure is not fatal here: the receipt is evidence, not authority,
        and a book that cannot be split still plans at the configured budget.
        """

        try:
            book = self._portfolio_book_for_cycle(as_of_utc=as_of_utc)
            inventory = book["inventory"]
            self._portfolio_inventory_last = {
                "open_notional_usdc": inventory["open_notional_usdc"],
                "portfolio_hhi": inventory["portfolio_hhi"],
                "breaches": inventory["breaches"],
                "new_intents_allowed": inventory["new_intents_allowed"],
                "drawdown": inventory["drawdown"],
            }
            quota, allocation = portfolio_quota_from(
                stations=stations,
                inventory=inventory,
                edges_for=lambda: self._station_edge_evidence(
                    stations=stations,
                    minimum_clip_usdc=float(book["minimum_clip_usdc"]),
                ),
                blocks_by_station=book["blocks_by_station"],
                policy=book["policy"],
            )
            if not inventory["new_intents_allowed"]:
                self._portfolio_allocation_last = {
                    "state": "PORTFOLIO_BOUND_BREACHED",
                    "breaches": inventory["breaches"],
                    "new_intents_allowed": False,
                }
                return quota
            if allocation is None:
                return quota
            edges = allocation["_edges"]
            allocation = {
                key: value for key, value in allocation.items() if key != "_edges"
            }
            persist_portfolio_allocation(
                self.commit_conn,
                allocation,
                as_of_utc=as_of_utc,
                blocks_content_sha256=book["blocks_sha"],
                created_at_utc=as_of_utc,
            )
            self._portfolio_allocation_last = {
                "funded_station_count": allocation["funded_station_count"],
                "station_count": allocation["station_count"],
                "allocated_usdc": allocation["allocated_usdc"],
                "bankroll_usdc": allocation["bankroll_usdc"],
                "portfolio_sigma_usdc": allocation["portfolio_sigma_usdc"],
                "naive_sigma_usdc": allocation["naive_sigma_usdc"],
                "minimum_bankroll": derive_minimum_bankroll(
                    station_edges=edges
                ),
            }
            return dict(allocation["quota_usdc_by_station"])
        except (ContractError, sqlite3.Error, ValueError, KeyError) as exc:
            self._portfolio_allocation_last = {
                "state": "ALLOCATION_UNAVAILABLE",
                "reason": f"{type(exc).__name__}:{exc}",
                "fallback_budget_usdc": float(fallback_budget_usdc),
            }
            return {}

    def _portfolio_book_for_cycle(self, *, as_of_utc: str) -> dict[str, Any]:
        """The station-independent half of the quota, read once per cycle.

        A failure is not remembered: the next ask in the same cycle reads the
        book again, which is what every ask did before.
        """

        memo = getattr(self, "_portfolio_book_cycle_memo", None)
        if isinstance(memo, dict):
            memo["reused"] = int(memo.get("reused", 0)) + 1
            return memo
        blocks_by_station, blocks_sha = load_regional_blocks()
        policy, _policy_sha = load_portfolio_capital_policy()
        # What the book already holds decides whether it may hold more.
        # A breached Tier-1 bound stops new baskets and leaves open ones
        # to settle; closing them would realize the loss it is reacting
        # to, at whatever price the book happens to show.
        inventory = build_portfolio_inventory(
            self.commit_conn,
            as_of_utc=as_of_utc,
            blocks_by_station=blocks_by_station,
            policy=policy,
            budget_usdc=_resolve_target_remaining_budget(),
        )
        persist_portfolio_inventory(
            self.commit_conn, inventory, created_at_utc=as_of_utc
        )
        clip_row = self.conn.execute(
            "SELECT artifact_json FROM basket_delta_v2_policy_artifact "
            "ORDER BY rowid DESC LIMIT 1"
        ).fetchone()
        minimum_clip = min(
            json.loads(str(clip_row[0]))["cash_clip_grid"]
        ) if clip_row else 0.0
        memo = {
            "blocks_by_station": blocks_by_station,
            "blocks_sha": blocks_sha,
            "policy": policy,
            "inventory": inventory,
            "minimum_clip_usdc": float(minimum_clip),
            "read_at_utc": as_of_utc,
            "reused": 0,
        }
        self._portfolio_book_cycle_memo = memo
        return memo

    def _station_edge_evidence(
        self,
        *,
        stations: Sequence[str],
        minimum_clip_usdc: float,
    ) -> list[dict[str, Any]]:
        """What a dollar bought each station, from its own last plan."""

        rows: list[dict[str, Any]] = []
        for station_id in stations:
            # Pick the row by id first, then read it.  Written as
            # ``WHERE station_id=? ORDER BY rowid DESC LIMIT 1`` the planner
            # takes the scope index for the filter and then builds a temp
            # B-tree to sort -- which means materialising every one of that
            # station's ~1,000 plans, each dragging its plan_json through
            # overflow pages, to keep one.  Measured 2026-09-01 over 44,670
            # rows: 864ms per station, 38.9 seconds for the fleet, and the
            # forward sweep asks this once per scope.  MAX(rowid) is answered
            # from the covering index without touching a single plan_json,
            # and the outer lookup is one primary-key seek: 22.5ms for the
            # same 45 answers, byte-identical on every one.
            record = self.conn.execute(
                "SELECT plan_json FROM basket_p0_preselection_plan "
                "WHERE rowid=("
                "  SELECT MAX(rowid) FROM basket_p0_preselection_plan"
                "  WHERE station_id=?"
                ")",
                (station_id,),
            ).fetchone()
            if record is None:
                continue
            edge = station_edge_from_plan(
                json.loads(str(record[0])).get("compiled_plan") or {},
                station_id=station_id,
                minimum_clip_usdc=minimum_clip_usdc,
            )
            if edge is not None:
                rows.append(edge)
        return rows

    def _record_refused_compile_market_evidence(
        self,
        *,
        station_id: str,
        event_date: str,
        evaluation_at_utc: str,
        registry_snapshot: Mapping[str, Any],
        ws_manifest: Mapping[str, Any],
        ws_quotes: Mapping[str, Mapping[str, Any]],
        planning_budget_usdc: float,
        activation: Mapping[str, Any],
        compile_blocker: str,
        book_equity_usdc: float | None = None,
    ) -> dict[str, Any]:
        """Commit the book a refused forward compile was measured against.

        Its own transaction, and it never raises.  The caller is already on
        its way out with the compile's blocker, which is the answer to what
        happened; this is only the observation, and an observation that
        cannot be recorded must not replace or mask the refusal that brought
        us here.  The receipt is kept for the sweep's blocked entry so the
        status file says whether the book survived.

        The budget must be the one the compile was given: it rides in the
        quote row's content hash, and a bundle whose snapshot id already
        exists with different bytes is rejected outright.
        """

        receipt: dict[str, Any] = {
            "station_id": station_id,
            "event_date": event_date,
            "compile_blocker": compile_blocker,
            "state": "BLOCKED",
            "wrote_quote": False,
            "places_orders": False,
            "calls_order_gateway": False,
        }
        try:
            if self.commit_conn is None:
                raise ContractError("target_atomic_writer_not_injected")
            market_snapshot = compile_p0_market_evidence(
                self.conn,
                station_id=station_id,
                event_date=event_date,
                evaluation_at_utc=evaluation_at_utc,
                registry_snapshot=registry_snapshot,
                ws_manifest=ws_manifest,
                ws_quotes=ws_quotes,
                planning_budget_usdc=planning_budget_usdc,
                book_equity_usdc=book_equity_usdc,
            )
            (
                quote_raw,
                inventory_raw,
                order_state_raw,
            ) = _forward_market_evidence_rows(
                market_snapshot,
                quote_freshness_policy_sha256=(
                    QuoteFreshnessPolicy.from_mapping(
                        activation.get("quote_freshness_policy")
                    ).content_sha256
                ),
            )
            _forward_quote_sequence(self.commit_conn, quote_raw)
            assert_connection_target_capacity(
                self.commit_conn,
                recover_oversized_wal=True,
            )
            with _writer_transaction(
                self.commit_conn,
                savepoint="basket_target_p0_refused_compile_evidence",
            ):
                bundle = insert_market_evidence_bundle(
                    self.commit_conn,
                    quote_raw,
                    inventory_raw,
                    order_state_raw,
                )
            receipt["state"] = "COMMITTED"
            receipt["wrote_quote"] = bool(bundle["wrote_quote"])
            receipt["quote_snapshot_id"] = bundle["quote_snapshot_id"]
            receipt["quote_observed_at"] = str(
                market_snapshot.get("quote_observed_at") or ""
            )
        except Exception as exc:  # noqa: BLE001 -- observational
            receipt["market_evidence_blocker"] = f"{type(exc).__name__}:{exc}"
        self._forward_market_evidence_last = receipt
        return receipt

    def materialize_forward_p0_preselections(
        self,
        *,
        registry_snapshot_path: Path,
        ws_manifest_path: Path,
        event_date: str,
        evaluation_at_utc: str,
        station_id: str | None = None,
    ) -> dict[str, Any]:
        """Compile and append future-day P0 plans through the sole worker.

        This path atomically writes ``basket_p0_preselection_plan`` and its
        zero-execution ``auto_trade_decisions`` authority row.  It never
        creates an intent, reservation, order, or gateway call.
        """

        if self.conn is None:
            return _blocked(
                self._target_open_blocker(),
                event_date=event_date,
            )
        if self.commit_conn is None:
            return _blocked(
                self.commit_error or "target_atomic_writer_not_injected",
                event_date=event_date,
            )
        # Schema-dispatching on purpose: self.activation_path is the live
        # contract in live mode, and the narrow loader shut production for
        # seven hours the first time and one more cycle the second.
        #
        # The assignment below sat at twelve spaces for a day -- comments do
        # not take part in indentation, so Python read it as the tail of the
        # `if self.commit_conn is None:` block above, i.e. dead code behind
        # its return.  On the live path `activation` was then never bound and
        # every forward-day P0 preselection died on an UnboundLocalError:
        # this lane is the only entry that plans tomorrow's baskets, so the
        # 09-01 and 09-02 books had no P0 opening while the current-day
        # chain looked healthy.
        activation = load_activation(self.activation_path)
        self._assert_db_activation(activation)
        scope = activation.get("target_scope")
        if not isinstance(scope, Mapping):
            raise RuntimeError("target_scope_config_missing")
        missing = [key for key in TARGET_SCOPE_KEYS if not str(scope.get(key) or "").strip()]
        if missing:
            raise RuntimeError("target_scope_missing:" + ",".join(missing))
        registry_path = Path(registry_snapshot_path).expanduser().resolve()
        manifest_path = Path(ws_manifest_path).expanduser().resolve()
        if manifest_path == self.market_manifest_path:
            raise RuntimeError("forward_p0_manifest_must_not_be_resident_manifest")
        # Each of these runs once per scope, forty-odd times a cycle, inside
        # the loop that now owns most of it.  Naming them separately is the
        # difference between "the sweep is slow" and knowing whether it is
        # the registry read, the visibility query, or the compile.
        with self._span("fwd_registry_snapshot", label=str(station_id or "")):
            registry = load_market_registry_snapshot(registry_path)
        with self._span("fwd_ws_quotes", label=str(station_id or "")):
            manifest, quotes = load_official_ws_quotes(manifest_path)
        with self._span("fwd_visible_stations", label=str(station_id or "")):
            stations = latest_visible_p0_station_ids(
                self.conn,
                event_date=event_date,
                evaluation_at_utc=evaluation_at_utc,
            )
        if station_id is not None:
            requested_station = str(station_id or "").strip().upper()
            if not requested_station:
                raise RuntimeError(
                    "forward_p0_station_scope_invalid"
                )
            stations = [
                value
                for value in stations
                if value == requested_station
            ]
        if not stations:
            raise RuntimeError("forward_p0_probability_scope_empty")
        if len(stations) > MAX_FORWARD_P0_STATIONS:
            raise RuntimeError("forward_p0_station_scope_cap_exceeded")
        assert_process_memory_budget()
        planning_budget_usdc = _resolve_target_remaining_budget()
        # The book's equity, read once for the whole loop and handed to every
        # scope's snapshot as ``book_equity_usdc``.  The kernel's per-scope
        # stake cap is 2% of the *book* (charter of 2026-08-26); the planning
        # budget is the portfolio quota below, a quarter of the pool at most.
        # With no equity on the snapshot the compiler fell back to the budget
        # and the 2% rode on the quota: 514.29 x 0.25 x 0.02 x 0.6 = 1.54
        # USDC for a P0 open, below one exchange lot on any leg above 0.30.
        # Measured 2026-09-02: every positive-edge forward basket of the day
        # (6 of 6) was refused for a missing leg it could have afforded at
        # the 6.17 the ruling actually grants.  The paper ledger has sized
        # off whole-book equity since it was built, so this is also what
        # makes the two sides agree again.
        # Charter 141: the real account, capped by the budget dial.  A stale
        # read plans nothing: every station's budget is zeroed below.
        book_equity_usdc, account_equity_state = self._account_book_equity_usdc(
            as_of_utc=evaluation_at_utc,
        )
        # The bankroll is one book.  Handing every station the whole of it --
        # which is what the configured budget did, forty-five times over the
        # same 20 USDC -- only failed to over-commit because almost nothing
        # traded.  The allocator splits it, charging stations under one air
        # mass as a single position, and a station it cannot fund to a whole
        # atomic basket gets nothing rather than an amount that buys nothing.
        with self._span("fwd_portfolio_quota", label=str(station_id or "")):
            quota_by_station = self._portfolio_quota(
                stations=stations,
                fallback_budget_usdc=planning_budget_usdc,
                as_of_utc=evaluation_at_utc,
            )
        compiled = []
        for station_id in stations:
            if self.stop_requested:
                # SIGTERM: stop at the scope boundary (see request_stop).
                break
            station_budget = float(
                quota_by_station.get(station_id, planning_budget_usdc)
            )
            if account_equity_state == "account_equity_stale":
                # Charter 141: no fresh account read, no plan that spends.
                station_budget = 0.0
            # An unfunded station is compiled at zero budget rather than
            # skipped.  The two things this call produces are not the same
            # kind of thing: the plan is a trading decision, but the market
            # snapshot it commits is *evidence*, and evidence must be
            # recorded whether or not the book can afford to act on it.
            #
            # Skipping cost us the whole forward-day book.  Measured
            # 2026-08-15: the pool holds 20 USDC, the allocator's risk
            # fraction leaves 7 to deploy, and the smallest whole atomic
            # basket needs 11.43 -- so every station returned zero, every
            # station was skipped, and not one 2026-08-16 quote reached
            # basket_official_ws_snapshot even though the publisher had all
            # 319 tokens live.  Quotes are ephemeral; a forward day dropped
            # here is gone for good, and with it the ability to audit or
            # replay what the listing window actually offered.
            #
            # Zero budget is a legal planning budget (only negative or
            # non-finite is rejected), so the trading side stays fail-closed
            # by arithmetic: nothing is affordable, no intent is written.
            try:
                with self._span("fwd_compile_preselection", label=station_id):
                    compiled.append(compile_p0_preselection(
                        self.conn,
                        station_id=station_id,
                        event_date=event_date,
                        evaluation_at_utc=evaluation_at_utc,
                        registry_snapshot=registry,
                        ws_manifest=manifest,
                        ws_quotes=quotes,
                        season_bin=str(scope["season_bin"]),
                        maturity_bin=str(scope["maturity_bin"]),
                        liquidity_bin=str(scope["liquidity_bin"]),
                        strategy_version=str(scope["strategy_version"]),
                        planning_budget_usdc=max(0.0, station_budget),
                        book_equity_usdc=book_equity_usdc,
                        # Charter 125.  This lane plans forward days, whose
                        # thermometer has usually said nothing yet -- but a
                        # listing window can straddle the local midnight, and
                        # a preliminary plan that shows dead rungs on the
                        # board is the same error as buying them.
                        observed_running_high_c=(
                            self._observed_running_high_c(
                                station_id=station_id,
                                event_date=event_date,
                                as_of_utc=evaluation_at_utc,
                            )
                        ),
                        base_policy=(
                            scope.get("base_policy")
                            if isinstance(scope.get("base_policy"), Mapping)
                            else None
                        ),
                    ))
            except ResourceBoundError:
                # A process at its resource ceiling must not be asked to do
                # more work to be polite about it.
                raise
            except Exception as compile_error:  # noqa: BLE001
                # Same rule the zero-budget branch above already follows,
                # applied to the other way a plan can fail to appear.  A
                # compile that raises is a refusal to trade -- the tape
                # offered a sub-tick price, the regime disagreed with the
                # support, delta-v2 had no artifact -- and none of those are
                # reasons to discard the observation the refusal was measured
                # against.  Measured 2026-08-16 12:06Z, one 43-scope sweep:
                # 24 scopes raised and every one of them recorded no book at
                # all, because the only writer of basket_official_ws_snapshot
                # on this path sat downstream of the compile.  The quote is
                # ephemeral -- a forward one missed cannot be refetched -- so
                # the refusal cost the audit, the replay and the paper ledger
                # a day of market history per scope.
                #
                # The blocker still propagates: this records the book, it does
                # not forgive the plan.
                self._record_refused_compile_market_evidence(
                    station_id=station_id,
                    event_date=event_date,
                    evaluation_at_utc=evaluation_at_utc,
                    registry_snapshot=registry,
                    ws_manifest=manifest,
                    ws_quotes=quotes,
                    planning_budget_usdc=max(0.0, station_budget),
                    activation=activation,
                    compile_blocker=(
                        f"{type(compile_error).__name__}:{compile_error}"
                    ),
                    book_equity_usdc=book_equity_usdc,
                )
                raise
            assert_process_memory_budget()
        with self._span("fwd_capacity_guard"):
            assert_connection_target_capacity(
                self.commit_conn,
                recover_oversized_wal=True,
            )
        # The write side of a scope, separated from the compile above it: one
        # is read-bound work, the other holds the single writer lock, and the
        # remedy for each is a different one.
        with self._span("fwd_commit"), _writer_transaction(
            self.commit_conn,
            savepoint="basket_target_p0_worker_batch",
        ):
            receipts = []
            decision_receipts = []
            for item in compiled:
                preselection_receipt = commit_p0_preselection(
                    self.commit_conn,
                    item,
                    created_at_utc=evaluation_at_utc,
                )
                receipts.append(preselection_receipt)
                # Shadow-score the approved log-wealth objective next to the
                # committed plan: same buckets, same prices, same budget, no
                # authority.  Its own savepoint -- a scoring defect must never
                # cost a preselection.
                try:
                    self.commit_conn.execute(
                        "SAVEPOINT shadow_objective_score"
                    )
                    try:
                        shadow_compiled = item["compiled_plan"]
                        bankroll_row = self.commit_conn.execute(
                            "SELECT balance_usdc FROM "
                            "basket_target_capital_pool LIMIT 1"
                        ).fetchone()
                        shadow_score = build_shadow_objective_score(
                            station_id=str(item["station_id"]),
                            event_date=str(item["event_date"]),
                            probability_stage=str(
                                item["probability_stage"]
                            ),
                            checkpoint_id=str(item["checkpoint_id"]),
                            decision_at_utc=str(item["decision_at_utc"]),
                            candidate_rows=(
                                shadow_compiled.get(
                                    "order_sizing_decisions"
                                ) or []
                            ),
                            probabilities_by_bucket=(
                                shadow_compiled.get(
                                    "probability_envelope", {}
                                ).get("probabilities") or {}
                            ),
                            budget_usdc=float(
                                item.get("planning_budget_usdc") or 0.0
                            ),
                            bankroll_usdc=float(
                                bankroll_row[0]
                            ) if bankroll_row else 0.0,
                            created_at_utc=evaluation_at_utc,
                        )
                        if shadow_score is not None:
                            persist_shadow_objective_score(
                                self.commit_conn, shadow_score
                            )
                            preselection_receipt["shadow_objective"] = {
                                "growth_actual": shadow_score[
                                    "actual_curve"
                                ]["expected_log_growth"],
                                "growth_shadow": shadow_score[
                                    "shadow_curve"
                                ]["expected_log_growth"],
                            }
                        self.commit_conn.execute(
                            "RELEASE shadow_objective_score"
                        )
                    except Exception as exc:  # noqa: BLE001 -- observational
                        self.commit_conn.execute(
                            "ROLLBACK TO shadow_objective_score"
                        )
                        self.commit_conn.execute(
                            "RELEASE shadow_objective_score"
                        )
                        preselection_receipt["shadow_objective"] = {
                            "state": "SCORING_FAILED",
                            "error": f"{type(exc).__name__}:{exc}",
                        }
                except sqlite3.Error:
                    pass
                # P0 is the opening stage: a forward day is precisely when the
                # ensemble has something to say that the tape does not yet.
                # The quotes here come from the resident official WS book
                # sliced to this scope, so an opening intent is priced against
                # the live market, not a stale forward cache.  Plans that are
                # not compile-ready keep the preliminary no-execution record.
                market_snapshot = item.get(
                    UNPERSISTED_MARKET_SNAPSHOT_KEY
                )
                compiled_plan = item.get("compiled_plan")
                opened = None
                # Charter 46: the preliminary record is only ever allowed
                # *after* a named stage-open failure, never as a gate that
                # runs instead of one.  When the inputs stage-open needs are
                # absent it cannot be attempted, and that absence is itself
                # the blocker -- naming it here is what keeps the record
                # below a receipt rather than a prior refusal.
                if not isinstance(market_snapshot, Mapping):
                    preselection_receipt["stage_open_blocker"] = (
                        "stage_open_not_attempted:market_snapshot_missing"
                    )
                elif not isinstance(compiled_plan, Mapping):
                    preselection_receipt["stage_open_blocker"] = (
                        "stage_open_not_attempted:compiled_plan_missing"
                    )
                elif str(compiled_plan.get("status") or "") == "blocked":
                    # The runtime already decided: a blocked compile carries
                    # its reasons and no plan.  Attempting to open it only
                    # renamed those reasons -- the ledger refused the plan it
                    # never had as ``production_compiled_plan_missing``, and
                    # the status file said "plan missing" about fourteen
                    # forward scopes a cycle whose plan was a named HOLD
                    # (delta_v2_support_empty, 2026-09-02 07:48Z).  Name the
                    # runtime's own reasons instead, and do not attempt.
                    preselection_receipt["stage_open_blocker"] = (
                        "stage_open_not_attempted:compiled_plan_blocked:"
                        + ",".join(
                            str(code)
                            for code in (
                                compiled_plan.get("reason_codes") or ()
                            )
                        )
                    )
                if (
                    isinstance(market_snapshot, Mapping)
                    and isinstance(compiled_plan, Mapping)
                    and str(compiled_plan.get("status") or "") != "blocked"
                ):
                    # Two savepoints, because two different kinds of thing are
                    # written here.  The evidence bundle is the book as it
                    # stood; the stage open is a trading decision about it.
                    # They used to share one, so every stage-open refusal
                    # rolled the quote back out with it -- and a station whose
                    # opens all refuse then has no book at all.  Measured
                    # 2026-08-16: KORD, KSEA and ZUUU each refused every
                    # 2026-08-17 open on
                    # ``stage_evidence_intent_outside_bound`` -- the soft-bound
                    # gate of the day, an audit fact since charter 82 -- and
                    # between them wrote zero rows to
                    # basket_official_ws_snapshot for that day while the
                    # publisher held all 11 tokens of each live.  The forward
                    # book is ephemeral: the quote that was rolled back cannot
                    # be fetched again, so the refusal cost the audit, the
                    # replay and the paper ledger a day of market history
                    # apiece.  Same rule the zero-budget compile above already
                    # follows: evidence is recorded whether or not the book can
                    # act on it.
                    #
                    # The stage open still binds to *persisted* rows -- the
                    # forward validation joins the quote by snapshot_id and the
                    # inventory/order state by version -- so the bundle has to
                    # be committed before it, not merely attempted beside it.
                    # A forward day has no resident ingress writing that trio,
                    # and _insert_once makes the write idempotent across
                    # recompiles of the same quote version.
                    (
                        quote_raw,
                        inventory_raw,
                        order_state_raw,
                    ) = _forward_market_evidence_rows(
                        market_snapshot,
                        quote_freshness_policy_sha256=(
                            QuoteFreshnessPolicy.from_mapping(
                                activation.get("quote_freshness_policy")
                            ).content_sha256
                        ),
                    )
                    _forward_quote_sequence(self.commit_conn, quote_raw)
                    # Evidence first, in a savepoint of its own.  Set before
                    # the bundle is written, not after: the bundle refuses a
                    # quote whose version does not match the inventory row
                    # beside it, and the assignment sitting below the call left
                    # every scope failing that check.
                    evidence_written = False
                    try:
                        with _writer_transaction(
                            self.commit_conn,
                            savepoint="basket_target_p0_market_evidence",
                        ):
                            insert_market_evidence_bundle(
                                self.commit_conn,
                                quote_raw,
                                inventory_raw,
                                order_state_raw,
                            )
                        evidence_written = True
                    except (ContractError, AtomicLedgerError) as exc:
                        preselection_receipt[
                            "market_evidence_blocker"
                        ] = f"{type(exc).__name__}:{exc}"
                    # The forward binding names the persisted rows by content
                    # hash; recompute them through the same builders the insert
                    # used.
                    quote_raw["inventory_sha256"] = (
                        build_confirmed_inventory_snapshot(
                            inventory_raw
                        )["content_sha256"]
                    )
                    quote_raw["order_state_sha256"] = (
                        build_order_state_snapshot(
                            order_state_raw
                        )["content_sha256"]
                    )
                    if not evidence_written:
                        # The open binds to persisted rows, so without them it
                        # cannot be attempted -- and that absence is the
                        # blocker, named per charter 46 rather than left to the
                        # preliminary record to imply.
                        preselection_receipt["stage_open_blocker"] = (
                            "stage_open_not_attempted:"
                            "market_evidence_not_persisted"
                        )
                    else:
                        # Its own savepoint: a plan that fails partway through
                        # must leave no half-written cycle behind for the
                        # preliminary record that follows it -- and now no
                        # longer takes the book down with it.
                        try:
                            with _writer_transaction(
                                self.commit_conn,
                                savepoint="basket_target_p0_stage_open",
                            ):
                                opened = commit_production_candidate_atomic(
                                    self.commit_conn,
                                    compiled_plan=compiled_plan,
                                    market_snapshot=quote_raw,
                                    awc_observation_contract=None,
                                    truth_observation_revision_content_sha256=(
                                        ""
                                    ),
                                    bound=None,
                                    created_at_utc=evaluation_at_utc,
                                )
                        except (ContractError, AtomicLedgerError) as exc:
                            opened = None
                            preselection_receipt[
                                "stage_open_blocker"
                            ] = f"{type(exc).__name__}:{exc}"
                if opened is not None:
                    # The submission receipt is the only record of what
                    # happened at the exchange boundary -- which intents were
                    # gated, which reached the send and stopped there, and the
                    # payload hash a live run would have to reproduce byte for
                    # byte.  It rides the preselection receipt so it is
                    # readable from the status file without opening the
                    # ledger.
                    submission = opened.get("order_submission")
                    if isinstance(submission, Mapping):
                        preselection_receipt["order_submission"] = {
                            "cycle_id": submission.get("cycle_id"),
                            "intent_count": submission.get("intent_count"),
                            "orders_submitted": submission.get(
                                "orders_submitted"
                            ),
                            "live_submit_authorized": submission.get(
                                "live_submit_authorized"
                            ),
                            "calls_order_gateway": submission.get(
                                "calls_order_gateway"
                            ),
                            "submissions": [
                                {
                                    key: entry.get(key)
                                    for key in (
                                        "order_intent_id",
                                        "state",
                                        "reason",
                                        "payload_sha256",
                                        "exchange_post_started",
                                    )
                                    if key in entry
                                }
                                for entry in (
                                    submission.get("submissions") or ()
                                )
                                if isinstance(entry, Mapping)
                            ][:8],
                        }
                    decision_receipts.append(opened)
                    continue
                decision_receipts.append(
                    commit_preliminary_scope_decision(
                        self.commit_conn,
                        # Every path to here is a stage-open that did not
                        # open, and each one has to say which: raised (the
                        # except branch named it), never attempted (the
                        # guard above named it), or attempted and returned
                        # nothing -- the last had no name, and since the
                        # record now refuses to be written without one, an
                        # unnamed case aborted the whole production cycle
                        # rather than logging a blocked scope.
                        stage_open_blocker=(
                            str(
                                preselection_receipt.get(
                                    "stage_open_blocker"
                                )
                                or ""
                            ).strip()
                            or "stage_open_returned_no_candidate"
                        ),
                        preselection_id=str(item["preselection_id"]),
                        station_id=str(item["station_id"]),
                        event_date=str(item["event_date"]),
                        settlement_timezone=str(
                            item["settlement_timezone"]
                        ),
                        checkpoint_id=str(item["checkpoint_id"]),
                        probability_stage=str(item["probability_stage"]),
                        quote_manifest_sha256=str(
                            preselection_receipt[
                                "quote_manifest_sha256"
                            ]
                        ),
                        preselection_plan_sha256=str(
                            item["plan_sha256"]
                        ),
                        created_at_utc=evaluation_at_utc,
                    )
                )
        return {
            "schema": "bayes_basket_target_worker_p0_batch_v1",
            "state": "COMMITTED",
            "event_date": event_date,
            "portfolio_allocation": getattr(
                self, "_portfolio_allocation_last", None
            ),
            "portfolio_inventory": getattr(
                self, "_portfolio_inventory_last", None
            ),
            "station_count": len(compiled),
            "written_count": sum(1 for item in receipts if item["wrote"]),
            "receipts": receipts,
            "preliminary_decision_count": len(decision_receipts),
            "preliminary_decisions": decision_receipts,
            "write_authority": "TargetProductionWorker",
            "final_authority": "P1",
            "intents_written": 0,
            "reservations_written": 0,
            "places_orders": False,
            "calls_order_gateway": False,
            "live_submit_authorized": False,
            "orders_submitted": 0,
        }

    def _delta_v2_label_cursor_path(self) -> Path | None:
        root = getattr(self, "nwp_runtime_root", None)
        return root / "delta_v2_label_cursor.json" if isinstance(root, Path) else None

    def _load_persisted_delta_v2_label_cursor(self) -> None:
        """Seed the label cursor from the last page a previous process wrote.

        The cursor lived only in memory, so every restart rescanned the
        training facts from rowid 0: 235s on the first cycle after the
        2026-09-21 05:44Z restart, 180s at the worst before the outage, and
        restarts are not rare -- four that day.  The retry lane already
        wraps to rowid 0 on its own, so resuming from the persisted page
        skips nothing a page would not revisit anyway.

        Read once per process, and only when the cursor has not been set by
        a page this process committed.  Discarded, with a cold rescan, when
        the file is malformed, its lanes are inconsistent, or the rowid it
        names is past the store's newest fact -- which is what a rebuilt or
        substituted store looks like.
        """

        if getattr(self, "_delta_v2_label_cursor_initialized", False):
            return
        if getattr(self, "_delta_v2_label_cursor_loaded_from_disk", False):
            return
        self._delta_v2_label_cursor_loaded_from_disk = True
        path = self._delta_v2_label_cursor_path()
        if path is None or self.commit_conn is None:
            return
        try:
            raw = load_bounded_json(path)
        except Exception:  # noqa: BLE001 -- a hint, not a fact
            return
        if not isinstance(raw, Mapping) or raw.get("schema") != "delta_v2_label_cursor_v2":
            return
        try:
            scan = int(raw["scan_after_rowid"])
            retry = int(raw["retry_after_rowid"])
            lane = str(raw["next_lane"])
        except (KeyError, TypeError, ValueError):
            return
        if scan < 0 or retry < 0 or retry > scan or lane not in {"retry", "new"}:
            return
        try:
            newest = self.commit_conn.execute(
                "SELECT MAX(rowid) FROM basket_policy_training_fact"
            ).fetchone()
        except sqlite3.Error:
            return
        if newest is None or newest[0] is None or scan > int(newest[0]):
            return
        self._delta_v2_label_fact_cursor = scan
        self._delta_v2_label_cursor_state = {
            "schema": "delta_v2_label_cursor_v2",
            "scan_after_rowid": scan,
            "retry_after_rowid": retry,
            "next_lane": lane,
        }
        self._delta_v2_label_cursor_initialized = True

    def _persist_delta_v2_label_cursor(self, *, as_of_utc: str) -> None:
        """Write the committed cursor beside the maintenance turn."""

        path = self._delta_v2_label_cursor_path()
        if path is None:
            return
        state = dict(getattr(self, "_delta_v2_label_cursor_state", None) or {})
        if not state:
            return
        try:
            write_bounded_json_if_changed(
                path,
                {
                    "schema": "delta_v2_label_cursor_v2",
                    "scan_after_rowid": int(state.get("scan_after_rowid", 0)),
                    "retry_after_rowid": int(state.get("retry_after_rowid", 0)),
                    "next_lane": str(state.get("next_lane") or "retry"),
                    "persisted_at_utc": as_of_utc,
                },
            )
        except Exception:  # noqa: BLE001 -- telemetry and a restart hint
            pass

    def _materialize_delta_v2_labels(
        self,
        *,
        as_of_utc: str,
        enforce_interval: bool = True,
    ) -> dict[str, Any]:
        """Run bounded, independently throttled post-settlement label pages."""

        if self.commit_conn is None:
            return {
                "state": "not_attempted",
                "reason": "target_atomic_writer_not_injected",
                "appended_count": 0,
            }
        if enforce_interval:
            now_monotonic = time.monotonic()
            if (
                self._last_delta_v2_label_scan_monotonic is not None
                and now_monotonic
                - self._last_delta_v2_label_scan_monotonic
                < DELTA_V2_LABEL_SCAN_INTERVAL_SECONDS
            ):
                return {
                    "state": "throttled",
                    "reason": "delta_v2_label_scan_interval",
                    "appended_count": 0,
                }
            self._last_delta_v2_label_scan_monotonic = now_monotonic
        assert_process_memory_budget()
        self._load_persisted_delta_v2_label_cursor()
        source_cursor = (
            int(getattr(self, "_delta_v2_label_fact_cursor", 0))
            if bool(
                getattr(
                    self,
                    "_delta_v2_label_cursor_initialized",
                    False,
                )
            )
            else 0
        )
        committed_cursor = source_cursor
        committed_cursor_state = dict(
            getattr(self, "_delta_v2_label_cursor_state", {})
            or {
                "schema": "delta_v2_label_cursor_v2",
                "scan_after_rowid": source_cursor,
                "retry_after_rowid": 0,
                "next_lane": "retry",
            }
        )
        if int(
            committed_cursor_state.get("scan_after_rowid", -1)
        ) != source_cursor:
            committed_cursor_state = {
                "schema": "delta_v2_label_cursor_v2",
                "scan_after_rowid": source_cursor,
                "retry_after_rowid": 0,
                "next_lane": "retry",
            }
        page_results: list[dict[str, Any]] = []
        try:
            # One transaction per page, not one around all eight.  Paging
            # exists to bound the work; wrapping the loop in a single writer
            # transaction gave that bound away, because the lock is held for
            # the sum of the pages rather than for one of them.  Measured
            # 2026-09-09: this savepoint held the writer for 561.6 seconds in
            # a single call -- 9.4 minutes of a cycle whose target is 300
            # seconds, and 59% of every millisecond the writer lock was held
            # that cycle.  Eight pages now take eight locks and release seven
            # of them early.
            #
            # The failure semantics improve with it.  A page that comes back
            # ``blocked_fail_closed`` already broke the loop and kept its
            # predecessors -- that path is unchanged.  What changes is a page
            # that RAISES: it used to roll back the seven good pages with it
            # and leave the cursor where the pass began, so the next cycle
            # redid all of them.  Now the completed pages stand, and because
            # the cursor advances with each commit rather than after the
            # loop, the next pass resumes at the first page that did not
            # land instead of repeating the ones that did.
            for _page_number in range(
                MAX_DELTA_V2_LABEL_PAGES_PER_PASS
            ):
                assert_process_memory_budget()
                with _writer_transaction(
                    self.commit_conn,
                    savepoint="delta_v2_settlement_labels",
                ):
                    page = materialize_delta_v2_settled_training_labels(
                        self.commit_conn,
                        as_of_utc=as_of_utc,
                        after_fact_rowid=committed_cursor,
                        cursor_state=committed_cursor_state,
                        max_facts=MAX_LABEL_BATCH,
                    )
                page_results.append(dict(page))
                committed_cursor = int(
                    page.get("source_cursor_after")
                    or committed_cursor
                )
                next_cursor_state = page.get("cursor_state_after")
                if isinstance(next_cursor_state, Mapping):
                    committed_cursor_state = dict(next_cursor_state)
                else:
                    committed_cursor_state = {
                        "schema": "delta_v2_label_cursor_v2",
                        "scan_after_rowid": committed_cursor,
                        "retry_after_rowid": 0,
                        "next_lane": "retry",
                    }
                # Advanced per committed page, so a later raise cannot cost
                # the pages that are already durable.
                self._delta_v2_label_fact_cursor = committed_cursor
                self._delta_v2_label_cursor_state = committed_cursor_state
                self._delta_v2_label_cursor_initialized = True
                self._persist_delta_v2_label_cursor(as_of_utc=as_of_utc)
                if (
                    page.get("state") == "blocked_fail_closed"
                    or int(page.get("candidate_count") or 0) == 0
                    or not bool(page.get("has_more"))
                ):
                    break
        except Exception as exc:
            return {
                "schema": LABEL_BATCH_SCHEMA,
                "state": "blocked_fail_closed",
                "reason": f"{type(exc).__name__}:{exc}",
                "appended_count": 0,
                "forward_settlement_label_sync": {
                    "state": "blocked_fail_closed",
                    "reason": f"{type(exc).__name__}:{exc}",
                },
                "calls_order_gateway": False,
                "orders_submitted": 0,
                "live_submit_authorized": False,
            }
        result = {
            "schema": LABEL_BATCH_SCHEMA,
            "state": (
                "blocked_fail_closed"
                if any(
                    page.get("state") == "blocked_fail_closed"
                    for page in page_results
                )
                else (
                    "committed"
                    if sum(
                        int(page.get("appended_count") or 0)
                        for page in page_results
                    )
                    else "no_new_final_labels"
                )
            ),
            "candidate_count": sum(
                int(page.get("candidate_count") or 0)
                for page in page_results
            ),
            "appended_count": sum(
                int(page.get("appended_count") or 0)
                for page in page_results
            ),
            "blockers": [
                blocker
                for page in page_results
                for blocker in (
                    page.get("blockers")
                    if isinstance(page.get("blockers"), list)
                    else []
                )
            ],
            "source_cursor_before": source_cursor,
            "source_cursor_after": committed_cursor,
            "page_count": len(page_results),
            "page_limit": MAX_DELTA_V2_LABEL_PAGES_PER_PASS,
            "has_more": bool(
                page_results
                and page_results[-1].get("has_more")
                and len(page_results)
                >= MAX_DELTA_V2_LABEL_PAGES_PER_PASS
            ),
            "skipped_open_count": sum(
                int(page.get("skipped_open_count") or 0)
                for page in page_results
            ),
        }
        # The target label table is the append-only authority; the separate
        # v2 store is a replayable projection.  Commit the authority first.
        # A projection failure leaves a retryable lag, never an orphaned store
        # label copied from a source transaction that later rolled back.
        try:
            store_path = (
                DEFAULT_STORE_PATH
                if getattr(self, "cash_phase_forward_store_path", None) is None
                else self.cash_phase_forward_store_path
            )
            store_root = getattr(
                self,
                "cash_phase_forward_store_root",
                DEFAULT_STORE_ROOT,
            )
            store_state = read_forward_store_state(
                store_path,
                allowed_root=store_root,
            )
            sync_pages: list[dict[str, Any]] = []
            for _page_number in range(
                MAX_DELTA_V2_LABEL_PAGES_PER_PASS
            ):
                label_sync = append_forward_settlement_labels(
                    store_path,
                    source_conn=self.commit_conn,
                    expected_generation=int(store_state["generation"]),
                    as_of_utc=as_of_utc,
                    allowed_root=store_root,
                )
                if not isinstance(label_sync, Mapping):
                    raise ContractError(
                        "forward_store_settlement_label_sync_result_invalid"
                    )
                sync_pages.append(dict(label_sync))
                if not bool(label_sync.get("more_pending")):
                    break
                store_state = read_forward_store_state(
                    store_path,
                    allowed_root=store_root,
                )
            label_sync = {
                "state": (
                    "committed"
                    if any(
                        int(page.get("ingested") or 0) > 0
                        or page.get("state") == "committed"
                        for page in sync_pages
                    )
                    else "already_current"
                ),
                "page_count": len(sync_pages),
                "page_limit": MAX_DELTA_V2_LABEL_PAGES_PER_PASS,
                "inserted": sum(
                    int(page.get("inserted") or 0)
                    for page in sync_pages
                ),
                "skipped_ineligible": sum(
                    int(page.get("skipped_ineligible") or 0)
                    for page in sync_pages
                ),
                "ingested": sum(
                    int(page.get("ingested") or 0)
                    for page in sync_pages
                ),
                "more_pending": bool(
                    sync_pages
                    and sync_pages[-1].get("more_pending")
                    and len(sync_pages)
                    >= MAX_DELTA_V2_LABEL_PAGES_PER_PASS
                ),
                "generation": (
                    sync_pages[-1].get("generation")
                    if sync_pages
                    else store_state.get("generation")
                ),
            }
        except Exception as exc:
            return {
                **result,
                "state": "blocked_fail_closed",
                "reason": f"{type(exc).__name__}:{exc}",
                "source_labels_committed": True,
                "forward_settlement_label_sync": {
                    "state": "blocked_fail_closed",
                    "reason": f"{type(exc).__name__}:{exc}",
                },
                "calls_order_gateway": False,
                "orders_submitted": 0,
                "live_submit_authorized": False,
            }
        return {
            **result,
            "source_labels_committed": True,
            "forward_settlement_label_sync": dict(label_sync),
            "calls_order_gateway": False,
            "orders_submitted": 0,
            "live_submit_authorized": False,
        }

    def _materialize_delta_v2_truths(
        self,
        *,
        as_of_utc: str,
    ) -> dict[str, Any]:
        """Freeze bounded registry-timezone truth before label materialization."""

        if self.commit_conn is None:
            return {
                "state": "not_attempted",
                "reason": "target_atomic_writer_not_injected",
                "written_count": 0,
            }
        if self.canonical_source_conn is None:
            return {
                "state": "blocked_fail_closed",
                "reason": self.canonical_source_error
                or "resident_canonical_source_not_configured",
                "written_count": 0,
                "calls_order_gateway": False,
                "orders_submitted": 0,
                "live_submit_authorized": False,
            }
        now_monotonic = time.monotonic()
        last_truth_scan = getattr(
            self,
            "_last_delta_v2_truth_scan_monotonic",
            None,
        )
        if (
            last_truth_scan is not None
            and now_monotonic - last_truth_scan
            < DELTA_V2_LABEL_SCAN_INTERVAL_SECONDS
        ):
            return {
                "state": "throttled",
                "reason": "delta_v2_settlement_scan_interval",
                "written_count": 0,
                "calls_order_gateway": False,
                "orders_submitted": 0,
                "live_submit_authorized": False,
            }
        self._last_delta_v2_truth_scan_monotonic = now_monotonic
        assert_process_memory_budget()
        committed_cursor: int | None = None
        committed_initialization = bool(
            getattr(
                self,
                "_delta_v2_truth_cursor_initialized",
                False,
            )
        )
        try:
            with _writer_transaction(
                self.commit_conn,
                savepoint="delta_v2_settlement_truths",
            ):
                if committed_initialization:
                    source_cursor = int(
                        getattr(
                            self,
                            "_delta_v2_truth_fact_cursor",
                            0,
                        )
                    )
                else:
                    # A resident restart must not spend its first bounded
                    # pass on the oldest historical scopes while the current
                    # 45-station page waits behind them.  Start immediately
                    # before the newest bounded page, then use the normal
                    # end-of-keyset wrap to revisit history.
                    newest_page = self.commit_conn.execute(
                        "SELECT min(source_rowid) FROM ("
                        "SELECT max(rowid) AS source_rowid "
                        "FROM basket_policy_training_fact "
                        "GROUP BY station_id,event_date "
                        "ORDER BY source_rowid DESC LIMIT ?"
                        ")",
                        (MAX_FORWARD_P0_STATIONS,),
                    ).fetchone()
                    first_source_rowid = int(
                        newest_page[0] or 0
                    ) if newest_page is not None else 0
                    source_cursor = max(0, first_source_rowid - 1)
                additional_scopes: list[tuple[str, str]] = []
                candidate_scopes = _candidate_ensemble_scopes_without_truth(
                    self.commit_conn,
                    limit=expected_station_count() * 4,
                )
                if candidate_scopes:
                    # Bootstrap truth directly from bounded forward member
                    # scope identities.  Without this bridge the first strict
                    # OOS P0 is circular: basket facts require P0, while truth
                    # discovery previously required basket facts.  This is
                    # intentionally source-neutral at the storage boundary:
                    # both tables remain candidate-only until the later
                    # closed-AWC strict-OOS validator accepts their evidence.
                    as_of = datetime.fromisoformat(
                        as_of_utc.replace("Z", "+00:00")
                    ).astimezone(timezone.utc)
                    timezone_by_scope: dict[
                        tuple[str, str], set[str]
                    ] = {}
                    for row in candidate_scopes:
                        scope = (
                            str(row[0] or "").strip().upper(),
                            str(row[1] or "").strip(),
                        )
                        timezone_by_scope.setdefault(
                            scope,
                            set(),
                        ).add(str(row[2] or "").strip())
                    settled_scopes: list[tuple[str, str]] = []
                    for scope, timezone_names in sorted(
                        timezone_by_scope.items()
                    ):
                        if len(timezone_names) != 1 or "" in timezone_names:
                            raise ContractError(
                                "native_truth_scope_timezone_not_unique"
                            )
                        window = settlement_day_window(
                            scope[1],
                            next(iter(timezone_names)),
                        )
                        closed_at = datetime.fromisoformat(
                            str(
                                window["target_day_end_utc"]
                            ).replace("Z", "+00:00")
                        ).astimezone(timezone.utc)
                        if closed_at <= as_of:
                            settled_scopes.append(scope)
                    # Rotate rather than always taking the first page of a
                    # station-sorted list.  The candidate set is routinely
                    # larger than one page, and cutting it at a fixed offset
                    # meant the same alphabetical prefix was served every
                    # cycle: stations late in the alphabet were never asked
                    # about at all.  They did not fail any gate -- a read-only
                    # replay of their scopes reaches the write -- they simply
                    # never got a turn, which is indistinguishable from a
                    # source outage in every receipt.
                    if settled_scopes:
                        page = min(45, len(settled_scopes))
                        start = int(
                            getattr(
                                self,
                                "_delta_v2_truth_bootstrap_cursor",
                                0,
                            )
                        ) % len(settled_scopes)
                        additional_scopes = [
                            settled_scopes[
                                (start + offset) % len(settled_scopes)
                            ]
                            for offset in range(page)
                        ]
                        self._delta_v2_truth_bootstrap_cursor = (
                            start + page
                        ) % len(settled_scopes)
                truth_kwargs: dict[str, Any] = {
                    "as_of_utc": as_of_utc,
                    "max_scopes": expected_station_count(),
                    "after_fact_rowid": source_cursor,
                }
                if additional_scopes:
                    truth_kwargs["additional_scopes"] = additional_scopes
                result = materialize_settled_training_truths(
                    self.commit_conn,
                    self.canonical_source_conn,
                    **truth_kwargs,
                )
                if (
                    result.get("state") == "blocked_fail_closed"
                    and not result.get("advance_safe")
                ):
                    blockers = [
                        item
                        for item in (result.get("blockers") or [])
                        if isinstance(item, Mapping)
                    ]
                    # Name the blocker that actually stopped the batch, not
                    # whichever happened to be first.  An all-availability
                    # batch no longer reaches here, so what remains is a trust
                    # failure -- and reporting an unrelated availability gap
                    # instead sends the reader looking for a missing report
                    # when the real problem is a contradiction.
                    consistency = [
                        item
                        for item in blockers
                        if item.get("blocker_class") != "AVAILABILITY"
                    ]
                    culprit = (consistency or blockers or [{}])[0]
                    raise ContractError(
                        "delta_v2_settlement_truth_blocked:"
                        + str(culprit.get("reason") or "unknown")
                        + ":"
                        + str(culprit.get("station_id") or "?")
                        + "|"
                        + str(culprit.get("event_date") or "?")
                        + f":consistency={len(consistency)}"
                        + f"/total={len(blockers)}"
                    )
                # A batch in which every scope was merely unsettleable is not a
                # system failure, and refusing to advance past it is what turned
                # a source gap into a standstill: 126 station-days with no
                # eligible hourly report filled the batch window from
                # 2026-08-02, every batch came back all-failed, the cursor was
                # never committed, and the same doomed scopes were reselected
                # forever.  No later station-day was ever reached, so settled
                # truth stopped for all 45 stations and P1 with it.
                #
                # The original caution above still holds for the case it was
                # written for -- a transaction that may yet fail must not move
                # the cursor past a page it could roll back.  An all-unavailable
                # batch wrote nothing, so there is no such page.
                committed_cursor = int(
                    result.get("source_cursor_after") or 0
                )
            # The in-memory cursor is only a post-commit optimization.  It
            # must never move while the database transaction can still fail,
            # otherwise a failed COMMIT would skip the rolled-back page.
            self._delta_v2_truth_fact_cursor = int(committed_cursor or 0)
            self._delta_v2_truth_cursor_initialized = True
        except Exception as exc:
            # A failed truth scan must never become a "safe throttle" on the
            # next resident cycle; otherwise an older accepted truth could
            # reach the label writer while the unresolved blocker is merely
            # being rate-limited.
            self._last_delta_v2_truth_scan_monotonic = None
            return {
                "schema": (
                    "bayes_basket_target_resident_settlement_truth_batch_v1"
                ),
                "state": "blocked_fail_closed",
                "reason": f"{type(exc).__name__}:{exc}",
                "written_count": 0,
                "calls_order_gateway": False,
                "orders_submitted": 0,
                "live_submit_authorized": False,
            }
        return result

    def _run_delta_v2_settlement_maintenance(
        self,
        *,
        as_of_utc: str,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        """Run closed-day truth/label work outside the current quote lease."""

        truth: dict[str, Any] | None = None
        try:
            truth = self._materialize_delta_v2_truths(
                as_of_utc=as_of_utc,
            )
            if truth.get("state") == "blocked_fail_closed":
                return truth, {
                    "state": "blocked_fail_closed",
                    "reason": "delta_v2_truth_required_before_label",
                    "appended_count": 0,
                    "calls_order_gateway": False,
                    "orders_submitted": 0,
                    "live_submit_authorized": False,
                }
            labels = self._materialize_delta_v2_labels(
                as_of_utc=as_of_utc,
                enforce_interval=True,
            )
            return truth, labels
        except Exception as exc:
            reason = f"{type(exc).__name__}:{exc}"
            return (
                truth
                or {
                    "state": "blocked_fail_closed",
                    "reason": reason,
                    "written_count": 0,
                    "calls_order_gateway": False,
                    "orders_submitted": 0,
                    "live_submit_authorized": False,
                },
                {
                    "state": "blocked_fail_closed",
                    "reason": reason,
                    "appended_count": 0,
                    "calls_order_gateway": False,
                    "orders_submitted": 0,
                    "live_submit_authorized": False,
                },
            )

    def _mark(self, stage: str) -> None:
        """Close the current stage of ``run`` and open the next one.

        A mark records the span since the previous mark, so the timings read
        as a timeline in the order the stages ran.  This is deliberately a
        single call per stage rather than a wrapper per stage: ``run`` is one
        long body with many early returns, and re-indenting it to profile it
        is how a profiling change becomes a behaviour change.
        """

        now = time.perf_counter()
        previous = getattr(self, "_stage_mark_at", now)
        self._stage_mark_at = now
        timings = getattr(self, "_stage_timings_ms", None)
        if timings is None:
            timings = {}
            self._stage_timings_ms = timings
        timings[stage] = round((now - previous) * 1000.0, 1)
        # Charter 180: when each stage ended, so the cycle's stack samples
        # can be told which stage they fell in.
        mark_log = getattr(self, "_stage_mark_log", None)
        if isinstance(mark_log, list):
            mark_log.append((stage, now))

    def _add_span(
        self, name: str, elapsed_ms: float, *, label: str = ""
    ) -> None:
        """Record one span directly, for call sites ``_span`` cannot wrap.

        A ``with`` around a forty-line keyword call would re-indent the call
        to measure it, and re-indenting working code to profile it is how a
        profiling change becomes a behaviour change.  Such a site records
        only on success; the loop's own handler already reports the failure.
        """

        spans = getattr(self, "_stage_spans", None)
        if spans is None:
            spans = {}
            self._stage_spans = spans
        row = spans.setdefault(
            name,
            {"count": 0, "total_ms": 0.0, "max_ms": 0.0, "slowest": ""},
        )
        row["count"] += 1
        row["total_ms"] += elapsed_ms
        if elapsed_ms > row["max_ms"]:
            row["max_ms"] = elapsed_ms
            row["slowest"] = label

    @contextmanager
    def _span(self, name: str, *, label: str = "") -> Iterator[None]:
        """Fold one repetition of a per-item stage into a cycle summary.

        ``_mark`` describes a timeline and cannot describe a loop: the two
        stages that now dominate a cycle are both loops, and a mark around
        either reports one number for forty-odd iterations.  This keeps the
        count, the total, and which single item was worst -- enough to tell
        "uniformly slow" from "one scope is pathological", which are
        different bugs and were indistinguishable from the timeline alone.

        A span never swallows an exception; a failed iteration is still
        counted, because a fast failure that repeats is itself a finding.
        """

        started = time.perf_counter()
        try:
            yield
        finally:
            self._add_span(
                name,
                (time.perf_counter() - started) * 1000.0,
                label=label,
            )

    def _stage_span_summary(self) -> dict[str, Any]:
        """Merge the worker's spans with the ledger's into one report.

        They measure the same cycle through two modules; reporting them
        apart just makes the reader add them up.
        """

        spans = getattr(self, "_stage_spans", None) or {}
        merged: dict[str, Any] = dict(ledger_span_profile())
        merged.update({
            name: {
                "count": int(row["count"]),
                "total_ms": round(float(row["total_ms"]), 1),
                "max_ms": round(float(row["max_ms"]), 1),
                "mean_ms": round(
                    float(row["total_ms"]) / max(1, int(row["count"])), 1
                ),
                "slowest": str(row["slowest"]),
            }
            for name, row in spans.items()
        })
        return dict(
            sorted(
                merged.items(),
                key=lambda item: -float(item[1]["total_ms"]),
            )
        )

    def run(self) -> dict[str, Any]:
        """Run one production cycle and report where its time went.

        The cycle is submitted every 15s but has been taking 6-16 minutes,
        and until now a slow cycle and a wedged one were indistinguishable
        from outside: the result said what the cycle concluded, never what it
        spent.  Publish the stage timeline and the write-lock profile beside
        the result so the next stall is read from the status file.
        """

        self._stage_timings_ms = {}
        self._stage_spans = {}
        self._stage_mark_at = time.perf_counter()
        # The maintenance allowance is per cycle; the turns it charges
        # against outlive the process.
        self._maintenance_spent_sec = 0.0
        self._maintenance_admissions = {}
        self._quote_lease_seconds = None
        # Which scopes the last decision loop refused for want of a P0-M
        # replay.  Carried across the cycle boundary on purpose: the P0-M
        # lane runs before the decision loop, so the only refusals it can
        # order itself by are the previous round's -- and a scope stays in
        # the set until a replay clears it, which is exactly the condition
        # for wanting the budget.
        #
        # It reads the guard's answer rather than recomputing it.  Deciding
        # "is this scope blocked" up front would mean loading every
        # station-day's envelopes before the loop that exists to avoid
        # exactly that, and an ordering hint that re-derives the rule is how
        # an ordering hint comes to disagree with it.
        self._p0m_replay_blocked_scopes = frozenset(
            getattr(self, "_p0m_replay_blocked_next", frozenset())
        )
        self._p0m_replay_blocked_next = set()
        self._begin_cycle_scratch()
        begin_statement_ledger()
        # Charter 180: the Python-side counterpart of the statement ledger.
        self._stage_mark_log = []
        sampler = (
            CycleStackSampler(threading.get_ident()).start()
            if sampler_enabled()
            else None
        )
        samples = None
        started = time.perf_counter()
        reset_writer_lock_profile()
        reset_ledger_spans()
        try:
            result = self._run_stages()
        finally:
            if sampler is not None:
                samples = sampler.stop()
            total_ms = round((time.perf_counter() - started) * 1000.0, 1)
            # Marks tile a timeline, so what they do not name is arithmetic,
            # not a mystery -- but only if someone does the arithmetic.  For
            # three weeks nobody did, and every overrun was read off a
            # profile that silently covered a minority of the cycle.  Publish
            # the residual: a stage added after the last mark, or an early
            # return that skips one, now shows up as ``unattributed`` growing
            # rather than as a timeline that quietly stops accounting.
            named_ms = sum(
                float(value)
                for key, value in self._stage_timings_ms.items()
                if key != "cycle_total" and isinstance(value, (int, float))
            )
            self._stage_timings_ms["unattributed"] = round(
                max(0.0, total_ms - named_ms), 1
            )
            self._stage_timings_ms["cycle_total"] = total_ms
        if isinstance(result, dict):
            result.setdefault("stage_timings_ms", dict(self._stage_timings_ms))
            result.setdefault("stage_span_ms", self._stage_span_summary())
            result.setdefault(
                "maintenance_lane", self._maintenance_lane_report()
            )
            result.setdefault("writer_lock_profile", writer_lock_profile())
            result.setdefault("statement_ledger_top", statement_ledger_top(15))
            if sampler is not None and samples is not None:
                result.setdefault("python_sample_top", summarize_samples(
                    samples,
                    marks=list(self._stage_mark_log),
                    interval_sec=sampler.interval_sec,
                ))
            if self.stop_requested:
                result["cycle_interrupted"] = True
        return result

    def _run_stages(self) -> dict[str, Any]:
        if self.conn is None:
            return _blocked(self._target_open_blocker())
        if self.commit_error is not None:
            return _blocked(self.commit_error)
        if self.commit_conn is None:
            # A writer that was never enabled is not an error, so it leaves
            # ``commit_error`` unset and slips past the guard above with a
            # None connection -- which then reaches the first of a dozen
            # bare ``self.commit_conn.execute`` calls a hundred lines later
            # and surfaces as ``AttributeError: 'NoneType' object has no
            # attribute 'execute'``, naming neither the connection nor the
            # switch.  It cost a wrong lead during the 2026-08-15 stall
            # diagnosis.  Same reason string the forward preselection path
            # already uses for the same condition.
            return _blocked("target_atomic_writer_not_injected")
        try:
            # Schema-dispatching on purpose: self.activation_path is the live
            # contract in live mode, and the narrow loader shut production for
            # seven hours the first time and one more cycle the second.
            activation = load_activation(self.activation_path)
            self._assert_db_activation(activation)
        except Exception as exc:
            return _blocked(f"target_activation_invalid:{type(exc).__name__}:{exc}")
        self._record_quote_lease_seconds(activation)
        self._mark("activation")
        # The fast lane, first of all (user, 2026-09-19: 「把taf和metar的抓取
        # 入库和bayes更新优先级提高最高」).  New TAFs become P0-M and new
        # reports become P1 before the intent reconcile below, which measured
        # a 49s median and delayed both for no dependency: neither stage reads
        # an intent, and the reconcile still runs before anything is priced
        # or ordered.  Both read their watermark before their clock (charter
        # 148's rule) and neither can raise, so nothing here can keep the
        # reconcile from running.
        self._early_p1_this_cycle = None
        self._early_p0m_this_cycle = None
        self._fast_lane_receipts = []
        self._copy_follow_receipts = []
        self._probability_chain_ran = False
        self._regime_ran_this_cycle = False
        early_report_watermark = _live_observation_watermark(
            getattr(self, "canonical_source_conn", None)
        )
        early_taf_watermark = _taf_inbox_watermark(
            getattr(self, "taf_inbox_path", None)
        )
        early_now = utc_now()
        self._early_p0m_this_cycle = self._materialize_early_p0m(
            as_of_utc=early_now, taf_watermark=early_taf_watermark,
        )
        self._mark("early_p0m")
        self._early_p1_this_cycle = self._materialize_early_p1(
            as_of_utc=early_now,
            report_watermark=early_report_watermark,
            force=bool((self._early_p0m_this_cycle or {}).get("new_envelopes")),
            stage_clock_utc=(self._early_p0m_this_cycle or {}).get("stage_clock_utc"),
        )
        self._early_p1_watermark = early_report_watermark
        self._mark("early_p1")
        self._last_fast_lane_checkpoint_mono = time.monotonic()
        self._last_fast_lane_checkpoint_cost_sec = 0.0
        # Close intents the exchange has already answered about, before the
        # cycle spends anything on anything else.
        #
        # Above the market ingress on purpose.  This lane reads the exchange
        # by deterministic order id and writes only this ledger; it has no
        # use for quotes, inventory or a scope catalog, and it was sitting
        # downstream of all of them.  That gate is soft today -- a failed
        # ingress lets the cycle continue -- so the lane still ran, but a
        # question about whether real money is resting at an exchange should
        # not be answerable only when the market evidence happens to
        # materialize.  Nothing above this point can keep it from running.
        # Charter 141: read the real account before anything sizes off it.
        # At most once a minute; a failed read leaves the last row to age out,
        # and production refuses once it is older than the freshness bound.
        try:
            with self._span("account_equity_capture"):
                account_equity_receipt = self._capture_account_equity(
                    as_of_utc=utc_now(),
                )
        except Exception as exc:  # noqa: BLE001 -- observational lane
            account_equity_receipt = {
                "state": "blocked_fail_closed",
                "reason": f"{type(exc).__name__}:{exc}"[:160],
            }
        try:
            with self._span("reconcile_unresolved_intents"):
                intent_reconcile = self._reconcile_unresolved_intents(
                    as_of_utc=utc_now(),
                )
        except Exception as exc:  # noqa: BLE001 -- observational lane
            intent_reconcile = {
                "schema": "bayes_basket_target_intent_reconcile_v1",
                "state": "blocked_fail_closed",
                "reason": f"{type(exc).__name__}:{exc}"[:160],
                "closed": 0,
            }
        # Charter 94: the resting ladder follows the bid.  Every resting
        # rung is synced with the exchange (a resting order is polled by
        # nothing else) and a rung off the ladder that stands is cancelled,
        # which frees its bucket for the re-post the next compile makes.
        try:
            with self._span("reprice_resting_rungs"):
                resting_reprice = self._reprice_resting_rungs(
                    as_of_utc=utc_now(),
                )
        except Exception as exc:  # noqa: BLE001 -- observational lane
            resting_reprice = {
                "schema": "bayes_basket_target_resting_reprice_v1",
                "state": "blocked_fail_closed",
                "reason": f"{type(exc).__name__}:{exc}"[:160],
            }
        # And retire the ones no cycle will ever submit, which would
        # otherwise hold their buckets shut indefinitely.
        try:
            with self._span("retire_stranded_intents"):
                intent_retire = self._retire_stranded_prepared_intents(
                    as_of_utc=utc_now(),
                )
        except Exception as exc:  # noqa: BLE001 -- observational lane
            intent_retire = {
                "schema": "bayes_basket_target_intent_retire_v1",
                "state": "blocked_fail_closed",
                "reason": f"{type(exc).__name__}:{exc}"[:160],
                "retired": 0,
            }
        # And settle the live cycles whose orders have all ended: a batch
        # that traded and is over must stop standing as the station-day's
        # active candidate, or nothing after it can be committed.
        try:
            with self._span("settle_live_cycles"):
                live_cycle_settle = self._settle_live_cycles(
                    as_of_utc=utc_now()
                )
        except Exception as exc:  # noqa: BLE001 -- observational lane
            live_cycle_settle = {
                "schema": "bayes_basket_target_live_cycle_settle_v1",
                "state": "blocked_fail_closed",
                "reason": f"{type(exc).__name__}:{exc}"[:160],
                "settled": 0,
            }
        self._mark("intent_reconcile")
        scope = activation.get("target_scope")
        if not isinstance(scope, Mapping):
            return _blocked("target_scope_config_missing")
        missing = [key for key in TARGET_SCOPE_KEYS if not str(scope.get(key) or "").strip()]
        if missing:
            return _blocked("target_scope_missing:" + ",".join(missing))
        try:
            cash_phase_forward_observations = (
                self._flush_cash_phase_forward_observations()
            )
        except Exception as exc:
            cash_phase_forward_observations = {
                "state": "blocked_fail_closed",
                "reason": f"{type(exc).__name__}:{exc}",
                "observation_count": 0,
                "written": False,
                "orders_submitted": 0,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
            }
        self._mark("cash_phase_flush")
        # Charter 148: read before the clock, so a report committed in
        # between is inside this cycle's as-of read and at worst makes
        # the next cycle's head pass run once more -- never the reverse.
        cycle_report_watermark = _live_observation_watermark(
            getattr(self, "canonical_source_conn", None)
        )
        now = utc_now()
        market_ingress: dict[str, Any] | None = None
        resident_p0_ingress: dict[str, Any] | None = None
        resident_p0m_ingress: dict[str, Any] | None = None
        resident_p1_ingress: dict[str, Any] | None = None
        resident_probability_chain: dict[str, Any] | None = None
        regime_ingress: dict[str, Any] | None = None
        truth_materialization: dict[str, Any] | None = None
        delta_v2_truth_ingress: dict[str, Any] | None = None
        delta_v2_label_ingress: dict[str, Any] | None = None
        post_fill_recompute: dict[str, Any] | None = None
        resident_registry_ingress: dict[str, Any] | None = None
        native_ensemble_ingress: dict[str, Any] | None = None
        native_ensemble_oos_ingress: dict[str, Any] | None = None
        forward_p0_preselections: list[dict[str, Any]] = []
        try:
            registry_path = (
                self.nwp_runtime_root / "market_registry_forward.json"
            )
            if registry_path.is_file():
                resident_registry_ingress = ingest_target_market_registry(
                    self.commit_conn,
                    snapshot_path=registry_path,
                    commit=True,
                    as_of_utc=now,
                )
            else:
                resident_registry_ingress = {
                    "state": "not_available",
                    "reason": "resident_registry_snapshot_missing",
                    "wrote_rows": 0,
                    "writes_target_database": False,
                    "calls_order_gateway": False,
                    "places_orders": False,
                }
            self._mark("registry_ingress")
            native_inbox_path = (
                self.nwp_runtime_root
                / "native_ensemble_forward_inbox.json"
            )
            official_inbox_path = (
                self.nwp_runtime_root
                / "official_native_ensemble_forward_inbox.json"
            )
            if (
                native_inbox_path.is_file()
                or official_inbox_path.is_file()
            ):
                # The coordinator freezes the current station×event-date
                # scope in the environment.  Resident inboxes may retain
                # older/future observational packets, but those packets must
                # not be ingested or replayed in this cycle: mixing dates
                # turns the 45-station cap into a station-day cap and can
                # fail the whole chain closed.  Empty allowlists preserve the
                # bounded standalone/research worker behavior.
                allowed_stations = tuple(
                    getattr(self, "station_allowlist", ())
                )
                allowed_event_dates = tuple(
                    getattr(self, "event_date_allowlist", ())
                )

                # Charter 195 (一): what the replay compile below covers, read
                # before the inbox itself so a merge landing in between moves
                # the mark past it and the next checkpoint compiles it.
                official_mark = _official_inbox_watermark(official_inbox_path)
                raw_native_packets: list[Mapping[str, Any]] = []
                if native_inbox_path.is_file():
                    raw_native_packets.extend(
                        _load_native_forward_inbox(
                            native_inbox_path,
                            error_code=(
                                "native_ensemble_forward_inbox_invalid"
                            ),
                        )
                    )
                if official_inbox_path.is_file():
                    raw_native_packets.extend(
                        _load_native_forward_inbox(
                            official_inbox_path,
                            error_code=(
                                "official_native_forward_inbox_invalid"
                            ),
                        )
                    )
                if len(raw_native_packets) > 256:
                    raise ContractError(
                        "combined_native_forward_inbox_limit_exceeded"
                    )
                if any(
                    packet.get("schema")
                    not in {
                        OPEN_METEO_FORWARD_PACKET_SCHEMA,
                        OFFICIAL_NATIVE_FORWARD_PACKET_SCHEMA,
                    }
                    for packet in raw_native_packets
                ):
                    raise ContractError(
                        "native_forward_packet_schema_invalid"
                    )
                valid_native_packets = [
                    packet
                    for packet in raw_native_packets
                    if _forward_packet_in_cycle_scope(
                        packet,
                        station_allowlist=allowed_stations,
                        event_date_allowlist=allowed_event_dates,
                    )
                ]
                pending_native_packets: list[Mapping[str, Any]] = []
                for packet in valid_native_packets:
                    if packet.get("schema") != (
                        OPEN_METEO_FORWARD_PACKET_SCHEMA
                    ):
                        continue
                    station_id = str(
                        packet.get("station_id") or ""
                    ).strip().upper()
                    event_date = str(
                        packet.get("event_date") or ""
                    )
                    bucket_contract_sha = str(
                        packet.get("bucket_contract_sha256") or ""
                    )
                    for system in packet.get("systems") or []:
                        if not isinstance(system, Mapping):
                            continue
                        if not _open_meteo_packet_bucket_exists(
                            self.commit_conn,
                            ensemble_system_id=str(
                                system.get("ensemble_system_id") or ""
                            ),
                            station_id=station_id,
                            event_date=event_date,
                            member_set_sha256=str(
                                system.get("member_set_sha256") or ""
                            ),
                            bucket_contract_sha256=bucket_contract_sha,
                        ):
                            pending_native_packets.append(packet)
                            break
                selected_native_packets = pending_native_packets[
                    :MAX_RESIDENT_NWP_SCOPES_PER_CYCLE
                ]
                native_receipts = [
                    ingest_forward_packet(
                        self.commit_conn,
                        packet,
                    )
                    for packet in selected_native_packets
                ]
                native_ensemble_ingress = {
                    "schema": "native_ensemble_forward_ingress_batch_v1",
                    "state": "COMMITTED",
                    "packet_count": len(native_receipts),
                    "inbox_packet_count": len(valid_native_packets),
                    "raw_inbox_packet_count": len(raw_native_packets),
                    "filtered_out_of_scope_packet_count": (
                        len(raw_native_packets) - len(valid_native_packets)
                    ),
                    "station_allowlist": sorted(allowed_stations),
                    "event_date_allowlist": sorted(allowed_event_dates),
                    "event_date_scope_source": str(
                        getattr(self, "event_date_scope_source", "unconfigured")
                    ),
                    "pending_packet_count_before": len(
                        pending_native_packets
                    ),
                    "remaining_packet_count_after": max(
                        0,
                        len(pending_native_packets)
                        - len(selected_native_packets),
                    ),
                    "max_packets_per_cycle":
                        MAX_RESIDENT_NWP_SCOPES_PER_CYCLE,
                    "receipts": native_receipts,
                    "writes_target_database": any(
                        sum(receipt["counts"].values()) > 0
                        for receipt in native_receipts
                    ),
                    "calls_order_gateway": False,
                    "orders_submitted": 0,
                    "live_submit_authorized": False,
                }
                active_native_stations = {
                    str(row[0]).strip().upper()
                    # Station by station, an index seek each (a skip scan
                    # written out), then one seek for a valid row: the bare
                    # DISTINCT went through the artifact_kind index and read
                    # every CROSS activation row, 9-19 s of every cycle on
                    # 2026-10-02, for 45 stations.  Same rows (station_id is
                    # NOT NULL), 0.06 s.
                    for row in self.commit_conn.execute(
                        "WITH RECURSIVE s(station_id) AS ("
                        " SELECT (SELECT MIN(station_id)"
                        " FROM calibration_native_ensemble_activation)"
                        " UNION ALL SELECT (SELECT MIN(station_id)"
                        " FROM calibration_native_ensemble_activation"
                        " WHERE station_id>s.station_id)"
                        " FROM s WHERE s.station_id IS NOT NULL)"
                        " SELECT s.station_id FROM s"
                        " WHERE s.station_id IS NOT NULL AND EXISTS ("
                        "SELECT 1 FROM calibration_native_ensemble_activation a"
                        " WHERE a.station_id=s.station_id"
                        " AND a.artifact_kind='CROSS_NATIVE_ENSEMBLE'"
                        " AND a.valid_until_utc>?"
                        " AND a.authority_scope='PRODUCTION_NO_LIVE_ONLY'"
                        " AND a.valid_from_utc<=?)"
                        " ORDER BY s.station_id LIMIT ?",
                        (now, now, MAX_FORWARD_P0_STATIONS),
                    )
                }
                self._mark("native_inbox_ingest")
                # Official native remains first choice for each station-day.
                # If it is absent at this evidence instant, retain the
                # explicitly labelled Open-Meteo packet for the compiler's
                # independently enforced, closed-day strict-OOS no-live
                # fallback gate.  This selection never upgrades transport
                # lineage or lets a republisher replace a native packet.
                (
                    preferred_p0_packets,
                    official_by_scope,
                    republisher_by_scope,
                ) = _preferred_forward_packets_for_p0(valid_native_packets)
                active_replay_packets = []
                for _scope, packet in sorted(
                    preferred_p0_packets.items(),
                    key=lambda item: (item[0][1], item[0][0]),
                    reverse=True,
                ):
                    station = str(
                        packet.get("station_id") or ""
                    ).strip().upper()
                    if station not in active_native_stations:
                        continue
                    try:
                        window = settlement_day_window(
                            str(packet.get("event_date") or ""),
                            str(
                                packet.get("settlement_timezone")
                                or ""
                            ),
                        )
                        closes_at = datetime.fromisoformat(
                            str(
                                window["target_day_end_utc"]
                            ).replace("Z", "+00:00")
                        ).astimezone(timezone.utc)
                    except Exception:
                        continue
                    if closes_at <= datetime.fromisoformat(
                        now.replace("Z", "+00:00")
                    ).astimezone(timezone.utc):
                        continue
                    active_replay_packets.append(packet)
                # One packet per station-day, so several open days put this
                # above the station count without anything being wrong.
                if len(active_replay_packets) > MAX_FORWARD_P0_STATION_DAYS:
                    raise ContractError("official_native_forward_scope_bound_exceeded")
                active_replay_compiled = []
                active_replay_failures = []
                active_replay_fallback_attempts = []
                active_republisher_fallback_used = 0
                for replay_packet in active_replay_packets:
                    replay_scope = (
                        str(replay_packet.get("station_id") or "")
                        .strip()
                        .upper(),
                        str(replay_packet.get("event_date") or ""),
                    )
                    compiled, failures, source_class = (
                        _compile_native_p0_with_republisher_fallback(
                            self.commit_conn,
                            scope=replay_scope,
                            preferred_packet=replay_packet,
                            official_packet=official_by_scope.get(replay_scope),
                            republisher_packet=republisher_by_scope.get(
                                replay_scope
                            ),
                            decision_at_utc=now,
                            native_oos_snapshot=self.native_oos_snapshot,
                        )
                    )
                    if compiled is None:
                        active_replay_failures.extend(failures)
                        continue
                    try:
                        compiled["forward_prediction_persistence"] = (
                            persist_native_ensemble_forward_prediction(
                                self.commit_conn,
                                compiled,
                            )
                        )
                    except Exception as exc:
                        active_replay_failures.append({
                            "station_id": replay_scope[0],
                            "event_date": replay_scope[1],
                            "source_class": source_class,
                            "reason": f"{type(exc).__name__}:{exc}",
                        })
                        continue
                    if source_class == "aggregator_republisher":
                        active_replay_fallback_attempts.extend(failures)
                        active_republisher_fallback_used += 1
                    active_replay_compiled.append(compiled)
                active_activation_p0_replay = (
                    _upsert_native_p0_inbox(
                        self.p0_inbox_path,
                        compiled_packets=active_replay_compiled,
                        generated_at_utc=now,
                    )
                    if active_replay_compiled
                    else {
                        "state": "NO_COMPILED_P0",
                        "accepted_count": 0,
                        "packet_count": 0,
                        "wrote": False,
                        "calls_order_gateway": False,
                        "orders_submitted": 0,
                        "live_submit_authorized": False,
                    }
                )
                active_activation_p0_replay["active_station_count"] = (
                    len(active_native_stations)
                )
                active_activation_p0_replay["official_packet_count"] = (
                    len(official_by_scope)
                )
                active_activation_p0_replay[
                    "republisher_fallback_packet_count"
                ] = len(republisher_by_scope)
                active_activation_p0_replay[
                    "republisher_fallback_used_count"
                ] = active_republisher_fallback_used
                active_activation_p0_replay[
                    "republisher_fallback_attempts"
                ] = active_replay_fallback_attempts
                active_activation_p0_replay["failures"] = (
                    active_replay_failures
                )
                native_ensemble_ingress[
                    "active_activation_p0_replay"
                ] = active_activation_p0_replay
                # Charter 195 (一): the checkpoints compile only what moved
                # past this pass -- the snapshots it compiled, the stations it
                # had activations for, and the inbox content it read.
                self._p0_replay_compiled_shas = {
                    (
                        str(packet.get("station_id") or "").strip().upper(),
                        str(packet.get("event_date") or ""),
                    ): str(packet.get("snapshot_content_sha256") or "")
                    for packet in active_replay_packets
                    if str(packet.get("schema") or "")
                    == OFFICIAL_NATIVE_FORWARD_PACKET_SCHEMA
                }
                self._p0_replay_active_stations = set(active_native_stations)
                self._p0_covered_official_watermark = official_mark
                self._mark("native_p0_replay_compile")
                self._fast_lane_checkpoint_if_due("after_native_p0_replay_compile")
                now_mono = time.monotonic()
                last_oos_scan = getattr(
                    self,
                    "_last_native_ensemble_oos_scan_monotonic",
                    None,
                )
                # Charter 189: a live maintenance worker owns the OOS pass;
                # this cycle only replays what it handed over (below), and
                # skips the candidate scan the pass alone needs.
                oos_delegate = (
                    maintenance_worker_alive()
                    if str(os.environ.get("PM_MAINTENANCE_WORKER", "1")).strip()
                    not in {"0", "false", "off"}
                    else {"alive": False, "reason": "disabled"}
                )
                oos_delegated = bool(oos_delegate.get("alive"))
                new_oos_stations = [] if oos_delegated else sorted({
                    str(receipt["station_id"])
                    for receipt in native_receipts
                    if sum(receipt["counts"].values()) > 0
                })
                all_oos_stations = [] if oos_delegated else (
                    _candidate_ensemble_station_ids(
                        self.commit_conn,
                        limit=MAX_FORWARD_P0_STATIONS,
                    )
                )
                truth_signatures = {} if oos_delegated else (
                    _native_ensemble_truth_signatures(
                        self.commit_conn,
                    )
                )
                previous_truth_signatures = dict(getattr(
                    self,
                    "_native_ensemble_oos_truth_signature_by_station",
                    {},
                ))
                changed_truth_stations = [
                    station
                    for station, signature
                    in sorted(truth_signatures.items())
                    if previous_truth_signatures.get(station)
                    != signature
                ]
                new_oos_stations = sorted(set(
                    new_oos_stations + changed_truth_stations
                ))
                self._mark("oos_candidate_scan")
                # One station per production cycle, throttled only enough to
                # keep a fast cycle from spinning the sweep.  At 600s the
                # sweep took 45 x 10min = 7.5 hours to carry a calibration
                # change fleet-wide, while the work itself is 13-19s per
                # station -- a 4% duty cycle, and the reason 41 weight rows
                # sat 3 to 13 days stale with nothing wrong except the
                # clock.  The real floor is the production cycle it rides
                # inside (~175s), so this bound stops being the binding
                # constraint and the sweep lands near 2 hours.
                # The interval below stopped binding once truth began
                # landing fleet-wide daily: ``new_oos_stations`` is then
                # non-empty on nearly every cycle, so "due" meant "always"
                # and the sweep took 70.8s out of every decision.  It is
                # measurement -- the receipt says so itself -- so it is due
                # when the budget can carry it, or when it has been starved.
                if oos_delegated:
                    oos_admitted = False
                    oos_due = False
                    native_ensemble_oos_ingress = self._delegated_oos_handoff(
                        valid_native_packets=valid_native_packets,
                        now=now,
                        delegate=oos_delegate,
                    )
                else:
                    oos_admitted = self._maintenance_admits("native_ensemble_oos")
                    oos_due = oos_admitted and (
                        bool(new_oos_stations)
                        or last_oos_scan is None
                        or now_mono - float(last_oos_scan)
                        >= NATIVE_ENSEMBLE_OOS_SCAN_MIN_INTERVAL_SEC
                    )
                    if not oos_admitted:
                        native_ensemble_oos_ingress = self._maintenance_deferred(
                            "native_ensemble_oos"
                        )
                _oos_started = time.perf_counter()
                if oos_due and all_oos_stations:
                    if new_oos_stations:
                        # Stalest artifact first, never the alphabet.  Truth
                        # lands for the whole fleet every day, so the changed
                        # list almost always holds many stations and taking
                        # its first element let the alphabet head re-queue
                        # ahead of the tail forever: measured 2026-08-27,
                        # 24 L-Z stations frozen at the 08-25 full pass
                        # (RCSS serving a bias fit that predates its four
                        # worst miss days) while C-L refreshed hourly.  Same
                        # starvation class, same fix shape, as the P1 stage
                        # rotation and the hosted-sweep scheduler.
                        vintage = (
                            _native_ensemble_artifact_vintage_by_station(
                                self.commit_conn,
                            )
                        )
                        oos_station = min(
                            new_oos_stations,
                            key=lambda station: (
                                vintage.get(station, ""),
                                station,
                            ),
                        )
                    else:
                        cursor = int(getattr(
                            self,
                            "_native_ensemble_oos_station_cursor",
                            0,
                        )) % len(all_oos_stations)
                        oos_station = all_oos_stations[cursor]
                        self._native_ensemble_oos_station_cursor = (
                            cursor + 1
                        ) % len(all_oos_stations)
                    self._last_native_ensemble_oos_scan_monotonic = (
                        now_mono
                    )
                    if oos_station in truth_signatures:
                        previous_truth_signatures[oos_station] = (
                            truth_signatures[oos_station]
                        )
                    self._native_ensemble_oos_truth_signature_by_station = (
                        previous_truth_signatures
                    )
                    try:
                        # Forward-accumulation window (user decision): the
                        # 20/8 profile ejected any family with one hole in
                        # its latest eight settled days, which kept ECCC out
                        # on thirty days of history and priced ICON three
                        # weeks away.  Training still uses every settled day;
                        # only the gate's holdout shrinks, and thin evidence
                        # is priced by the weight ramp instead of barred.
                        oos_report = build_native_ensemble_oos(
                            self.commit_conn,
                            station_id=oos_station,
                            as_of_utc=now,
                            min_train_days=(
                                FORWARD_ACCUMULATION_MIN_TRAIN_DAYS
                            ),
                            min_holdout_days=(
                                FORWARD_ACCUMULATION_MIN_HOLDOUT_DAYS
                            ),
                        )
                        oos_persist = persist_native_ensemble_oos(
                            self.commit_conn,
                            oos_report,
                            activated_at_utc=now,
                        )
                    except Exception as exc:
                        native_ensemble_oos_ingress = {
                            "state": "blocked_fail_closed",
                            "reason": f"{type(exc).__name__}:{exc}",
                            "station_id": oos_station,
                            "isolated_from_probability_and_execution":
                                True,
                            "calls_order_gateway": False,
                            "orders_submitted": 0,
                            "live_submit_authorized": False,
                        }
                    else:
                        activation_replay = self._replay_oos_activation_p0(
                            oos_station=oos_station,
                            valid_native_packets=valid_native_packets,
                            now=now,
                            oos_report=oos_report,
                        )
                        native_ensemble_oos_ingress = {
                            "schema": oos_report["schema"],
                            "state": (
                                "OOS_READY"
                                if oos_report["cross_candidates"]
                                else "ACCUMULATING_STRICT_OOS"
                            ),
                            "station_id": oos_station,
                            "registered_system_count": oos_report[
                                "registered_system_count"
                            ],
                            "threshold_profile": oos_report[
                                "threshold_profile"
                            ],
                            "min_train_days": oos_report[
                                "min_train_days"
                            ],
                            "min_holdout_days": oos_report[
                                "min_holdout_days"
                            ],
                            "formal_p0_eligible": oos_report[
                                "formal_p0_eligible"
                            ],
                            "readiness": oos_report["readiness"],
                            "cross_candidate_states": [
                                {
                                    "season_bin": row["season_bin"],
                                    "lead_bucket": row["lead_bucket"],
                                    "run_cycle": row["run_cycle"],
                                    "state": row["state"],
                                    "selected_system_count": row[
                                        "selected_system_count"
                                    ],
                                    "independent_family_count": row[
                                        "independent_family_count"
                                    ],
                                    "oos_metrics": row["oos_metrics"],
                                }
                                for row in oos_report[
                                    "cross_candidates"
                                ]
                            ],
                            "persist": oos_persist,
                            "activation_p0_replay": activation_replay,
                            "report_content_sha256": oos_report[
                                "content_sha256"
                            ],
                            "calls_order_gateway": False,
                            "orders_submitted": 0,
                            "live_submit_authorized": False,
                        }
                elif oos_admitted:
                    native_ensemble_oos_ingress = {
                        "state": "throttled",
                        "reason": "native_ensemble_oos_scan_interval",
                        "calls_order_gateway": False,
                        "orders_submitted": 0,
                        "live_submit_authorized": False,
                    }
                if oos_due:
                    self._record_maintenance_served(
                        "native_ensemble_oos",
                        time.perf_counter() - _oos_started,
                    )
            else:
                native_ensemble_ingress = {
                    "state": "not_available",
                    "reason": (
                        "native_ensemble_forward_inbox_missing"
                    ),
                    "writes_target_database": False,
                    "calls_order_gateway": False,
                    "orders_submitted": 0,
                    "live_submit_authorized": False,
                }
                native_ensemble_oos_ingress = {
                    "state": "not_available",
                    "reason": "native_ensemble_forward_inbox_missing",
                    "calls_order_gateway": False,
                    "orders_submitted": 0,
                    "live_submit_authorized": False,
                }
            self._mark("native_ensemble_oos")
            self._fast_lane_checkpoint_if_due("after_native_ensemble_oos")
            # Before the chain, because the chain is the consumer: P1 resolves
            # each observation's truth-revision hash at compile time, and a
            # report identified after that compile is one this cycle's P1
            # could not carry -- permanently, the envelope table being
            # append-only.
            live_observation_identity = (
                self._identify_live_observations_for_chain()
            )
            self._mark("live_observation_identity")
            resident_probability_chain = self._materialize_resident_probability_chain(
                as_of_utc=now,
            )
            self._probability_chain_ran = True
            resident_p0_ingress = resident_probability_chain["p0"]
            resident_p0m_ingress = resident_probability_chain["p0m"]
            resident_p1_ingress = resident_probability_chain["p1"]
            # Charter 148: this cycle's P1 covered every report committed by
            # its clock; the next head pass runs only for later ones.  A
            # wholly blocked pass covers nothing and is not recorded.
            # When the head P1 ran, it ran before the reconcile and read its
            # own watermark; reports that landed in between were seen by no P1
            # this cycle, so only that earlier read is covered.
            covered_mark = _covered_report_watermark(
                early_p1_ran=bool((self._early_p1_this_cycle or {}).get("ran")),
                early_watermark=getattr(self, "_early_p1_watermark", None),
                cycle_watermark=cycle_report_watermark,
            )
            if (
                covered_mark is not None
                and str(resident_p1_ingress.get("state") or "").upper()
                != "BLOCKED_FAIL_CLOSED"
            ):
                self._p1_covered_watermark = _later_report_watermark(
                    getattr(self, "_p1_covered_watermark", None), covered_mark
                )
            resident_probability_chain["early_p0m"] = dict(
                self._early_p0m_this_cycle or {}
            )
            resident_probability_chain["early_p1"] = {
                key: value
                for key, value in (self._early_p1_this_cycle or {}).items()
                if key != "p1"
            }
            # A correction/revision halt belongs to one station-day.  It must
            # remain fail-closed for that scope, but must not suppress healthy
            # stations from reaching their own WS/decision path.  Only a
            # malformed unscoped P1 blocker is a global chain blocker.
            if (
                str(resident_p1_ingress.get("state") or "").upper()
                == "BLOCKED_FAIL_CLOSED"
            ):
                p1_blockers = resident_p1_ingress.get("blockers")
                if not isinstance(p1_blockers, list) or any(
                    not isinstance(item, Mapping)
                    or not str(item.get("station_id") or "").strip()
                    or not str(item.get("event_date") or "").strip()
                    for item in p1_blockers
                ):
                    raise ContractError(
                        "resident_p1_blocked_before_current_scope_market"
                    )
            # A pending correction review halts that station-day's P1 -- the
            # only writer of the reported-high hard bound -- until the standing
            # auto-clear policy runs, and that runs on a six-hour timer.
            # Measured over 128 corrections since 2026-08-23: median wait 0.8h,
            # but 55 waited over an hour, 14 over three, one 16.  The blocker
            # itself is the cheap, precise signal that work is pending, so let
            # it retire the timer; the next poll runs the same policy
            # subprocess it always would, and the halt lasts a poll instead of
            # a shift.  Only the throttle is cleared -- never the in-flight
            # guard, which is what keeps one subprocess running at a time.
            if correction_review_pending(
                resident_p1_ingress.get("blockers")
            ):
                self._correction_auto_clear_last_mono = None
            regime_ingress = self._materialize_regime_ssot(as_of_utc=now)
            self._mark("regime")
            self._fast_lane_checkpoint_if_due("after_regime")
            if self._maintenance_admits("truth_increment"):
                _truth_started = time.perf_counter()
                truth_materialization = self._materialize_truth_increment(
                    as_of_utc=now,
                )
                self._record_maintenance_served(
                    "truth_increment",
                    time.perf_counter() - _truth_started,
                )
            else:
                truth_materialization = self._maintenance_deferred(
                    "truth_increment"
                )
            self._mark("truth_increment")
            ws_scope_catalog = (
                self._resident_ws_scope_catalog()
                if self.market_manifest_path.is_file()
                else []
            )
            self._mark("ws_scope_catalog")
            # Charter 141: refresh the account before a loop that sizes off
            # it (throttled; a long cycle must not age the read out).
            self._refresh_account_equity()
            registry_snapshot_path = (
                self.nwp_runtime_root / "market_registry_forward.json"
            )
            # The catalog was snapshotted at loop entry, but each scope
            # evaluates at its own now(): a compile costs seconds, so forty-odd
            # scopes in, the snapshot's connection clock is past the
            # strict-as-of age budget and every remaining scope dies
            # manifest_stale.  Measured 2026-08-16: scopes 0-19 committed and
            # LTAC onward -- twenty-two of forty-three -- all raised
            # p0_preselection_manifest_stale, losing those stations' forward
            # book for the day, because a forward quote missed is not
            # refetchable.
            #
            # A re-read every sixty seconds was already here and did not fix
            # it: it rebound only the single scope in hand and discarded the
            # rest of the refreshed catalog, so exactly one late scope per
            # minute survived.  That signature is visible in the same
            # measurement -- RJTT, and only RJTT, committed after the
            # truncation point.
            #
            # Re-read against the budget the compile actually enforces, and
            # keep the answer for every scope behind this one.  A read costs
            # ~360ms against a ~4s compile.
            #
            # Measured 2026-08-16, because it sizes the threshold: the
            # publisher republishes every 60-100s, not every few seconds, so
            # the manifest's own age sawtooths most of the way to the 120s
            # budget on its own.  A re-read therefore often returns the same
            # document -- that is fine and cheap -- and when the publisher is
            # genuinely behind, the scope fails closed on a book that really
            # is too old.  What must not happen again is one stale read
            # condemning every scope behind it.
            try:
                max_ws_snapshot_age_sec = float(
                    load_performance_budget()["limits"][
                        "max_ws_snapshot_age_sec"
                    ]
                )
            except Exception:
                max_ws_snapshot_age_sec = 120.0
            # Half the budget: the age is re-measured at the far end of a
            # compile, so the refresh has to leave room for one to run.
            preselection_manifest_max_age_sec = max(
                15.0, max_ws_snapshot_age_sec / 2.0
            )
            preselection_catalog_by_key = {
                item["scope_key"]: item for item in ws_scope_catalog
            }
            # Rotate the start so a truncated pass does not starve the same
            # tail every cycle.  The order is otherwise the catalog's, and
            # every scope is still visited exactly once per pass -- this moves
            # where the pass begins, not which scopes it covers.
            preselection_order = self._forward_preselection_order(
                [item["scope_key"] for item in ws_scope_catalog],
                resume_at=self._forward_p0_rotation_cursor,
                # The station-days holding live positions lead the pass.
                priority=self._ledger_held_scope_keys(),
            )
            for position, scope_key in enumerate(preselection_order):
                # Advance before the work, not after: whatever ends this pass
                # -- an escaping exception, a lock, a restart -- the next one
                # resumes at the scope this one did not finish.
                self._forward_p0_rotation_cursor = preselection_order[
                    (position + 1) % len(preselection_order)
                ]
                ws_scope = preselection_catalog_by_key.get(scope_key)
                if self._forward_preselection_scope_skipped(ws_scope):
                    continue
                if (
                    self._ws_scope_manifest_age_sec(
                        ws_scope, now=datetime.now(timezone.utc)
                    )
                    > preselection_manifest_max_age_sec
                ):
                    try:
                        with self._span(
                            "forward_p0_catalog_reread", label=scope_key
                        ):
                            preselection_catalog_by_key = {
                                item["scope_key"]: item
                                for item in self._resident_ws_scope_catalog()
                            }
                    except (ContractError, ResourceBoundError):
                        # A torn or rejected read is not this sweep's to fail
                        # on: keep the catalog in hand and let the compile's
                        # own freshness check refuse the scope.  Letting it
                        # escape here would abort the pass and lose every
                        # scope behind it, which is the failure being fixed.
                        pass
                    ws_scope = preselection_catalog_by_key.get(scope_key)
                    if self._forward_preselection_scope_skipped(ws_scope):
                        continue
                try:
                    preselection_evaluation_at = utc_now()
                    # Cleared per scope: a receipt left over from an earlier
                    # scope's refusal must not be read as this one's book.
                    self._forward_market_evidence_last = None
                    with self._span(
                        "forward_p0_scope", label=scope_key
                    ), self._temporary_scope_manifest(
                        ws_scope["manifest"]
                    ) as scope_manifest_path:
                        forward_p0_preselections.append(
                            self.materialize_forward_p0_preselections(
                                registry_snapshot_path=(
                                    registry_snapshot_path
                                ),
                                ws_manifest_path=scope_manifest_path,
                                event_date=str(ws_scope["event_date"]),
                                evaluation_at_utc=(
                                    preselection_evaluation_at
                                ),
                                station_id=str(
                                    ws_scope["station_id"]
                                ),
                            )
                        )
                except Exception as exc:
                    forward_p0_preselections.append({
                        **_blocked(
                            f"{type(exc).__name__}:{exc}",
                            station_id=str(ws_scope["station_id"]),
                            event_date=str(ws_scope["event_date"]),
                        ),
                        # A bare exception name is undiagnosable from the
                        # status file, and this receipt is the only trace a
                        # failed forward scope leaves.  Keep the innermost
                        # frames so the site is readable without reproducing
                        # the exact drain race that triggered it.
                        "blocked_traceback_tail": [
                            line.strip()
                            for line in traceback.format_exception(exc)[-4:]
                        ],
                        # A blocked plan no longer implies a lost book.  This
                        # says which of the two happened, without opening the
                        # ledger.
                        "market_evidence": (
                            self._forward_market_evidence_last
                        ),
                        "preliminary_decision_count": 0,
                        "intents_written": 0,
                        "reservations_written": 0,
                    })
            self._mark("forward_p0_loop")
            self._fast_lane_checkpoint_if_due("after_forward_p0_loop")
            self._refresh_account_equity()
            # Charter 48: a listed day's scope belongs in the merged manifest
            # the ingress reads.  The publisher already subscribes it and
            # rewrites its book alongside the open ones -- both days' scope
            # manifests sit in the catalog, each with a full set of quoted
            # tokens -- but this filter admitted only "open", so the listed
            # scope's book never reached the evidence lane and every listing
            # scope resolved to no quotes at all.  Freshness and the scope's
            # own blocker still apply to both, unchanged.
            listing_scope_keys = {
                f"{station}|{day}"
                # utc_now(), not `now`: that name is bound further down, after
                # market ingress.  Reading it here is the UnboundLocalError
                # that killed the forward preselection lane for a day.
                for station, day in self._listing_entry_scopes(
                    as_of_utc=utc_now()
                )
            }
            # Charter 126: what this cycle may DECIDE on, and what it must
            # RECORD, are two questions, and this filter answered only the
            # first.
            #
            # Every blocker the catalog attaches is documented, in the
            # catalog itself, as a reason not to act -- "observational, not
            # fatal", "keep recording its book, block decisions on it
            # alone", "excluded from the actionable scope set while allowing
            # other fresh scopes to proceed".  None of them is a reason not
            # to write down what the market said.  But the sweep below drew
            # its scopes from this one list, so a scope the decision rule
            # dropped lost its book too -- and a quote is ephemeral: a
            # forward one missed cannot be refetched.  That is the same
            # lesson ``_record_refused_compile_market_evidence`` learned for
            # the forward compile, and the 2026-09-06 ruling learned for the
            # publisher (a not-started day keeps its book while its P0 is
            # stale); the publisher was changed and this half was not.
            #
            # Measured 2026-09-09 11:52Z, the first reading of the serving
            # state table: 41 of 45 stations' D+1 scope was unserved on
            # ``future_probability_stale`` -- the standing condition, not a
            # restart artifact -- and ZUUU|2026-09-09 recorded no book at
            # all for 21.6 hours across the first 13.2 hours of its own
            # event day, over which 27C went from 0.30 to 0.998 with nothing
            # written down.  ``production_quote_expired`` is the top blocked
            # reason in the store (348 since 09-01) and is what a scope
            # decides on when its book was never taken.
            #
            # The cost is rows, so the widening is not at the decision
            # cadence: an evidence-only scope is captured on a floor
            # interval, which keeps a repricing visible without writing a
            # 17KB book every cycle for a scope nobody may act on.
            day_window_scopes = [
                item
                for item in ws_scope_catalog
                if (
                    item["event_day_state"] == "open"
                    or str(item.get("scope_key") or "") in listing_scope_keys
                )
            ]
            open_ws_scopes = [
                item
                for item in day_window_scopes
                if (
                    item["probability_evidence_fresh"] is True
                    and not item.get("scope_blocker")
                )
            ]
            evidence_only_ws_scopes = self._evidence_only_capture_scopes(
                day_window_scopes,
                decidable=open_ws_scopes,
            )
            # The verdict above is the one field that decides whether a
            # scope's book is recorded at all, and until now it lived only
            # in a status file the next cycle overwrote.  Persist it before
            # anything can return, so an outage is measurable while it is
            # happening rather than reconstructed afterwards -- which, for
            # ZUUU 2026-09-09, it could not be.
            ws_scope_serving = self._record_ws_scope_serving_state(
                ws_scope_catalog, as_of_utc=now
            )
            self._mark("ws_scope_serving_state")
            if ws_scope_catalog and not open_ws_scopes:
                if not forward_p0_preselections:
                    raise ContractError(
                        "resident_target_ws_actionable_scope_missing"
                    )
                preliminary_ok = all(
                    item.get("state") == "COMMITTED"
                    for item in forward_p0_preselections
                )
                return {
                    "schema": SCHEMA,
                    "ok": preliminary_ok,
                    "state": (
                        "preliminary_no_live"
                        if preliminary_ok
                        else "blocked_fail_closed"
                    ),
                    "execution_mode": PRODUCTION_EXECUTION_MODE,
                    "candidate_count": 0,
                    "candidates": [],
                    "forward_p0_preselections": (
                        forward_p0_preselections
                    ),
                    "ws_scope_catalog": self._ws_scope_catalog_summary(
                        ws_scope_catalog
                    ),
                    "ws_scope_serving": ws_scope_serving,
                    "places_orders": False,
                    "calls_order_gateway": False,
                    "live_submit_authorized": False,
                    "orders_submitted": 0,
                    "resident_registry_ingress": (
                        resident_registry_ingress
                    ),
                    "native_ensemble_ingress": (
                        native_ensemble_ingress
                    ),
                    "native_ensemble_oos_ingress": (
                        native_ensemble_oos_ingress
                    ),
                    "resident_probability_chain": (
                        resident_probability_chain
                    ),
                    "regime_ingress": regime_ingress,
                    "worker_checked_at": now,
                }
            # Probability is the sole weather authority.  Commit every
            # newly available official-observation P1 before binding the
            # market snapshot so downstream selection can prove that its
            # quote is at or after the current checkpoint.  Reversing these
            # calls creates a stale P0-era market snapshot immediately
            # before a P1 update and breaks the canonical
            # P1 -> official WS -> basket ordering.
            selected_open_scope = self._select_resident_open_ws_scope(
                open_ws_scopes,
                as_of_utc=now,
            )
            # Bound before the branch, not inside one of them.  The compile
            # loop below reads it on every path, and a name bound only in the
            # else arm is an UnboundLocalError waiting for the day the other
            # arm is taken -- twice today already.
            evidence_materialized_at: dict[str, float] = {}
            # Bound before the branch: the scope assembly below reads it on
            # every path, and the other arm never sets it.
            serve_listing = False
            # Likewise: read by the listing-row assembly on every path, and
            # bound only in the else arm until now.
            listing_stations: set[str] = set()
            lead_listing_scopes: set[tuple[str, str]] = set()
            if not ws_scope_catalog or not selected_open_scope or not str(
                selected_open_scope["probability_stage"]
            ):
                market_ingress = self._materialize_market_evidence(
                    activation
                )
            else:
                # Every open scope of this event day, not one of them.
                # Serving a single scope per cycle meant a full pass over 33
                # stations took five to eight minutes, while the quote lease
                # it depends on is sixty seconds -- so a station's book had
                # expired several times over before its turn came round
                # again, which is where the recurring
                # ``production_quote_expired`` came from.  P1 is the dynamic
                # stage; at one station per cycle it was not dynamic, it was
                # occasional.
                #
                # Nothing new is fetched to do this: the publisher already
                # holds every scope's book in the manifest it rewrites every
                # two seconds, and the ingress below has always taken a
                # station list.  The single-scope bridge was the only thing
                # making it one at a time.
                sweep_scopes = self._sweep_scope_manifests(
                    # Charter 126: the evidence-only scopes join the same
                    # sweep, so they inherit its rotation order, its
                    # one-event-day rule and its cap.  The selected scope
                    # still leads; the count admitted here is bounded above
                    # so the cap cannot be reached by them.
                    [*open_ws_scopes, *evidence_only_ws_scopes],
                    selected=selected_open_scope,
                    as_of_utc=now,
                )
                self._mark_evidence_only_captured(
                    evidence_only_ws_scopes,
                    swept=sweep_scopes,
                    as_of_utc=now,
                )
                cycle_evidence = self._materialize_cycle_market_evidence(
                    activation,
                    sweep_scopes=sweep_scopes,
                    selected_scope=selected_open_scope,
                )
                market_ingress = cycle_evidence["market_ingress"]
                evidence_materialized_at.update(
                    cycle_evidence["materialized_at"]
                )
                serve_listing = cycle_evidence["serve_listing"]
                listing_stations = cycle_evidence["listing_stations"]
                lead_listing_scopes = cycle_evidence["lead_listing_scopes"]
                if cycle_evidence["error"] is not None:
                    # Raised only now, after the listed days have had their
                    # pass: every group this cycle depended on refused, and
                    # the exception names the groups whose blocker it is.
                    raise cycle_evidence["error"]
            station_allowlist = {
                str(value or "").strip().upper()
                for value in market_ingress.get("station_allowlist", [])
                if str(value or "").strip()
            }
            manifest_event_date = str(
                market_ingress.get("event_date") or ""
            ).strip()
            if not station_allowlist or not manifest_event_date:
                raise ContractError(
                    "target_market_station_allowlist_scope_required"
                )
            # The market bundle is materialized after the cycle's initial
            # probability clock.  Compile against a clock captured after that
            # atomic write; otherwise the new quote can be invisible while
            # its inventory/order versions are already visible, producing a
            # false cross-generation drift.
            now = utc_now()
            self._mark("market_ingress")
            self._fast_lane_checkpoint_if_due("after_market_ingress")
            post_fill_recompute = self._consume_post_fill_recompute_requests(
                activation=activation,
                scope_config=scope,
                as_of_utc=now,
            )
            if post_fill_recompute.get("state") == "BLOCKED_FAIL_CLOSED":
                raise ContractError("post_fill_recompute_blocked")
            self._mark("post_fill_recompute")
            recomputed_scopes = {
                (
                    str(item.get("station_id") or ""),
                    str(item.get("event_date") or ""),
                )
                for item in post_fill_recompute.get("results", [])
                if isinstance(item, Mapping)
            }
            # Every committed scope ever written was listed here and then
            # thrown away by the event-date test below -- 478 scopes read to
            # keep the handful belonging to this cycle's day.  The day is
            # already known and non-empty (guarded above), so ask for it:
            # the sweep drops from 59,120 index entries to one day's worth,
            # and with the committed-scope index it stops touching the table
            # at all.  The Python filters are unchanged and still authoritative.
            all_rows = self.conn.execute(
                "SELECT DISTINCT station_id,event_date,settlement_timezone FROM basket_probability_envelope "
                "WHERE state='COMMITTED' AND event_date=? ORDER BY station_id,event_date",
                (manifest_event_date,),
            ).fetchall()
            rows = [
                (station_id, event_date)
                for station_id, event_date, settlement_timezone in all_rows
                if str(station_id).upper() in station_allowlist
                and str(event_date) == manifest_event_date
                and self._event_day_open(
                    str(event_date),
                    settlement_timezone=str(settlement_timezone or ""),
                    as_of_utc=now,
                )
            ]
            # Charter 48, restored.  The query above asks for one day and the
            # predicate requires it to be open, so a listed-but-not-started
            # day -- the thing clause 48 says is tradable the moment it is
            # listed -- could never enter this list.  Its scopes are appended
            # here under the admission rule _decision_scopes already carries
            # for them (committed P0/P0-M authority, no P1), and they then
            # meet every downstream gate the current day meets, unchanged.
            # The listing rows' station set is the main pass's allowlist
            # joined with every station a listing pass materialized this
            # cycle: the allowlist alone names only the current date's open
            # stations, which is exactly the set a not-started scope is
            # never in.
            listing_rows = [
                (station_id, event_date)
                for station_id, event_date in self._listing_entry_scopes(
                    as_of_utc=now,
                    station_allowlist=(
                        set(station_allowlist) | set(listing_stations)
                    ),
                )
                if (station_id, event_date) not in set(rows)
            ]
            # Only on the listed days' turn.  Their evidence was not
            # materialized this cycle otherwise, and compiling a scope
            # against last cycle's books is how production_quote_expired is
            # manufactured rather than observed.
            rows = list(rows) + _compiled_listing_rows(
                listing_rows,
                serve_listing=serve_listing,
                lead_listing_scopes=lead_listing_scopes,
            )
            self._mark("committed_scope_sweep")
            # Decisions price the freshest update there is.
            self._copy_follow_if_due("before_decisions")
            self._fast_lane_checkpoint("before_decisions")
            # ...and every envelope committed since the regime pass gets its
            # companion before anything prices it.
            self._regime_catch_up(label="before_decisions")
            if not rows:
                # Preliminary future scopes have their own zero-execution
                # decision chain above.  A current-scope blocker must never
                # be copied into a not-started day or wait for that day to
                # open/settle.
                scopes = self._decision_scopes(
                    as_of_utc=now,
                    include_not_started=False,
                )
                reason_codes = self._blocker_reason_codes(
                    "materialized_probability_envelope_missing",
                    market_ingress.get("reason") if isinstance(market_ingress, Mapping) else None,
                )
                details = {
                    "blocked_scope_decision_version": 1,
                    "probability_envelope_count": 0,
                    "market_ingress_state": str((market_ingress or {}).get("state") or "unknown"),
                    "market_ingress_reason_code": self._blocker_reason_codes(
                        (market_ingress or {}).get("reason") if isinstance(market_ingress, Mapping) else None
                    )[0],
                    "no_market_snapshot_written": True,
                    "no_intents_written": True,
                    "no_capital_reserved": True,
                    "no_orders_submitted": True,
                    "execution_mode": PRODUCTION_EXECUTION_MODE,
                }
                receipts = self._commit_blocked_scopes(
                    scopes=scopes,
                    reason_codes=reason_codes,
                    details=details,
                    created_at_utc=now,
                )
                return {
                    **_blocked("materialized_probability_envelope_missing"),
                    "worker_checked_at": now,
                    "candidate_count": 0,
                    "scope_count": len(scopes),
                    "durable_blocked_decision_count": sum(
                        1 for item in receipts if item.get("writes_target_ledger") is True
                    ),
                    "durable_blocked_decisions": self._blocked_receipt_summary(receipts),
                    "market_ingress": market_ingress,
                    "resident_p0_ingress": resident_p0_ingress,
                    "resident_p0m_ingress": resident_p0m_ingress,
                    "resident_p1_ingress": resident_p1_ingress,
                    "regime_ingress": regime_ingress,
                    "delta_v2_truth_ingress": delta_v2_truth_ingress,
                    "delta_v2_label_ingress": delta_v2_label_ingress,
                    "post_fill_recompute": post_fill_recompute,
                }
            results: list[dict[str, Any]] = [
                dict(item["candidate"])
                for item in post_fill_recompute.get("results", [])
                if isinstance(item, Mapping)
                and isinstance(item.get("candidate"), Mapping)
            ]
            # One evidence read, then a compile loop several times longer
            # than the lease it depends on.  Measured 2026-08-31: the books
            # were stamped 09:48:25, the cycle ran to 09:51:03, and the quote
            # lease is sixty seconds -- so every scope compiled after
            # 09:49:25 died on production_quote_expired no matter how healthy
            # it was.  Eighty-two scopes over a 158-second window against a
            # 60-second lease can only ever commit the first third.
            #
            # An earlier fix moved this from one scope per cycle to all of
            # them in one ingest, which removed the worst of it; what was
            # left is this, and the answer is the same as it was then.  Read
            # the books again -- the publisher rewrites the manifest every
            # couple of seconds and it costs one bounded file read -- rather
            # than lengthening the lease, which would mint a freshness the
            # evidence never had and is the one move the freshness contract
            # exists to forbid.
            #
            # Refreshed per day, not per scope: one re-materialization serves
            # every scope of that day still to come, so a 158-second loop
            # costs three reads instead of eighty-two.
            # Seeded from when each day's evidence was actually written, not
            # from when this loop began.  Those are not the same instant: the
            # current day is materialized first and a listed day after it,
            # measured 45 seconds apart, so seeding both at loop start told
            # the listed day it had a full lease when most of it was already
            # spent.  Its scopes also compile last, which is where the
            # remaining production_quote_expired came from.
            loop_started = time.monotonic()
            evidence_refreshed_at: dict[str, float] = {
                day_key: evidence_materialized_at.get(day_key, loop_started)
                for day_key in {str(item[1]) for item in rows}
            }
            quote_refresh_failures: list[dict[str, str]] = []
            quote_refresh_attempts: list[str] = []
            quote_refresh_receipts: list[dict[str, Any]] = []
            # One read per scope, kept until that scope's day is refreshed.
            #
            # Per station-day, not per day.  The lease this triggers on has
            # to be the lease the compile below fails on, and that one is the
            # station's: ``load_production_market_snapshot`` reads the newest
            # snapshot for *this* station-day and refuses it if the
            # evaluation instant is past its expiry.  Keyed by day alone the
            # trigger read a fleet maximum, so one station holding a fresh
            # book told every other station of that day it had one -- and a
            # station whose own book was hours old never asked for a refresh
            # at all.  Measured 2026-09-01: 21 scopes on production_quote_
            # expired against a single refresh attempt for the whole cycle.
            scope_quote_expiry: dict[tuple[str, str], datetime | None] = {}
            refresh_ineffective_days: set[str] = set()
            day_refresh_counts: dict[str, int] = {}
            # Attempts that did not renew the lease -- the ones the cap
            # exists for.  Kept apart from the attempt count above, which
            # stays whole so the receipt still reports what was tried.
            day_unproductive_refreshes: dict[str, int] = {}
            # Where the next refresh's reach is measured from: this loop's own
            # cost per position once it has a few, the last loop's before.
            seconds_per_position_seed = getattr(
                self, "_decision_loop_seconds_per_position", None
            )
            refresh_ineffective_scopes: set[tuple[str, str]] = set()
            restated_station_count = 0
            # Days whose last refresh renewed nothing: the next one waits for
            # the publisher's next generation first
            # (``QUOTE_PUBLISHER_WAIT_BUDGET_SECONDS``).
            days_awaiting_publisher: set[str] = set()
            publisher_wait_budget = QUOTE_PUBLISHER_WAIT_BUDGET_SECONDS
            publisher_waits: list[dict[str, Any]] = []
            try:
                quote_lease_seconds: float | None = float(
                    QuoteFreshnessPolicy.from_mapping(
                        activation.get("quote_freshness_policy")
                    ).max_quote_age_seconds
                )
            except Exception:  # noqa: BLE001 -- no lease, no wait
                quote_lease_seconds = None
            for position, (station_id, event_date) in enumerate(rows):
                if self.stop_requested:
                    # SIGTERM: stop at the scope boundary.  The scopes not
                    # reached keep last cycle's decisions; the next cycle
                    # serves them first because nothing was written.
                    break
                station = str(station_id)
                day = str(event_date)
                if (station, day) in recomputed_scopes:
                    continue
                if (station, day) not in scope_quote_expiry:
                    _probe_started = time.perf_counter()
                    scope_quote_expiry[(station, day)] = (
                        self._scope_day_quote_expiry(day, station)
                    )
                    self._add_span(
                        "decision_loop_lease_probe",
                        (time.perf_counter() - _probe_started) * 1000.0,
                        label=f"{station}|{day}",
                    )
                expiry = scope_quote_expiry[(station, day)]
                lease_left = (
                    (expiry - datetime.now(timezone.utc)).total_seconds()
                    if expiry is not None
                    else 0.0
                )
                if quote_refresh_admitted_v1(
                    lease_left_seconds=lease_left,
                    day_is_ineffective=(
                        day in refresh_ineffective_days
                        or (station, day) in refresh_ineffective_scopes
                    ),
                    unproductive_attempts=day_unproductive_refreshes.get(
                        day, 0
                    ),
                ):
                    if (
                        QUOTE_REFRESH_AWAIT_PUBLISHER
                        and day in days_awaiting_publisher
                        and quote_lease_seconds is not None
                        and publisher_wait_budget > 0.0
                    ):
                        waited, arrived = self._await_publisher_books(
                            station_id=station,
                            event_date=day,
                            lease_seconds=quote_lease_seconds,
                            budget_seconds=publisher_wait_budget,
                        )
                        publisher_wait_budget -= waited
                        publisher_waits.append({
                            "scope": f"{station}|{day}",
                            "waited_seconds": round(waited, 1),
                            "books_arrived": arrived,
                        })
                        self._add_span(
                            "decision_loop_publisher_wait",
                            waited * 1000.0,
                            label=f"{station}|{day}",
                        )
                    evidence_refreshed_at[day] = time.monotonic()
                    quote_refresh_attempts.append(day)
                    day_refresh_counts[day] = (
                        day_refresh_counts.get(day, 0) + 1
                    )
                    # The stations of this day the loop will reach while the
                    # renewed lease holds (``quote_refresh_reach_v1``): this
                    # one, and the day's scopes in the positions after it,
                    # not yet compiled and not known to have nothing to
                    # restate.  None restates the whole day, as before.
                    refresh_stations: list[str] | None = None
                    if QUOTE_REFRESH_WITHIN_REACH:
                        reach = quote_refresh_reach_v1(
                            seconds_per_position=(
                                (time.monotonic() - loop_started) / position
                                if position >= 3
                                else seconds_per_position_seed
                            ),
                        )
                        refresh_stations = quote_refresh_stations_v1(
                            rows,
                            position=position,
                            reach=reach,
                            skip=set(recomputed_scopes) | refresh_ineffective_scopes,
                        )
                    # The books it restates are the ones whose cached expiry
                    # is now stale -- and the ones whose renewal says whether
                    # it worked.
                    day_expiry_before = (
                        self._scope_day_quote_expiry(day)
                        if refresh_stations is None
                        else max(
                            (
                                expiry
                                for expiry in (
                                    self._scope_day_quote_expiry(day, item)
                                    for item in refresh_stations
                                )
                                if expiry is not None
                            ),
                            default=None,
                        )
                    )
                    for cached_key in [
                        key for key in scope_quote_expiry
                        if key[1] == day
                        and (refresh_stations is None or key[0] in refresh_stations)
                    ]:
                        scope_quote_expiry.pop(cached_key, None)
                    try:
                        # Kept, not discarded.  "Ineffective" is a verdict
                        # about a pass whose own receipt says why it wrote
                        # nothing -- no_scope_manifest, blocked_fail_closed
                        # with a reason, or committed_with_skipped_scopes --
                        # and throwing it away left the cycle reporting an
                        # ineffective day with no way to tell those apart.
                        _refresh_started = time.perf_counter()
                        refresh_receipt = self._refresh_scope_day_evidence(
                            activation,
                            event_date=day,
                            as_of_utc=utc_now(),
                            stations=refresh_stations,
                        )  # writes the snapshot the compile reads
                        self._add_span(
                            "decision_loop_quote_refresh",
                            (time.perf_counter() - _refresh_started) * 1000.0,
                            label=day,
                        )
                        restated_count = (
                            len(refresh_stations)
                            if refresh_stations is not None
                            else len(
                                (refresh_receipt or {}).get("station_allowlist")
                                or ()
                            )
                        )
                        restated_station_count += restated_count
                        quote_refresh_receipts.append({
                            "event_date": day,
                            # The reach: how many stations this pass restated.
                            "station_count": restated_count,
                            "state": str(
                                (refresh_receipt or {}).get("state") or ""
                            ),
                            "reason": str(
                                (refresh_receipt or {}).get("reason") or ""
                            )[:200],
                            "skipped_scope_count": (
                                (refresh_receipt or {}).get(
                                    "snapshot_skipped_scope_count"
                                )
                                if (refresh_receipt or {}).get(
                                    "snapshot_skipped_scope_count"
                                ) is not None
                                else (refresh_receipt or {}).get(
                                    "skipped_scope_count"
                                )
                            ),
                        })
                        refresh_wrote = str(
                            (refresh_receipt or {}).get("state") or ""
                        ) == "committed"
                        now = utc_now()
                        # Did it actually renew anything?  A refresh that
                        # cannot -- the day has no fresh scope manifest to
                        # merge, so the pass returns without writing -- leaves
                        # the expiry exactly where it was, and every remaining
                        # scope of that day then asks for the same refresh
                        # again.  Measured: 44 refreshes for one event day in
                        # one cycle, none of them renewing anything, and the
                        # cycle went from eight minutes to fourteen.
                        #
                        # Asked of the day, not of the station in hand.  "Did
                        # this pass write anything" is a question about the
                        # pass; a station the manifest no longer carries can
                        # fail to renew while the pass restated thirty
                        # others, and reading that as a dead day disabled the
                        # refresh for every one of them.  The station's own
                        # expiry is what decides whether *it* still needs a
                        # refresh, and it is re-read above.
                        #
                        # And only when the pass did not write.  A refresh
                        # that commits and still leaves the expiry where it
                        # was has not failed -- it has restated the newest
                        # book the publisher has, which republishes every
                        # 60-100 seconds and so is often the same generation
                        # twice running.  Reading that as a dead day disabled
                        # the day's refresh over an unremarkable republish
                        # gap: measured 2026-09-01 04:55, three passes, all
                        # three committed with no scope skipped, the third
                        # landing between generations -- and ten scopes
                        # behind it died on production_quote_expired.  The
                        # attempt cap is what bounds a genuinely dead day
                        # now; this flag is for a pass that wrote nothing.
                        # Asked of what the pass restated: the day when it
                        # restated the day, its reach when it restated that.
                        renewed_day = (
                            self._scope_day_quote_expiry(day)
                            if refresh_stations is None
                            else max(
                                (
                                    expiry
                                    for expiry in (
                                        self._scope_day_quote_expiry(day, item)
                                        for item in refresh_stations
                                    )
                                    if expiry is not None
                                ),
                                default=None,
                            )
                        )
                        renewed = (
                            day_expiry_before is not None
                            and renewed_day is not None
                            and renewed_day > day_expiry_before
                        )
                        if not renewed:
                            day_unproductive_refreshes[day] = (
                                day_unproductive_refreshes.get(day, 0) + 1
                            )
                            days_awaiting_publisher.add(day)
                        else:
                            days_awaiting_publisher.discard(day)
                        if (
                            not refresh_wrote
                            and day_expiry_before is not None
                            and (
                                renewed_day is None
                                or renewed_day <= day_expiry_before
                            )
                        ):
                            # A day with nothing to restate latches the day,
                            # as before; a reach with nothing latches only
                            # its own stations, so one station the catalog no
                            # longer carries cannot disable the others.
                            day_manifests = (refresh_receipt or {}).get(
                                "day_scope_manifest_count"
                            )
                            if refresh_stations is None or day_manifests == 0:
                                refresh_ineffective_days.add(day)
                            else:
                                refresh_ineffective_scopes.update(
                                    (item, day) for item in refresh_stations
                                )
                        scope_quote_expiry[(station, day)] = (
                            self._scope_day_quote_expiry(day, station)
                        )
                    except Exception as exc:  # noqa: BLE001 -- observational
                        # A failed refresh leaves the previous books in
                        # place; the scope then fails on its own expiry with
                        # its own reason, which is the honest outcome.
                        #
                        # It also renewed nothing, and the ineffective latch
                        # does not catch it -- the latch asks whether a pass
                        # WROTE, and this pass threw.  So it counts against
                        # the cap: an erroring refresh is precisely the case
                        # a bounded number of attempts is still for.
                        day_unproductive_refreshes[day] = (
                            day_unproductive_refreshes.get(day, 0) + 1
                        )
                        days_awaiting_publisher.add(day)
                        quote_refresh_failures.append(
                            {"event_date": day, "reason": f"{type(exc).__name__}:{exc}"[:160]}
                        )
                # Cleared before the compile so the except arm can tell a
                # compile-side throw (candidate still None) from a
                # commit-side one (candidate exists and carries the plan's
                # own status and reason codes -- the upstream story the
                # receipt used to drop on the floor).
                candidate = None
                # What the replay check reads is what the compile below would
                # read: the same station-day at the same instant, with no
                # write between them.  Read once (125 station-day reads a
                # cycle, 2026-10-04).
                scope_validated: list[ProbabilityEnvelope] = []
                try:
                    replay_blocker = self._replay_root_mismatch_reason(
                        station_id=station,
                        event_date=day,
                        as_of_utc=now,
                        validated_out=scope_validated,
                    )
                    if replay_blocker is not None:
                        if replay_blocker == "resident_p0m_replay_required":
                            # Next cycle's P0-M lane spends its replay budget
                            # here first.  Measured 2026-09-09 04:24Z: the
                            # budget of four was spent on the furthest event
                            # day -- correct by the stage-governs-its-day
                            # rule, and none of those scopes was blocked --
                            # while nineteen waited and KLGA and KMIA, whose
                            # decisions this refusal was actually stopping,
                            # were among them.
                            self._p0m_replay_blocked_next.add((station, day))
                        raise ContractError(replay_blocker)
                    _compile_started = time.perf_counter()
                    candidate = compile_production_cycle_from_ssot(
                        self.conn,
                        station_id=station,
                        event_date=day,
                        evaluation_at_utc=now,
                        season_bin=str(scope["season_bin"]),
                        maturity_bin=str(scope["maturity_bin"]),
                        liquidity_bin=str(scope["liquidity_bin"]),
                        strategy_version=str(scope["strategy_version"]),
                        policy_authority_scope=str(activation["policy_authority_scope"]),
                        base_policy=scope.get("base_policy") if isinstance(scope.get("base_policy"), Mapping) else None,
                        # Charter 125: the day's own thermometer, read here
                        # because this process is the one holding the
                        # canonical observation connection.  None before the
                        # day reports anything, which is every pre-day P0.
                        observed_running_high_c=self._observed_running_high_c(
                            station_id=station,
                            event_date=day,
                            as_of_utc=now,
                        ),
                        preloaded_validated=scope_validated or None,
                    )
                    self._add_span(
                        "decision_loop_compile",
                        (time.perf_counter() - _compile_started) * 1000.0,
                        label=f"{station}|{day}",
                    )
                    # A complete current-stage + WS compile is a valid
                    # no-live decision point. Every stage commits only the
                    # content-addressed NO_EXECUTION authority; dry-run must
                    # not materialize P1 observation/bound/training facts.
                    _commit_started = time.perf_counter()
                    _atomic_commit = (
                        self._commit_current_stage_no_execution_candidate(
                            candidate,
                            station_id=station,
                            event_date=day,
                            created_at_utc=now,
                        )
                    )
                    self._add_span(
                        "decision_loop_commit",
                        (time.perf_counter() - _commit_started) * 1000.0,
                        label=f"{station}|{day}",
                    )
                    candidate = {
                        **candidate,
                        "atomic_commit": _atomic_commit,
                    }
                    # The chain's stake factor is the opener's, forever:
                    # the first authorized P0 plan writes one row and every
                    # later stage compiles against it (INSERT OR IGNORE, so
                    # a re-authorized P0 cycle does not re-decide).
                    record_chain_opener_tilt(
                        self.commit_conn,
                        station_id=station,
                        event_date=day,
                        plan=candidate,
                        decided_at_utc=now,
                    )
                    # Charter 257 补记三: the decision loop is the cycle's
                    # longest stage; the copy-follow lane looks between scopes.
                    self._copy_follow_if_due("in_decision_loop")
                    results.append(candidate)
                except Exception as exc:
                    reason = f"{type(exc).__name__}:{exc}"
                    _blocked_funnel = _window_funnel_from(
                        exc, candidate=candidate
                    )
                    _blocked_started = time.perf_counter()
                    blocked_commit = self._commit_blocked_scope(
                        station_id=station,
                        event_date=day,
                        reason_codes=self._blocker_reason_codes(reason),
                        details={
                            "blocked_scope_decision_version": 1,
                            "exception_type": type(exc).__name__,
                            "exception_reason": str(exc),
                            # Which gate emptied the window list, when
                            # the compile died there (2026-09-05): the
                            # funnel the solver attached to its error,
                            # and the per-window solve failures when the
                            # list was not empty but nothing on it solved.
                            "window_gate_counts": _blocked_funnel[0],
                            "window_failures": _blocked_funnel[1],
                            "no_market_snapshot_written": True,
                            "no_intents_written": True,
                            "no_capital_reserved": True,
                            "no_orders_submitted": True,
                            "execution_mode": PRODUCTION_EXECUTION_MODE,
                        },
                        created_at_utc=now,
                    )
                    self._add_span(
                        "decision_loop_blocked_commit",
                        (time.perf_counter() - _blocked_started) * 1000.0,
                        label=f"{station}|{day}",
                    )
                    wrapper = {
                        **_blocked(reason, station_id=station, event_date=day),
                        "atomic_commit": blocked_commit,
                    }
                    if isinstance(candidate, Mapping):
                        # The commit refused a candidate the compile had
                        # already produced.  What that plan claimed about
                        # itself -- blocked/hold/ready, and why -- is the
                        # diagnosis; without it, seven stations spent three
                        # cycles today naming a different shape error each
                        # round while the real upstream reasons stayed
                        # unreadable.
                        wrapper["compiled_plan_status"] = str(
                            candidate.get("status") or ""
                        )
                        wrapper["compiled_plan_reason_codes"] = [
                            str(code)
                            for code in (candidate.get("reason_codes") or ())
                        ][:8]
                        wrapper["failed_in"] = "commit"
                    else:
                        wrapper["failed_in"] = "compile"
                    results.append(wrapper)
            if rows:
                self._decision_loop_seconds_per_position = (
                    (time.monotonic() - loop_started) / len(rows)
                )
            # The loop above ran unnamed until 2026-09-07.  Every stall since
            # the timeline was introduced was diagnosed from a profile that
            # covered 41% of the cycle: measured that morning, 1768s of named
            # stages inside a 4285s cycle, with the other 2517s -- 90 scopes,
            # 86 of them dying on ``production_quote_expired`` -- attributed
            # to nothing at all.  That blind spot is why the same overrun has
            # been "fixed" repeatedly from whichever statement the point-in-
            # time probe happened to catch.
            self._mark("decision_loop")
            # Closed-day truth and labels are maintenance work, not inputs to
            # the current action.  Running their scans before market ingress
            # consumed the strict quote lease and could turn a fresh official
            # WS generation stale before DeltaBasketScore compiled.  Keep the
            # settlement lane independent and non-blocking after every current
            # scope has completed its current-stage -> JIT WS -> decision path.
            if self._maintenance_admits("delta_v2_settlement"):
                _settlement_started = time.perf_counter()
                (
                    delta_v2_truth_ingress,
                    delta_v2_label_ingress,
                ) = self._run_delta_v2_settlement_maintenance(
                    as_of_utc=utc_now(),
                )
                self._record_maintenance_served(
                    "delta_v2_settlement",
                    time.perf_counter() - _settlement_started,
                )
            else:
                delta_v2_truth_ingress = self._maintenance_deferred(
                    "delta_v2_settlement"
                )
                delta_v2_label_ingress = self._maintenance_deferred(
                    "delta_v2_settlement"
                )
            try:
                cash_phase_forward_observations = (
                    self._flush_cash_phase_forward_observations()
                )
            except Exception as exc:
                cash_phase_forward_observations = {
                    "state": "blocked_fail_closed",
                    "reason": f"{type(exc).__name__}:{exc}",
                    "observation_count": 0,
                    "written": False,
                    "orders_submitted": 0,
                    "calls_order_gateway": False,
                    "live_submit_authorized": False,
                }
            # One blocked scope out of thirty-eight used to turn this whole
            # receipt blocked_fail_closed -- all-or-nothing, over a fleet
            # where some scopes are always in a soft per-station refusal
            # (support_empty is HOLD semantics, not a fault).  The light was
            # red on the first cycle that ever carried nine fully committed
            # live-authority decisions, and the operator read an outage.
            #
            # The verdict now counts what the ledger says: a scope whose
            # atomic commit landed (or was idempotently retained) is
            # committed; a scope that refused is blocked and its reason is
            # tallied.  The whole cycle is blocked_fail_closed only when it
            # produced nothing at all -- no results, or results and not one
            # of them committed -- which is also exactly the shape of the
            # worker-level failures the except arm below already reports.
            self._mark("settlement_lane")
            committed_scopes, blocked_scope_reasons = _scope_verdict_tally(
                results
            )
            blocked_scopes = sum(blocked_scope_reasons.values())
            scope_defects = _scope_defect_tally(results)
            # A cycle that committed nothing says why on its own receipt.
            # The board's fail-closed branch reads ``reason`` and nothing
            # else, and a listing turn that served only tomorrow's stations
            # -- every one refused on the P1 entry window -- printed
            # "blocked_fail_closed" with no reason at all (2026-09-03
            # 16:56Z, 16 of 16).  A worker-level failure keeps its own
            # reason from the except arm below; this names the refusals.
            summary_reason = (
                # A fleet-wide code defect is named ahead of the refusal
                # tally, and ahead of "committed something", because it can
                # take most of the fleet while a handful of scopes still
                # commit -- and the board reads ``reason`` and nothing else.
                "fleet_wide_scope_defect:" + next(
                    iter(scope_defects["defect_reasons"])
                )
                if scope_defects["fleet_wide_defect"]
                else None
                if committed_scopes > 0 or not results
                else "all_scopes_refused:" + ",".join(
                    f"{key}x{count}"
                    for key, count in sorted(
                        blocked_scope_reasons.items(),
                        key=lambda item: (-item[1], item[0]),
                    )
                )
                if blocked_scope_reasons
                else "no_scope_committed_or_refused"
            )
            return {
                "schema": SCHEMA,
                "ok": bool(results) and committed_scopes > 0,
                "state": (
                    "blocked_fail_closed"
                    if not results or committed_scopes == 0
                    else "cycle_committed"
                    if blocked_scopes == 0
                    else "cycle_committed_partial"
                ),
                **({"reason": summary_reason} if summary_reason else {}),
                "committed_scope_count": committed_scopes,
                "blocked_scope_count": blocked_scopes,
                "blocked_scope_reasons": blocked_scope_reasons,
                # Which of those refusals were a rule speaking and which
                # were a bug.  The tally above cannot tell them apart by
                # construction; this is the line that can.
                "scope_defect_blockers": scope_defects,
                "refusal_split": split_refusals_by_capability(
                    blocked_scope_reasons
                ),
                "execution_mode": PRODUCTION_EXECUTION_MODE,
                "candidate_count": len(results),
                "candidates": results,
                "copy_follow_checkpoints": list(getattr(self, "_copy_follow_receipts", None) or []),
                "listing_scope_turn": serve_listing,
                "account_equity": account_equity_receipt,
                "intent_reconcile": intent_reconcile,
                "resting_reprice": resting_reprice,
                "intent_retire": intent_retire,
                "live_cycle_settle": live_cycle_settle,
                "quote_evidence_refresh": {
                    # Lease HEADROOM, not a cadence -- the constant's own
                    # comment has to open with "Not a cadence" to fight its
                    # name, and this receipt was printing that name.  A
                    # refresh fires when a day's books have less than this
                    # much lease left, so the number does not bound how
                    # often anything happens; on a 595-second cycle with a
                    # 60-second lease, several renewals a day is the lease
                    # working, not a loop spinning.  Read as an interval it
                    # says the opposite: 2026-09-10, eight committed
                    # refreshes were read off this field as "a 12-second
                    # cadence inside a ten-minute cycle" and proposed for
                    # widening -- which is the change that killed 43 of 44
                    # scopes on production_quote_expired on 2026-09-08.
                    "lease_headroom_seconds": QUOTE_EVIDENCE_REFRESH_SECONDS,
                    # Counted, not inferred.  A refresh loop reports how many
                    # times it fired and for which day, because "zero
                    # failures" reads the same whether it ran twice or never.
                    "attempts": len(quote_refresh_attempts),
                    # And how many of those did what they are for.  The cap
                    # counts only the unproductive ones, so a reader who
                    # sees "attempts: 8" and wants to know whether that is
                    # eight renewals or eight wasted reads had to subtract
                    # two other fields to find out.
                    "productive_attempts": (
                        len(quote_refresh_attempts)
                        - sum(day_unproductive_refreshes.values())
                    ),
                    "attempts_by_day": {
                        day: quote_refresh_attempts.count(day)
                        for day in sorted(set(quote_refresh_attempts))
                    },
                    "ineffective_days": sorted(refresh_ineffective_days),
                    "ineffective_scopes": sorted(
                        f"{item[0]}|{item[1]}" for item in refresh_ineffective_scopes
                    ),
                    # Station writes the attempts made between them: one a
                    # scope that needed one when they restate the reach, a
                    # whole day each before.
                    "restated_station_count": restated_station_count,
                    "within_reach": QUOTE_REFRESH_WITHIN_REACH,
                    # Each wait for the publisher's next generation after a
                    # refresh renewed nothing, and whether the books came.
                    "await_publisher": QUOTE_REFRESH_AWAIT_PUBLISHER,
                    "publisher_wait_budget_seconds": (
                        QUOTE_PUBLISHER_WAIT_BUDGET_SECONDS
                    ),
                    "publisher_wait_seconds": round(
                        sum(item["waited_seconds"] for item in publisher_waits), 1
                    ),
                    "publisher_waits": publisher_waits[:10],
                    # What the cap actually counts since 2026-09-08: an
                    # attempt that renewed nothing.  ``attempts_by_day``
                    # below stays the whole count, so a reader can still see
                    # a healthy day refreshing more than six times.
                    "unproductive_by_day": dict(day_unproductive_refreshes),
                    # What each pass said about itself, so an ineffective day
                    # names its cause instead of only its verdict.
                    "receipts": quote_refresh_receipts[:10],
                    # The bound and how close the day came to it.  A day that
                    # keeps hitting the cap is a loop outrunning its lease,
                    # which is a different fault from a day that cannot renew
                    # -- and the two used to be indistinguishable here.
                    "max_refreshes_per_day": (
                        MAX_QUOTE_EVIDENCE_REFRESHES_PER_DAY
                    ),
                    # Capped means the cap actually stopped the day, so it
                    # reads the number the cap turns on.  Against the whole
                    # attempt count it reported "capped" for a day that had
                    # simply refreshed six productive times and was free to
                    # refresh again -- which is how 2026-09-08 looked capped
                    # while nothing was wrong with it.
                    "capped_days": sorted(
                        day
                        for day, count in day_unproductive_refreshes.items()
                        if count >= MAX_QUOTE_EVIDENCE_REFRESHES_PER_DAY
                    ),
                    "failures": quote_refresh_failures[:10],
                    "failure_count": len(quote_refresh_failures),
                },
                "ws_scope_serving": ws_scope_serving,
                "ws_scope_catalog": self._ws_scope_catalog_summary(
                    ws_scope_catalog
                ),
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
                "market_ingress": market_ingress,
                "resident_registry_ingress": resident_registry_ingress,
                "native_ensemble_ingress": native_ensemble_ingress,
                "native_ensemble_oos_ingress": (
                    native_ensemble_oos_ingress
                ),
                "resident_p0_ingress": resident_p0_ingress,
                "resident_p0m_ingress": resident_p0m_ingress,
                "resident_p1_ingress": resident_p1_ingress,
                "resident_probability_chain": resident_probability_chain,
                "regime_ingress": regime_ingress,
                "live_observation_identity": live_observation_identity,
                "truth_materialization": truth_materialization,
                "maintenance_lane": self._maintenance_lane_report(),
                "delta_v2_truth_ingress": delta_v2_truth_ingress,
                "delta_v2_label_ingress": delta_v2_label_ingress,
                "post_fill_recompute": post_fill_recompute,
                "forward_p0_preselections": forward_p0_preselections,
                "cash_phase_forward_observations": (
                    cash_phase_forward_observations
                ),
                "worker_checked_at": now,
            }
        except Exception as exc:
            reason = f"{type(exc).__name__}:{exc}"
            # Which of SQLite's two "database is locked" faults ended the
            # cycle: a lock starved past busy_timeout (5) or this
            # connection's own stale read snapshot (517), which waiting can
            # never fix.  The board prints ``reason`` and nothing else, and
            # the three cycles lost on 2026-09-26 all read the bare sentence.
            # The stored reason codes keep the plain text.
            lock_kind = sqlite_busy.busy_kind(exc)
            receipt_reason = (
                f"{reason}:{lock_kind[0]}:{lock_kind[1]}"
                if lock_kind is not None else reason
            )
            if (
                delta_v2_truth_ingress is None
                and delta_v2_label_ingress is None
            ):
                if self._maintenance_admits("delta_v2_settlement"):
                    _settlement_started = time.perf_counter()
                    (
                        delta_v2_truth_ingress,
                        delta_v2_label_ingress,
                    ) = self._run_delta_v2_settlement_maintenance(
                        as_of_utc=utc_now(),
                    )
                    self._record_maintenance_served(
                        "delta_v2_settlement",
                        time.perf_counter() - _settlement_started,
                    )
                else:
                    delta_v2_truth_ingress = self._maintenance_deferred(
                        "delta_v2_settlement"
                    )
                    delta_v2_label_ingress = self._maintenance_deferred(
                        "delta_v2_settlement"
                    )
            try:
                cash_phase_forward_observations = (
                    self._flush_cash_phase_forward_observations()
                )
            except Exception as forward_exc:
                cash_phase_forward_observations = {
                    "state": "blocked_fail_closed",
                    "reason": (
                        f"{type(forward_exc).__name__}:{forward_exc}"
                    ),
                    "observation_count": 0,
                    "written": False,
                    "orders_submitted": 0,
                    "calls_order_gateway": False,
                    "live_submit_authorized": False,
                }
            # Future P0/P0-M is already materialized by the preliminary
            # no-live lane.  The ordinary atomic ledger is open-day only, so
            # do not turn a current-scope exception into a false
            # future_event_day_not_allowed blocker.
            scopes = _confine_blocked_scopes(
                self._decision_scopes(
                    as_of_utc=now,
                    include_not_started=False,
                ),
                exc,
            )
            receipts = self._commit_blocked_scopes(
                scopes=scopes,
                reason_codes=self._blocker_reason_codes(reason),
                details={
                    "blocked_scope_decision_version": 1,
                    "exception_type": type(exc).__name__,
                    "exception_reason": str(exc),
                    # Which statement, not just which sentence.
                    "failed_statement": last_failed_statement(),
                    "sqlite_busy_kind": (
                        list(lock_kind) if lock_kind is not None else None
                    ),
                    "no_market_snapshot_written": True,
                    "no_intents_written": True,
                    "no_capital_reserved": True,
                    "no_orders_submitted": True,
                    "execution_mode": PRODUCTION_EXECUTION_MODE,
                },
                created_at_utc=now,
            )
            payload = {
                **_blocked(receipt_reason),
                "failed_statement": last_failed_statement(),
                "worker_checked_at": now,
                "scope_count": len(scopes),
                "durable_blocked_decision_count": sum(
                    1 for item in receipts if item.get("writes_target_ledger") is True
                ),
                "durable_blocked_decisions": self._blocked_receipt_summary(receipts),
            }
            payload["market_ingress"] = market_ingress or {
                "state": "blocked_fail_closed",
                "reason": reason,
                "writes_target_ssot": False,
            }
            payload["resident_registry_ingress"] = (
                resident_registry_ingress
                or {
                    "state": "blocked_fail_closed",
                    "reason": reason,
                    "wrote_rows": 0,
                    "writes_target_database": False,
                    "calls_order_gateway": False,
                    "places_orders": False,
                }
            )
            payload["native_ensemble_ingress"] = (
                native_ensemble_ingress
                or {
                    "state": "blocked_fail_closed",
                    "reason": reason,
                    "writes_target_database": False,
                    "calls_order_gateway": False,
                    "orders_submitted": 0,
                    "live_submit_authorized": False,
                }
            )
            payload["native_ensemble_oos_ingress"] = (
                native_ensemble_oos_ingress
                or {
                    "state": "blocked_fail_closed",
                    "reason": reason,
                    "calls_order_gateway": False,
                    "orders_submitted": 0,
                    "live_submit_authorized": False,
                }
            )
            payload["resident_p0_ingress"] = resident_p0_ingress or {
                "state": "blocked_fail_closed",
                "reason": reason,
                "writes_target_ssot": False,
            }
            payload["resident_p0m_ingress"] = resident_p0m_ingress or {
                "state": "blocked_fail_closed",
                "reason": reason,
                "writes_target_ssot": False,
            }
            payload["resident_p1_ingress"] = resident_p1_ingress or {
                "state": "blocked_fail_closed",
                "reason": reason,
                "writes_target_ssot": False,
            }
            payload["resident_probability_chain"] = resident_probability_chain or {
                "schema": "bayes_basket_target_resident_probability_chain_v1",
                "stage_order": ["P0", "P0-M", "P1"],
                "state": "BLOCKED_FAIL_CLOSED",
                "reason": reason,
                "calls_order_gateway": False,
                "places_orders": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
            payload["regime_ingress"] = regime_ingress or {
                "schema": "bayes_basket_target_regime_batch_v1",
                "state": "BLOCKED_FAIL_CLOSED",
                "reason": reason,
                "receipts": [],
                "blockers": [],
                "calls_order_gateway": False,
                "orders_submitted": 0,
            }
            payload["delta_v2_label_ingress"] = (
                delta_v2_label_ingress
                or {
                    "state": "blocked_fail_closed",
                    "reason": reason,
                    "appended_count": 0,
                }
            )
            payload["delta_v2_truth_ingress"] = (
                delta_v2_truth_ingress
                or {
                    "state": "blocked_fail_closed",
                    "reason": reason,
                    "written_count": 0,
                }
            )
            payload["post_fill_recompute"] = post_fill_recompute or {
                "schema": "bayes_basket_target_post_fill_recompute_batch_v1",
                "state": "blocked_fail_closed",
                "reason": reason,
                "request_count": 0,
                "applied_count": 0,
                "places_orders": False,
                "calls_order_gateway": False,
                "live_submit_authorized": False,
                "orders_submitted": 0,
            }
            payload["forward_p0_preselections"] = (
                forward_p0_preselections
            )
            payload["cash_phase_forward_observations"] = (
                cash_phase_forward_observations
            )
            return payload

    def close(self) -> None:
        pool = getattr(self, "_official_native_capture_pool", None)
        if pool is not None:
            # Let in-flight captures finish: each is already hard-bounded by
            # its own subprocess deadline, and a half-written staging file
            # would otherwise be merged on the next start.
            pool.shutdown(wait=True, cancel_futures=True)
            self._official_native_capture_pool = None
        follow_pool = getattr(self, "_official_native_follow_pool", None)
        if follow_pool is not None:
            # Charter 192: queued follow captures are dropped, not waited on.
            # The next pass queues them again, and a running one writes its
            # archive atomically and ingests in one transaction.
            follow_pool.shutdown(wait=False, cancel_futures=True)
            self._official_native_follow_pool = None
        if self.conn is not None:
            self.conn.close()
            self.conn = None
        if self.canonical_source_conn is not None:
            self.canonical_source_conn.close()
            self.canonical_source_conn = None
        if self.commit_conn is not None:
            self.commit_conn.close()
            self.commit_conn = None


__all__ = [
    "DEFAULT_TARGET_ACTIVATION",
    "DEFAULT_TARGET_DB",
    "DEFAULT_TARGET_MARKET_MANIFEST",
    "MAX_PREPARED_CYCLES_PER_SCOPE",
    "PRODUCTION_EXECUTION_MODE",
    "SCHEMA",
    "TargetProductionWorker",
    "open_target_read_only",
    "open_target_writer_if_enabled",
    "utc_now",
]
